namespace CamboBIM.Revit2024.Addin
{
    internal class CadToModelExternalEventHandler : IExternalEventHandler
    {
        private CamboBIMWindow _window;
        private readonly List<ElementId> _previewElementIds = new List<ElementId>();
        public CadToModelRequest Request { get; } = new CadToModelRequest();
        private const string SiteProgressLegacyParamName = "%Site_Progress";
        private const string SiteProgressVolumeParamName = "%Site_Progress_Volume";
        private static readonly BuiltInCategory[] SiteProgressSummaryCategories =
        {
            BuiltInCategory.OST_StructuralFoundation,
            BuiltInCategory.OST_StructuralColumns,
            BuiltInCategory.OST_Walls,
            BuiltInCategory.OST_StructuralFraming,
            BuiltInCategory.OST_Floors,
            BuiltInCategory.OST_Stairs
        };

        private enum SiteProgressColorBand
        {
            NotStarted,
            Range0To25,
            Range25To50,
            Range50To75,
            Range75To99,
            Completed
        }

        public void SetWindow(CamboBIMWindow window)
        {
            _window = window;
        }

        public string GetName() => "CamboBIM CadToModel Handler";

        public void Execute(UIApplication app)
        {
            if (_window == null) return;

            UIDocument uidoc = app.ActiveUIDocument;
            if (uidoc == null) return;

            Document doc = uidoc.Document;

            try
            {
                if (ShouldClearPreview(Request.RequestType))
                {
                    ClearPreviewLines(doc);
                }

                switch (Request.RequestType)
                {
                    case CadToModelRequestType.Initialize:
                        InitializeUi(doc);
                        break;
                    case CadToModelRequestType.PickLink:
                        PickLink(uidoc, doc);
                        break;
                    case CadToModelRequestType.PickObjects:
                        PickObjects(uidoc, doc);
                        break;
                    case CadToModelRequestType.EditFoundationSlabType:
                        EditFoundationSlabType(app, uidoc, doc);
                        break;
                    case CadToModelRequestType.EditSelectedTypeProperties:
                        EditSelectedTypeProperties(app, uidoc, doc);
                        break;
                    case CadToModelRequestType.RefreshFoundationSlabTypes:
                        RefreshFoundationSlabTypes(doc);
                        break;
                    case CadToModelRequestType.PickColumnSideline:
                        PickColumnSideline(uidoc, doc);
                        break;
                    case CadToModelRequestType.PickColumnLabel:
                        PickColumnLabel(uidoc, doc);
                        break;
                    case CadToModelRequestType.AutoDetectColumns:
                        AutoDetectColumns(doc);
                        break;
                    case CadToModelRequestType.ClickIdentifyColumns:
                        ClickIdentifyColumns(uidoc, doc);
                        break;
                    case CadToModelRequestType.DragIdentifyColumns:
                        DragIdentifyColumns(uidoc, doc);
                        break;
                    case CadToModelRequestType.PickColumnSchedule:
                        PickColumnSchedule(uidoc, doc);
                        break;
                    case CadToModelRequestType.AutoDetectWalls:
                        AutoDetectWalls(doc);
                        break;
                    case CadToModelRequestType.PickWallSchedule:
                        PickWallSchedule(uidoc, doc);
                        break;
                    case CadToModelRequestType.AutoDetectBeams:
                        AutoDetectBeams(doc);
                        break;
                    case CadToModelRequestType.PickBeamSchedule:
                        PickBeamSchedule(uidoc, doc);
                        break;
                    case CadToModelRequestType.ApplyTasAttributesToSelection:
                        ApplyTasAttributesToSelection(uidoc, doc);
                        break;
                    case CadToModelRequestType.GenerateGridlines:
                        GenerateGridlines(doc);
                        break;
                    case CadToModelRequestType.GenerateFoundations:
                        GenerateFoundations(doc);
                        break;
                    case CadToModelRequestType.GenerateLeanConcrete:
                        GenerateLeanConcrete(doc);
                        break;
                    case CadToModelRequestType.GenerateSoilExcavation:
                        GenerateSoilExcavation(doc);
                        break;
                    case CadToModelRequestType.GenerateSlabs:
                        GenerateSlabs(doc);
                        break;
                    case CadToModelRequestType.GenerateColumns:
                        GenerateColumns(doc);
                        break;
                    case CadToModelRequestType.GenerateWalls:
                        GenerateWalls(doc);
                        break;
                    case CadToModelRequestType.GenerateBeams:
                        GenerateBeams(doc);
                        break;
                    case CadToModelRequestType.GeneratePiles:
                        GeneratePiles(doc);
                        break;
                    case CadToModelRequestType.GenerateDetailLines:
                        GenerateDetailLines(doc);
                        break;
                    case CadToModelRequestType.PickColumnRebarHost:
                        PickColumnRebarHost(uidoc, doc);
                        break;
                    case CadToModelRequestType.GenerateColumnRebar:
                        GenerateColumnRebar(doc);
                        break;
                    case CadToModelRequestType.PickFoundationRebarHost:
                        PickFoundationRebarHost(uidoc, doc);
                        break;
                    case CadToModelRequestType.GenerateFoundationRebar:
                        GenerateFoundationRebar(doc);
                        break;
                    case CadToModelRequestType.PickWallRebarHosts:
                        PickWallRebarHosts(uidoc, doc);
                        break;
                    case CadToModelRequestType.GenerateWallRebar:
                        GenerateWallRebar(doc);
                        break;
                    case CadToModelRequestType.PickBeamRebarHosts:
                        PickBeamRebarHosts(uidoc, doc);
                        break;
                    case CadToModelRequestType.PickBeamRebarSecondaryHosts:
                        PickBeamRebarSecondaryHosts(uidoc, doc);
                        break;
                    case CadToModelRequestType.PickBeamRebarSupportHosts:
                        PickBeamRebarSupportHosts(uidoc, doc);
                        break;
                    case CadToModelRequestType.GenerateBeamRebar:
                        GenerateBeamRebar(doc);
                        break;
                    case CadToModelRequestType.GenerateFormworkShopDrawings:
                        GenerateShopDrawings(uidoc, doc, includeFormwork: true, includeRebar: false, createSheets: Request.ShopDrawingsCreateSheets);
                        break;
                    case CadToModelRequestType.GenerateRebarShopDrawings:
                        GenerateShopDrawings(uidoc, doc, includeFormwork: false, includeRebar: true, createSheets: Request.ShopDrawingsCreateSheets);
                        break;
                    case CadToModelRequestType.GenerateConstructionShopSheets:
                        GenerateShopDrawings(uidoc, doc, includeFormwork: Request.ShopDrawingsIncludeFormwork, includeRebar: Request.ShopDrawingsIncludeRebar, createSheets: Request.ShopDrawingsCreateSheets);
                        break;
                    case CadToModelRequestType.GenerateSelectedElementShopViews:
                        GenerateSelectedElementShopViews(uidoc, doc, createSheets: Request.ShopDrawingsCreateSheets);
                        break;
                    case CadToModelRequestType.CalculateQs:
                        CBIM_QS.Calculate(app, uidoc, doc, Request, _window);
                        break;
                    case CadToModelRequestType.ExportQsCsv:
                        CBIM_QS.ExportCsv(uidoc, doc, Request, _window);
                        break;
                    case CadToModelRequestType.RefreshBoqTable:
                        CBIM_BOQ.BuildTable(uidoc, doc, Request, _window);
                        break;
                    case CadToModelRequestType.ViewQsExpression:
                        CBIM_QS.ViewExpression(uidoc, doc, _window);
                        break;
                    case CadToModelRequestType.HideQsFormworkShapes:
                        CBIM_QS.ToggleFormworkShapesInActiveView(uidoc, doc, _window);
                        break;
                    case CadToModelRequestType.DeleteQsFormworkShapes:
                        CBIM_QS.DeleteFormworkShapes(doc, _window);
                        break;
                    case CadToModelRequestType.RefreshLinksheetSchedules:
                        RefreshLinksheetSchedules(doc);
                        break;
                    case CadToModelRequestType.RefreshLinksheetParameters:
                        RefreshLinksheetParameters(doc);
                        break;
                    case CadToModelRequestType.BuildLinksheetPreview:
                        BuildLinksheetPreview(uidoc, doc);
                        break;
                    case CadToModelRequestType.ApplyLinksheetPreviewEdits:
                        ApplyLinksheetPreviewEdits(uidoc, doc);
                        break;
                    case CadToModelRequestType.ApplySiteProgress:
                        CBIM_SITE_PROGRESS.ApplyFromSelection(app, uidoc, doc, Request, _window);
                        if (doc.ActiveView is View3D)
                        {
                            ApplySiteProgressColorView(uidoc, doc);
                        }
                        break;
                    case CadToModelRequestType.ApplySiteProgressFromImport:
                        CBIM_SITE_PROGRESS.ApplyFromImportRows(app, uidoc, doc, Request, _window);
                        if (doc.ActiveView is View3D)
                        {
                            ApplySiteProgressColorView(uidoc, doc);
                        }
                        break;
                    case CadToModelRequestType.RefreshSiteProgressSummary:
                        CBIM_SITE_PROGRESS.RefreshSummary(app, uidoc, doc, Request, _window);
                        if (Request.SiteProgressFocusFilteredView)
                        {
                            FocusSiteProgressByCurrentFilter(uidoc, doc);
                        }
                        break;
                    case CadToModelRequestType.SelectSiteProgressElements:
                        SelectSiteProgressElements(uidoc, doc);
                        break;
                    case CadToModelRequestType.ColorizeSiteProgressView:
                        ApplySiteProgressColorView(uidoc, doc);
                        break;
                    case CadToModelRequestType.ClearSiteProgressColorView:
                        ClearSiteProgressColorView(doc);
                        break;
                    case CadToModelRequestType.SyncBoreyFloorData:
                        CBIM_BOREY.SyncFloorData(app, uidoc, doc, Request, _window);
                        break;
                    case CadToModelRequestType.SelectBoreyElements:
                        CBIM_BOREY.SelectBoreyElements(uidoc, doc, Request, _window);
                        break;
                    case CadToModelRequestType.ImportAdaptTendonProfiles:
                        ImportAdaptTendonProfiles(doc);
                        break;
                    case CadToModelRequestType.ImportAdaptCadDrawing:
                        ImportAdaptCadDrawing(doc);
                        break;
                    case CadToModelRequestType.AutoJoinJoin:
                        RunAutoJoin(doc, AutoJoinAction.Join);
                        break;
                    case CadToModelRequestType.AutoJoinSwitch:
                        RunAutoJoin(doc, AutoJoinAction.Switch);
                        break;
                    case CadToModelRequestType.AutoJoinUnjoin:
                        RunAutoJoin(doc, AutoJoinAction.Unjoin);
                        break;
                }
            }
            catch (Autodesk.Revit.Exceptions.OperationCanceledException)
            {
                _window?.ShowStatus("Cancelled.");
            }
            catch (System.OperationCanceledException)
            {
                _window?.ShowStatus("Cancelled.");
            }
            catch (Exception ex)
            {
                TaskDialog.Show("CamboBIM", $"Error: {ex}");
            }
            finally
            {
                if (Request.RequestType == CadToModelRequestType.PickLink ||
                    Request.RequestType == CadToModelRequestType.PickColumnSchedule ||
                    Request.RequestType == CadToModelRequestType.PickWallSchedule ||
                    Request.RequestType == CadToModelRequestType.PickBeamSchedule ||
                    Request.RequestType == CadToModelRequestType.PickColumnSideline ||
                    Request.RequestType == CadToModelRequestType.PickColumnLabel ||
                    Request.RequestType == CadToModelRequestType.ClickIdentifyColumns ||
                    Request.RequestType == CadToModelRequestType.DragIdentifyColumns)
                {
                    _window?.RestoreAfterColumnScheduleCadScan();
                }

                Request.SiteProgressFocusFilteredView = false;
                Request.BoreyEnsureSharedParameters = false;
                Request.BoreyApplyGridChanges = false;
                Request.BoreyLogicalTableName = "";
                Request.BoreyRows = new List<BoreyGridRowPayload>();
                Request.SiteProgressImportRows = new List<SiteProgressImportRowPayload>();
                Request.AdaptTendonSourcePath = "";
                Request.AdaptTendonProfileSegments = new List<AdaptTendonProfileSegmentPayload>();
                Request.LinksheetEditedCells = new List<LinksheetCellEdit>();
                Request.EditSelectedTypeId = ElementId.InvalidElementId;
                Request.EditSelectedTypeCandidateCategories = new List<BuiltInCategory>();
                Request.EditSelectedTypeDisplayName = "";
                Request.RequestType = CadToModelRequestType.None;
            }
        }

        private void InitializeUi(Document doc)
        {
            var columnTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Category != null &&
                             fs.Category.Id.Value == (int)BuiltInCategory.OST_StructuralColumns)
                .OrderBy(fs => fs.FamilyName)
                .ThenBy(fs => fs.Name)
                .Select(fs => new CamboBIMWindow.ComboItem(fs.Id, $"{fs.FamilyName} : {fs.Name}"))
                .ToList();

            var levels = new FilteredElementCollector(doc)
                .OfClass(typeof(Level))
                .Cast<Level>()
                .OrderBy(l => l.Elevation)
                .Select(l => new CamboBIMWindow.ComboItem(l.Id, l.Name))
                .ToList();

            var foundationTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Category != null &&
                             fs.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFoundation)
                .OrderBy(fs => fs.FamilyName)
                .ThenBy(fs => fs.Name)
                .Select(fs => new CamboBIMWindow.ComboItem(fs.Id, $"{fs.FamilyName} : {fs.Name}"))
                .ToList();

            var slabTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FloorType))
                .Cast<FloorType>()
                .Where(ft => ft.Category != null &&
                             (ft.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFoundation ||
                              ft.Category.Id.Value == (int)BuiltInCategory.OST_Floors))
                .OrderBy(ft => ft.FamilyName)
                .ThenBy(ft => ft.Name)
                .Select(ft => new CamboBIMWindow.ComboItem(ft.Id, $"{ft.FamilyName} : {ft.Name}"))
                .ToList();

            var wallTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(WallType))
                .Cast<WallType>()
                .OrderBy(wt => wt.FamilyName)
                .ThenBy(wt => wt.Name)
                .Select(wt => new CamboBIMWindow.ComboItem(wt.Id, $"{wt.FamilyName} : {wt.Name}"))
                .ToList();

            var beamTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Category != null &&
                             fs.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFraming)
                .OrderBy(fs => fs.FamilyName)
                .ThenBy(fs => fs.Name)
                .Select(fs => new CamboBIMWindow.ComboItem(fs.Id, $"{fs.FamilyName} : {fs.Name}"))
                .ToList();

            var lineStyles = new List<CamboBIMWindow.ComboItem>();
            try
            {
                Category lineCat = doc.Settings.Categories.get_Item(BuiltInCategory.OST_Lines);
                if (lineCat != null)
                {
                    foreach (Category sub in lineCat.SubCategories)
                    {
                        if (sub == null) continue;
                        GraphicsStyle gs = sub.GetGraphicsStyle(GraphicsStyleType.Projection);
                        if (gs == null) continue;
                        lineStyles.Add(new CamboBIMWindow.ComboItem(gs.Id, sub.Name));
                    }
                }
            }
            catch
            {
                // ignore line style lookup failures
            }

            lineStyles = lineStyles.OrderBy(ls => ls.Name).ToList();

            var titleBlockTypes = new FilteredElementCollector(doc)
                .OfCategory(BuiltInCategory.OST_TitleBlocks)
                .WhereElementIsElementType()
                .Cast<Element>()
                .OrderBy(e => e.Name)
                .Select(e => new CamboBIMWindow.ComboItem(e.Id, e.Name))
                .ToList();

            var rebarBarTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(RebarBarType))
                .Cast<RebarBarType>()
                .OrderBy(bt => bt.Name)
                .Select(bt => new CamboBIMWindow.ComboItem(bt.Id, bt.Name))
                .ToList();

            var rebarTieShapes = new FilteredElementCollector(doc)
                .OfClass(typeof(RebarShape))
                .Cast<RebarShape>()
                .OrderBy(rs => rs.Name)
                .Select(rs =>
                {
                    string style = "";
                    try
                    {
                        style = rs.RebarStyle.ToString();
                    }
                    catch
                    {
                        style = "";
                    }

                    string label = string.IsNullOrWhiteSpace(style)
                        ? $"{rs.Id.Value} - {rs.Name}"
                        : $"{rs.Id.Value} - {rs.Name} [{style}]";
                    return new CamboBIMWindow.ComboItem(rs.Id, label);
                })
                .ToList();

            _window?.UpdateColumnTypes(columnTypes);
            _window?.UpdateLevels(levels);
            _window?.UpdateFoundationTypes(foundationTypes);
            _window?.UpdateFoundationSlabTypes(slabTypes);
            _window?.UpdateWallTypes(wallTypes);
            _window?.UpdateBeamTypes(beamTypes);
            _window?.UpdateSlabTypes(slabTypes);
            _window?.UpdateLineStyles(lineStyles);
            _window?.UpdateShopDrawingTitleBlocks(titleBlockTypes);
            _window?.UpdateColumnRebarBarTypes(rebarBarTypes);
            _window?.UpdateColumnRebarTieShapes(rebarTieShapes);
            RefreshLinksheetSchedules(doc);
        }

        private void RefreshFoundationSlabTypes(Document doc)
        {
            var slabTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FloorType))
                .Cast<FloorType>()
                .Where(ft => ft.Category != null &&
                             (ft.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFoundation ||
                              ft.Category.Id.Value == (int)BuiltInCategory.OST_Floors))
                .OrderBy(ft => ft.FamilyName)
                .ThenBy(ft => ft.Name)
                .Select(ft => new CamboBIMWindow.ComboItem(ft.Id, $"{ft.FamilyName} : {ft.Name}"))
                .ToList();

            _window?.UpdateFoundationSlabTypes(slabTypes);
        }

        private void RefreshLinksheetSchedules(Document doc)
        {
            List<LinksheetScheduleInfo> schedules = CollectLinksheetSchedules(doc)
                .Select(s => new LinksheetScheduleInfo
                {
                    Name = s.Name,
                    // Keep schedule refresh fast: avoid per-schedule row counting which forces
                    // expensive schedule table evaluation in large projects.
                    ElementCount = -1
                })
                .ToList();

            _window?.UpdateLinksheetSchedules(schedules);
        }

        private void RefreshLinksheetParameters(Document doc)
        {
            List<ViewSchedule> selectedSchedules = GetSelectedLinksheetSchedules(doc);
            if (selectedSchedules.Count == 0)
            {
                _window?.UpdateLinksheetParameters(new List<LinksheetParameterInfo>());
                return;
            }

            var parameterMap = new Dictionary<string, LinksheetParameterInfo>(StringComparer.OrdinalIgnoreCase);
            foreach (ViewSchedule schedule in selectedSchedules)
            {
                Element sample = new FilteredElementCollector(doc, schedule.Id)
                    .WhereElementIsNotElementType()
                    .FirstElement();

                foreach (ScheduleField field in GetLinksheetFields(schedule))
                {
                    string fieldName = GetLinksheetFieldDisplayName(field);
                    if (string.IsNullOrWhiteSpace(fieldName))
                    {
                        continue;
                    }

                    string key = NormalizeLinksheetParameterKey(fieldName);
                    if (parameterMap.ContainsKey(key))
                    {
                        continue;
                    }

                    parameterMap[key] = new LinksheetParameterInfo
                    {
                        Key = key,
                        Name = fieldName,
                        Kind = ResolveLinksheetParameterKind(doc, sample, field)
                    };
                }
            }

            List<LinksheetParameterInfo> parameters = parameterMap.Values
                .OrderBy(p => p.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();

            _window?.UpdateLinksheetParameters(parameters);
        }

        private void BuildLinksheetPreview(UIDocument uidoc, Document doc)
        {
            List<ViewSchedule> selectedSchedules = GetSelectedLinksheetSchedules(doc);
            if (selectedSchedules.Count == 0)
            {
                _window?.UpdateLinksheetPreview(
                    new List<LinksheetSchedulePreview>(),
                    "LINKSHEET: select at least one schedule first.");
                return;
            }

            HashSet<long> scopeIds = GetLinksheetScopeElementIds(uidoc, doc, Request.LinksheetScope);
            var selectedParameterKeys = new HashSet<string>(
                (Request.LinksheetSelectedParameterKeys ?? new List<string>())
                    .Select(NormalizeLinksheetParameterKey)
                    .Where(k => !string.IsNullOrWhiteSpace(k)),
                StringComparer.OrdinalIgnoreCase);
            bool includeAllParameters = selectedParameterKeys.Count == 0;

            var previews = new List<LinksheetSchedulePreview>();
            int totalRows = 0;

            foreach (ViewSchedule schedule in selectedSchedules)
            {
                List<ScheduleField> allFields = GetLinksheetFields(schedule);
                List<ScheduleField> selectedFields = includeAllParameters
                    ? allFields
                    : allFields
                        .Where(f => selectedParameterKeys.Contains(NormalizeLinksheetParameterKey(GetLinksheetFieldDisplayName(f))))
                        .ToList();

                var preview = new LinksheetSchedulePreview
                {
                    ScheduleName = schedule.Name
                };

                preview.ColumnKeys.Add(LinksheetFieldKeys.Guid);
                preview.ColumnHeaders[LinksheetFieldKeys.Guid] = "GUID";
                preview.ColumnKeys.Add(LinksheetFieldKeys.ElementId);
                preview.ColumnHeaders[LinksheetFieldKeys.ElementId] = "Element ID";

                var addedColumnKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                {
                    LinksheetFieldKeys.Guid,
                    LinksheetFieldKeys.ElementId
                };

                foreach (ScheduleField field in selectedFields)
                {
                    string fieldName = GetLinksheetFieldDisplayName(field);
                    if (string.IsNullOrWhiteSpace(fieldName))
                    {
                        continue;
                    }

                    string key = NormalizeLinksheetParameterKey(fieldName);
                    if (string.Equals(key, "guid", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(key, "element id", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                    if (!addedColumnKeys.Add(key))
                    {
                        continue;
                    }

                    preview.ColumnKeys.Add(key);
                    preview.ColumnHeaders[key] = fieldName;
                }

                IEnumerable<Element> elements = new FilteredElementCollector(doc, schedule.Id)
                    .WhereElementIsNotElementType()
                    .ToElements()
                    .Cast<Element>();

                foreach (Element element in elements)
                {
                    if (element == null || element.Id == ElementId.InvalidElementId)
                    {
                        continue;
                    }
                    if (scopeIds != null && !scopeIds.Contains(element.Id.Value))
                    {
                        continue;
                    }

                    var row = new LinksheetPreviewRow
                    {
                        ElementId = element.Id.Value,
                        UniqueId = element.UniqueId ?? ""
                    };

                    foreach (ScheduleField field in selectedFields)
                    {
                        string fieldName = GetLinksheetFieldDisplayName(field);
                        if (string.IsNullOrWhiteSpace(fieldName))
                        {
                            continue;
                        }

                        string key = NormalizeLinksheetParameterKey(fieldName);
                        if (string.Equals(key, "guid", StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(key, "element id", StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }
                        if (!addedColumnKeys.Contains(key))
                        {
                            continue;
                        }

                        row.Values[key] = GetLinksheetFieldValue(doc, element, field);
                    }

                    preview.Rows.Add(row);
                }

                totalRows += preview.Rows.Count;
                previews.Add(preview);
            }

            string message = "LINKSHEET preview: " + previews.Count.ToString(CultureInfo.InvariantCulture) +
                             " schedule(s), " + totalRows.ToString(CultureInfo.InvariantCulture) + " row(s).";
            _window?.UpdateLinksheetPreview(previews, message);
        }

        private void ApplyLinksheetPreviewEdits(UIDocument uidoc, Document doc)
        {
            List<LinksheetCellEdit> edits = (Request.LinksheetEditedCells ?? new List<LinksheetCellEdit>())
                .Where(edit =>
                    edit != null &&
                    !string.IsNullOrWhiteSpace(edit.ParameterKey) &&
                    !string.Equals(edit.ParameterKey, LinksheetFieldKeys.Guid, StringComparison.OrdinalIgnoreCase) &&
                    !string.Equals(edit.ParameterKey, LinksheetFieldKeys.ElementId, StringComparison.OrdinalIgnoreCase) &&
                    (edit.ElementId > 0 || !string.IsNullOrWhiteSpace(edit.UniqueId)))
                .ToList();

            if (edits.Count == 0)
            {
                _window?.ShowStatus("LINKSHEET: no valid edited values to apply.");
                return;
            }

            HashSet<long> scopeIds = GetLinksheetScopeElementIds(uidoc, doc, Request.LinksheetScope);
            Dictionary<string, Dictionary<string, ScheduleField>> scheduleFieldMap = BuildLinksheetScheduleFieldMap(doc);

            int applied = 0;
            int skippedReadOnly = 0;
            int missingElements = 0;
            int missingParameters = 0;
            int outOfScope = 0;
            int parseFailed = 0;

            using (Transaction transaction = new Transaction(doc, "CamboBIM - LINKSHEET Update Model"))
            {
                transaction.Start();

                foreach (LinksheetCellEdit edit in edits)
                {
                    if (edit.Kind == LinksheetParameterKind.ReadOnly)
                    {
                        skippedReadOnly++;
                        continue;
                    }

                    Element element = ResolveLinksheetElement(doc, edit);
                    if (element == null)
                    {
                        missingElements++;
                        continue;
                    }

                    if (scopeIds != null && !scopeIds.Contains(element.Id.Value))
                    {
                        outOfScope++;
                        continue;
                    }

                    Parameter parameter = ResolveLinksheetParameterForEdit(doc, element, edit, scheduleFieldMap);
                    if (parameter == null)
                    {
                        missingParameters++;
                        continue;
                    }
                    if (parameter.IsReadOnly)
                    {
                        skippedReadOnly++;
                        continue;
                    }

                    if (!TrySetLinksheetParameterFromText(parameter, edit.Value, out bool changed))
                    {
                        parseFailed++;
                        continue;
                    }

                    if (changed)
                    {
                        applied++;
                    }
                }

                if (applied > 0)
                {
                    transaction.Commit();
                }
                else
                {
                    transaction.RollBack();
                }
            }

            if (applied > 0)
            {
                BuildLinksheetPreview(uidoc, doc);
            }

            string message = "LINKSHEET update: " +
                             applied.ToString(CultureInfo.InvariantCulture) + " applied";
            if (skippedReadOnly > 0)
            {
                message += ", " + skippedReadOnly.ToString(CultureInfo.InvariantCulture) + " read-only";
            }
            if (missingElements > 0)
            {
                message += ", " + missingElements.ToString(CultureInfo.InvariantCulture) + " missing elements";
            }
            if (missingParameters > 0)
            {
                message += ", " + missingParameters.ToString(CultureInfo.InvariantCulture) + " missing parameters";
            }
            if (outOfScope > 0)
            {
                message += ", " + outOfScope.ToString(CultureInfo.InvariantCulture) + " out of scope";
            }
            if (parseFailed > 0)
            {
                message += ", " + parseFailed.ToString(CultureInfo.InvariantCulture) + " parse failed";
            }
            message += ".";
            _window?.ShowStatus(message);
        }

        private Dictionary<string, Dictionary<string, ScheduleField>> BuildLinksheetScheduleFieldMap(Document doc)
        {
            var result = new Dictionary<string, Dictionary<string, ScheduleField>>(StringComparer.OrdinalIgnoreCase);
            foreach (ViewSchedule schedule in GetSelectedLinksheetSchedules(doc))
            {
                if (schedule == null || string.IsNullOrWhiteSpace(schedule.Name))
                {
                    continue;
                }

                var fieldMap = new Dictionary<string, ScheduleField>(StringComparer.OrdinalIgnoreCase);
                foreach (ScheduleField field in GetLinksheetFields(schedule))
                {
                    string fieldName = GetLinksheetFieldDisplayName(field);
                    string key = NormalizeLinksheetParameterKey(fieldName);
                    if (string.IsNullOrWhiteSpace(key) || fieldMap.ContainsKey(key))
                    {
                        continue;
                    }

                    fieldMap[key] = field;
                }

                result[schedule.Name] = fieldMap;
            }

            return result;
        }

        private static Element ResolveLinksheetElement(Document doc, LinksheetCellEdit edit)
        {
            if (doc == null || edit == null)
            {
                return null;
            }

            Element element = null;
            if (edit.ElementId > 0 && edit.ElementId <= int.MaxValue)
            {
                try
                {
                    element = doc.GetElement(new ElementId(Convert.ToInt64(edit.ElementId, CultureInfo.InvariantCulture)));
                }
                catch
                {
                    element = null;
                }
            }

            if (element == null && !string.IsNullOrWhiteSpace(edit.UniqueId))
            {
                try
                {
                    element = doc.GetElement(edit.UniqueId);
                }
                catch
                {
                    element = null;
                }
            }

            return element;
        }

        private Parameter ResolveLinksheetParameterForEdit(
            Document doc,
            Element element,
            LinksheetCellEdit edit,
            Dictionary<string, Dictionary<string, ScheduleField>> scheduleFieldMap)
        {
            if (doc == null || element == null || edit == null)
            {
                return null;
            }

            string key = NormalizeLinksheetParameterKey(edit.ParameterKey);
            if (string.IsNullOrWhiteSpace(key))
            {
                return null;
            }

            ScheduleField scheduleField = null;
            if (!string.IsNullOrWhiteSpace(edit.ScheduleName) &&
                scheduleFieldMap != null &&
                scheduleFieldMap.TryGetValue(edit.ScheduleName, out Dictionary<string, ScheduleField> perScheduleMap) &&
                perScheduleMap != null)
            {
                perScheduleMap.TryGetValue(key, out scheduleField);
            }

            if (scheduleField == null && scheduleFieldMap != null)
            {
                foreach (Dictionary<string, ScheduleField> map in scheduleFieldMap.Values)
                {
                    if (map != null && map.TryGetValue(key, out scheduleField))
                    {
                        break;
                    }
                }
            }

            Element typeElement = null;
            try
            {
                ElementId typeId = element.GetTypeId();
                if (typeId != null && typeId != ElementId.InvalidElementId)
                {
                    typeElement = doc.GetElement(typeId);
                }
            }
            catch
            {
                typeElement = null;
            }

            Parameter instanceFromField = scheduleField != null ? TryGetLinksheetParameter(element, scheduleField, true) : null;
            Parameter typeFromField = scheduleField != null ? TryGetLinksheetParameter(typeElement, scheduleField, true) : null;
            Parameter instanceByName = FindLinksheetParameterByNormalizedKey(element, key);
            Parameter typeByName = FindLinksheetParameterByNormalizedKey(typeElement, key);

            switch (edit.Kind)
            {
                case LinksheetParameterKind.Instance:
                    return FirstWritableParameter(instanceFromField, instanceByName, typeFromField, typeByName);
                case LinksheetParameterKind.Type:
                    return FirstWritableParameter(typeFromField, typeByName, instanceFromField, instanceByName);
                default:
                    return FirstWritableParameter(instanceFromField, typeFromField, instanceByName, typeByName);
            }
        }

        private static Parameter FirstWritableParameter(params Parameter[] candidates)
        {
            if (candidates == null || candidates.Length == 0)
            {
                return null;
            }

            foreach (Parameter candidate in candidates)
            {
                if (candidate != null && !candidate.IsReadOnly)
                {
                    return candidate;
                }
            }

            return candidates.FirstOrDefault(p => p != null);
        }

        private static Parameter FindLinksheetParameterByNormalizedKey(Element element, string normalizedKey)
        {
            if (element == null || string.IsNullOrWhiteSpace(normalizedKey))
            {
                return null;
            }

            try
            {
                foreach (Parameter parameter in element.Parameters)
                {
                    if (parameter?.Definition == null)
                    {
                        continue;
                    }

                    string nameKey = NormalizeLinksheetParameterKey(parameter.Definition.Name);
                    if (string.Equals(nameKey, normalizedKey, StringComparison.OrdinalIgnoreCase))
                    {
                        return parameter;
                    }
                }
            }
            catch
            {
                return null;
            }

            return null;
        }

        private static bool TrySetLinksheetParameterFromText(
            Parameter parameter,
            string rawValue,
            out bool changed)
        {
            changed = false;
            if (parameter == null || parameter.IsReadOnly)
            {
                return false;
            }

            string value = rawValue ?? "";
            switch (parameter.StorageType)
            {
                case StorageType.String:
                {
                    string oldValue = parameter.AsString() ?? "";
                    if (string.Equals(oldValue, value, StringComparison.Ordinal))
                    {
                        return true;
                    }

                    changed = parameter.Set(value);
                    return true;
                }
                case StorageType.Integer:
                {
                    if (!TryParseLinksheetInteger(value, out int intValue))
                    {
                        try
                        {
                            if (parameter.SetValueString(value))
                            {
                                changed = true;
                                return true;
                            }
                        }
                        catch
                        {
                            // ignore SetValueString failures
                        }

                        return false;
                    }

                    int oldValue = parameter.AsInteger();
                    if (oldValue == intValue)
                    {
                        return true;
                    }

                    changed = parameter.Set(intValue);
                    return true;
                }
                case StorageType.Double:
                {
                    double oldValue = parameter.AsDouble();
                    if (string.IsNullOrWhiteSpace(value))
                    {
                        if (Math.Abs(oldValue) < 1e-9)
                        {
                            return true;
                        }

                        changed = parameter.Set(0.0);
                        return true;
                    }

                    try
                    {
                        if (parameter.SetValueString(value))
                        {
                            changed = Math.Abs(parameter.AsDouble() - oldValue) >= 1e-9;
                            return true;
                        }
                    }
                    catch
                    {
                        // ignore SetValueString failures
                    }

                    if (TryParseLinksheetDouble(value, out double doubleValue))
                    {
                        if (Math.Abs(oldValue - doubleValue) < 1e-9)
                        {
                            return true;
                        }

                        changed = parameter.Set(doubleValue);
                        return true;
                    }

                    return false;
                }
                case StorageType.ElementId:
                {
                    if (!TryResolveLinksheetElementIdValue(value, out ElementId targetId))
                    {
                        return false;
                    }

                    ElementId oldId = parameter.AsElementId() ?? ElementId.InvalidElementId;
                    if (oldId.Value == targetId.Value)
                    {
                        return true;
                    }

                    changed = parameter.Set(targetId);
                    return true;
                }
                default:
                {
                    if (string.IsNullOrWhiteSpace(value))
                    {
                        return true;
                    }

                    try
                    {
                        changed = parameter.SetValueString(value);
                        return changed;
                    }
                    catch
                    {
                        return false;
                    }
                }
            }
        }

        private static bool TryParseLinksheetInteger(string rawValue, out int value)
        {
            value = 0;
            string text = (rawValue ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return true;
            }

            if (int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsedInt) ||
                int.TryParse(text, NumberStyles.Integer, CultureInfo.CurrentCulture, out parsedInt))
            {
                value = parsedInt;
                return true;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out double parsedDouble) ||
                double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out parsedDouble))
            {
                value = Convert.ToInt32(Math.Round(parsedDouble), CultureInfo.InvariantCulture);
                return true;
            }

            if (string.Equals(text, "true", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "yes", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "y", StringComparison.OrdinalIgnoreCase))
            {
                value = 1;
                return true;
            }
            if (string.Equals(text, "false", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "no", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "n", StringComparison.OrdinalIgnoreCase))
            {
                value = 0;
                return true;
            }

            return false;
        }

        private static bool TryParseLinksheetDouble(string rawValue, out double value)
        {
            value = 0.0;
            string text = (rawValue ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return true;
            }

            return double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out value) ||
                   double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out value);
        }

        private static bool TryResolveLinksheetElementIdValue(string rawValue, out ElementId elementId)
        {
            elementId = ElementId.InvalidElementId;
            string text = (rawValue ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return true;
            }

            if (int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int idValue) ||
                int.TryParse(text, NumberStyles.Integer, CultureInfo.CurrentCulture, out idValue))
            {
                elementId = idValue > 0 ? new ElementId(Convert.ToInt64(idValue, CultureInfo.InvariantCulture)) : ElementId.InvalidElementId;
                return true;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out double asDouble) ||
                double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out asDouble))
            {
                int rounded = Convert.ToInt32(Math.Round(asDouble), CultureInfo.InvariantCulture);
                elementId = rounded > 0 ? new ElementId(Convert.ToInt64(rounded, CultureInfo.InvariantCulture)) : ElementId.InvalidElementId;
                return true;
            }

            return false;
        }

        private static List<ViewSchedule> CollectLinksheetSchedules(Document doc)
        {
            return new FilteredElementCollector(doc)
                .OfClass(typeof(ViewSchedule))
                .Cast<ViewSchedule>()
                .Where(IsLinksheetScheduleSupported)
                .OrderBy(s => s.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static bool IsLinksheetScheduleSupported(ViewSchedule schedule)
        {
            if (schedule == null)
            {
                return false;
            }

            if (GetBooleanProperty(schedule, "IsTemplate"))
            {
                return false;
            }
            if (GetBooleanProperty(schedule, "IsTitleblockRevisionSchedule"))
            {
                return false;
            }

            ScheduleDefinition definition;
            try
            {
                definition = schedule.Definition;
            }
            catch
            {
                return false;
            }

            if (definition == null)
            {
                return false;
            }
            if (GetBooleanProperty(definition, "IsKeySchedule"))
            {
                return false;
            }
            if (GetBooleanProperty(definition, "IsInternalKeynoteSchedule"))
            {
                return false;
            }

            string name = schedule.Name ?? "";
            return !string.IsNullOrWhiteSpace(name) && !name.StartsWith("<", StringComparison.OrdinalIgnoreCase);
        }

        private static bool GetBooleanProperty(object instance, string propertyName)
        {
            if (instance == null || string.IsNullOrWhiteSpace(propertyName))
            {
                return false;
            }

            try
            {
                PropertyInfo property = instance.GetType().GetProperty(propertyName, BindingFlags.Instance | BindingFlags.Public);
                if (property == null || property.PropertyType != typeof(bool))
                {
                    return false;
                }

                object value = property.GetValue(instance);
                return value is bool b && b;
            }
            catch
            {
                return false;
            }
        }

        private static int GetLinksheetScheduleElementCount(Document doc, ViewSchedule schedule)
        {
            if (doc == null || schedule == null)
            {
                return 0;
            }

            try
            {
                TableData tableData = schedule.GetTableData();
                if (tableData == null)
                {
                    return 0;
                }

                TableSectionData body = tableData.GetSectionData(SectionType.Body);
                if (body == null)
                {
                    return 0;
                }

                // Fast path: use schedule body row count instead of per-schedule element collector.
                int rows = body.NumberOfRows;
                return rows < 0 ? 0 : rows;
            }
            catch
            {
                return 0;
            }
        }

        private List<ViewSchedule> GetSelectedLinksheetSchedules(Document doc)
        {
            List<string> names = (Request.LinksheetSelectedScheduleNames ?? new List<string>())
                .Where(n => !string.IsNullOrWhiteSpace(n))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (names.Count == 0)
            {
                return new List<ViewSchedule>();
            }

            Dictionary<string, ViewSchedule> lookup = CollectLinksheetSchedules(doc)
                .GroupBy(s => s.Name, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

            var result = new List<ViewSchedule>();
            foreach (string name in names)
            {
                if (lookup.TryGetValue(name, out ViewSchedule schedule) && schedule != null)
                {
                    result.Add(schedule);
                }
            }

            return result;
        }

        private static List<ScheduleField> GetLinksheetFields(ViewSchedule schedule)
        {
            var fields = new List<ScheduleField>();
            if (schedule == null)
            {
                return fields;
            }

            ScheduleDefinition definition;
            try
            {
                definition = schedule.Definition;
            }
            catch
            {
                return fields;
            }

            if (definition == null)
            {
                return fields;
            }

            try
            {
                IList<ScheduleFieldId> fieldOrder = definition.GetFieldOrder();
                foreach (ScheduleFieldId fieldId in fieldOrder)
                {
                    ScheduleField field = definition.GetField(fieldId);
                    if (field != null)
                    {
                        fields.Add(field);
                    }
                }
            }
            catch
            {
                // ignore schedule definition parsing errors
            }

            return fields;
        }

        private static string GetLinksheetFieldDisplayName(ScheduleField field)
        {
            if (field == null)
            {
                return "";
            }

            string name = "";
            try
            {
                name = field.ColumnHeading;
            }
            catch
            {
            }

            if (string.IsNullOrWhiteSpace(name))
            {
                try
                {
                    name = field.GetName();
                }
                catch
                {
                    name = "";
                }
            }

            return (name ?? "").Trim();
        }

        private LinksheetParameterKind ResolveLinksheetParameterKind(Document doc, Element sampleElement, ScheduleField field)
        {
            if (doc == null || sampleElement == null || field == null)
            {
                return LinksheetParameterKind.ReadOnly;
            }

            Parameter instanceParameter = TryGetLinksheetParameter(sampleElement, field, true);
            if (instanceParameter != null)
            {
                return instanceParameter.IsReadOnly
                    ? LinksheetParameterKind.ReadOnly
                    : LinksheetParameterKind.Instance;
            }

            Element typeElement = null;
            try
            {
                ElementId typeId = sampleElement.GetTypeId();
                if (typeId != null && typeId != ElementId.InvalidElementId)
                {
                    typeElement = doc.GetElement(typeId);
                }
            }
            catch
            {
                typeElement = null;
            }

            Parameter typeParameter = TryGetLinksheetParameter(typeElement, field, true);
            if (typeParameter != null)
            {
                return typeParameter.IsReadOnly
                    ? LinksheetParameterKind.ReadOnly
                    : LinksheetParameterKind.Type;
            }

            return LinksheetParameterKind.ReadOnly;
        }

        private static Parameter TryGetLinksheetParameter(Element element, ScheduleField field, bool allowNameFallback)
        {
            if (element == null || field == null)
            {
                return null;
            }

            Parameter parameter = null;
            ElementId parameterId;

            try
            {
                parameterId = field.ParameterId;
            }
            catch
            {
                parameterId = ElementId.InvalidElementId;
            }

            if (parameterId != null && parameterId != ElementId.InvalidElementId)
            {
                if (parameterId.Value < 0)
                {
                    try
                    {
                        parameter = element.get_Parameter((BuiltInParameter)parameterId.Value);
                    }
                    catch
                    {
                        parameter = null;
                    }
                }
                else
                {
                    try
                    {
                        ParameterSet parameterSet = element.Parameters;
                        if (parameterSet != null)
                        {
                            foreach (Parameter candidate in parameterSet)
                            {
                                if (candidate?.Id != null && candidate.Id.Value == parameterId.Value)
                                {
                                    parameter = candidate;
                                    break;
                                }
                            }
                        }
                    }
                    catch
                    {
                        parameter = null;
                    }
                }
            }

            if (parameter == null && allowNameFallback)
            {
                string fieldName = GetLinksheetFieldDisplayName(field);
                if (!string.IsNullOrWhiteSpace(fieldName))
                {
                    try
                    {
                        parameter = element.LookupParameter(fieldName);
                    }
                    catch
                    {
                        parameter = null;
                    }
                }
            }

            return parameter;
        }

        private string GetLinksheetFieldValue(Document doc, Element element, ScheduleField field)
        {
            if (doc == null || element == null || field == null)
            {
                return "";
            }

            Parameter parameter = TryGetLinksheetParameter(element, field, true);
            if (parameter == null)
            {
                try
                {
                    ElementId typeId = element.GetTypeId();
                    if (typeId != null && typeId != ElementId.InvalidElementId)
                    {
                        Element typeElement = doc.GetElement(typeId);
                        parameter = TryGetLinksheetParameter(typeElement, field, true);
                    }
                }
                catch
                {
                    parameter = null;
                }
            }

            if (parameter == null)
            {
                string fieldName = GetLinksheetFieldDisplayName(field);
                if (string.Equals(fieldName, "Element ID", StringComparison.OrdinalIgnoreCase))
                {
                    return element.Id.Value.ToString(CultureInfo.InvariantCulture);
                }
                if (string.Equals(fieldName, "GUID", StringComparison.OrdinalIgnoreCase))
                {
                    return element.UniqueId ?? "";
                }

                return "";
            }

            return FormatLinksheetParameterValue(doc, parameter);
        }

        private static string FormatLinksheetParameterValue(Document doc, Parameter parameter)
        {
            if (parameter == null)
            {
                return "";
            }

            try
            {
                string asValueString = parameter.AsValueString();
                if (!string.IsNullOrWhiteSpace(asValueString))
                {
                    return asValueString;
                }
            }
            catch
            {
            }

            switch (parameter.StorageType)
            {
                case StorageType.String:
                    return parameter.AsString() ?? "";
                case StorageType.Integer:
                    return parameter.AsInteger().ToString(CultureInfo.InvariantCulture);
                case StorageType.Double:
                    return parameter.AsDouble().ToString("0.###", CultureInfo.InvariantCulture);
                case StorageType.ElementId:
                    ElementId id = parameter.AsElementId();
                    if (id == null || id == ElementId.InvalidElementId)
                    {
                        return "";
                    }

                    Element referenced;
                    try
                    {
                        referenced = doc?.GetElement(id);
                    }
                    catch
                    {
                        referenced = null;
                    }

                    if (referenced != null && !string.IsNullOrWhiteSpace(referenced.Name))
                    {
                        return referenced.Name;
                    }

                    return id.Value.ToString(CultureInfo.InvariantCulture);
                default:
                    return "";
            }
        }

        private static string NormalizeLinksheetParameterKey(string value)
        {
            return (value ?? "").Trim().ToLowerInvariant();
        }

        private static HashSet<long> GetLinksheetScopeElementIds(UIDocument uidoc, Document doc, QsScope scope)
        {
            if (uidoc == null || doc == null || scope == QsScope.EntireModel)
            {
                return null;
            }

            if (scope == QsScope.CurrentSelection)
            {
                return new HashSet<long>(
                    (uidoc.Selection?.GetElementIds() ?? new List<ElementId>())
                        .Select(id => id.Value));
            }

            if (scope == QsScope.CurrentView)
            {
                View activeView = doc.ActiveView;
                if (activeView == null)
                {
                    return new HashSet<long>();
                }

                try
                {
                    return new HashSet<long>(
                        new FilteredElementCollector(doc, activeView.Id)
                            .WhereElementIsNotElementType()
                            .ToElementIds()
                            .Select(id => id.Value));
                }
                catch
                {
                    return new HashSet<long>();
                }
            }

            return null;
        }

        private void PickLink(UIDocument uidoc, Document doc)
        {
            ClearPreviewLines(doc);

            Reference r = uidoc.Selection.PickObject(
                ObjectType.Element,
                new ImportInstanceSelectionFilter(),
                "Select linked DWG (ImportInstance)");

            if (!(doc.GetElement(r) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected element is not a DWG Import/Link.");
                return;
            }

            Request.SelectedLinkId = cad.Id;

            var layers = CollectCadLayers(doc, cad);
            _window?.UpdateLink(cad.Name, layers);

            if (_window != null && _window.IsColumnTabActive() && _window.IsColumnLayerMode())
            {
                AutoDetectColumns(doc, cad, layers, _window.GetColumnLayerName(), true);
            }
        }

        private void PickObjects(UIDocument uidoc, Document doc)
        {
            if (_window != null && _window.IsSoilExcavationTabActive())
            {
                IList<Reference> soilRefs = uidoc.Selection.PickObjects(
                    ObjectType.Element,
                    new SoilExcavationSourceSelectionFilter(),
                    "Select lean concrete floor elements (multiple allowed)");

                List<ElementId> pickedIds = soilRefs
                    .Where(r => r != null && r.ElementId != ElementId.InvalidElementId)
                    .Select(r => r.ElementId)
                    .Distinct()
                    .Where(id => IsSoilExcavationSourceElement(doc.GetElement(id)))
                    .ToList();

                Request.SelectedSoilExcavationSourceElementIds = pickedIds;
                Request.SelectedLeanSourceElementIds.Clear();
                Request.SelectedCadReferences.Clear();
                ClearPreviewLines(doc);

                if (pickedIds.Count > 0)
                {
                    uidoc.Selection.SetElementIds(pickedIds);
                }

                _window?.UpdateSelectedObjectCount(pickedIds.Count);
                _window?.ShowStatus("Selected lean source elements: " +
                                    pickedIds.Count.ToString(CultureInfo.InvariantCulture) +
                                    ". Click Generate.");
                return;
            }

            if (_window != null && _window.IsLeanConcreteTabActive())
            {
                IList<Reference> foundationRefs = uidoc.Selection.PickObjects(
                    ObjectType.Element,
                    new LeanConcreteSourceSelectionFilter(),
                    "Select structural source elements for lean concrete (Foundation, Column, Wall, Beam, Floor, Stair) (multiple allowed)");

                List<ElementId> pickedIds = foundationRefs
                    .Where(r => r != null && r.ElementId != ElementId.InvalidElementId)
                    .Select(r => r.ElementId)
                    .Distinct()
                    .Where(id => IsLeanConcreteSourceElement(doc.GetElement(id)))
                    .ToList();

                Request.SelectedLeanSourceElementIds = pickedIds;
                Request.SelectedSoilExcavationSourceElementIds.Clear();
                Request.SelectedCadReferences.Clear();
                ClearPreviewLines(doc);

                if (pickedIds.Count > 0)
                {
                    uidoc.Selection.SetElementIds(pickedIds);
                }

                _window?.UpdateSelectedObjectCount(pickedIds.Count);
                _window?.ShowStatus("Selected lean source elements: " +
                                    pickedIds.Count.ToString(CultureInfo.InvariantCulture) +
                                    ". Click Generate.");
                return;
            }

            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            IList<Reference> refs = uidoc.Selection.PickObjects(
                ObjectType.PointOnElement,
                new ImportInstanceReferenceFilter(),
                "Select CAD objects in the linked DWG");

            Request.SelectedCadReferences = refs
                .Where(r => r != null && r.ElementId == cad.Id)
                .ToList();
            Request.SelectedLeanSourceElementIds.Clear();
            Request.SelectedSoilExcavationSourceElementIds.Clear();

            ClearPreviewLines(doc);
            CreatePreviewLines(uidoc, doc, cad, Request.SelectedCadReferences);
            HighlightPickedCadReferences(uidoc, cad, Request.SelectedCadReferences);

            _window?.UpdateSelectedObjectCount(Request.SelectedCadReferences.Count);
        }

        private void PickColumnSideline(UIDocument uidoc, Document doc)
        {
            Request.HasSelectedColumnSidelineBox = false;
            Request.SelectedColumnSidelineBoxMin = XYZ.Zero;
            Request.SelectedColumnSidelineBoxMax = XYZ.Zero;
            Request.SelectedLeanSourceElementIds.Clear();
            Request.SelectedSoilExcavationSourceElementIds.Clear();

            if (Request.UseColorFilter)
            {
                Reference reference = uidoc.Selection.PickObject(
                    ObjectType.PointOnElement,
                    new ImportInstanceReferenceFilter(),
                    "Select Column Sideline color, right click to confirm");

                if (!TryUseCadFromReference(doc, reference, "Column sideline", out ImportInstance cad))
                {
                    return;
                }

                GeometryObject geometry = cad.GetGeometryObjectFromReference(reference);
                string colorKey = GetCadColorKey(doc, geometry);
                if (string.IsNullOrWhiteSpace(colorKey))
                {
                    _window?.ShowStatus("Pick Sideline: CAD color could not be read.");
                    return;
                }

                CadShapeHits hits = ExtractShapesFromColor(doc, cad, colorKey);
                Request.SelectedColumnSidelineColorKey = colorKey;
                Request.SelectedColumnSidelineReferences.Clear();
                Request.SelectedCadReferences.Clear();

                ClearPreviewLines(doc);
                CreatePreviewLinesFromHits(uidoc, doc, hits);
                ApplyColumnSidelineColorHits(colorKey, hits);
                return;
            }

            if (Request.UseLayerFilter)
            {
                Reference reference = uidoc.Selection.PickObject(
                    ObjectType.PointOnElement,
                    new ImportInstanceReferenceFilter(),
                    "Select Column Sideline, right click to confirm");

                if (!TryUseCadFromReference(doc, reference, "Column sideline", out ImportInstance cad))
                {
                    return;
                }

                string layerName = GetCadLayer(doc, cad.GetGeometryObjectFromReference(reference));
                if (string.IsNullOrWhiteSpace(layerName))
                {
                    _window?.ShowStatus("Pick Sideline: CAD layer could not be read.");
                    return;
                }

                CadShapeHits hits = ExtractShapesFromLayer(doc, cad, layerName);
                Request.SelectedLayerName = layerName;
                Request.SelectedColumnSidelineColorKey = "";
                Request.SelectedColumnSidelineReferences.Clear();
                Request.SelectedCadReferences.Clear();

                ClearPreviewLines(doc);
                CreatePreviewLinesFromHits(uidoc, doc, hits);
                ApplyColumnSidelineHits(layerName, hits, true);
                return;
            }

            IList<Reference> refs = uidoc.Selection.PickObjects(
                ObjectType.PointOnElement,
                new ImportInstanceReferenceFilter(),
                "Select Column Sideline, right click to confirm");

            if (!TryUseCadFromReferences(doc, refs, "Column sideline", out ImportInstance pickedCad))
            {
                return;
            }

            Request.SelectedColumnSidelineReferences = refs
                .Where(r => r != null && r.ElementId == pickedCad.Id)
                .ToList();
            Request.SelectedCadReferences = Request.SelectedColumnSidelineReferences.ToList();
            Request.SelectedColumnSidelineColorKey = "";

            CadShapeHits selectedHits = ExtractShapesFromSelectedObjects(doc, pickedCad, Request.SelectedColumnSidelineReferences);

            ClearPreviewLines(doc);
            CreatePreviewLinesFromHits(uidoc, doc, selectedHits);
            HighlightPickedCadReferences(uidoc, pickedCad, Request.SelectedColumnSidelineReferences);
            ApplyColumnSidelineHits("", selectedHits, false);
        }

        private void PickColumnLabel(UIDocument uidoc, Document doc)
        {
            if (Request.UseColumnLabelColorFilter)
            {
                Reference reference = uidoc.Selection.PickObject(
                    ObjectType.PointOnElement,
                    new ImportInstanceReferenceFilter(),
                    "Select Column Label color, right click to confirm");

                if (!TryUseCadFromReference(doc, reference, "Column label", out ImportInstance cad))
                {
                    return;
                }

                GeometryObject geometry = cad.GetGeometryObjectFromReference(reference);
                string colorKey = GetCadColorKey(doc, geometry);
                if (string.IsNullOrWhiteSpace(colorKey))
                {
                    _window?.ShowStatus("Column label color could not be read.");
                    return;
                }

                Request.SelectedColumnLabelColorKey = colorKey;
                Request.SelectedColumnLabelReferences.Clear();
                Request.UseColumnLabelSelectionFilter = false;
                Request.UseColumnLabelLayerFilter = false;
                Request.UseColumnLabelColorFilter = true;

                int labelCount = CollectCadTextLabelsByColor(doc, cad, colorKey).Count;
                _window?.ApplyColumnLabelColorPick(colorKey, labelCount);
                return;
            }

            if (Request.UseColumnLabelLayerFilter)
            {
                Reference reference = uidoc.Selection.PickObject(
                    ObjectType.PointOnElement,
                    new ImportInstanceReferenceFilter(),
                    "Select Column Label, right click to confirm");

                if (!TryUseCadFromReference(doc, reference, "Column label", out ImportInstance cad))
                {
                    return;
                }

                GeometryObject geometry = cad.GetGeometryObjectFromReference(reference);
                string layerName = GetCadLayer(doc, geometry);
                if (string.IsNullOrWhiteSpace(layerName))
                {
                    _window?.ShowStatus("Column label layer could not be read.");
                    return;
                }

                Request.SelectedLabelLayerName = layerName;
                Request.SelectedColumnLabelColorKey = "";
                Request.SelectedColumnLabelReferences.Clear();
                Request.UseColumnLabelSelectionFilter = false;
                Request.UseColumnLabelLayerFilter = true;
                Request.UseColumnLabelColorFilter = false;

                int labelCount = CollectCadTextLabels(doc, cad, layerName).Count;
                _window?.ApplyColumnLabelPick(layerName, labelCount, true);
                return;
            }

            IList<Reference> refs = uidoc.Selection.PickObjects(
                ObjectType.PointOnElement,
                new ImportInstanceReferenceFilter(),
                "Select Column Label, right click to confirm");

            if (!TryUseCadFromReferences(doc, refs, "Column label", out ImportInstance pickedCad))
            {
                return;
            }

            Request.SelectedColumnLabelReferences = refs
                .Where(r => r != null && r.ElementId == pickedCad.Id)
                .ToList();
            Request.SelectedColumnLabelColorKey = "";
            Request.UseColumnLabelSelectionFilter = true;
            Request.UseColumnLabelLayerFilter = false;
            Request.UseColumnLabelColorFilter = false;

            HighlightPickedCadReferences(uidoc, pickedCad, Request.SelectedColumnLabelReferences);

            int pickedLabelCount = CollectCadTextLabelsFromSelectedObjects(
                doc,
                pickedCad,
                Request.SelectedColumnLabelReferences,
                "").Count;
            _window?.ApplyColumnLabelPick("", pickedLabelCount, false);
        }

        private void ClickIdentifyColumns(UIDocument uidoc, Document doc)
        {
            Reference reference = uidoc.Selection.PickObject(
                ObjectType.PointOnElement,
                new ImportInstanceReferenceFilter(),
                "Click-Identify Column source");

            if (!TryUseCadFromReference(doc, reference, "Click-Identify column", out ImportInstance cad))
            {
                return;
            }

            GeometryObject geometry = cad.GetGeometryObjectFromReference(reference);
            XYZ clickPoint = reference.GlobalPoint;
            if (clickPoint == null)
            {
                clickPoint = TryGetGeometryObjectApproximatePoint(geometry, GetCadGeometryRootTransform(cad));
            }

            if (clickPoint == null)
            {
                _window?.ShowStatus("Click-Identify: CAD pick point could not be read.");
                return;
            }

            string layerName = GetCadLayer(doc, geometry);
            string colorKey = GetCadColorKey(doc, geometry);
            double radiusFt = MmToFeet(1200.0);
            XYZ boxMin = new XYZ(clickPoint.X - radiusFt, clickPoint.Y - radiusFt, 0.0);
            XYZ boxMax = new XYZ(clickPoint.X + radiusFt, clickPoint.Y + radiusFt, 0.0);

            string layerFilter = layerName ?? "";
            string colorFilter = string.IsNullOrWhiteSpace(layerFilter) ? (colorKey ?? "") : "";
            CadShapeHits hits = ExtractShapesFromBox(
                doc,
                cad,
                boxMin,
                boxMax,
                layerFilter,
                colorFilter,
                null,
                null);

            if (hits == null || hits.IsEmpty)
            {
                hits = ExtractShapesFromSelectedObjects(doc, cad, new List<Reference> { reference });
            }

            XYZ columnPoint = ResolveClickIdentifyPoint(hits, clickPoint);
            if (columnPoint == null)
            {
                _window?.ShowStatus("Click-Identify: No valid column point found.");
                return;
            }

            Request.SelectedColumnSidelineReferences = new List<Reference> { reference };
            Request.SelectedCadReferences = Request.SelectedColumnSidelineReferences.ToList();
            Request.HasSelectedColumnSidelineBox = true;
            Request.SelectedColumnSidelineBoxMin = boxMin;
            Request.SelectedColumnSidelineBoxMax = boxMax;
            Request.ExplicitColumnPoints.Clear();
            Request.ExplicitColumnPoints.Add(columnPoint);

            ApplyColumnSourceFilters(layerFilter, colorFilter);
            ConfigureColumnGeometryOptionsFromHits(hits, true, out _);
            _window?.ApplyColumnAutoSettings(
                string.IsNullOrWhiteSpace(layerFilter) ? "" : layerFilter,
                Request.UseCircles,
                Request.UseBlocks,
                Request.UseLineIntersections,
                1);

            GenerateColumns(doc);
        }

        private void DragIdentifyColumns(UIDocument uidoc, Document doc)
        {
            if (!TryGetSelectedOrFirstCad(doc, "No linked/imported DWG found for Drag-Identify.", out ImportInstance cad))
            {
                return;
            }

            PickedBox box = uidoc.Selection.PickBox(PickBoxStyle.Enclosing, "Drag-Identify Column area");
            if (box == null)
            {
                _window?.ShowStatus("Drag-Identify: No selection box.");
                return;
            }

            string layerFilter = Request.UseLayerFilter ? (Request.SelectedLayerName ?? "") : "";
            string colorFilter = Request.UseColorFilter ? (Request.SelectedColumnSidelineColorKey ?? "") : "";

            CadShapeHits hits = ExtractShapesFromBox(doc, cad, box.Min, box.Max, layerFilter, colorFilter, null, null);
            if ((hits == null || hits.IsEmpty) && !string.IsNullOrWhiteSpace(layerFilter))
            {
                hits = ExtractShapesFromBox(doc, cad, box.Min, box.Max, "", colorFilter, null, null);
                if (hits != null && !hits.IsEmpty)
                {
                    layerFilter = "";
                }
            }

            if (hits == null || hits.IsEmpty)
            {
                _window?.ShowStatus("Drag-Identify: No valid CAD column geometry found inside the selected box.");
                return;
            }

            Request.SelectedColumnSidelineReferences.Clear();
            Request.SelectedCadReferences.Clear();
            Request.ExplicitColumnPoints.Clear();
            Request.HasSelectedColumnSidelineBox = true;
            Request.SelectedColumnSidelineBoxMin = box.Min;
            Request.SelectedColumnSidelineBoxMax = box.Max;

            ApplyColumnSourceFilters(layerFilter, colorFilter);
            ConfigureColumnGeometryOptionsFromHits(hits, false, out int previewCount);
            if (previewCount <= 0)
            {
                _window?.ShowStatus("Drag-Identify: CAD geometry was found, but no column points could be resolved.");
                return;
            }

            _window?.ApplyColumnAutoSettings(
                string.IsNullOrWhiteSpace(layerFilter) ? "" : layerFilter,
                Request.UseCircles,
                Request.UseBlocks,
                Request.UseLineIntersections,
                previewCount);

            GenerateColumns(doc);
        }

        private void ApplyColumnSourceFilters(string layerFilter, string colorFilter)
        {
            if (!string.IsNullOrWhiteSpace(layerFilter))
            {
                Request.UseLayerFilter = true;
                Request.UseColorFilter = false;
                Request.SelectedLayerName = layerFilter;
                Request.SelectedColumnSidelineColorKey = "";
                return;
            }

            if (!string.IsNullOrWhiteSpace(colorFilter))
            {
                Request.UseLayerFilter = false;
                Request.UseColorFilter = true;
                Request.SelectedColumnSidelineColorKey = colorFilter;
                return;
            }

            Request.UseLayerFilter = false;
            Request.UseColorFilter = false;
            Request.SelectedColumnSidelineColorKey = "";
        }

        private void ConfigureColumnGeometryOptionsFromHits(CadShapeHits hits, bool fallbackToExplicitPoint, out int previewCount)
        {
            bool useCircles = hits != null && hits.CircleCenters.Count > 0;
            bool useBlocks = hits != null && hits.BlockPoints.Count > 0;
            bool useLines = hits != null &&
                            (hits.Lines.Count > 1 || hits.Polylines.Count > 0) &&
                            !useCircles &&
                            !useBlocks;

            if (fallbackToExplicitPoint && !useCircles && !useBlocks && !useLines)
            {
                useBlocks = true;
            }

            Request.UseCircles = useCircles;
            Request.UseBlocks = useBlocks;
            Request.UseLineIntersections = useLines;
            previewCount = EstimateColumnCount(hits, useCircles, useBlocks, useLines);

            if (fallbackToExplicitPoint)
            {
                previewCount = Math.Max(1, previewCount);
            }
        }

        private static XYZ ResolveClickIdentifyPoint(CadShapeHits hits, XYZ clickPoint)
        {
            if (clickPoint == null)
            {
                return null;
            }

            IEnumerable<XYZ> pointCandidates = Enumerable.Empty<XYZ>();
            if (hits != null)
            {
                pointCandidates = hits.CircleCenters
                    .Concat(hits.BlockPoints)
                    .Concat(hits.Polylines.Select(p => p.Center));
            }

            XYZ nearest = pointCandidates
                .Where(p => p != null)
                .OrderBy(p => p.DistanceTo(clickPoint))
                .FirstOrDefault();
            if (nearest != null)
            {
                return nearest;
            }

            if (TryComputeLineBoundsCenter(hits?.Lines, out XYZ lineCenter))
            {
                return lineCenter;
            }

            return clickPoint;
        }

        private static bool TryComputeLineBoundsCenter(IEnumerable<Line> lines, out XYZ center)
        {
            center = null;
            if (lines == null)
            {
                return false;
            }

            bool hasPoint = false;
            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;
            double z = 0.0;

            foreach (Line line in lines)
            {
                if (line == null)
                {
                    continue;
                }

                for (int i = 0; i < 2; i++)
                {
                    XYZ point = line.GetEndPoint(i);
                    if (point == null)
                    {
                        continue;
                    }

                    hasPoint = true;
                    minX = Math.Min(minX, point.X);
                    minY = Math.Min(minY, point.Y);
                    maxX = Math.Max(maxX, point.X);
                    maxY = Math.Max(maxY, point.Y);
                    z = point.Z;
                }
            }

            if (!hasPoint)
            {
                return false;
            }

            center = new XYZ((minX + maxX) * 0.5, (minY + maxY) * 0.5, z);
            return true;
        }

        private static XYZ TryGetGeometryObjectApproximatePoint(GeometryObject geometry, Transform transform)
        {
            if (geometry == null)
            {
                return null;
            }

            Transform trf = transform ?? Transform.Identity;

            GeometryInstance instance = geometry as GeometryInstance;
            if (instance != null)
            {
                return trf.Multiply(instance.Transform).Origin;
            }

            Arc arc = geometry as Arc;
            if (arc != null)
            {
                return trf.OfPoint(arc.Center);
            }

            Line line = geometry as Line;
            if (line != null)
            {
                return (trf.OfPoint(line.GetEndPoint(0)) + trf.OfPoint(line.GetEndPoint(1))) * 0.5;
            }

            Curve curve = geometry as Curve;
            if (curve != null)
            {
                try
                {
                    return (trf.OfPoint(curve.GetEndPoint(0)) + trf.OfPoint(curve.GetEndPoint(1))) * 0.5;
                }
                catch
                {
                    return null;
                }
            }

            PolyLine polyline = geometry as PolyLine;
            if (polyline != null)
            {
                IList<XYZ> points = polyline.GetCoordinates();
                if (points != null && points.Count > 0)
                {
                    return ComputePolylineCentroid(points.Select(p => trf.OfPoint(p)).ToList());
                }
            }

            return null;
        }

        private static Transform GetCadGeometryRootTransform(ImportInstance cad)
        {
            // CAD ImportInstance geometry already carries placement through nested
            // GeometryInstance transforms. Starting with GetTotalTransform here
            // shifts generated Revit elements away from the visible DWG.
            return Transform.Identity;
        }

        private static GeometryElement GetCadSymbolGeometry(GeometryInstance instance)
        {
            if (instance == null)
            {
                return null;
            }

            try
            {
                return instance.GetSymbolGeometry();
            }
            catch
            {
                return null;
            }
        }

        private bool TryGetSelectedCad(Document doc, out ImportInstance cad)
        {
            cad = null;
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return false;
            }

            cad = doc.GetElement(Request.SelectedLinkId) as ImportInstance;
            if (cad == null)
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return false;
            }

            return true;
        }

        private bool TryGetSelectedOrFirstCad(Document doc, string missingStatus, out ImportInstance cad)
        {
            cad = null;
            if (Request.SelectedLinkId != ElementId.InvalidElementId)
            {
                cad = doc.GetElement(Request.SelectedLinkId) as ImportInstance;
                if (cad != null)
                {
                    return true;
                }
            }

            cad = CollectCandidateCadImports(doc).FirstOrDefault();
            if (cad == null)
            {
                _window?.ShowStatus(string.IsNullOrWhiteSpace(missingStatus) ? "No linked/imported DWG found." : missingStatus);
                return false;
            }

            UseCadImport(doc, cad);
            return true;
        }

        private bool TryUseCadFromReference(Document doc, Reference reference, string context, out ImportInstance cad)
        {
            cad = null;
            if (reference == null || reference.ElementId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus(context + " was not selected from a DWG import/link.");
                return false;
            }

            cad = doc.GetElement(reference.ElementId) as ImportInstance;
            if (cad == null)
            {
                _window?.ShowStatus(context + " was not selected from a DWG import/link.");
                return false;
            }

            UseCadImport(doc, cad);
            return true;
        }

        private bool TryUseCadFromReferences(Document doc, IList<Reference> references, string context, out ImportInstance cad)
        {
            cad = null;
            if (references == null || references.Count == 0)
            {
                _window?.ShowStatus("No " + context.ToLowerInvariant() + " CAD objects selected.");
                return false;
            }

            foreach (Reference reference in references)
            {
                if (reference == null || reference.ElementId == ElementId.InvalidElementId)
                {
                    continue;
                }

                cad = doc.GetElement(reference.ElementId) as ImportInstance;
                if (cad != null)
                {
                    UseCadImport(doc, cad);
                    return true;
                }
            }

            _window?.ShowStatus(context + " was not selected from a DWG import/link.");
            return false;
        }

        private void UseCadImport(Document doc, ImportInstance cad)
        {
            if (doc == null || cad == null)
            {
                return;
            }

            Request.SelectedLinkId = cad.Id;
            var layers = CollectCadLayers(doc, cad);
            _window?.UpdateLink(cad.Name, layers);
        }

        private List<ImportInstance> CollectCandidateCadImports(Document doc)
        {
            var imports = new List<ImportInstance>();
            var seen = new HashSet<long>();

            void Add(ImportInstance cad)
            {
                if (cad == null)
                {
                    return;
                }

                long key = cad.Id.Value;
                if (seen.Add(key))
                {
                    imports.Add(cad);
                }
            }

            if (doc == null)
            {
                return imports;
            }

            if (Request.SelectedLinkId != ElementId.InvalidElementId)
            {
                Add(doc.GetElement(Request.SelectedLinkId) as ImportInstance);
            }

            try
            {
                View activeView = doc.ActiveView;
                if (activeView != null && activeView.Id != ElementId.InvalidElementId)
                {
                    foreach (ImportInstance cad in new FilteredElementCollector(doc, activeView.Id)
                                 .OfClass(typeof(ImportInstance))
                                 .Cast<ImportInstance>())
                    {
                        Add(cad);
                    }
                }
            }
            catch
            {
                // Some view types do not support view-scoped collection; fall back to document scope below.
            }

            try
            {
                foreach (ImportInstance cad in new FilteredElementCollector(doc)
                             .OfClass(typeof(ImportInstance))
                             .Cast<ImportInstance>())
                {
                    Add(cad);
                }
            }
            catch
            {
                // Keep the command non-fatal; caller will report if no CAD import can be used.
            }

            return imports;
        }

        private static List<CadTextLabel> FilterCadTextLabelsInsideBox(IEnumerable<CadTextLabel> labels, PickedBox box)
        {
            var inside = new List<CadTextLabel>();
            if (labels == null || box == null)
            {
                return inside;
            }

            double minX = Math.Min(box.Min.X, box.Max.X);
            double maxX = Math.Max(box.Min.X, box.Max.X);
            double minY = Math.Min(box.Min.Y, box.Max.Y);
            double maxY = Math.Max(box.Min.Y, box.Max.Y);

            foreach (CadTextLabel label in labels)
            {
                if (label == null)
                {
                    continue;
                }

                if (label.Position.X >= minX && label.Position.X <= maxX &&
                    label.Position.Y >= minY && label.Position.Y <= maxY)
                {
                    inside.Add(label);
                }
            }

            return inside;
        }

        private static List<CadTextLabel> CollectScheduleTextLabelsInsideBox(Document doc, ImportInstance cad, PickedBox box)
        {
            var result = new List<CadTextLabel>();
            if (doc == null || cad == null || box == null)
            {
                return result;
            }

            foreach (CadTextLabel label in FilterCadTextLabelsInsideBox(CollectCadTextLabels(doc, cad, ""), box))
            {
                AddCadTextLabelUnique(result, label);
            }

            foreach (CadTextLabel label in FilterCadTextLabelsInsideBox(CollectCadTextLabelsRaw(doc, cad, ""), box))
            {
                AddCadTextLabelUnique(result, label);
            }

            return result;
        }

        private static List<CadTextLabel> CollectRevitTextLabelsInsideBox(Document doc, PickedBox box)
        {
            var result = new List<CadTextLabel>();
            if (doc == null || box == null || doc.ActiveView == null)
            {
                return result;
            }

            IEnumerable<TextNote> textNotes;
            try
            {
                textNotes = new FilteredElementCollector(doc, doc.ActiveView.Id)
                    .OfClass(typeof(TextNote))
                    .Cast<TextNote>();
            }
            catch
            {
                textNotes = Enumerable.Empty<TextNote>();
            }

            foreach (TextNote note in textNotes)
            {
                if (note == null || string.IsNullOrWhiteSpace(note.Text))
                {
                    continue;
                }

                XYZ position = note.Coord;
                if (position == null)
                {
                    BoundingBoxXYZ bb = note.get_BoundingBox(doc.ActiveView);
                    if (bb == null)
                    {
                        continue;
                    }

                    position = (bb.Min + bb.Max) * 0.5;
                }

                AddCadTextLabelUnique(result, new CadTextLabel(note.Text.Trim(), position));
            }

            return FilterCadTextLabelsInsideBox(result, box);
        }

        private static void AddCadTextLabelUnique(List<CadTextLabel> labels, CadTextLabel candidate)
        {
            if (labels == null || candidate == null || string.IsNullOrWhiteSpace(candidate.Text))
            {
                return;
            }

            bool exists = labels.Any(existing =>
                existing != null &&
                string.Equals(existing.Text, candidate.Text, StringComparison.OrdinalIgnoreCase) &&
                existing.Position.DistanceTo(candidate.Position) < MmToFeet(5.0));
            if (!exists)
            {
                labels.Add(candidate);
            }
        }

        private void ApplyColumnSidelineHits(string layerName, CadShapeHits hits, bool byLayer)
        {
            if (hits == null || hits.IsEmpty)
            {
                _window?.ApplyColumnSidelinePick(layerName, false, false, false, 0, byLayer);
                _window?.ShowStatus("Pick Sideline: no valid column sideline geometry found.");
                return;
            }

            bool useCircles = hits.CircleCenters.Count > 0;
            bool useBlocks = hits.BlockPoints.Count > 0;
            bool useLines = (hits.Lines.Count > 1 || hits.Polylines.Count > 0) && !useCircles && !useBlocks;
            int previewCount = EstimateColumnCount(hits, useCircles, useBlocks, useLines);

            _window?.ApplyColumnSidelinePick(layerName, useCircles, useBlocks, useLines, previewCount, byLayer);
        }

        private void ApplyColumnSidelineColorHits(string colorKey, CadShapeHits hits)
        {
            if (hits == null || hits.IsEmpty)
            {
                _window?.ApplyColumnSidelineColorPick(colorKey, false, false, false, 0);
                _window?.ShowStatus("Pick Sideline: no valid column sideline geometry found for the selected color.");
                return;
            }

            bool useCircles = hits.CircleCenters.Count > 0;
            bool useBlocks = hits.BlockPoints.Count > 0;
            bool useLines = (hits.Lines.Count > 1 || hits.Polylines.Count > 0) && !useCircles && !useBlocks;
            int previewCount = EstimateColumnCount(hits, useCircles, useBlocks, useLines);

            _window?.ApplyColumnSidelineColorPick(colorKey, useCircles, useBlocks, useLines, previewCount);
        }

        private void PickColumnRebarHost(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            IList<Reference> pickedRefs = uidoc.Selection.PickObjects(
                ObjectType.Element,
                new ColumnRebarHostSelectionFilter(),
                "Select one or more structural columns for rebar generation");

            if (pickedRefs == null || pickedRefs.Count == 0)
            {
                _window?.ShowStatus("Column Rebar: no columns selected.");
                return;
            }

            List<Element> selectedHosts = new List<Element>();
            HashSet<long> seenIds = new HashSet<long>();
            foreach (Reference pickedRef in pickedRefs)
            {
                if (pickedRef == null || pickedRef.ElementId == ElementId.InvalidElementId)
                {
                    continue;
                }

                if (!seenIds.Add(pickedRef.ElementId.Value))
                {
                    continue;
                }

                Element hostCandidate = doc.GetElement(pickedRef.ElementId);
                if (!IsColumnRebarHostElement(hostCandidate))
                {
                    continue;
                }

                selectedHosts.Add(hostCandidate);
            }

            if (selectedHosts.Count == 0)
            {
                _window?.ShowStatus("Column Rebar: no valid structural columns selected.");
                return;
            }

            Element host = selectedHosts[0];
            if (!TryBuildColumnRebarHostPreviewData(doc, host, out CamboBIMWindow.ColumnRebarHostPreviewData preview, out string error))
            {
                _window?.ShowStatus("Column Rebar: " + error);
                return;
            }

            Request.ColumnRebarHostElementId = host.Id;
            Request.ColumnRebarHostElementIds = selectedHosts
                .Select(x => x?.Id ?? ElementId.InvalidElementId)
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();
            Request.ColumnRebarSelectedFloorNames = selectedHosts
                .Select(x => TryGetElementLevelName(doc, x))
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();

            try
            {
                uidoc.Selection.SetElementIds(Request.ColumnRebarHostElementIds);
            }
            catch
            {
            }

            _window?.UpdateColumnRebarHostPreview(preview);
        }

        private void PickFoundationRebarHost(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            Reference pickedRef = uidoc.Selection.PickObject(
                ObjectType.Element,
                new FoundationRebarHostSelectionFilter(),
                "Select a foundation host (isolated footing / pile cap / strip footing / raft)");

            if (pickedRef == null || pickedRef.ElementId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("FOUNDATION: no host selected.");
                return;
            }

            Element host = doc.GetElement(pickedRef.ElementId);
            if (!IsFoundationRebarHostElement(host))
            {
                _window?.ShowStatus("FOUNDATION: selected element is not a valid foundation rebar host.");
                return;
            }

            if (!TryBuildFoundationRebarHostPreviewData(doc, host, out CamboBIMWindow.FoundationRebarHostPreviewData preview, out string error))
            {
                _window?.ShowStatus("FOUNDATION: " + error);
                return;
            }

            Request.FoundationRebarHostElementId = host.Id;

            try
            {
                uidoc.Selection.SetElementIds(new List<ElementId> { host.Id });
            }
            catch
            {
            }

            _window?.UpdateFoundationRebarHostPreview(preview);
        }

        private void PickWallRebarHosts(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            IList<Reference> pickedRefs = uidoc.Selection.PickObjects(
                ObjectType.Element,
                new WallRebarHostSelectionFilter(),
                "Select one or more walls/floors for wall reinforcement");

            List<ElementId> selectedHostIds = new List<ElementId>();
            int wallCount = 0;
            int floorCount = 0;
            HashSet<long> seenIds = new HashSet<long>();

            foreach (Reference pickedRef in pickedRefs ?? new List<Reference>())
            {
                if (pickedRef == null || pickedRef.ElementId == ElementId.InvalidElementId)
                {
                    continue;
                }

                if (!seenIds.Add(pickedRef.ElementId.Value))
                {
                    continue;
                }

                Element candidate = doc.GetElement(pickedRef.ElementId);
                if (!IsWallRebarHostElement(candidate))
                {
                    continue;
                }

                selectedHostIds.Add(candidate.Id);

                if (candidate is Wall)
                {
                    wallCount++;
                }
                else if (candidate is Floor)
                {
                    floorCount++;
                }
            }

            Request.WallRebarHostElementIds = selectedHostIds;

            try
            {
                uidoc.Selection.SetElementIds(selectedHostIds);
            }
            catch
            {
            }

            _window?.UpdateWallRebarSelectedHosts(selectedHostIds, wallCount, floorCount);

            if (selectedHostIds.Count == 0)
            {
                _window?.ShowStatus("WALL: no valid walls/floors selected.");
                return;
            }

            _window?.ShowStatus(
                $"WALL: selected {selectedHostIds.Count} host(s) ({wallCount} wall(s), {floorCount} floor(s)).");
        }

        private void PickBeamRebarHosts(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            List<ElementId> selectedHostIds = PickBeamRebarElementIds(
                uidoc,
                doc,
                "Select one or more beams for beam reinforcement");
            if (selectedHostIds == null)
            {
                _window?.ShowStatus("BEAM: host selection canceled.");
                return;
            }
            Request.BeamRebarHostElementIds = selectedHostIds;

            try
            {
                uidoc.Selection.SetElementIds(selectedHostIds);
            }
            catch
            {
            }

            List<double> selectedHostLengthsMm = GetBeamRebarHostLengthsMm(doc, selectedHostIds);
            _window?.UpdateBeamRebarSelectedHosts(selectedHostIds, selectedHostLengthsMm);
            if (TryGetPrimaryBeamHostSectionMm(doc, selectedHostIds, out double hostWidthMm, out double hostDepthMm))
            {
                _window?.UpdateBeamRebarSelectedHostSection(hostWidthMm, hostDepthMm);
            }
            else
            {
                _window?.UpdateBeamRebarSelectedHostSection(0.0, 0.0);
            }

            List<BeamSupportPreviewMarker> detectedSupportProfiles = DetectBeamSupportPreviewMarkersMm(doc, selectedHostIds);
            List<double> detectedSupportStationsMm = detectedSupportProfiles
                .Select(x => x.StationMm)
                .ToList();
            _window?.UpdateBeamRebarDetectedSupportStations(
                detectedSupportStationsMm,
                detectedSupportProfiles.Select(x => x.WidthMm).ToList(),
                detectedSupportProfiles.Select(x => x.KindKey).ToList());
            BeamHostDetectedElementSummary detectedSummary = DetectBeamHostRelatedElementsSummary(doc, selectedHostIds);
            string detectedSummaryText = BuildBeamHostDetectedSummaryText(detectedSummary);

            double hostLengthMm = selectedHostLengthsMm.DefaultIfEmpty(0.0).Max();
            double stationTolMm = Math.Max(120.0, hostLengthMm * 0.01);
            int startConnectionCount = detectedSupportStationsMm.Count(s => s <= stationTolMm);
            int endConnectionCount = detectedSupportStationsMm.Count(s => s >= Math.Max(0.0, hostLengthMm - stationTolMm));
            _window?.UpdateBeamRebarDetectedModelConnection(
                startConnectionCount,
                endConnectionCount);
            _window?.UpdateBeamRebarDetectedModelSummary(detectedSummaryText);

            if (selectedHostIds.Count == 0)
            {
                _window?.ShowStatus("BEAM: no valid beam hosts selected.");
                return;
            }

            _window?.ShowStatus(
                $"BEAM: selected {selectedHostIds.Count} host(s). " +
                (string.IsNullOrWhiteSpace(detectedSummaryText) ? "" : $"Detected -> {detectedSummaryText}."));
        }

