        private void PickBeamRebarSupportHosts(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            List<ElementId> selectedIds = PickBeamSupportReferenceElementIds(
                uidoc,
                doc,
                "Select support element(s): column, wall, foundation, or framing");
            if (selectedIds == null)
            {
                _window?.ShowStatus("BEAM: support reference selection canceled.");
                return;
            }
            Request.BeamRebarSupportElementIds = selectedIds;
            try
            {
                uidoc.Selection.SetElementIds(selectedIds);
            }
            catch
            {
            }
            _window?.UpdateBeamRebarSelectedSupportHosts(selectedIds);
            List<BeamSupportPreviewMarker> supportProfiles = DetectBeamSupportPreviewMarkersMm(
                doc,
                Request.BeamRebarHostElementIds,
                selectedIds);
            if (supportProfiles.Count > 0)
            {
                _window?.UpdateBeamRebarDetectedSupportStations(
                    supportProfiles.Select(x => x.StationMm).ToList(),
                    supportProfiles.Select(x => x.WidthMm).ToList(),
                    supportProfiles.Select(x => x.KindKey).ToList());
            }

            if (selectedIds.Count == 0)
