                _window?.ShowStatus("BEAM: no support element(s) selected.");
                return;
            }

            if (supportProfiles.Count > 0)
            {
                _window?.ShowStatus($"BEAM: selected {selectedIds.Count} support reference(s) [column/wall/foundation/framing]. Detected {supportProfiles.Count} support station(s).");
            }
            else
            {
                _window?.ShowStatus($"BEAM: selected {selectedIds.Count} support reference(s) [column/wall/foundation/framing].");
            }
        }

        private static List<ElementId> PickBeamRebarElementIds(UIDocument uidoc, Document doc, string prompt)
        {
            if (uidoc == null || doc == null)
            {
                return new List<ElementId>();
            }

            // If the user already selected beams before clicking "Pick Beam", use that selection directly.
            List<ElementId> preselectedBeamIds = (uidoc.Selection.GetElementIds() ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .Select(id => doc.GetElement(id))
                .Where(IsBeamRebarHostElement)
                .Select(e => e.Id)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();
            if (preselectedBeamIds.Count > 0)
            {
                return preselectedBeamIds;
            }

            IList<Reference> pickedRefs;
            try
            {
                pickedRefs = uidoc.Selection.PickObjects(
                    ObjectType.Element,
                    new BeamRebarHostSelectionFilter(),
                    prompt ?? "Select one or more beams");
            }
            catch (Autodesk.Revit.Exceptions.OperationCanceledException)
            {
                return null;
            }

            List<ElementId> selectedIds = new List<ElementId>();
            HashSet<long> seenIds = new HashSet<long>();

            foreach (Reference pickedRef in pickedRefs ?? new List<Reference>())
            {
                if (pickedRef == null || pickedRef.ElementId == ElementId.InvalidElementId)
                {
                    continue;
                }

                if (!seenIds.Add(pickedRef.ElementId.Value))
                {
                    continue;
                }

                Element candidate = doc.GetElement(pickedRef.ElementId);
                if (!IsBeamRebarHostElement(candidate))
                {
                    continue;
                }

                selectedIds.Add(candidate.Id);
            }

            return selectedIds;
        }

