        private static List<double> GetBeamRebarHostLengthsMm(Document doc, IEnumerable<ElementId> hostIds)
        {
            var lengthsMm = new List<double>();
            foreach (ElementId id in hostIds ?? Enumerable.Empty<ElementId>())
            {
                if (id == null || id == ElementId.InvalidElementId)
                {
                    continue;
                }

                Element host = doc.GetElement(id);
                if (!IsBeamRebarHostElement(host))
                {
                    continue;
                }

                double lengthFeet = 0.0;
                if (host.Location is LocationCurve locationCurve && locationCurve.Curve != null)
                {
                    lengthFeet = locationCurve.Curve.Length;
                }
                if (lengthFeet <= 1e-9)
                {
                    Parameter curveLength = host.get_Parameter(BuiltInParameter.CURVE_ELEM_LENGTH);
                    if (curveLength != null && curveLength.StorageType == StorageType.Double)
                    {
                        lengthFeet = curveLength.AsDouble();
                    }
                }
                if (lengthFeet <= 1e-9)
                {
                    Parameter instanceLength = host.get_Parameter(BuiltInParameter.INSTANCE_LENGTH_PARAM);
                    if (instanceLength != null && instanceLength.StorageType == StorageType.Double)
                    {
                        lengthFeet = instanceLength.AsDouble();
                    }
                }
                if (lengthFeet > 1e-9)
                {
                    lengthsMm.Add(lengthFeet * 304.8);
                }
            }

            return lengthsMm;
        }

        private sealed class BeamSupportPreviewMarker
        {
            public double StationMm { get; set; }
            public double WidthMm { get; set; }
            public string KindKey { get; set; } = "";
        }

        private static bool TryGetPrimaryBeamHostSectionMm(
            Document doc,
            IEnumerable<ElementId> hostIds,
            out double widthMm,
            out double depthMm)
        {
            widthMm = 0.0;
            depthMm = 0.0;

            Element primaryHost = ResolvePrimaryBeamPreviewHost(doc, hostIds);
            if (primaryHost == null)
            {
                return false;
            }

            if (!TryGetFoundationRebarHostFrameAndBounds(primaryHost, out Transform _, out XYZ localMin, out XYZ localMax, out string _))
            {
                return false;
            }

            double widthFt = Math.Abs(localMax.Y - localMin.Y);
            double depthFt = Math.Abs(localMax.Z - localMin.Z);
            if (widthFt <= 1e-6 || depthFt <= 1e-6)
            {
                return false;
            }

            widthMm = widthFt * 304.8;
            depthMm = depthFt * 304.8;
            return true;
        }

        private static Element ResolvePrimaryBeamPreviewHost(Document doc, IEnumerable<ElementId> hostIds)
        {
            if (doc == null)
            {
                return null;
            }

            return (hostIds ?? Enumerable.Empty<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => doc.GetElement(g.First()))
                .Where(IsBeamRebarHostElement)
                .OrderByDescending(e =>
                {
                    if (TryGetBeamHostEndpoints(e, out XYZ _, out XYZ _, out double lengthFt))
                    {
                        return lengthFt;
                    }

                    return 0.0;
                })
                .FirstOrDefault();
        }

        private static List<double> DetectBeamHostSupportStationsMm(Document doc, IEnumerable<ElementId> hostIds)
        {
            return DetectBeamSupportPreviewMarkersMm(doc, hostIds)
                .Select(x => x.StationMm)
                .ToList();
        }

        private static List<double> DetectBeamSupportStationsFromReferencesMm(
            Document doc,
            IEnumerable<ElementId> hostIds,
            IEnumerable<ElementId> supportIds)
        {
            return DetectBeamSupportPreviewMarkersMm(doc, hostIds, supportIds)
                .Select(x => x.StationMm)
                .ToList();
        }

        private static List<BeamSupportPreviewMarker> DetectBeamSupportPreviewMarkersMm(
            Document doc,
            IEnumerable<ElementId> hostIds,
            IEnumerable<ElementId> explicitSupportIds = null)
        {
            var result = new List<BeamSupportPreviewMarker>();
            if (doc == null)
            {
                return result;
            }

            List<ElementId> normalizedHostIds = (hostIds ?? Enumerable.Empty<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();
            if (normalizedHostIds.Count == 0)
            {
                return result;
            }

            Element primaryHost = ResolvePrimaryBeamPreviewHost(doc, normalizedHostIds);
            if (primaryHost == null ||
                !TryGetBeamHostEndpoints(primaryHost, out XYZ end0, out XYZ end1, out double hostLengthFt) ||
                hostLengthFt <= 1e-6)
            {
                return result;
            }

            XYZ axisDir = (end1 - end0).Normalize();
            var hostIdSet = new HashSet<long>(normalizedHostIds.Select(id => id.Value));
            List<Element> candidates = CollectBeamSupportPreviewCandidates(doc, primaryHost, hostIdSet, explicitSupportIds);
            if (candidates.Count == 0)
            {
                return result;
            }

            double lateralToleranceFt = 2.0;
            double endToleranceFt = 1.0;
            double dedupTolMm = Math.Max(120.0, hostLengthFt * 304.8 * 0.01);
            double maxWidthMm = Math.Max(1200.0, hostLengthFt * 304.8 * 0.25);

            foreach (Element candidate in candidates)
            {
                if (candidate == null)
                {
                    continue;
                }

                XYZ anchor = GetElementAnchorPoint(candidate);
                if (anchor == null)
                {
                    continue;
                }

                if (!TryProjectPointToBeamAxisPlan(end0, axisDir, anchor, out double stationFt, out double lateralDistanceFt))
                {
                    continue;
                }
                if (stationFt < -endToleranceFt || stationFt > (hostLengthFt + endToleranceFt))
                {
                    continue;
                }
                if (lateralDistanceFt > lateralToleranceFt)
                {
                    continue;
                }

                double stationMm = Math.Max(0.0, Math.Min(hostLengthFt, stationFt)) * 304.8;
                if (double.IsNaN(stationMm) || double.IsInfinity(stationMm))
                {
                    continue;
                }

                double widthMm = 0.0;
                if (TryGetElementExtentAlongDirectionFt(candidate, axisDir, out double widthFt))
                {
                    widthMm = Math.Max(120.0, Math.Min(maxWidthMm, widthFt * 304.8));
                }

                result.Add(new BeamSupportPreviewMarker
                {
                    StationMm = stationMm,
                    WidthMm = widthMm,
                    KindKey = ResolveBeamSupportKindKey(candidate)
                });
            }

            if (result.Count == 0)
            {
                return result;
            }

            result = result
                .OrderBy(x => x.StationMm)
                .ToList();

            var deduped = new List<BeamSupportPreviewMarker>();
            foreach (BeamSupportPreviewMarker item in result)
            {
                if (deduped.Count == 0 || Math.Abs(item.StationMm - deduped[deduped.Count - 1].StationMm) > dedupTolMm)
                {
                    deduped.Add(new BeamSupportPreviewMarker
                    {
                        StationMm = item.StationMm,
                        WidthMm = item.WidthMm,
                        KindKey = item.KindKey
                    });
                    continue;
                }

                BeamSupportPreviewMarker merged = deduped[deduped.Count - 1];
                merged.StationMm = (merged.StationMm + item.StationMm) * 0.5;
                if (item.WidthMm > merged.WidthMm)
                {
                    merged.WidthMm = item.WidthMm;
                }
                if (string.IsNullOrWhiteSpace(merged.KindKey))
                {
                    merged.KindKey = item.KindKey;
                }
            }

            return deduped;
        }

        private static List<Element> CollectBeamSupportPreviewCandidates(
            Document doc,
            Element primaryHost,
            HashSet<long> hostIdSet,
            IEnumerable<ElementId> explicitSupportIds)
        {
            var candidates = new List<Element>();
            if (doc == null || primaryHost == null)
            {
                return candidates;
            }

            var seenIds = new HashSet<long>();
            foreach (ElementId supportId in (explicitSupportIds ?? Enumerable.Empty<ElementId>()))
            {
                if (supportId == null || supportId == ElementId.InvalidElementId)
                {
                    continue;
                }

                if (hostIdSet != null && hostIdSet.Contains(supportId.Value))
                {
                    continue;
                }

                if (!seenIds.Add(supportId.Value))
                {
                    continue;
                }

                Element support = doc.GetElement(supportId);
                if (support == null || !IsBeamSupportReferenceElement(support))
                {
                    continue;
                }

                candidates.Add(support);
            }

            if (candidates.Count > 0)
            {
                return candidates;
            }

            BoundingBoxXYZ hostBbox = null;
            try
            {
                hostBbox = primaryHost.get_BoundingBox(null);
            }
            catch
            {
                hostBbox = null;
            }

            if (hostBbox?.Min == null || hostBbox.Max == null)
            {
                return candidates;
            }

            var categoryFilter = new ElementMulticategoryFilter(new List<BuiltInCategory>
            {
                BuiltInCategory.OST_StructuralColumns,
                BuiltInCategory.OST_Walls,
                BuiltInCategory.OST_StructuralFoundation,
                BuiltInCategory.OST_StructuralFraming
            });

            XYZ pad = new XYZ(2.5, 2.5, 2.5);
            Outline search = new Outline(hostBbox.Min - pad, hostBbox.Max + pad);
            var collector = new FilteredElementCollector(doc)
                .WhereElementIsNotElementType()
                .WherePasses(categoryFilter)
                .WherePasses(new BoundingBoxIntersectsFilter(search));

            foreach (Element candidate in collector)
            {
                if (candidate == null || candidate.Id == null || candidate.Id == ElementId.InvalidElementId)
                {
                    continue;
                }

                if (hostIdSet != null && hostIdSet.Contains(candidate.Id.Value))
                {
                    continue;
                }

                if (!seenIds.Add(candidate.Id.Value))
                {
                    continue;
                }

                if (!IsBeamSupportReferenceElement(candidate))
                {
                    continue;
                }

                candidates.Add(candidate);
            }

            return candidates;
        }

        private static string ResolveBeamSupportKindKey(Element element)
        {
            long catId = element?.Category?.Id?.Value ?? 0;
            if (catId == (long)BuiltInCategory.OST_StructuralColumns) return "column";
            if (catId == (long)BuiltInCategory.OST_Walls) return "wall";
            if (catId == (long)BuiltInCategory.OST_StructuralFoundation) return "foundation";
            if (catId == (long)BuiltInCategory.OST_StructuralFraming) return "framing";
            return "other";
        }

        private static bool TryGetElementExtentAlongDirectionFt(Element element, XYZ direction, out double extentFt)
        {
            extentFt = 0.0;
            if (element == null || direction == null || direction.GetLength() <= 1e-6)
            {
                return false;
            }

            BoundingBoxXYZ bbox = null;
            try
            {
                bbox = element.get_BoundingBox(null);
            }
            catch
            {
                bbox = null;
            }

            if (bbox?.Min == null || bbox.Max == null)
            {
                return false;
            }

            XYZ dir = direction.Normalize();
            XYZ min = bbox.Min;
            XYZ max = bbox.Max;
            XYZ[] corners =
            {
                new XYZ(min.X, min.Y, min.Z),
                new XYZ(min.X, min.Y, max.Z),
                new XYZ(min.X, max.Y, min.Z),
                new XYZ(min.X, max.Y, max.Z),
                new XYZ(max.X, min.Y, min.Z),
                new XYZ(max.X, min.Y, max.Z),
                new XYZ(max.X, max.Y, min.Z),
                new XYZ(max.X, max.Y, max.Z)
            };

            bool hasProjection = false;
            double minProj = 0.0;
            double maxProj = 0.0;
            foreach (XYZ p in corners)
            {
                double proj = p.DotProduct(dir);
                if (double.IsNaN(proj) || double.IsInfinity(proj))
                {
                    continue;
                }

                if (!hasProjection)
                {
                    minProj = proj;
                    maxProj = proj;
                    hasProjection = true;
                    continue;
                }

                if (proj < minProj) minProj = proj;
                if (proj > maxProj) maxProj = proj;
            }

            if (!hasProjection)
            {
                return false;
            }

            extentFt = Math.Max(0.0, maxProj - minProj);
            return extentFt > 1e-6;
        }

        private sealed class BeamHostDetectedElementSummary
        {
            public int Total { get; set; }
            public int Columns { get; set; }
            public int Walls { get; set; }
            public int Framing { get; set; }
            public int Floors { get; set; }
            public int Foundations { get; set; }
            public int Stairs { get; set; }
            public int EndConnected { get; set; }
            public int SpanFraming { get; set; }
            public int StartConnections { get; set; }
            public int EndConnections { get; set; }
        }

        private static BeamHostDetectedElementSummary DetectBeamHostRelatedElementsSummary(Document doc, IEnumerable<ElementId> hostIds)
        {
            var summary = new BeamHostDetectedElementSummary();
            if (doc == null)
            {
                return summary;
            }

            List<ElementId> normalizedHostIds = (hostIds ?? Enumerable.Empty<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();
            if (normalizedHostIds.Count == 0)
            {
                return summary;
            }

            var hostIdSet = new HashSet<long>(normalizedHostIds.Select(id => id.Value));
            var categoryFilter = new ElementMulticategoryFilter(new List<BuiltInCategory>
            {
                BuiltInCategory.OST_StructuralColumns,
                BuiltInCategory.OST_Walls,
                BuiltInCategory.OST_StructuralFraming,
                BuiltInCategory.OST_Floors,
                BuiltInCategory.OST_StructuralFoundation,
                BuiltInCategory.OST_Stairs
            });

            var seenDetectedIds = new HashSet<long>();
            foreach (ElementId hostId in normalizedHostIds)
            {
                Element host = doc.GetElement(hostId);
                if (!IsBeamRebarHostElement(host))
                {
                    continue;
                }

                BoundingBoxXYZ hostBbox = null;
                try
                {
                    hostBbox = host.get_BoundingBox(null);
                }
                catch
                {
                    hostBbox = null;
                }
                if (hostBbox?.Min == null || hostBbox.Max == null)
                {
                    continue;
                }

                XYZ pad = new XYZ(1.5, 1.5, 1.5);
                Outline search = new Outline(hostBbox.Min - pad, hostBbox.Max + pad);
                var collector = new FilteredElementCollector(doc)
                    .WhereElementIsNotElementType()
                    .WherePasses(categoryFilter)
                    .WherePasses(new BoundingBoxIntersectsFilter(search));

                bool hasHostEndpoints = TryGetBeamHostEndpoints(host, out XYZ end0, out XYZ end1, out double hostLengthFt);
                double endpointTolerance = Math.Max(1.0, Math.Min(4.0, hostLengthFt * 0.10));

                foreach (Element candidate in collector)
                {
                    if (candidate == null ||
                        candidate.Id == null ||
                        candidate.Id == ElementId.InvalidElementId)
                    {
                        continue;
                    }

                    if (hostIdSet.Contains(candidate.Id.Value))
                    {
                        continue;
                    }

                    if (!seenDetectedIds.Add(candidate.Id.Value))
                    {
                        continue;
                    }

                    long catId = candidate.Category?.Id?.Value ?? 0;
                    summary.Total++;

                    if (catId == (long)BuiltInCategory.OST_StructuralColumns) summary.Columns++;
                    else if (catId == (long)BuiltInCategory.OST_Walls) summary.Walls++;
                    else if (catId == (long)BuiltInCategory.OST_StructuralFraming) summary.Framing++;
                    else if (catId == (long)BuiltInCategory.OST_Floors) summary.Floors++;
                    else if (catId == (long)BuiltInCategory.OST_StructuralFoundation) summary.Foundations++;
                    else if (catId == (long)BuiltInCategory.OST_Stairs) summary.Stairs++;

                    XYZ anchor = GetElementAnchorPoint(candidate);
                    if (hasHostEndpoints && anchor != null)
                    {
                        double d0 = anchor.DistanceTo(end0);
                        double d1 = anchor.DistanceTo(end1);
                        bool nearStart = d0 <= endpointTolerance;
                        bool nearEnd = d1 <= endpointTolerance;
                        bool nearAnyEnd = nearStart || nearEnd;
                        if (nearAnyEnd)
                        {
                            if (nearStart && (!nearEnd || d0 <= d1))
                            {
                                summary.StartConnections++;
                            }
                            if (nearEnd && (!nearStart || d1 <= d0))
                            {
                                summary.EndConnections++;
                            }
                            summary.EndConnected++;
                        }

                        if (!nearAnyEnd && catId == (long)BuiltInCategory.OST_StructuralFraming)
                        {
                            summary.SpanFraming++;
                        }
                    }
                    else if (catId == (long)BuiltInCategory.OST_StructuralFraming)
                    {
                        summary.SpanFraming++;
                    }
                }
            }

            return summary;
        }

        private static string BuildBeamHostDetectedSummaryText(BeamHostDetectedElementSummary summary)
        {
            if (summary == null || summary.Total <= 0)
            {
                return string.Empty;
            }

            var parts = new List<string>();
            if (summary.Columns > 0) parts.Add("Column " + summary.Columns);
            if (summary.Walls > 0) parts.Add("Wall " + summary.Walls);
            if (summary.Framing > 0) parts.Add("Framing " + summary.Framing);
            if (summary.Floors > 0) parts.Add("Floor " + summary.Floors);
            if (summary.Foundations > 0) parts.Add("Foundation " + summary.Foundations);
            if (summary.Stairs > 0) parts.Add("Stair " + summary.Stairs);
            if (summary.EndConnected > 0) parts.Add("End-connected " + summary.EndConnected);
            if (summary.SpanFraming > 0) parts.Add("Span framing " + summary.SpanFraming);

            string detail = parts.Count == 0 ? summary.Total.ToString(CultureInfo.InvariantCulture) : string.Join(", ", parts);
            return "Detected " + summary.Total.ToString(CultureInfo.InvariantCulture) + " [" + detail + "]";
        }

        private static bool TryGetBeamHostEndpoints(Element host, out XYZ end0, out XYZ end1, out double lengthFt)
        {
            end0 = null;
            end1 = null;
            lengthFt = 0.0;

            if (host?.Location is LocationCurve locationCurve && locationCurve.Curve != null)
            {
                Curve curve = locationCurve.Curve;
                end0 = curve.GetEndPoint(0);
                end1 = curve.GetEndPoint(1);
                if (end0 != null && end1 != null)
                {
                    lengthFt = end0.DistanceTo(end1);
                    return lengthFt > 1e-6;
                }
            }

            BoundingBoxXYZ bbox = null;
            try
            {
                bbox = host?.get_BoundingBox(null);
            }
            catch
            {
                bbox = null;
            }
            if (bbox?.Min == null || bbox.Max == null)
            {
                return false;
            }

            XYZ center = new XYZ(
                (bbox.Min.X + bbox.Max.X) * 0.5,
                (bbox.Min.Y + bbox.Max.Y) * 0.5,
                (bbox.Min.Z + bbox.Max.Z) * 0.5);
            XYZ axis = new XYZ(bbox.Max.X - bbox.Min.X, bbox.Max.Y - bbox.Min.Y, bbox.Max.Z - bbox.Min.Z);
            if (axis.GetLength() < 1e-6)
            {
                return false;
            }
            axis = axis.Normalize();
            double half = Math.Max(
                Math.Abs(bbox.Max.X - bbox.Min.X),
                Math.Max(Math.Abs(bbox.Max.Y - bbox.Min.Y), Math.Abs(bbox.Max.Z - bbox.Min.Z))) * 0.5;
            end0 = center - (axis * half);
            end1 = center + (axis * half);
            lengthFt = end0.DistanceTo(end1);
            return lengthFt > 1e-6;
        }

        private static XYZ GetElementAnchorPoint(Element element)
        {
            if (element == null)
            {
                return null;
            }

            if (element.Location is LocationPoint lp && lp.Point != null)
            {
                return lp.Point;
            }

            if (element.Location is LocationCurve lc && lc.Curve != null)
            {
                try
                {
                    return lc.Curve.Evaluate(0.5, true);
                }
                catch
                {
                }
            }

            BoundingBoxXYZ bbox = null;
            try
            {
                bbox = element.get_BoundingBox(null);
            }
            catch
            {
                bbox = null;
            }

            if (bbox?.Min != null && bbox.Max != null)
            {
                return new XYZ(
                    (bbox.Min.X + bbox.Max.X) * 0.5,
                    (bbox.Min.Y + bbox.Max.Y) * 0.5,
                    (bbox.Min.Z + bbox.Max.Z) * 0.5);
            }

            return null;
        }

        private static bool TryProjectPointToBeamAxisPlan(
            XYZ beamStart,
            XYZ beamAxisDirection,
            XYZ point,
            out double stationFt,
            out double lateralDistanceFt)
        {
            stationFt = 0.0;
            lateralDistanceFt = 0.0;
            if (beamStart == null || beamAxisDirection == null || point == null || beamAxisDirection.GetLength() <= 1e-6)
            {
                return false;
            }

            XYZ axisDir = beamAxisDirection.Normalize();
            XYZ relative = point - beamStart;
            stationFt = relative.DotProduct(axisDir);
            if (double.IsNaN(stationFt) || double.IsInfinity(stationFt))
            {
                return false;
            }

            XYZ projected = beamStart + (axisDir * stationFt);
            double dx = point.X - projected.X;
            double dy = point.Y - projected.Y;
            lateralDistanceFt = Math.Sqrt((dx * dx) + (dy * dy));
            if (double.IsNaN(lateralDistanceFt) || double.IsInfinity(lateralDistanceFt))
            {
                return false;
            }

            return true;
        }

        private void GenerateBeamRebar(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            if (!Request.BeamRebarUseNaviateDataModel || Request.BeamRebarNaviate == null)
            {
                _window?.ShowStatus("BEAM: request data is missing. Re-open the BEAM form and click Apply again.");
                return;
            }

            BeamNaviateRebarRequest nav = Request.BeamRebarNaviate;
            nav.DeleteExistingRebar = true; // Always regenerate from a clean host state.

            List<ElementId> requestedIds = (nav.HostElementIds ?? new List<ElementId>())
                .Concat(Request.BeamRebarHostElementIds ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();

            if (requestedIds.Count == 0)
            {
                _window?.ShowStatus("BEAM: select beam host(s) first.");
                return;
            }

            List<Element> targetHosts = requestedIds
                .Select(doc.GetElement)
                .Where(IsBeamRebarHostElement)
                .ToList();

            if (targetHosts.Count == 0)
            {
                _window?.ShowStatus("BEAM: selected hosts are no longer available or are not valid beam rebar hosts.");
                return;
            }

            if (nav.MainBars == null)
            {
                _window?.ShowStatus("BEAM: main bars request data is missing.");
                return;
            }

            if (!TryResolveWallNaviateBarType(doc, nav.MainBars.UpperBarTypeName, out RebarBarType upperBarType))
            {
                _window?.ShowStatus($"BEAM: cannot find upper bar type '{nav.MainBars.UpperBarTypeName}'.");
                return;
            }
            nav.MainBars.UpperBarTypeId = upperBarType.Id;
            nav.MainBars.UpperBarTypeName = upperBarType.Name;

            RebarBarType upperSecondLayerBarType = upperBarType;
            string upperSecondLayerTypeName = (nav.MainBars.UpperSecondLayerBarTypeName ?? string.Empty).Trim();
            if (!string.IsNullOrWhiteSpace(upperSecondLayerTypeName))
            {
                if (!TryResolveWallNaviateBarType(doc, upperSecondLayerTypeName, out upperSecondLayerBarType))
                {
                    _window?.ShowStatus($"BEAM: cannot find upper second-layer bar type '{upperSecondLayerTypeName}'.");
                    return;
                }
            }
            nav.MainBars.UpperSecondLayerBarTypeId = upperSecondLayerBarType.Id;
            nav.MainBars.UpperSecondLayerBarTypeName = upperSecondLayerBarType.Name;

            if (!TryResolveWallNaviateBarType(doc, nav.MainBars.LowerBarTypeName, out RebarBarType lowerBarType))
            {
                _window?.ShowStatus($"BEAM: cannot find lower bar type '{nav.MainBars.LowerBarTypeName}'.");
                return;
            }
            nav.MainBars.LowerBarTypeId = lowerBarType.Id;
            nav.MainBars.LowerBarTypeName = lowerBarType.Name;

            RebarBarType lowerSecondLayerBarType = lowerBarType;
            string lowerSecondLayerTypeName = (nav.MainBars.LowerSecondLayerBarTypeName ?? string.Empty).Trim();
            if (!string.IsNullOrWhiteSpace(lowerSecondLayerTypeName))
            {
                if (!TryResolveWallNaviateBarType(doc, lowerSecondLayerTypeName, out lowerSecondLayerBarType))
                {
                    _window?.ShowStatus($"BEAM: cannot find lower second-layer bar type '{lowerSecondLayerTypeName}'.");
                    return;
                }
            }
            nav.MainBars.LowerSecondLayerBarTypeId = lowerSecondLayerBarType.Id;
            nav.MainBars.LowerSecondLayerBarTypeName = lowerSecondLayerBarType.Name;

            RebarBarType sideBarType = null;
            if (nav.MainBars.CreateSideBars)
            {
                string sideTypeName = (nav.MainBars.SideBarTypeName ?? "").Trim();
                if (string.IsNullOrWhiteSpace(sideTypeName))
                {
                    sideBarType = lowerBarType;
                }
                else if (!TryResolveWallNaviateBarType(doc, sideTypeName, out sideBarType))
                {
                    _window?.ShowStatus($"BEAM: cannot find side bar type '{sideTypeName}'.");
                    return;
                }

                nav.MainBars.SideBarTypeId = sideBarType?.Id ?? ElementId.InvalidElementId;
            }

            RebarBarType stirrupBarType = null;
            if (nav.Stirrups?.IsEnabled == true)
            {
                if (!TryResolveWallNaviateBarType(doc, nav.Stirrups.BarTypeName, out stirrupBarType))
                {
                    _window?.ShowStatus($"BEAM: cannot find stirrup bar type '{nav.Stirrups.BarTypeName}'.");
                    return;
                }
                nav.Stirrups.BarTypeId = stirrupBarType.Id;
            }

            List<BeamNaviateAdditionalBarRequest> additionalBottomRows = BuildBeamAdditionalRows(
                nav.AdditionalBottomBarRows,
                nav.AdditionalBottomBars);
            List<BeamNaviateAdditionalBarRequest> additionalTopRows = BuildBeamAdditionalRows(
                nav.AdditionalTopBarRows,
                nav.AdditionalTopBars);

            nav.AdditionalBottomBarRows = additionalBottomRows;
            nav.AdditionalTopBarRows = additionalTopRows;
            nav.AdditionalBottomBars = additionalBottomRows.FirstOrDefault() ?? new BeamNaviateAdditionalBarRequest();
            nav.AdditionalTopBars = additionalTopRows.FirstOrDefault() ?? new BeamNaviateAdditionalBarRequest();

            Dictionary<string, RebarBarType> additionalBarTypesByName = new Dictionary<string, RebarBarType>(StringComparer.OrdinalIgnoreCase);
            if (!TryResolveBeamAdditionalBarRows(doc, additionalBottomRows, "additional bottom", additionalBarTypesByName))
            {
                return;
            }
            if (!TryResolveBeamAdditionalBarRows(doc, additionalTopRows, "additional top", additionalBarTypesByName))
            {
                return;
            }

            RebarBarType secondaryBarType = null;
            if (nav.SecondaryBeam?.IsEnabled == true)
            {
                if (!TryResolveWallNaviateBarType(doc, nav.SecondaryBeam.BarTypeName, out secondaryBarType))
                {
                    _window?.ShowStatus($"BEAM: cannot find secondary beam bar type '{nav.SecondaryBeam.BarTypeName}'.");
                    return;
                }
                nav.SecondaryBeam.BarTypeId = secondaryBarType.Id;
            }

            RebarBarType specialStirrupBarType = null;
            if (nav.SpecialStirrups?.IsEnabled == true)
            {
                if (!TryResolveWallNaviateBarType(doc, nav.SpecialStirrups.BarTypeName, out specialStirrupBarType))
                {
                    _window?.ShowStatus($"BEAM: cannot find special stirrup bar type '{nav.SpecialStirrups.BarTypeName}'.");
                    return;
                }
                nav.SpecialStirrups.BarTypeId = specialStirrupBarType.Id;
            }

            nav.HostElementIds = targetHosts
                .Select(x => x?.Id ?? ElementId.InvalidElementId)
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .ToList();
            Request.BeamRebarHostElementIds = nav.HostElementIds.ToList();

            int hostsSucceeded = 0;
            int hostsFailed = 0;
            int deletedExistingTotal = 0;
            int topMainCreatedTotal = 0;
            int topMainFailedTotal = 0;
            int bottomMainCreatedTotal = 0;
            int bottomMainFailedTotal = 0;
            int sideCreatedTotal = 0;
            int sideFailedTotal = 0;
            int stirrupCreatedTotal = 0;
            int stirrupFailedTotal = 0;
            int addBottomCreatedTotal = 0;
            int addBottomFailedTotal = 0;
            int addTopCreatedTotal = 0;
            int addTopFailedTotal = 0;
            int secondaryCreatedTotal = 0;
            int secondaryFailedTotal = 0;
            int specialCreatedTotal = 0;
            int specialFailedTotal = 0;
            string firstError = "";

            TransactionStatus commitStatus = TransactionStatus.Uninitialized;
            using (Transaction t = new Transaction(doc, "CamboBIM - Generate Beam Rebar"))
            {
                t.Start();

                foreach (Element host in targetHosts)
                {
                    if (host == null)
                    {
                        hostsFailed++;
                        continue;
                    }

                    if (!TryGenerateBeamRebarForHost(
                        doc,
                        host,
                        nav,
                        upperBarType,
                        upperSecondLayerBarType,
                        lowerBarType,
                        lowerSecondLayerBarType,
                        sideBarType,
                        stirrupBarType,
                        additionalBarTypesByName,
                        secondaryBarType,
                        specialStirrupBarType,
                        out BeamRebarHostGenerationStats stats,
                        out string error))
                    {
                        hostsFailed++;
                        if (string.IsNullOrWhiteSpace(firstError) && !string.IsNullOrWhiteSpace(error))
                        {
                            firstError = $"Host {host.Id.Value}: {error}";
                        }
                        continue;
                    }

                    hostsSucceeded++;
                    deletedExistingTotal += stats.DeletedExisting;
                    topMainCreatedTotal += stats.TopMainBarsCreated;
                    topMainFailedTotal += stats.TopMainBarsFailed;
                    bottomMainCreatedTotal += stats.BottomMainBarsCreated;
                    bottomMainFailedTotal += stats.BottomMainBarsFailed;
                    sideCreatedTotal += stats.SideBarsCreated;
                    sideFailedTotal += stats.SideBarsFailed;
                    stirrupCreatedTotal += stats.StirrupsCreated;
                    stirrupFailedTotal += stats.StirrupsFailed;
                    addBottomCreatedTotal += stats.AdditionalBottomBarsCreated;
                    addBottomFailedTotal += stats.AdditionalBottomBarsFailed;
                    addTopCreatedTotal += stats.AdditionalTopBarsCreated;
                    addTopFailedTotal += stats.AdditionalTopBarsFailed;
                    secondaryCreatedTotal += stats.SecondaryBarsCreated;
                    secondaryFailedTotal += stats.SecondaryBarsFailed;
                    specialCreatedTotal += stats.SpecialStirrupsCreated;
                    specialFailedTotal += stats.SpecialStirrupsFailed;
                }

                commitStatus = t.Commit();
            }

            if (commitStatus != TransactionStatus.Committed)
            {
                _window?.ShowStatus("BEAM: rebar generation was cancelled or failed to commit. Review Revit warnings/errors.");
                return;
            }

            string summary =
                $"BEAM: Generated on {hostsSucceeded}/{targetHosts.Count} host(s), deleted existing {deletedExistingTotal}. " +
                $"Main bars Top/Bottom {topMainCreatedTotal}/{bottomMainCreatedTotal} (failed {topMainFailedTotal}/{bottomMainFailedTotal}), " +
                $"Side {sideCreatedTotal} (failed {sideFailedTotal}), Stirrups {stirrupCreatedTotal} (failed {stirrupFailedTotal}), " +
                $"Additional B/T {addBottomCreatedTotal}/{addTopCreatedTotal} (failed {addBottomFailedTotal}/{addTopFailedTotal}), " +
                $"Secondary {secondaryCreatedTotal} (failed {secondaryFailedTotal}), Special stirrups {specialCreatedTotal} (failed {specialFailedTotal}).";
            if (!string.IsNullOrWhiteSpace(firstError))
            {
                summary += " " + firstError;
            }

            _window?.ShowStatus(summary);
        }

        private sealed class BeamRebarHostGenerationStats
        {
            public int DeletedExisting { get; set; }
            public int TopMainBarsCreated { get; set; }
            public int TopMainBarsFailed { get; set; }
            public int BottomMainBarsCreated { get; set; }
            public int BottomMainBarsFailed { get; set; }
            public int SideBarsCreated { get; set; }
            public int SideBarsFailed { get; set; }
            public int StirrupsCreated { get; set; }
            public int StirrupsFailed { get; set; }
            public int AdditionalBottomBarsCreated { get; set; }
            public int AdditionalBottomBarsFailed { get; set; }
            public int AdditionalTopBarsCreated { get; set; }
            public int AdditionalTopBarsFailed { get; set; }
            public int SecondaryBarsCreated { get; set; }
            public int SecondaryBarsFailed { get; set; }
            public int SpecialStirrupsCreated { get; set; }
            public int SpecialStirrupsFailed { get; set; }
        }

        private static List<BeamNaviateAdditionalBarRequest> BuildBeamAdditionalRows(
            IEnumerable<BeamNaviateAdditionalBarRequest> rows,
            BeamNaviateAdditionalBarRequest legacySingleRow)
        {
            List<BeamNaviateAdditionalBarRequest> normalizedRows = (rows ?? Enumerable.Empty<BeamNaviateAdditionalBarRequest>())
                .Where(r => r != null)
                .Select(CloneBeamAdditionalRow)
                .ToList();

            if (normalizedRows.Count == 0 &&
                legacySingleRow != null &&
                legacySingleRow.IsEnabled &&
                legacySingleRow.BarCount > 0 &&
                !string.IsNullOrWhiteSpace(legacySingleRow.BarTypeName))
            {
                normalizedRows.Add(CloneBeamAdditionalRow(legacySingleRow));
            }

            return normalizedRows;
        }

        private static BeamNaviateAdditionalBarRequest CloneBeamAdditionalRow(BeamNaviateAdditionalBarRequest source)
        {
            if (source == null)
            {
                return new BeamNaviateAdditionalBarRequest();
            }

            return new BeamNaviateAdditionalBarRequest
            {
                IsEnabled = source.IsEnabled,
                BarTypeId = source.BarTypeId ?? ElementId.InvalidElementId,
                BarTypeName = (source.BarTypeName ?? "").Trim(),
                BarCount = Math.Max(0, source.BarCount),
                LayerIndex = Math.Max(1, source.LayerIndex),
                StartGridIndex = Math.Max(0, source.StartGridIndex),
                EndGridIndex = Math.Max(0, source.EndGridIndex),
                StartLengthFt = IsFiniteNumber(source.StartLengthFt) ? source.StartLengthFt : 0.0,
                EndLengthFt = IsFiniteNumber(source.EndLengthFt) ? source.EndLengthFt : 0.0
            };
        }

        private static int ResolveBeamAdditionalGridMaxIndex(
            IEnumerable<BeamNaviateAdditionalBarRequest> bottomRows,
            IEnumerable<BeamNaviateAdditionalBarRequest> topRows)
        {
            int rowMax = (bottomRows ?? Enumerable.Empty<BeamNaviateAdditionalBarRequest>())
                .Concat(topRows ?? Enumerable.Empty<BeamNaviateAdditionalBarRequest>())
                .Where(r => r != null && r.IsEnabled && r.BarCount > 0)
                .Select(r => Math.Max(r.StartGridIndex, r.EndGridIndex))
                .DefaultIfEmpty(1)
                .Max();

            return Math.Max(1, rowMax);
        }

        private static bool TryResolveBeamAdditionalRowRangeFt(
            BeamNaviateAdditionalBarRequest row,
            double xMainStartFt,
            double xMainEndFt,
            int gridMaxIndex,
            IList<double> gridStationsFt,
            out double xRowStartFt,
            out double xRowEndFt)
        {
            xRowStartFt = 0.0;
            xRowEndFt = 0.0;

            if (row == null || xMainEndFt <= xMainStartFt + 1e-9)
            {
                return false;
            }

            bool useExplicitStations = gridStationsFt != null && gridStationsFt.Count >= 2;
            int safeGridMax = useExplicitStations
                ? Math.Max(1, gridStationsFt.Count - 1)
                : Math.Max(1, gridMaxIndex);
            int startGrid = Math.Max(0, Math.Min(safeGridMax, row.StartGridIndex));
            int endGrid = Math.Max(0, Math.Min(safeGridMax, row.EndGridIndex));

            double xStartGridFt;
            double xEndGridFt;
            if (useExplicitStations)
            {
                xStartGridFt = gridStationsFt[startGrid];
                xEndGridFt = gridStationsFt[endGrid];
            }
            else
            {
                double beamLengthFt = xMainEndFt - xMainStartFt;
                xStartGridFt = xMainStartFt + (beamLengthFt * ((double)startGrid / safeGridMax));
                xEndGridFt = xMainStartFt + (beamLengthFt * ((double)endGrid / safeGridMax));
            }
            double spanRefFt = Math.Max(0.0, Math.Abs(xEndGridFt - xStartGridFt));
            double leftRefFt = 0.0;
            double rightRefFt = 0.0;
            if (useExplicitStations)
            {
                if (startGrid > 0)
                {
                    leftRefFt = Math.Max(0.0, Math.Abs(xStartGridFt - gridStationsFt[startGrid - 1]));
                }
                if (startGrid < safeGridMax)
                {
                    rightRefFt = Math.Max(0.0, Math.Abs(gridStationsFt[startGrid + 1] - xStartGridFt));
                }
            }

            double startRefFt = startGrid == endGrid
                ? (leftRefFt > 1e-9 ? leftRefFt : Math.Max(spanRefFt, rightRefFt))
                : spanRefFt;
            double endRefFt = startGrid == endGrid
                ? (rightRefFt > 1e-9 ? rightRefFt : Math.Max(spanRefFt, leftRefFt))
                : spanRefFt;
            if (startRefFt <= 1e-9)
            {
                startRefFt = Math.Max(0.0, xMainEndFt - xMainStartFt);
            }
            if (endRefFt <= 1e-9)
            {
                endRefFt = Math.Max(0.0, xMainEndFt - xMainStartFt);
            }

            double startLenFt = ResolveBeamAdditionalLengthFt(row.StartLengthFt, startRefFt);
            double endLenFt = ResolveBeamAdditionalLengthFt(row.EndLengthFt, endRefFt);

            if (startGrid == endGrid)
            {
                xRowStartFt = xStartGridFt - startLenFt;
                xRowEndFt = xStartGridFt + endLenFt;
                if (useExplicitStations)
                {
                    if (startGrid == 0 && startLenFt <= 1e-9)
                    {
                        xRowStartFt = xMainStartFt;
                    }
                    if (startGrid == safeGridMax && endLenFt <= 1e-9)
                    {
                        xRowEndFt = xMainEndFt;
                    }
                }

                double requestedLengthFt = Math.Max(0.0, xRowEndFt - xRowStartFt);
                double availableLengthFt = Math.Max(0.0, xMainEndFt - xMainStartFt);
                if (requestedLengthFt > availableLengthFt + 1e-9)
                {
                    requestedLengthFt = availableLengthFt;
                    xRowStartFt = xStartGridFt - (requestedLengthFt * 0.5);
                    xRowEndFt = xStartGridFt + (requestedLengthFt * 0.5);
                }

                if (xRowStartFt < xMainStartFt)
                {
                    double shiftRightFt = xMainStartFt - xRowStartFt;
                    xRowStartFt += shiftRightFt;
                    xRowEndFt += shiftRightFt;
                }
                if (xRowEndFt > xMainEndFt)
                {
                    double shiftLeftFt = xRowEndFt - xMainEndFt;
                    xRowStartFt -= shiftLeftFt;
                    xRowEndFt -= shiftLeftFt;
                }
            }
            else if (xStartGridFt <= xEndGridFt)
            {
                xRowStartFt = xStartGridFt + startLenFt;
                xRowEndFt = xEndGridFt - endLenFt;
            }
            else
            {
                xRowStartFt = xEndGridFt + endLenFt;
                xRowEndFt = xStartGridFt - startLenFt;
            }

            xRowStartFt = Math.Max(xMainStartFt, Math.Min(xMainEndFt, xRowStartFt));
            xRowEndFt = Math.Max(xMainStartFt, Math.Min(xMainEndFt, xRowEndFt));

            if (xRowEndFt <= xRowStartFt + 1e-6)
            {
                if (startGrid != endGrid)
                {
                    double xLow = Math.Max(xMainStartFt, Math.Min(xMainEndFt, Math.Min(xStartGridFt, xEndGridFt)));
                    double xHigh = Math.Max(xMainStartFt, Math.Min(xMainEndFt, Math.Max(xStartGridFt, xEndGridFt)));
                    xRowStartFt = xLow;
                    xRowEndFt = xHigh;
                }
                else
                {
                    // Fallback to full main span when a single-grid row has zero usable range.
                    xRowStartFt = xMainStartFt;
                    xRowEndFt = xMainEndFt;
                }
            }

            return xRowEndFt > xRowStartFt + 1e-6;
        }

        private static double ResolveBeamAdditionalLengthFt(double encodedLengthFt, double referenceLengthFt)
        {
            if (!IsFiniteNumber(encodedLengthFt))
            {
                return 0.0;
            }

            // Ratio-of-span encoding from UI: -(ratio + 1.0), e.g. 0.3L => -1.3
            if (encodedLengthFt < -0.5)
            {
                double ratio = Math.Max(0.0, -encodedLengthFt - 1.0);
                return ratio * Math.Max(0.0, referenceLengthFt);
            }

            return Math.Max(0.0, encodedLengthFt);
        }

        private static List<(double StartFt, double EndFt)> ExpandBeamAdditionalBottomRowRangesFt(
            BeamNaviateAdditionalBarRequest row,
            double xMainStartFt,
            double xMainEndFt,
            int gridMaxIndex,
            IList<double> gridStationsFt)
        {
            var ranges = new List<(double StartFt, double EndFt)>();
            if (row == null)
            {
                return ranges;
            }

            bool useExplicitStations = gridStationsFt != null && gridStationsFt.Count >= 2;
            if (useExplicitStations && row.StartGridIndex == row.EndGridIndex)
            {
                int spanCount = Math.Max(1, gridStationsFt.Count - 1);
                for (int spanIndex = 0; spanIndex < spanCount; spanIndex++)
                {
                    BeamNaviateAdditionalBarRequest spanRow = CloneBeamAdditionalRow(row);
                    spanRow.StartGridIndex = spanIndex;
                    spanRow.EndGridIndex = spanIndex + 1;
                    if (TryResolveBeamAdditionalRowRangeFt(
                        spanRow,
                        xMainStartFt,
                        xMainEndFt,
                        gridMaxIndex,
                        gridStationsFt,
                        out double xSpanStartFt,
                        out double xSpanEndFt))
                    {
                        ranges.Add((xSpanStartFt, xSpanEndFt));
                    }
                }
            }

            if (ranges.Count == 0 &&
                TryResolveBeamAdditionalRowRangeFt(
                    row,
                    xMainStartFt,
                    xMainEndFt,
                    gridMaxIndex,
                    gridStationsFt,
                    out double xRowStartFt,
                    out double xRowEndFt))
            {
                ranges.Add((xRowStartFt, xRowEndFt));
            }

            return ranges;
        }

        private bool TryResolveBeamAdditionalBarRows(
            Document doc,
            IEnumerable<BeamNaviateAdditionalBarRequest> rows,
            string rowLabel,
            IDictionary<string, RebarBarType> resolvedTypesByName)
        {
            if (doc == null || resolvedTypesByName == null)
            {
                return false;
            }

            foreach (BeamNaviateAdditionalBarRequest row in rows ?? Enumerable.Empty<BeamNaviateAdditionalBarRequest>())
            {
                if (row == null || !row.IsEnabled || row.BarCount <= 0)
                {
                    continue;
                }

                string barTypeName = (row.BarTypeName ?? "").Trim();
                if (string.IsNullOrWhiteSpace(barTypeName))
                {
                    _window?.ShowStatus($"BEAM: missing {rowLabel} bar type.");
                    return false;
                }

                if (!resolvedTypesByName.TryGetValue(barTypeName, out RebarBarType resolvedType) || resolvedType == null)
                {
                    if (!TryResolveWallNaviateBarType(doc, barTypeName, out resolvedType))
                    {
                        _window?.ShowStatus($"BEAM: cannot find {rowLabel} bar type '{barTypeName}'.");
                        return false;
                    }

                    resolvedTypesByName[barTypeName] = resolvedType;
                }

                row.BarTypeId = resolvedType.Id;
            }

            return true;
        }

        private bool TryGenerateBeamRebarForHost(
            Document doc,
            Element host,
            BeamNaviateRebarRequest nav,
            RebarBarType upperBarType,
            RebarBarType upperSecondLayerBarType,
            RebarBarType lowerBarType,
            RebarBarType lowerSecondLayerBarType,
            RebarBarType sideBarType,
            RebarBarType stirrupBarType,
            IDictionary<string, RebarBarType> additionalBarTypesByName,
            RebarBarType secondaryBarType,
            RebarBarType specialStirrupBarType,
            out BeamRebarHostGenerationStats stats,
            out string error)
        {
            stats = new BeamRebarHostGenerationStats();
            error = "";

            if (doc == null || host == null || nav?.MainBars == null || upperBarType == null || lowerBarType == null)
            {
                error = "input data is not valid.";
                return false;
            }

            if (upperSecondLayerBarType == null)
            {
                upperSecondLayerBarType = upperBarType;
            }
            if (lowerSecondLayerBarType == null)
            {
                lowerSecondLayerBarType = lowerBarType;
            }

            if (!RebarHostData.IsValidHost(host))
            {
                error = "selected host cannot contain rebar.";
                return false;
            }

            if (!TryGetFoundationRebarHostFrameAndBounds(host, out Transform hostTransform, out XYZ localMin, out XYZ localMax, out string hostError))
            {
                error = hostError;
                return false;
            }

            double xMin = Math.Min(localMin.X, localMax.X);
            double xMax = Math.Max(localMin.X, localMax.X);
            double yMin = Math.Min(localMin.Y, localMax.Y);
            double yMax = Math.Max(localMin.Y, localMax.Y);
            double zMin = Math.Min(localMin.Z, localMax.Z);
            double zMax = Math.Max(localMin.Z, localMax.Z);

            double beamLengthFt = xMax - xMin;
            double beamWidthFt = yMax - yMin;
            double beamDepthFt = zMax - zMin;
            if (beamLengthFt <= 1e-6 || beamWidthFt <= 1e-6 || beamDepthFt <= 1e-6)
            {
                error = "beam geometry size is invalid.";
                return false;
            }

            if (nav.DeleteExistingRebar || nav.DeleteOnly)
            {
                stats.DeletedExisting = DeleteExistingColumnRebars(doc, host);
            }

            if (nav.DeleteOnly)
            {
                return true;
            }

            double upperDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(upperBarType));
            double upperSecondDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(upperSecondLayerBarType));
            double lowerDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(lowerBarType));
            double lowerSecondDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(lowerSecondLayerBarType));
            double sideDiaFt = sideBarType != null ? Math.Max(0.0, GetRebarBarDiameterSafe(sideBarType)) : Math.Max(upperDiaFt, lowerDiaFt);
            double stirrupDiaFt = stirrupBarType != null ? Math.Max(0.0, GetRebarBarDiameterSafe(stirrupBarType)) : Math.Max(upperDiaFt, lowerDiaFt);
            double maxTopDiaFt = Math.Max(upperDiaFt, upperSecondDiaFt);
            double maxBottomDiaFt = Math.Max(lowerDiaFt, lowerSecondDiaFt);
            double maxMainDiaFt = Math.Max(maxTopDiaFt, maxBottomDiaFt);

            double coverFt = nav.MainBars.CoverFt > 1e-9 ? nav.MainBars.CoverFt : MmToFeet(40.0);
            double minCenterlineCoverFt = Math.Max(MmToFeet(20.0), coverFt);
            double xCoverFt = Math.Max(MmToFeet(5.0), coverFt);
            double yCoverFt = Math.Max(minCenterlineCoverFt, (maxMainDiaFt * 0.5) + MmToFeet(10.0));
            double zCoverTopFt = Math.Max(minCenterlineCoverFt, (upperDiaFt * 0.5) + MmToFeet(10.0));
            double zCoverBottomFt = Math.Max(minCenterlineCoverFt, (lowerDiaFt * 0.5) + MmToFeet(10.0));

            double xStartFt = xMin + xCoverFt;
            double xEndFt = xMax - xCoverFt;
            double yLeftFt = yMin + yCoverFt;
            double yRightFt = yMax - yCoverFt;
            double zTopMainFt = zMax - zCoverTopFt;
            double zBottomMainFt = zMin + zCoverBottomFt;
            if (xEndFt <= xStartFt + 1e-6 || yRightFt <= yLeftFt + 1e-6 || zTopMainFt <= zBottomMainFt + 1e-6)
            {
                error = "beam cover is too large for this host size.";
                return false;
            }

            RebarHookType stirrupOpenHookType = FindClosestRebarHookTypeByAngle(doc, 135.0, RebarStyle.StirrupTie)
                ?? FindClosestRebarHookTypeByAngle(doc, 135.0, RebarStyle.Standard)
                ?? FindClosestRebarHookTypeByAngle(doc, 90.0, RebarStyle.StirrupTie);
            RebarHookType stirrupOpenHookType180 = FindClosestRebarHookTypeByAngle(doc, 180.0, RebarStyle.StirrupTie)
                ?? FindClosestRebarHookTypeByAngle(doc, 180.0, RebarStyle.Standard);
            RebarHookType specialStirrupStartHookType = stirrupOpenHookType180 ?? stirrupOpenHookType;
            RebarHookType specialStirrupEndHookType = stirrupOpenHookType ?? stirrupOpenHookType180;
            RebarShape beamStirrupPreferredShape = FindRebarShapeByCode(doc, "M_T1", RebarStyle.StirrupTie)
                ?? FindRebarShapeByCode(doc, "M_T1", RebarStyle.Standard);
            if ((nav.Stirrups?.IsEnabled == true || nav.SpecialStirrups?.IsEnabled == true) &&
                beamStirrupPreferredShape == null)
            {
                error = "required beam stirrup shape 'M_T1' was not found in the project.";
                return false;
            }

            List<double> supportStationsFt = ResolveBeamSupportStationsFtForHost(
                doc,
                host,
                hostTransform,
                Request.BeamRebarSupportElementIds,
                xStartFt,
                xEndFt,
                out List<double> supportWidthsFt);
            double xLongStartFt = xStartFt;
            double xLongEndFt = xEndFt;
            if (supportStationsFt.Count > 0)
            {
                int startIndex = -1;
                int endIndex = -1;
                double startBestDistanceFt = double.MaxValue;
                double endBestDistanceFt = double.MaxValue;
                double endSupportTolFt = MmToFeet(500.0);
                for (int i = 0; i < supportStationsFt.Count; i++)
                {
                    double station = supportStationsFt[i];
                    if (!IsFiniteNumber(station))
                    {
                        continue;
                    }

                    double dStart = Math.Abs(station - xStartFt);
                    if (dStart <= endSupportTolFt && dStart < startBestDistanceFt)
                    {
                        startBestDistanceFt = dStart;
                        startIndex = i;
                    }

                    double dEnd = Math.Abs(station - xEndFt);
                    if (dEnd <= endSupportTolFt && dEnd < endBestDistanceFt)
                    {
                        endBestDistanceFt = dEnd;
                        endIndex = i;
                    }
                }

                if (startIndex >= 0 && startIndex < supportWidthsFt.Count && supportWidthsFt[startIndex] > 1e-6)
                {
                    double leftSupportFaceFt = supportStationsFt[startIndex] - (supportWidthsFt[startIndex] * 0.5);
                    xLongStartFt = Math.Min(xLongStartFt, leftSupportFaceFt + coverFt);
                }
                if (endIndex >= 0 && endIndex < supportWidthsFt.Count && supportWidthsFt[endIndex] > 1e-6)
                {
                    double rightSupportFaceFt = supportStationsFt[endIndex] + (supportWidthsFt[endIndex] * 0.5);
                    xLongEndFt = Math.Max(xLongEndFt, rightSupportFaceFt - coverFt);
                }
            }

            if (xLongEndFt <= xLongStartFt + 1e-6)
            {
                xLongStartFt = xStartFt;
                xLongEndFt = xEndFt;
            }
            List<double> spanBoundaryStationsFt = BuildBeamSpanBoundaryStations(
                xStartFt,
                xEndFt,
                supportStationsFt);

            int topLayerCount = Math.Max(1, nav.MainBars.UpperLayerCount);
            int topBarsPerLayer = Math.Max(1, nav.MainBars.UpperBarsPerLayer);
            int topSecondBarsPerLayer = nav.MainBars.UpperSecondBarsPerLayer > 0
                ? Math.Max(1, nav.MainBars.UpperSecondBarsPerLayer)
                : topBarsPerLayer;
            int bottomLayerCount = Math.Max(1, nav.MainBars.LowerLayerCount);
            int bottomBarsPerLayer = Math.Max(1, nav.MainBars.LowerBarsPerLayer);
            int bottomSecondBarsPerLayer = nav.MainBars.LowerSecondBarsPerLayer > 0
                ? Math.Max(1, nav.MainBars.LowerSecondBarsPerLayer)
                : bottomBarsPerLayer;

            double clearFt = Math.Max(MmToFeet(20.0), maxMainDiaFt + MmToFeet(10.0));
            List<double> topLayerZs = BuildBeamLayerZPositions(zTopMainFt, zBottomMainFt, topLayerCount, fromTop: true, clearFt);
            List<double> bottomLayerZs = BuildBeamLayerZPositions(zTopMainFt, zBottomMainFt, bottomLayerCount, fromTop: false, clearFt);
            double topAcrossInsetFt = Math.Max(0.0, maxTopDiaFt * 2.0);
            double bottomAcrossInsetFt = Math.Max(0.0, maxBottomDiaFt * 2.0);
            List<double> acrossYPositionsTopFirstLayer = BuildBeamLongitudinalBarYPositions(yLeftFt, yRightFt, topBarsPerLayer, topAcrossInsetFt);
            List<double> acrossYPositionsTopSecondLayer = BuildBeamLongitudinalBarYPositions(yLeftFt, yRightFt, topSecondBarsPerLayer, topAcrossInsetFt);
            List<double> acrossYPositionsBottomFirstLayer = BuildBeamLongitudinalBarYPositions(yLeftFt, yRightFt, bottomBarsPerLayer, bottomAcrossInsetFt);
            List<double> acrossYPositionsBottomSecondLayer = BuildBeamLongitudinalBarYPositions(yLeftFt, yRightFt, bottomSecondBarsPerLayer, bottomAcrossInsetFt);

            bool autoSplit = nav.MainBars.AutoSplitMainBars;
            double maxBarLengthFt = nav.MainBars.MaxMainBarLengthFt > 1e-6 ? nav.MainBars.MaxMainBarLengthFt : MmToFeet(12000.0);
            maxBarLengthFt = Math.Min(maxBarLengthFt, MmToFeet(12000.0));
            double lapLengthFt = nav.MainBars.LapLengthFt > 1e-6
                ? nav.MainBars.LapLengthFt
                : Math.Max(MmToFeet(300.0), maxMainDiaFt * 40.0);

            for (int layerIndex = 0; layerIndex < topLayerZs.Count; layerIndex++)
            {
                double zFt = topLayerZs[layerIndex];
                RebarBarType topLayerBarType = layerIndex == 0 ? upperBarType : upperSecondLayerBarType;
                IList<double> acrossYPositionsTop = layerIndex == 0
                    ? acrossYPositionsTopFirstLayer
                    : acrossYPositionsTopSecondLayer;
                CreateBeamLongitudinalLayer(
                    doc,
                    host,
                    hostTransform,
                    topLayerBarType,
                    acrossYPositionsTop,
                    xLongStartFt,
                    xLongEndFt,
                    zFt,
                    startHookType: null,
                    endHookType: null,
                    autoSplit,
                    maxBarLengthFt,
                    lapLengthFt,
                    out int created,
                    out int failed);
                stats.TopMainBarsCreated += created;
                stats.TopMainBarsFailed += failed;
            }

            for (int layerIndex = 0; layerIndex < bottomLayerZs.Count; layerIndex++)
            {
                double zFt = bottomLayerZs[layerIndex];
                RebarBarType bottomLayerBarType = layerIndex == 0 ? lowerBarType : lowerSecondLayerBarType;
                IList<double> acrossYPositionsBottom = layerIndex == 0
                    ? acrossYPositionsBottomFirstLayer
                    : acrossYPositionsBottomSecondLayer;
                CreateBeamLongitudinalLayer(
                    doc,
                    host,
                    hostTransform,
                    bottomLayerBarType,
                    acrossYPositionsBottom,
                    xLongStartFt,
                    xLongEndFt,
                    zFt,
                    startHookType: null,
                    endHookType: null,
                    autoSplit,
                    maxBarLengthFt,
                    lapLengthFt,
                    out int created,
                    out int failed);
                stats.BottomMainBarsCreated += created;
                stats.BottomMainBarsFailed += failed;
            }

            if (nav.MainBars.CreateSideBars && sideBarType != null && nav.MainBars.SideBarsPerFace > 0)
            {
                double zSideTopFt = zTopMainFt - Math.Max(MmToFeet(5.0), upperDiaFt * 0.5);
                double zSideBottomFt = zBottomMainFt + Math.Max(MmToFeet(5.0), lowerDiaFt * 0.5);
                if (zSideTopFt <= zSideBottomFt + 1e-6)
                {
                    zSideTopFt = zTopMainFt;
                    zSideBottomFt = zBottomMainFt;
                }

                List<double> sideZPositions = BuildBeamLongitudinalBarYPositions(zSideBottomFt, zSideTopFt, Math.Max(1, nav.MainBars.SideBarsPerFace));
                double anchorFt = Math.Max(0.0, nav.MainBars.SideAnchorLengthFt);
                double sideXStartFt = Math.Max(xMin + Math.Max(MmToFeet(5.0), coverFt), xLongStartFt - anchorFt);
                double sideXEndFt = Math.Min(xMax - Math.Max(MmToFeet(5.0), coverFt), xLongEndFt + anchorFt);

                CreateWallBarsAtPositions(
                    doc,
                    host,
                    RebarStyle.Standard,
                    sideBarType,
                    startHookType: null,
                    endHookType: null,
                    NormalizeOrDefault(hostTransform.BasisZ, XYZ.BasisZ),
                    sideZPositions,
                    zFt => hostTransform.OfPoint(new XYZ(sideXStartFt, yLeftFt, zFt)),
                    zFt => hostTransform.OfPoint(new XYZ(sideXEndFt, yLeftFt, zFt)),
                    out int sideLeftCreated,
                    out int sideLeftFailed,
                    autoSplit,
                    maxBarLengthFt,
                    lapLengthFt,
                    preferredShape: null);

                CreateWallBarsAtPositions(
                    doc,
                    host,
                    RebarStyle.Standard,
                    sideBarType,
                    startHookType: null,
                    endHookType: null,
                    NormalizeOrDefault(hostTransform.BasisZ, XYZ.BasisZ),
                    sideZPositions,
                    zFt => hostTransform.OfPoint(new XYZ(sideXStartFt, yRightFt, zFt)),
                    zFt => hostTransform.OfPoint(new XYZ(sideXEndFt, yRightFt, zFt)),
                    out int sideRightCreated,
                    out int sideRightFailed,
                    autoSplit,
                    maxBarLengthFt,
                    lapLengthFt,
                    preferredShape: null);

                stats.SideBarsCreated += sideLeftCreated + sideRightCreated;
                stats.SideBarsFailed += sideLeftFailed + sideRightFailed;
            }

            var createdStirrupElementIds = new List<ElementId>();
            var regularStirrupXPositions = new List<double>();
            if (nav.Stirrups?.IsEnabled == true && stirrupBarType != null)
            {
                double yTie0Ft = yMin + Math.Max(minCenterlineCoverFt, (stirrupDiaFt * 0.5) + MmToFeet(8.0));
                double yTie1Ft = yMax - Math.Max(minCenterlineCoverFt, (stirrupDiaFt * 0.5) + MmToFeet(8.0));
                double zTie0Ft = zMin + Math.Max(minCenterlineCoverFt, (stirrupDiaFt * 0.5) + MmToFeet(8.0));
                double zTie1Ft = zMax - Math.Max(minCenterlineCoverFt, (stirrupDiaFt * 0.5) + MmToFeet(8.0));
                if (yTie1Ft > yTie0Ft + 1e-6 && zTie1Ft > zTie0Ft + 1e-6)
                {
                    List<double> stirrupXPositions = BuildBeamStirrupXPositionsWithSupports(
                        xStartFt,
                        xEndFt,
                        supportStationsFt,
                        nav.Stirrups.LayoutType,
                        nav.Stirrups.StartSpacingFt,
                        nav.Stirrups.MiddleSpacingFt,
                        nav.Stirrups.EndSpacingFt,
                        nav.Stirrups.StartZoneLengthFt,
                        nav.Stirrups.EndZoneLengthFt,
                        nav.Stirrups.SpanOverrides);
                    regularStirrupXPositions = stirrupXPositions
                        .Where(IsFiniteNumber)
                        .OrderBy(x => x)
                        .ToList();

                    CreateBeamStirrupsFromPositionsAsMaximumSpacingSets(
                        doc,
                        host,
                        hostTransform,
                        stirrupBarType,
                        beamStirrupPreferredShape,
                        stirrupXPositions,
                        yTie0Ft,
                        yTie1Ft,
                        zTie0Ft,
                        zTie1Ft,
                        closeLoop: true,
                        startHookType: null,
                        endHookType: null,
                        createdStirrupElementIds,
                        out int stirrupCreated,
                        out int stirrupFailed);
                    stats.StirrupsCreated += stirrupCreated;
                    stats.StirrupsFailed += stirrupFailed;
                }
            }

            List<BeamNaviateAdditionalBarRequest> additionalBottomRows = BuildBeamAdditionalRows(
                nav.AdditionalBottomBarRows,
                nav.AdditionalBottomBars);
            List<BeamNaviateAdditionalBarRequest> additionalTopRows = BuildBeamAdditionalRows(
                nav.AdditionalTopBarRows,
                nav.AdditionalTopBars);
            int additionalGridMaxIndex = ResolveBeamAdditionalGridMaxIndex(additionalBottomRows, additionalTopRows);
            int supportRefsGridMax = Math.Max(1, spanBoundaryStationsFt.Count - 1);
            int secondaryRefsGridMax = Math.Max(1, Request.BeamRebarSecondaryElementIds?.Count ?? 0);
            additionalGridMaxIndex = Math.Max(additionalGridMaxIndex, Math.Max(supportRefsGridMax, secondaryRefsGridMax));
            IList<double> spanGridStations = spanBoundaryStationsFt.Count > 2 ? spanBoundaryStationsFt : null;

            foreach (BeamNaviateAdditionalBarRequest row in additionalBottomRows
                .Where(r => r != null && r.IsEnabled && r.BarCount > 0))
            {
                string rowBarTypeName = (row.BarTypeName ?? "").Trim();
                if (string.IsNullOrWhiteSpace(rowBarTypeName) ||
                    additionalBarTypesByName == null ||
                    !additionalBarTypesByName.TryGetValue(rowBarTypeName, out RebarBarType addBottomBarType) ||
                    addBottomBarType == null)
                {
                    stats.AdditionalBottomBarsFailed += Math.Max(1, row.BarCount);
                    continue;
                }

                double rowDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(addBottomBarType));
                int rowLayerIndex = Math.Max(1, row.LayerIndex);
                double layerStepFt = Math.Max(MmToFeet(25.0), rowDiaFt + MmToFeet(10.0));
                double zBottomFt = zBottomMainFt + Math.Max(MmToFeet(20.0), lowerDiaFt) + ((rowLayerIndex - 1) * layerStepFt);
                List<(double StartFt, double EndFt)> rowRanges = ExpandBeamAdditionalBottomRowRangesFt(
                    row,
                    xLongStartFt,
                    xLongEndFt,
                    additionalGridMaxIndex,
                    spanGridStations);
                if (rowRanges.Count == 0)
                {
                    stats.AdditionalBottomBarsFailed += Math.Max(1, row.BarCount);
                    continue;
                }

                foreach ((double StartFt, double EndFt) range in rowRanges)
                {
                    CreateBeamAdditionalLongitudinalBars(
                        doc,
                        host,
                        hostTransform,
                        addBottomBarType,
                        row.BarCount,
                        range.StartFt,
                        range.EndFt,
                        0.0,
                        0.0,
                        zBottomFt,
                        yLeftFt,
                        yRightFt,
                        startHookType: null,
                        endHookType: null,
                        autoSplit,
                        maxBarLengthFt,
                        lapLengthFt,
                        out int addBottomCreated,
                        out int addBottomFailed);
                    stats.AdditionalBottomBarsCreated += addBottomCreated;
                    stats.AdditionalBottomBarsFailed += addBottomFailed;
                }
            }

            foreach (BeamNaviateAdditionalBarRequest row in additionalTopRows
                .Where(r => r != null && r.IsEnabled && r.BarCount > 0))
            {
                string rowBarTypeName = (row.BarTypeName ?? "").Trim();
                if (string.IsNullOrWhiteSpace(rowBarTypeName) ||
                    additionalBarTypesByName == null ||
                    !additionalBarTypesByName.TryGetValue(rowBarTypeName, out RebarBarType addTopBarType) ||
                    addTopBarType == null)
                {
                    stats.AdditionalTopBarsFailed += Math.Max(1, row.BarCount);
                    continue;
                }

                double rowDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(addTopBarType));
                int rowLayerIndex = Math.Max(1, row.LayerIndex);
                double layerStepFt = Math.Max(MmToFeet(25.0), rowDiaFt + MmToFeet(10.0));
                double zTopFt = zTopMainFt - Math.Max(MmToFeet(20.0), upperDiaFt) - ((rowLayerIndex - 1) * layerStepFt);
                if (!TryResolveBeamAdditionalRowRangeFt(
                    row,
                    xLongStartFt,
                    xLongEndFt,
                    additionalGridMaxIndex,
                    spanGridStations,
                    out double xRowStartFt,
                    out double xRowEndFt))
                {
                    stats.AdditionalTopBarsFailed += Math.Max(1, row.BarCount);
                    continue;
                }

                CreateBeamAdditionalLongitudinalBars(
                    doc,
                    host,
                    hostTransform,
                    addTopBarType,
                    row.BarCount,
                    xRowStartFt,
                    xRowEndFt,
                    0.0,
                    0.0,
                    zTopFt,
                    yLeftFt,
                    yRightFt,
                    startHookType: null,
                    endHookType: null,
                    autoSplit,
                    maxBarLengthFt,
                    lapLengthFt,
                    out int addTopCreated,
                    out int addTopFailed);
                stats.AdditionalTopBarsCreated += addTopCreated;
                stats.AdditionalTopBarsFailed += addTopFailed;
            }

            if (nav.SecondaryBeam?.IsEnabled == true && secondaryBarType != null && nav.SecondaryBeam.BarCount > 0)
            {
                double zSecondaryFt = (zBottomMainFt + zTopMainFt) * 0.5;
                CreateBeamAdditionalLongitudinalBars(
                    doc,
                    host,
                    hostTransform,
                    secondaryBarType,
                    nav.SecondaryBeam.BarCount,
                    xStartFt,
                    xEndFt,
                    nav.SecondaryBeam.StartLengthFt,
                    nav.SecondaryBeam.EndLengthFt,
                    zSecondaryFt,
                    yLeftFt,
                    yRightFt,
                    startHookType: null,
                    endHookType: null,
                    autoSplit,
                    maxBarLengthFt,
                    lapLengthFt,
                    out int secondaryCreated,
                    out int secondaryFailed);
                stats.SecondaryBarsCreated += secondaryCreated;
                stats.SecondaryBarsFailed += secondaryFailed;
            }

            if (nav.SpecialStirrups?.IsEnabled == true && (stirrupBarType != null || specialStirrupBarType != null))
            {
                RebarBarType effectiveSpecialStirrupBarType = stirrupBarType ?? specialStirrupBarType;
                double effectiveSpecialDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(effectiveSpecialStirrupBarType));
                double yTie0Ft = yMin + Math.Max(minCenterlineCoverFt, (effectiveSpecialDiaFt * 0.5) + MmToFeet(8.0));
                double yTie1Ft = yMax - Math.Max(minCenterlineCoverFt, (effectiveSpecialDiaFt * 0.5) + MmToFeet(8.0));
                double zTie0Ft = zMin + Math.Max(minCenterlineCoverFt, (effectiveSpecialDiaFt * 0.5) + MmToFeet(8.0));
                double zTie1Ft = zMax - Math.Max(minCenterlineCoverFt, (effectiveSpecialDiaFt * 0.5) + MmToFeet(8.0));
                if (yTie1Ft > yTie0Ft + 1e-6 && zTie1Ft > zTie0Ft + 1e-6)
                {
                    List<double> spanBoundariesFt = BuildBeamSpanBoundaryStations(xStartFt, xEndFt, supportStationsFt);
                    if (spanBoundariesFt.Count < 2)
                    {
                        spanBoundariesFt = new List<double> { Math.Min(xStartFt, xEndFt), Math.Max(xStartFt, xEndFt) };
                    }

                    List<BeamNaviateSpecialStirrupRowRequest> specialRows = (nav.SpecialStirrups.Rows ?? new List<BeamNaviateSpecialStirrupRowRequest>())
                        .Where(x => x != null)
                        .ToList();
                    if (specialRows.Count == 0)
                    {
                        specialRows.Add(new BeamNaviateSpecialStirrupRowRequest
                        {
                            SectionIndex = 1,
                            CageIndex = 1,
                            Mode = nav.SpecialStirrups.Mode ?? "Tie Stirrup",
                            SpacingFt = nav.SpecialStirrups.SpacingFt,
                            StartZoneLengthFt = nav.SpecialStirrups.ZoneLengthFt,
                            EndZoneLengthFt = nav.SpecialStirrups.ZoneLengthFt
                        });
                    }

                    specialRows = specialRows
                        .OrderBy(x => Math.Max(1, x.SectionIndex))
                        .ThenBy(x => Math.Max(1, x.CageIndex))
                        .ThenBy(x =>
                        {
                            string mode = (x.Mode ?? "").Trim();
                            bool isRect = mode.IndexOf("rect", StringComparison.OrdinalIgnoreCase) >= 0;
                            bool isTie = mode.IndexOf("tie", StringComparison.OrdinalIgnoreCase) >= 0;
                            return isRect ? 0 : (isTie ? 1 : 2);
                        })
                        .ToList();

                    List<BeamNaviateCustomLineTieSpec> customLineSpecs = (nav.SpecialStirrups.CustomLineTies ?? new List<BeamNaviateCustomLineTieSpec>())
                        .Where(x => x != null)
                        .ToList();
                    List<BeamNaviateCustomRectTieSpec> customRectSpecs = (nav.SpecialStirrups.CustomRectTies ?? new List<BeamNaviateCustomRectTieSpec>())
                        .Where(x => x != null)
                        .ToList();
                    bool hasCustomShapes = customLineSpecs.Count > 0 || customRectSpecs.Count > 0;
                    int spanCount = Math.Max(1, spanBoundariesFt.Count - 1);
                    List<double> specialReferenceXPositions = regularStirrupXPositions
                        .Where(IsFiniteNumber)
                        .OrderBy(x => x)
                        .ToList();
                    if (specialReferenceXPositions.Count == 0 && nav.Stirrups != null)
                    {
                        specialReferenceXPositions = BuildBeamStirrupXPositionsWithSupports(
                            xStartFt,
                            xEndFt,
                            supportStationsFt,
                            nav.Stirrups.LayoutType,
                            nav.Stirrups.StartSpacingFt,
                            nav.Stirrups.MiddleSpacingFt,
                            nav.Stirrups.EndSpacingFt,
                            nav.Stirrups.StartZoneLengthFt,
                            nav.Stirrups.EndZoneLengthFt,
                            nav.Stirrups.SpanOverrides)
                            .Where(IsFiniteNumber)
                            .OrderBy(x => x)
                            .ToList();
                    }
                    if (specialReferenceXPositions.Count == 0)
                    {
                        double fallbackSpacingFt = MmToFeet(150.0);
                        if (nav.Stirrups != null)
                        {
                            if (nav.Stirrups.MiddleSpacingFt > 1e-6) fallbackSpacingFt = nav.Stirrups.MiddleSpacingFt;
                            else if (nav.Stirrups.StartSpacingFt > 1e-6) fallbackSpacingFt = nav.Stirrups.StartSpacingFt;
                            else if (nav.Stirrups.EndSpacingFt > 1e-6) fallbackSpacingFt = nav.Stirrups.EndSpacingFt;
                        }

                        specialReferenceXPositions = BuildFoundationRebarPositionsBySpacing(
                            xStartFt,
                            xEndFt,
                            Math.Max(MmToFeet(60.0), fallbackSpacingFt))
                            .Where(IsFiniteNumber)
                            .OrderBy(x => x)
                            .ToList();
                    }

                    if (hasCustomShapes)
                    {
                        int acrossCount = Math.Max(
                            2,
                            Math.Max(
                                Math.Max(nav.MainBars.UpperBarsPerLayer, nav.MainBars.LowerBarsPerLayer),
                                Math.Max(
                                    nav.MainBars.UpperSecondBarsPerLayer > 0 ? nav.MainBars.UpperSecondBarsPerLayer : nav.MainBars.UpperBarsPerLayer,
                                    nav.MainBars.LowerSecondBarsPerLayer > 0 ? nav.MainBars.LowerSecondBarsPerLayer : nav.MainBars.LowerBarsPerLayer)));
                        int depthCount = Math.Max(2, (nav.MainBars.CreateSideBars ? nav.MainBars.SideBarsPerFace : 0) + 2);
                        List<double> yNodesFt = BuildColumnRebarLinearPositions(yTie0Ft, yTie1Ft, acrossCount).ToList();
                        List<double> zNodesFt = BuildColumnRebarLinearPositions(zTie0Ft, zTie1Ft, depthCount).ToList();
                        double lineTrimFt = Math.Max(MmToFeet(5.0), maxMainDiaFt * 0.8);

                        for (int sectionIndex = 1; sectionIndex <= spanCount; sectionIndex++)
                        {
                            List<BeamNaviateCustomLineTieSpec> sectionLineSpecs = customLineSpecs
                                .Where(x => Math.Max(1, x.SectionIndex) == sectionIndex)
                                .ToList();
                            List<BeamNaviateCustomRectTieSpec> sectionRectSpecs = customRectSpecs
                                .Where(x => Math.Max(1, x.SectionIndex) == sectionIndex)
                                .ToList();
                            if (sectionLineSpecs.Count == 0 && sectionRectSpecs.Count == 0)
                            {
                                continue;
                            }

                            int boundaryIndex = sectionIndex - 1;
                            double spanStartFt = spanBoundariesFt[Math.Max(0, Math.Min(boundaryIndex, spanBoundariesFt.Count - 2))];
                            double spanEndFt = spanBoundariesFt[Math.Max(1, Math.Min(boundaryIndex + 1, spanBoundariesFt.Count - 1))];
                            if (spanEndFt <= spanStartFt + 1e-6)
                            {
                                continue;
                            }

                            List<double> rowPositions = specialReferenceXPositions
                                .Where(x => x >= spanStartFt - MmToFeet(1.0) && x <= spanEndFt + MmToFeet(1.0))
                                .OrderBy(x => x)
                                .ToList();
                            if (rowPositions.Count == 0)
                            {
                                stats.SpecialStirrupsFailed++;
                                continue;
                            }

                            foreach (BeamNaviateCustomRectTieSpec rectSpec in sectionRectSpecs)
                            {
                                if (!TryResolveBeamNaviateCustomRectBoundsFt(
                                    rectSpec,
                                    yNodesFt,
                                    zNodesFt,
                                    out double rowY0Ft,
                                    out double rowY1Ft,
                                    out double rowZ0Ft,
                                    out double rowZ1Ft))
                                {
                                    stats.SpecialStirrupsFailed++;
                                    continue;
                                }

                                CreateBeamStirrupsFromPositionsAsMaximumSpacingSets(
                                    doc,
                                    host,
                                    hostTransform,
                                    effectiveSpecialStirrupBarType,
                                    beamStirrupPreferredShape,
                                    rowPositions,
                                    rowY0Ft,
                                    rowY1Ft,
                                    rowZ0Ft,
                                    rowZ1Ft,
                                    closeLoop: true,
                                    startHookType: specialStirrupStartHookType,
                                    endHookType: specialStirrupEndHookType,
                                    createdStirrupElementIds,
                                    out int rectCreated,
                                    out int rectFailed);
                                stats.SpecialStirrupsCreated += rectCreated;
                                stats.SpecialStirrupsFailed += rectFailed;
                            }

                            foreach (BeamNaviateCustomLineTieSpec lineSpec in sectionLineSpecs)
                            {
                                if (!TryResolveBeamNaviateCustomLineFt(
                                    lineSpec,
                                    yNodesFt,
                                    zNodesFt,
                                    lineTrimFt,
                                    out bool verticalLine,
                                    out double fixedCoordFt,
                                    out double rangeStartFt,
                                    out double rangeEndFt))
                                {
                                    stats.SpecialStirrupsFailed++;
                                    continue;
                                }

                                CreateBeamSpecialTieLinesFromPositionsAsMaximumSpacingSets(
                                    doc,
                                    host,
                                    hostTransform,
                                    effectiveSpecialStirrupBarType,
                                    rowPositions,
                                    fixedCoordFt,
                                    rangeStartFt,
                                    rangeEndFt,
                                    verticalLine,
                                    startHookType: specialStirrupStartHookType,
                                    endHookType: specialStirrupEndHookType,
                                    createdStirrupElementIds,
                                    out int tieCreated,
                                    out int tieFailed);
                                stats.SpecialStirrupsCreated += tieCreated;
                                stats.SpecialStirrupsFailed += tieFailed;
                            }
                        }
                    }
                    else
                    {
                        foreach (BeamNaviateSpecialStirrupRowRequest specialRow in specialRows)
                        {
                            int sectionIndex = Math.Max(1, specialRow.SectionIndex);
                            int cageIndex = Math.Max(1, specialRow.CageIndex);
                            sectionIndex = Math.Min(sectionIndex, spanCount);
                            int boundaryIndex = sectionIndex - 1;
                            double spanStartFt = spanBoundariesFt[Math.Max(0, Math.Min(boundaryIndex, spanBoundariesFt.Count - 2))];
                            double spanEndFt = spanBoundariesFt[Math.Max(1, Math.Min(boundaryIndex + 1, spanBoundariesFt.Count - 1))];
                            if (spanEndFt <= spanStartFt + 1e-6)
                            {
                                continue;
                            }

                            string specialModeText = (specialRow.Mode ?? nav.SpecialStirrups.Mode ?? "").Trim();
                            bool specialRectangular = specialModeText.IndexOf("rect", StringComparison.OrdinalIgnoreCase) >= 0;
                            bool specialTie = specialModeText.IndexOf("tie", StringComparison.OrdinalIgnoreCase) >= 0;
                            bool specialU = !specialRectangular && !specialTie;
                            bool closeLoop = specialRectangular || specialU;
                            RebarShape specialPreferredShape = specialRectangular ? beamStirrupPreferredShape : null;
                            int modeLane = specialRectangular ? 0 : (specialTie ? 1 : 2);

                            List<double> rowPositions = specialReferenceXPositions
                                .Where(x => x >= spanStartFt - MmToFeet(1.0) && x <= spanEndFt + MmToFeet(1.0))
                                .OrderBy(x => x)
                                .ToList();
                            if (rowPositions.Count == 0)
                            {
                                stats.SpecialStirrupsFailed++;
                                continue;
                            }

                            double modeInsetFt = modeLane * Math.Max(MmToFeet(16.0), effectiveSpecialDiaFt * 1.05);
                            double cageInsetFt = (cageIndex - 1) * Math.Max(MmToFeet(28.0), effectiveSpecialDiaFt * 2.30);
                            double totalInsetFt = modeInsetFt + cageInsetFt;
                            double rowY0Ft = yTie0Ft + totalInsetFt;
                            double rowY1Ft = yTie1Ft - totalInsetFt;
                            double rowZ0Ft = zTie0Ft + totalInsetFt;
                            double rowZ1Ft = zTie1Ft - totalInsetFt;
                            if (rowY1Ft <= rowY0Ft + MmToFeet(35.0) || rowZ1Ft <= rowZ0Ft + MmToFeet(35.0))
                            {
                                stats.SpecialStirrupsFailed++;
                                continue;
                            }

                            if (specialTie)
                            {
                                int acrossCount = Math.Max(
                                    2,
                                    Math.Max(
                                        Math.Max(nav.MainBars.UpperBarsPerLayer, nav.MainBars.LowerBarsPerLayer),
                                        Math.Max(
                                            nav.MainBars.UpperSecondBarsPerLayer > 0 ? nav.MainBars.UpperSecondBarsPerLayer : nav.MainBars.UpperBarsPerLayer,
                                            nav.MainBars.LowerSecondBarsPerLayer > 0 ? nav.MainBars.LowerSecondBarsPerLayer : nav.MainBars.LowerBarsPerLayer)));
                                int depthCount = Math.Max(2, nav.MainBars.SideBarsPerFace + 2);
                                List<double> yInternal = BuildColumnRebarLinearPositions(rowY0Ft, rowY1Ft, acrossCount)
                                    .Skip(1)
                                    .Take(Math.Max(0, acrossCount - 2))
                                    .ToList();
                                List<double> zInternal = BuildColumnRebarLinearPositions(rowZ0Ft, rowZ1Ft, depthCount)
                                    .Skip(1)
                                    .Take(Math.Max(0, depthCount - 2))
                                    .ToList();

                                if (yInternal.Count == 0 && zInternal.Count == 0)
                                {
                                    yInternal.Add((rowY0Ft + rowY1Ft) * 0.5);
                                }

                                if (yInternal.Count > 0)
                                {
                                    int yIdx = Math.Max(0, (cageIndex - 1) % Math.Max(1, yInternal.Count));
                                    double tieYFt = yInternal[yIdx];
                                    CreateBeamSpecialTieLinesFromPositionsAsMaximumSpacingSets(
                                        doc,
                                        host,
                                        hostTransform,
                                        effectiveSpecialStirrupBarType,
                                        rowPositions,
                                        tieYFt,
                                        rowZ0Ft,
                                        rowZ1Ft,
                                        verticalLine: true,
                                        startHookType: specialStirrupStartHookType,
                                        endHookType: specialStirrupEndHookType,
                                        createdStirrupElementIds,
                                        out int tieCreated,
                                        out int tieFailed);
                                    stats.SpecialStirrupsCreated += tieCreated;
                                    stats.SpecialStirrupsFailed += tieFailed;
                                }

                                if (zInternal.Count > 0)
                                {
                                    int zIdx = Math.Max(0, (cageIndex - 1) % Math.Max(1, zInternal.Count));
                                    double tieZFt = zInternal[zIdx];
                                    CreateBeamSpecialTieLinesFromPositionsAsMaximumSpacingSets(
                                        doc,
                                        host,
                                        hostTransform,
                                        effectiveSpecialStirrupBarType,
                                        rowPositions,
                                        tieZFt,
                                        rowY0Ft,
                                        rowY1Ft,
                                        verticalLine: false,
                                        startHookType: specialStirrupStartHookType,
                                        endHookType: specialStirrupEndHookType,
                                        createdStirrupElementIds,
                                        out int tieCreated,
                                        out int tieFailed);
                                    stats.SpecialStirrupsCreated += tieCreated;
                                    stats.SpecialStirrupsFailed += tieFailed;
                                }
                            }
                            else
                            {
                                CreateBeamStirrupsFromPositionsAsMaximumSpacingSets(
                                    doc,
                                    host,
                                    hostTransform,
                                    effectiveSpecialStirrupBarType,
                                    specialPreferredShape,
                                    rowPositions,
                                    rowY0Ft,
                                    rowY1Ft,
                                    rowZ0Ft,
                                    rowZ1Ft,
                                    closeLoop,
                                    startHookType: specialStirrupStartHookType,
                                    endHookType: specialStirrupEndHookType,
                                    createdStirrupElementIds,
                                    out int specialCreated,
                                    out int specialFailed);
                                stats.SpecialStirrupsCreated += specialCreated;
                                stats.SpecialStirrupsFailed += specialFailed;
                            }
                        }
                    }
                }
            }

            return true;
        }

        private static void TryAssignRebarPartitionByType(Rebar rebar, RebarBarType barType)
        {
            if (rebar == null || barType == null)
            {
                return;
            }

            string partitionName = (barType.Name ?? "").Trim();
            if (string.IsNullOrWhiteSpace(partitionName))
            {
                return;
            }

            try
            {
                Parameter partitionParam = rebar.get_Parameter(BuiltInParameter.NUMBER_PARTITION_PARAM);
                if (partitionParam != null &&
                    !partitionParam.IsReadOnly &&
                    partitionParam.StorageType == StorageType.String)
                {
                    partitionParam.Set(partitionName);
                }
            }
            catch
            {
                // Keep generation robust even when partition is unavailable in some templates.
            }
        }

        private static List<double> BuildBeamLayerZPositions(double zTopFt, double zBottomFt, int layerCount, bool fromTop, double minSpacingFt)
        {
            var result = new List<double>();
            layerCount = Math.Max(1, layerCount);

            double z0 = Math.Min(zBottomFt, zTopFt);
            double z1 = Math.Max(zBottomFt, zTopFt);
            if (z1 <= z0 + 1e-9)
            {
                result.Add((z0 + z1) * 0.5);
                return result;
            }

            if (layerCount == 1)
            {
                result.Add(fromTop ? z1 : z0);
                return result;
            }

            double spanFt = z1 - z0;
            double spacingFt = Math.Max(minSpacingFt, spanFt / (layerCount + 1));

            for (int i = 0; i < layerCount; i++)
            {
                double z = fromTop
                    ? z1 - (i * spacingFt)
                    : z0 + (i * spacingFt);
                if (z < z0) z = z0;
                if (z > z1) z = z1;
                result.Add(z);
            }

            return result;
        }

        private static List<double> BuildBeamLongitudinalBarYPositions(
            double yStartFt,
            double yEndFt,
            int barCount,
            double edgeInsetFt = 0.0)
        {
            barCount = Math.Max(1, barCount);
            double y0 = Math.Min(yStartFt, yEndFt);
            double y1 = Math.Max(yStartFt, yEndFt);
            if (barCount == 1 || y1 <= y0 + 1e-9)
            {
                return new List<double> { (y0 + y1) * 0.5 };
            }

            double insetFt = Math.Max(0.0, edgeInsetFt);
            double spanFt = y1 - y0;
            double maxInsetFt = Math.Max(0.0, (spanFt * 0.5) - MmToFeet(5.0));
            insetFt = Math.Min(insetFt, maxInsetFt);
            if (insetFt > 1e-9)
            {
                y0 += insetFt;
                y1 -= insetFt;
            }

            if (y1 <= y0 + 1e-9)
            {
                return new List<double> { (yStartFt + yEndFt) * 0.5 };
            }

            return BuildColumnRebarLinearPositions(y0, y1, barCount).ToList();
        }

        private static void CreateBeamLongitudinalLayer(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            IList<double> yPositions,
            double xStartFt,
            double xEndFt,
            double zFt,
            RebarHookType startHookType,
            RebarHookType endHookType,
            bool autoSplitEnabled,
            double maxSplitLengthFt,
            double splitLapLengthFt,
            out int createdBars,
            out int failedBars)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || hostTransform == null || barType == null || yPositions == null || yPositions.Count == 0)
            {
                failedBars = yPositions?.Count ?? 0;
                return;
            }

            var orderedY = yPositions
                .Where(IsFiniteNumber)
                .OrderBy(v => v)
                .ToList();
            if (orderedY.Count == 0)
            {
                return;
            }

            foreach (double yFt in orderedY)
            {
                XYZ p0 = hostTransform.OfPoint(new XYZ(xStartFt, yFt, zFt));
                XYZ p1 = hostTransform.OfPoint(new XYZ(xEndFt, yFt, zFt));

                CreateWallLinearRebarSetWithOptionalSplit(
                    doc,
                    host,
                    RebarStyle.Standard,
                    barType,
                    startHookType,
                    endHookType,
                    NormalizeOrDefault(hostTransform.BasisY, XYZ.BasisY),
                    p0,
                    p1,
                    1,
                    0.0,
                    out int lineCreated,
                    out int lineFailed,
                    autoSplitEnabled,
                    maxSplitLengthFt,
                    splitLapLengthFt,
                    preferredShape: null);
                createdBars += lineCreated;
                failedBars += lineFailed;
            }
        }

        private static List<double> BuildBeamStirrupXPositions(
            double xStartFt,
            double xEndFt,
            string layoutType,
            double startSpacingFt,
            double middleSpacingFt,
            double endSpacingFt,
            double startZoneLengthFt,
            double endZoneLengthFt)
        {
            var result = new List<double>();

            double x0 = Math.Min(xStartFt, xEndFt);
            double x1 = Math.Max(xStartFt, xEndFt);
            double lengthFt = x1 - x0;
            if (lengthFt <= 1e-6)
            {
                result.Add(x0);
                return result;
            }

            bool useUniform = (layoutType ?? "").IndexOf("uniform", StringComparison.OrdinalIgnoreCase) >= 0;
            if (useUniform)
            {
                result.AddRange(BuildFoundationRebarPositionsBySpacing(x0, x1, middleSpacingFt));
                return result.Distinct().OrderBy(x => x).ToList();
            }

            double s1 = Math.Max(MmToFeet(50.0), startSpacingFt > 1e-6 ? startSpacingFt : middleSpacingFt);
            double s2 = Math.Max(MmToFeet(50.0), middleSpacingFt > 1e-6 ? middleSpacingFt : s1);
            double s3 = Math.Max(MmToFeet(50.0), endSpacingFt > 1e-6 ? endSpacingFt : s1);

            double l1 = startZoneLengthFt > 1e-6 ? startZoneLengthFt : lengthFt * 0.25;
            double l3 = endZoneLengthFt > 1e-6 ? endZoneLengthFt : lengthFt * 0.25;
            l1 = Math.Max(MmToFeet(150.0), Math.Min(l1, lengthFt * 0.5));
            l3 = Math.Max(MmToFeet(150.0), Math.Min(l3, lengthFt * 0.5));
            if (l1 + l3 >= lengthFt - 1e-6)
            {
                double half = lengthFt * 0.5;
                l1 = half;
                l3 = lengthFt - l1;
            }

            double xa0 = x0;
            double xa1 = Math.Min(x1, x0 + l1);
            double xb0 = xa1;
            double xb1 = Math.Max(xb0, x1 - l3);
            double xc0 = xb1;
            double xc1 = x1;

            result.AddRange(BuildFoundationRebarPositionsBySpacing(xa0, xa1, s1));
            result.AddRange(BuildFoundationRebarPositionsBySpacing(xb0, xb1, s2));
            result.AddRange(BuildFoundationRebarPositionsBySpacing(xc0, xc1, s3));

            if (result.Count == 0)
            {
                result.Add(x0);
                result.Add(x1);
            }

            return result
                .Distinct()
                .OrderBy(x => x)
                .ToList();
        }

        private static List<double> BuildBeamStirrupXPositionsWithSupports(
            double xStartFt,
            double xEndFt,
            IEnumerable<double> supportStationsFt,
            string layoutType,
            double startSpacingFt,
            double middleSpacingFt,
            double endSpacingFt,
            double startZoneLengthFt,
            double endZoneLengthFt,
            IEnumerable<BeamNaviateStirrupSpanOverrideRequest> spanOverrides)
        {
            List<double> boundaries = BuildBeamSpanBoundaryStations(xStartFt, xEndFt, supportStationsFt);
            if (boundaries.Count <= 2)
            {
                BeamNaviateStirrupSpanOverrideRequest single = spanOverrides?
                    .Where(x => x != null && x.SpanIndex == 0)
                    .OrderBy(x => x.SpanIndex)
                    .FirstOrDefault();
                if (single != null)
                {
                    if (single.StartSpacingFt > 1e-6) startSpacingFt = single.StartSpacingFt;
                    if (single.MiddleSpacingFt > 1e-6) middleSpacingFt = single.MiddleSpacingFt;
                    if (single.EndSpacingFt > 1e-6) endSpacingFt = single.EndSpacingFt;
                    if (single.StartZoneLengthFt > 1e-6) startZoneLengthFt = single.StartZoneLengthFt;
                    if (single.EndZoneLengthFt > 1e-6) endZoneLengthFt = single.EndZoneLengthFt;
                }

                return BuildBeamStirrupXPositions(
                    xStartFt,
                    xEndFt,
                    layoutType,
                    startSpacingFt,
                    middleSpacingFt,
                    endSpacingFt,
                    startZoneLengthFt,
                    endZoneLengthFt);
            }

            string effectiveLayout = (layoutType ?? "").Trim();
            if (string.IsNullOrWhiteSpace(effectiveLayout) ||
                effectiveLayout.IndexOf("uniform", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                // For multi-span beams, force ACI-style 3-zone distribution per span.
                effectiveLayout = "L/4-L/2-L/4";
            }

            Dictionary<int, BeamNaviateStirrupSpanOverrideRequest> spanOverrideByIndex = (spanOverrides ?? Enumerable.Empty<BeamNaviateStirrupSpanOverrideRequest>())
                .Where(x => x != null && x.SpanIndex >= 0)
                .GroupBy(x => x.SpanIndex)
                .ToDictionary(g => g.Key, g => g.First());

            var result = new List<double>();
            for (int i = 0; i < boundaries.Count - 1; i++)
            {
                double x0 = boundaries[i];
                double x1 = boundaries[i + 1];
                double spanFt = x1 - x0;
                if (spanFt <= 1e-6)
                {
                    continue;
                }

                double spanS1Ft = startSpacingFt;
                double spanS2Ft = middleSpacingFt;
                double spanS3Ft = endSpacingFt;
                double spanL1Ft = startZoneLengthFt;
                double spanL3Ft = endZoneLengthFt;
                if (spanOverrideByIndex.TryGetValue(i, out BeamNaviateStirrupSpanOverrideRequest spanOverride) && spanOverride != null)
                {
                    if (spanOverride.StartSpacingFt > 1e-6) spanS1Ft = spanOverride.StartSpacingFt;
                    if (spanOverride.MiddleSpacingFt > 1e-6) spanS2Ft = spanOverride.MiddleSpacingFt;
                    if (spanOverride.EndSpacingFt > 1e-6) spanS3Ft = spanOverride.EndSpacingFt;
                    if (spanOverride.StartZoneLengthFt > 1e-6) spanL1Ft = spanOverride.StartZoneLengthFt;
                    if (spanOverride.EndZoneLengthFt > 1e-6) spanL3Ft = spanOverride.EndZoneLengthFt;
                }

                // Support-mode default = 0.3L / 0.4L / 0.3L for each span when no explicit zone lengths are set.
                double spanStartZoneFt = spanL1Ft > 1e-6 ? spanL1Ft : spanFt * 0.30;
                double spanEndZoneFt = spanL3Ft > 1e-6 ? spanL3Ft : spanFt * 0.30;
                result.AddRange(BuildBeamStirrupXPositions(
                    x0,
                    x1,
                    effectiveLayout,
                    spanS1Ft,
                    spanS2Ft,
                    spanS3Ft,
                    spanStartZoneFt,
                    spanEndZoneFt));
            }

            if (result.Count == 0)
            {
                result.Add(Math.Min(xStartFt, xEndFt));
                result.Add(Math.Max(xStartFt, xEndFt));
            }

            result = result
                .OrderBy(x => x)
                .ToList();

            var merged = new List<double>();
            double dedupTolFt = MmToFeet(5.0);
            foreach (double x in result)
            {
                if (merged.Count == 0 || Math.Abs(x - merged[merged.Count - 1]) > dedupTolFt)
                {
                    merged.Add(x);
                }
            }

            return merged;
        }

        private static List<double> BuildBeamSpecialStirrupXPositionsWithSupports(
            double xStartFt,
            double xEndFt,
            IEnumerable<double> supportStationsFt,
            double spacingFt,
            double zoneLengthFt)
        {
            double x0 = Math.Min(xStartFt, xEndFt);
            double x1 = Math.Max(xStartFt, xEndFt);
            if (x1 <= x0 + 1e-6)
            {
                return new List<double>();
            }

            spacingFt = Math.Max(MmToFeet(60.0), spacingFt);
            List<double> boundaries = BuildBeamSpanBoundaryStations(x0, x1, supportStationsFt);
            if (boundaries.Count < 2)
            {
                boundaries.Clear();
                boundaries.Add(x0);
                boundaries.Add(x1);
            }

            var result = new List<double>();
            for (int i = 0; i < boundaries.Count - 1; i++)
            {
                double spanStartFt = boundaries[i];
                double spanEndFt = boundaries[i + 1];
                double spanFt = spanEndFt - spanStartFt;
                if (spanFt <= 1e-6)
                {
                    continue;
                }

                double zoneFt = zoneLengthFt > 1e-6
                    ? zoneLengthFt
                    : Math.Max(MmToFeet(500.0), spanFt * 0.15);
                zoneFt = Math.Min(zoneFt, Math.Max(MmToFeet(150.0), spanFt * 0.45));

                double leftEndFt = Math.Min(spanEndFt, spanStartFt + zoneFt);
                double rightStartFt = Math.Max(spanStartFt, spanEndFt - zoneFt);

                result.AddRange(BuildFoundationRebarPositionsBySpacing(spanStartFt, leftEndFt, spacingFt));
                result.AddRange(BuildFoundationRebarPositionsBySpacing(rightStartFt, spanEndFt, spacingFt));
            }

            if (result.Count == 0)
            {
                double fallbackZoneFt = zoneLengthFt > 1e-6
                    ? zoneLengthFt
                    : Math.Max(MmToFeet(500.0), (x1 - x0) * 0.15);
                fallbackZoneFt = Math.Min(fallbackZoneFt, Math.Max(MmToFeet(150.0), (x1 - x0) * 0.45));
                result.AddRange(BuildFoundationRebarPositionsBySpacing(x0, Math.Min(x1, x0 + fallbackZoneFt), spacingFt));
                result.AddRange(BuildFoundationRebarPositionsBySpacing(Math.Max(x0, x1 - fallbackZoneFt), x1, spacingFt));
            }

            result = result
                .OrderBy(x => x)
                .ToList();

            var merged = new List<double>();
            double dedupTolFt = MmToFeet(5.0);
            foreach (double xFt in result)
            {
                if (merged.Count == 0 || Math.Abs(xFt - merged[merged.Count - 1]) > dedupTolFt)
                {
                    merged.Add(xFt);
                }
            }

            return merged;
        }

        private static List<double> BuildBeamSpanBoundaryStations(
            double xStartFt,
            double xEndFt,
            IEnumerable<double> supportStationsFt)
        {
            double x0 = Math.Min(xStartFt, xEndFt);
            double x1 = Math.Max(xStartFt, xEndFt);
            var boundaries = new List<double> { x0, x1 };

            double boundaryTolFt = MmToFeet(50.0);
            foreach (double station in supportStationsFt ?? Enumerable.Empty<double>())
            {
                if (!IsFiniteNumber(station))
                {
                    continue;
                }

                if (station <= x0 + boundaryTolFt || station >= x1 - boundaryTolFt)
                {
                    continue;
                }

                boundaries.Add(station);
            }

            boundaries = boundaries
                .OrderBy(x => x)
                .ToList();

            var merged = new List<double>();
            double mergeTolFt = MmToFeet(80.0);
            foreach (double x in boundaries)
            {
                if (merged.Count == 0 || Math.Abs(x - merged[merged.Count - 1]) > mergeTolFt)
                {
                    merged.Add(x);
                }
            }

            if (merged.Count < 2)
            {
                merged.Clear();
                merged.Add(x0);
                merged.Add(x1);
            }

            return merged;
        }

        private static List<double> ResolveBeamSupportStationsFtForHost(
            Document doc,
            Element host,
            Transform hostTransform,
            IEnumerable<ElementId> supportReferenceIds,
            double xMainStartFt,
            double xMainEndFt,
            out List<double> supportWidthsFt)
        {
            var result = new List<double>();
            supportWidthsFt = new List<double>();
            if (doc == null || host == null || hostTransform == null)
            {
                return result;
            }

            if (!TryGetBeamHostEndpoints(host, out XYZ end0, out XYZ end1, out double hostLengthFt) || hostLengthFt <= 1e-6)
            {
                return result;
            }

            Transform inverse = hostTransform.Inverse;
            double localHostStartX = inverse.OfPoint(end0).X;
            double localHostEndX = inverse.OfPoint(end1).X;
            if (!IsFiniteNumber(localHostStartX) || !IsFiniteNumber(localHostEndX) || Math.Abs(localHostEndX - localHostStartX) <= 1e-6)
            {
                localHostStartX = Math.Min(xMainStartFt, xMainEndFt);
                localHostEndX = Math.Max(xMainStartFt, xMainEndFt);
            }

            double stationTolFt = MmToFeet(400.0);
            var rawProfiles = new List<(double StationXFt, double WidthFt)>();
            void AddStationByAxisDistance(double stationFt, double widthFt)
            {
                if (!IsFiniteNumber(stationFt))
                {
                    return;
                }

                if (stationFt < -stationTolFt || stationFt > hostLengthFt + stationTolFt)
                {
                    return;
                }

                double t = hostLengthFt <= 1e-9 ? 0.0 : stationFt / hostLengthFt;
                t = Math.Max(0.0, Math.Min(1.0, t));
                double x = localHostStartX + ((localHostEndX - localHostStartX) * t);
                if (IsFiniteNumber(x))
                {
                    rawProfiles.Add((x, Math.Max(0.0, widthFt)));
                }
            }

            List<BeamSupportPreviewMarker> markers = DetectBeamSupportPreviewMarkersMm(
                doc,
                new[] { host.Id },
                supportReferenceIds);
            foreach (BeamSupportPreviewMarker marker in markers)
            {
                if (marker == null)
                {
                    continue;
                }
                AddStationByAxisDistance(marker.StationMm / 304.8, marker.WidthMm / 304.8);
            }

            if (rawProfiles.Count == 0)
            {
                return result;
            }

            rawProfiles = rawProfiles
                .OrderBy(x => x.StationXFt)
                .ToList();
            var merged = new List<(double StationXFt, double WidthFt)>();
            double mergeTolFt = MmToFeet(80.0);
            foreach ((double StationXFt, double WidthFt) item in rawProfiles)
            {
                if (merged.Count == 0 || Math.Abs(item.StationXFt - merged[merged.Count - 1].StationXFt) > mergeTolFt)
                {
                    merged.Add(item);
                    continue;
                }

                (double StationXFt, double WidthFt) prev = merged[merged.Count - 1];
                double mergedStationFt = (prev.StationXFt + item.StationXFt) * 0.5;
                double mergedWidthFt = Math.Max(prev.WidthFt, item.WidthFt);
                merged[merged.Count - 1] = (mergedStationFt, mergedWidthFt);
            }

            foreach ((double StationXFt, double WidthFt) item in merged)
            {
                result.Add(item.StationXFt);
                supportWidthsFt.Add(item.WidthFt);
            }

            return result;
        }

        private static bool CreateBeamStirrupAtX(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            RebarShape preferredShape,
            double xFt,
            double y0Ft,
            double y1Ft,
            double z0Ft,
            double z1Ft,
            bool closeLoop,
            RebarHookType startHookType,
            RebarHookType endHookType,
            out ElementId createdRebarId)
        {
            createdRebarId = ElementId.InvalidElementId;

            if (doc == null || host == null || hostTransform == null || barType == null)
            {
                return false;
            }

            if (y1Ft <= y0Ft + 1e-6 || z1Ft <= z0Ft + 1e-6)
            {
                return false;
            }

            XYZ p00 = hostTransform.OfPoint(new XYZ(xFt, y0Ft, z0Ft));
            XYZ p01 = hostTransform.OfPoint(new XYZ(xFt, y0Ft, z1Ft));
            XYZ p11 = hostTransform.OfPoint(new XYZ(xFt, y1Ft, z1Ft));
            XYZ p10 = hostTransform.OfPoint(new XYZ(xFt, y1Ft, z0Ft));

            var curves = new List<Curve>
            {
                Line.CreateBound(p00, p01),
                Line.CreateBound(p01, p11),
                Line.CreateBound(p11, p10)
            };

            // Keep hooked stirrups as an open profile so start/end hooks are applied on different ends.
            bool useOpenProfileForHookedLoop = closeLoop && (startHookType != null || endHookType != null);
            if (closeLoop && !useOpenProfileForHookedLoop)
            {
                curves.Add(Line.CreateBound(p10, p00));
            }

            RebarHookOrientation startOrientation = RebarHookOrientation.Right;
            RebarHookOrientation endOrientation = useOpenProfileForHookedLoop
                ? RebarHookOrientation.Left
                : RebarHookOrientation.Right;

            Rebar rb = null;
            if (preferredShape != null)
            {
                try
                {
                    rb = Rebar.CreateFromCurvesAndShape(
                        doc,
                        preferredShape,
                        barType,
                        startHookType,
                        endHookType,
                        host,
                        NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX),
                        curves,
                        startOrientation,
                        endOrientation);
                }
                catch
                {
                    rb = null;
                }

                if (rb == null && (startHookType != null || endHookType != null))
                {
                    // Some projects have M_T1-like shapes that do not accept explicit hook assignment.
                    try
                    {
                        rb = Rebar.CreateFromCurvesAndShape(
                            doc,
                            preferredShape,
                            barType,
                            null,
                            null,
                            host,
                            NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX),
                            curves,
                            startOrientation,
                            endOrientation);
                    }
                    catch
                    {
                        rb = null;
                    }
                }
            }
            else
            {
                rb = CreateRebarFromCurvesPreferShape(
                    doc,
                    RebarStyle.StirrupTie,
                    barType,
                    preferredShape: null,
                    startHookType: startHookType,
                    endHookType: endHookType,
                    host: host,
                    normal: NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX),
                    curves: curves,
                    startOrientation: startOrientation,
                    endOrientation: endOrientation);

                if (rb == null && (startHookType != null || endHookType != null))
                {
                    rb = CreateRebarFromCurvesPreferShape(
                        doc,
                        RebarStyle.StirrupTie,
                        barType,
                        preferredShape: null,
                        startHookType: null,
                        endHookType: null,
                        host: host,
                        normal: NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX),
                        curves: curves,
                        startOrientation: startOrientation,
                        endOrientation: endOrientation);
                }
            }

            if (rb == null)
            {
                return false;
            }

            TryAssignRebarPartitionByType(rb, barType);
            createdRebarId = rb.Id;
            return true;
        }

        private static bool CreateBeamStirrupSetByMaximumSpacing(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            RebarShape preferredShape,
            double xStartFt,
            double xEndFt,
            double maxSpacingFt,
            double y0Ft,
            double y1Ft,
            double z0Ft,
            double z1Ft,
            bool closeLoop,
            RebarHookType startHookType,
            RebarHookType endHookType,
            int expectedBarCount,
            out int createdBars,
            out int failedBars,
            out ElementId createdRebarId)
        {
            createdBars = 0;
            failedBars = 0;
            createdRebarId = ElementId.InvalidElementId;

            if (doc == null || host == null || hostTransform == null || barType == null)
            {
                failedBars = Math.Max(1, expectedBarCount);
                return false;
            }

            double x0Ft = Math.Min(xStartFt, xEndFt);
            double x1Ft = Math.Max(xStartFt, xEndFt);
            int expected = Math.Max(1, expectedBarCount);
            if (!IsFiniteNumber(x0Ft) || !IsFiniteNumber(x1Ft))
            {
                failedBars = expected;
                return false;
            }

            if (!CreateBeamStirrupAtX(
                doc,
                host,
                hostTransform,
                barType,
                preferredShape,
                x0Ft,
                y0Ft,
                y1Ft,
                z0Ft,
                z1Ft,
                closeLoop,
                startHookType,
                endHookType,
                out createdRebarId))
            {
                failedBars = expected;
                return false;
            }

            createdBars = 1;
            if (expected <= 1 || x1Ft <= x0Ft + 1e-6)
            {
                return true;
            }

            Rebar seedRebar = doc.GetElement(createdRebarId) as Rebar;
            if (seedRebar == null)
            {
                failedBars = expected - 1;
                return true;
            }

            double safeSpacingFt = Math.Max(MmToFeet(50.0), Math.Abs(maxSpacingFt));
            double arrayLengthFt = Math.Max(0.0, x1Ft - x0Ft);
            bool layoutApplied = false;
            try
            {
                RebarShapeDrivenAccessor accessor = seedRebar.GetShapeDrivenAccessor();
                if (accessor != null)
                {
                    accessor.SetLayoutAsMaximumSpacing(
                        safeSpacingFt,
                        arrayLengthFt,
                        true,
                        true,
                        true);
                    layoutApplied = true;
                }
            }
            catch
            {
                layoutApplied = false;
            }

            if (layoutApplied)
            {
                createdBars = expected;
                return true;
            }

            failedBars = expected - 1;
            return true;
        }

        private static void CreateBeamStirrupsFromPositionsAsMaximumSpacingSets(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            RebarShape preferredShape,
            IEnumerable<double> xPositionsFt,
            double y0Ft,
            double y1Ft,
            double z0Ft,
            double z1Ft,
            bool closeLoop,
            RebarHookType startHookType,
            RebarHookType endHookType,
            IList<ElementId> createdRebarIds,
            out int createdBars,
            out int failedBars)
        {
            createdBars = 0;
            failedBars = 0;

            List<double> ordered = (xPositionsFt ?? Enumerable.Empty<double>())
                .Where(IsFiniteNumber)
                .OrderBy(x => x)
                .ToList();
            if (ordered.Count == 0)
            {
                return;
            }

            var deduped = new List<double>();
            double dedupTolFt = MmToFeet(0.5);
            foreach (double xFt in ordered)
            {
                if (deduped.Count == 0 || Math.Abs(xFt - deduped[deduped.Count - 1]) > dedupTolFt)
                {
                    deduped.Add(xFt);
                }
            }
            if (deduped.Count == 0)
            {
                return;
            }

            const double tiny = 1e-9;
            double spacingTolFt = MmToFeet(0.5);
            int i = 0;
            while (i < deduped.Count)
            {
                if (i == deduped.Count - 1)
                {
                    if (CreateBeamStirrupSetByMaximumSpacing(
                        doc,
                        host,
                        hostTransform,
                        barType,
                        preferredShape,
                        deduped[i],
                        deduped[i],
                        maxSpacingFt: MmToFeet(150.0),
                        y0Ft,
                        y1Ft,
                        z0Ft,
                        z1Ft,
                        closeLoop,
                        startHookType,
                        endHookType,
                        expectedBarCount: 1,
                        out int singleCreated,
                        out int singleFailed,
                        out ElementId singleId))
                    {
                        createdBars += singleCreated;
                        failedBars += singleFailed;
                        if (singleId != null && singleId != ElementId.InvalidElementId)
                        {
                            createdRebarIds?.Add(singleId);
                        }
                    }
                    else
                    {
                        failedBars += 1;
                    }

                    i++;
                    continue;
                }

                int runStart = i;
                double spacingFt = Math.Abs(deduped[i + 1] - deduped[i]);
                if (spacingFt <= tiny)
                {
                    spacingFt = MmToFeet(60.0);
                }

                i += 2;
                while (i < deduped.Count)
                {
                    double nextSpacingFt = Math.Abs(deduped[i] - deduped[i - 1]);
                    if (Math.Abs(nextSpacingFt - spacingFt) > spacingTolFt + tiny)
                    {
                        break;
                    }

                    i++;
                }

                int runEnd = i - 1;
                int runBarCount = Math.Max(1, runEnd - runStart + 1);
                if (CreateBeamStirrupSetByMaximumSpacing(
                    doc,
                    host,
                    hostTransform,
                    barType,
                    preferredShape,
                    deduped[runStart],
                    deduped[runEnd],
                    spacingFt,
                    y0Ft,
                    y1Ft,
                    z0Ft,
                    z1Ft,
                    closeLoop,
                    startHookType,
                    endHookType,
                    runBarCount,
                    out int runCreated,
                    out int runFailed,
                    out ElementId runId))
                {
                    createdBars += runCreated;
                    failedBars += runFailed;
                    if (runId != null && runId != ElementId.InvalidElementId)
                    {
                        createdRebarIds?.Add(runId);
                    }
                }
                else
                {
                    failedBars += runBarCount;
                }
            }
        }

        private static bool CreateBeamSpecialTieLineAtX(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            double xFt,
            double fixedCoordFt,
            double rangeStartFt,
            double rangeEndFt,
            bool verticalLine,
            RebarHookType startHookType,
            RebarHookType endHookType,
            out ElementId createdRebarId)
        {
            createdRebarId = ElementId.InvalidElementId;
            if (doc == null || host == null || hostTransform == null || barType == null)
            {
                return false;
            }

            double aFt = Math.Min(rangeStartFt, rangeEndFt);
            double bFt = Math.Max(rangeStartFt, rangeEndFt);
            if (bFt <= aFt + 1e-6)
            {
                return false;
            }

            XYZ p0 = verticalLine
                ? hostTransform.OfPoint(new XYZ(xFt, fixedCoordFt, aFt))
                : hostTransform.OfPoint(new XYZ(xFt, aFt, fixedCoordFt));
            XYZ p1 = verticalLine
                ? hostTransform.OfPoint(new XYZ(xFt, fixedCoordFt, bFt))
                : hostTransform.OfPoint(new XYZ(xFt, bFt, fixedCoordFt));

            if (p0.DistanceTo(p1) <= 1e-6)
            {
                return false;
            }

            Rebar rb = CreateRebarFromCurvesPreferShape(
                doc,
                RebarStyle.Standard,
                barType,
                preferredShape: null,
                startHookType: startHookType,
                endHookType: endHookType,
                host: host,
                normal: NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX),
                curves: new List<Curve> { Line.CreateBound(p0, p1) },
                startOrientation: RebarHookOrientation.Right,
                endOrientation: RebarHookOrientation.Right);
            if (rb == null && (startHookType != null || endHookType != null))
            {
                rb = CreateRebarFromCurvesPreferShape(
                    doc,
                    RebarStyle.Standard,
                    barType,
                    preferredShape: null,
                    startHookType: null,
                    endHookType: null,
                    host: host,
                    normal: NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX),
                    curves: new List<Curve> { Line.CreateBound(p0, p1) },
                    startOrientation: RebarHookOrientation.Right,
                    endOrientation: RebarHookOrientation.Right);
            }
            if (rb == null)
            {
                return false;
            }

            TryAssignRebarPartitionByType(rb, barType);
            createdRebarId = rb.Id;
            return true;
        }

        private static bool CreateBeamSpecialTieLineSetByMaximumSpacing(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            double xStartFt,
            double xEndFt,
            double maxSpacingFt,
            double fixedCoordFt,
            double rangeStartFt,
            double rangeEndFt,
            bool verticalLine,
            RebarHookType startHookType,
            RebarHookType endHookType,
            int expectedBarCount,
            out int createdBars,
            out int failedBars,
            out ElementId createdRebarId)
        {
            createdBars = 0;
            failedBars = 0;
            createdRebarId = ElementId.InvalidElementId;

            if (doc == null || host == null || hostTransform == null || barType == null)
            {
                failedBars = Math.Max(1, expectedBarCount);
                return false;
            }

            int expected = Math.Max(1, expectedBarCount);
            double x0Ft = Math.Min(xStartFt, xEndFt);
            double x1Ft = Math.Max(xStartFt, xEndFt);
            if (!CreateBeamSpecialTieLineAtX(
                doc,
                host,
                hostTransform,
                barType,
                x0Ft,
                fixedCoordFt,
                rangeStartFt,
                rangeEndFt,
                verticalLine,
                startHookType,
                endHookType,
                out createdRebarId))
            {
                failedBars = expected;
                return false;
            }

            createdBars = 1;
            if (expected <= 1 || x1Ft <= x0Ft + 1e-6)
            {
                return true;
            }

            Rebar seedRebar = doc.GetElement(createdRebarId) as Rebar;
            if (seedRebar == null)
            {
                failedBars = expected - 1;
                return true;
            }

            double safeSpacingFt = Math.Max(MmToFeet(50.0), Math.Abs(maxSpacingFt));
            double arrayLengthFt = Math.Max(0.0, x1Ft - x0Ft);
            bool layoutApplied = false;
            try
            {
                RebarShapeDrivenAccessor accessor = seedRebar.GetShapeDrivenAccessor();
                if (accessor != null)
                {
                    accessor.SetLayoutAsMaximumSpacing(
                        safeSpacingFt,
                        arrayLengthFt,
                        true,
                        true,
                        true);
                    layoutApplied = true;
                }
            }
            catch
            {
                layoutApplied = false;
            }

            if (layoutApplied)
            {
                createdBars = expected;
                return true;
            }

            failedBars = expected - 1;
            return true;
        }

        private static void CreateBeamSpecialTieLinesFromPositionsAsMaximumSpacingSets(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            IEnumerable<double> xPositionsFt,
            double fixedCoordFt,
            double rangeStartFt,
            double rangeEndFt,
            bool verticalLine,
            RebarHookType startHookType,
            RebarHookType endHookType,
            IList<ElementId> createdRebarIds,
            out int createdBars,
            out int failedBars)
        {
            createdBars = 0;
            failedBars = 0;

            List<double> ordered = (xPositionsFt ?? Enumerable.Empty<double>())
                .Where(IsFiniteNumber)
                .OrderBy(x => x)
                .ToList();
            if (ordered.Count == 0)
            {
                return;
            }

            var deduped = new List<double>();
            double dedupTolFt = MmToFeet(0.5);
            foreach (double xFt in ordered)
            {
                if (deduped.Count == 0 || Math.Abs(xFt - deduped[deduped.Count - 1]) > dedupTolFt)
                {
                    deduped.Add(xFt);
                }
            }
            if (deduped.Count == 0)
            {
                return;
            }

            const double tiny = 1e-9;
            double spacingTolFt = MmToFeet(0.5);
            int i = 0;
            while (i < deduped.Count)
            {
                if (i == deduped.Count - 1)
                {
                    if (CreateBeamSpecialTieLineSetByMaximumSpacing(
                        doc,
                        host,
                        hostTransform,
                        barType,
                        deduped[i],
                        deduped[i],
                        maxSpacingFt: MmToFeet(150.0),
                        fixedCoordFt,
                        rangeStartFt,
                        rangeEndFt,
                        verticalLine,
                        startHookType,
                        endHookType,
                        expectedBarCount: 1,
                        out int singleCreated,
                        out int singleFailed,
                        out ElementId singleId))
                    {
                        createdBars += singleCreated;
                        failedBars += singleFailed;
                        if (singleId != null && singleId != ElementId.InvalidElementId)
                        {
                            createdRebarIds?.Add(singleId);
                        }
                    }
                    else
                    {
                        failedBars += 1;
                    }

                    i++;
                    continue;
                }

                int runStart = i;
                double spacingFt = Math.Abs(deduped[i + 1] - deduped[i]);
                if (spacingFt <= tiny)
                {
                    spacingFt = MmToFeet(60.0);
                }

                i += 2;
                while (i < deduped.Count)
                {
                    double nextSpacingFt = Math.Abs(deduped[i] - deduped[i - 1]);
                    if (Math.Abs(nextSpacingFt - spacingFt) > spacingTolFt + tiny)
                    {
                        break;
                    }

                    i++;
                }

                int runEnd = i - 1;
                int runBarCount = Math.Max(1, runEnd - runStart + 1);
                if (CreateBeamSpecialTieLineSetByMaximumSpacing(
                    doc,
                    host,
                    hostTransform,
                    barType,
                    deduped[runStart],
                    deduped[runEnd],
                    spacingFt,
                    fixedCoordFt,
                    rangeStartFt,
                    rangeEndFt,
                    verticalLine,
                    startHookType,
                    endHookType,
                    runBarCount,
                    out int runCreated,
                    out int runFailed,
                    out ElementId runId))
                {
                    createdBars += runCreated;
                    failedBars += runFailed;
                    if (runId != null && runId != ElementId.InvalidElementId)
                    {
                        createdRebarIds?.Add(runId);
                    }
                }
                else
                {
                    failedBars += runBarCount;
                }
            }
        }

        private static BeamNaviateSpecialStirrupRowRequest ResolveBeamNaviateSpecialPrimaryRowForSection(
            BeamNaviateSpecialStirrupRequest request,
            IList<BeamNaviateSpecialStirrupRowRequest> rows,
            int sectionIndex)
        {
            int safeSection = Math.Max(1, sectionIndex);
            BeamNaviateSpecialStirrupRowRequest preferred = (rows ?? new List<BeamNaviateSpecialStirrupRowRequest>())
                .Where(x => x != null && Math.Max(1, x.SectionIndex) == safeSection)
                .OrderBy(x => Math.Max(1, x.CageIndex))
                .ThenBy(x =>
                {
                    string mode = (x.Mode ?? "").Trim();
                    bool isRect = mode.IndexOf("rect", StringComparison.OrdinalIgnoreCase) >= 0;
                    bool isTie = mode.IndexOf("tie", StringComparison.OrdinalIgnoreCase) >= 0;
                    return isRect ? 0 : (isTie ? 1 : 2);
                })
                .FirstOrDefault();

            if (preferred != null)
            {
                return preferred;
            }

            return new BeamNaviateSpecialStirrupRowRequest
            {
                SectionIndex = safeSection,
                CageIndex = 1,
                Mode = request?.Mode ?? "Tie Stirrup",
                SpacingFt = request?.SpacingFt ?? 0.0,
                StartZoneLengthFt = request?.ZoneLengthFt ?? 0.0,
                EndZoneLengthFt = request?.ZoneLengthFt ?? 0.0
            };
        }

        private static void ResolveBeamNaviateSpecialSpacingAndZonesForSpan(
            BeamNaviateSpecialStirrupRequest request,
            BeamNaviateSpecialStirrupRowRequest row,
            double spanFt,
            out double spacingFt,
            out double zoneLeftFt,
            out double zoneRightFt)
        {
            spacingFt = (row?.SpacingFt ?? 0.0) > 1e-6
                ? row.SpacingFt
                : (request?.SpacingFt ?? 0.0);
            if (spacingFt <= 1e-6)
            {
                spacingFt = MmToFeet(150.0);
            }
            spacingFt = Math.Max(MmToFeet(60.0), spacingFt);

            zoneLeftFt = Math.Max(0.0, row?.StartZoneLengthFt ?? 0.0);
            zoneRightFt = Math.Max(0.0, row?.EndZoneLengthFt ?? 0.0);
            if (zoneLeftFt <= 1e-6 && zoneRightFt <= 1e-6)
            {
                double fallbackZoneFt = (request?.ZoneLengthFt ?? 0.0) > 1e-6
                    ? request.ZoneLengthFt
                    : Math.Max(MmToFeet(500.0), Math.Max(0.0, spanFt) * 0.15);
                zoneLeftFt = fallbackZoneFt;
                zoneRightFt = fallbackZoneFt;
            }

            zoneLeftFt = Math.Min(zoneLeftFt, Math.Max(MmToFeet(100.0), Math.Max(0.0, spanFt) * 0.8));
            zoneRightFt = Math.Min(zoneRightFt, Math.Max(MmToFeet(100.0), Math.Max(0.0, spanFt) * 0.8));
        }

        private static List<double> BuildBeamNaviateSpecialXPositionsForZones(
            double spanStartFt,
            double spanEndFt,
            double spacingFt,
            double zoneLeftFt,
            double zoneRightFt)
        {
            var positions = new List<double>();
            if (spanEndFt <= spanStartFt + 1e-6)
            {
                return positions;
            }

            if (zoneLeftFt <= 1e-6 && zoneRightFt <= 1e-6)
            {
                positions.AddRange(BuildFoundationRebarPositionsBySpacing(spanStartFt, spanEndFt, spacingFt));
            }
            else
            {
                double leftZoneEndFt = Math.Min(spanEndFt, spanStartFt + Math.Max(0.0, zoneLeftFt));
                if (leftZoneEndFt > spanStartFt + 1e-6)
                {
                    positions.AddRange(BuildFoundationRebarPositionsBySpacing(spanStartFt, leftZoneEndFt, spacingFt));
                }

                double rightZoneStartFt = Math.Max(spanStartFt, spanEndFt - Math.Max(0.0, zoneRightFt));
                if (rightZoneStartFt < spanEndFt - 1e-6)
                {
                    positions.AddRange(BuildFoundationRebarPositionsBySpacing(rightZoneStartFt, spanEndFt, spacingFt));
                }

                if (positions.Count == 0)
                {
                    positions.AddRange(BuildFoundationRebarPositionsBySpacing(spanStartFt, spanEndFt, spacingFt));
                }
            }

            return positions
                .Distinct()
                .OrderBy(x => x)
                .ToList();
        }

        private static bool TryResolveBeamNaviateCustomRectBoundsFt(
            BeamNaviateCustomRectTieSpec spec,
            IList<double> yNodesFt,
            IList<double> zNodesFt,
            out double y0Ft,
            out double y1Ft,
            out double z0Ft,
            out double z1Ft)
        {
            y0Ft = 0.0;
            y1Ft = 0.0;
            z0Ft = 0.0;
            z1Ft = 0.0;
            if (spec == null || yNodesFt == null || zNodesFt == null || yNodesFt.Count < 2 || zNodesFt.Count < 2)
            {
                return false;
            }

            int xMax = yNodesFt.Count - 1;
            int yMax = zNodesFt.Count - 1;
            int ux0 = Math.Max(0, Math.Min(xMax, spec.X0GridIndex));
            int ux1 = Math.Max(0, Math.Min(xMax, spec.X1GridIndex));
            int uy0 = Math.Max(0, Math.Min(yMax, spec.Y0GridIndex));
            int uy1 = Math.Max(0, Math.Min(yMax, spec.Y1GridIndex));
            int mx0 = xMax - ux0;
            int mx1 = xMax - ux1;
            int my0 = yMax - uy0;
            int my1 = yMax - uy1;
            int x0 = Math.Min(mx0, mx1);
            int x1 = Math.Max(mx0, mx1);
            int y0 = Math.Min(my0, my1);
            int y1 = Math.Max(my0, my1);
            if (x1 <= x0 || y1 <= y0)
            {
                return false;
            }

            y0Ft = Math.Min(yNodesFt[x0], yNodesFt[x1]);
            y1Ft = Math.Max(yNodesFt[x0], yNodesFt[x1]);
            z0Ft = Math.Min(zNodesFt[y0], zNodesFt[y1]);
            z1Ft = Math.Max(zNodesFt[y0], zNodesFt[y1]);
            return y1Ft > y0Ft + 1e-6 && z1Ft > z0Ft + 1e-6;
        }

        private static bool TryResolveBeamNaviateCustomLineFt(
            BeamNaviateCustomLineTieSpec spec,
            IList<double> yNodesFt,
            IList<double> zNodesFt,
            double trimOffsetFt,
            out bool verticalLine,
            out double fixedCoordFt,
            out double rangeStartFt,
            out double rangeEndFt)
        {
            verticalLine = true;
            fixedCoordFt = 0.0;
            rangeStartFt = 0.0;
            rangeEndFt = 0.0;
            if (spec == null || yNodesFt == null || zNodesFt == null || yNodesFt.Count < 2 || zNodesFt.Count < 2)
            {
                return false;
            }

            int xMax = yNodesFt.Count - 1;
            int yMax = zNodesFt.Count - 1;
            int x0 = xMax - Math.Max(0, Math.Min(xMax, spec.X0GridIndex));
            int x1 = xMax - Math.Max(0, Math.Min(xMax, spec.X1GridIndex));
            int y0 = yMax - Math.Max(0, Math.Min(yMax, spec.Y0GridIndex));
            int y1 = yMax - Math.Max(0, Math.Min(yMax, spec.Y1GridIndex));
            int dx = Math.Abs(x1 - x0);
            int dy = Math.Abs(y1 - y0);
            if (dx == 0 && dy == 0)
            {
                return false;
            }

            if (dx > 0 && dy > 0)
            {
                if (dx >= dy)
                {
                    y1 = y0;
                }
                else
                {
                    x1 = x0;
                }
            }

            if (x0 == x1)
            {
                verticalLine = true;
                fixedCoordFt = yNodesFt[x0];
                rangeStartFt = Math.Min(zNodesFt[y0], zNodesFt[y1]);
                rangeEndFt = Math.Max(zNodesFt[y0], zNodesFt[y1]);
            }
            else if (y0 == y1)
            {
                verticalLine = false;
                fixedCoordFt = zNodesFt[y0];
                rangeStartFt = Math.Min(yNodesFt[x0], yNodesFt[x1]);
                rangeEndFt = Math.Max(yNodesFt[x0], yNodesFt[x1]);
            }
            else
            {
                return false;
            }

            double trimFt = Math.Max(0.0, trimOffsetFt);
            if (trimFt > 1e-9)
            {
                double maxTrimFt = Math.Max(0.0, ((rangeEndFt - rangeStartFt) * 0.5) - MmToFeet(5.0));
                trimFt = Math.Min(trimFt, maxTrimFt);
                if (trimFt > 1e-9)
                {
                    rangeStartFt += trimFt;
                    rangeEndFt -= trimFt;
                }
            }

            return rangeEndFt > rangeStartFt + 1e-6;
        }

        private static bool TryCreateBeamStirrupGroup(Document doc, Element host, IEnumerable<ElementId> rebarIds)
        {
            if (doc == null || host == null)
            {
                return false;
            }

            List<ElementId> ids = (rebarIds ?? Enumerable.Empty<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();
            if (ids.Count < 2)
            {
                return false;
            }

            try
            {
                Autodesk.Revit.DB.Group group = doc.Create.NewGroup(ids);
                if (group?.GroupType != null)
                {
                    string preferredName = $"CBIM_BEAM_STIRRUP_{host.Id.Value}";
                    if (!string.Equals(group.GroupType.Name, preferredName, StringComparison.OrdinalIgnoreCase))
                    {
                        string candidate = preferredName;
                        int suffix = 1;
                        while (!CanRenameGroupType(doc, group.GroupType, candidate) && suffix < 500)
                        {
                            candidate = $"{preferredName}_{suffix}";
                            suffix++;
                        }

                        if (!string.Equals(group.GroupType.Name, candidate, StringComparison.OrdinalIgnoreCase))
                        {
                            group.GroupType.Name = candidate;
                        }
                    }
                }

                return true;
            }
            catch
            {
                return false;
            }
        }

        private static bool CanRenameGroupType(Document doc, GroupType sourceType, string candidateName)
        {
            if (doc == null || sourceType == null || string.IsNullOrWhiteSpace(candidateName))
            {
                return false;
            }

            try
            {
                GroupType existing = new FilteredElementCollector(doc)
                    .OfClass(typeof(GroupType))
                    .Cast<GroupType>()
                    .FirstOrDefault(gt => gt != null &&
                        string.Equals(gt.Name, candidateName, StringComparison.OrdinalIgnoreCase));
                return existing == null || existing.Id == sourceType.Id;
            }
            catch
            {
                return false;
            }
        }

        private static void CreateBeamAdditionalLongitudinalBars(
            Document doc,
            Element host,
            Transform hostTransform,
            RebarBarType barType,
            int barCount,
            double xStartMainFt,
            double xEndMainFt,
            double startLengthFt,
            double endLengthFt,
            double zFt,
            double yLeftFt,
            double yRightFt,
            RebarHookType startHookType,
            RebarHookType endHookType,
            bool autoSplitEnabled,
            double maxSplitLengthFt,
            double splitLapLengthFt,
            out int createdBars,
            out int failedBars)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || hostTransform == null || barType == null || barCount <= 0)
            {
                failedBars = Math.Max(0, barCount);
                return;
            }

            double x0 = xStartMainFt + Math.Max(0.0, startLengthFt);
            double x1 = xEndMainFt - Math.Max(0.0, endLengthFt);
            if (x1 <= x0 + 1e-6)
            {
                x0 = xStartMainFt;
                x1 = xEndMainFt;
            }

            if (x1 <= x0 + 1e-6)
            {
                failedBars = Math.Max(0, barCount);
                return;
            }

            List<double> yPositions = BuildBeamLongitudinalBarYPositions(yLeftFt, yRightFt, barCount);
            CreateBeamLongitudinalLayer(
                doc,
                host,
                hostTransform,
                barType,
                yPositions,
                x0,
                x1,
                zFt,
                startHookType,
                endHookType,
                autoSplitEnabled,
                maxSplitLengthFt,
                splitLapLengthFt,
                out createdBars,
                out failedBars);
        }

        private void GenerateWallRebar(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            if (!Request.WallRebarUseNaviateDataModel || Request.WallRebarNaviate == null)
            {
                _window?.ShowStatus("WALL: request data is missing. Re-open the WALL form and click Apply again.");
                return;
            }

            WallNaviateRebarRequest nav = Request.WallRebarNaviate;
            nav.DeleteExistingRebar = true;

            List<ElementId> requestedIds = (nav.HostElementIds ?? new List<ElementId>())
                .Concat(Request.WallRebarHostElementIds ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();

            if (requestedIds.Count == 0)
            {
                _window?.ShowStatus("WALL: select wall/floor host(s) first.");
                return;
            }

            List<Element> targetHosts = requestedIds
                .Select(doc.GetElement)
                .Where(IsWallRebarHostElement)
                .ToList();

            if (targetHosts.Count == 0)
            {
                _window?.ShowStatus("WALL: selected hosts are no longer available or are not valid rebar hosts.");
                return;
            }

            List<Element> targetWallHosts = targetHosts
                .Where(x => x is Wall)
                .ToList();
            int skippedNonWallHosts = Math.Max(0, targetHosts.Count - targetWallHosts.Count);
            if (targetWallHosts.Count == 0)
            {
                _window?.ShowStatus("WALL: selected host(s) contain no Wall elements. Please select wall element(s).");
                return;
            }

            if (nav.MainBars == null)
            {
                _window?.ShowStatus("WALL: main bars request data is missing.");
                return;
            }

            if (nav.MainBars.VerticalSpacingFt <= 0.0 || nav.MainBars.HorizontalSpacingFt <= 0.0)
            {
                _window?.ShowStatus("WALL: vertical and horizontal spacing must be > 0 mm.");
                return;
            }

            if (!TryResolveWallNaviateBarType(doc, nav.MainBars.VerticalBarTypeName, out RebarBarType verticalBarType))
            {
                _window?.ShowStatus($"WALL: cannot find bar type '{nav.MainBars.VerticalBarTypeName}' for Vertical Bars.");
                return;
            }
            nav.MainBars.VerticalBarTypeId = verticalBarType.Id;

            if (!TryResolveWallNaviateBarType(doc, nav.MainBars.HorizontalBarTypeName, out RebarBarType horizontalBarType))
            {
                _window?.ShowStatus($"WALL: cannot find bar type '{nav.MainBars.HorizontalBarTypeName}' for Horizontal Bars.");
                return;
            }
            nav.MainBars.HorizontalBarTypeId = horizontalBarType.Id;

            if (!TryResolveWallNaviateDowelRequest(doc, nav.TopDowels, "Top Lap Length", verticalBarType, out RebarBarType topDowelBarType, out string dowelError) ||
                !TryResolveWallNaviateDowelRequest(doc, nav.LeftDowels, "Left Lap Length", horizontalBarType, out RebarBarType leftDowelBarType, out dowelError) ||
                !TryResolveWallNaviateDowelRequest(doc, nav.RightDowels, "Right Lap Length", horizontalBarType, out RebarBarType rightDowelBarType, out dowelError))
            {
                _window?.ShowStatus("WALL: " + dowelError);
                return;
            }

            RebarBarType tieBarType = null;
            if (nav.MainBars.CreateTieBars)
            {
                if (nav.MainBars.TieSpacingXFt <= 0.0 || nav.MainBars.TieSpacingZFt <= 0.0)
                {
                    _window?.ShowStatus("WALL: tie bar spacing X and Z must be > 0 mm.");
                    return;
                }

                if (!TryResolveWallNaviateBarType(doc, nav.MainBars.TieBarTypeName, out tieBarType))
                {
                    _window?.ShowStatus($"WALL: cannot find tie bar type '{nav.MainBars.TieBarTypeName}'.");
                    return;
                }

                nav.MainBars.TieBarTypeId = tieBarType.Id;
            }

            nav.HostElementIds = targetWallHosts
                .Select(x => x?.Id ?? ElementId.InvalidElementId)
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .ToList();
            Request.WallRebarHostElementIds = nav.HostElementIds.ToList();

            int hostsSucceeded = 0;
            int hostsFailed = 0;
            int deletedExistingTotal = 0;
            int verticalBarsCreatedTotal = 0;
            int verticalBarsFailedTotal = 0;
            int horizontalBarsCreatedTotal = 0;
            int horizontalBarsFailedTotal = 0;
            int topDowelsCreatedTotal = 0;
            int topDowelsFailedTotal = 0;
            int leftDowelsCreatedTotal = 0;
            int leftDowelsFailedTotal = 0;
            int rightDowelsCreatedTotal = 0;
            int rightDowelsFailedTotal = 0;
            int tieBarsCreatedTotal = 0;
            int tieBarsFailedTotal = 0;
            string firstError = "";

            TransactionStatus commitStatus = TransactionStatus.Uninitialized;
            using (Transaction t = new Transaction(doc, "CamboBIM - Generate Wall Rebar"))
            {
                t.Start();

                foreach (Element host in targetWallHosts)
                {
                    if (host == null)
                    {
                        hostsFailed++;
                        continue;
                    }

                    if (!TryGenerateWallRebarForHost(
                        doc,
                        host,
                        nav,
                        verticalBarType,
                        horizontalBarType,
                        topDowelBarType,
                        leftDowelBarType,
                        rightDowelBarType,
                        tieBarType,
                        out WallRebarHostGenerationStats stats,
                        out string error))
                    {
                        hostsFailed++;
                        if (string.IsNullOrWhiteSpace(firstError) && !string.IsNullOrWhiteSpace(error))
                        {
                            firstError = $"Host {host.Id.Value}: {error}";
                        }
                        continue;
                    }

                    hostsSucceeded++;
                    deletedExistingTotal += stats.DeletedExisting;
                    verticalBarsCreatedTotal += stats.VerticalBarsCreated;
                    verticalBarsFailedTotal += stats.VerticalBarsFailed;
                    horizontalBarsCreatedTotal += stats.HorizontalBarsCreated;
                    horizontalBarsFailedTotal += stats.HorizontalBarsFailed;
                    topDowelsCreatedTotal += stats.TopDowelsCreated;
                    topDowelsFailedTotal += stats.TopDowelsFailed;
                    leftDowelsCreatedTotal += stats.LeftDowelsCreated;
                    leftDowelsFailedTotal += stats.LeftDowelsFailed;
                    rightDowelsCreatedTotal += stats.RightDowelsCreated;
                    rightDowelsFailedTotal += stats.RightDowelsFailed;
                    tieBarsCreatedTotal += stats.TieBarsCreated;
                    tieBarsFailedTotal += stats.TieBarsFailed;
                }

                commitStatus = t.Commit();
            }

            if (commitStatus != TransactionStatus.Committed)
            {
                _window?.ShowStatus("WALL: rebar generation was cancelled or failed to commit. Review Revit warnings/errors.");
                return;
            }

            string summary =
                $"WALL: Generated on {hostsSucceeded}/{targetWallHosts.Count} wall host(s), deleted existing {deletedExistingTotal}. " +
                $"Main bars V/H {verticalBarsCreatedTotal}/{horizontalBarsCreatedTotal} (failed {verticalBarsFailedTotal}/{horizontalBarsFailedTotal}), " +
                $"Lap bars Top/L/R {topDowelsCreatedTotal}/{leftDowelsCreatedTotal}/{rightDowelsCreatedTotal} " +
                $"(failed {topDowelsFailedTotal}/{leftDowelsFailedTotal}/{rightDowelsFailedTotal}), " +
                $"Ties {tieBarsCreatedTotal} (failed {tieBarsFailedTotal}).";

            if (skippedNonWallHosts > 0)
            {
                summary += $" Skipped {skippedNonWallHosts} non-wall host(s).";
            }

            if (!string.IsNullOrWhiteSpace(firstError))
            {
                summary += " " + firstError;
            }

            _window?.ShowStatus(summary);
        }

        private sealed class WallNaviateLayerSpec
        {
            public double YFt { get; set; }
            public int OptionIndex { get; set; }
        }

        private sealed class WallRebarHostGenerationStats
        {
            public int DeletedExisting { get; set; }
            public int VerticalBarsCreated { get; set; }
            public int VerticalBarsFailed { get; set; }
            public int HorizontalBarsCreated { get; set; }
            public int HorizontalBarsFailed { get; set; }
            public int TopDowelsCreated { get; set; }
            public int TopDowelsFailed { get; set; }
            public int LeftDowelsCreated { get; set; }
            public int LeftDowelsFailed { get; set; }
            public int RightDowelsCreated { get; set; }
            public int RightDowelsFailed { get; set; }
            public int TieBarsCreated { get; set; }
            public int TieBarsFailed { get; set; }
        }

        private bool TryGenerateWallRebarForHost(
            Document doc,
            Element host,
            WallNaviateRebarRequest nav,
            RebarBarType verticalBarType,
            RebarBarType horizontalBarType,
            RebarBarType topDowelBarType,
            RebarBarType leftDowelBarType,
            RebarBarType rightDowelBarType,
            RebarBarType tieBarType,
            out WallRebarHostGenerationStats stats,
            out string error)
        {
            stats = new WallRebarHostGenerationStats();
            error = "";

            if (doc == null || host == null || nav?.MainBars == null || verticalBarType == null || horizontalBarType == null)
            {
                error = "input data is not valid.";
                return false;
            }

            RebarBarType resolvedTopDowelBarType = topDowelBarType ?? verticalBarType;
            RebarBarType resolvedLeftDowelBarType = leftDowelBarType ?? horizontalBarType;
            RebarBarType resolvedRightDowelBarType = rightDowelBarType ?? horizontalBarType;

            if (!RebarHostData.IsValidHost(host))
            {
                error = "selected host cannot contain rebar.";
                return false;
            }

            if (!(host is Wall))
            {
                error = "currently only Wall hosts are supported for generation.";
                return false;
            }

            if (!TryGetFoundationRebarHostFrameAndBounds(host, out Transform hostTransform, out XYZ localMin, out XYZ localMax, out string hostError))
            {
                error = hostError;
                return false;
            }

            double lengthFt = Math.Max(0.0, localMax.X - localMin.X);
            double thicknessFt = Math.Max(0.0, localMax.Y - localMin.Y);
            double heightFt = Math.Max(0.0, localMax.Z - localMin.Z);
            if (lengthFt <= 1e-6 || thicknessFt <= 1e-6 || heightFt <= 1e-6)
            {
                error = "wall geometry size is invalid.";
                return false;
            }

            double verticalDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(verticalBarType));
            double horizontalDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(horizontalBarType));
            double maxMainDiaFt = Math.Max(verticalDiaFt, horizontalDiaFt);

            double faceCoverFt = Math.Max(MmToFeet(40.0), (maxMainDiaFt * 0.5) + MmToFeet(5.0));
            double xCoverVerticalFt = Math.Max(MmToFeet(35.0), (verticalDiaFt * 0.5) + MmToFeet(10.0));
            double xCoverHorizontalFt = Math.Max(MmToFeet(35.0), (horizontalDiaFt * 0.5) + MmToFeet(10.0));
            double zCoverVerticalFt = Math.Max(MmToFeet(35.0), (verticalDiaFt * 0.5) + MmToFeet(10.0));
            double zCoverHorizontalFt = Math.Max(MmToFeet(35.0), (horizontalDiaFt * 0.5) + MmToFeet(10.0));

            List<WallNaviateLayerSpec> layerSpecs = ResolveWallNaviateLayerSpecs(
                localMin,
                localMax,
                faceCoverFt,
                nav.MainBars.UseReinforcementMode1,
                nav.MainBars.ReinforcementMode1OptionIndex,
                nav.MainBars.UseReinforcementMode2,
                nav.MainBars.ReinforcementMode2OptionIndex);
            if (layerSpecs.Count == 0)
            {
                error = "reinforcement mode is not selected.";
                return false;
            }

            double xStartVertical = localMin.X + xCoverVerticalFt;
            double xEndVertical = localMax.X - xCoverVerticalFt;
            double zStartVertical = localMin.Z + zCoverVerticalFt;
            double zEndVertical = localMax.Z - zCoverVerticalFt;
            if (xEndVertical <= xStartVertical + 1e-6 || zEndVertical <= zStartVertical + 1e-6)
            {
                error = "vertical bar cover is too large for this wall size.";
                return false;
            }

            double xStartHorizontal = localMin.X + xCoverHorizontalFt;
            double xEndHorizontal = localMax.X - xCoverHorizontalFt;
            double zStartHorizontal = localMin.Z + zCoverHorizontalFt;
            double zEndHorizontal = localMax.Z - zCoverHorizontalFt;
            if (xEndHorizontal <= xStartHorizontal + 1e-6 || zEndHorizontal <= zStartHorizontal + 1e-6)
            {
                error = "horizontal bar cover is too large for this wall size.";
                return false;
            }

            List<double> verticalXPositions = BuildFoundationRebarPositionsBySpacing(
                xStartVertical,
                xEndVertical,
                nav.MainBars.VerticalSpacingFt);
            List<double> horizontalZPositions = BuildFoundationRebarPositionsBySpacing(
                zStartHorizontal,
                zEndHorizontal,
                nav.MainBars.HorizontalSpacingFt);
            if (verticalXPositions.Count == 0 && horizontalZPositions.Count == 0)
            {
                error = "unable to resolve main bar positions with the current spacing.";
                return false;
            }

            RebarHookType verticalTopHookType = ResolveFoundationNaviateHookType(doc, nav.MainBars.VerticalHookTop, RebarStyle.Standard);
            RebarHookType horizontalLeftHookType = ResolveFoundationNaviateHookType(doc, nav.MainBars.HorizontalHookLeft, RebarStyle.Standard);
            RebarHookType horizontalRightHookType = ResolveFoundationNaviateHookType(doc, nav.MainBars.HorizontalHookRight, RebarStyle.Standard);
            XYZ distributionNormalX = NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX); // distribute along wall length
            XYZ distributionNormalZ = NormalizeOrDefault(hostTransform.BasisZ, XYZ.BasisZ); // distribute along wall height

            if (nav.DeleteExistingRebar)
            {
                stats.DeletedExisting = DeleteExistingColumnRebars(doc, host);
            }

            int topLapPatternMode = ClampWallNaviateLapModeIndex(nav.TopDowels?.PatternModeIndex ?? 0);
            int leftLapPatternMode = ClampWallNaviateLapModeIndex(nav.LeftDowels?.PatternModeIndex ?? 0);
            int rightLapPatternMode = ClampWallNaviateLapModeIndex(nav.RightDowels?.PatternModeIndex ?? 0);

            bool topLapEnabled = nav.TopDowels?.IsEnabled == true && nav.TopDowels.OverlapLengthFt > 1e-6;
            bool leftLapEnabled = nav.LeftDowels?.IsEnabled == true && nav.LeftDowels.OverlapLengthFt > 1e-6;
            bool rightLapEnabled = nav.RightDowels?.IsEnabled == true && nav.RightDowels.OverlapLengthFt > 1e-6;

            bool topLapStraightEnabled = topLapEnabled && topLapPatternMode != 2;
            bool leftLapStraightEnabled = leftLapEnabled && leftLapPatternMode != 2;
            bool rightLapStraightEnabled = rightLapEnabled && rightLapPatternMode != 2;
            bool topLapUShapeEnabled = topLapEnabled && topLapPatternMode == 2;
            bool leftLapUShapeEnabled = leftLapEnabled && leftLapPatternMode == 2;
            bool rightLapUShapeEnabled = rightLapEnabled && rightLapPatternMode == 2;

            double topLapExtensionFt = topLapEnabled ? Math.Max(nav.TopDowels.OverlapLengthFt, MmToFeet(120.0)) : 0.0;
            double leftLapExtensionFt = leftLapEnabled ? Math.Max(nav.LeftDowels.OverlapLengthFt, MmToFeet(120.0)) : 0.0;
            double rightLapExtensionFt = rightLapEnabled ? Math.Max(nav.RightDowels.OverlapLengthFt, MmToFeet(120.0)) : 0.0;
            bool autoSplitEnabled = nav.MainBars.AutoSplitEnabled;
            double maxSplitLengthFt = nav.MainBars.MaxBarLengthFt > 1e-6 ? nav.MainBars.MaxBarLengthFt : MmToFeet(12000.0);
            maxSplitLengthFt = Math.Min(maxSplitLengthFt, MmToFeet(12000.0));
            double verticalSplitLapFt = (nav.MainBars.UseFixedSplitLapLength && nav.MainBars.FixedSplitLapLengthFt > 1e-6)
                ? nav.MainBars.FixedSplitLapLengthFt
                : Math.Max(MmToFeet(300.0), topLapEnabled ? nav.TopDowels.OverlapLengthFt : Math.Max(verticalDiaFt * 40.0, MmToFeet(300.0)));
            double horizontalSplitLapFt = (nav.MainBars.UseFixedSplitLapLength && nav.MainBars.FixedSplitLapLengthFt > 1e-6)
                ? nav.MainBars.FixedSplitLapLengthFt
                : Math.Max(MmToFeet(300.0), Math.Max(leftLapEnabled ? nav.LeftDowels.OverlapLengthFt : horizontalDiaFt * 40.0,
                                                     rightLapEnabled ? nav.RightDowels.OverlapLengthFt : horizontalDiaFt * 40.0));
            double wallYMinFt = Math.Min(localMin.Y, localMax.Y);
            double wallYMaxFt = Math.Max(localMin.Y, localMax.Y);
            double wallYMidFt = (wallYMinFt + wallYMaxFt) * 0.5;
            double wallInteriorYMinFt = wallYMinFt + MmToFeet(2.0);
            double wallInteriorYMaxFt = wallYMaxFt - MmToFeet(2.0);
            if (wallInteriorYMaxFt <= wallInteriorYMinFt + 1e-6)
            {
                wallInteriorYMinFt = wallYMinFt;
                wallInteriorYMaxFt = wallYMaxFt;
            }

            double crossingOffsetFt = Math.Max(MmToFeet(2.0), (verticalDiaFt + horizontalDiaFt) * 0.5);
            double mainBarsSplitPivotXFt = (xStartHorizontal + xEndHorizontal) * 0.5;

            foreach (WallNaviateLayerSpec layer in layerSpecs)
            {
                if (layer == null)
                {
                    continue;
                }

                if (!TryResolveWallNaviateModeVerticalRange(
                    zStartVertical,
                    zEndVertical,
                    layer.OptionIndex,
                    out double layerVerticalStartFt,
                    out double layerVerticalEndFt))
                {
                    continue;
                }

                int mainBarsOption = ClampWallNaviateMainBarsModeIndex(layer.OptionIndex);
                double outsideDirectionSign = layer.YFt >= wallYMidFt ? 1.0 : -1.0;
                double verticalOutsideYFt = Math.Max(wallInteriorYMinFt, Math.Min(wallInteriorYMaxFt, layer.YFt + (outsideDirectionSign * crossingOffsetFt * 0.5)));
                double verticalInsideYFt = Math.Max(wallInteriorYMinFt, Math.Min(wallInteriorYMaxFt, layer.YFt - (outsideDirectionSign * crossingOffsetFt * 0.5)));

                if (verticalXPositions.Count > 0)
                {
                    var verticalBasePositions = new List<double>();
                    var verticalLapPositions = new List<double>();
                    for (int i = 0; i < verticalXPositions.Count; i++)
                    {
                        double xFt = verticalXPositions[i];
                        if (topLapStraightEnabled && ShouldIncludeWallNaviatePatternIndex(i, topLapPatternMode))
                        {
                            verticalLapPositions.Add(xFt);
                        }
                        else
                        {
                            verticalBasePositions.Add(xFt);
                        }
                    }

                    if (verticalBasePositions.Count > 0)
                    {
                        CreateWallBarsAtPositions(
                            doc,
                            host,
                            RebarStyle.Standard,
                            verticalBarType,
                            null,
                            verticalTopHookType,
                            distributionNormalX,
                            verticalBasePositions,
                            xFt => hostTransform.OfPoint(new XYZ(
                                xFt,
                                ResolveWallMainVerticalBarYFt(mainBarsOption, xFt, mainBarsSplitPivotXFt, verticalOutsideYFt, verticalInsideYFt),
                                layerVerticalStartFt)),
                            xFt => hostTransform.OfPoint(new XYZ(
                                xFt,
                                ResolveWallMainVerticalBarYFt(mainBarsOption, xFt, mainBarsSplitPivotXFt, verticalOutsideYFt, verticalInsideYFt),
                                layerVerticalEndFt)),
                            out int createdBars,
                            out int failedBars,
                            autoSplitEnabled,
                            maxSplitLengthFt,
                            verticalSplitLapFt);
                        stats.VerticalBarsCreated += createdBars;
                        stats.VerticalBarsFailed += failedBars;
                    }

                    if (verticalLapPositions.Count > 0)
                    {
                        double verticalLapEndFt = layerVerticalEndFt + topLapExtensionFt;
                        CreateWallBarsAtPositions(
                            doc,
                            host,
                            RebarStyle.Standard,
                            resolvedTopDowelBarType,
                            null,
                            verticalTopHookType,
                            distributionNormalX,
                            verticalLapPositions,
                            xFt => hostTransform.OfPoint(new XYZ(
                                xFt,
                                ResolveWallMainVerticalBarYFt(mainBarsOption, xFt, mainBarsSplitPivotXFt, verticalOutsideYFt, verticalInsideYFt),
                                layerVerticalStartFt)),
                            xFt => hostTransform.OfPoint(new XYZ(
                                xFt,
                                ResolveWallMainVerticalBarYFt(mainBarsOption, xFt, mainBarsSplitPivotXFt, verticalOutsideYFt, verticalInsideYFt),
                                verticalLapEndFt)),
                            out int createdBars,
                            out int failedBars,
                            autoSplitEnabled,
                            maxSplitLengthFt,
                            verticalSplitLapFt);
                        stats.VerticalBarsCreated += createdBars;
                        stats.VerticalBarsFailed += failedBars;
                        stats.TopDowelsCreated += createdBars;
                        stats.TopDowelsFailed += failedBars;
                    }

                    if (topLapUShapeEnabled)
                    {
                        CreateWallTopLapUShapeBars(
                            doc,
                            host,
                            RebarStyle.Standard,
                            resolvedTopDowelBarType,
                            hostTransform,
                            ResolveWallMainVerticalBarYFt(mainBarsOption, mainBarsSplitPivotXFt, mainBarsSplitPivotXFt, verticalOutsideYFt, verticalInsideYFt),
                            verticalXPositions,
                            layerVerticalEndFt,
                            topLapExtensionFt,
                            out int createdBars,
                            out int failedBars);
                        stats.TopDowelsCreated += createdBars;
                        stats.TopDowelsFailed += failedBars;
                    }
                }

                if (horizontalZPositions.Count > 0)
                {
                    var layerHorizontalIndices = new List<int>();
                    var layerHorizontalPositions = new List<double>();
                    for (int i = 0; i < horizontalZPositions.Count; i++)
                    {
                        double zFt = horizontalZPositions[i];
                        if (zFt < (layerVerticalStartFt - 1e-6) || zFt > (layerVerticalEndFt + 1e-6))
                        {
                            continue;
                        }

                        layerHorizontalIndices.Add(i);
                        layerHorizontalPositions.Add(zFt);
                    }

                    if (layerHorizontalPositions.Count > 0)
                    {
                        var horizontalBasePositions = new List<double>();
                        var horizontalLeftOnlyPositions = new List<double>();
                        var horizontalRightOnlyPositions = new List<double>();
                        var horizontalBothLapPositions = new List<double>();
                        ResolveWallMainHorizontalBarYBySide(
                            mainBarsOption,
                            verticalOutsideYFt,
                            verticalInsideYFt,
                            out double horizontalLeftYFt,
                            out double horizontalRightYFt);

                        for (int i = 0; i < layerHorizontalPositions.Count; i++)
                        {
                            int sourceIndex = layerHorizontalIndices[i];
                            double zFt = layerHorizontalPositions[i];
                            bool leftLap = leftLapStraightEnabled && ShouldIncludeWallNaviatePatternIndex(sourceIndex, leftLapPatternMode);
                            bool rightLap = rightLapStraightEnabled && ShouldIncludeWallNaviatePatternIndex(sourceIndex, rightLapPatternMode);

                            if (leftLap && rightLap)
                            {
                                horizontalBothLapPositions.Add(zFt);
                            }
                            else if (leftLap)
                            {
                                horizontalLeftOnlyPositions.Add(zFt);
                            }
                            else if (rightLap)
                            {
                                horizontalRightOnlyPositions.Add(zFt);
                            }
                            else
                            {
                                horizontalBasePositions.Add(zFt);
                            }
                        }

                        if (horizontalBasePositions.Count > 0)
                        {
                            CreateWallHorizontalBarsAtPositions(
                                doc,
                                host,
                                RebarStyle.Standard,
                                horizontalBarType,
                                horizontalLeftHookType,
                                horizontalRightHookType,
                                distributionNormalZ,
                                horizontalBasePositions,
                                hostTransform,
                                xStartHorizontal,
                                xEndHorizontal,
                                mainBarsSplitPivotXFt,
                                verticalOutsideYFt,
                                verticalInsideYFt,
                                mainBarsOption,
                                out int createdBars,
                                out int failedBars,
                                autoSplitEnabled,
                                maxSplitLengthFt,
                                horizontalSplitLapFt);
                            stats.HorizontalBarsCreated += createdBars;
                            stats.HorizontalBarsFailed += failedBars;
                        }

                        if (horizontalLeftOnlyPositions.Count > 0)
                        {
                            double xLeftStartFt = xStartHorizontal - leftLapExtensionFt;
                            CreateWallHorizontalBarsAtPositions(
                                doc,
                                host,
                                RebarStyle.Standard,
                                resolvedLeftDowelBarType,
                                horizontalLeftHookType,
                                horizontalRightHookType,
                                distributionNormalZ,
                                horizontalLeftOnlyPositions,
                                hostTransform,
                                xLeftStartFt,
                                xEndHorizontal,
                                mainBarsSplitPivotXFt,
                                verticalOutsideYFt,
                                verticalInsideYFt,
                                mainBarsOption,
                                out int createdBars,
                                out int failedBars,
                                autoSplitEnabled,
                                maxSplitLengthFt,
                                horizontalSplitLapFt);
                            stats.HorizontalBarsCreated += createdBars;
                            stats.HorizontalBarsFailed += failedBars;
                            stats.LeftDowelsCreated += createdBars;
                            stats.LeftDowelsFailed += failedBars;
                        }

                        if (horizontalRightOnlyPositions.Count > 0)
                        {
                            double xRightEndFt = xEndHorizontal + rightLapExtensionFt;
                            CreateWallHorizontalBarsAtPositions(
                                doc,
                                host,
                                RebarStyle.Standard,
                                resolvedRightDowelBarType,
                                horizontalLeftHookType,
                                horizontalRightHookType,
                                distributionNormalZ,
                                horizontalRightOnlyPositions,
                                hostTransform,
                                xStartHorizontal,
                                xRightEndFt,
                                mainBarsSplitPivotXFt,
                                verticalOutsideYFt,
                                verticalInsideYFt,
                                mainBarsOption,
                                out int createdBars,
                                out int failedBars,
                                autoSplitEnabled,
                                maxSplitLengthFt,
                                horizontalSplitLapFt);
                            stats.HorizontalBarsCreated += createdBars;
                            stats.HorizontalBarsFailed += failedBars;
                            stats.RightDowelsCreated += createdBars;
                            stats.RightDowelsFailed += failedBars;
                        }

                        if (horizontalBothLapPositions.Count > 0)
                        {
                            double xLeftStartFt = xStartHorizontal - leftLapExtensionFt;
                            double xRightEndFt = xEndHorizontal + rightLapExtensionFt;
                            RebarBarType bothLapBarType = resolvedLeftDowelBarType ?? resolvedRightDowelBarType ?? horizontalBarType;
                            if (resolvedLeftDowelBarType != null &&
                                resolvedRightDowelBarType != null &&
                                resolvedLeftDowelBarType.Id != resolvedRightDowelBarType.Id)
                            {
                                bothLapBarType = horizontalBarType;
                            }
                            CreateWallHorizontalBarsAtPositions(
                                doc,
                                host,
                                RebarStyle.Standard,
                                bothLapBarType,
                                horizontalLeftHookType,
                                horizontalRightHookType,
                                distributionNormalZ,
                                horizontalBothLapPositions,
                                hostTransform,
                                xLeftStartFt,
                                xRightEndFt,
                                mainBarsSplitPivotXFt,
                                verticalOutsideYFt,
                                verticalInsideYFt,
                                mainBarsOption,
                                out int createdBars,
                                out int failedBars,
                                autoSplitEnabled,
                                maxSplitLengthFt,
                                horizontalSplitLapFt);
                            stats.HorizontalBarsCreated += createdBars;
                            stats.HorizontalBarsFailed += failedBars;
                            stats.LeftDowelsCreated += createdBars;
                            stats.LeftDowelsFailed += failedBars;
                            stats.RightDowelsCreated += createdBars;
                            stats.RightDowelsFailed += failedBars;
                        }

                        if (leftLapUShapeEnabled)
                        {
                            CreateWallSideLapUShapeBars(
                                doc,
                                host,
                                RebarStyle.Standard,
                                resolvedLeftDowelBarType,
                                hostTransform,
                                horizontalLeftYFt,
                                layerHorizontalPositions,
                                xStartHorizontal,
                                leftLapExtensionFt,
                                isLeftSide: true,
                                out int createdBars,
                                out int failedBars);
                            stats.LeftDowelsCreated += createdBars;
                            stats.LeftDowelsFailed += failedBars;
                        }

                        if (rightLapUShapeEnabled)
                        {
                            CreateWallSideLapUShapeBars(
                                doc,
                                host,
                                RebarStyle.Standard,
                                resolvedRightDowelBarType,
                                hostTransform,
                                horizontalRightYFt,
                                layerHorizontalPositions,
                                xEndHorizontal,
                                rightLapExtensionFt,
                                isLeftSide: false,
                                out int createdBars,
                                out int failedBars);
                            stats.RightDowelsCreated += createdBars;
                            stats.RightDowelsFailed += failedBars;
                        }
                    }
                }
            }

            if (nav.MainBars.CreateTieBars && tieBarType != null)
            {
                RebarHookType tieStartHookType = FindClosestRebarHookTypeByAngle(doc, 180.0, RebarStyle.Standard);
                RebarHookType tieEndHookType = FindClosestRebarHookTypeByAngle(doc, 135.0, RebarStyle.Standard);
                RebarShape tiePreferredShape = TryFindPreferredWallTieShape(doc);
                double tieDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(tieBarType));
                double yCoverTieFt = Math.Max(MmToFeet(25.0), (tieDiaFt * 0.5) + MmToFeet(5.0));
                double y0TieFt = localMin.Y + yCoverTieFt;
                double y1TieFt = localMax.Y - yCoverTieFt;
                if (y1TieFt > y0TieFt + 1e-6)
                {
                    List<double> tieXPositions = BuildFoundationRebarPositionsBySpacing(
                        xStartVertical,
                        xEndVertical,
                        nav.MainBars.TieSpacingXFt);
                    List<double> tieZPositions = BuildFoundationRebarPositionsBySpacing(
                        zStartHorizontal,
                        zEndHorizontal,
                        nav.MainBars.TieSpacingZFt);

                    foreach (double zTieFt in tieZPositions)
                    {
                        CreateWallBarsAtPositions(
                            doc,
                            host,
                            RebarStyle.Standard,
                            tieBarType,
                            tieStartHookType,
                            tieEndHookType,
                            distributionNormalX,
                            tieXPositions,
                            xFt => hostTransform.OfPoint(new XYZ(xFt, y0TieFt, zTieFt)),
                            xFt => hostTransform.OfPoint(new XYZ(xFt, y1TieFt, zTieFt)),
                            out int tieCreated,
                            out int tieFailed,
                            false,
                            0.0,
                            0.0,
                            tiePreferredShape);
                        stats.TieBarsCreated += tieCreated;
                        stats.TieBarsFailed += tieFailed;
                    }
                }
            }

            return true;
        }

        private static List<WallNaviateLayerSpec> ResolveWallNaviateLayerSpecs(
            XYZ localMin,
            XYZ localMax,
            double faceCoverFt,
            bool useMode1,
            int mode1OptionIndex,
            bool useMode2,
            int mode2OptionIndex)
        {
            var result = new List<WallNaviateLayerSpec>();
            if (localMin == null || localMax == null)
            {
                return result;
            }

            if (!useMode1 && !useMode2)
            {
                useMode1 = true;
            }

            double yMin = Math.Min(localMin.Y, localMax.Y);
            double yMax = Math.Max(localMin.Y, localMax.Y);
            if (yMax <= yMin + 1e-6)
            {
                return result;
            }

            double insideMin = yMin + MmToFeet(2.0);
            double insideMax = yMax - MmToFeet(2.0);
            if (insideMax <= insideMin + 1e-6)
            {
                insideMin = yMin;
                insideMax = yMax;
            }

            // Mode 1: 2 layers (near both faces)
            if (useMode1)
            {
                double yTopFt = Math.Max(insideMin, Math.Min(insideMax, yMax - Math.Max(0.0, faceCoverFt)));
                double yBottomFt = Math.Max(insideMin, Math.Min(insideMax, yMin + Math.Max(0.0, faceCoverFt)));
                AddWallNaviateLayerSpec(result, yTopFt, 0);
                AddWallNaviateLayerSpec(result, yBottomFt, 0);
                return result;
            }

            // Mode 2: 1 layer (wall center line)
            if (useMode2)
            {
                double yMidFt = (insideMin + insideMax) * 0.5;
                AddWallNaviateLayerSpec(result, yMidFt, 1);
            }

            return result;
        }

        private static void AddWallNaviateLayerSpec(List<WallNaviateLayerSpec> target, double yFt, int optionIndex)
        {
            if (target == null)
            {
                return;
            }

            double tolFt = MmToFeet(1.0);
            foreach (WallNaviateLayerSpec existing in target)
            {
                if (existing == null)
                {
                    continue;
                }

                if (Math.Abs(existing.YFt - yFt) <= tolFt)
                {
                    return;
                }
            }

            target.Add(new WallNaviateLayerSpec
            {
                YFt = yFt,
                OptionIndex = Math.Max(0, optionIndex)
            });
        }

        private static bool TryResolveWallNaviateModeVerticalRange(
            double zMin,
            double zMax,
            int optionIndex,
            out double zStart,
            out double zEnd)
        {
            zStart = Math.Min(zMin, zMax);
            zEnd = Math.Max(zMin, zMax);
            return zEnd > zStart + 1e-6;
        }

        private static bool ShouldIncludeWallNaviatePatternIndex(int index, int patternModeIndex)
        {
            if (index < 0)
            {
                return false;
            }

            switch (Math.Max(0, patternModeIndex))
            {
                case 1:
                    return index % 2 == 0;
                case 2:
                    return false; // U-shape mode does not use straight lap continuation.
                default:
                    return true;
            }
        }

        private static int ClampWallNaviateLapModeIndex(int modeIndex)
        {
            if (modeIndex <= 0)
            {
                return 0;
            }

            return modeIndex >= 2 ? 2 : modeIndex;
        }

        private static int ClampWallNaviateMainBarsModeIndex(int modeIndex)
        {
            if (modeIndex <= 0)
            {
                return 0;
            }

            return 1;
        }

        private static double ResolveWallMainVerticalBarYFt(
            int mainBarsOptionIndex,
            double xFt,
            double splitPivotXFt,
            double yOutsideFt,
            double yInsideFt)
        {
            if (ClampWallNaviateMainBarsModeIndex(mainBarsOptionIndex) == 1)
            {
                return (yOutsideFt + yInsideFt) * 0.5; // one centered layer
            }

            return yOutsideFt; // two-layer mode: vertical outside horizontal
        }

        private static void ResolveWallMainHorizontalBarYBySide(
            int mainBarsOptionIndex,
            double yOutsideFt,
            double yInsideFt,
            out double yLeftFt,
            out double yRightFt)
        {
            if (ClampWallNaviateMainBarsModeIndex(mainBarsOptionIndex) == 1)
            {
                double yMidFt = (yOutsideFt + yInsideFt) * 0.5;
                yLeftFt = yMidFt;
                yRightFt = yMidFt;
                return;
            }

            yLeftFt = yInsideFt;  // two-layer mode: horizontal inside vertical
            yRightFt = yInsideFt;
        }

        private static List<double> BuildWallNaviatePatternedPositions(IList<double> sourcePositions, int patternModeIndex)
        {
            var result = new List<double>();
            if (sourcePositions == null || sourcePositions.Count == 0)
            {
                return result;
            }

            for (int i = 0; i < sourcePositions.Count; i++)
            {
                if (ShouldIncludeWallNaviatePatternIndex(i, patternModeIndex))
                {
                    result.Add(sourcePositions[i]);
                }
            }

            return result;
        }

        private static double TryGetWallNaviateLinearSpacingFt(IList<double> positions)
        {
            if (positions == null || positions.Count < 2)
            {
                return 0.0;
            }

            return Math.Abs(positions[1] - positions[0]);
        }

        private static void CreateWallLinearRebarSet(
            Document doc,
            Element host,
            RebarStyle style,
            RebarBarType barType,
            RebarHookType startHookType,
            RebarHookType endHookType,
            XYZ normal,
            XYZ lineStart,
            XYZ lineEnd,
            int barCount,
            double spacingFt,
            out int createdBars,
            out int failedBars,
            RebarShape preferredShape = null)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || barType == null || normal == null || lineStart == null || lineEnd == null || barCount <= 0)
            {
                failedBars = Math.Max(0, barCount);
                return;
            }

            if (lineStart.DistanceTo(lineEnd) <= 1e-6)
            {
                failedBars = barCount;
                return;
            }

            Rebar rebar = CreateRebarFromCurvesPreferShape(
                doc,
                style,
                barType,
                preferredShape,
                startHookType,
                endHookType,
                host,
                normal,
                new List<Curve> { Line.CreateBound(lineStart, lineEnd) },
                RebarHookOrientation.Right,
                RebarHookOrientation.Right);
            if (rebar == null)
            {
                failedBars = barCount;
                return;
            }

            TryAssignRebarPartitionByType(rebar, barType);

            if (barCount <= 1)
            {
                createdBars = 1;
                return;
            }

            bool layoutApplied = false;
            double safeSpacingFt = Math.Max(MmToFeet(1.0), Math.Abs(spacingFt));
            try
            {
                RebarShapeDrivenAccessor accessor = rebar.GetShapeDrivenAccessor();
                if (accessor != null)
                {
                    accessor.SetLayoutAsNumberWithSpacing(
                        barCount,
                        safeSpacingFt,
                        true,
                        true,
                        true);
                    layoutApplied = true;
                }
            }
            catch
            {
                layoutApplied = false;
            }

            if (!layoutApplied)
            {
                try
                {
                    RebarShapeDrivenAccessor accessor = rebar.GetShapeDrivenAccessor();
                    if (accessor != null)
                    {
                        accessor.SetLayoutAsMaximumSpacing(
                            safeSpacingFt,
                            safeSpacingFt * (barCount - 1),
                            true,
                            true,
                            true);
                        layoutApplied = true;
                    }
                }
                catch
                {
                    layoutApplied = false;
                }
            }

            if (layoutApplied)
            {
                createdBars = barCount;
                return;
            }

            createdBars = 1;
            failedBars = barCount - 1;
        }

        private static void CreateWallBarsAtPositions(
            Document doc,
            Element host,
            RebarStyle style,
            RebarBarType barType,
            RebarHookType startHookType,
            RebarHookType endHookType,
            XYZ distributionNormal,
            IList<double> positions,
            Func<double, XYZ> buildStartPoint,
            Func<double, XYZ> buildEndPoint,
            out int createdBars,
            out int failedBars,
            bool autoSplitEnabled,
            double maxSplitLengthFt,
            double splitLapLengthFt,
            RebarShape preferredShape = null)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || barType == null || distributionNormal == null ||
                positions == null || positions.Count == 0 || buildStartPoint == null || buildEndPoint == null)
            {
                failedBars = positions?.Count ?? 0;
                return;
            }

            const double tiny = 1e-9;
            double spacingTolFt = MmToFeet(0.5);
            int i = 0;
            while (i < positions.Count)
            {
                if (i == positions.Count - 1)
                {
                    XYZ p0 = buildStartPoint(positions[i]);
                    XYZ p1 = buildEndPoint(positions[i]);
                    CreateWallLinearRebarSet(
                        doc,
                        host,
                        style,
                        barType,
                        startHookType,
                        endHookType,
                        distributionNormal,
                        p0,
                        p1,
                        1,
                        0.0,
                        out int created,
                        out int failed,
                        preferredShape);
                    createdBars += created;
                    failedBars += failed;
                    i++;
                    continue;
                }

                int runStart = i;
                double spacingFt = Math.Abs(positions[i + 1] - positions[i]);
                i += 2;
                while (i < positions.Count)
                {
                    double nextSpacingFt = Math.Abs(positions[i] - positions[i - 1]);
                    if (Math.Abs(nextSpacingFt - spacingFt) > spacingTolFt + tiny)
                    {
                        break;
                    }

                    i++;
                }

                int runCount = i - runStart;
                XYZ runP0 = buildStartPoint(positions[runStart]);
                XYZ runP1 = buildEndPoint(positions[runStart]);
                CreateWallLinearRebarSetWithOptionalSplit(
                    doc,
                    host,
                    style,
                    barType,
                    startHookType,
                    endHookType,
                    distributionNormal,
                    runP0,
                    runP1,
                    runCount,
                    spacingFt,
                    out int runCreated,
                    out int runFailed,
                    autoSplitEnabled,
                    maxSplitLengthFt,
                    splitLapLengthFt,
                    preferredShape);
                createdBars += runCreated;
                failedBars += runFailed;
            }
        }

        private static void CreateWallHorizontalBarsAtPositions(
            Document doc,
            Element host,
            RebarStyle style,
            RebarBarType barType,
            RebarHookType startHookType,
            RebarHookType endHookType,
            XYZ distributionNormal,
            IList<double> zPositions,
            Transform hostTransform,
            double xStartFt,
            double xEndFt,
            double splitPivotXFt,
            double yOutsideFt,
            double yInsideFt,
            int mainBarsOptionIndex,
            out int createdBars,
            out int failedBars,
            bool autoSplitEnabled,
            double maxSplitLengthFt,
            double splitLapLengthFt,
            RebarShape preferredShape = null)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || barType == null || distributionNormal == null ||
                zPositions == null || zPositions.Count == 0 || hostTransform == null)
            {
                failedBars = zPositions?.Count ?? 0;
                return;
            }

            double x0 = Math.Min(xStartFt, xEndFt);
            double x1 = Math.Max(xStartFt, xEndFt);
            if (x1 <= x0 + 1e-6)
            {
                failedBars = zPositions.Count;
                return;
            }

            ResolveWallMainHorizontalBarYBySide(mainBarsOptionIndex, yOutsideFt, yInsideFt, out double yLeftFt, out double yRightFt);
            CreateWallBarsAtPositions(
                doc,
                host,
                style,
                barType,
                startHookType,
                endHookType,
                distributionNormal,
                zPositions,
                zFt => hostTransform.OfPoint(new XYZ(x0, yLeftFt, zFt)),
                zFt => hostTransform.OfPoint(new XYZ(x1, yRightFt, zFt)),
                out createdBars,
                out failedBars,
                autoSplitEnabled,
                maxSplitLengthFt,
                splitLapLengthFt,
                preferredShape);
        }

        private static void CreateWallTopLapUShapeBars(
            Document doc,
            Element host,
            RebarStyle style,
            RebarBarType barType,
            Transform hostTransform,
            double yFt,
            IList<double> xPositions,
            double zTopOfWallFt,
            double lapExtensionFt,
            out int createdBars,
            out int failedBars)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || barType == null || hostTransform == null || xPositions == null || xPositions.Count < 2)
            {
                return;
            }

            double zBridgeFt = zTopOfWallFt + Math.Max(MmToFeet(120.0), lapExtensionFt);
            XYZ planeNormal = NormalizeOrDefault(hostTransform.BasisY, XYZ.BasisY);
            const double tol = 1e-6;

            for (int i = 0; i + 1 < xPositions.Count; i += 2)
            {
                double x0Ft = xPositions[i];
                double x1Ft = xPositions[i + 1];
                if (x1Ft <= x0Ft + tol)
                {
                    continue;
                }

                XYZ p0 = hostTransform.OfPoint(new XYZ(x0Ft, yFt, zTopOfWallFt));
                XYZ p1 = hostTransform.OfPoint(new XYZ(x0Ft, yFt, zBridgeFt));
                XYZ p2 = hostTransform.OfPoint(new XYZ(x1Ft, yFt, zBridgeFt));
                XYZ p3 = hostTransform.OfPoint(new XYZ(x1Ft, yFt, zTopOfWallFt));

                IList<Curve> curves = new List<Curve>
                {
                    Line.CreateBound(p0, p1),
                    Line.CreateBound(p1, p2),
                    Line.CreateBound(p2, p3)
                };

                Rebar rb = CreateRebarFromCurvesPreferShape(
                    doc,
                    style,
                    barType,
                    preferredShape: null,
                    startHookType: null,
                    endHookType: null,
                    host: host,
                    normal: planeNormal,
                    curves: curves,
                    startOrientation: RebarHookOrientation.Right,
                    endOrientation: RebarHookOrientation.Right);
                if (rb != null)
                {
                    createdBars++;
                }
                else
                {
                    failedBars++;
                }
            }
        }

        private static void CreateWallSideLapUShapeBars(
            Document doc,
            Element host,
            RebarStyle style,
            RebarBarType barType,
            Transform hostTransform,
            double yFt,
            IList<double> zPositions,
            double xInnerFt,
            double lapExtensionFt,
            bool isLeftSide,
            out int createdBars,
            out int failedBars)
        {
            createdBars = 0;
            failedBars = 0;

            if (doc == null || host == null || barType == null || hostTransform == null || zPositions == null || zPositions.Count < 2)
            {
                return;
            }

            double extensionFt = Math.Max(MmToFeet(120.0), lapExtensionFt);
            double xOuterFt = isLeftSide ? (xInnerFt - extensionFt) : (xInnerFt + extensionFt);
            XYZ planeNormal = NormalizeOrDefault(hostTransform.BasisY, XYZ.BasisY);
            const double tol = 1e-6;

            for (int i = 0; i + 1 < zPositions.Count; i += 2)
            {
                double z0Ft = zPositions[i];
                double z1Ft = zPositions[i + 1];
                if (z1Ft <= z0Ft + tol)
                {
                    continue;
                }

                XYZ p0 = hostTransform.OfPoint(new XYZ(xInnerFt, yFt, z0Ft));
                XYZ p1 = hostTransform.OfPoint(new XYZ(xOuterFt, yFt, z0Ft));
                XYZ p2 = hostTransform.OfPoint(new XYZ(xOuterFt, yFt, z1Ft));
                XYZ p3 = hostTransform.OfPoint(new XYZ(xInnerFt, yFt, z1Ft));

                IList<Curve> curves = new List<Curve>
                {
                    Line.CreateBound(p0, p1),
                    Line.CreateBound(p1, p2),
                    Line.CreateBound(p2, p3)
                };

                Rebar rb = CreateRebarFromCurvesPreferShape(
                    doc,
                    style,
                    barType,
                    preferredShape: null,
                    startHookType: null,
                    endHookType: null,
                    host: host,
                    normal: planeNormal,
                    curves: curves,
                    startOrientation: RebarHookOrientation.Right,
                    endOrientation: RebarHookOrientation.Right);
                if (rb != null)
                {
                    createdBars++;
                }
                else
                {
                    failedBars++;
                }
            }
        }

        private static void CreateWallLinearRebarSetWithOptionalSplit(
            Document doc,
            Element host,
            RebarStyle style,
            RebarBarType barType,
            RebarHookType startHookType,
            RebarHookType endHookType,
            XYZ normal,
            XYZ lineStart,
            XYZ lineEnd,
            int barCount,
            double spacingFt,
            out int createdBars,
            out int failedBars,
            bool autoSplitEnabled,
            double maxSplitLengthFt,
            double splitLapLengthFt,
            RebarShape preferredShape = null)
        {
            createdBars = 0;
            failedBars = 0;

            double lengthFt = (lineStart != null && lineEnd != null) ? lineStart.DistanceTo(lineEnd) : 0.0;
            double startHookAllowanceFt = EstimateWallHookLengthAllowanceFt(startHookType, barType);
            double endHookAllowanceFt = EstimateWallHookLengthAllowanceFt(endHookType, barType);
            bool withinSplitLimit = lengthFt + startHookAllowanceFt + endHookAllowanceFt <= maxSplitLengthFt + 1e-6;

            if (!autoSplitEnabled || lengthFt <= 1e-6 || maxSplitLengthFt <= 1e-6 || withinSplitLimit)
            {
                CreateWallLinearRebarSet(
                    doc,
                    host,
                    style,
                    barType,
                    startHookType,
                    endHookType,
                    normal,
                    lineStart,
                    lineEnd,
                    barCount,
                    spacingFt,
                    out createdBars,
                    out failedBars,
                    preferredShape);
                return;
            }

            double minimumAvailableStraightFt = maxSplitLengthFt - Math.Max(startHookAllowanceFt, endHookAllowanceFt);
            double lapFt = Math.Max(MmToFeet(100.0), splitLapLengthFt);
            double maxLapForProgressFt = Math.Max(MmToFeet(50.0), minimumAvailableStraightFt - MmToFeet(50.0));
            lapFt = Math.Min(lapFt, maxLapForProgressFt);
            double advanceFt = minimumAvailableStraightFt - lapFt;
            if (advanceFt <= MmToFeet(20.0))
            {
                CreateWallLinearRebarSet(
                    doc,
                    host,
                    style,
                    barType,
                    startHookType,
                    endHookType,
                    normal,
                    lineStart,
                    lineEnd,
                    barCount,
                    spacingFt,
                    out createdBars,
                    out failedBars,
                    preferredShape);
                return;
            }

            XYZ dir = (lineEnd - lineStart).Normalize();
            double segmentStartFt = 0.0;
            const int maxIterations = 64;
            for (int iter = 0; iter < maxIterations; iter++)
            {
                bool isFirst = segmentStartFt <= 1e-6;
                double firstHookAllowanceFt = isFirst ? startHookAllowanceFt : 0.0;
                double remainingStraightFt = lengthFt - segmentStartFt;

                bool canFinishThisSegment =
                    remainingStraightFt + firstHookAllowanceFt + endHookAllowanceFt <= maxSplitLengthFt + 1e-6;

                double segmentEndFt;
                bool isLast;
                if (canFinishThisSegment)
                {
                    segmentEndFt = lengthFt;
                    isLast = true;
                }
                else
                {
                    double maxStraightThisSegmentFt = Math.Max(MmToFeet(50.0), maxSplitLengthFt - firstHookAllowanceFt);
                    segmentEndFt = Math.Min(lengthFt, segmentStartFt + maxStraightThisSegmentFt);
                    isLast = segmentEndFt >= (lengthFt - 1e-6);
                }

                XYZ segP0 = lineStart + dir.Multiply(segmentStartFt);
                XYZ segP1 = lineStart + dir.Multiply(segmentEndFt);
                CreateWallLinearRebarSet(
                    doc,
                    host,
                    style,
                    barType,
                    isFirst ? startHookType : null,
                    isLast ? endHookType : null,
                    normal,
                    segP0,
                    segP1,
                    barCount,
                    spacingFt,
                    out int segCreated,
                    out int segFailed,
                    preferredShape);
                createdBars += segCreated;
                failedBars += segFailed;

                if (isLast)
                {
                    break;
                }

                double nextStartFt = segmentEndFt - lapFt;
                if (nextStartFt <= segmentStartFt + 1e-6)
                {
                    break;
                }

                segmentStartFt = nextStartFt;
            }
        }

        private static double EstimateWallHookLengthAllowanceFt(RebarHookType hookType, RebarBarType barType)
        {
            if (hookType == null || barType == null)
            {
                return 0.0;
            }

            double diameterFt = Math.Max(0.0, GetRebarBarDiameterSafe(barType));
            if (diameterFt <= 1e-9)
            {
                return MmToFeet(120.0);
            }

            double angleDeg = 90.0;
            try
            {
                angleDeg = Math.Abs(hookType.HookAngle) * 180.0 / Math.PI;
            }
            catch
            {
                angleDeg = 90.0;
            }

            // Conservative allowance to keep total "Bar Length" at or below the split target.
            double multiplier = angleDeg >= 170.0
                ? 12.0
                : (angleDeg >= 130.0 ? 16.0 : 20.0);
            return Math.Max(MmToFeet(120.0), (diameterFt * multiplier) + MmToFeet(20.0));
        }

        private static RebarShape TryFindPreferredWallTieShape(Document doc)
        {
            if (doc == null)
            {
                return null;
            }

            List<RebarShape> shapes = new FilteredElementCollector(doc)
                .OfClass(typeof(RebarShape))
                .Cast<RebarShape>()
                .Where(x => x != null)
                .ToList();

            RebarShape byAlias = shapes.FirstOrDefault(x =>
                (x.Name ?? "").IndexOf("M_01", StringComparison.OrdinalIgnoreCase) >= 0);
            if (byAlias != null)
            {
                return byAlias;
            }

            RebarShape byCode = shapes.FirstOrDefault(x =>
            {
                string name = (x.Name ?? "").Trim();
                if (string.IsNullOrWhiteSpace(name))
                {
                    return false;
                }

                return Regex.IsMatch(
                    name,
                    @"(^|[\s_\-\[\(])0?1($|[\s_\-\]\)])",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            });
            return byCode;
        }

        private static bool TryResolveWallNaviateBarType(Document doc, string barTypeName, out RebarBarType barType)
        {
            barType = null;
            if (doc == null)
            {
                return false;
            }

            string target = (barTypeName ?? "").Trim();
            if (string.IsNullOrWhiteSpace(target))
            {
                return false;
            }

            List<RebarBarType> barTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(RebarBarType))
                .Cast<RebarBarType>()
                .Where(x => x != null)
                .ToList();

            barType = barTypes.FirstOrDefault(x =>
                string.Equals((x.Name ?? "").Trim(), target, StringComparison.OrdinalIgnoreCase));

            if (barType != null)
            {
                return true;
            }

            // Fallback: allow "DB20" to match names with extra suffix/prefix text.
            barType = barTypes.FirstOrDefault(x =>
                (x.Name ?? "").IndexOf(target, StringComparison.OrdinalIgnoreCase) >= 0);

            return barType != null;
        }

        private bool TryResolveWallNaviateDowelRequest(
            Document doc,
            WallNaviateDowelRequest dowel,
            string label,
            RebarBarType inheritedBarType,
            out RebarBarType resolvedBarType,
            out string error)
        {
            resolvedBarType = inheritedBarType;
            error = "";
            if (dowel == null)
            {
                return true;
            }

            if (!dowel.IsEnabled)
            {
                dowel.BarTypeId = ElementId.InvalidElementId;
                dowel.OverlapLengthFt = 0.0;
                resolvedBarType = inheritedBarType;
                return true;
            }

            if (inheritedBarType == null)
            {
                error = $"{label}: cannot resolve inherited main bar type.";
                return false;
            }

            RebarBarType targetBarType = inheritedBarType;
            if (!dowel.UseMainBarType)
            {
                string explicitBarTypeName = (dowel.BarTypeName ?? "").Trim();
                if (!string.IsNullOrWhiteSpace(explicitBarTypeName))
                {
                    if (!TryResolveWallNaviateBarType(doc, explicitBarTypeName, out targetBarType))
                    {
                        error = $"{label}: cannot find bar type '{explicitBarTypeName}'.";
                        return false;
                    }
                }
            }

            targetBarType = targetBarType ?? inheritedBarType;
            if (targetBarType == null)
            {
                error = $"{label}: cannot resolve dowel bar type.";
                return false;
            }

            resolvedBarType = targetBarType;
            dowel.BarTypeId = targetBarType.Id;
            dowel.BarTypeName = targetBarType.Name ?? dowel.BarTypeName ?? "";
            double diameterFt = Math.Max(0.0, GetRebarBarDiameterSafe(targetBarType));
            int multiplier = Math.Max(0, dowel.OverlapDiameterMultiplier);
            dowel.OverlapLengthFt = diameterFt * multiplier;
            return true;
        }

        private static double FeetToMmUi(double ft)
        {
            return ft * 304.8;
        }

        private void GenerateColumnRebar(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            List<ElementId> targetIds = (Request.ColumnRebarHostElementIds ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();

            if (targetIds.Count == 0 && Request.ColumnRebarHostElementId != ElementId.InvalidElementId)
            {
                targetIds.Add(Request.ColumnRebarHostElementId);
            }

            if (targetIds.Count <= 1)
            {
                if (targetIds.Count == 1)
                {
                    Request.ColumnRebarHostElementId = targetIds[0];
                }

                GenerateColumnRebarSingleHost(doc);
                return;
            }

            ElementId originalHostId = Request.ColumnRebarHostElementId;
            int requestedCount = targetIds.Count;
            int processedCount = 0;
            int validHostCount = 0;
            var floors = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (ElementId targetId in targetIds)
            {
                if (targetId == null || targetId == ElementId.InvalidElementId)
                {
                    continue;
                }

                Element host = doc.GetElement(targetId);
                if (!IsColumnRebarHostElement(host))
                {
                    continue;
                }

                validHostCount++;
                string levelName = TryGetElementLevelName(doc, host);
                if (!string.IsNullOrWhiteSpace(levelName))
                {
                    floors.Add(levelName.Trim());
                }

                Request.ColumnRebarHostElementId = targetId;
                GenerateColumnRebarSingleHost(doc);
                processedCount++;
            }

            Request.ColumnRebarHostElementId = originalHostId != ElementId.InvalidElementId
                ? originalHostId
                : targetIds.FirstOrDefault() ?? ElementId.InvalidElementId;

            if (processedCount == 0)
            {
                _window?.ShowStatus("Column Rebar: no valid selected columns available for generation.");
                return;
            }

            string floorSummary = floors.Count > 0
                ? $" across {floors.Count} floor(s)"
                : "";
            _window?.ShowStatus($"Column Rebar: processed {processedCount}/{requestedCount} selected column(s){floorSummary}. Preview uses the first selected column.");
        }

        private void GenerateColumnRebarSingleHost(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            if (Request.ColumnRebarHostElementId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Column Rebar: pick a structural column first.");
                return;
            }

            Element host = doc.GetElement(Request.ColumnRebarHostElementId);
            if (!IsColumnRebarHostElement(host))
            {
                _window?.ShowStatus("Column Rebar: selected host column is no longer available.");
                return;
            }

            if (!(doc.GetElement(Request.ColumnRebarMainBarTypeId) is RebarBarType mainBarType))
            {
                _window?.ShowStatus("Column Rebar: select a valid Main Bar Type.");
                return;
            }

            if (!(doc.GetElement(Request.ColumnRebarTieBarTypeId) is RebarBarType tieBarType))
            {
                _window?.ShowStatus("Column Rebar: select a valid Tie Bar Type.");
                return;
            }

            RebarShape outerTieShape = doc.GetElement(Request.ColumnRebarOuterTieShapeId) as RebarShape;
            RebarShape innerTieShape = doc.GetElement(Request.ColumnRebarInnerTieShapeId) as RebarShape;
            RebarHookType lineTieStartHookType = FindClosestRebarHookTypeByAngle(doc, 180.0, RebarStyle.Standard);
            RebarHookType lineTieEndHookType = FindClosestRebarHookTypeByAngle(doc, 135.0, RebarStyle.Standard);
            RebarHookType stirrupTieHookType = FindClosestRebarHookTypeByAngle(doc, 135.0, RebarStyle.StirrupTie)
                                               ?? FindClosestRebarHookTypeByAngle(doc, 135.0, RebarStyle.Standard);

            if (!RebarHostData.IsValidHost(host))
            {
                _window?.ShowStatus("Column Rebar: selected element cannot host rebar.");
                return;
            }

            if (!TryGetColumnRebarHostFrameAndBounds(host, out Transform hostTransform, out XYZ localMin, out XYZ localMax, out string error))
            {
                _window?.ShowStatus("Column Rebar: " + error);
                return;
            }

            int barsX = Math.Max(2, Request.ColumnRebarBarsX);
            int barsY = Math.Max(2, Request.ColumnRebarBarsY);
            double coverFt = Math.Max(0.0, Request.ColumnRebarCoverFt);
            double bottomOffsetFt = 0.0;
            double topOffsetFt = Math.Max(0.0, Request.ColumnRebarTopOffsetFt);
            double tieSpacingMidFtRaw = Request.ColumnRebarTieSpacingFt > 1e-9 ? Request.ColumnRebarTieSpacingFt : MmToFeet(150.0);
            double tieSpacingBottomFtRaw = Request.ColumnRebarTieSpacingBottomFt > 1e-9 ? Request.ColumnRebarTieSpacingBottomFt : tieSpacingMidFtRaw;
            double tieSpacingTopFtRaw = Request.ColumnRebarTieSpacingTopFt > 1e-9 ? Request.ColumnRebarTieSpacingTopFt : tieSpacingMidFtRaw;
            double tieSpacingBottomFt = Math.Max(MmToFeet(50.0), tieSpacingBottomFtRaw);
            double tieSpacingMidFt = Math.Max(MmToFeet(50.0), tieSpacingMidFtRaw);
            double tieSpacingTopFt = Math.Max(MmToFeet(50.0), tieSpacingTopFtRaw);
            double tieZoneBottomLengthFt = Math.Max(0.0, Request.ColumnRebarTieZoneBottomLengthFt);
            double tieZoneMiddleLengthFt = Math.Max(0.0, Request.ColumnRebarTieZoneMiddleLengthFt);
            double tieZoneTopLengthFt = Math.Max(0.0, Request.ColumnRebarTieZoneTopLengthFt);
            double tieZoneBottomPercent = Request.ColumnRebarTieZoneBottomPercent;
            double tieZoneMiddlePercent = Request.ColumnRebarTieZoneMiddlePercent;
            double tieZoneTopPercent = Request.ColumnRebarTieZoneTopPercent;
            int tieInnerLegsX = Math.Max(0, Request.ColumnRebarTieInnerLegsX);
            int tieInnerLegsY = Math.Max(0, Request.ColumnRebarTieInnerLegsY);
            List<int> selectedTieXIndices = (Request.ColumnRebarTieSelectedXIndices ?? new List<int>())
                .Where(i => i >= 0)
                .Distinct()
                .OrderBy(i => i)
                .ToList();
            List<int> selectedTieYIndices = (Request.ColumnRebarTieSelectedYIndices ?? new List<int>())
                .Where(i => i >= 0)
                .Distinct()
                .OrderBy(i => i)
                .ToList();
            List<ColumnRebarCustomLineTieSpec> customLineTieSpecs = (Request.ColumnRebarCustomLineTies ?? new List<ColumnRebarCustomLineTieSpec>())
                .Where(x => x != null)
                .ToList();
            List<ColumnRebarCustomRectTieSpec> customRectTieSpecs = (Request.ColumnRebarCustomRectTies ?? new List<ColumnRebarCustomRectTieSpec>())
                .Where(x => x != null)
                .ToList();
            bool createTies = Request.ColumnRebarCreateTies;
            int topLapBarCoveragePercent = Math.Max(0, Math.Min(100, Request.ColumnRebarTopLapBarCoveragePercent));

            double mainBarDiameterFt = GetRebarBarDiameterSafe(mainBarType);
            double tieBarDiameterFt = GetRebarBarDiameterSafe(tieBarType);
            double topLapFt = Request.ColumnRebarTopLapBarDiameterMultiplier > 0
                ? Math.Max(0.0, mainBarDiameterFt * Request.ColumnRebarTopLapBarDiameterMultiplier)
                : Math.Max(0.0, Request.ColumnRebarTopLapLengthFt);
            bool topLapMinDiameterApplied = false;
            if (topLapFt > 1e-6 && mainBarDiameterFt > 1e-9 && topLapFt < mainBarDiameterFt)
            {
                topLapFt = mainBarDiameterFt;
                topLapMinDiameterApplied = true;
            }
            double mainBarCoverLineFt = coverFt + (createTies ? tieBarDiameterFt : 0.0) + (mainBarDiameterFt * 0.5);
            double tieCenterlineCoverFt = coverFt + (tieBarDiameterFt * 0.5);

            double z0 = localMin.Z + bottomOffsetFt;
            double defaultLapStartZ = localMax.Z - topOffsetFt;
            bool hasBeamOrSlabLapReference = TryGetColumnRebarTopLapReferenceFromConnectedBeamOrSlab(
                doc,
                host,
                hostTransform,
                localMin,
                localMax,
                out double connectedTopRefRelativeFt);

            double zLapStart = hasBeamOrSlabLapReference
                ? localMin.Z + connectedTopRefRelativeFt
                : defaultLapStartZ;
            zLapStart = Math.Max(z0, Math.Min(localMax.Z, zLapStart));

            // Continuation bars should still reach the top of the host column segment.
            // Top Offset is for tie-zone termination, not for trimming the continuation main bars.
            double zContinuationTop = hasBeamOrSlabLapReference
                ? localMax.Z
                : Math.Max(z0, localMax.Z - topOffsetFt);

            double zTieTop = hasBeamOrSlabLapReference
                ? Math.Max(z0, Math.Min(zLapStart, zLapStart - topOffsetFt))
                : zContinuationTop;

            double zMainTop = zLapStart + topLapFt;
            if (zContinuationTop <= z0 + 1e-6)
            {
                _window?.ShowStatus("Column Rebar: invalid top/bottom offsets (rebar height <= 0).");
                return;
            }

            ResolveColumnRebarTieZonePercentsFromLengths(
                zTieTop - z0,
                tieZoneBottomLengthFt,
                tieZoneMiddleLengthFt,
                tieZoneTopLengthFt,
                ref tieZoneBottomPercent,
                ref tieZoneMiddlePercent,
                ref tieZoneTopPercent);

            List<XYZ> mainBarPointsLocal = BuildColumnRebarLocalMainBarPoints(localMin, localMax, barsX, barsY, mainBarCoverLineFt);
            if (mainBarPointsLocal.Count == 0)
            {
                _window?.ShowStatus("Column Rebar: cover is too large for the selected column size.");
                return;
            }

            List<List<Curve>> tieLoopsWorld = createTies
                ? BuildColumnRebarTieLoopsWorld(hostTransform, localMin, localMax, z0, zTieTop, tieCenterlineCoverFt, tieSpacingBottomFt, tieSpacingMidFt, tieSpacingTopFt, tieZoneBottomPercent, tieZoneMiddlePercent, tieZoneTopPercent)
                : new List<List<Curve>>();
            List<Curve> internalTieLinesWorld = createTies
                ? BuildColumnRebarInternalTieLinesWorld(
                    hostTransform,
                    localMin,
                    localMax,
                    z0,
                    zTieTop,
                    tieCenterlineCoverFt,
                    mainBarCoverLineFt,
                    mainBarDiameterFt,
                    barsX,
                    barsY,
                    tieSpacingBottomFt,
                    tieSpacingMidFt,
                    tieSpacingTopFt,
                    tieZoneBottomPercent,
                    tieZoneMiddlePercent,
                    tieZoneTopPercent,
                    tieInnerLegsX,
                    tieInnerLegsY,
                    selectedTieXIndices,
                    selectedTieYIndices)
                : new List<Curve>();
            List<List<Curve>> customRectTieLoopsWorld = createTies
                ? BuildColumnRebarCustomRectTieLoopsWorld(
                    hostTransform,
                    localMin,
                    localMax,
                    z0,
                    zTieTop,
                    tieCenterlineCoverFt,
                    mainBarCoverLineFt,
                    mainBarDiameterFt,
                    barsX,
                    barsY,
                    tieSpacingBottomFt,
                    tieSpacingMidFt,
                    tieSpacingTopFt,
                    tieZoneBottomPercent,
                    tieZoneMiddlePercent,
                    tieZoneTopPercent,
                    customRectTieSpecs)
                : new List<List<Curve>>();
            List<Curve> customLineTieCurvesWorld = createTies
                ? BuildColumnRebarCustomLineTiesWorld(
                    hostTransform,
                    localMin,
                    localMax,
                    z0,
                    zTieTop,
                    mainBarCoverLineFt,
                    mainBarDiameterFt,
                    barsX,
                    barsY,
                    tieSpacingBottomFt,
                    tieSpacingMidFt,
                    tieSpacingTopFt,
                    tieZoneBottomPercent,
                    tieZoneMiddlePercent,
                    tieZoneTopPercent,
                    customLineTieSpecs)
                : new List<Curve>();

            XYZ mainNormal = NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX);
            XYZ tieNormal = NormalizeOrDefault(hostTransform.BasisZ, XYZ.BasisZ);

            int mainBarsCreated = 0;
            int mainBarsFailed = 0;
            int tiesCreated = 0;
            int tiesFailed = 0;
            int internalTiesCreated = 0;
            int internalTiesFailed = 0;
            int deletedExisting = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - Generate Column Rebar"))
            {
                t.Start();

                deletedExisting = DeleteExistingColumnRebars(doc, host);

                HashSet<int> lappedMainBarIndices = BuildColumnRebarTopLapBarIndexSet(mainBarPointsLocal, topLapBarCoveragePercent);
                for (int mainBarIndex = 0; mainBarIndex < mainBarPointsLocal.Count; mainBarIndex++)
                {
                    XYZ pLocal = mainBarPointsLocal[mainBarIndex];
                    XYZ p0 = hostTransform.OfPoint(new XYZ(pLocal.X, pLocal.Y, z0));
                    XYZ p1 = hostTransform.OfPoint(new XYZ(pLocal.X, pLocal.Y, zContinuationTop));
                    if (p0.DistanceTo(p1) <= 1e-6)
                    {
                        continue;
                    }

                    try
                    {
                        Rebar rb = Rebar.CreateFromCurves(
                            doc,
                            RebarStyle.Standard,
                            mainBarType,
                            null,
                            null,
                            host,
                            mainNormal,
                            new List<Curve> { Line.CreateBound(p0, p1) },
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right,
                            true,
                            true);

                        if (rb != null)
                        {
                            mainBarsCreated++;
                        }
                        else
                        {
                            mainBarsFailed++;
                        }
                    }
                    catch
                    {
                        mainBarsFailed++;
                    }

                    if (!hasBeamOrSlabLapReference || topLapFt <= 1e-6 || !lappedMainBarIndices.Contains(mainBarIndex))
                    {
                        continue;
                    }

                    // Additional lap/end rebar condition: starts at beam/slab top and ends at lap length above.
                    XYZ pLap0 = hostTransform.OfPoint(new XYZ(pLocal.X, pLocal.Y, zLapStart));
                    XYZ pLap1 = hostTransform.OfPoint(new XYZ(pLocal.X, pLocal.Y, zMainTop));
                    if (pLap0.DistanceTo(pLap1) <= 1e-6)
                    {
                        continue;
                    }

                    try
                    {
                        double lapBendOffsetFt = Math.Max(mainBarDiameterFt, MmToFeet(5.0));
                        List<Curve> lapCurves = null;
                        XYZ lapPlaneNormal = mainNormal;
                        if (TryBuildColumnRebarBentLapBarCurvesWorld(
                            hostTransform,
                            localMin,
                            localMax,
                            pLocal,
                            zLapStart,
                            zMainTop,
                            lapBendOffsetFt,
                            out List<Curve> bentLapCurves,
                            out XYZ bentLapPlaneNormal))
                        {
                            lapCurves = bentLapCurves;
                            lapPlaneNormal = bentLapPlaneNormal;
                        }
                        else
                        {
                            lapCurves = new List<Curve> { Line.CreateBound(pLap0, pLap1) };
                        }

                        Rebar lapBar = Rebar.CreateFromCurves(
                            doc,
                            RebarStyle.Standard,
                            mainBarType,
                            null,
                            null,
                            host,
                            lapPlaneNormal,
                            lapCurves,
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right,
                            true,
                            true);

                        if (lapBar != null)
                        {
                            mainBarsCreated++;
                        }
                        else
                        {
                            mainBarsFailed++;
                        }
                    }
                    catch
                    {
                        mainBarsFailed++;
                    }
                }

                if (createTies)
                {
                    foreach (List<Curve> tieLoop in tieLoopsWorld)
                    {
                        if (tieLoop == null || tieLoop.Count < 4)
                        {
                            continue;
                        }

                    try
                    {
                        Rebar tie = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.StirrupTie,
                            tieBarType,
                            outerTieShape,
                            null,
                            null,
                            host,
                            tieNormal,
                            tieLoop,
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);

                            if (tie != null)
                            {
                                tiesCreated++;
                            }
                            else
                            {
                                tiesFailed++;
                            }
                        }
                        catch
                        {
                            tiesFailed++;
                        }
                    }

                    foreach (List<Curve> tieLoop in customRectTieLoopsWorld)
                    {
                        if (tieLoop == null || tieLoop.Count < 4)
                        {
                            continue;
                        }

                    try
                    {
                        // Draw Rect Tie in section should follow the same rectangle tie shape standard (e.g. M_T1).
                        Rebar tie = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.StirrupTie,
                            tieBarType,
                            outerTieShape,
                            null,
                            null,
                            host,
                            tieNormal,
                            tieLoop,
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);

                            if (tie != null)
                            {
                                internalTiesCreated++;
                            }
                            else
                            {
                                internalTiesFailed++;
                            }
                        }
                        catch
                        {
                            internalTiesFailed++;
                        }
                    }

                    foreach (Curve internalTieCurve in internalTieLinesWorld)
                    {
                        if (internalTieCurve == null || internalTieCurve.Length <= 1e-6)
                        {
                            continue;
                        }

                    try
                    {
                        Rebar tieLine = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.Standard,
                            tieBarType,
                            innerTieShape,
                            lineTieStartHookType,
                            lineTieEndHookType,
                            host,
                            tieNormal,
                            new List<Curve> { internalTieCurve },
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);

                            if (tieLine != null)
                            {
                                internalTiesCreated++;
                            }
                            else
                            {
                                internalTiesFailed++;
                            }
                        }
                        catch
                        {
                            internalTiesFailed++;
                        }
                    }

                    foreach (Curve internalTieCurve in customLineTieCurvesWorld)
                    {
                        if (internalTieCurve == null || internalTieCurve.Length <= 1e-6)
                        {
                            continue;
                        }

                    try
                    {
                        Rebar tieLine = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.Standard,
                            tieBarType,
                            innerTieShape,
                            lineTieStartHookType,
                            lineTieEndHookType,
                            host,
                            tieNormal,
                            new List<Curve> { internalTieCurve },
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);

                            if (tieLine != null)
                            {
                                internalTiesCreated++;
                            }
                            else
                            {
                                internalTiesFailed++;
                            }
                        }
                        catch
                        {
                            internalTiesFailed++;
                        }
                    }
                }

                t.Commit();
            }

            _window?.ShowStatus(
                $"Column Rebar: host {host.Id.Value}, deleted existing {deletedExisting}, main bars {mainBarsCreated} (failed {mainBarsFailed}), " +
                $"outer ties {tiesCreated} (failed {tiesFailed}), internal ties {internalTiesCreated} (failed {internalTiesFailed}), top lap {FeetToMm(topLapFt):0.#} mm ({topLapBarCoveragePercent}%)." +
                (topLapMinDiameterApplied ? $" Min lap enforced to 1Ø ({FeetToMm(mainBarDiameterFt):0.#} mm)." : ""));
        }

        private static bool TryBuildColumnRebarBentLapBarCurvesWorld(
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            XYZ mainBarPointLocal,
            double zLapStartLocalFt,
            double zLapTopLocalFt,
            double requestedOffsetFt,
            out List<Curve> curvesWorld,
            out XYZ planeNormalWorld)
        {
            curvesWorld = null;
            planeNormalWorld = XYZ.BasisX;

            if (hostTransform == null || mainBarPointLocal == null)
            {
                return false;
            }

            if (requestedOffsetFt <= 1e-6 || zLapTopLocalFt <= zLapStartLocalFt + 1e-6)
            {
                return false;
            }

            double centerX = (localMin.X + localMax.X) * 0.5;
            double centerY = (localMin.Y + localMax.Y) * 0.5;
            double halfX = Math.Max(1e-6, (localMax.X - localMin.X) * 0.5);
            double halfY = Math.Max(1e-6, (localMax.Y - localMin.Y) * 0.5);

            double xNorm = (mainBarPointLocal.X - centerX) / halfX;
            double yNorm = (mainBarPointLocal.Y - centerY) / halfY;
            bool offsetAlongX = Math.Abs(xNorm) >= Math.Abs(yNorm);

            // Bend the lap bar toward the column core so it remains inside the column cage.
            double dx = 0.0;
            double dy = 0.0;
            if (offsetAlongX)
            {
                dx = mainBarPointLocal.X >= centerX ? -requestedOffsetFt : requestedOffsetFt;
                planeNormalWorld = NormalizeOrDefault(hostTransform.BasisY, XYZ.BasisY);
            }
            else
            {
                dy = mainBarPointLocal.Y >= centerY ? -requestedOffsetFt : requestedOffsetFt;
                planeNormalWorld = NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX);
            }

            if (Math.Abs(dx) <= 1e-6 && Math.Abs(dy) <= 1e-6)
            {
                return false;
            }

            XYZ p0Local = new XYZ(mainBarPointLocal.X, mainBarPointLocal.Y, zLapStartLocalFt);
            XYZ p1Local = new XYZ(mainBarPointLocal.X + dx, mainBarPointLocal.Y + dy, zLapStartLocalFt);
            XYZ p2Local = new XYZ(mainBarPointLocal.X + dx, mainBarPointLocal.Y + dy, zLapTopLocalFt);

            XYZ p0 = hostTransform.OfPoint(p0Local);
            XYZ p1 = hostTransform.OfPoint(p1Local);
            XYZ p2 = hostTransform.OfPoint(p2Local);

            var curves = new List<Curve>();
            if (p0.DistanceTo(p1) > 1e-6)
            {
                curves.Add(Line.CreateBound(p0, p1));
            }

            if (p1.DistanceTo(p2) > 1e-6)
            {
                curves.Add(Line.CreateBound(p1, p2));
            }

            if (curves.Count == 0)
            {
                return false;
            }

            curvesWorld = curves;
            return true;
        }

        private sealed class FoundationRebarHostGenerationStats
        {
            public int DeletedExisting { get; set; }
            public int TopMainBarsCreated { get; set; }
            public int TopMainBarsFailed { get; set; }
            public int TopDistributionBarsCreated { get; set; }
            public int TopDistributionBarsFailed { get; set; }
            public int BottomMainBarsCreated { get; set; }
            public int BottomMainBarsFailed { get; set; }
            public int BottomDistributionBarsCreated { get; set; }
            public int BottomDistributionBarsFailed { get; set; }
            public int LinksCreated { get; set; }
            public int LinksFailed { get; set; }
            public int StartersCreated { get; set; }
            public int StartersFailed { get; set; }
        }

        private static bool TryParseFoundationNaviateCountBarSpec(string text, out int barCount)
        {
            barCount = 0;
            string raw = (text ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            string compact = raw.Replace(" ", "");
            int firstLetterIndex = -1;
            for (int i = 0; i < compact.Length; i++)
            {
                if (char.IsLetter(compact[i]))
                {
                    firstLetterIndex = i;
                    break;
                }
            }

            if (firstLetterIndex <= 0)
            {
                return false;
            }

            string countPart = compact.Substring(0, firstLetterIndex).ToUpperInvariant()
                .Replace("Nº", "")
                .Replace("N°", "")
                .Replace("NO.", "")
                .Replace("NO", "");

            if (countPart.EndsWith("X", StringComparison.OrdinalIgnoreCase) ||
                countPart.EndsWith("*", StringComparison.OrdinalIgnoreCase))
            {
                countPart = countPart.Substring(0, countPart.Length - 1);
            }

            if (!int.TryParse(countPart, NumberStyles.Integer, CultureInfo.InvariantCulture, out barCount))
            {
                return false;
            }

            return barCount >= 2;
        }

        private static bool TryConvertFoundationBarCountToSpacingFt(int barCount, double dimensionFt, double sideCoverFt, out double spacingFt)
        {
            spacingFt = 0.0;
            if (barCount < 2 || dimensionFt <= 1e-9)
            {
                return false;
            }

            double usableFt = Math.Max(0.0, dimensionFt - (2.0 * Math.Max(0.0, sideCoverFt)));
            if (usableFt <= 1e-9)
            {
                return false;
            }

            spacingFt = usableFt / Math.Max(1, barCount - 1);
            return spacingFt > 1e-9 && !double.IsNaN(spacingFt) && !double.IsInfinity(spacingFt);
        }

        private static bool TryResolveFoundationNaviateLayerAxisSpacingFt(
            FoundationNaviateLayerRequest layer,
            bool isXAxis,
            double dimensionFt,
            double sideCoverFt,
            double fallbackSpacingFt,
            out double spacingFt)
        {
            spacingFt = fallbackSpacingFt > 1e-9 ? fallbackSpacingFt : MmToFeet(150.0);
            if (layer == null)
            {
                return false;
            }

            if (isXAxis && layer.XSpacingFt > 1e-9)
            {
                spacingFt = layer.XSpacingFt;
            }
            else if (!isXAxis && layer.YSpacingFt > 1e-9)
            {
                spacingFt = layer.YSpacingFt;
            }
            else if (layer.QuantityInputMode == FoundationNaviateQuantityInputMode.Spacing && layer.SpacingFt > 1e-9)
            {
                spacingFt = layer.SpacingFt;
            }

            string spec = isXAxis ? (layer.XDirectionSpec ?? "") : (layer.YDirectionSpec ?? "");
            if (TryParseFoundationNaviateCountBarSpec(spec, out int barCount) &&
                TryConvertFoundationBarCountToSpacingFt(barCount, dimensionFt, sideCoverFt, out double countBasedSpacingFt))
            {
                spacingFt = countBasedSpacingFt;
                return true;
            }

            if (layer.QuantityInputMode == FoundationNaviateQuantityInputMode.NumberOfBars &&
                layer.NumberOfBars >= 2 &&
                TryConvertFoundationBarCountToSpacingFt(layer.NumberOfBars, dimensionFt, sideCoverFt, out double genericCountSpacingFt))
            {
                spacingFt = genericCountSpacingFt;
                return true;
            }

            return false;
        }

        private void ApplyFoundationNaviateCompatibilityToLegacyRequest()
        {
            if (!Request.FoundationRebarUseNaviateDataModel || Request.FoundationRebarNaviate == null)
            {
                return;
            }

            FoundationNaviateRebarRequest nav = Request.FoundationRebarNaviate;

            Request.FoundationRebarDeleteExisting = nav.DeleteExistingRebar;
            Request.FoundationRebarTopCoverFt = nav.TopCoverFt > 0.0 ? nav.TopCoverFt : Request.FoundationRebarTopCoverFt;
            Request.FoundationRebarBottomCoverFt = nav.BottomCoverFt > 0.0 ? nav.BottomCoverFt : Request.FoundationRebarBottomCoverFt;
            Request.FoundationRebarSideCoverFt = nav.SideCoverFt > 0.0 ? nav.SideCoverFt : Request.FoundationRebarSideCoverFt;

            if (nav.TopBars != null)
            {
                Request.FoundationRebarCreateTopBars = nav.TopBars.IsEnabled;
                if (nav.TopBars.XSpacingFt > 1e-9) Request.FoundationRebarTopSpacingXFt = nav.TopBars.XSpacingFt;
                if (nav.TopBars.YSpacingFt > 1e-9) Request.FoundationRebarTopSpacingYFt = nav.TopBars.YSpacingFt;
                if (nav.TopBars.LapLengthFt > 1e-9) Request.FoundationRebarTopLapLengthFt = nav.TopBars.LapLengthFt;
            }

            if (nav.BottomBars != null)
            {
                Request.FoundationRebarCreateBottomBars = nav.BottomBars.IsEnabled;
                if (nav.BottomBars.XSpacingFt > 1e-9) Request.FoundationRebarBottomSpacingXFt = nav.BottomBars.XSpacingFt;
                if (nav.BottomBars.YSpacingFt > 1e-9) Request.FoundationRebarBottomSpacingYFt = nav.BottomBars.YSpacingFt;
                if (nav.BottomBars.LapLengthFt > 1e-9) Request.FoundationRebarBottomLapLengthFt = nav.BottomBars.LapLengthFt;
            }

            if (nav.SideBars != null)
            {
                Request.FoundationRebarCreateLinks = nav.SideBars.IsEnabled;
                if (nav.SideBars.BarTypeId != ElementId.InvalidElementId)
                {
                    Request.FoundationRebarLinkBarTypeId = nav.SideBars.BarTypeId;
                }
                if (nav.SideBars.BottomTieSpacingFt > 1e-9) Request.FoundationRebarBottomTieSpacingFt = nav.SideBars.BottomTieSpacingFt;
                if (nav.SideBars.MidTieSpacingFt > 1e-9) Request.FoundationRebarMidTieSpacingFt = nav.SideBars.MidTieSpacingFt;
                if (nav.SideBars.TopTieSpacingFt > 1e-9) Request.FoundationRebarTopTieSpacingFt = nav.SideBars.TopTieSpacingFt;
                if (nav.SideBars.BottomZoneLengthFt >= 0.0) Request.FoundationRebarBottomZoneLengthFt = nav.SideBars.BottomZoneLengthFt;
                if (nav.SideBars.MidZoneLengthFt >= 0.0) Request.FoundationRebarMidZoneLengthFt = nav.SideBars.MidZoneLengthFt;
                if (nav.SideBars.TopZoneLengthFt >= 0.0) Request.FoundationRebarTopZoneLengthFt = nav.SideBars.TopZoneLengthFt;
            }

            if (nav.ColumnStarterBars != null)
            {
                Request.FoundationRebarIncludeStarterBars = nav.ColumnStarterBars.IsEnabled;
            }
        }

        private void GenerateFoundationRebar(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            if (Request.FoundationRebarHostElementId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("FOUNDATION: pick a host first.");
                return;
            }

            ApplyFoundationNaviateCompatibilityToLegacyRequest();

            Element seedHost = doc.GetElement(Request.FoundationRebarHostElementId);
            if (!IsFoundationRebarHostElement(seedHost))
            {
                _window?.ShowStatus("FOUNDATION: selected host is no longer available or not a valid foundation host.");
                return;
            }

            if (!(doc.GetElement(Request.FoundationRebarMainBarTypeId) is RebarBarType mainBarType))
            {
                _window?.ShowStatus("FOUNDATION: select a valid Top/Bottom Main bar type.");
                return;
            }

            if (!(doc.GetElement(Request.FoundationRebarDistributionBarTypeId) is RebarBarType distributionBarType))
            {
                _window?.ShowStatus("FOUNDATION: select a valid Distribution bar type.");
                return;
            }

            RebarBarType linkBarType = null;
            if (Request.FoundationRebarCreateLinks)
            {
                if (!(doc.GetElement(Request.FoundationRebarLinkBarTypeId) is RebarBarType resolvedLinkBarType))
                {
                    _window?.ShowStatus("FOUNDATION: select a valid Link/Stirrup bar type.");
                    return;
                }

                linkBarType = resolvedLinkBarType;
            }

            List<Element> targetHosts = ResolveFoundationRebarTargetHosts(doc, seedHost, Request.FoundationRebarApplyToSameType);
            if (targetHosts.Count == 0)
            {
                _window?.ShowStatus("FOUNDATION: no valid target hosts found for generation.");
                return;
            }

            int hostsSucceeded = 0;
            int hostsFailed = 0;
            int deletedExistingTotal = 0;
            int topMainCreatedTotal = 0;
            int topMainFailedTotal = 0;
            int topDistCreatedTotal = 0;
            int topDistFailedTotal = 0;
            int bottomMainCreatedTotal = 0;
            int bottomMainFailedTotal = 0;
            int bottomDistCreatedTotal = 0;
            int bottomDistFailedTotal = 0;
            int linksCreatedTotal = 0;
            int linksFailedTotal = 0;
            int startersCreatedTotal = 0;
            int startersFailedTotal = 0;
            string firstError = "";

            string transactionName = Request.FoundationRebarApplyToSameType
                ? "CamboBIM - Generate Foundation Rebar (Same Type)"
                : "CamboBIM - Generate Foundation Rebar";

            TransactionStatus commitStatus = TransactionStatus.Uninitialized;
            using (Transaction t = new Transaction(doc, transactionName))
            {
                t.Start();

                foreach (Element host in targetHosts)
                {
                    if (host == null)
                    {
                        hostsFailed++;
                        continue;
                    }

                    if (!TryGenerateFoundationRebarForHost(
                        doc,
                        host,
                        mainBarType,
                        distributionBarType,
                        linkBarType,
                        out FoundationRebarHostGenerationStats stats,
                        out string error))
                    {
                        hostsFailed++;
                        if (string.IsNullOrWhiteSpace(firstError) && !string.IsNullOrWhiteSpace(error))
                        {
                            firstError = $"Host {host.Id.Value}: {error}";
                        }
                        continue;
                    }

                    hostsSucceeded++;
                    deletedExistingTotal += stats.DeletedExisting;
                    topMainCreatedTotal += stats.TopMainBarsCreated;
                    topMainFailedTotal += stats.TopMainBarsFailed;
                    topDistCreatedTotal += stats.TopDistributionBarsCreated;
                    topDistFailedTotal += stats.TopDistributionBarsFailed;
                    bottomMainCreatedTotal += stats.BottomMainBarsCreated;
                    bottomMainFailedTotal += stats.BottomMainBarsFailed;
                    bottomDistCreatedTotal += stats.BottomDistributionBarsCreated;
                    bottomDistFailedTotal += stats.BottomDistributionBarsFailed;
                    linksCreatedTotal += stats.LinksCreated;
                    linksFailedTotal += stats.LinksFailed;
                    startersCreatedTotal += stats.StartersCreated;
                    startersFailedTotal += stats.StartersFailed;
                }

                commitStatus = t.Commit();
            }

            if (commitStatus != TransactionStatus.Committed)
            {
                _window?.ShowStatus("FOUNDATION: Rebar generation was cancelled or failed to commit. Review Revit error dialog and parameters.");
                return;
            }

            string scopeLabel = Request.FoundationRebarApplyToSameType ? "same type" : "selected host";
            string summary =
                $"FOUNDATION: Generated on {hostsSucceeded}/{targetHosts.Count} host(s) ({scopeLabel}), deleted existing {deletedExistingTotal}. " +
                $"Top M/D {topMainCreatedTotal}/{topDistCreatedTotal} (failed {topMainFailedTotal}/{topDistFailedTotal}), " +
                $"Bottom M/D {bottomMainCreatedTotal}/{bottomDistCreatedTotal} (failed {bottomMainFailedTotal}/{bottomDistFailedTotal}), " +
                $"Links {linksCreatedTotal} (failed {linksFailedTotal}), Starters {startersCreatedTotal} (failed {startersFailedTotal}).";
            if (!string.IsNullOrWhiteSpace(firstError))
            {
                summary += " " + firstError;
            }

            _window?.ShowStatus(summary);
        }

        private bool TryGenerateFoundationRebarForHost(
            Document doc,
            Element host,
            RebarBarType mainBarType,
            RebarBarType distributionBarType,
            RebarBarType linkBarType,
            out FoundationRebarHostGenerationStats stats,
            out string error)
        {
            stats = new FoundationRebarHostGenerationStats();
            error = "";

            if (doc == null || host == null)
            {
                error = "host is not available.";
                return false;
            }

            if (!RebarHostData.IsValidHost(host))
            {
                error = "selected element cannot host rebar.";
                return false;
            }

            if (!TryGetFoundationRebarHostFrameAndBounds(host, out Transform hostTransform, out XYZ localMin, out XYZ localMax, out error))
            {
                return false;
            }

            double lengthFt = Math.Max(0.0, localMax.X - localMin.X);
            double widthFt = Math.Max(0.0, localMax.Y - localMin.Y);
            double thicknessFt = Math.Max(0.0, localMax.Z - localMin.Z);
            if (lengthFt <= 1e-6 || widthFt <= 1e-6 || thicknessFt <= 1e-6)
            {
                error = "host geometry size is invalid.";
                return false;
            }

            double mainDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(mainBarType));
            double distDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(distributionBarType));
            double linkDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(linkBarType));
            double planDiaMaxFt = Math.Max(mainDiaFt, distDiaFt);

            double sideCoverCenterFt = Math.Max(0.0, Request.FoundationRebarSideCoverFt) + (planDiaMaxFt * 0.5);
            double topCoverCenterFt = Math.Max(0.0, Request.FoundationRebarTopCoverFt) + (planDiaMaxFt * 0.5);
            double bottomCoverCenterFt = Math.Max(0.0, Request.FoundationRebarBottomCoverFt) + (planDiaMaxFt * 0.5);

            double x0 = localMin.X + sideCoverCenterFt;
            double x1 = localMax.X - sideCoverCenterFt;
            double y0 = localMin.Y + sideCoverCenterFt;
            double y1 = localMax.Y - sideCoverCenterFt;
            double zTop = localMax.Z - topCoverCenterFt;
            double zBottom = localMin.Z + bottomCoverCenterFt;

            if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6 || zTop <= zBottom + 1e-6)
            {
                error = "cover values are too large for the selected foundation size.";
                return false;
            }

            XYZ barPlaneNormal = NormalizeOrDefault(hostTransform.BasisZ, XYZ.BasisZ);
            XYZ starterNormal = NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX);

            bool createTopBars = Request.FoundationRebarCreateTopBars;
            bool createBottomBars = Request.FoundationRebarCreateBottomBars;
            bool createLinks = Request.FoundationRebarCreateLinks;
            bool includeStarterBars = Request.FoundationRebarIncludeStarterBars;

            double topSpacingXFt = Request.FoundationRebarTopSpacingXFt;
            double topSpacingYFt = Request.FoundationRebarTopSpacingYFt;
            double bottomSpacingXFt = Request.FoundationRebarBottomSpacingXFt;
            double bottomSpacingYFt = Request.FoundationRebarBottomSpacingYFt;

            bool topSwapMainDistributionByDirection = false;
            bool bottomSwapMainDistributionByDirection = false;
            FoundationNaviateLayerRequest navTopLayer = null;
            FoundationNaviateLayerRequest navBottomLayer = null;
            FoundationNaviateSideBarsRequest navSideBars = null;

            FoundationNaviateRebarRequest nav = (Request.FoundationRebarUseNaviateDataModel && Request.FoundationRebarNaviate != null)
                ? Request.FoundationRebarNaviate
                : null;
            if (nav != null)
            {
                if (nav.TopBars != null)
                {
                    navTopLayer = nav.TopBars;
                    createTopBars = nav.TopBars.IsEnabled;
                    topSwapMainDistributionByDirection =
                        nav.TopBars.MainLayerDirection == FoundationNaviateMainLayerDirection.TransversalBars;
                    TryResolveFoundationNaviateLayerAxisSpacingFt(
                        nav.TopBars,
                        isXAxis: true,
                        dimensionFt: widthFt,
                        sideCoverFt: Math.Max(0.0, Request.FoundationRebarSideCoverFt),
                        fallbackSpacingFt: topSpacingXFt,
                        out topSpacingXFt);
                    TryResolveFoundationNaviateLayerAxisSpacingFt(
                        nav.TopBars,
                        isXAxis: false,
                        dimensionFt: lengthFt,
                        sideCoverFt: Math.Max(0.0, Request.FoundationRebarSideCoverFt),
                        fallbackSpacingFt: topSpacingYFt,
                        out topSpacingYFt);
                }

                if (nav.BottomBars != null)
                {
                    navBottomLayer = nav.BottomBars;
                    createBottomBars = nav.BottomBars.IsEnabled;
                    bottomSwapMainDistributionByDirection =
                        nav.BottomBars.MainLayerDirection == FoundationNaviateMainLayerDirection.TransversalBars;
                    TryResolveFoundationNaviateLayerAxisSpacingFt(
                        nav.BottomBars,
                        isXAxis: true,
                        dimensionFt: widthFt,
                        sideCoverFt: Math.Max(0.0, Request.FoundationRebarSideCoverFt),
                        fallbackSpacingFt: bottomSpacingXFt,
                        out bottomSpacingXFt);
                    TryResolveFoundationNaviateLayerAxisSpacingFt(
                        nav.BottomBars,
                        isXAxis: false,
                        dimensionFt: lengthFt,
                        sideCoverFt: Math.Max(0.0, Request.FoundationRebarSideCoverFt),
                        fallbackSpacingFt: bottomSpacingYFt,
                        out bottomSpacingYFt);
                }

                if (nav.SideBars != null)
                {
                    navSideBars = nav.SideBars;
                    createLinks = nav.SideBars.IsEnabled;
                }

                if (nav.ColumnStarterBars != null)
                {
                    includeStarterBars = nav.ColumnStarterBars.IsEnabled;
                }
            }

            if (Request.FoundationRebarDeleteExisting)
            {
                stats.DeletedExisting = DeleteExistingColumnRebars(doc, host);
            }

            if (createTopBars)
            {
                int topMainCreated = 0;
                int topMainFailed = 0;
                int topDistCreated = 0;
                int topDistFailed = 0;
                CreateFoundationRebarBarsAtLevel(
                    doc, host, hostTransform, x0, x1, y0, y1, zTop, zBottom, zTop, isTopLayer: true,
                    topSpacingXFt,
                    topSpacingYFt,
                    topSwapMainDistributionByDirection ? distributionBarType : mainBarType,
                    topSwapMainDistributionByDirection ? mainBarType : distributionBarType,
                    barPlaneNormal,
                    navTopLayer,
                    ref topMainCreated,
                    ref topMainFailed,
                    ref topDistCreated,
                    ref topDistFailed);
                stats.TopMainBarsCreated += topMainCreated;
                stats.TopMainBarsFailed += topMainFailed;
                stats.TopDistributionBarsCreated += topDistCreated;
                stats.TopDistributionBarsFailed += topDistFailed;
            }

            if (createBottomBars)
            {
                int bottomMainCreated = 0;
                int bottomMainFailed = 0;
                int bottomDistCreated = 0;
                int bottomDistFailed = 0;
                CreateFoundationRebarBarsAtLevel(
                    doc, host, hostTransform, x0, x1, y0, y1, zBottom, zBottom, zTop, isTopLayer: false,
                    bottomSpacingXFt,
                    bottomSpacingYFt,
                    bottomSwapMainDistributionByDirection ? distributionBarType : mainBarType,
                    bottomSwapMainDistributionByDirection ? mainBarType : distributionBarType,
                    barPlaneNormal,
                    navBottomLayer,
                    ref bottomMainCreated,
                    ref bottomMainFailed,
                    ref bottomDistCreated,
                    ref bottomDistFailed);
                stats.BottomMainBarsCreated += bottomMainCreated;
                stats.BottomMainBarsFailed += bottomMainFailed;
                stats.BottomDistributionBarsCreated += bottomDistCreated;
                stats.BottomDistributionBarsFailed += bottomDistFailed;
            }

            if (createLinks && linkBarType != null)
            {
                int linksCreated = 0;
                int linksFailed = 0;
                CreateFoundationRebarLinks(
                    doc,
                    host,
                    hostTransform,
                    localMin,
                    localMax,
                    x0,
                    x1,
                    y0,
                    y1,
                    zBottom,
                    zTop,
                    linkDiaFt,
                    linkBarType,
                    barPlaneNormal,
                    navSideBars,
                    ref linksCreated,
                    ref linksFailed);
                stats.LinksCreated += linksCreated;
                stats.LinksFailed += linksFailed;
            }

            if (includeStarterBars)
            {
                int startersCreated = 0;
                int startersFailed = 0;
                CreateFoundationStarterBars(
                    doc,
                    host,
                    hostTransform,
                    localMin,
                    localMax,
                    x0,
                    x1,
                    y0,
                    y1,
                    zBottom,
                    mainBarType,
                    starterNormal,
                    ref startersCreated,
                    ref startersFailed);
                stats.StartersCreated += startersCreated;
                stats.StartersFailed += startersFailed;
            }

            return true;
        }

        private void CreateFoundationRebarBarsAtLevel(
            Document doc,
            Element host,
            Transform hostTransform,
            double x0,
            double x1,
            double y0,
            double y1,
            double z,
            double zBottomLimit,
            double zTopLimit,
            bool isTopLayer,
            double spacingXFt,
            double spacingYFt,
            RebarBarType mainBarType,
            RebarBarType distributionBarType,
            XYZ planeNormal,
            FoundationNaviateLayerRequest navLayer,
            ref int mainCreated,
            ref int mainFailed,
            ref int distributionCreated,
            ref int distributionFailed)
        {
            if (doc == null || host == null || hostTransform == null || mainBarType == null || distributionBarType == null)
            {
                return;
            }

            if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6)
            {
                return;
            }

            double requestedLapLengthFt = Math.Max(0.0, navLayer?.LapLengthFt ?? 0.0);
            string selectedShapeCode = (navLayer?.ShapeCode ?? "").Trim();
            bool shapeSelectionIsNone = string.IsNullOrWhiteSpace(selectedShapeCode) ||
                                        string.Equals(selectedShapeCode, "None", StringComparison.OrdinalIgnoreCase);
            // Naviate-style Shape 21 for top/bottom bars represents a U-bar with a real leg/lap length.
            // When lap = 0 (continuous bars), forcing Shape 21 creates tiny U-bars that often trigger
            // "Can't solve Rebar Shape" errors on commit. Fall back to straight bars in that case.
            bool selectedShapeIs21 = IsFoundationNaviateShapeCode(selectedShapeCode, "21");
            bool useShape21 = selectedShapeIs21 && requestedLapLengthFt > 1e-6;
            RebarShape preferredUShape = useShape21 ? FindRebarShapeByCode(doc, "21", RebarStyle.Standard) : null;
            RebarShape preferredLinearShape =
                (!shapeSelectionIsNone && !selectedShapeIs21)
                    ? FindRebarShapeByCode(doc, selectedShapeCode, RebarStyle.Standard)
                    : null;
            RebarHookType startHookType = ResolveFoundationNaviateHookType(doc, navLayer?.HookAtStart, RebarStyle.Standard);
            RebarHookType endHookType = ResolveFoundationNaviateHookType(doc, navLayer?.HookAtEnd, RebarStyle.Standard);
            XYZ mainPlaneNormal = NormalizeOrDefault(hostTransform.BasisY, XYZ.BasisY); // XZ plane for X-direction bars
            XYZ distPlaneNormal = NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX); // YZ plane for Y-direction bars

            foreach (double y in BuildFoundationRebarPositionsBySpacing(y0, y1, spacingXFt))
            {
                XYZ p0 = hostTransform.OfPoint(new XYZ(x0, y, z));
                XYZ p1 = hostTransform.OfPoint(new XYZ(x1, y, z));
                if (p0.DistanceTo(p1) <= 1e-6)
                {
                    continue;
                }

                try
                {
                    Rebar rb;
                    if (useShape21 &&
                        TryBuildFoundationShape21UBarCurves(
                            hostTransform,
                            x0,
                            x1,
                            y,
                            z,
                            zBottomLimit,
                            zTopLimit,
                            isTopLayer,
                            Math.Max(requestedLapLengthFt, Math.Max(0.0, GetRebarBarDiameterSafe(mainBarType))),
                            alongXAxis: true,
                            out List<Curve> uCurves))
                    {
                        rb = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.Standard,
                            mainBarType,
                            preferredUShape,
                            startHookType,
                            endHookType,
                            host,
                            mainPlaneNormal,
                            uCurves,
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);
                    }
                    else
                    {
                        rb = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.Standard,
                            mainBarType,
                            preferredLinearShape,
                            startHookType,
                            endHookType,
                            host,
                            planeNormal,
                            new List<Curve> { Line.CreateBound(p0, p1) },
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);
                    }

                    if (rb != null) mainCreated++;
                    else mainFailed++;
                }
                catch
                {
                    mainFailed++;
                }
            }

            foreach (double x in BuildFoundationRebarPositionsBySpacing(x0, x1, spacingYFt))
            {
                XYZ p0 = hostTransform.OfPoint(new XYZ(x, y0, z));
                XYZ p1 = hostTransform.OfPoint(new XYZ(x, y1, z));
                if (p0.DistanceTo(p1) <= 1e-6)
                {
                    continue;
                }

                try
                {
                    Rebar rb;
                    if (useShape21 &&
                        TryBuildFoundationShape21UBarCurves(
                            hostTransform,
                            y0,
                            y1,
                            x,
                            z,
                            zBottomLimit,
                            zTopLimit,
                            isTopLayer,
                            Math.Max(requestedLapLengthFt, Math.Max(0.0, GetRebarBarDiameterSafe(distributionBarType))),
                            alongXAxis: false,
                            out List<Curve> uCurves))
                    {
                        rb = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.Standard,
                            distributionBarType,
                            preferredUShape,
                            startHookType,
                            endHookType,
                            host,
                            distPlaneNormal,
                            uCurves,
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);
                    }
                    else
                    {
                        rb = CreateRebarFromCurvesPreferShape(
                            doc,
                            RebarStyle.Standard,
                            distributionBarType,
                            preferredLinearShape,
                            startHookType,
                            endHookType,
                            host,
                            planeNormal,
                            new List<Curve> { Line.CreateBound(p0, p1) },
                            RebarHookOrientation.Right,
                            RebarHookOrientation.Right);
                    }

                    if (rb != null) distributionCreated++;
                    else distributionFailed++;
                }
                catch
                {
                    distributionFailed++;
                }
            }
        }

        private void CreateFoundationRebarLinks(
            Document doc,
            Element host,
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            double x0,
            double x1,
            double y0,
            double y1,
            double zBottom,
            double zTop,
            double linkDiaFt,
            RebarBarType linkBarType,
            XYZ tiePlaneNormal,
            FoundationNaviateSideBarsRequest navSideBars,
            ref int linksCreated,
            ref int linksFailed)
        {
            if (doc == null || host == null || hostTransform == null || linkBarType == null)
            {
                return;
            }

            if (localMin == null || localMax == null)
            {
                return;
            }

            // Link/stirrup cage should wrap around the mat bars, not sit only on internal horizontal levels.
            double sideCoverLinkFt = Math.Max(0.0, Request.FoundationRebarSideCoverFt) + Math.Max(0.0, linkDiaFt * 0.5);
            double topCoverLinkFt = Math.Max(0.0, Request.FoundationRebarTopCoverFt) + Math.Max(0.0, linkDiaFt * 0.5);
            double bottomCoverLinkFt = Math.Max(0.0, Request.FoundationRebarBottomCoverFt) + Math.Max(0.0, linkDiaFt * 0.5);

            double xLink0 = Math.Max(x0, localMin.X + sideCoverLinkFt);
            double xLink1 = Math.Min(x1, localMax.X - sideCoverLinkFt);
            double yLink0 = Math.Max(y0, localMin.Y + sideCoverLinkFt);
            double yLink1 = Math.Min(y1, localMax.Y - sideCoverLinkFt);
            double zLinkMin = Math.Max(zBottom, localMin.Z + bottomCoverLinkFt);
            double zLinkMax = Math.Min(zTop, localMax.Z - topCoverLinkFt);

            if (xLink1 <= xLink0 + 1e-6 || yLink1 <= yLink0 + 1e-6 || zLinkMax <= zLinkMin + 1e-6)
            {
                return;
            }

            XYZ horizontalLoopNormal = NormalizeOrDefault(hostTransform.BasisZ, tiePlaneNormal ?? XYZ.BasisZ);
            XYZ xzLoopNormal = NormalizeOrDefault(hostTransform.BasisY, XYZ.BasisY); // plane = XZ
            XYZ yzLoopNormal = NormalizeOrDefault(hostTransform.BasisX, XYZ.BasisX); // plane = YZ
            bool useShape21U = IsFoundationNaviateShapeCode(navSideBars?.ShapeCode, "21");
            RebarShape preferredSideUShape = useShape21U ? FindRebarShapeByCode(doc, "21", RebarStyle.Standard) : null;

            List<double> levels = BuildFoundationRebarTieZLevels(
                zLinkMin,
                zLinkMax,
                Request.FoundationRebarBottomTieSpacingFt,
                Request.FoundationRebarMidTieSpacingFt,
                Request.FoundationRebarTopTieSpacingFt,
                Request.FoundationRebarBottomZoneLengthFt,
                Request.FoundationRebarMidZoneLengthFt,
                Request.FoundationRebarTopZoneLengthFt);

            // Horizontal locking/perimeter rings (kept from previous implementation).
            foreach (double z in levels)
            {
                XYZ p00 = hostTransform.OfPoint(new XYZ(xLink0, yLink0, z));
                XYZ p10 = hostTransform.OfPoint(new XYZ(xLink1, yLink0, z));
                XYZ p11 = hostTransform.OfPoint(new XYZ(xLink1, yLink1, z));
                XYZ p01 = hostTransform.OfPoint(new XYZ(xLink0, yLink1, z));
                var loop = useShape21U
                    ? new List<Curve>
                    {
                        Line.CreateBound(p00, p10),
                        Line.CreateBound(p10, p11),
                        Line.CreateBound(p11, p01)
                    }
                    : new List<Curve>
                    {
                        Line.CreateBound(p00, p10),
                        Line.CreateBound(p10, p11),
                        Line.CreateBound(p11, p01),
                        Line.CreateBound(p01, p00)
                    };

                try
                {
                    Rebar tie = CreateRebarFromCurvesPreferShape(
                        doc,
                        useShape21U ? RebarStyle.Standard : RebarStyle.StirrupTie,
                        linkBarType,
                        useShape21U ? preferredSideUShape : null,
                        null,
                        null,
                        host,
                        horizontalLoopNormal,
                        loop,
                        RebarHookOrientation.Right,
                        RebarHookOrientation.Right);
                    if (tie != null) linksCreated++;
                    else linksFailed++;
                }
                catch
                {
                    linksFailed++;
                }
            }

            if (useShape21U)
            {
                // Shape 21 side bars are intended as repeated horizontal U-bars along the side height.
                return;
            }

            // Vertical perimeter stirrup loops distributed along both plan directions.
            // This matches the pile-cap cage shop-drawing pattern much better than horizontal rings alone.
            double xzLoopSpacingFt = ChooseFoundationLinkPerimeterLoopSpacing(
                Request.FoundationRebarTopSpacingXFt,
                Request.FoundationRebarBottomSpacingXFt);
            double yzLoopSpacingFt = ChooseFoundationLinkPerimeterLoopSpacing(
                Request.FoundationRebarTopSpacingYFt,
                Request.FoundationRebarBottomSpacingYFt);

            foreach (double y in BuildFoundationRebarPositionsBySpacing(yLink0, yLink1, xzLoopSpacingFt))
            {
                XYZ p00 = hostTransform.OfPoint(new XYZ(xLink0, y, zLinkMin));
                XYZ p10 = hostTransform.OfPoint(new XYZ(xLink1, y, zLinkMin));
                XYZ p11 = hostTransform.OfPoint(new XYZ(xLink1, y, zLinkMax));
                XYZ p01 = hostTransform.OfPoint(new XYZ(xLink0, y, zLinkMax));
                var verticalLoop = new List<Curve>
                {
                    Line.CreateBound(p00, p10),
                    Line.CreateBound(p10, p11),
                    Line.CreateBound(p11, p01),
                    Line.CreateBound(p01, p00)
                };

                try
                {
                    Rebar loop = CreateRebarFromCurvesPreferShape(
                        doc,
                        RebarStyle.StirrupTie,
                        linkBarType,
                        null,
                        null,
                        null,
                        host,
                        xzLoopNormal,
                        verticalLoop,
                        RebarHookOrientation.Right,
                        RebarHookOrientation.Right);
                    if (loop != null) linksCreated++;
                    else linksFailed++;
                }
                catch
                {
                    linksFailed++;
                }
            }

            foreach (double x in BuildFoundationRebarPositionsBySpacing(xLink0, xLink1, yzLoopSpacingFt))
            {
                XYZ p00 = hostTransform.OfPoint(new XYZ(x, yLink0, zLinkMin));
                XYZ p10 = hostTransform.OfPoint(new XYZ(x, yLink1, zLinkMin));
                XYZ p11 = hostTransform.OfPoint(new XYZ(x, yLink1, zLinkMax));
                XYZ p01 = hostTransform.OfPoint(new XYZ(x, yLink0, zLinkMax));
                var verticalLoop = new List<Curve>
                {
                    Line.CreateBound(p00, p10),
                    Line.CreateBound(p10, p11),
                    Line.CreateBound(p11, p01),
                    Line.CreateBound(p01, p00)
                };

                try
                {
                    Rebar loop = CreateRebarFromCurvesPreferShape(
                        doc,
                        RebarStyle.StirrupTie,
                        linkBarType,
                        null,
                        null,
                        null,
                        host,
                        yzLoopNormal,
                        verticalLoop,
                        RebarHookOrientation.Right,
                        RebarHookOrientation.Right);
                    if (loop != null) linksCreated++;
                    else linksFailed++;
                }
                catch
                {
                    linksFailed++;
                }
            }
        }

        private static bool TryBuildFoundationShape21UBarCurves(
            Transform hostTransform,
            double runStartFt,
            double runEndFt,
            double fixedCoordFt,
            double zFt,
            double zBottomLimitFt,
            double zTopLimitFt,
            bool isTopLayer,
            double legLengthFt,
            bool alongXAxis,
            out List<Curve> curves)
        {
            curves = null;
            if (hostTransform == null)
            {
                return false;
            }

            if (!IsFiniteNumber(runStartFt) || !IsFiniteNumber(runEndFt) || !IsFiniteNumber(fixedCoordFt) ||
                !IsFiniteNumber(zFt) || !IsFiniteNumber(zBottomLimitFt) || !IsFiniteNumber(zTopLimitFt))
            {
                return false;
            }

            if (runEndFt <= runStartFt + 1e-6)
            {
                return false;
            }

            double legFt = Math.Max(0.0, legLengthFt);
            if (legFt <= 1e-6)
            {
                return false;
            }

            double zLegFt = isTopLayer
                ? Math.Max(zBottomLimitFt, zFt - legFt)
                : Math.Min(zTopLimitFt, zFt + legFt);

            if (Math.Abs(zLegFt - zFt) <= 1e-6)
            {
                return false;
            }

            XYZ a0Local;
            XYZ a1Local;
            XYZ b1Local;
            XYZ b0Local;
            if (alongXAxis)
            {
                a0Local = new XYZ(runStartFt, fixedCoordFt, zLegFt);
                a1Local = new XYZ(runStartFt, fixedCoordFt, zFt);
                b1Local = new XYZ(runEndFt, fixedCoordFt, zFt);
                b0Local = new XYZ(runEndFt, fixedCoordFt, zLegFt);
            }
            else
            {
                a0Local = new XYZ(fixedCoordFt, runStartFt, zLegFt);
                a1Local = new XYZ(fixedCoordFt, runStartFt, zFt);
                b1Local = new XYZ(fixedCoordFt, runEndFt, zFt);
                b0Local = new XYZ(fixedCoordFt, runEndFt, zLegFt);
            }

            XYZ a0 = hostTransform.OfPoint(a0Local);
            XYZ a1 = hostTransform.OfPoint(a1Local);
            XYZ b1 = hostTransform.OfPoint(b1Local);
            XYZ b0 = hostTransform.OfPoint(b0Local);

            if (a0.DistanceTo(a1) <= 1e-6 || a1.DistanceTo(b1) <= 1e-6 || b1.DistanceTo(b0) <= 1e-6)
            {
                return false;
            }

            curves = new List<Curve>
            {
                Line.CreateBound(a0, a1),
                Line.CreateBound(a1, b1),
                Line.CreateBound(b1, b0)
            };
            return true;
        }

        private static bool IsFoundationNaviateShapeCode(string actualShapeCode, string expectedShapeCode)
        {
            string actual = (actualShapeCode ?? "").Trim();
            string expected = (expectedShapeCode ?? "").Trim();
            if (string.IsNullOrWhiteSpace(actual) || string.IsNullOrWhiteSpace(expected))
            {
                return false;
            }

            if (string.Equals(actual, expected, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Accept common labels like "Shape 21" / "M_21".
            return actual.IndexOf(expected, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static RebarShape FindRebarShapeByCode(Document doc, string shapeCode, RebarStyle preferredStyle)
        {
            if (doc == null || string.IsNullOrWhiteSpace(shapeCode))
            {
                return null;
            }

            string code = shapeCode.Trim();
            RebarShape fallback = null;

            try
            {
                foreach (RebarShape shape in new FilteredElementCollector(doc)
                    .OfClass(typeof(RebarShape))
                    .Cast<RebarShape>())
                {
                    if (shape == null)
                    {
                        continue;
                    }

                    string name = "";
                    try
                    {
                        name = shape.Name ?? "";
                    }
                    catch
                    {
                        name = "";
                    }

                    if (!IsFoundationNaviateShapeCode(name, code))
                    {
                        continue;
                    }

                    bool styleMatch = false;
                    try
                    {
                        styleMatch = shape.RebarStyle == preferredStyle;
                    }
                    catch
                    {
                        styleMatch = false;
                    }

                    if (styleMatch)
                    {
                        return shape;
                    }

                    if (fallback == null)
                    {
                        fallback = shape;
                    }
                }
            }
            catch
            {
                return null;
            }

            return fallback;
        }

        private static double ChooseFoundationLinkPerimeterLoopSpacing(double preferredFt, double fallbackFt)
        {
            if (preferredFt > 1e-9 && fallbackFt > 1e-9)
            {
                return Math.Min(preferredFt, fallbackFt);
            }

            if (preferredFt > 1e-9)
            {
                return preferredFt;
            }

            if (fallbackFt > 1e-9)
            {
                return fallbackFt;
            }

            return MmToFeet(150.0);
        }

        private void CreateFoundationStarterBars(
            Document doc,
            Element host,
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            double x0,
            double x1,
            double y0,
            double y1,
            double zBottom,
            RebarBarType mainBarType,
            XYZ starterNormal,
            ref int startersCreated,
            ref int startersFailed)
        {
            if (doc == null || host == null || hostTransform == null || localMin == null || localMax == null || mainBarType == null)
            {
                return;
            }

            double pedHeightFt = Math.Max(0.0, Request.FoundationRebarPedestalHeightFt);
            double pedLengthFt = Math.Max(0.0, Request.FoundationRebarPedestalWidthFt);
            double pedWidthFt = Math.Max(0.0, Request.FoundationRebarPedestalDepthFt);
            if (pedHeightFt <= 1e-6 || pedLengthFt <= 1e-6 || pedWidthFt <= 1e-6)
            {
                return;
            }

            double hostCenterX = (localMin.X + localMax.X) * 0.5;
            double hostCenterY = (localMin.Y + localMax.Y) * 0.5;
            double hostTopZ = localMax.Z;

            double barDiaFt = Math.Max(0.0, GetRebarBarDiameterSafe(mainBarType));
            double sideTrimFt = Math.Max(Math.Max(Request.FoundationRebarSideCoverFt, MmToFeet(25.0)), barDiaFt * 0.5);
            double topTrimFt = Math.Max(Math.Max(Request.FoundationRebarTopCoverFt, MmToFeet(25.0)), barDiaFt * 0.5);
            double bottomTrimFt = Math.Max(Math.Max(Request.FoundationRebarBottomCoverFt, MmToFeet(25.0)), barDiaFt * 0.5);

            double px0 = Math.Max(x0, hostCenterX - (pedLengthFt * 0.5) + sideTrimFt);
            double px1 = Math.Min(x1, hostCenterX + (pedLengthFt * 0.5) - sideTrimFt);
            double py0 = Math.Max(y0, hostCenterY - (pedWidthFt * 0.5) + sideTrimFt);
            double py1 = Math.Min(y1, hostCenterY + (pedWidthFt * 0.5) - sideTrimFt);
            double z0 = Math.Max(localMin.Z + bottomTrimFt, zBottom);
            double z1 = hostTopZ + Math.Max(0.0, pedHeightFt - topTrimFt);

            if (px1 <= px0 + 1e-6 || py1 <= py0 + 1e-6 || z1 <= z0 + 1e-6)
            {
                return;
            }

            int barsX = 0;
            int barsY = 0;
            FoundationNaviateColumnStarterBarsRequest navStarter =
                (Request.FoundationRebarUseNaviateDataModel && Request.FoundationRebarNaviate != null)
                ? Request.FoundationRebarNaviate.ColumnStarterBars
                : null;
            if (navStarter != null)
            {
                barsX = Math.Max(0, navStarter.BarsX);
                barsY = Math.Max(0, navStarter.BarsY);
            }

            if (barsX < 2 || barsY < 2)
            {
                double spacingXFt = Request.FoundationRebarTopSpacingXFt > 1e-9 ? Request.FoundationRebarTopSpacingXFt : MmToFeet(150.0);
                double spacingYFt = Request.FoundationRebarTopSpacingYFt > 1e-9 ? Request.FoundationRebarTopSpacingYFt : MmToFeet(150.0);
                if (barsX < 2)
                {
                    barsX = Math.Max(2, (int)Math.Floor(Math.Max(0.0, py1 - py0) / Math.Max(MmToFeet(50.0), spacingXFt)) + 1);
                }
                if (barsY < 2)
                {
                    barsY = Math.Max(2, (int)Math.Floor(Math.Max(0.0, px1 - px0) / Math.Max(MmToFeet(50.0), spacingYFt)) + 1);
                }
            }

            List<XYZ> pointsLocal = BuildColumnRebarLocalMainBarPoints(
                new XYZ(px0, py0, 0.0),
                new XYZ(px1, py1, 0.0),
                barsX,
                barsY,
                0.0);

            foreach (XYZ pLocal in pointsLocal)
            {
                XYZ p0 = hostTransform.OfPoint(new XYZ(pLocal.X, pLocal.Y, z0));
                XYZ p1 = hostTransform.OfPoint(new XYZ(pLocal.X, pLocal.Y, z1));
                if (p0.DistanceTo(p1) <= 1e-6)
                {
                    continue;
                }

                try
                {
                    Rebar rb = Rebar.CreateFromCurves(
                        doc,
                        RebarStyle.Standard,
                        mainBarType,
                        null,
                        null,
                        host,
                        starterNormal,
                        new List<Curve> { Line.CreateBound(p0, p1) },
                        RebarHookOrientation.Right,
                        RebarHookOrientation.Right,
                        true,
                        true);
                    if (rb != null) startersCreated++;
                    else startersFailed++;
                }
                catch
                {
                    startersFailed++;
                }
            }
        }

        private static List<double> BuildFoundationRebarPositionsBySpacing(double start, double end, double spacingFt)
        {
            var result = new List<double>();
            if (!IsFiniteNumber(start) || !IsFiniteNumber(end))
            {
                return result;
            }

            if (end < start)
            {
                double temp = start;
                start = end;
                end = temp;
            }

            double span = end - start;
            if (span <= 1e-6)
            {
                result.Add(start);
                return result;
            }

            double spacing = spacingFt > 1e-9 ? spacingFt : MmToFeet(150.0);
            spacing = Math.Max(MmToFeet(50.0), spacing);

            int count = Math.Max(2, (int)Math.Floor(span / spacing) + 1);
            result.AddRange(BuildColumnRebarLinearPositions(start, end, count));
            return result;
        }

        private static List<double> BuildFoundationRebarTieZLevels(
            double zMin,
            double zMax,
            double bottomSpacingFt,
            double midSpacingFt,
            double topSpacingFt,
            double bottomZoneLengthFt,
            double midZoneLengthFt,
            double topZoneLengthFt)
        {
            var result = new List<double>();
            if (!IsFiniteNumber(zMin) || !IsFiniteNumber(zMax))
            {
                return result;
            }

            if (zMax < zMin)
            {
                double temp = zMin;
                zMin = zMax;
                zMax = temp;
            }

            if (zMax <= zMin + 1e-6)
            {
                result.Add(zMin);
                return result;
            }

            double total = zMax - zMin;
            double bottomLen = Math.Max(0.0, bottomZoneLengthFt);
            double midLen = Math.Max(0.0, midZoneLengthFt);
            double topLen = Math.Max(0.0, topZoneLengthFt);

            if (bottomLen + midLen + topLen <= 1e-6)
            {
                midLen = total;
            }
            else
            {
                if (bottomLen > total) bottomLen = total;
                if (topLen > Math.Max(0.0, total - bottomLen)) topLen = Math.Max(0.0, total - bottomLen);
                double remaining = Math.Max(0.0, total - bottomLen - topLen);
                if (midLen <= 1e-6 || midLen > remaining)
                {
                    midLen = remaining;
                }
            }

            double zBottomEnd = Math.Min(zMax, zMin + bottomLen);
            double zTopStart = Math.Max(zMin, zMax - topLen);
            if (zTopStart < zBottomEnd)
            {
                zTopStart = zBottomEnd;
            }

            AppendFoundationRebarZoneLevels(result, zMin, zBottomEnd, bottomSpacingFt, includeStart: true, includeEnd: false);
            AppendFoundationRebarZoneLevels(result, zBottomEnd, zTopStart, midSpacingFt, includeStart: result.Count == 0, includeEnd: false);
            AppendFoundationRebarZoneLevels(result, zTopStart, zMax, topSpacingFt, includeStart: result.Count == 0, includeEnd: true);

            if (result.Count == 0)
            {
                result.Add(zMin);
                AddFoundationRebarLevelIfDistinct(result, zMax);
            }

            return result;
        }

        private static void AppendFoundationRebarZoneLevels(
            IList<double> result,
            double start,
            double end,
            double spacingFt,
            bool includeStart,
            bool includeEnd)
        {
            if (result == null || !IsFiniteNumber(start) || !IsFiniteNumber(end))
            {
                return;
            }

            if (end < start)
            {
                double temp = start;
                start = end;
                end = temp;
            }

            double tol = MmToFeet(0.5);
            if (end <= start + tol)
            {
                if (includeStart || includeEnd)
                {
                    AddFoundationRebarLevelIfDistinct(result, start);
                }
                return;
            }

            double spacing = spacingFt > 1e-9 ? spacingFt : MmToFeet(150.0);
            spacing = Math.Max(MmToFeet(50.0), spacing);

            if (includeStart)
            {
                AddFoundationRebarLevelIfDistinct(result, start);
            }

            double z = start + spacing;
            while (z < end - tol)
            {
                AddFoundationRebarLevelIfDistinct(result, z);
                z += spacing;
            }

            if (includeEnd)
            {
                AddFoundationRebarLevelIfDistinct(result, end);
            }
        }

        private static void AddFoundationRebarLevelIfDistinct(IList<double> result, double z)
        {
            if (result == null || !IsFiniteNumber(z))
            {
                return;
            }

            double tol = MmToFeet(0.5);
            for (int i = 0; i < result.Count; i++)
            {
                if (Math.Abs(result[i] - z) <= tol)
                {
                    return;
                }
            }

            result.Add(z);
        }

        private static List<Element> ResolveFoundationRebarTargetHosts(Document doc, Element seedHost, bool applyToSameType)
        {
            var result = new List<Element>();
            if (doc == null || seedHost == null)
            {
                return result;
            }

            if (!applyToSameType)
            {
                if (IsFoundationRebarHostElement(seedHost))
                {
                    result.Add(seedHost);
                }
                return result;
            }

            ElementId seedTypeId = ElementId.InvalidElementId;
            try
            {
                seedTypeId = seedHost.GetTypeId();
            }
            catch
            {
                seedTypeId = ElementId.InvalidElementId;
            }

            long categoryId = seedHost.Category?.Id?.Value ?? long.MinValue;
            Type seedClrType = seedHost.GetType();

            foreach (Element candidate in new FilteredElementCollector(doc).WhereElementIsNotElementType())
            {
                if (candidate == null)
                {
                    continue;
                }

                if (!IsFoundationRebarHostElement(candidate))
                {
                    continue;
                }

                if ((candidate.Category?.Id?.Value ?? long.MinValue) != categoryId)
                {
                    continue;
                }

                if (seedClrType != null && candidate.GetType() != seedClrType)
                {
                    continue;
                }

                if (seedTypeId != ElementId.InvalidElementId)
                {
                    ElementId candidateTypeId;
                    try
                    {
                        candidateTypeId = candidate.GetTypeId();
                    }
                    catch
                    {
                        candidateTypeId = ElementId.InvalidElementId;
                    }

                    if (candidateTypeId != seedTypeId)
                    {
                        continue;
                    }
                }

                result.Add(candidate);
            }

            result = result
                .OrderBy(e => e?.Id?.Value ?? long.MaxValue)
                .ToList();

            if (result.Count == 0 && IsFoundationRebarHostElement(seedHost))
            {
                result.Add(seedHost);
            }

            return result;
        }

        private static int DeleteExistingColumnRebars(Document doc, Element host)
        {
            if (doc == null || host == null)
            {
                return 0;
            }

            var toDelete = new List<ElementId>();
            var seen = new HashSet<long>();

            try
            {
                foreach (Element rebarElement in new FilteredElementCollector(doc)
                    .WhereElementIsNotElementType()
                    .OfCategory(BuiltInCategory.OST_Rebar))
                {
                    if (rebarElement == null ||
                        rebarElement.Id == null ||
                        rebarElement.Id == ElementId.InvalidElementId)
                    {
                        continue;
                    }

                    if (!seen.Add(rebarElement.Id.Value))
                    {
                        continue;
                    }

                    ElementId hostId = TryGetHostedRebarHostId(rebarElement);
                    if (hostId == host.Id)
                    {
                        toDelete.Add(rebarElement.Id);
                    }
                }
            }
            catch
            {
                return 0;
            }

            if (toDelete.Count == 0)
            {
                return 0;
            }

            try
            {
                doc.Delete(toDelete);
                return toDelete.Count;
            }
            catch
            {
                int deleted = 0;
                foreach (ElementId id in toDelete)
                {
                    try
                    {
                        doc.Delete(id);
                        deleted++;
                    }
                    catch
                    {
                    }
                }

                return deleted;
            }
        }

        private static ElementId TryGetHostedRebarHostId(Element element)
        {
            if (element == null)
            {
                return ElementId.InvalidElementId;
            }

            if (element is Rebar rebar)
            {
                try
                {
                    return rebar.GetHostId();
                }
                catch
                {
                }
            }

            try
            {
                MethodInfo method = element.GetType().GetMethod(
                    "GetHostId",
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                    binder: null,
                    types: Type.EmptyTypes,
                    modifiers: null);
                if (method != null && typeof(ElementId).IsAssignableFrom(method.ReturnType))
                {
                    object value = method.Invoke(element, null);
                    if (value is ElementId id)
                    {
                        return id;
                    }
                }
            }
            catch
            {
            }

            return ElementId.InvalidElementId;
        }

        private static bool TryBuildColumnRebarHostPreviewData(
            Document doc,
            Element host,
            out CamboBIMWindow.ColumnRebarHostPreviewData data,
            out string error)
        {
            data = null;
            error = "";

            if (host == null)
            {
                error = "host column not found.";
                return false;
            }

            if (!TryGetColumnRebarHostFrameAndBounds(host, out Transform hostTransform, out XYZ localMin, out XYZ localMax, out error))
            {
                return false;
            }

            string levelName = "";
            if (doc?.GetElement(host.LevelId) is Level lvl)
            {
                levelName = lvl.Name ?? "";
            }

            string hostName = host.Name ?? "";
            if (host is FamilyInstance fi && fi.Symbol != null)
            {
                string family = fi.Symbol.FamilyName ?? "";
                string symbol = fi.Symbol.Name ?? hostName;
                hostName = string.IsNullOrWhiteSpace(family) ? symbol : $"{family} : {symbol}";
            }

            data = new CamboBIMWindow.ColumnRebarHostPreviewData
            {
                HostElementId = host.Id,
                HostDisplayName = hostName,
                LevelName = levelName,
                WidthFt = Math.Max(0.0, localMax.X - localMin.X),
                DepthFt = Math.Max(0.0, localMax.Y - localMin.Y),
                HeightFt = Math.Max(0.0, localMax.Z - localMin.Z),
                HostTransform = hostTransform,
                LocalMin = localMin,
                LocalMax = localMax
            };

            try
            {
                PopulateColumnRebarElevationContextElements(doc, host, hostTransform, localMin, localMax, data.ElevationContextElements);
            }
            catch
            {
                // Keep preview usable even if context extraction fails.
            }

            return true;
        }

        private static bool TryBuildFoundationRebarHostPreviewData(
            Document doc,
            Element host,
            out CamboBIMWindow.FoundationRebarHostPreviewData data,
            out string error)
        {
            data = null;
            error = "";

            if (host == null)
            {
                error = "host not found.";
                return false;
            }

            if (!TryGetFoundationRebarHostFrameAndBounds(host, out Transform hostTransform, out XYZ localMin, out XYZ localMax, out error))
            {
                return false;
            }

            string levelName = TryGetElementLevelName(doc, host);
            double lengthFt = Math.Max(0.0, localMax.X - localMin.X);
            double widthFt = Math.Max(0.0, localMax.Y - localMin.Y);
            double thicknessFt = Math.Max(0.0, localMax.Z - localMin.Z);
            string typeMode = InferFoundationRebarTypeMode(host);
            string hostLabel = BuildFoundationRebarHostDisplayName(host);
            string dimsLabel = $"{FeetToMm(lengthFt):0.#}x{FeetToMm(widthFt):0.#}x{FeetToMm(thicknessFt):0.#} mm";
            string previewLabel = string.IsNullOrWhiteSpace(levelName)
                ? $"{hostLabel} | {typeMode} | {dimsLabel}"
                : $"{hostLabel} | {typeMode} | {dimsLabel} | {levelName}";

            ElementId typeId = ElementId.InvalidElementId;
            try
            {
                typeId = host.GetTypeId();
            }
            catch
            {
                typeId = ElementId.InvalidElementId;
            }

            data = new CamboBIMWindow.FoundationRebarHostPreviewData
            {
                HostElementId = host.Id,
                HostTypeElementId = typeId,
                HostDisplayName = previewLabel,
                LevelName = levelName ?? "",
                SuggestedTypeMode = typeMode,
                LengthFt = lengthFt,
                WidthFt = widthFt,
                ThicknessFt = thicknessFt,
                HostTransform = hostTransform,
                LocalMin = localMin,
                LocalMax = localMax
            };

            try
            {
                TryPopulateFoundationRebarDetectedColumnData(doc, host, hostTransform, localMin, localMax, data);
            }
            catch
            {
                // Keep preview usable even if connected-column detection fails.
            }

            return true;
        }

        private static void TryPopulateFoundationRebarDetectedColumnData(
            Document doc,
            Element host,
            Transform hostTransform,
            XYZ hostLocalMin,
            XYZ hostLocalMax,
            CamboBIMWindow.FoundationRebarHostPreviewData data)
        {
            if (doc == null || host == null || hostTransform == null || data == null)
            {
                return;
            }

            BoundingBoxXYZ hostBbox = null;
            try
            {
                hostBbox = host.get_BoundingBox(null);
            }
            catch
            {
                hostBbox = null;
            }

            if (hostBbox == null || hostBbox.Min == null || hostBbox.Max == null)
            {
                return;
            }

            double hostLenFt = Math.Max(0.0, hostLocalMax.X - hostLocalMin.X);
            double hostWidFt = Math.Max(0.0, hostLocalMax.Y - hostLocalMin.Y);
            double hostThkFt = Math.Max(0.0, hostLocalMax.Z - hostLocalMin.Z);
            double hostTopZLocal = hostLocalMax.Z;
            double hostCenterXLocal = 0.5 * (hostLocalMin.X + hostLocalMax.X);
            double hostCenterYLocal = 0.5 * (hostLocalMin.Y + hostLocalMax.Y);

            double planMarginFt = Math.Max(MmToFeet(300.0), Math.Max(hostLenFt, hostWidFt) * 0.20);
            double verticalBelowMarginFt = Math.Max(MmToFeet(150.0), hostThkFt * 0.15);
            double verticalAboveMarginFt = Math.Max(MmToFeet(12000.0), hostThkFt * 20.0);

            XYZ searchMin = new XYZ(
                hostBbox.Min.X - planMarginFt,
                hostBbox.Min.Y - planMarginFt,
                hostBbox.Min.Z - verticalBelowMarginFt);
            XYZ searchMax = new XYZ(
                hostBbox.Max.X + planMarginFt,
                hostBbox.Max.Y + planMarginFt,
                hostBbox.Max.Z + verticalAboveMarginFt);

            FilteredElementCollector collector = new FilteredElementCollector(doc)
                .OfCategory(BuiltInCategory.OST_StructuralColumns)
                .WhereElementIsNotElementType();

            try
            {
                collector = collector.WherePasses(new BoundingBoxIntersectsFilter(new Outline(searchMin, searchMax)));
            }
            catch
            {
                // Fallback to uncropped collector if outline filter fails.
            }

            Element bestColumn = null;
            XYZ bestLocalMin = XYZ.Zero;
            XYZ bestLocalMax = XYZ.Zero;
            double bestScore = double.NegativeInfinity;
            double topZToleranceFt = Math.Max(MmToFeet(50.0), hostThkFt * 0.05);

            foreach (Element candidate in collector)
            {
                if (candidate == null || candidate.Id == host.Id)
                {
                    continue;
                }

                BoundingBoxXYZ candidateBbox = null;
                try
                {
                    candidateBbox = candidate.get_BoundingBox(null);
                }
                catch
                {
                    candidateBbox = null;
                }

                if (candidateBbox == null || candidateBbox.Min == null || candidateBbox.Max == null)
                {
                    continue;
                }

                if (!TryGetLocalBoundsFromWorldBoundingBox(hostTransform, candidateBbox, out XYZ candidateBoxLocalMin, out XYZ candidateBoxLocalMax))
                {
                    continue;
                }

                if (candidateBoxLocalMax.Z < (hostLocalMin.Z - topZToleranceFt))
                {
                    continue;
                }

                if (candidateBoxLocalMin.Z > (hostTopZLocal + verticalAboveMarginFt))
                {
                    continue;
                }

                if (candidateBoxLocalMax.Z < (hostTopZLocal - topZToleranceFt))
                {
                    continue;
                }

                double overlapX = Math.Min(hostLocalMax.X, candidateBoxLocalMax.X) - Math.Max(hostLocalMin.X, candidateBoxLocalMin.X);
                double overlapY = Math.Min(hostLocalMax.Y, candidateBoxLocalMax.Y) - Math.Max(hostLocalMin.Y, candidateBoxLocalMin.Y);
                double overlapArea = Math.Max(0.0, overlapX) * Math.Max(0.0, overlapY);

                double candidateCenterXLocal = 0.5 * (candidateBoxLocalMin.X + candidateBoxLocalMax.X);
                double candidateCenterYLocal = 0.5 * (candidateBoxLocalMin.Y + candidateBoxLocalMax.Y);
                bool centerInsideFoundation =
                    candidateCenterXLocal >= (hostLocalMin.X - planMarginFt) &&
                    candidateCenterXLocal <= (hostLocalMax.X + planMarginFt) &&
                    candidateCenterYLocal >= (hostLocalMin.Y - planMarginFt) &&
                    candidateCenterYLocal <= (hostLocalMax.Y + planMarginFt);

                if (overlapArea <= 1e-9 && !centerInsideFoundation)
                {
                    continue;
                }

                if (!TryGetElementBoundsInFoundationLocalFrame(candidate, hostTransform, out XYZ candidateLocalMin, out XYZ candidateLocalMax))
                {
                    candidateLocalMin = candidateBoxLocalMin;
                    candidateLocalMax = candidateBoxLocalMax;
                }

                double colWidthFt = Math.Max(0.0, candidateLocalMax.X - candidateLocalMin.X);
                double colDepthFt = Math.Max(0.0, candidateLocalMax.Y - candidateLocalMin.Y);
                if (colWidthFt <= 1e-6 || colDepthFt <= 1e-6)
                {
                    continue;
                }

                double footprintAreaFt2 = colWidthFt * colDepthFt;
                if (footprintAreaFt2 > (hostLenFt * hostWidFt * 1.20) && hostLenFt > 1e-6 && hostWidFt > 1e-6)
                {
                    // Likely picked a nearby wall/odd bbox; structural column footprint should be smaller than host.
                    continue;
                }

                double centerX = 0.5 * (candidateLocalMin.X + candidateLocalMax.X);
                double centerY = 0.5 * (candidateLocalMin.Y + candidateLocalMax.Y);
                double dist2 = (centerX - hostCenterXLocal) * (centerX - hostCenterXLocal) +
                               (centerY - hostCenterYLocal) * (centerY - hostCenterYLocal);

                bool crossesHostTop = candidateLocalMin.Z <= (hostTopZLocal + topZToleranceFt) &&
                                      candidateLocalMax.Z >= (hostTopZLocal - topZToleranceFt);

                double score =
                    overlapArea * 1000.0 +
                    (crossesHostTop ? 500.0 : 0.0) +
                    (centerInsideFoundation ? 100.0 : 0.0) -
                    dist2 * 25.0;

                if (score > bestScore)
                {
                    bestScore = score;
                    bestColumn = candidate;
                    bestLocalMin = candidateLocalMin;
                    bestLocalMax = candidateLocalMax;
                }
            }

            if (bestColumn == null)
            {
                return;
            }

            data.DetectedColumnElementId = bestColumn.Id;
            data.DetectedColumnWidthFt = Math.Max(0.0, bestLocalMax.X - bestLocalMin.X);
            data.DetectedColumnDepthFt = Math.Max(0.0, bestLocalMax.Y - bestLocalMin.Y);
            data.DetectedColumnDisplayName = BuildFoundationDetectedColumnDisplayName(bestColumn);
        }

        private static bool TryGetElementBoundsInFoundationLocalFrame(
            Element element,
            Transform foundationLocalFrame,
            out XYZ localMin,
            out XYZ localMax)
        {
            localMin = XYZ.Zero;
            localMax = XYZ.Zero;

            if (element == null || foundationLocalFrame == null)
            {
                return false;
            }

            Options options = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = false
            };

            GeometryElement ge = null;
            try
            {
                ge = element.get_Geometry(options);
            }
            catch
            {
                ge = null;
            }

            var verticesWorld = new List<XYZ>();
            if (ge != null)
            {
                CollectColumnRebarWorldVertices(ge, verticesWorld);
            }

            if (verticesWorld.Count == 0)
            {
                BoundingBoxXYZ bbox = null;
                try
                {
                    bbox = element.get_BoundingBox(null);
                }
                catch
                {
                    bbox = null;
                }

                return TryGetLocalBoundsFromWorldBoundingBox(foundationLocalFrame, bbox, out localMin, out localMax);
            }

            Transform inv;
            try
            {
                inv = foundationLocalFrame.Inverse;
            }
            catch
            {
                return false;
            }

            bool has = false;
            double minX = 0.0, minY = 0.0, minZ = 0.0, maxX = 0.0, maxY = 0.0, maxZ = 0.0;
            foreach (XYZ pWorld in verticesWorld)
            {
                if (pWorld == null)
                {
                    continue;
                }

                XYZ pLocal;
                try
                {
                    pLocal = inv.OfPoint(pWorld);
                }
                catch
                {
                    continue;
                }

                if (!IsFinite(pLocal))
                {
                    continue;
                }

                if (!has)
                {
                    minX = maxX = pLocal.X;
                    minY = maxY = pLocal.Y;
                    minZ = maxZ = pLocal.Z;
                    has = true;
                }
                else
                {
                    if (pLocal.X < minX) minX = pLocal.X;
                    if (pLocal.Y < minY) minY = pLocal.Y;
                    if (pLocal.Z < minZ) minZ = pLocal.Z;
                    if (pLocal.X > maxX) maxX = pLocal.X;
                    if (pLocal.Y > maxY) maxY = pLocal.Y;
                    if (pLocal.Z > maxZ) maxZ = pLocal.Z;
                }
            }

            if (!has)
            {
                return false;
            }

            localMin = new XYZ(minX, minY, minZ);
            localMax = new XYZ(maxX, maxY, maxZ);
            return true;
        }

        private static string BuildFoundationDetectedColumnDisplayName(Element column)
        {
            if (column == null)
            {
                return "";
            }

            if (column is FamilyInstance fi && fi.Symbol != null)
            {
                string family = (fi.Symbol.FamilyName ?? "").Trim();
                string symbol = (fi.Symbol.Name ?? column.Name ?? "").Trim();
                if (!string.IsNullOrWhiteSpace(family) && !string.IsNullOrWhiteSpace(symbol))
                {
                    return family + " : " + symbol;
                }

                if (!string.IsNullOrWhiteSpace(symbol))
                {
                    return symbol;
                }
            }

            return (column.Name ?? "").Trim();
        }

        private static bool TryGetFoundationRebarHostFrameAndBounds(
            Element host,
            out Transform hostTransform,
            out XYZ localMin,
            out XYZ localMax,
            out string error)
        {
            hostTransform = Transform.Identity;
            localMin = XYZ.Zero;
            localMax = XYZ.Zero;
            error = "";

            if (host == null)
            {
                error = "host not found.";
                return false;
            }

            if (!RebarHostData.IsValidHost(host))
            {
                error = "selected element cannot host rebar.";
                return false;
            }

            hostTransform = BuildFoundationRebarHostTransform(host);

            Options options = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = false
            };

            GeometryElement ge = null;
            try
            {
                ge = host.get_Geometry(options);
            }
            catch
            {
                ge = null;
            }

            var verticesWorld = new List<XYZ>();
            if (ge != null)
            {
                CollectColumnRebarWorldVertices(ge, verticesWorld);
            }

            if (verticesWorld.Count == 0)
            {
                BoundingBoxXYZ bbox = null;
                try
                {
                    bbox = host.get_BoundingBox(null);
                }
                catch
                {
                    bbox = null;
                }

                // Use all bbox corners in local-frame conversion via the shared helper,
                // otherwise rotated hosts can report incorrect local dimensions.
                if (TryGetLocalBoundsFromWorldBoundingBox(hostTransform, bbox, out localMin, out localMax))
                {
                    if ((localMax.X - localMin.X) <= 1e-6 || (localMax.Y - localMin.Y) <= 1e-6 || (localMax.Z - localMin.Z) <= 1e-6)
                    {
                        error = "foundation geometry size is invalid for rebar generation.";
                        return false;
                    }

                    return true;
                }
            }

            if (verticesWorld.Count == 0)
            {
                error = "unable to extract foundation geometry.";
                return false;
            }

            Transform inv;
            try
            {
                inv = hostTransform.Inverse;
            }
            catch
            {
                error = "invalid host transform.";
                return false;
            }

            bool has = false;
            double minX = 0.0, minY = 0.0, minZ = 0.0, maxX = 0.0, maxY = 0.0, maxZ = 0.0;
            foreach (XYZ pWorld in verticesWorld)
            {
                if (pWorld == null)
                {
                    continue;
                }

                XYZ p;
                try
                {
                    p = inv.OfPoint(pWorld);
                }
                catch
                {
                    continue;
                }

                if (!IsFinite(p))
                {
                    continue;
                }

                if (!has)
                {
                    minX = maxX = p.X;
                    minY = maxY = p.Y;
                    minZ = maxZ = p.Z;
                    has = true;
                }
                else
                {
                    if (p.X < minX) minX = p.X;
                    if (p.Y < minY) minY = p.Y;
                    if (p.Z < minZ) minZ = p.Z;
                    if (p.X > maxX) maxX = p.X;
                    if (p.Y > maxY) maxY = p.Y;
                    if (p.Z > maxZ) maxZ = p.Z;
                }
            }

            if (!has)
            {
                error = "foundation geometry could not be converted to local coordinates.";
                return false;
            }

            localMin = new XYZ(minX, minY, minZ);
            localMax = new XYZ(maxX, maxY, maxZ);

            if ((localMax.X - localMin.X) <= 1e-6 || (localMax.Y - localMin.Y) <= 1e-6 || (localMax.Z - localMin.Z) <= 1e-6)
            {
                error = "foundation geometry size is invalid for rebar generation.";
                return false;
            }

            return true;
        }

        private static Transform BuildFoundationRebarHostTransform(Element host)
        {
            if (host is FamilyInstance fi)
            {
                Transform fiTransform = BuildColumnRebarHostTransform(fi);
                XYZ origin = fiTransform?.Origin ?? XYZ.Zero;

                XYZ basisX = fiTransform?.BasisX ?? XYZ.BasisX;
                basisX = new XYZ(basisX.X, basisX.Y, 0.0);
                if (basisX.GetLength() < 1e-6)
                {
                    XYZ alt = fiTransform?.BasisY ?? XYZ.BasisY;
                    basisX = new XYZ(alt.X, alt.Y, 0.0);
                }
                basisX = NormalizeOrDefault(basisX, XYZ.BasisX);
                XYZ basisZ = XYZ.BasisZ;
                XYZ basisY = NormalizeOrDefault(basisZ.CrossProduct(basisX), XYZ.BasisY);
                basisX = NormalizeOrDefault(basisY.CrossProduct(basisZ), XYZ.BasisX);

                Transform result = Transform.Identity;
                result.Origin = origin;
                result.BasisX = basisX;
                result.BasisY = basisY;
                result.BasisZ = basisZ;
                return result;
            }

            if (TryBuildHorizontalTransformFromLocationCurve(host, out Transform curveTransform))
            {
                return curveTransform;
            }

            XYZ originPoint = XYZ.Zero;
            if (host?.Location is LocationPoint lp && lp.Point != null)
            {
                originPoint = lp.Point;
            }
            else
            {
                BoundingBoxXYZ bbox = null;
                try
                {
                    bbox = host?.get_BoundingBox(null);
                }
                catch
                {
                    bbox = null;
                }

                if (bbox != null && bbox.Min != null && bbox.Max != null)
                {
                    originPoint = new XYZ(
                        (bbox.Min.X + bbox.Max.X) * 0.5,
                        (bbox.Min.Y + bbox.Max.Y) * 0.5,
                        (bbox.Min.Z + bbox.Max.Z) * 0.5);
                }
            }

            Transform identity = Transform.Identity;
            identity.Origin = originPoint;
            identity.BasisX = XYZ.BasisX;
            identity.BasisY = XYZ.BasisY;
            identity.BasisZ = XYZ.BasisZ;
            return identity;
        }

        private static bool TryBuildHorizontalTransformFromLocationCurve(Element host, out Transform transform)
        {
            transform = null;
            if (!(host?.Location is LocationCurve lc) || lc.Curve == null)
            {
                return false;
            }

            Curve curve = lc.Curve;
            XYZ p0 = curve.GetEndPoint(0);
            XYZ p1 = curve.GetEndPoint(1);
            if (p0 == null || p1 == null)
            {
                return false;
            }

            XYZ dir = p1 - p0;
            dir = new XYZ(dir.X, dir.Y, 0.0);
            if (dir.GetLength() < 1e-6)
            {
                return false;
            }

            XYZ basisX = dir.Normalize();
            XYZ basisZ = XYZ.BasisZ;
            XYZ basisY = NormalizeOrDefault(basisZ.CrossProduct(basisX), XYZ.BasisY);
            basisX = NormalizeOrDefault(basisY.CrossProduct(basisZ), XYZ.BasisX);
            XYZ origin = (p0 + p1) * 0.5;

            transform = Transform.Identity;
            transform.Origin = origin;
            transform.BasisX = basisX;
            transform.BasisY = basisY;
            transform.BasisZ = basisZ;
            return true;
        }

        private static string TryGetElementLevelName(Document doc, Element element)
        {
            if (doc == null || element == null)
            {
                return "";
            }

            try
            {
                if (doc.GetElement(element.LevelId) is Level level)
                {
                    return level.Name ?? "";
                }
            }
            catch
            {
            }

            BuiltInParameter[] levelParams =
            {
                BuiltInParameter.LEVEL_PARAM,
                BuiltInParameter.FAMILY_LEVEL_PARAM,
                BuiltInParameter.SCHEDULE_LEVEL_PARAM
            };

            foreach (BuiltInParameter bip in levelParams)
            {
                try
                {
                    Parameter p = element.get_Parameter(bip);
                    if (p?.StorageType != StorageType.ElementId)
                    {
                        continue;
                    }

                    ElementId levelId = p.AsElementId();
                    if (levelId == null || levelId == ElementId.InvalidElementId)
                    {
                        continue;
                    }

                    if (doc.GetElement(levelId) is Level level)
                    {
                        return level.Name ?? "";
                    }
                }
                catch
                {
                }
            }

            return "";
        }

        private static string BuildFoundationRebarHostDisplayName(Element host)
        {
            if (host == null)
            {
                return "";
            }

            string hostName = host.Name ?? "";
            if (host is FamilyInstance fi && fi.Symbol != null)
            {
                string family = fi.Symbol.FamilyName ?? "";
                string symbol = fi.Symbol.Name ?? hostName;
                hostName = string.IsNullOrWhiteSpace(family) ? symbol : $"{family} : {symbol}";
            }
            else if (host is Floor floor)
            {
                string typeName = "";
                try
                {
                    typeName = floor.FloorType?.Name ?? "";
                }
                catch
                {
                    typeName = "";
                }

                if (!string.IsNullOrWhiteSpace(typeName))
                {
                    hostName = "Floor : " + typeName;
                }
            }

            if (string.IsNullOrWhiteSpace(hostName) && host.Category != null)
            {
                hostName = host.Category.Name ?? "Foundation";
            }

            if (string.IsNullOrWhiteSpace(hostName))
            {
                hostName = "Foundation";
            }

            return $"Host #{host.Id.Value} | {hostName}";
        }

        private static string InferFoundationRebarTypeMode(Element host)
        {
            if (host is Floor)
            {
                return "Raft / Mat";
            }

            if (host is WallFoundation)
            {
                return "Strip Footing";
            }

            string nameKey = ((host?.Name ?? "") + " " +
                              (host is FamilyInstance fi ? (fi.Symbol?.Name ?? "") + " " + (fi.Symbol?.FamilyName ?? "") : ""))
                .ToUpperInvariant();

            if (nameKey.Contains("PILE") && nameKey.Contains("CAP"))
            {
                return "Pile Cap";
            }

            if (nameKey.Contains("RAFT") || nameKey.Contains("MAT"))
            {
                return "Raft / Mat";
            }

            if (nameKey.Contains("STRIP") || nameKey.Contains("WALL FOUNDATION"))
            {
                return "Strip Footing";
            }

            return "Isolated Footing";
        }

        private static void PopulateColumnRebarElevationContextElements(
            Document doc,
            Element host,
            Transform hostTransform,
            XYZ hostLocalMin,
            XYZ hostLocalMax,
            IList<CamboBIMWindow.ColumnRebarElevationContextElementPreview> target)
        {
            if (doc == null || host == null || hostTransform == null || target == null)
            {
                return;
            }

            target.Clear();

            BoundingBoxXYZ hostBbox = null;
            try
            {
                hostBbox = host.get_BoundingBox(null);
            }
            catch
            {
                hostBbox = null;
            }

            if (hostBbox == null || hostBbox.Min == null || hostBbox.Max == null)
            {
                return;
            }

            double hostWidth = Math.Max(0.0, hostLocalMax.X - hostLocalMin.X);
            double hostDepth = Math.Max(0.0, hostLocalMax.Y - hostLocalMin.Y);
            double hostHeight = Math.Max(0.0, hostLocalMax.Z - hostLocalMin.Z);

            // Search nearby elements only; this keeps preview fast and focused on actual connections.
            double planMarginFt = Math.Max(8.0, Math.Max(hostWidth, hostDepth) * 4.0);
            double verticalMarginFt = Math.Max(10.0, hostHeight * 0.75);
            XYZ searchMin = new XYZ(
                hostBbox.Min.X - planMarginFt,
                hostBbox.Min.Y - planMarginFt,
                hostBbox.Min.Z - verticalMarginFt);
            XYZ searchMax = new XYZ(
                hostBbox.Max.X + planMarginFt,
                hostBbox.Max.Y + planMarginFt,
                hostBbox.Max.Z + verticalMarginFt);

            var categories = new List<BuiltInCategory>
            {
                BuiltInCategory.OST_StructuralFoundation,
                BuiltInCategory.OST_Floors,
                BuiltInCategory.OST_StructuralFraming,
                BuiltInCategory.OST_Walls
            };

            FilteredElementCollector collector = new FilteredElementCollector(doc)
                .WherePasses(new ElementMulticategoryFilter(categories))
                .WhereElementIsNotElementType();

            try
            {
                collector = collector.WherePasses(new BoundingBoxIntersectsFilter(new Outline(searchMin, searchMax)));
            }
            catch
            {
                // Fallback to uncropped collector if outline filter fails.
            }

            double ySliceMarginFt = Math.Max(2.0, hostDepth * 0.75);
            double xLimitMarginFt = Math.Max(12.0, hostWidth * 6.0);
            double zLimitMarginFt = Math.Max(12.0, hostHeight * 1.25);

            var previews = new List<CamboBIMWindow.ColumnRebarElevationContextElementPreview>();

            foreach (Element candidate in collector)
            {
                if (candidate == null || candidate.Id == host.Id)
                {
                    continue;
                }

                string kindKey = GetColumnRebarElevationContextKindKey(candidate);
                if (string.IsNullOrEmpty(kindKey))
                {
                    continue;
                }

                BoundingBoxXYZ bbox = null;
                try
                {
                    bbox = candidate.get_BoundingBox(null);
                }
                catch
                {
                    bbox = null;
                }

                if (bbox == null || bbox.Min == null || bbox.Max == null)
                {
                    continue;
                }

                if (!TryGetLocalBoundsFromWorldBoundingBox(hostTransform, bbox, out XYZ localMin, out XYZ localMax))
                {
                    continue;
                }

                // Only show elements crossing the column section slice neighborhood (local Y).
                if (localMax.Y < (hostLocalMin.Y - ySliceMarginFt) || localMin.Y > (hostLocalMax.Y + ySliceMarginFt))
                {
                    continue;
                }

                // Avoid very far geometry that would make the section unreadable.
                if (localMax.X < (hostLocalMin.X - xLimitMarginFt) || localMin.X > (hostLocalMax.X + xLimitMarginFt))
                {
                    continue;
                }
                if (localMax.Z < (hostLocalMin.Z - zLimitMarginFt) || localMin.Z > (hostLocalMax.Z + zLimitMarginFt))
                {
                    continue;
                }

                double x0 = localMin.X - hostLocalMin.X;
                double x1 = localMax.X - hostLocalMin.X;
                double z0 = localMin.Z - hostLocalMin.Z;
                double z1 = localMax.Z - hostLocalMin.Z;
                if (!IsFiniteNumber(x0) || !IsFiniteNumber(x1) || !IsFiniteNumber(z0) || !IsFiniteNumber(z1))
                {
                    continue;
                }

                string label = BuildColumnRebarElevationContextLabel(candidate, kindKey);
                previews.Add(new CamboBIMWindow.ColumnRebarElevationContextElementPreview
                {
                    ElementId = candidate.Id,
                    KindKey = kindKey,
                    Label = label,
                    X0Ft = Math.Min(x0, x1),
                    X1Ft = Math.Max(x0, x1),
                    Z0Ft = Math.Min(z0, z1),
                    Z1Ft = Math.Max(z0, z1)
                });
            }

            foreach (var item in previews
                .OrderBy(p => GetColumnRebarElevationContextKindSort(p.KindKey))
                .ThenBy(p => p.Z0Ft)
                .ThenBy(p => p.X0Ft)
                .Take(40))
            {
                target.Add(item);
            }
        }

        private static int GetColumnRebarElevationContextKindSort(string kindKey)
        {
            switch ((kindKey ?? "").ToLowerInvariant())
            {
                case "foundation": return 0;
                case "slab": return 1;
                case "beam": return 2;
                case "wall": return 3;
                default: return 9;
            }
        }

        private static bool TryGetColumnRebarTopLapReferenceFromConnectedBeamOrSlab(
            Document doc,
            Element host,
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            out double topRefRelativeFt)
        {
            topRefRelativeFt = 0.0;
            if (doc == null || host == null || hostTransform == null)
            {
                return false;
            }

            var context = new List<CamboBIMWindow.ColumnRebarElevationContextElementPreview>();
            try
            {
                PopulateColumnRebarElevationContextElements(doc, host, hostTransform, localMin, localMax, context);
            }
            catch
            {
                return false;
            }

            if (context.Count == 0)
            {
                return false;
            }

            double widthFt = Math.Max(0.0, localMax.X - localMin.X);
            double heightFt = Math.Max(0.0, localMax.Z - localMin.Z);
            double minRequiredOverlapX = Math.Max(MmToFeet(50.0), widthFt * 0.15);
            double bestZ = double.NegativeInfinity;

            foreach (var item in context)
            {
                if (item == null)
                {
                    continue;
                }

                string kind = (item.KindKey ?? "").Trim();
                if (!string.Equals(kind, "beam", StringComparison.OrdinalIgnoreCase) &&
                    !string.Equals(kind, "slab", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                double x0 = Math.Min(item.X0Ft, item.X1Ft);
                double x1 = Math.Max(item.X0Ft, item.X1Ft);
                double zTop = Math.Max(item.Z0Ft, item.Z1Ft);
                if (!IsFiniteNumber(x0) || !IsFiniteNumber(x1) || !IsFiniteNumber(zTop))
                {
                    continue;
                }

                double overlapX = Math.Min(widthFt, x1) - Math.Max(0.0, x0);
                if (overlapX < minRequiredOverlapX)
                {
                    continue;
                }

                if (zTop <= MmToFeet(1.0))
                {
                    continue;
                }

                if (zTop > heightFt + MmToFeet(5.0))
                {
                    continue;
                }

                if (zTop > bestZ)
                {
                    bestZ = zTop;
                }
            }

            if (!IsFiniteNumber(bestZ) || double.IsNegativeInfinity(bestZ))
            {
                return false;
            }

            topRefRelativeFt = Math.Max(0.0, Math.Min(heightFt, bestZ));
            return true;
        }

        private static bool IsFiniteNumber(double value)
        {
            return !double.IsNaN(value) && !double.IsInfinity(value);
        }

        private static string BuildColumnRebarElevationContextLabel(Element element, string kindKey)
        {
            string shortKind = (kindKey ?? "").ToUpperInvariant();
            if (element == null)
            {
                return shortKind;
            }

            string name = element.Name ?? "";
            if (string.IsNullOrWhiteSpace(name) && element.Category != null)
            {
                name = element.Category.Name ?? "";
            }

            if (string.IsNullOrWhiteSpace(name))
            {
                return $"{shortKind} {element.Id.Value}";
            }

            return $"{shortKind} {element.Id.Value}";
        }

        private static string GetColumnRebarElevationContextKindKey(Element element)
        {
            if (element?.Category == null)
            {
                return "";
            }

            long catId = element.Category.Id.Value;
            if (catId == (int)BuiltInCategory.OST_StructuralFoundation)
            {
                return "foundation";
            }
            if (catId == (int)BuiltInCategory.OST_Floors)
            {
                return "slab";
            }
            if (catId == (int)BuiltInCategory.OST_StructuralFraming)
            {
                return "beam";
            }
            if (catId == (int)BuiltInCategory.OST_Walls)
            {
                return "wall";
            }

            return "";
        }

        private static bool TryGetLocalBoundsFromWorldBoundingBox(
            Transform localFrame,
            BoundingBoxXYZ bbox,
            out XYZ localMin,
            out XYZ localMax)
        {
            localMin = XYZ.Zero;
            localMax = XYZ.Zero;

            if (localFrame == null || bbox == null || bbox.Min == null || bbox.Max == null)
            {
                return false;
            }

            Transform inv;
            try
            {
                inv = localFrame.Inverse;
            }
            catch
            {
                return false;
            }

            var corners = new[]
            {
                new XYZ(bbox.Min.X, bbox.Min.Y, bbox.Min.Z),
                new XYZ(bbox.Max.X, bbox.Min.Y, bbox.Min.Z),
                new XYZ(bbox.Min.X, bbox.Max.Y, bbox.Min.Z),
                new XYZ(bbox.Max.X, bbox.Max.Y, bbox.Min.Z),
                new XYZ(bbox.Min.X, bbox.Min.Y, bbox.Max.Z),
                new XYZ(bbox.Max.X, bbox.Min.Y, bbox.Max.Z),
                new XYZ(bbox.Min.X, bbox.Max.Y, bbox.Max.Z),
                new XYZ(bbox.Max.X, bbox.Max.Y, bbox.Max.Z)
            };

            bool has = false;
            double minX = 0, minY = 0, minZ = 0, maxX = 0, maxY = 0, maxZ = 0;
            foreach (XYZ world in corners)
            {
                XYZ p;
                try
                {
                    p = inv.OfPoint(world);
                }
                catch
                {
                    continue;
                }

                if (!IsFinite(p))
                {
                    continue;
                }

                if (!has)
                {
                    minX = maxX = p.X;
                    minY = maxY = p.Y;
                    minZ = maxZ = p.Z;
                    has = true;
                }
                else
                {
                    if (p.X < minX) minX = p.X;
                    if (p.Y < minY) minY = p.Y;
                    if (p.Z < minZ) minZ = p.Z;
                    if (p.X > maxX) maxX = p.X;
                    if (p.Y > maxY) maxY = p.Y;
                    if (p.Z > maxZ) maxZ = p.Z;
                }
            }

            if (!has)
            {
                return false;
            }

            localMin = new XYZ(minX, minY, minZ);
            localMax = new XYZ(maxX, maxY, maxZ);
            return true;
        }

        private static bool TryGetColumnRebarHostFrameAndBounds(
            Element host,
            out Transform hostTransform,
            out XYZ localMin,
            out XYZ localMax,
            out string error)
        {
            hostTransform = Transform.Identity;
            localMin = XYZ.Zero;
            localMax = XYZ.Zero;
            error = "";

            if (host == null)
            {
                error = "host column not found.";
                return false;
            }

            if (!(host is FamilyInstance fi))
            {
                error = "selected column is not a family instance.";
                return false;
            }

            hostTransform = BuildColumnRebarHostTransform(fi);

            Options options = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = false
            };

            GeometryElement ge = host.get_Geometry(options);
            if (ge == null)
            {
                error = "unable to read column geometry.";
                return false;
            }

            var verticesWorld = new List<XYZ>();
            CollectColumnRebarWorldVertices(ge, verticesWorld);
            if (verticesWorld.Count == 0)
            {
                BoundingBoxXYZ bbox = host.get_BoundingBox(null);
                if (bbox != null)
                {
                    verticesWorld.Add(bbox.Min);
                    verticesWorld.Add(bbox.Max);
                }
            }

            if (verticesWorld.Count == 0)
            {
                error = "unable to extract solid geometry for the selected column.";
                return false;
            }

            Transform inv;
            try
            {
                inv = hostTransform.Inverse;
            }
            catch
            {
                error = "invalid column transform.";
                return false;
            }

            bool has = false;
            double minX = 0, minY = 0, minZ = 0, maxX = 0, maxY = 0, maxZ = 0;
            foreach (XYZ pWorld in verticesWorld)
            {
                if (pWorld == null) continue;
                XYZ p = inv.OfPoint(pWorld);
                if (!IsFinite(p)) continue;

                if (!has)
                {
                    minX = maxX = p.X;
                    minY = maxY = p.Y;
                    minZ = maxZ = p.Z;
                    has = true;
                }
                else
                {
                    if (p.X < minX) minX = p.X;
                    if (p.Y < minY) minY = p.Y;
                    if (p.Z < minZ) minZ = p.Z;
                    if (p.X > maxX) maxX = p.X;
                    if (p.Y > maxY) maxY = p.Y;
                    if (p.Z > maxZ) maxZ = p.Z;
                }
            }

            if (!has)
            {
                error = "column geometry could not be converted to local coordinates.";
                return false;
            }

            localMin = new XYZ(minX, minY, minZ);
            localMax = new XYZ(maxX, maxY, maxZ);

            if ((localMax.X - localMin.X) <= 1e-6 || (localMax.Y - localMin.Y) <= 1e-6 || (localMax.Z - localMin.Z) <= 1e-6)
            {
                error = "column geometry size is invalid for rebar generation.";
                return false;
            }

            return true;
        }

        private static Transform BuildColumnRebarHostTransform(FamilyInstance fi)
        {
            Transform t = null;
            try
            {
                t = fi?.GetTransform();
            }
            catch
            {
                t = null;
            }

            XYZ origin = XYZ.Zero;
            if (fi?.Location is LocationPoint lp)
            {
                origin = lp.Point ?? XYZ.Zero;
            }
            else if (t != null)
            {
                origin = t.Origin;
            }

            XYZ basisX = t?.BasisX ?? XYZ.BasisX;
            XYZ basisY = t?.BasisY ?? XYZ.BasisY;
            XYZ basisZ = t?.BasisZ ?? XYZ.BasisZ;

            basisZ = NormalizeOrDefault(basisZ, XYZ.BasisZ);
            if (basisZ.DotProduct(XYZ.BasisZ) < 0)
            {
                basisZ = basisZ.Negate();
            }

            basisX = NormalizeOrDefault(basisX, XYZ.BasisX);
            basisY = basisZ.CrossProduct(basisX);
            if (basisY.GetLength() < 1e-6)
            {
                basisY = NormalizeOrDefault(t?.BasisY ?? XYZ.BasisY, XYZ.BasisY);
                basisX = basisY.CrossProduct(basisZ);
            }

            basisY = NormalizeOrDefault(basisY, XYZ.BasisY);
            basisX = NormalizeOrDefault(basisY.CrossProduct(basisZ), XYZ.BasisX);

            Transform result = Transform.Identity;
            result.Origin = origin;
            result.BasisX = basisX;
            result.BasisY = basisY;
            result.BasisZ = basisZ;
            return result;
        }

        private static void CollectColumnRebarWorldVertices(GeometryElement ge, List<XYZ> vertices)
        {
            if (ge == null || vertices == null) return;

            foreach (GeometryObject go in ge)
            {
                if (go == null) continue;

                if (go is GeometryInstance gi)
                {
                    GeometryElement instGeom = null;
                    try
                    {
                        instGeom = gi.GetInstanceGeometry();
                    }
                    catch
                    {
                        instGeom = null;
                    }

                    if (instGeom != null)
                    {
                        CollectColumnRebarWorldVertices(instGeom, vertices);
                    }

                    continue;
                }

                if (go is Solid solid && solid.Faces != null && solid.Faces.Size > 0 && solid.Volume > 1e-9)
                {
                    foreach (Face face in solid.Faces)
                    {
                        Mesh mesh = null;
                        try
                        {
                            mesh = face?.Triangulate();
                        }
                        catch
                        {
                            mesh = null;
                        }

                        if (mesh == null || mesh.NumTriangles <= 0) continue;
                        for (int i = 0; i < mesh.NumTriangles; i++)
                        {
                            MeshTriangle tri = mesh.get_Triangle(i);
                            if (tri == null) continue;
                            vertices.Add(tri.get_Vertex(0));
                            vertices.Add(tri.get_Vertex(1));
                            vertices.Add(tri.get_Vertex(2));
                        }
                    }

                    continue;
                }

                if (go is Mesh topMesh && topMesh.NumTriangles > 0)
                {
                    for (int i = 0; i < topMesh.NumTriangles; i++)
                    {
                        MeshTriangle tri = topMesh.get_Triangle(i);
                        if (tri == null) continue;
                        vertices.Add(tri.get_Vertex(0));
                        vertices.Add(tri.get_Vertex(1));
                        vertices.Add(tri.get_Vertex(2));
                    }
                }
            }
        }

        private static bool IsFinite(XYZ p)
        {
            return p != null &&
                   !double.IsNaN(p.X) && !double.IsInfinity(p.X) &&
                   !double.IsNaN(p.Y) && !double.IsInfinity(p.Y) &&
                   !double.IsNaN(p.Z) && !double.IsInfinity(p.Z);
        }

        private static XYZ NormalizeOrDefault(XYZ vector, XYZ fallback)
        {
            if (vector == null || vector.GetLength() < 1e-9)
            {
                return fallback;
            }

            return vector.Normalize();
        }

        private static double GetRebarBarDiameterSafe(RebarBarType barType)
        {
            if (barType == null)
            {
                return 0.0;
            }

            try
            {
                Parameter p = null;
                try
                {
                    p = barType.get_Parameter(BuiltInParameter.REBAR_BAR_DIAMETER);
                }
                catch
                {
                    p = null;
                }

                if (p == null)
                {
                    p = barType.LookupParameter("Bar Diameter");
                }

                if (p == null)
                {
                    p = barType.LookupParameter("Diameter");
                }

                if (p != null && p.StorageType == StorageType.Double)
                {
                    return Math.Max(0.0, p.AsDouble());
                }

                return 0.0;
            }
            catch
            {
                return 0.0;
            }
        }

        private static RebarHookType FindClosestRebarHookTypeByAngle(Document doc, double angleDeg, RebarStyle preferredStyle)
        {
            if (doc == null || angleDeg <= 0.0)
            {
                return null;
            }

            double targetRad = angleDeg * Math.PI / 180.0;
            RebarHookType bestMatch = null;
            double bestDiff = double.MaxValue;

            try
            {
                foreach (RebarHookType hookType in new FilteredElementCollector(doc)
                    .OfClass(typeof(RebarHookType))
                    .Cast<RebarHookType>())
                {
                    if (hookType == null)
                    {
                        continue;
                    }

                    try
                    {
                        // Prefer matching style when available, but still allow fallback if only one style exists.
                        double angle = hookType.HookAngle;
                        double diff = Math.Abs(angle - targetRad);
                        if (hookType.Style != preferredStyle)
                        {
                            diff += 0.01; // small penalty
                        }

                        if (diff < bestDiff)
                        {
                            bestDiff = diff;
                            bestMatch = hookType;
                        }
                    }
                    catch
                    {
                    }
                }
            }
            catch
            {
                return null;
            }

            return bestMatch;
        }

        private static bool TryParseFoundationNaviateHookAngleDeg(string hookLabel, out double angleDeg)
        {
            angleDeg = 0.0;
            string text = (hookLabel ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text) ||
                string.Equals(text, "None", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // UI labels are typically "Standard - 90 deg.", "Standard - 135 deg.", "Standard - 180 deg.",
            // or "Rebar Hook 90". A simple token search is more robust than exact matching.
            if (text.IndexOf("180", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                angleDeg = 180.0;
                return true;
            }

            if (text.IndexOf("135", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                angleDeg = 135.0;
                return true;
            }

            if (text.IndexOf("90", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                angleDeg = 90.0;
                return true;
            }

            return false;
        }

        private static RebarHookType ResolveFoundationNaviateHookType(Document doc, string hookLabel, RebarStyle preferredStyle)
        {
            if (!TryParseFoundationNaviateHookAngleDeg(hookLabel, out double angleDeg))
            {
                return null;
            }

            return FindClosestRebarHookTypeByAngle(doc, angleDeg, preferredStyle);
        }

        private static Rebar CreateRebarFromCurvesPreferShape(
            Document doc,
            RebarStyle style,
            RebarBarType barType,
            RebarShape preferredShape,
            RebarHookType startHookType,
            RebarHookType endHookType,
            Element host,
            XYZ normal,
            IList<Curve> curves,
            RebarHookOrientation startOrientation,
            RebarHookOrientation endOrientation)
        {
            if (doc == null || barType == null || host == null || normal == null || curves == null || curves.Count == 0)
            {
                return null;
            }

            if (preferredShape != null)
            {
                try
                {
                    Rebar byShape = Rebar.CreateFromCurvesAndShape(
                        doc,
                        preferredShape,
                        barType,
                        startHookType,
                        endHookType,
                        host,
                        normal,
                        curves,
                        startOrientation,
                        endOrientation);
                    if (byShape != null)
                    {
                        return byShape;
                    }
                }
                catch
                {
                    // Fall back to curve-driven creation if the selected shape is incompatible with the given curves.
                }
            }

            try
            {
                return Rebar.CreateFromCurves(
                    doc,
                    style,
                    barType,
                    startHookType,
                    endHookType,
                    host,
                    normal,
                    curves,
                    startOrientation,
                    endOrientation,
                    true,
                    true);
            }
            catch
            {
                if (startHookType != null || endHookType != null)
                {
                    try
                    {
                        return Rebar.CreateFromCurves(
                            doc,
                            style,
                            barType,
                            null,
                            null,
                            host,
                            normal,
                            curves,
                            startOrientation,
                            endOrientation,
                            true,
                            true);
                    }
                    catch
                    {
                    }
                }

                return null;
            }
        }

        private static List<XYZ> BuildColumnRebarLocalMainBarPoints(XYZ localMin, XYZ localMax, int barsX, int barsY, double coverFt)
        {
            var result = new List<XYZ>();

            double x0 = localMin.X + Math.Max(0.0, coverFt);
            double x1 = localMax.X - Math.Max(0.0, coverFt);
            double y0 = localMin.Y + Math.Max(0.0, coverFt);
            double y1 = localMax.Y - Math.Max(0.0, coverFt);
            if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6)
            {
                return result;
            }

            barsX = Math.Max(2, barsX);
            barsY = Math.Max(2, barsY);

            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            double tol = MmToFeet(0.1);

            void AddPoint(double x, double y)
            {
                XYZ p = new XYZ(x, y, 0.0);
                string key = $"{Math.Round(p.X / tol):0}|{Math.Round(p.Y / tol):0}";
                if (seen.Add(key))
                {
                    result.Add(p);
                }
            }

            foreach (double x in BuildColumnRebarLinearPositions(x0, x1, barsX))
            {
                AddPoint(x, y0);
                AddPoint(x, y1);
            }

            foreach (double y in BuildColumnRebarLinearPositions(y0, y1, barsY))
            {
                AddPoint(x0, y);
                AddPoint(x1, y);
            }

            return result;
        }

        private static IEnumerable<double> BuildColumnRebarLinearPositions(double start, double end, int count)
        {
            if (count <= 1 || Math.Abs(end - start) < 1e-9)
            {
                yield return start;
                yield break;
            }

            for (int i = 0; i < count; i++)
            {
                double t = (double)i / (count - 1);
                yield return start + (end - start) * t;
            }
        }

        private static HashSet<int> BuildColumnRebarTopLapBarIndexSet(IList<XYZ> points, int coveragePercent)
        {
            var result = new HashSet<int>();
            if (points == null || points.Count == 0)
            {
                return result;
            }

            coveragePercent = Math.Max(0, Math.Min(100, coveragePercent));
            if (coveragePercent <= 0)
            {
                return result;
            }

            if (coveragePercent >= 100)
            {
                for (int i = 0; i < points.Count; i++)
                {
                    result.Add(i);
                }
                return result;
            }

            List<int> ordered = BuildColumnRebarPerimeterOrderedIndices(points);
            if (ordered.Count == 0)
            {
                return BuildColumnRebarTopLapBarIndexSet(points.Count, coveragePercent);
            }

            int requested = Math.Max(1, (int)Math.Ceiling(ordered.Count * (coveragePercent / 100.0)));
            foreach (int orderedPos in BuildDistributedIndices(ordered.Count, requested))
            {
                if (orderedPos >= 0 && orderedPos < ordered.Count)
                {
                    result.Add(ordered[orderedPos]);
                }
            }

            return result;
        }

        private static HashSet<int> BuildColumnRebarTopLapBarIndexSet(int totalCount, int coveragePercent)
        {
            totalCount = Math.Max(0, totalCount);
            coveragePercent = Math.Max(0, Math.Min(100, coveragePercent));
            var result = new HashSet<int>();
            if (totalCount <= 0)
            {
                return result;
            }

            if (coveragePercent >= 100)
            {
                for (int i = 0; i < totalCount; i++)
                {
                    result.Add(i);
                }
                return result;
            }

            if (coveragePercent <= 0)
            {
                return result;
            }

            int requested = Math.Max(1, (int)Math.Ceiling(totalCount * (coveragePercent / 100.0)));
            foreach (int idx in BuildDistributedIndices(totalCount, requested))
            {
                result.Add(idx);
            }

            return result;
        }

        private static List<int> BuildColumnRebarPerimeterOrderedIndices(IList<XYZ> points)
        {
            var ordered = new List<int>();
            if (points == null || points.Count == 0)
            {
                return ordered;
            }

            double minX = double.MaxValue, maxX = double.MinValue;
            double minY = double.MaxValue, maxY = double.MinValue;
            for (int i = 0; i < points.Count; i++)
            {
                XYZ p = points[i];
                if (p == null) continue;
                if (p.X < minX) minX = p.X;
                if (p.X > maxX) maxX = p.X;
                if (p.Y < minY) minY = p.Y;
                if (p.Y > maxY) maxY = p.Y;
            }

            if (!IsFiniteNumber(minX) || !IsFiniteNumber(maxX) || !IsFiniteNumber(minY) || !IsFiniteNumber(maxY))
            {
                return ordered;
            }

            double tol = Math.Max(MmToFeet(0.5), Math.Max(maxX - minX, maxY - minY) * 1e-5);
            var used = new HashSet<int>();

            void AddRange(IEnumerable<int> indices)
            {
                foreach (int idx in indices)
                {
                    if (idx >= 0 && idx < points.Count && used.Add(idx))
                    {
                        ordered.Add(idx);
                    }
                }
            }

            // Clockwise perimeter order: bottom, right, top, left.
            AddRange(Enumerable.Range(0, points.Count)
                .Where(i => points[i] != null && Math.Abs(points[i].Y - minY) <= tol)
                .OrderBy(i => points[i].X));

            AddRange(Enumerable.Range(0, points.Count)
                .Where(i => points[i] != null && Math.Abs(points[i].X - maxX) <= tol)
                .OrderBy(i => points[i].Y));

            AddRange(Enumerable.Range(0, points.Count)
                .Where(i => points[i] != null && Math.Abs(points[i].Y - maxY) <= tol)
                .OrderByDescending(i => points[i].X));

            AddRange(Enumerable.Range(0, points.Count)
                .Where(i => points[i] != null && Math.Abs(points[i].X - minX) <= tol)
                .OrderByDescending(i => points[i].Y));

            // Fallback for any unexpected point not caught by boundary tests.
            AddRange(Enumerable.Range(0, points.Count));
            return ordered;
        }

        private static IEnumerable<int> BuildDistributedIndices(int candidateCount, int requestedCount)
        {
            candidateCount = Math.Max(0, candidateCount);
            requestedCount = Math.Max(0, requestedCount);
            if (candidateCount == 0 || requestedCount == 0)
            {
                yield break;
            }

            if (requestedCount >= candidateCount)
            {
                for (int i = 0; i < candidateCount; i++)
                {
                    yield return i;
                }
                yield break;
            }

            var used = new HashSet<int>();
            if (requestedCount == 1)
            {
                yield return (candidateCount - 1) / 2;
                yield break;
            }

            for (int i = 0; i < requestedCount; i++)
            {
                double t = (double)i / (requestedCount - 1);
                int idx = (int)Math.Round(t * (candidateCount - 1));
                if (used.Add(idx))
                {
                    yield return idx;
                }
            }

            if (used.Count < requestedCount)
            {
                for (int i = 0; i < candidateCount && used.Count < requestedCount; i++)
                {
                    if (used.Add(i))
                    {
                        yield return i;
                    }
                }
            }
        }

        private static List<List<Curve>> BuildColumnRebarTieLoopsWorld(
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            double z0,
            double z1,
            double tieCenterlineCoverFt,
            double bottomSpacingFt,
            double middleSpacingFt,
            double topSpacingFt,
            double bottomZonePercent,
            double middleZonePercent,
            double topZonePercent)
        {
            var loops = new List<List<Curve>>();
            if (hostTransform == null || z1 <= z0 + 1e-6)
            {
                return loops;
            }

            double x0 = localMin.X + Math.Max(0.0, tieCenterlineCoverFt);
            double x1 = localMax.X - Math.Max(0.0, tieCenterlineCoverFt);
            double y0 = localMin.Y + Math.Max(0.0, tieCenterlineCoverFt);
            double y1 = localMax.Y - Math.Max(0.0, tieCenterlineCoverFt);
            if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6)
            {
                return loops;
            }

            List<double> zLevels = BuildColumnRebarTieZLevels(z0, z1, bottomSpacingFt, middleSpacingFt, topSpacingFt, bottomZonePercent, middleZonePercent, topZonePercent);
            foreach (double z in zLevels)
            {
                XYZ p00 = hostTransform.OfPoint(new XYZ(x0, y0, z));
                XYZ p10 = hostTransform.OfPoint(new XYZ(x1, y0, z));
                XYZ p11 = hostTransform.OfPoint(new XYZ(x1, y1, z));
                XYZ p01 = hostTransform.OfPoint(new XYZ(x0, y1, z));

                if (p00.DistanceTo(p10) <= 1e-6 || p10.DistanceTo(p11) <= 1e-6)
                {
                    continue;
                }

                loops.Add(new List<Curve>
                {
                    Line.CreateBound(p00, p10),
                    Line.CreateBound(p10, p11),
                    Line.CreateBound(p11, p01),
                    Line.CreateBound(p01, p00)
                });
            }

            return loops;
        }

        private static List<Curve> BuildColumnRebarInternalTieLinesWorld(
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            double z0,
            double z1,
            double tieCenterlineCoverFt,
            double mainBarCoverLineFt,
            double mainBarDiameterFt,
            int barsX,
            int barsY,
            double bottomSpacingFt,
            double middleSpacingFt,
            double topSpacingFt,
            double bottomZonePercent,
            double middleZonePercent,
            double topZonePercent,
            int innerLegsX,
            int innerLegsY,
            IList<int> selectedXIndices,
            IList<int> selectedYIndices)
        {
            var lines = new List<Curve>();
            if (hostTransform == null || z1 <= z0 + 1e-6)
            {
                return lines;
            }

            innerLegsX = Math.Max(0, innerLegsX);
            innerLegsY = Math.Max(0, innerLegsY);
            if (innerLegsX == 0 && innerLegsY == 0)
            {
                return lines;
            }

            double x0 = localMin.X + Math.Max(0.0, tieCenterlineCoverFt);
            double x1 = localMax.X - Math.Max(0.0, tieCenterlineCoverFt);
            double y0 = localMin.Y + Math.Max(0.0, tieCenterlineCoverFt);
            double y1 = localMax.Y - Math.Max(0.0, tieCenterlineCoverFt);
            if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6)
            {
                return lines;
            }

            List<double> zLevels = BuildColumnRebarTieZLevels(z0, z1, bottomSpacingFt, middleSpacingFt, topSpacingFt, bottomZonePercent, middleZonePercent, topZonePercent);
            List<double> xInternal;
            List<double> yInternal;

            List<double> xCandidates = BuildColumnRebarInternalTieCandidatePositions(
                    localMin.X + Math.Max(0.0, mainBarCoverLineFt),
                    localMax.X - Math.Max(0.0, mainBarCoverLineFt),
                    Math.Max(2, barsX))
                .ToList();
            List<double> yCandidates = BuildColumnRebarInternalTieCandidatePositions(
                    localMin.Y + Math.Max(0.0, mainBarCoverLineFt),
                    localMax.Y - Math.Max(0.0, mainBarCoverLineFt),
                    Math.Max(2, barsY))
                .ToList();

            if (selectedXIndices != null && selectedXIndices.Count > 0)
            {
                xInternal = selectedXIndices
                    .Where(i => i >= 0 && i < xCandidates.Count)
                    .Select(i => xCandidates[i])
                    .Distinct()
                    .ToList();
            }
            else
            {
                xInternal = BuildColumnRebarInnerLinePositions(x0, x1, innerLegsX).ToList();
            }

            if (selectedYIndices != null && selectedYIndices.Count > 0)
            {
                yInternal = selectedYIndices
                    .Where(i => i >= 0 && i < yCandidates.Count)
                    .Select(i => yCandidates[i])
                    .Distinct()
                    .ToList();
            }
            else
            {
                yInternal = BuildColumnRebarInnerLinePositions(y0, y1, innerLegsY).ToList();
            }

            foreach (double z in zLevels)
            {
                foreach (double x in xInternal)
                {
                    if (!TryTrimColumnRebarTieLineAwayFromBarCenters(
                        new XYZ(x, y0, 0.0),
                        new XYZ(x, y1, 0.0),
                        Math.Max(0.0, mainBarDiameterFt),
                        out XYZ aLocal,
                        out XYZ bLocal))
                    {
                        continue;
                    }

                    XYZ p0 = hostTransform.OfPoint(new XYZ(aLocal.X, aLocal.Y, z));
                    XYZ p1 = hostTransform.OfPoint(new XYZ(bLocal.X, bLocal.Y, z));
                    if (p0.DistanceTo(p1) > 1e-6)
                    {
                        lines.Add(Line.CreateBound(p0, p1));
                    }
                }

                foreach (double y in yInternal)
                {
                    if (!TryTrimColumnRebarTieLineAwayFromBarCenters(
                        new XYZ(x0, y, 0.0),
                        new XYZ(x1, y, 0.0),
                        Math.Max(0.0, mainBarDiameterFt),
                        out XYZ aLocal,
                        out XYZ bLocal))
                    {
                        continue;
                    }

                    XYZ p0 = hostTransform.OfPoint(new XYZ(aLocal.X, aLocal.Y, z));
                    XYZ p1 = hostTransform.OfPoint(new XYZ(bLocal.X, bLocal.Y, z));
                    if (p0.DistanceTo(p1) > 1e-6)
                    {
                        lines.Add(Line.CreateBound(p0, p1));
                    }
                }
            }

            return lines;
        }

        private static List<List<Curve>> BuildColumnRebarCustomRectTieLoopsWorld(
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            double z0,
            double z1,
            double tieCenterlineCoverFt,
            double mainBarCoverLineFt,
            double mainBarDiameterFt,
            int barsX,
            int barsY,
            double bottomSpacingFt,
            double middleSpacingFt,
            double topSpacingFt,
            double bottomZonePercent,
            double middleZonePercent,
            double topZonePercent,
            IList<ColumnRebarCustomRectTieSpec> specs)
        {
            var loops = new List<List<Curve>>();
            if (hostTransform == null || z1 <= z0 + 1e-6 || specs == null || specs.Count == 0)
            {
                return loops;
            }

            if (!TryBuildColumnRebarMainBarGridNodeCoordinates(localMin, localMax, mainBarCoverLineFt, barsX, barsY, out var xNodes, out var yNodes))
            {
                return loops;
            }

            List<double> zLevels = BuildColumnRebarTieZLevels(z0, z1, bottomSpacingFt, middleSpacingFt, topSpacingFt, bottomZonePercent, middleZonePercent, topZonePercent);
            foreach (double z in zLevels)
            {
                foreach (ColumnRebarCustomRectTieSpec spec in specs)
                {
                    if (spec == null) continue;
                    if (!TryResolveColumnRebarGridRect(spec.X0GridIndex, spec.Y0GridIndex, spec.X1GridIndex, spec.Y1GridIndex, xNodes, yNodes, out double x0, out double y0, out double x1, out double y1))
                    {
                        continue;
                    }

                    double rectOffset = Math.Max(0.0, mainBarDiameterFt);
                    x0 -= rectOffset;
                    y0 -= rectOffset;
                    x1 += rectOffset;
                    y1 += rectOffset;

                    double clampX0 = localMin.X + Math.Max(0.0, tieCenterlineCoverFt);
                    double clampX1 = localMax.X - Math.Max(0.0, tieCenterlineCoverFt);
                    double clampY0 = localMin.Y + Math.Max(0.0, tieCenterlineCoverFt);
                    double clampY1 = localMax.Y - Math.Max(0.0, tieCenterlineCoverFt);
                    x0 = Math.Max(clampX0, x0);
                    y0 = Math.Max(clampY0, y0);
                    x1 = Math.Min(clampX1, x1);
                    y1 = Math.Min(clampY1, y1);
                    if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6)
                    {
                        continue;
                    }

                    XYZ p00 = hostTransform.OfPoint(new XYZ(x0, y0, z));
                    XYZ p10 = hostTransform.OfPoint(new XYZ(x1, y0, z));
                    XYZ p11 = hostTransform.OfPoint(new XYZ(x1, y1, z));
                    XYZ p01 = hostTransform.OfPoint(new XYZ(x0, y1, z));
                    if (p00.DistanceTo(p10) <= 1e-6 || p10.DistanceTo(p11) <= 1e-6)
                    {
                        continue;
                    }

                    loops.Add(new List<Curve>
                    {
                        Line.CreateBound(p00, p10),
                        Line.CreateBound(p10, p11),
                        Line.CreateBound(p11, p01),
                        Line.CreateBound(p01, p00)
                    });
                }
            }

            return loops;
        }

        private static List<Curve> BuildColumnRebarCustomLineTiesWorld(
            Transform hostTransform,
            XYZ localMin,
            XYZ localMax,
            double z0,
            double z1,
            double mainBarCoverLineFt,
            double mainBarDiameterFt,
            int barsX,
            int barsY,
            double bottomSpacingFt,
            double middleSpacingFt,
            double topSpacingFt,
            double bottomZonePercent,
            double middleZonePercent,
            double topZonePercent,
            IList<ColumnRebarCustomLineTieSpec> specs)
        {
            var lines = new List<Curve>();
            if (hostTransform == null || z1 <= z0 + 1e-6 || specs == null || specs.Count == 0)
            {
                return lines;
            }

            if (!TryBuildColumnRebarMainBarGridNodeCoordinates(localMin, localMax, mainBarCoverLineFt, barsX, barsY, out var xNodes, out var yNodes))
            {
                return lines;
            }

            List<double> zLevels = BuildColumnRebarTieZLevels(z0, z1, bottomSpacingFt, middleSpacingFt, topSpacingFt, bottomZonePercent, middleZonePercent, topZonePercent);
            foreach (double z in zLevels)
            {
                foreach (ColumnRebarCustomLineTieSpec spec in specs)
                {
                    if (spec == null) continue;
                    if (!TryResolveColumnRebarGridLine(spec.X0GridIndex, spec.Y0GridIndex, spec.X1GridIndex, spec.Y1GridIndex, xNodes, yNodes, out XYZ a, out XYZ b))
                    {
                        continue;
                    }

                    if (!TryTrimColumnRebarTieLineAwayFromBarCenters(a, b, Math.Max(0.0, mainBarDiameterFt), out XYZ aTrim, out XYZ bTrim))
                    {
                        continue;
                    }

                    XYZ p0 = hostTransform.OfPoint(new XYZ(aTrim.X, aTrim.Y, z));
                    XYZ p1 = hostTransform.OfPoint(new XYZ(bTrim.X, bTrim.Y, z));
                    if (p0.DistanceTo(p1) > 1e-6)
                    {
                        lines.Add(Line.CreateBound(p0, p1));
                    }
                }
            }

            return lines;
        }

        private static bool TryTrimColumnRebarTieLineAwayFromBarCenters(XYZ a, XYZ b, double trimOffsetFt, out XYZ aTrim, out XYZ bTrim)
        {
            aTrim = a ?? XYZ.Zero;
            bTrim = b ?? XYZ.Zero;
            if (a == null || b == null)
            {
                return false;
            }

            XYZ v = b - a;
            double len = v.GetLength();
            if (len <= 1e-6)
            {
                return false;
            }

            double trim = Math.Max(0.0, trimOffsetFt);
            if (trim <= 1e-9)
            {
                aTrim = a;
                bTrim = b;
                return true;
            }

            // Keep at least a small usable straight segment after trimming from both ends.
            double maxTrimEach = Math.Max(0.0, (len * 0.5) - MmToFeet(5.0));
            trim = Math.Min(trim, maxTrimEach);
            if (trim <= 1e-9)
            {
                return false;
            }

            XYZ dir = v.Normalize();
            aTrim = a + (dir * trim);
            bTrim = b - (dir * trim);
            return aTrim.DistanceTo(bTrim) > 1e-6;
        }

        private static bool TryBuildColumnRebarMainBarGridNodeCoordinates(
            XYZ localMin,
            XYZ localMax,
            double mainBarCoverLineFt,
            int barsX,
            int barsY,
            out List<double> xNodes,
            out List<double> yNodes)
        {
            xNodes = new List<double>();
            yNodes = new List<double>();

            double x0 = localMin.X + Math.Max(0.0, mainBarCoverLineFt);
            double x1 = localMax.X - Math.Max(0.0, mainBarCoverLineFt);
            double y0 = localMin.Y + Math.Max(0.0, mainBarCoverLineFt);
            double y1 = localMax.Y - Math.Max(0.0, mainBarCoverLineFt);
            if (x1 <= x0 + 1e-6 || y1 <= y0 + 1e-6)
            {
                return false;
            }

            xNodes = BuildColumnRebarLinearPositions(x0, x1, Math.Max(2, barsX)).ToList();
            yNodes = BuildColumnRebarLinearPositions(y0, y1, Math.Max(2, barsY)).ToList();
            return xNodes.Count >= 2 && yNodes.Count >= 2;
        }

        private static bool TryResolveColumnRebarGridRect(
            int x0Idx,
            int y0Idx,
            int x1Idx,
            int y1Idx,
            IList<double> xNodes,
            IList<double> yNodes,
            out double x0,
            out double y0,
            out double x1,
            out double y1)
        {
            x0 = y0 = x1 = y1 = 0.0;
            if (!TryResolveColumnRebarGridLine(x0Idx, y0Idx, x1Idx, y1Idx, xNodes, yNodes, out XYZ a, out XYZ b))
            {
                return false;
            }

            x0 = Math.Min(a.X, b.X);
            x1 = Math.Max(a.X, b.X);
            y0 = Math.Min(a.Y, b.Y);
            y1 = Math.Max(a.Y, b.Y);
            return x1 > x0 + 1e-6 && y1 > y0 + 1e-6;
        }

        private static bool TryResolveColumnRebarGridLine(
            int x0Idx,
            int y0Idx,
            int x1Idx,
            int y1Idx,
            IList<double> xNodes,
            IList<double> yNodes,
            out XYZ a,
            out XYZ b)
        {
            a = XYZ.Zero;
            b = XYZ.Zero;
            if (xNodes == null || yNodes == null) return false;
            if (x0Idx < 0 || x1Idx < 0 || y0Idx < 0 || y1Idx < 0) return false;
            if (x0Idx >= xNodes.Count || x1Idx >= xNodes.Count || y0Idx >= yNodes.Count || y1Idx >= yNodes.Count) return false;

            a = new XYZ(xNodes[x0Idx], yNodes[y0Idx], 0.0);
            b = new XYZ(xNodes[x1Idx], yNodes[y1Idx], 0.0);
            return a.DistanceTo(b) > 1e-6;
        }

        private static IEnumerable<double> BuildColumnRebarInternalTieCandidatePositions(double start, double end, int barCount)
        {
            barCount = Math.Max(2, barCount);
            int idx = 0;
            foreach (double p in BuildColumnRebarLinearPositions(start, end, barCount))
            {
                if (idx > 0 && idx < (barCount - 1))
                {
                    yield return p;
                }
                idx++;
            }
        }

        private static IEnumerable<double> BuildColumnRebarInnerLinePositions(double start, double end, int innerLegCount)
        {
            innerLegCount = Math.Max(0, innerLegCount);
            if (innerLegCount <= 0 || end <= start + 1e-9)
            {
                yield break;
            }

            double step = (end - start) / (innerLegCount + 1);
            for (int i = 1; i <= innerLegCount; i++)
            {
                yield return start + (step * i);
            }
        }

        private static void ResolveColumnRebarTieZonePercentsFromLengths(
            double totalHeightFt,
            double bottomLenFt,
            double middleLenFt,
            double topLenFt,
            ref double bottomZonePercent,
            ref double middleZonePercent,
            ref double topZonePercent)
        {
            bottomLenFt = Math.Max(0.0, bottomLenFt);
            middleLenFt = Math.Max(0.0, middleLenFt);
            topLenFt = Math.Max(0.0, topLenFt);

            if (totalHeightFt <= 1e-9)
            {
                bottomZonePercent = middleZonePercent = topZonePercent = 1.0;
                return;
            }

            bool useLengths = bottomLenFt > 1e-9 || middleLenFt > 1e-9 || topLenFt > 1e-9;
            if (!useLengths)
            {
                // Keep incoming percentages, but ensure they remain valid.
                bottomZonePercent = Math.Max(0.0, bottomZonePercent);
                middleZonePercent = Math.Max(0.0, middleZonePercent);
                topZonePercent = Math.Max(0.0, topZonePercent);
                if ((bottomZonePercent + middleZonePercent + topZonePercent) <= 1e-9)
                {
                    bottomZonePercent = middleZonePercent = topZonePercent = 1.0;
                }
                return;
            }

            double reqB = bottomLenFt;
            double reqM = middleLenFt;
            double reqT = topLenFt;
            double sumReq = reqB + reqM + reqT;
            if (sumReq > totalHeightFt + 1e-9 && sumReq > 1e-9)
            {
                double scale = totalHeightFt / sumReq;
                reqB *= scale;
                reqM *= scale;
                reqT *= scale;
                sumReq = totalHeightFt;
            }

            double remaining = Math.Max(0.0, totalHeightFt - sumReq);
            bool autoB = reqB <= 1e-9;
            bool autoM = reqM <= 1e-9;
            bool autoT = reqT <= 1e-9;

            if (!autoB && !autoM && !autoT)
            {
                bottomZonePercent = reqB;
                middleZonePercent = reqM;
                topZonePercent = reqT;
                return;
            }

            double pBauto = autoB ? Math.Max(0.0, bottomZonePercent) : 0.0;
            double pMauto = autoM ? Math.Max(0.0, middleZonePercent) : 0.0;
            double pTauto = autoT ? Math.Max(0.0, topZonePercent) : 0.0;
            double pAutoSum = pBauto + pMauto + pTauto;
            if (pAutoSum <= 1e-9)
            {
                pBauto = autoB ? 1.0 : 0.0;
                pMauto = autoM ? 1.0 : 0.0;
                pTauto = autoT ? 1.0 : 0.0;
                pAutoSum = pBauto + pMauto + pTauto;
            }

            double resolvedB = autoB ? remaining * (pBauto / pAutoSum) : reqB;
            double resolvedM = autoM ? remaining * (pMauto / pAutoSum) : reqM;
            double resolvedT = autoT ? remaining * (pTauto / pAutoSum) : reqT;

            // Downstream code normalizes these values, so sending lengths as weights preserves the zone proportions.
            bottomZonePercent = resolvedB;
            middleZonePercent = resolvedM;
            topZonePercent = resolvedT;

            if ((bottomZonePercent + middleZonePercent + topZonePercent) <= 1e-9)
            {
                bottomZonePercent = middleZonePercent = topZonePercent = 1.0;
            }
        }

        private static List<double> BuildColumnRebarTieZLevels(
            double z0,
            double z1,
            double bottomSpacingFt,
            double middleSpacingFt,
            double topSpacingFt,
            double bottomZonePercent,
            double middleZonePercent,
            double topZonePercent)
        {
            var result = new List<double>();
            if (z1 <= z0 + 1e-6)
            {
                return result;
            }

            double minSpacing = MmToFeet(50.0);
            double sB = Math.Max(minSpacing, bottomSpacingFt);
            double sM = Math.Max(minSpacing, middleSpacingFt);
            double sT = Math.Max(minSpacing, topSpacingFt);

            double height = z1 - z0;
            double zoneBottom = Math.Max(0.0, bottomZonePercent);
            double zoneMiddle = Math.Max(0.0, middleZonePercent);
            double zoneTop = Math.Max(0.0, topZonePercent);
            double zoneSum = zoneBottom + zoneMiddle + zoneTop;
            if (zoneSum <= 1e-9)
            {
                zoneBottom = zoneMiddle = 1.0;
                zoneTop = 1.0;
                zoneSum = 3.0;
            }

            double zBottomEnd = z0 + height * (zoneBottom / zoneSum);
            double zMiddleEnd = zBottomEnd + height * (zoneMiddle / zoneSum);
            double tol = MmToFeet(0.5);

            void AddRange(double start, double end, double spacing, bool includeEnd)
            {
                if (end < start) return;
                if (result.Count == 0 || Math.Abs(result[result.Count - 1] - start) > tol)
                {
                    result.Add(start);
                }

                double z = start + spacing;
                int guard = 0;
                while (z < end - tol && guard < 5000)
                {
                    result.Add(z);
                    z += spacing;
                    guard++;
                }

                if (includeEnd)
                {
                    if (result.Count == 0 || Math.Abs(result[result.Count - 1] - end) > tol)
                    {
                        result.Add(end);
                    }
                }
            }

            AddRange(z0, zBottomEnd, sB, true);
            AddRange(zBottomEnd, zMiddleEnd, sM, true);
            AddRange(zMiddleEnd, z1, sT, true);

            return result
                .Distinct()
                .OrderBy(z => z)
                .ToList();
        }

        private static bool ShouldClearPreview(CadToModelRequestType type)
        {
            return type == CadToModelRequestType.GenerateGridlines ||
                   type == CadToModelRequestType.GenerateFoundations ||
                   type == CadToModelRequestType.GenerateLeanConcrete ||
                   type == CadToModelRequestType.GenerateSoilExcavation ||
                   type == CadToModelRequestType.GenerateSlabs ||
                   type == CadToModelRequestType.GenerateColumns ||
                   type == CadToModelRequestType.GenerateWalls ||
                   type == CadToModelRequestType.GenerateBeams ||
                   type == CadToModelRequestType.GeneratePiles ||
                   type == CadToModelRequestType.GenerateDetailLines;
        }

        private void HighlightPickedCadReferences(UIDocument uidoc, ImportInstance cad, IList<Reference> refs)
        {
            if (uidoc == null || cad == null || refs == null || refs.Count == 0) return;

            try
            {
                Selection selection = uidoc.Selection;
                if (selection != null)
                {
                    MethodInfo setRefs = selection.GetType()
                        .GetMethods(BindingFlags.Instance | BindingFlags.Public)
                        .FirstOrDefault(m =>
                        {
                            if (!string.Equals(m.Name, "SetReferences", StringComparison.OrdinalIgnoreCase)) return false;
                            ParameterInfo[] ps = m.GetParameters();
                            if (ps.Length != 1) return false;
                            Type paramType = ps[0].ParameterType;
                            return paramType.IsAssignableFrom(typeof(List<Reference>)) ||
                                   paramType.IsAssignableFrom(typeof(IList<Reference>)) ||
                                   paramType.IsAssignableFrom(typeof(ICollection<Reference>)) ||
                                   paramType.IsAssignableFrom(typeof(IEnumerable<Reference>));
                        });

                    if (setRefs != null)
                    {
                        setRefs.Invoke(selection, new object[] { refs.ToList() });
                        uidoc.RefreshActiveView();
                        return;
                    }

                    selection.SetElementIds(new List<ElementId> { cad.Id });
                    uidoc.RefreshActiveView();
                }
            }
            catch
            {
                // ignore selection highlight failures
            }
        }

        private void ClearPreviewLines(Document doc)
        {
            if (doc == null || _previewElementIds.Count == 0) return;

            try
            {
                using (Transaction t = new Transaction(doc, "CamboBIM - Clear Preview Lines"))
                {
                    t.Start();
                    foreach (ElementId id in _previewElementIds)
                    {
                        if (id == null || id == ElementId.InvalidElementId) continue;
                        if (doc.GetElement(id) != null)
                        {
                            doc.Delete(id);
                        }
                    }
                    t.Commit();
                }
            }
            catch
            {
                // ignore delete failures
            }
            finally
            {
                _previewElementIds.Clear();
            }
        }

        private void CreatePreviewLines(UIDocument uidoc, Document doc, ImportInstance cad, IList<Reference> refs)
        {
            if (uidoc == null || doc == null || cad == null || refs == null || refs.Count == 0) return;

            View view = doc.ActiveView;
            if (view == null || view.IsTemplate) return;
            if (view.ViewType == ViewType.Schedule || view.ViewType == ViewType.DrawingSheet) return;

            List<Line> lines = ExtractLinesFromSelectedObjects(doc, cad, refs);
            if (lines.Count == 0) return;

            bool is3D = view.ViewType == ViewType.ThreeD;
            var planeCache = new Dictionary<double, SketchPlane>();

            var ogs = new OverrideGraphicSettings();
            ogs.SetProjectionLineColor(new Color(255, 0, 0));
            ogs.SetProjectionLineWeight(6);

            using (Transaction t = new Transaction(doc, "CamboBIM - Preview CAD Lines"))
            {
                t.Start();

                foreach (Line line in lines)
                {
                    if (line == null) continue;

                    try
                    {
                        if (is3D)
                        {
                            double z = (line.GetEndPoint(0).Z + line.GetEndPoint(1).Z) * 0.5;
                            double key = Math.Round(z, 6);
                            if (!planeCache.TryGetValue(key, out SketchPlane sp))
                            {
                                Plane plane = Plane.CreateByNormalAndOrigin(XYZ.BasisZ, new XYZ(0, 0, z));
                                sp = SketchPlane.Create(doc, plane);
                                planeCache[key] = sp;
                                _previewElementIds.Add(sp.Id);
                            }

                            Line projected = ProjectLineToZ(line, z);
                            if (projected == null) continue;

                            ModelCurve mc = doc.Create.NewModelCurve(projected, sp);
                            _previewElementIds.Add(mc.Id);
                            view.SetElementOverrides(mc.Id, ogs);
                        }
                        else
                        {
                            DetailCurve dc = doc.Create.NewDetailCurve(view, line);
                            _previewElementIds.Add(dc.Id);
                            view.SetElementOverrides(dc.Id, ogs);
                        }
                    }
                    catch
                    {
                        // ignore invalid curves
                    }
                }

                t.Commit();
            }
        }

        private void CreatePreviewLinesFromHits(UIDocument uidoc, Document doc, CadShapeHits hits)
        {
            if (uidoc == null || doc == null || hits == null || hits.IsEmpty) return;

            View view = doc.ActiveView;
            if (view == null || view.IsTemplate) return;
            if (view.ViewType == ViewType.Schedule || view.ViewType == ViewType.DrawingSheet) return;

            bool is3D = view.ViewType == ViewType.ThreeD;
            var planeCache = new Dictionary<double, SketchPlane>();
            List<Line> previewLines = hits.Lines.Take(800).ToList();
            double markerHalf = MmToFeet(75.0);

            foreach (XYZ point in hits.CircleCenters
                         .Concat(hits.BlockPoints)
                         .Concat(hits.Polylines.Select(p => p.Center))
                         .Where(p => p != null)
                         .Take(200))
            {
                if (previewLines.Count >= 800)
                {
                    break;
                }

                XYZ px0 = point + new XYZ(-markerHalf, 0, 0);
                XYZ px1 = point + new XYZ(markerHalf, 0, 0);
                XYZ py0 = point + new XYZ(0, -markerHalf, 0);
                XYZ py1 = point + new XYZ(0, markerHalf, 0);
                previewLines.Add(Line.CreateBound(px0, px1));
                previewLines.Add(Line.CreateBound(py0, py1));
            }

            if (previewLines.Count == 0) return;

            var ogs = new OverrideGraphicSettings();
            ogs.SetProjectionLineColor(new Color(255, 0, 0));
            ogs.SetProjectionLineWeight(6);

            using (Transaction t = new Transaction(doc, "CamboBIM - Preview Column Sideline"))
            {
                t.Start();

                foreach (Line line in previewLines)
                {
                    if (line == null) continue;

                    try
                    {
                        if (is3D)
                        {
                            double z = (line.GetEndPoint(0).Z + line.GetEndPoint(1).Z) * 0.5;
                            double key = Math.Round(z, 6);
                            if (!planeCache.TryGetValue(key, out SketchPlane sp))
                            {
                                Plane plane = Plane.CreateByNormalAndOrigin(XYZ.BasisZ, new XYZ(0, 0, z));
                                sp = SketchPlane.Create(doc, plane);
                                planeCache[key] = sp;
                                _previewElementIds.Add(sp.Id);
                            }

                            Line projected = ProjectLineToZ(line, z);
                            if (projected == null) continue;

                            ModelCurve mc = doc.Create.NewModelCurve(projected, sp);
                            _previewElementIds.Add(mc.Id);
                            view.SetElementOverrides(mc.Id, ogs);
                        }
                        else
                        {
                            DetailCurve dc = doc.Create.NewDetailCurve(view, line);
                            _previewElementIds.Add(dc.Id);
                            view.SetElementOverrides(dc.Id, ogs);
                        }
                    }
                    catch
                    {
                        // ignore preview failures
                    }
                }

                t.Commit();
            }
        }

        private void PickColumnSchedule(UIDocument uidoc, Document doc)
        {
            PickedBox box = uidoc.Selection.PickBox(PickBoxStyle.Enclosing, "Drag to select column schedule table");
            if (box == null)
            {
                _window?.ShowStatus("No selection box.");
                return;
            }

            List<ImportInstance> candidates = CollectCandidateCadImports(doc);
            int insideTextCount = 0;
            foreach (ImportInstance cad in candidates)
            {
                List<CadTextLabel> inside = CollectScheduleTextLabelsInsideBox(doc, cad, box);
                insideTextCount += inside.Count;

                if (inside.Count == 0)
                {
                    continue;
                }

                List<List<string>> scheduleRows = BuildColumnScheduleTableRowsFromLabels(inside);
                if (scheduleRows.Count > 1)
                {
                    UseCadImport(doc, cad);
                    _window?.OpenColumnScheduleRowsInElementSchedule(scheduleRows, "CAD schedule");
                    return;
                }

                List<ColumnSectionSpec> specs = ParseColumnScheduleFromLabels(inside);
                if (specs.Count == 0)
                {
                    continue;
                }

                UseCadImport(doc, cad);
                _window?.OpenColumnScheduleRowsInElementSchedule(
                    BuildColumnScheduleRowsFromSpecs(specs),
                    "CAD schedule");
                return;
            }

            List<CadTextLabel> revitTextInside = CollectRevitTextLabelsInsideBox(doc, box);
            insideTextCount += revitTextInside.Count;
            if (revitTextInside.Count > 0)
            {
                List<List<string>> scheduleRows = BuildColumnScheduleTableRowsFromLabels(revitTextInside);
                if (scheduleRows.Count > 1)
                {
                    _window?.OpenColumnScheduleRowsInElementSchedule(scheduleRows, "view text schedule");
                    return;
                }

                List<ColumnSectionSpec> specs = ParseColumnScheduleFromLabels(revitTextInside);
                if (specs.Count > 0)
                {
                    _window?.OpenColumnScheduleRowsInElementSchedule(
                        BuildColumnScheduleRowsFromSpecs(specs),
                        "view text schedule");
                    return;
                }
            }

            if (TryStartColumnScheduleScreenOcr(uidoc, box, out string ocrStatus))
            {
                _window?.ShowStatus(
                    insideTextCount == 0
                        ? "No readable CAD/Revit text found. Reading selected CAD schedule from the screen..."
                        : "Text was found, but no column rows were detected. Trying screen OCR...");
                return;
            }

            if (insideTextCount == 0)
            {
                if (candidates.Count == 0)
                {
                    _window?.ShowStatus("No readable Revit text found inside selected box, and no linked/imported DWG was available. " + ocrStatus);
                    return;
                }

                _window?.ShowStatus("No readable CAD/Revit text found inside selected box. " + ocrStatus);
                return;
            }

            _window?.ShowStatus("Text was found, but no column rows were detected. Include rows like C1 and (250x450)mm. " + ocrStatus);
        }

        private void PickWallSchedule(UIDocument uidoc, Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            PickedBox box = uidoc.Selection.PickBox(PickBoxStyle.Enclosing, "Drag to select wall schedule table");
            if (box == null)
            {
                _window?.ShowStatus("No selection box.");
                return;
            }

            List<CadTextLabel> labels = CollectCadTextLabels(doc, cad, "");
            List<CadTextLabel> inside = labels
                .Where(l => l.Position.X >= box.Min.X && l.Position.X <= box.Max.X &&
                            l.Position.Y >= box.Min.Y && l.Position.Y <= box.Max.Y)
                .ToList();

            if (inside.Count == 0)
            {
                _window?.ShowStatus("No CAD text found inside selection.");
                return;
            }

            List<WallSectionSpec> specs = ParseWallScheduleFromLabels(inside);
            if (specs.Count == 0)
            {
                _window?.ShowStatus("No valid rows found in schedule. Ensure MARK and TYPE columns exist.");
                return;
            }

            _window?.OpenElementScheduleRowsInElementSchedule(
                BuildWallScheduleRowsFromSpecs(specs),
                "CAD schedule",
                "Wall");
        }

