        private void AutoDetectColumns(Document doc)
        {
            if (!TryGetSelectedOrFirstCad(doc, "No linked/imported DWG found for Column auto-detect.", out ImportInstance cad))
            {
                return;
            }

            var layers = CollectCadLayers(doc, cad);
            AutoDetectColumns(doc, cad, layers, Request.SelectedLayerName, Request.UseLayerFilter);
        }

        private void AutoDetectWalls(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            var layers = CollectCadLayers(doc, cad);

            string layerName = Request.SelectedLayerName ?? "";
            if (Request.UseLayerFilter)
            {
                if (string.IsNullOrWhiteSpace(layerName) || !LayerExists(layers, layerName))
                {
                    layerName = FindBestWallLayerByName(layers);
                    if (string.IsNullOrWhiteSpace(layerName))
                    {
                        layerName = FindBestWallLayerByGeometry(doc, cad, layers);
                    }
                }
            }

            List<Line> lines = null;
            if (!string.IsNullOrWhiteSpace(layerName))
            {
                lines = ExtractWallLinesFromLayer(doc, cad, layerName);
            }
            else if (Request.SelectedCadReferences != null && Request.SelectedCadReferences.Count > 0)
            {
                lines = ExtractWallLinesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
            }

            if (lines == null || lines.Count == 0)
            {
                _window?.ShowStatus("Auto Detect: No wall lines found.");
                return;
            }

            _window?.ApplyWallAutoSettings(layerName, lines.Count);
        }

