        private void AutoDetectColumns(
            Document doc,
            ImportInstance cad,
            List<string> layers,
            string selectedLayerName,
            bool useLayerMode)
        {
            string layerName = selectedLayerName ?? "";

            if (!useLayerMode && (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0))
            {
                useLayerMode = true;
            }

            CadShapeHits hits;
            if (Request.UseColorFilter)
            {
                if (string.IsNullOrWhiteSpace(Request.SelectedColumnSidelineColorKey))
                {
                    _window?.ShowStatus("Auto-Identify: Pick Column Sideline color first.");
                    return;
                }

                hits = ExtractShapesFromColor(doc, cad, Request.SelectedColumnSidelineColorKey);
            }
            else if (useLayerMode)
            {
                if (string.IsNullOrWhiteSpace(layerName) || !LayerExists(layers, layerName))
                {
                    layerName = FindBestColumnLayerByName(layers);
                    if (string.IsNullOrWhiteSpace(layerName))
                    {
                        layerName = FindBestColumnLayerByGeometry(doc, cad, layers);
                    }
                }

                if (string.IsNullOrWhiteSpace(layerName))
                {
                    _window?.ShowStatus("Auto-Identify: No column layer found.");
                    return;
                }

                hits = ExtractShapesFromLayer(doc, cad, layerName);
            }
            else
            {
                if (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0)
                {
                    _window?.ShowStatus("Auto-Identify: Select CAD data or switch to By Layer.");
                    return;
                }

                hits = ExtractShapesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
            }

            if (hits == null || hits.IsEmpty)
            {
                _window?.ShowStatus("Auto-Identify: No valid CAD geometry found.");
                return;
            }

            bool useCircles = hits.CircleCenters.Count > 0;
            bool useBlocks = hits.BlockPoints.Count > 0;
            bool useLines = hits.Lines.Count > 1 && !useCircles && !useBlocks;

            int previewCount = EstimateColumnCount(hits, useCircles, useBlocks, useLines);
            _window?.ApplyColumnAutoSettings(layerName, useCircles, useBlocks, useLines, previewCount);
        }

