        private void EditTypeProperties(
            UIApplication app,
            UIDocument uidoc,
            Document doc,
            ElementId typeId,
            string typeDisplayName,
            IList<BuiltInCategory> candidateCategories)
        {
            string safeTypeName = string.IsNullOrWhiteSpace(typeDisplayName) ? "type" : typeDisplayName.Trim();
            if (typeId == null || typeId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Select " + safeTypeName + ".");
                return;
            }

            if (!(doc.GetElement(typeId) is ElementType))
            {
                _window?.ShowStatus("Selected " + safeTypeName + " not found.");
                return;
            }

            ElementId instanceId = ElementId.InvalidElementId;
            if (candidateCategories != null)
            {
                foreach (BuiltInCategory category in candidateCategories.Distinct())
                {
                    instanceId = FindInstanceIdByType(doc, typeId, category);
                    if (instanceId != ElementId.InvalidElementId)
                    {
                        break;
                    }
                }
            }

            var ids = new List<ElementId> { instanceId != ElementId.InvalidElementId ? instanceId : typeId };
            uidoc.Selection.SetElementIds(ids);

            RevitCommandId commandId = RevitCommandId.LookupPostableCommandId(PostableCommand.TypeProperties);
            if (commandId == null || !app.CanPostCommand(commandId))
            {
                _window?.ShowStatus("Type Properties command is not available.");
                return;
            }

            app.PostCommand(commandId);
        }

        private void SelectSiteProgressElements(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            List<int> target = Request.SiteProgressTargetElementIds ?? new List<int>();
            if (target.Count == 0)
            {
                _window?.ShowStatus("Site Progress: selected row has no model elements.");
                return;
            }

            var validIds = target
                .Distinct()
                .Select(i => new ElementId((long)i))
                .Where(id => id != ElementId.InvalidElementId && doc.GetElement(id) != null)
                .ToList();

            if (validIds.Count == 0)
            {
                _window?.ShowStatus("Site Progress: linked elements were not found in this model.");
                return;
            }

            uidoc.Selection.SetElementIds(validIds);
            try
            {
                uidoc.ShowElements(validIds);
            }
            catch
            {
            }

            _window?.ShowStatus($"Site Progress: selected {validIds.Count} element(s) in model.");
        }

        private void FocusSiteProgressByCurrentFilter(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null || Request == null)
            {
                return;
            }

            string structure = (Request.SiteProgressStructureFilter ?? "").Trim();
            string building = (Request.SiteProgressBuildingLevelFilter ?? "").Trim();
            bool hasStructureFilter = !string.IsNullOrWhiteSpace(structure) &&
                                      !string.Equals(structure, "All", StringComparison.OrdinalIgnoreCase);
            bool hasBuildingFilter = !string.IsNullOrWhiteSpace(building) &&
                                     !string.Equals(building, "All", StringComparison.OrdinalIgnoreCase);

            // Only force model focus when a real filter is selected.
            if (!hasStructureFilter && !hasBuildingFilter)
            {
                ClearSiteProgressTemporaryIsolate(doc);
                return;
            }

            List<ElementId> ids = CBIM_SITE_PROGRESS.CollectFilteredElementIds(uidoc, doc, Request);
            if (ids.Count == 0)
            {
                _window?.ShowStatus("Site Progress: no elements found for current filters.");
                return;
            }

            uidoc.Selection.SetElementIds(ids);
            try
            {
                if (ids.Count <= 300)
                {
                    uidoc.ShowElements(ids);
                }
                else
                {
                    uidoc.ShowElements(new List<ElementId> { ids[0] });
                }
            }
            catch
            {
            }

            IsolateSiteProgressElementsInActiveView(doc, ids);
            _window?.ShowStatus("Site Progress: focused filtered elements in active view (" +
                                ids.Count.ToString(CultureInfo.InvariantCulture) + ").");
        }

        private static void IsolateSiteProgressElementsInActiveView(Document doc, ICollection<ElementId> ids)
        {
            if (doc == null || ids == null || ids.Count == 0)
            {
                return;
            }

            View activeView = doc.ActiveView;
            if (activeView == null || !(activeView is View3D))
            {
                return;
            }

            try
            {
                using (Transaction t = new Transaction(doc, "CamboBIM - Focus Site Progress Filter"))
                {
                    t.Start();
                    try
                    {
                        activeView.DisableTemporaryViewMode(TemporaryViewMode.TemporaryHideIsolate);
                    }
                    catch
                    {
                    }

                    activeView.IsolateElementsTemporary(ids);
                    t.Commit();
                }
            }
            catch
            {
            }
        }

        private static void ClearSiteProgressTemporaryIsolate(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            View activeView = doc.ActiveView;
            if (activeView == null)
            {
                return;
            }

            try
            {
                using (Transaction t = new Transaction(doc, "CamboBIM - Clear Site Progress Focus"))
                {
                    t.Start();
                    activeView.DisableTemporaryViewMode(TemporaryViewMode.TemporaryHideIsolate);
                    t.Commit();
                }
            }
            catch
            {
            }
        }

        private void ApplySiteProgressColorView(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null || Request == null)
            {
                return;
            }

            if (!(doc.ActiveView is View3D active3D))
            {
                _window?.ShowStatus("Site Progress color view works only in a 3D view. Open a 3D view first.");
                return;
            }

            List<ElementId> targetIds = CBIM_SITE_PROGRESS.CollectFilteredElementIds(uidoc, doc, Request)
                .Where(id => id != null && id != ElementId.InvalidElementId && doc.GetElement(id) != null)
                .Distinct()
                .ToList();

            if (targetIds.Count == 0)
            {
                _window?.ShowStatus("Site Progress: no elements found for current filters. 3D color view not applied.");
                return;
            }

            List<ElementId> clearIds = CollectSiteProgressCategoryElementIdsInView(doc, active3D);
            ElementId solidFillPatternId = GetSolidFillPatternId(doc);

            int countNotStarted = 0;
            int count0To25 = 0;
            int count25To50 = 0;
            int count50To75 = 0;
            int count75To99 = 0;
            int countCompleted = 0;
            int painted = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - Color Site Progress"))
            {
                t.Start();

                // Clear existing Site Progress color overrides in this active view before repainting.
                foreach (ElementId id in clearIds)
                {
                    if (id == null || id == ElementId.InvalidElementId) continue;
                    active3D.SetElementOverrides(id, new OverrideGraphicSettings());
                }

                foreach (ElementId id in targetIds)
                {
                    Element element = doc.GetElement(id);
                    if (element == null) continue;

                    double progress = ReadSiteProgressPercentForColor(element);
                    SiteProgressColorBand band = ResolveSiteProgressColorBand(progress);
                    active3D.SetElementOverrides(id, BuildSiteProgressOverrideSettings(band, solidFillPatternId));

                    painted++;
                    if (band == SiteProgressColorBand.NotStarted) countNotStarted++;
                    else if (band == SiteProgressColorBand.Range0To25) count0To25++;
                    else if (band == SiteProgressColorBand.Range25To50) count25To50++;
                    else if (band == SiteProgressColorBand.Range50To75) count50To75++;
                    else if (band == SiteProgressColorBand.Range75To99) count75To99++;
                    else countCompleted++;
                }

                t.Commit();
            }

            try
            {
                uidoc.RefreshActiveView();
            }
            catch
            {
            }

            _window?.ShowStatus(
                "3D Site Progress color applied: " + painted.ToString(CultureInfo.InvariantCulture) + " element(s). " +
                "0%=" + countNotStarted.ToString(CultureInfo.InvariantCulture) +
                " | 0-25%=" + count0To25.ToString(CultureInfo.InvariantCulture) +
                " | 25-50%=" + count25To50.ToString(CultureInfo.InvariantCulture) +
                " | 50-75%=" + count50To75.ToString(CultureInfo.InvariantCulture) +
                " | 75-99%=" + count75To99.ToString(CultureInfo.InvariantCulture) +
                " | 100%=" + countCompleted.ToString(CultureInfo.InvariantCulture) + ".");
        }

        private void ClearSiteProgressColorView(Document doc)
        {
            if (doc == null)
            {
                return;
            }

            if (!(doc.ActiveView is View3D active3D))
            {
                _window?.ShowStatus("Clear 3D color works only in a 3D view.");
                return;
            }

            List<ElementId> ids = CollectSiteProgressCategoryElementIdsInView(doc, active3D);
            if (ids.Count == 0)
            {
                _window?.ShowStatus("3D Site Progress color cleared (no elements found in this view).");
                return;
            }

            using (Transaction t = new Transaction(doc, "CamboBIM - Clear Site Progress Color"))
            {
                t.Start();
                foreach (ElementId id in ids)
                {
                    if (id == null || id == ElementId.InvalidElementId) continue;
                    active3D.SetElementOverrides(id, new OverrideGraphicSettings());
                }
                t.Commit();
            }

            _window?.ShowStatus("3D Site Progress color cleared in active 3D view.");
        }

        private static List<ElementId> CollectSiteProgressCategoryElementIdsInView(Document doc, View view)
        {
            if (doc == null || view == null)
            {
                return new List<ElementId>();
            }

            var categories = SiteProgressSummaryCategories.ToList();
            var filter = new ElementMulticategoryFilter(categories);
            return new FilteredElementCollector(doc, view.Id)
                .WherePasses(filter)
                .WhereElementIsNotElementType()
                .ToElementIds()
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .Distinct()
                .ToList();
        }

        private static ElementId GetSolidFillPatternId(Document doc)
        {
            if (doc == null) return ElementId.InvalidElementId;

            FillPatternElement solid = new FilteredElementCollector(doc)
                .OfClass(typeof(FillPatternElement))
                .Cast<FillPatternElement>()
                .FirstOrDefault(fp =>
                {
                    FillPattern pattern = fp?.GetFillPattern();
                    return pattern != null && pattern.IsSolidFill;
                });

            return solid?.Id ?? ElementId.InvalidElementId;
        }

        private static SiteProgressColorBand ResolveSiteProgressColorBand(double progress)
        {
            double p = ClampPercent(progress);
            if (p <= 0.001) return SiteProgressColorBand.NotStarted;
            if (p < 25.0) return SiteProgressColorBand.Range0To25;
            if (p < 50.0) return SiteProgressColorBand.Range25To50;
            if (p < 75.0) return SiteProgressColorBand.Range50To75;
            if (p < 99.999) return SiteProgressColorBand.Range75To99;
            return SiteProgressColorBand.Completed;
        }

        private static OverrideGraphicSettings BuildSiteProgressOverrideSettings(SiteProgressColorBand band, ElementId solidFillPatternId)
        {
            Color fillColor;
            Color lineColor;
            int transparency;

            switch (band)
            {
                case SiteProgressColorBand.NotStarted:
                    fillColor = new Color(188, 198, 214);     // blue-gray
                    lineColor = new Color(102, 120, 148);
                    transparency = 25;
                    break;
                case SiteProgressColorBand.Range0To25:
                    fillColor = new Color(225, 104, 110);     // red
                    lineColor = new Color(158, 59, 65);
                    transparency = 18;
                    break;
                case SiteProgressColorBand.Range25To50:
                    fillColor = new Color(242, 154, 74);      // orange
                    lineColor = new Color(179, 107, 45);
                    transparency = 14;
                    break;
                case SiteProgressColorBand.Range50To75:
                    fillColor = new Color(242, 200, 84);      // amber
                    lineColor = new Color(173, 136, 43);
                    transparency = 10;
                    break;
                case SiteProgressColorBand.Range75To99:
                    fillColor = new Color(141, 198, 114);     // light green
                    lineColor = new Color(88, 137, 70);
                    transparency = 8;
                    break;
                default:
                    fillColor = new Color(46, 139, 87);       // completed green
                    lineColor = new Color(28, 94, 58);
                    transparency = 4;
                    break;
            }

            var ogs = new OverrideGraphicSettings();
            ogs.SetProjectionLineColor(lineColor);
            ogs.SetCutLineColor(lineColor);
            ogs.SetSurfaceForegroundPatternColor(fillColor);
            ogs.SetCutForegroundPatternColor(fillColor);
            ogs.SetSurfaceTransparency(transparency);

            if (solidFillPatternId != ElementId.InvalidElementId)
            {
                ogs.SetSurfaceForegroundPatternId(solidFillPatternId);
                ogs.SetCutForegroundPatternId(solidFillPatternId);
                ogs.SetSurfaceForegroundPatternVisible(true);
                ogs.SetCutForegroundPatternVisible(true);
            }

            return ogs;
        }

        private static double ReadSiteProgressPercentForColor(Element element)
        {
            if (element == null) return 0.0;

            Parameter volume = element.LookupParameter(SiteProgressVolumeParamName);
            bool hasVolume = TryReadProgressPercent(volume, out double volumePercent);
            bool volumeHasValue = HasExplicitProgressValue(volume);

            Parameter legacy = element.LookupParameter(SiteProgressLegacyParamName);
            bool hasLegacy = TryReadProgressPercent(legacy, out double legacyPercent);
            bool legacyHasValue = HasExplicitProgressValue(legacy);

            if (hasVolume && volumeHasValue)
            {
                if (Math.Abs(volumePercent) <= 1e-9 && hasLegacy && legacyHasValue && legacyPercent > 0.0)
                {
                    return ClampPercent(legacyPercent);
                }

                return ClampPercent(volumePercent);
            }

            if (hasLegacy && legacyHasValue)
            {
                return ClampPercent(legacyPercent);
            }

            if (hasVolume) return ClampPercent(volumePercent);
            if (hasLegacy) return ClampPercent(legacyPercent);
            return 0.0;
        }

        private static bool TryReadProgressPercent(Parameter p, out double percent)
        {
            percent = 0.0;
            if (p == null) return false;

            if (p.StorageType == StorageType.Double)
            {
                double raw = p.AsDouble();
                bool showPercent = IsDisplayPercent(p);
                percent = showPercent ? (raw * 100.0) : raw;
                return true;
            }

            if (p.StorageType == StorageType.Integer)
            {
                percent = p.AsInteger();
                return true;
            }

            if (p.StorageType == StorageType.String)
            {
                return TryParsePercent(p.AsString(), out percent);
            }

            return false;
        }

        private static bool HasExplicitProgressValue(Parameter p)
        {
            if (p == null) return false;
            try
            {
                if (!p.HasValue) return false;
            }
            catch
            {
            }

            if (p.StorageType == StorageType.String)
            {
                string raw = p.AsString();
                if (!string.IsNullOrWhiteSpace(raw)) return true;
                string display = p.AsValueString();
                return !string.IsNullOrWhiteSpace(display);
            }

            return true;
        }

        private static bool IsDisplayPercent(Parameter p)
        {
            if (p == null) return false;
            try
            {
                string value = p.AsValueString();
                return !string.IsNullOrWhiteSpace(value) &&
                       value.IndexOf("%", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryParsePercent(string raw, out double value)
        {
            value = 0.0;
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            string normalized = raw.Trim().Replace("%", "");
            return double.TryParse(normalized, NumberStyles.Float, CultureInfo.InvariantCulture, out value) ||
                   double.TryParse(normalized, NumberStyles.Float, CultureInfo.CurrentCulture, out value);
        }

        private static double ClampPercent(double percent)
        {
            if (double.IsNaN(percent) || double.IsInfinity(percent))
            {
                return 0.0;
            }

            if (percent < 0.0) return 0.0;
            if (percent > 100.0) return 100.0;
            return percent;
        }

        private static ElementId FindInstanceIdByType(Document doc, ElementId typeId, BuiltInCategory category)
        {
            Element match = new FilteredElementCollector(doc)
                .OfCategory(category)
                .WhereElementIsNotElementType()
                .FirstOrDefault(e => e.GetTypeId() == typeId);

            return match?.Id ?? ElementId.InvalidElementId;
        }

        private void GenerateColumns(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            if (!Request.UseCircles && !Request.UseBlocks && !Request.UseLineIntersections)
            {
                _window?.ShowStatus("Select at least one geometry option (Circles, Blocks, or Line Intersections).");
                return;
            }

            if (!(doc.GetElement(Request.ColumnTypeId) is FamilySymbol columnType) || !(doc.GetElement(Request.BaseLevelId) is Level baseLevel) || !(doc.GetElement(Request.TopLevelId) is Level topLevel))
            {
                _window?.ShowStatus("Select column type, base level, and top level.");
                return;
            }

            if (topLevel.Elevation < baseLevel.Elevation)
            {
                _window?.ShowStatus("Top Level must be above Base Level.");
                return;
            }

            IList<Reference> sidelineReferences = Request.SelectedColumnSidelineReferences != null &&
                                                  Request.SelectedColumnSidelineReferences.Count > 0
                ? Request.SelectedColumnSidelineReferences
                : Request.SelectedCadReferences;

            CadShapeHits hits;
            if (Request.HasSelectedColumnSidelineBox)
            {
                hits = ExtractShapesFromBox(
                    doc,
                    cad,
                    Request.SelectedColumnSidelineBoxMin,
                    Request.SelectedColumnSidelineBoxMax,
                    Request.UseLayerFilter ? Request.SelectedLayerName : "",
                    Request.UseColorFilter ? Request.SelectedColumnSidelineColorKey : "",
                    null,
                    null);
            }
            else
            {
                hits = Request.UseLayerFilter
                    ? ExtractShapesFromLayer(doc, cad, Request.SelectedLayerName)
                    : (Request.UseColorFilter && !string.IsNullOrWhiteSpace(Request.SelectedColumnSidelineColorKey)
                        ? ExtractShapesFromColor(doc, cad, Request.SelectedColumnSidelineColorKey)
                        : ExtractShapesFromSelectedObjects(doc, cad, sidelineReferences));
            }

            bool hasExplicitPoints = Request.ExplicitColumnPoints != null &&
                                     Request.ExplicitColumnPoints.Any(p => p != null);
            if ((hits == null || hits.IsEmpty) && !hasExplicitPoints)
            {
                _window?.ShowStatus("No valid CAD geometry found.");
                return;
            }

            List<XYZ> points = hasExplicitPoints
                ? Request.ExplicitColumnPoints.Where(p => p != null).ToList()
                : BuildPointsFromHits(hits);
            if (points.Count == 0)
            {
                _window?.ShowStatus("No valid CAD geometry found.");
                return;
            }

            double tolFt = GetTasRdpToleranceFt(10.0);
            List<XYZ> uniquePts = DeduplicatePoints(points, tolFt);

            int created = 0;
            int typeCreated = 0;
            int typeSkipped = 0;

                Dictionary<string, ColumnSectionSpec> specByName = BuildSpecNameMap(Request.ColumnSectionSpecs);
                Dictionary<string, ColumnSectionSpec> specBySize = BuildSpecSizeMap(Request.ColumnSectionSpecs);
                ColumnSectionSpec layerSpec = MatchSpecFromLabel(Request.SelectedLayerName, specByName, specBySize, false);
            Dictionary<ColumnSectionSpec, FamilySymbol> typeBySpec = new Dictionary<ColumnSectionSpec, FamilySymbol>();
            Dictionary<string, FamilySymbol> typeByName = new Dictionary<string, FamilySymbol>(StringComparer.OrdinalIgnoreCase);

            using (Transaction t = new Transaction(doc, "CamboBIM - Identify Columns"))
            {
                t.Start();

                if (!columnType.IsActive) columnType.Activate();

                if (Request.CreateColumnTypesFromExcel && Request.ColumnSectionSpecs != null && Request.ColumnSectionSpecs.Count > 0)
                {
                    EnsureColumnTypesFromExcel(doc, columnType, Request.ColumnSectionSpecs, typeBySpec, typeByName, out typeCreated, out typeSkipped);
                }

                List<CadTextLabel> labels = null;
                double labelSearchMaxDistFt = GetTasCadLineSearchDistanceFt(1000.0);
                if (specByName.Count > 0 || specBySize.Count > 0)
                {
                    string labelLayer = Request.SelectedLabelLayerName ?? "";
                    if (Request.UseColumnLabelColorFilter &&
                        !string.IsNullOrWhiteSpace(Request.SelectedColumnLabelColorKey))
                    {
                        labels = CollectCadTextLabelsByColor(doc, cad, Request.SelectedColumnLabelColorKey);
                    }
                    else if (Request.UseColumnLabelSelectionFilter &&
                        Request.SelectedColumnLabelReferences != null &&
                        Request.SelectedColumnLabelReferences.Count > 0)
                    {
                        labels = CollectCadTextLabelsFromSelectedObjects(doc, cad, Request.SelectedColumnLabelReferences, "");
                    }
                    else if (!string.IsNullOrWhiteSpace(labelLayer))
                    {
                        labelSearchMaxDistFt = Math.Max(GetTasCadLineSearchDistanceFt(3000.0), MmToFeet(1000.0));
                        labels = CollectCadTextLabels(doc, cad, labelLayer);
                    }
                    else if (!Request.UseLayerFilter &&
                             Request.SelectedCadReferences != null &&
                             Request.SelectedCadReferences.Count > 0)
                    {
                        labels = CollectCadTextLabelsFromSelectedObjects(doc, cad, Request.SelectedCadReferences, "");
                        if (labels.Count == 0)
                        {
                            labels = CollectCadTextLabels(doc, cad, "");
                        }
                    }
                    else
                    {
                        labels = CollectCadTextLabels(doc, cad, "");
                    }
                }

                foreach (XYZ p in uniquePts)
                {
                    FamilySymbol symbol = columnType;
                    if (typeBySpec.Count > 0)
                    {
                        ColumnSectionSpec spec = ResolveColumnSpecForPoint(p, hits, labels, specByName, specBySize, layerSpec, labelSearchMaxDistFt);
                        if (spec != null && typeBySpec.TryGetValue(spec, out FamilySymbol mappedType))
                        {
                            symbol = mappedType ?? columnType;
                        }
                    }

                    if (!symbol.IsActive) symbol.Activate();

                    FamilyInstance fi = doc.Create.NewFamilyInstance(
                        p,
                        symbol,
                        baseLevel,
                        StructuralType.Column);

                    SetTopLevel(fi, topLevel);
                    ApplyTasAttributesToElement(fi);
                    created++;
                }

                t.Commit();
            }

            if (typeCreated > 0 || typeSkipped > 0)
            {
                _window?.ShowStatus($"Created columns: {created} (from {uniquePts.Count} points). Types: {typeCreated} created, {typeSkipped} skipped.");
            }
            else
            {
                _window?.ShowStatus($"Created columns: {created} (from {uniquePts.Count} points).");
            }
        }

        private void GenerateWalls(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            if (!(doc.GetElement(Request.WallTypeId) is WallType wallType) || !(doc.GetElement(Request.BaseLevelId) is Level baseLevel) || !(doc.GetElement(Request.TopLevelId) is Level topLevel))
            {
                _window?.ShowStatus("Select wall type, base level, and top level.");
                return;
            }

            if (topLevel.Elevation < baseLevel.Elevation)
            {
                _window?.ShowStatus("Top Level must be above Base Level.");
                return;
            }

            Dictionary<string, WallSectionSpec> specByName = BuildWallSpecNameMap(Request.WallSectionSpecs);
            Dictionary<string, WallSectionSpec> specBySize = BuildWallSpecSizeMap(Request.WallSectionSpecs);
            WallSectionSpec layerSpec = MatchWallSpecFromLabel(Request.SelectedLayerName, specByName, specBySize);
            Dictionary<WallSectionSpec, WallType> typeBySpec = new Dictionary<WallSectionSpec, WallType>();
            Dictionary<string, WallType> typeByName = new Dictionary<string, WallType>(StringComparer.OrdinalIgnoreCase);
            int typeCreated = 0;
            int typeSkipped = 0;

            List<CurveLoop> loops = Request.UseLayerFilter
                ? ExtractClosedLoopsFromLayer(doc, cad, Request.SelectedLayerName)
                : ExtractClosedLoopsFromSelectedObjects(doc, cad, Request.SelectedCadReferences);

            CurveLoop outerLoop = SelectOutermostLoop(loops);
            List<Curve> loopCurves = outerLoop?.ToList();

            List<Line> wallLines = null;
            if (loopCurves == null || loopCurves.Count == 0)
            {
                wallLines = Request.UseLayerFilter
                    ? ExtractWallLinesFromLayer(doc, cad, Request.SelectedLayerName)
                    : ExtractWallLinesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);

                if (wallLines == null || wallLines.Count == 0)
                {
                    _window?.ShowStatus("No valid CAD wall centerlines found.");
                    return;
                }

                List<Line> flattened = wallLines
                    .Select(FlattenLine)
                    .Where(l => l != null)
                    .ToList();

                if (flattened.Count == 0)
                {
                    _window?.ShowStatus("No valid CAD wall centerlines found.");
                    return;
                }

                double tolFt = MmToFeet(5.0);
                List<Line> merged = MergeColinearLines(flattened, tolFt);
                wallLines = DeduplicateLines(merged, tolFt);
            }

            double height = topLevel.Elevation - baseLevel.Elevation;
            int created = 0;
            int skipped = 0;

            using (Transaction tx = new Transaction(doc, "Generate Walls from CAD"))
            {
                tx.Start();

                if (Request.CreateWallTypesFromExcel && Request.WallSectionSpecs != null && Request.WallSectionSpecs.Count > 0)
                {
                    EnsureWallTypesFromExcel(doc, wallType, Request.WallSectionSpecs, typeBySpec, typeByName, out typeCreated, out typeSkipped);
                }

                List<CadTextLabel> labels = null;
                if (specByName.Count > 0 || specBySize.Count > 0)
                {
                    labels = CollectCadTextLabels(doc, cad, "");
                }

                IEnumerable<Curve> curvesToUse = loopCurves ?? wallLines.Cast<Curve>();
                foreach (Curve curve in curvesToUse)
                {
                    if (curve == null) { skipped++; continue; }

                    Curve wallCurve = curve;
                    Line asLine = curve as Line;
                    if (asLine != null)
                    {
                        XYZ p0 = asLine.GetEndPoint(0);
                        XYZ p1 = asLine.GetEndPoint(1);
                        p0 = new XYZ(p0.X, p0.Y, 0);
                        p1 = new XYZ(p1.X, p1.Y, 0);
                        if (p0.DistanceTo(p1) < 1e-6)
                        {
                            skipped++;
                            continue;
                        }
                        wallCurve = Line.CreateBound(p0, p1);
                    }

                    WallType typeToUse = wallType;
                    if (typeBySpec.Count > 0)
                    {
                        if (asLine != null)
                        {
                            WallSectionSpec spec = ResolveWallSpecForLine(asLine, labels, specByName, specBySize, layerSpec);
                            if (spec != null && typeBySpec.TryGetValue(spec, out WallType mappedType))
                            {
                                typeToUse = mappedType ?? wallType;
                            }
                        }
                        else if (layerSpec != null && typeBySpec.TryGetValue(layerSpec, out WallType layerType))
                        {
                            typeToUse = layerType ?? wallType;
                        }
                    }

                    Wall wall = Wall.Create(doc, wallCurve, typeToUse.Id, baseLevel.Id, height, 0.0, false, false);

                    Parameter topConstraint = wall.get_Parameter(BuiltInParameter.WALL_HEIGHT_TYPE);
                    if (topConstraint != null && !topConstraint.IsReadOnly)
                    {
                        topConstraint.Set(topLevel.Id);
                    }

                    Parameter topOffset = wall.get_Parameter(BuiltInParameter.WALL_TOP_OFFSET);
                    if (topOffset != null && !topOffset.IsReadOnly)
                    {
                        topOffset.Set(0.0);
                    }

                    ApplyTasAttributesToElement(wall);
                    created++;
                }

                tx.Commit();
            }

            int sourceCount = loopCurves != null ? loopCurves.Count : (wallLines?.Count ?? 0);
            if (typeCreated > 0 || typeSkipped > 0)
            {
                _window?.ShowStatus($"Created walls: {created} (from {sourceCount} segments). Types: {typeCreated} created, {typeSkipped} skipped.");
            }
            else
            {
                _window?.ShowStatus($"Created walls: {created} (from {sourceCount} segments). Skipped: {skipped}.");
            }
        }

        private void GenerateBeams(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            if (!(doc.GetElement(Request.BeamTypeId) is FamilySymbol beamType) || !(doc.GetElement(Request.BaseLevelId) is Level baseLevel) || !(doc.GetElement(Request.TopLevelId) is Level topLevel))
            {
                _window?.ShowStatus("Select beam type, base level, and top level.");
                return;
            }

            if (topLevel.Elevation < baseLevel.Elevation)
            {
                _window?.ShowStatus("Top Level must be above Base Level.");
                return;
            }

            Dictionary<string, BeamSectionSpec> specByName = BuildBeamSpecNameMap(Request.BeamSectionSpecs);
            Dictionary<string, BeamSectionSpec> specBySize = BuildBeamSpecSizeMap(Request.BeamSectionSpecs);
            BeamSectionSpec layerSpec = MatchBeamSpecFromLabel(Request.SelectedLayerName, specByName, specBySize);
            Dictionary<BeamSectionSpec, FamilySymbol> typeBySpec = new Dictionary<BeamSectionSpec, FamilySymbol>();
            Dictionary<string, FamilySymbol> typeByName = new Dictionary<string, FamilySymbol>(StringComparer.OrdinalIgnoreCase);
            Dictionary<string, FamilySymbol> typeByNameAll = BuildBeamTypeNameMap(doc, null);
            Dictionary<string, FamilySymbol> typeBySizeAll = BuildBeamTypeSizeMap(doc, null);
            int typeCreated = 0;
            int typeSkipped = 0;
            string labelLayer = Request.SelectedBeamLabelLayerName ?? "";

            List<CurveLoop> loops = Request.UseLayerFilter
                ? ExtractClosedLoopsFromLayer(doc, cad, Request.SelectedLayerName)
                : ExtractClosedLoopsFromSelectedObjects(doc, cad, Request.SelectedCadReferences);

            CurveLoop outerLoop = SelectOutermostLoop(loops);
            List<Curve> loopCurves = outerLoop?.ToList();

            List<Line> beamLines = null;
            if (loopCurves == null || loopCurves.Count == 0)
            {
                beamLines = Request.UseLayerFilter
                    ? ExtractWallLinesFromLayer(doc, cad, Request.SelectedLayerName)
                    : ExtractWallLinesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);

                if (beamLines == null || beamLines.Count == 0)
                {
                    _window?.ShowStatus("No valid CAD beam lines found.");
                    return;
                }

                List<Line> flattened = beamLines
                    .Select(FlattenLine)
                    .Where(l => l != null)
                    .ToList();

                if (flattened.Count == 0)
                {
                    _window?.ShowStatus("No valid CAD beam lines found.");
                    return;
                }

                double tolFt = MmToFeet(5.0);
                List<Line> merged = MergeColinearLines(flattened, tolFt);
                beamLines = DeduplicateLines(merged, tolFt);
            }

            int created = 0;
            int skipped = 0;

            using (Transaction tx = new Transaction(doc, "Generate Beams from CAD"))
            {
                tx.Start();

                if (!beamType.IsActive) beamType.Activate();

                if (Request.CreateBeamTypesFromExcel && Request.BeamSectionSpecs != null && Request.BeamSectionSpecs.Count > 0)
                {
                    EnsureBeamTypesFromExcel(doc, beamType, Request.BeamSectionSpecs, typeBySpec, typeByName, out typeCreated, out typeSkipped);
                }

                List<CadTextLabel> labels = null;
                bool needLabels = specByName.Count > 0 || specBySize.Count > 0 || typeByNameAll.Count > 0 || typeBySizeAll.Count > 0;
                if (needLabels)
                {
                    if (!string.IsNullOrWhiteSpace(labelLayer))
                    {
                        labels = CollectCadTextLabels(doc, cad, labelLayer);
                    }
                    else if (!Request.UseLayerFilter &&
                             Request.SelectedCadReferences != null &&
                             Request.SelectedCadReferences.Count > 0)
                    {
                        labels = CollectCadTextLabelsFromSelectedObjects(doc, cad, Request.SelectedCadReferences, "");
                        if (labels.Count == 0)
                        {
                            labels = CollectCadTextLabels(doc, cad, "");
                        }
                    }
                    else
                    {
                        labels = CollectCadTextLabels(doc, cad, "");
                    }
                }

                IEnumerable<Curve> curvesToUse = loopCurves ?? beamLines.Cast<Curve>();
                foreach (Curve curve in curvesToUse)
                {
                    if (curve == null) { skipped++; continue; }

                    Line line = curve as Line;
                    if (line == null)
                    {
                        skipped++;
                        continue;
                    }

                    XYZ p0 = line.GetEndPoint(0);
                    XYZ p1 = line.GetEndPoint(1);
                    p0 = new XYZ(p0.X, p0.Y, baseLevel.Elevation);
                    p1 = new XYZ(p1.X, p1.Y, baseLevel.Elevation);

                    if (p0.DistanceTo(p1) < 1e-6)
                    {
                        skipped++;
                        continue;
                    }

                    Line beamLine = Line.CreateBound(p0, p1);
                    FamilySymbol typeToUse = beamType;
                    if (typeBySpec.Count > 0)
                    {
                        BeamSectionSpec spec = ResolveBeamSpecForLine(line, labels, specByName, specBySize, layerSpec);
                        if (spec != null && typeBySpec.TryGetValue(spec, out FamilySymbol mappedType))
                        {
                            typeToUse = mappedType ?? beamType;
                        }
                    }
                    else if (labels != null && labels.Count > 0 && (typeByNameAll.Count > 0 || typeBySizeAll.Count > 0))
                    {
                        FamilySymbol labelType = FindNearestBeamTypeFromLabels(
                            (p0 + p1) * 0.5,
                            labels,
                            typeByNameAll,
                            typeBySizeAll,
                            MmToFeet(1200.0));
                        if (labelType != null)
                        {
                            typeToUse = labelType;
                        }
                    }

                    if (!typeToUse.IsActive) typeToUse.Activate();
                    FamilyInstance beam = doc.Create.NewFamilyInstance(beamLine, typeToUse, baseLevel, StructuralType.Beam);

                    SetBeamEndOffsets(beam, baseLevel, topLevel);
                    ApplyTasAttributesToElement(beam);
                    created++;
                }

                tx.Commit();
            }

            int sourceCount = loopCurves != null ? loopCurves.Count : (beamLines?.Count ?? 0);
            if (typeCreated > 0 || typeSkipped > 0)
            {
                _window?.ShowStatus($"Created beams: {created} (from {sourceCount} segments). Types: {typeCreated} created, {typeSkipped} skipped.");
            }
            else
            {
                _window?.ShowStatus($"Created beams: {created} (from {sourceCount} segments). Skipped: {skipped}.");
            }
        }

        private List<Line> ExtractWallLinesFromSelectedObjects(Document doc, ImportInstance cad, List<Reference> refs)
        {
            var lines = new List<Line>();
            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (Reference r in refs)
            {
                if (r == null) continue;
                GeometryObject go = cad.GetGeometryObjectFromReference(r);
                if (go == null) continue;

                CollectWallLinesFromGeom(doc, go, importTrf, "", lines);
            }

            return lines;
        }

        private List<Line> ExtractWallLinesFromLayer(Document doc, ImportInstance cad, string layerName)
        {
            var lines = new List<Line>();

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return lines;

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (GeometryObject go in ge)
            {
                CollectWallLinesFromGeom(doc, go, importTrf, layerName, lines);
            }

            return lines;
        }

        private void CollectWallLinesFromGeom(
            Document doc,
            GeometryObject go,
            Transform trf,
            string layerFilter,
            List<Line> lines)
        {
            if (go == null) return;
            double tol = doc?.Application?.ShortCurveTolerance ?? 1e-6;
            double minLineLengthFt = Math.Max(tol, GetTasShortLineMinLengthFt(tol * 304.8));

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        CollectWallLinesFromGeom(doc, igo, instTrf, layerFilter, lines);
                    }
                }
                return;
            }

            Curve c = go as Curve;
            if (c != null)
            {
                string layer = GetCadLayer(doc, go);
                if (!string.IsNullOrWhiteSpace(layerFilter) &&
                    !string.Equals(layerFilter, layer, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                Line l = c as Line;
                if (l != null)
                {
                    XYZ p0 = trf.OfPoint(l.GetEndPoint(0));
                    XYZ p1 = trf.OfPoint(l.GetEndPoint(1));
                    if (p0.DistanceTo(p1) >= minLineLengthFt)
                    {
                        lines.Add(Line.CreateBound(p0, p1));
                    }
                }
                return;
            }

            PolyLine pl = go as PolyLine;
            if (pl == null) return;

            string plLayer = GetCadLayer(doc, go);
            if (!string.IsNullOrWhiteSpace(layerFilter) &&
                !string.Equals(layerFilter, plLayer, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            IList<XYZ> pts = pl.GetCoordinates();
            if (pts == null || pts.Count < 2) return;

            for (int i = 0; i < pts.Count - 1; i++)
            {
                XYZ p0 = trf.OfPoint(pts[i]);
                XYZ p1 = trf.OfPoint(pts[i + 1]);
                if (p0.DistanceTo(p1) < minLineLengthFt) continue;
                lines.Add(Line.CreateBound(p0, p1));
            }
        }

        private void GenerateGridlines(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            List<Line> lines;
            if (Request.UseLayerFilter && !string.IsNullOrWhiteSpace(Request.SelectedLayerName))
            {
                lines = ExtractLinesFromLayer(doc, cad, Request.SelectedLayerName);
            }
            else
            {
                if (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0)
                {
                    _window?.ShowStatus("Pick CAD objects or choose a layer to generate gridlines.");
                    return;
                }
                lines = ExtractLinesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
            }

            if (lines.Count == 0)
            {
                _window?.ShowStatus("No valid CAD lines found for gridlines.");
                return;
            }

            List<Line> flattened = lines
                .Select(FlattenLine)
                .Where(l => l != null)
                .ToList();

            if (flattened.Count == 0)
            {
                _window?.ShowStatus("No valid CAD lines found for gridlines.");
                return;
            }

            double tolFt = GetTasRdpToleranceFt(5.0);
            List<Line> merged = MergeColinearLines(flattened, tolFt);
            List<Line> uniqueLines = DeduplicateLines(merged, tolFt);

            double minLenFt = Math.Max(MmToFeet(1000.0), GetTasShortLineMinLengthFt(1000.0));
            List<Line> filtered = uniqueLines.Where(l => l.Length >= minLenFt).ToList();

            if (filtered.Count == 0)
            {
                _window?.ShowStatus("No gridlines created. All CAD lines were too short after cleanup.");
                return;
            }

            string labelLayer = Request.SelectedLabelLayerName;
            if (string.IsNullOrWhiteSpace(labelLayer))
            {
                labelLayer = Request.UseLayerFilter ? Request.SelectedLayerName : "";
            }

            List<CadTextLabel> labels = CollectCadTextLabels(doc, cad, labelLayer);
            if (labels.Count == 0 && !string.IsNullOrWhiteSpace(labelLayer))
            {
                labels = CollectCadTextLabels(doc, cad, "");
            }

            labels = labels
                .Where(l => IsLikelyGridLabel(l.Text))
                .ToList();

            HashSet<string> usedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Grid g in new FilteredElementCollector(doc).OfClass(typeof(Grid)).Cast<Grid>())
            {
                if (!string.IsNullOrWhiteSpace(g.Name))
                {
                    usedNames.Add(g.Name);
                }
            }

            double maxLabelDistFt = MmToFeet(1000.0);
            int created = 0;
            using (Transaction t = new Transaction(doc, "CamboBIM - CAD to Gridlines"))
            {
                t.Start();

                foreach (Line line in filtered)
                {
                    try
                    {
                        Grid grid = Grid.Create(doc, line);
                        string label = TryMatchLabel(line, labels, maxLabelDistFt, usedNames);
                        if (!string.IsNullOrWhiteSpace(label))
                        {
                            try
                            {
                                grid.Name = label;
                                usedNames.Add(label);
                            }
                            catch
                            {
                                // Ignore duplicate or invalid grid names
                            }
                        }
                        created++;
                    }
                    catch
                    {
                        // Skip invalid grid lines
                    }
                }

                t.Commit();
            }

            _window?.ShowStatus($"Created gridlines: {created} (from {filtered.Count} lines).");
        }

        private void GeneratePiles(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            FamilySymbol boredType = doc.GetElement(Request.BoredPileTypeId) as FamilySymbol;
            if (boredType == null)
            {
                _window?.ShowStatus("Select bored pile family type.");
                return;
            }

            if (!(doc.GetElement(Request.BaseLevelId) is Level baseLevel))
            {
                _window?.ShowStatus("Select base level.");
                return;
            }

            if (!(doc.GetElement(Request.TopLevelId) is Level topLevel))
            {
                topLevel = baseLevel;
            }

            if (topLevel.Elevation <= baseLevel.Elevation)
            {
                _window?.ShowStatus("Top Level must be above Base Level.");
                return;
            }

            var boredPts = new List<XYZ>();

            if (Request.UseLayerFilter)
            {
                if (string.IsNullOrWhiteSpace(Request.SelectedBoredLayerName) &&
                    string.IsNullOrWhiteSpace(Request.SelectedLayerName))
                {
                    _window?.ShowStatus("Select a layer for bored pile geometry.");
                    return;
                }

                string layerName = !string.IsNullOrWhiteSpace(Request.SelectedBoredLayerName)
                    ? Request.SelectedBoredLayerName
                    : Request.SelectedLayerName;
                boredPts = ExtractShapesFromLayer(doc, cad, layerName).CircleCenters;
            }
            else
            {
                if (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0)
                {
                    _window?.ShowStatus("Pick CAD objects or choose By Layer.");
                    return;
                }

                CadShapeHits hits = ExtractShapesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
                boredPts = hits.CircleCenters;
            }

            if (boredPts.Count == 0)
            {
                _window?.ShowStatus("No valid bored pile CAD geometry found (circle centers).");
                return;
            }

            double tolFt = MmToFeet(10.0);
            boredPts = DeduplicatePoints(boredPts, tolFt);

            int created = 0;
            using (Transaction t = new Transaction(doc, "CamboBIM - CAD to Piles"))
            {
                t.Start();

                if (boredPts.Count > 0)
                {
                    if (!boredType.IsActive) boredType.Activate();
                    created = PlacePointBasedFoundations(doc, boredType, baseLevel, topLevel, boredPts, Request.BoredPileTopOffsetFt);
                }

                t.Commit();
            }

            _window?.ShowStatus($"Created bored piles: {created} (Input points: {boredPts.Count}).");
        }

        private void GenerateFoundations(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            if (!(doc.GetElement(Request.FoundationLevelId) is Level level))
            {
                _window?.ShowStatus("Select foundation level.");
                return;
            }

            FloorType slabType = doc.GetElement(Request.FoundationSlabTypeId) as FloorType;
            FamilySymbol isolatedType = doc.GetElement(Request.FoundationIsolatedTypeId) as FamilySymbol;

            var slabLoops = new List<CurveLoop>();
            var isolatedPoints = new List<XYZ>();

            if (Request.UseLayerFilter)
            {
                if (slabType != null && !string.IsNullOrWhiteSpace(Request.SelectedFoundationSlabLayerName))
                {
                    slabLoops = ExtractClosedLoopsFromLayer(doc, cad, Request.SelectedFoundationSlabLayerName);
                }
                if (isolatedType != null && !string.IsNullOrWhiteSpace(Request.SelectedFoundationIsolatedLayerName))
                {
                    CadShapeHits hits = ExtractShapesFromLayer(doc, cad, Request.SelectedFoundationIsolatedLayerName);
                    isolatedPoints = hits.CircleCenters.Concat(hits.BlockPoints).ToList();
                }
            }
            else
            {
                if (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0)
                {
                    _window?.ShowStatus("Pick CAD objects or choose By Layer.");
                    return;
                }

                slabLoops = ExtractClosedLoopsFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
                CadShapeHits hits = ExtractShapesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
                isolatedPoints = hits.CircleCenters.Concat(hits.BlockPoints).ToList();
            }

            if (slabLoops.Count == 0 && isolatedPoints.Count == 0)
            {
                _window?.ShowStatus("No valid CAD geometry found for foundations.");
                return;
            }

            double tolFt = MmToFeet(10.0);
            isolatedPoints = DeduplicatePoints(isolatedPoints, tolFt);

            int slabCreated = 0;
            int isolatedCreated = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - CAD to Foundations"))
            {
                t.Start();

                if (slabType != null && slabLoops.Count > 0)
                {
                    List<List<CurveLoop>> groups = GroupLoopsWithHoles(slabLoops);
                    foreach (List<CurveLoop> group in groups)
                    {
                        try
                        {
                            Floor floor = Floor.Create(doc, group, slabType.Id, level.Id);
                            SetFloorOffset(floor, Request.FoundationOffsetFt);
                            ApplyTasAttributesToElement(floor);
                            slabCreated++;
                        }
                        catch
                        {
                            // ignore invalid loops
                        }
                    }
                }

                if (isolatedType != null && isolatedPoints.Count > 0)
                {
                    if (!isolatedType.IsActive) isolatedType.Activate();
                    foreach (XYZ p in isolatedPoints)
                    {
                        try
                        {
                            FamilyInstance fi = doc.Create.NewFamilyInstance(p, isolatedType, level, StructuralType.Footing);
                            SetFoundationOffset(fi, Request.FoundationOffsetFt);
                            ApplyTasAttributesToElement(fi);
                            isolatedCreated++;
                        }
                        catch
                        {
                            // ignore invalid instances
                        }
                    }
                }

                t.Commit();
            }

            _window?.ShowStatus($"Created foundations: {slabCreated + isolatedCreated} (Slab: {slabCreated}, Isolated: {isolatedCreated}).");
        }

        private void GenerateLeanConcrete(Document doc)
        {
            if (!(doc.GetElement(Request.LeanConcreteLevelId) is Level level))
            {
                _window?.ShowStatus("Select Lean Concrete level.");
                return;
            }

            if (!(doc.GetElement(Request.LeanConcreteTypeId) is FloorType leanType))
            {
                _window?.ShowStatus("Select Lean Concrete type.");
                return;
            }

            List<ElementId> selectedSourceIds = (Request.SelectedLeanSourceElementIds ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .Distinct()
                .Where(id => IsLeanConcreteSourceElement(doc.GetElement(id)))
                .ToList();

            if (selectedSourceIds.Count == 0)
            {
                _window?.ShowStatus("Pick modeled structural source elements first (Foundation, Column, Wall, Beam, Floor, Stair).");
                return;
            }

            List<LeanConcreteSourceProfile> sourceProfiles = BuildLeanConcreteSourceProfiles(doc, selectedSourceIds);
            if (sourceProfiles.Count == 0)
            {
                _window?.ShowStatus("No valid bottom boundaries found from selected structural source elements.");
                return;
            }

            double sideOffsetFt = Math.Abs(Request.LeanConcreteSideOffsetFt);
            int created = 0;
            int skipped = 0;
            int totalGroups = sourceProfiles.Sum(profile => profile.LoopGroups?.Count ?? 0);
            var selectedSourceSet = new HashSet<ElementId>(selectedSourceIds);
            List<CurveLoop> boredPileCutLoops = CollectBoredPileCutLoops(doc, selectedSourceSet);

            using (Transaction t = new Transaction(doc, "CamboBIM - CAD to Lean Concrete"))
            {
                t.Start();

                foreach (LeanConcreteSourceProfile profile in sourceProfiles)
                {
                    if (profile?.LoopGroups == null || profile.LoopGroups.Count == 0)
                    {
                        continue;
                    }

                    double floorOffsetFt = profile.BottomElevationFt - level.Elevation;

                    foreach (List<CurveLoop> group in profile.LoopGroups)
                    {
                        List<CurveLoop> targetGroup = sideOffsetFt > 1e-9
                            ? TryOffsetLoopGroup(group, sideOffsetFt)
                            : group;

                        if (targetGroup == null || targetGroup.Count == 0)
                        {
                            skipped++;
                            continue;
                        }

                        try
                        {
                            List<CurveLoop> loopsWithPileCuts = ApplyInnerCutLoops(targetGroup, boredPileCutLoops);
                            Floor floor = Floor.Create(doc, loopsWithPileCuts, leanType.Id, level.Id);
                            SetFloorOffset(floor, floorOffsetFt);
                            created++;
                        }
                        catch
                        {
                            skipped++;
                        }
                    }
                }

                t.Commit();
            }

            double sideOffsetMm = sideOffsetFt * 304.8;
            _window?.ShowStatus(
                $"Created lean concrete: {created} (Skipped: {skipped}, Source elements: {selectedSourceIds.Count}, Groups: {totalGroups}, Pile deduct loops: {boredPileCutLoops.Count}, Side offset: {sideOffsetMm:0.##} mm, Top aligned to source bottoms).");
        }

        private void GenerateSoilExcavation(Document doc)
        {
            List<ElementId> selectedSourceIds = (Request.SelectedSoilExcavationSourceElementIds ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .Distinct()
                .Where(id => IsSoilExcavationSourceElement(doc.GetElement(id)))
                .ToList();

            if (selectedSourceIds.Count == 0)
            {
                _window?.ShowStatus("Pick modeled lean concrete elements first.");
                return;
            }

            double topFoundationOffsetFt = Math.Abs(Request.SoilExcavationTopOffsetFt);
            if (double.IsNaN(topFoundationOffsetFt) || double.IsInfinity(topFoundationOffsetFt))
            {
                _window?.ShowStatus("Soil Excavation top foundation offset is invalid.");
                return;
            }

            double bottomLeanOffsetFt = Math.Abs(Request.SoilExcavationBaseOffsetFt);
            if (double.IsNaN(bottomLeanOffsetFt) || double.IsInfinity(bottomLeanOffsetFt))
            {
                _window?.ShowStatus("Soil Excavation bottom lean offset is invalid.");
                return;
            }

            double angleDeg = Request.SoilExcavationAngleDeg;
            if (angleDeg <= 0 || angleDeg >= 180)
            {
                _window?.ShowStatus("Soil Excavation angle must be between 0 and 180 degrees.");
                return;
            }

            double slopeAngleDeg = angleDeg > 90 ? 180 - angleDeg : angleDeg;
            if (slopeAngleDeg <= 0 || slopeAngleDeg >= 89.999)
            {
                _window?.ShowStatus("Soil Excavation angle cannot be 90 degrees. Use values like 45 or 135.");
                return;
            }

            double angleRad = slopeAngleDeg * Math.PI / 180.0;
            double tanAngle = Math.Tan(angleRad);
            if (tanAngle <= 1e-9)
            {
                _window?.ShowStatus("Soil Excavation angle produced invalid slope.");
                return;
            }

            List<SoilExcavationSourceProfile> sourceProfiles = BuildSoilExcavationSourceProfiles(doc, selectedSourceIds);
            if (sourceProfiles.Count == 0)
            {
                _window?.ShowStatus("No valid lean concrete bottom boundary loops found from selected elements.");
                return;
            }

            var selectedSourceSet = new HashSet<ElementId>(selectedSourceIds);
            List<SoilExcavationFoundationTopCandidate> foundationTopCandidates =
                BuildSoilExcavationFoundationTopCandidates(doc, selectedSourceSet);
            if (foundationTopCandidates.Count == 0)
            {
                _window?.ShowStatus("No modeled foundation tops were found. Generate or keep foundations before creating soil excavation.");
                return;
            }

            int created = 0;
            int skipped = 0;
            int skippedNoFoundationTop = 0;
            int skippedBottomOffset = 0;
            int skippedSlope = 0;
            int skippedTopOffset = 0;
            int skippedInvalidSolid = 0;
            int adjustedBottomOffsetGroups = 0;
            int adjustedSlopeGroups = 0;
            int adjustedTopOffsetGroups = 0;
            int totalGroups = sourceProfiles.Sum(profile => profile.LoopGroups?.Count ?? 0);
            double grossVolumeFt3 = 0.0;
            double minDepthFt = double.PositiveInfinity;
            double maxDepthFt = 0.0;
            var generatedSolids = new List<Solid>();

            using (Transaction t = new Transaction(doc, "CamboBIM - Soil Excavation"))
            {
                t.Start();

                foreach (SoilExcavationSourceProfile profile in sourceProfiles)
                {
                    if (profile?.LoopGroups == null || profile.LoopGroups.Count == 0)
                    {
                        continue;
                    }

                    double leanBottomElevationFt = profile.BottomElevationFt;

                    foreach (List<CurveLoop> group in profile.LoopGroups)
                    {
                        CurveLoop outerLoop = SelectOutermostLoop(group) ?? group.FirstOrDefault();
                        if (outerLoop == null)
                        {
                            skipped++;
                            continue;
                        }

                        SoilExcavationFoundationTopCandidate foundationTopCandidate = ResolveSoilExcavationTopCandidate(
                            outerLoop,
                            leanBottomElevationFt,
                            foundationTopCandidates);

                        if (foundationTopCandidate == null || foundationTopCandidate.LoopGroup == null || foundationTopCandidate.LoopGroup.Count == 0)
                        {
                            skipped++;
                            skippedNoFoundationTop++;
                            continue;
                        }

                        double topElevationFt = foundationTopCandidate.TopElevationFt;
                        double bottomElevationFt = leanBottomElevationFt;
                        if (topElevationFt <= bottomElevationFt + 1e-9)
                        {
                            skipped++;
                            continue;
                        }

                        double appliedBottomOffsetFt;
                        List<CurveLoop> bottomGroup = TryOffsetLoopGroupForSoilBottom(
                            group,
                            bottomLeanOffsetFt,
                            out appliedBottomOffsetFt);
                        if (bottomGroup == null || bottomGroup.Count == 0)
                        {
                            skipped++;
                            skippedBottomOffset++;
                            continue;
                        }
                        if (appliedBottomOffsetFt + 1e-6 < bottomLeanOffsetFt)
                        {
                            adjustedBottomOffsetGroups++;
                        }

                        double depthFt = topElevationFt - bottomElevationFt;
                        double horizontalRunFt = depthFt / tanAngle;
                        if (horizontalRunFt <= 1e-9)
                        {
                            skipped++;
                            continue;
                        }

                        double appliedTopRunFt;
                        List<CurveLoop> topGroup = TryOffsetLoopGroupForSoilTop(
                            bottomGroup,
                            horizontalRunFt,
                            out appliedTopRunFt);
                        if (topGroup == null || topGroup.Count == 0)
                        {
                            skipped++;
                            skippedSlope++;
                            continue;
                        }
                        if (appliedTopRunFt + 1e-6 < horizontalRunFt)
                        {
                            adjustedSlopeGroups++;
                        }

                        double appliedTopOffsetFt;
                        topGroup = TryOffsetLoopGroupForSoilTop(
                            topGroup,
                            topFoundationOffsetFt,
                            out appliedTopOffsetFt);
                        if (topGroup == null || topGroup.Count == 0)
                        {
                            skipped++;
                            skippedTopOffset++;
                            continue;
                        }
                        if (appliedTopOffsetFt + 1e-6 < topFoundationOffsetFt)
                        {
                            adjustedTopOffsetGroups++;
                        }

                        Solid excavationSolid = CreateSoilExcavationSolidFromGroups(
                            topGroup,
                            bottomGroup,
                            topElevationFt,
                            bottomElevationFt);

                        if (excavationSolid == null || excavationSolid.Volume <= 1e-9)
                        {
                            skipped++;
                            skippedInvalidSolid++;
                            continue;
                        }

                        try
                        {
                            DirectShape shape = DirectShape.CreateElement(
                                doc,
                                new ElementId(BuiltInCategory.OST_GenericModel));
                            shape.ApplicationId = "CamboBIM";
                            shape.ApplicationDataId = "SoilExcavation_" + Guid.NewGuid().ToString("N");
                            shape.SetShape(new List<GeometryObject> { excavationSolid });
                            grossVolumeFt3 += excavationSolid.Volume;
                            generatedSolids.Add(excavationSolid);
                            created++;

                            if (depthFt > 1e-9)
                            {
                                minDepthFt = Math.Min(minDepthFt, depthFt);
                                maxDepthFt = Math.Max(maxDepthFt, depthFt);
                            }
                        }
                        catch
                        {
                            skipped++;
                        }
                    }
                }

                t.Commit();
            }

            int overlapMergedPairs;
            int overlapBooleanFailures;
            double netVolumeFt3 = ComputeNonOverlappingVolumeFt3(
                generatedSolids,
                out overlapMergedPairs,
                out overlapBooleanFailures);
            double deductedOverlapFt3 = Math.Max(0.0, grossVolumeFt3 - netVolumeFt3);
            double netVolumeM3 = netVolumeFt3 * 0.028316846592;
            double grossVolumeM3 = grossVolumeFt3 * 0.028316846592;
            double deductedOverlapM3 = deductedOverlapFt3 * 0.028316846592;

            _window?.UpdateSoilExcavationVolume(netVolumeM3);

            double topFoundationOffsetMm = topFoundationOffsetFt * 304.8;
            double bottomLeanOffsetMm = bottomLeanOffsetFt * 304.8;
            if (double.IsPositiveInfinity(minDepthFt))
            {
                minDepthFt = 0.0;
            }

            double minDepthMm = minDepthFt * 304.8;
            double maxDepthMm = maxDepthFt * 304.8;
            _window?.ShowStatus(
                $"Created soil excavation: {created} (Skipped: {skipped}, No foundation-top match: {skippedNoFoundationTop}, Bottom offset fail: {skippedBottomOffset}, Slope fail: {skippedSlope}, Top offset fail: {skippedTopOffset}, Solid fail: {skippedInvalidSolid}, Lean sources: {selectedSourceIds.Count}, Groups: {totalGroups}, Top offset: {topFoundationOffsetMm:0.##} mm, Bottom offset: {bottomLeanOffsetMm:0.##} mm, Angle input/effective: {angleDeg:0.##}/{slopeAngleDeg:0.##} deg, Adjusted bottom offset groups: {adjustedBottomOffsetGroups}, Adjusted slope groups: {adjustedSlopeGroups}, Adjusted top offset groups: {adjustedTopOffsetGroups}, Depth range: {minDepthMm:0.##}-{maxDepthMm:0.##} mm, Overlap merged: {overlapMergedPairs}, Overlap bool-fail: {overlapBooleanFailures}, Volume gross/net/deduct: {grossVolumeM3:0.###}/{netVolumeM3:0.###}/{deductedOverlapM3:0.###} m3).");
        }

        private void GenerateSlabs(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            if (!(doc.GetElement(Request.SlabLevelId) is Level level))
            {
                _window?.ShowStatus("Select slab level.");
                return;
            }

            if (!(doc.GetElement(Request.SlabTypeId) is FloorType slabType))
            {
                _window?.ShowStatus("Select slab type.");
                return;
            }

            Dictionary<string, SlabSectionSpec> slabSpecByName = BuildSlabSpecNameMap(Request.SlabSectionSpecs);
            Dictionary<string, SlabSectionSpec> slabSpecByThickness = BuildSlabSpecThicknessMap(Request.SlabSectionSpecs);
            bool useSlabSpecs = Request.UseSlabSectionSpecs && (slabSpecByName.Count > 0 || slabSpecByThickness.Count > 0);
            SlabSectionSpec layerSpec = null;
            List<CadTextLabel> labels = null;
            Dictionary<string, FloorType> slabTypeByName = null;
            Dictionary<string, List<FloorType>> slabTypeByThickness = null;

            if (useSlabSpecs)
            {
                labels = CollectCadTextLabels(doc, cad, "");
                layerSpec = MatchSlabSpecFromLabel(Request.SelectedSlabLayerName, slabSpecByName, slabSpecByThickness);

                List<FloorType> slabTypes = new FilteredElementCollector(doc)
                    .OfClass(typeof(FloorType))
                    .Cast<FloorType>()
                    .Where(ft => ft.Category != null &&
                                 (ft.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFoundation ||
                                  ft.Category.Id.Value == (int)BuiltInCategory.OST_Floors))
                    .ToList();

                slabTypeByName = BuildFloorTypeNameMap(slabTypes);
                slabTypeByThickness = BuildFloorTypeThicknessMap(slabTypes);
            }

            List<CurveLoop> slabLoops;
            if (Request.UseLayerFilter)
            {
                if (string.IsNullOrWhiteSpace(Request.SelectedSlabLayerName))
                {
                    _window?.ShowStatus("Select slab layer.");
                    return;
                }
                slabLoops = ExtractClosedLoopsFromLayer(doc, cad, Request.SelectedSlabLayerName);
            }
            else
            {
                if (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0)
                {
                    _window?.ShowStatus("Pick CAD objects or choose By Layer.");
                    return;
                }
                slabLoops = ExtractClosedLoopsFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
            }

            if (slabLoops.Count == 0)
            {
                _window?.ShowStatus("No valid CAD loops found for slabs.");
                return;
            }

            int slabCreated = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - CAD to Slabs"))
            {
                t.Start();

                List<List<CurveLoop>> groups = GroupLoopsWithHoles(slabLoops);
                foreach (List<CurveLoop> group in groups)
                {
                    try
                    {
                        FloorType targetType = slabType;
                        if (useSlabSpecs && labels != null)
                        {
                            CurveLoop outer = SelectOutermostLoop(group) ?? group.FirstOrDefault();
                            SlabSectionSpec spec = ResolveSlabSpecForLoop(outer, labels, slabSpecByName, slabSpecByThickness, layerSpec);
                            if (spec != null)
                            {
                                targetType = ResolveSlabTypeForSpec(spec, slabType, slabTypeByName, slabTypeByThickness) ?? slabType;
                            }
                        }

                        Floor floor = Floor.Create(doc, group, targetType.Id, level.Id);
                        ApplyTasAttributesToElement(floor);
                        slabCreated++;
                    }
                    catch
                    {
                        // ignore invalid loops
                    }
                }

                t.Commit();
            }

            _window?.ShowStatus($"Created slabs: {slabCreated} (from {slabLoops.Count} loops).");
        }

        private void ApplyTasAttributesToSelection(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc == null)
            {
                return;
            }

            List<CadToModelTasAttributePayload> attributes = GetActiveTasAttributes();
            if (attributes.Count == 0)
            {
                _window?.ShowStatus("Attribute Editor: tick Add for at least one attribute before applying.");
                return;
            }

            List<ElementId> targetIds = (uidoc.Selection?.GetElementIds() ?? new List<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .Where(id => IsTasAttributeTargetElement(doc.GetElement(id)))
                .Distinct(new ElementIdValueComparer())
                .ToList();

            if (targetIds.Count == 0)
            {
                IList<Reference> picked = uidoc.Selection.PickObjects(
                    ObjectType.Element,
                    new TasAttributeTargetSelectionFilter(),
                    "Select Revit model elements to receive checked TAS attributes.");

                targetIds = (picked ?? new List<Reference>())
                    .Select(reference => reference?.ElementId ?? ElementId.InvalidElementId)
                    .Where(id => id != ElementId.InvalidElementId && IsTasAttributeTargetElement(doc.GetElement(id)))
                    .Distinct(new ElementIdValueComparer())
                    .ToList();
            }

            if (targetIds.Count == 0)
            {
                _window?.ShowStatus("Attribute Editor: no Revit model elements selected.");
                return;
            }

            int appliedCount = 0;
            using (var transaction = new Transaction(doc, "Apply TAS Attributes"))
            {
                transaction.Start();
                foreach (ElementId id in targetIds)
                {
                    Element element = doc.GetElement(id);
                    if (ApplyTasAttributesToElement(element))
                    {
                        appliedCount++;
                    }
                }

                transaction.Commit();
            }

            uidoc.Selection.SetElementIds(targetIds);
            _window?.ShowStatus($"Attribute Editor: applied {attributes.Count} checked attribute(s) to {appliedCount} of {targetIds.Count} selected element(s).");
        }

        private List<CadToModelTasAttributePayload> GetActiveTasAttributes()
        {
            return (Request.TasAttributes ?? new List<CadToModelTasAttributePayload>())
                .Where(a => a != null &&
                            a.Add &&
                            !string.IsNullOrWhiteSpace(a.Attribute) &&
                            !string.IsNullOrWhiteSpace(a.Value))
                .GroupBy(a => NormalizeTasAttributeName(a.Attribute), StringComparer.OrdinalIgnoreCase)
                .Select(group => group.Last())
                .ToList();
        }

        private static bool IsTasAttributeTargetElement(Element element)
        {
            if (element == null ||
                element.ViewSpecific ||
                element is ImportInstance ||
                element.Category == null)
            {
                return false;
            }

            return element.Category.CategoryType == CategoryType.Model;
        }

        private sealed class TasAttributeTargetSelectionFilter : ISelectionFilter
        {
            public bool AllowElement(Element elem)
            {
                return IsTasAttributeTargetElement(elem);
            }

            public bool AllowReference(Reference reference, XYZ position)
            {
                return true;
            }
        }

        private sealed class ElementIdValueComparer : IEqualityComparer<ElementId>
        {
            public bool Equals(ElementId x, ElementId y)
            {
                long left = x == null ? long.MinValue : x.Value;
                long right = y == null ? long.MinValue : y.Value;
                return left == right;
            }

            public int GetHashCode(ElementId obj)
            {
                return (obj == null ? long.MinValue : obj.Value).GetHashCode();
            }
        }

        private bool ApplyTasAttributesToElement(Element element)
        {
            if (element == null || Request.TasAttributes == null || Request.TasAttributes.Count == 0)
            {
                return false;
            }

            List<CadToModelTasAttributePayload> attributes = GetActiveTasAttributes();

            if (attributes.Count == 0)
            {
                return false;
            }

            var unapplied = new List<string>();
            bool wrote = false;
            foreach (CadToModelTasAttributePayload attribute in attributes)
            {
                if (!TrySetTasAttributeParameter(element, attribute.Attribute, attribute.Value))
                {
                    unapplied.Add(attribute.Attribute.Trim() + "=" + attribute.Value.Trim());
                    continue;
                }

                wrote = true;
            }

            if (unapplied.Count > 0)
            {
                wrote = TryAppendTasAttributeComment(element, "TAS: " + string.Join("; ", unapplied.Take(16))) || wrote;
            }

            return wrote;
        }

        private static bool TrySetTasAttributeParameter(Element element, string attributeName, string value)
        {
            foreach (string candidate in BuildTasAttributeParameterNames(attributeName))
            {
                Parameter parameter = element.LookupParameter(candidate);
                if (TrySetTasAttributeParameterValue(parameter, attributeName, value))
                {
                    return true;
                }
            }

            return false;
        }

        private static IEnumerable<string> BuildTasAttributeParameterNames(string attributeName)
        {
            string clean = Regex.Replace(attributeName ?? "", @"\s*\([^\)]*\)", "").Trim();
            string compact = Regex.Replace(clean, @"[^A-Za-z0-9]+", "");
            string underscore = Regex.Replace(clean, @"[^A-Za-z0-9]+", "_").Trim('_');

            yield return attributeName ?? "";
            yield return clean;
            yield return "TAS " + clean;
            yield return "TAS_" + underscore;
            yield return "CBIM_TAS_" + underscore;
            yield return "CBIM_TAS_" + compact;
        }

        private static bool TrySetTasAttributeParameterValue(Parameter parameter, string attributeName, string value)
        {
            if (parameter == null || parameter.IsReadOnly)
            {
                return false;
            }

            try
            {
                switch (parameter.StorageType)
                {
                    case StorageType.String:
                        parameter.Set(value ?? "");
                        return true;

                    case StorageType.Integer:
                        if (int.TryParse((value ?? "").Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int intValue))
                        {
                            parameter.Set(intValue);
                            return true;
                        }

                        return false;

                    case StorageType.Double:
                        foreach (string candidate in BuildTasAttributeValueStringCandidates(attributeName, value))
                        {
                            try
                            {
                                if (parameter.SetValueString(candidate))
                                {
                                    return true;
                                }
                            }
                            catch
                            {
                                // Try the next value format.
                            }
                        }

                        if (TryParseTasDoubleValue(value, out double doubleValue))
                        {
                            parameter.Set(doubleValue);
                            return true;
                        }

                        return false;

                    default:
                        return false;
                }
            }
            catch
            {
                return false;
            }
        }

        private static IEnumerable<string> BuildTasAttributeValueStringCandidates(string attributeName, string value)
        {
            string text = (value ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                yield break;
            }

            yield return text;

            string attribute = attributeName ?? "";
            if (attribute.IndexOf("(mm)", StringComparison.OrdinalIgnoreCase) >= 0 &&
                !Regex.IsMatch(text, @"\bmm\b", RegexOptions.IgnoreCase))
            {
                yield return text + " mm";
            }

            if (attribute.IndexOf("(m)", StringComparison.OrdinalIgnoreCase) >= 0 &&
                !Regex.IsMatch(text, @"\bm\b", RegexOptions.IgnoreCase))
            {
                yield return text + " m";
            }
        }

        private static bool TryParseTasDoubleValue(string value, out double result)
        {
            result = 0.0;
            string text = Regex.Replace((value ?? "").Trim(), @"[^\d\.\,\-]+", "");
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            return double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out result) ||
                   double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out result);
        }

        private static string NormalizeTasAttributeName(string attributeName)
        {
            string clean = Regex.Replace(attributeName ?? "", @"\s*\([^\)]*\)", "").Trim();
            return Regex.Replace(clean, @"\s+", " ");
        }

        private static bool TryAppendTasAttributeComment(Element element, string summary)
        {
            if (element == null || string.IsNullOrWhiteSpace(summary))
            {
                return false;
            }

            Parameter comments = element.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
            if (comments == null || comments.IsReadOnly || comments.StorageType != StorageType.String)
            {
                return false;
            }

            try
            {
                string existing = comments.AsString() ?? "";
                string append = summary.Length > 900 ? summary.Substring(0, 900) : summary;
                if (existing.IndexOf(append, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }

                string next = string.IsNullOrWhiteSpace(existing)
                    ? append
                    : existing.TrimEnd() + " | " + append;

                comments.Set(next.Length > 1024 ? next.Substring(0, 1024) : next);
                return true;
            }
            catch
            {
                // Attribute comments are best-effort and should not block model generation.
                return false;
            }
        }

        private void GenerateShopDrawings(
            UIDocument uidoc,
            Document doc,
            bool includeFormwork,
            bool includeRebar,
            bool createSheets)
        {
            if (doc == null)
            {
                return;
            }

            if (!includeFormwork && !includeRebar)
            {
                _window?.ShowStatus("Shop Drawing: enable Formwork Layout or Rebar Drawing.");
                return;
            }

            int viewScale = Math.Max(1, Request.ShopDrawingsViewScale);
            int maxMarksPerSheet = Math.Max(1, Math.Min(200, Request.ShopDrawingsMaxMarksPerSheet));
            QsScope scope = Request.ShopDrawingsScope;
            ShopDrawingGroupMode groupMode = Request.ShopDrawingsGroupMode;
            string issueText = NormalizeShopDrawingIssueText(Request.ShopDrawingsIssueText);
            string formworkSheetPrefix = NormalizeShopDrawingSheetPrefix(Request.ShopDrawingsFormworkSheetPrefix, "MHNK-FWK");
            string rebarSheetPrefix = NormalizeShopDrawingSheetPrefix(Request.ShopDrawingsRebarSheetPrefix, "MHNK-RBR");
            string indexSheetPrefix = NormalizeShopDrawingSheetPrefix(Request.ShopDrawingsIndexSheetPrefix, "MHNK-SD-INDEX");
            ShopDrawingIssueMetadata metadata = BuildShopDrawingIssueMetadata(Request, issueText);
            List<Element> formwork = includeFormwork
                ? CollectShopDrawingFormworkElements(uidoc, doc, scope)
                : new List<Element>();
            List<Element> rebar = includeRebar
                ? CollectShopDrawingRebarElements(uidoc, doc, scope)
                : new List<Element>();

            if (formwork.Count == 0 && rebar.Count == 0)
            {
                _window?.ShowStatus("Shop Drawing: no QS formwork shapes or rebar found in the selected scope.");
                return;
            }

            int deletedExisting = 0;
            if (Request.ShopDrawingsReplaceExisting)
            {
                TryMoveActiveViewAwayFromGeneratedShopDrawing(uidoc, doc);
                using (Transaction cleanup = new Transaction(doc, "CamboBIM - Clear Existing Shop Drawings"))
                {
                    cleanup.Start();
                    deletedExisting = DeleteExistingGeneratedShopDrawings(
                        doc,
                        new[] { formworkSheetPrefix, rebarSheetPrefix, indexSheetPrefix, NormalizeShopDrawingSheetPrefix(Request.ShopDrawingsDetailSheetPrefix, "MHNK-DET") });
                    cleanup.Commit();
                }
            }

            ViewFamilyType draftingType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(x => x.ViewFamily == ViewFamily.Drafting);

            if (draftingType == null)
            {
                _window?.ShowStatus("Shop Drawing: no drafting view type is available in this model.");
                return;
            }

            ViewFamilyType modelViewType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(x => x.ViewFamily == ViewFamily.ThreeDimensional);

            TextNoteType textType = new FilteredElementCollector(doc)
                .OfClass(typeof(TextNoteType))
                .Cast<TextNoteType>()
                .FirstOrDefault();

            var viewNames = new HashSet<string>(
                new FilteredElementCollector(doc)
                    .OfClass(typeof(View))
                    .Cast<View>()
                    .Select(v => v.Name),
                StringComparer.OrdinalIgnoreCase);

            var sheetNumbers = new HashSet<string>(
                new FilteredElementCollector(doc)
                    .OfClass(typeof(ViewSheet))
                    .Cast<ViewSheet>()
                    .Select(s => s.SheetNumber ?? ""),
                StringComparer.OrdinalIgnoreCase);

            ElementId titleBlockTypeId = GetShopDrawingTitleBlockTypeId(doc);
            var createdViews = new List<View>();
            var createdSheets = new List<ViewSheet>();
            int skippedGroups = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - Generate Shop Drawings"))
            {
                t.Start();

                if (formwork.Count > 0)
                {
                    CreateShopDrawingViewsForGroups(
                        doc,
                        draftingType,
                        modelViewType,
                        textType,
                        viewNames,
                        sheetNumbers,
                        titleBlockTypeId,
                        formwork,
                        "FORMWORK LAYOUT",
                        "MHNK_FWK_LAYOUT",
                        formworkSheetPrefix,
                        viewScale,
                        maxMarksPerSheet,
                        groupMode,
                        issueText,
                        metadata,
                        createSheets,
                        true,
                        createdViews,
                        createdSheets,
                        ref skippedGroups);
                }

                if (rebar.Count > 0)
                {
                    CreateShopDrawingViewsForGroups(
                        doc,
                        draftingType,
                        modelViewType,
                        textType,
                        viewNames,
                        sheetNumbers,
                        titleBlockTypeId,
                        rebar,
                        "REBAR DRAWING",
                        "MHNK_RBR_DRAWING",
                        rebarSheetPrefix,
                        viewScale,
                        maxMarksPerSheet,
                        groupMode,
                        issueText,
                        metadata,
                        createSheets,
                        false,
                        createdViews,
                        createdSheets,
                        ref skippedGroups);
                }

                if (createSheets && createdSheets.Count > 0)
                {
                    ViewSheet indexSheet = CreateShopDrawingIndexSheet(
                        doc,
                        draftingType,
                        textType,
                        viewNames,
                        sheetNumbers,
                        titleBlockTypeId,
                        createdSheets.ToList(),
                        createdViews,
                        formwork,
                        rebar,
                        issueText,
                        indexSheetPrefix,
                        metadata);
                    if (indexSheet != null)
                    {
                        createdSheets.Add(indexSheet);
                    }
                }

                t.Commit();
            }

            try
            {
                View targetView = createdSheets.Cast<View>().FirstOrDefault() ?? createdViews.FirstOrDefault();
                if (uidoc != null && targetView != null)
                {
                    uidoc.ActiveView = targetView;
                }
            }
            catch
            {
            }

            string sheetText = createSheets
                ? $", sheets {createdSheets.Count}"
                : "";
            _window?.ShowStatus(
                $"Shop Drawing: created views {createdViews.Count}{sheetText}. " +
                $"Formwork {formwork.Count}, rebar {rebar.Count}, skipped groups {skippedGroups}, cleared {deletedExisting}.");
        }

        private void GenerateSelectedElementShopViews(UIDocument uidoc, Document doc, bool createSheets)
        {
            if (doc == null)
            {
                return;
            }

            List<Element> selectedElements = CollectSelectedShopDrawingElements(uidoc, doc)
                .Take(30)
                .ToList();
            if (selectedElements.Count == 0)
            {
                _window?.ShowStatus("Shop Drawing: select one or more model elements first.");
                return;
            }

            ViewFamilyType draftingType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(x => x.ViewFamily == ViewFamily.Drafting);
            ViewFamilyType planType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(x => x.ViewFamily == ViewFamily.FloorPlan);
            ViewFamilyType sectionType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(x => x.ViewFamily == ViewFamily.Section);
            ViewFamilyType modelViewType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(x => x.ViewFamily == ViewFamily.ThreeDimensional);
            TextNoteType textType = new FilteredElementCollector(doc)
                .OfClass(typeof(TextNoteType))
                .Cast<TextNoteType>()
                .FirstOrDefault();

            if (draftingType == null && planType == null && sectionType == null && modelViewType == null)
            {
                _window?.ShowStatus("Shop Drawing: no usable plan, section, drafting, or 3D view type is available.");
                return;
            }

            int viewScale = Math.Max(1, Request.ShopDrawingsViewScale);
            string issueText = NormalizeShopDrawingIssueText(Request.ShopDrawingsIssueText);
            string detailSheetPrefix = NormalizeShopDrawingSheetPrefix(Request.ShopDrawingsDetailSheetPrefix, "MHNK-DET");
            ShopDrawingIssueMetadata metadata = BuildShopDrawingIssueMetadata(Request, issueText);
            ElementId titleBlockTypeId = GetShopDrawingTitleBlockTypeId(doc);
            int deletedExisting = 0;
            if (Request.ShopDrawingsReplaceExisting)
            {
                TryMoveActiveViewAwayFromGeneratedShopDrawing(uidoc, doc);
                using (Transaction cleanup = new Transaction(doc, "CamboBIM - Clear Existing Selected Element Views"))
                {
                    cleanup.Start();
                    deletedExisting = DeleteExistingGeneratedShopDrawings(
                        doc,
                        new[] { detailSheetPrefix });
                    cleanup.Commit();
                }
            }

            var viewNames = new HashSet<string>(
                new FilteredElementCollector(doc)
                    .OfClass(typeof(View))
                    .Cast<View>()
                    .Select(v => v.Name),
                StringComparer.OrdinalIgnoreCase);
            var sheetNumbers = new HashSet<string>(
                new FilteredElementCollector(doc)
                    .OfClass(typeof(ViewSheet))
                    .Cast<ViewSheet>()
                    .Select(s => s.SheetNumber ?? ""),
                StringComparer.OrdinalIgnoreCase);

            var createdViews = new List<View>();
            var createdSheets = new List<ViewSheet>();
            int skipped = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - Selected Element Shop Views"))
            {
                t.Start();

                foreach (Element element in selectedElements)
                {
                    if (!TryGetShopDrawingModelBounds3D(new[] { element }, out XYZ min, out XYZ max))
                    {
                        skipped++;
                        continue;
                    }

                    string label = BuildSelectedElementShopDrawingLabel(doc, element);
                    string safeName = BuildSelectedElementShopDrawingSafeName(element);
                    var elementViews = new List<View>();

                    ViewPlan planView = CreateSelectedElementPlanView(
                        doc,
                        planType,
                        viewNames,
                        element,
                        min,
                        max,
                        safeName,
                        viewScale);
                    if (planView != null)
                    {
                        elementViews.Add(planView);
                    }

                    ViewSection sectionView = CreateSelectedElementVerticalView(
                        doc,
                        sectionType,
                        viewNames,
                        element,
                        min,
                        max,
                        safeName,
                        "SECTION",
                        viewScale,
                        lookAlongX: false);
                    if (sectionView != null)
                    {
                        elementViews.Add(sectionView);
                    }

                    ViewSection elevationView = CreateSelectedElementVerticalView(
                        doc,
                        sectionType,
                        viewNames,
                        element,
                        min,
                        max,
                        safeName,
                        "ELEVATION",
                        viewScale,
                        lookAlongX: true);
                    if (elevationView != null)
                    {
                        elementViews.Add(elevationView);
                    }

                    View3D modelView = CreateSelectedElement3DView(
                        doc,
                        modelViewType,
                        viewNames,
                        element,
                        min,
                        max,
                        safeName,
                        viewScale);
                    if (modelView != null)
                    {
                        elementViews.Add(modelView);
                    }

                    ViewDrafting dimensionView = CreateSelectedElementDimensionView(
                        doc,
                        draftingType,
                        textType,
                        viewNames,
                        element,
                        min,
                        max,
                        label,
                        safeName,
                        viewScale,
                        metadata);
                    if (dimensionView != null)
                    {
                        elementViews.Add(dimensionView);
                    }

                    if (elementViews.Count == 0)
                    {
                        skipped++;
                        continue;
                    }

                    createdViews.AddRange(elementViews);
                    if (createSheets)
                    {
                        ViewSheet sheet = CreateSelectedElementDetailSheetForViews(
                            doc,
                            titleBlockTypeId,
                            sheetNumbers,
                            detailSheetPrefix,
                            label,
                            metadata,
                            elementViews);
                        if (sheet != null)
                        {
                            createdSheets.Add(sheet);
                        }
                    }
                }

                t.Commit();
            }

            try
            {
                View targetView = createdSheets.Cast<View>().FirstOrDefault() ?? createdViews.FirstOrDefault();
                if (uidoc != null && targetView != null)
                {
                    uidoc.ActiveView = targetView;
                }
            }
            catch
            {
            }

            string sheetText = createSheets ? $", sheets {createdSheets.Count}" : "";
            _window?.ShowStatus(
                $"Shop Drawing: selected element views created {createdViews.Count}{sheetText}. " +
                $"Selected {selectedElements.Count}, skipped {skipped}, cleared {deletedExisting}.");
        }

        private static List<Element> CollectSelectedShopDrawingElements(UIDocument uidoc, Document doc)
        {
            var result = new List<Element>();
            if (uidoc == null || doc == null)
            {
                return result;
            }

            try
            {
                foreach (ElementId id in uidoc.Selection?.GetElementIds() ?? new List<ElementId>())
                {
                    if (id == null || id == ElementId.InvalidElementId)
                    {
                        continue;
                    }

                    Element element = doc.GetElement(id);
                    if (element == null || element is ElementType || element is View)
                    {
                        continue;
                    }

                    result.Add(element);
                }
            }
            catch
            {
            }

            return result;
        }

        private static void TryMoveActiveViewAwayFromGeneratedShopDrawing(UIDocument uidoc, Document doc)
        {
            if (uidoc == null || doc?.ActiveView == null || !IsGeneratedShopDrawingViewName(doc.ActiveView.Name))
            {
                return;
            }

            try
            {
                View fallback = new FilteredElementCollector(doc)
                    .OfClass(typeof(View))
                    .Cast<View>()
                    .Where(v => v != null && !v.IsTemplate && v.Id != doc.ActiveView.Id)
                    .Where(v => !(v is ViewSheet))
                    .FirstOrDefault(v => !IsGeneratedShopDrawingViewName(v.Name));
                if (fallback != null)
                {
                    uidoc.ActiveView = fallback;
                }
            }
            catch
            {
            }
        }

        private static int DeleteExistingGeneratedShopDrawings(Document doc, IEnumerable<string> sheetPrefixes)
        {
            if (doc == null)
            {
                return 0;
            }

            var prefixes = new HashSet<string>(
                (sheetPrefixes ?? Enumerable.Empty<string>())
                    .Where(p => !string.IsNullOrWhiteSpace(p))
                    .Select(p => p.Trim()),
                StringComparer.OrdinalIgnoreCase);
            prefixes.Add("MHNK-FWK");
            prefixes.Add("MHNK-RBR");
            prefixes.Add("MHNK-SD-INDEX");
            prefixes.Add("MHNK-DET");

            int deleted = 0;
            List<ElementId> sheetIds = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewSheet))
                .Cast<ViewSheet>()
                .Where(s => s != null && IsGeneratedShopDrawingSheet(s, prefixes))
                .Where(s => doc.ActiveView == null || s.Id != doc.ActiveView.Id)
                .Select(s => s.Id)
                .ToList();

            deleted += DeleteShopDrawingElementsBestEffort(doc, sheetIds);

            List<ElementId> viewIds = new FilteredElementCollector(doc)
                .OfClass(typeof(View))
                .Cast<View>()
                .Where(v => v != null && !v.IsTemplate && !(v is ViewSheet))
                .Where(v => doc.ActiveView == null || v.Id != doc.ActiveView.Id)
                .Where(v => IsGeneratedShopDrawingViewName(v.Name))
                .Select(v => v.Id)
                .ToList();

            deleted += DeleteShopDrawingElementsBestEffort(doc, viewIds);
            return deleted;
        }

        private static int DeleteShopDrawingElementsBestEffort(Document doc, IList<ElementId> ids)
        {
            if (doc == null || ids == null || ids.Count == 0)
            {
                return 0;
            }

            try
            {
                ICollection<ElementId> deleted = doc.Delete(ids);
                return deleted?.Count ?? ids.Count;
            }
            catch
            {
                int count = 0;
                foreach (ElementId id in ids.Where(id => id != null && id != ElementId.InvalidElementId))
                {
                    try
                    {
                        ICollection<ElementId> deleted = doc.Delete(id);
                        count += deleted?.Count ?? 1;
                    }
                    catch
                    {
                    }
                }

                return count;
            }
        }

        private static bool IsGeneratedShopDrawingSheet(ViewSheet sheet, HashSet<string> sheetPrefixes)
        {
            string number = sheet?.SheetNumber ?? "";
            string name = sheet?.Name ?? "";
            foreach (string prefix in sheetPrefixes ?? new HashSet<string>())
            {
                if (!string.IsNullOrWhiteSpace(prefix) &&
                    number.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            return name.StartsWith("FORMWORK LAYOUT", StringComparison.OrdinalIgnoreCase) ||
                   name.StartsWith("REBAR DRAWING", StringComparison.OrdinalIgnoreCase) ||
                   name.StartsWith("SHOP DRAWING INDEX", StringComparison.OrdinalIgnoreCase) ||
                   name.StartsWith("SELECTED ELEMENT DETAIL", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsGeneratedShopDrawingViewName(string name)
        {
            string text = name ?? "";
            return text.StartsWith("MHNK_FWK_LAYOUT", StringComparison.OrdinalIgnoreCase) ||
                   text.StartsWith("MHNK_RBR_DRAWING", StringComparison.OrdinalIgnoreCase) ||
                   text.StartsWith("MHNK_SHOP_DRAWING_INDEX", StringComparison.OrdinalIgnoreCase) ||
                   text.StartsWith("MHNK_SEL_", StringComparison.OrdinalIgnoreCase);
        }

        private static ViewPlan CreateSelectedElementPlanView(
            Document doc,
            ViewFamilyType planType,
            HashSet<string> viewNames,
            Element element,
            XYZ min,
            XYZ max,
            string safeName,
            int viewScale)
        {
            if (doc == null || planType == null || element == null)
            {
                return null;
            }

            Level level = GetSelectedElementLevel(doc, element, min, max);
            if (level == null)
            {
                return null;
            }

            ViewPlan view = null;
            try
            {
                view = ViewPlan.Create(doc, planType.Id, level.Id);
                if (view == null)
                {
                    return null;
                }

                view.Name = MakeUniqueViewName(viewNames, $"MHNK_SEL_PLAN_{safeName}");
                ApplySelectedElementViewSettings(doc, view, element, viewScale);
                ApplySelectedElementPlanCrop(view, min, max);
                return view;
            }
            catch
            {
                if (view != null && view.Id != null && view.Id != ElementId.InvalidElementId)
                {
                    try
                    {
                        doc.Delete(view.Id);
                    }
                    catch
                    {
                    }
                }

                return null;
            }
        }

        private static ViewSection CreateSelectedElementVerticalView(
            Document doc,
            ViewFamilyType sectionType,
            HashSet<string> viewNames,
            Element element,
            XYZ min,
            XYZ max,
            string safeName,
            string viewKind,
            int viewScale,
            bool lookAlongX)
        {
            if (doc == null || sectionType == null || element == null)
            {
                return null;
            }

            double sizeX = Math.Max(max.X - min.X, MmToFeet(100.0));
            double sizeY = Math.Max(max.Y - min.Y, MmToFeet(100.0));
            double sizeZ = Math.Max(max.Z - min.Z, MmToFeet(100.0));
            double margin = GetSelectedElementViewMargin(min, max);
            XYZ center = new XYZ((min.X + max.X) * 0.5, (min.Y + max.Y) * 0.5, (min.Z + max.Z) * 0.5);

            Transform trf = Transform.Identity;
            trf.Origin = center;
            XYZ localMin;
            XYZ localMax;
            if (lookAlongX)
            {
                trf.BasisX = XYZ.BasisY;
                trf.BasisY = XYZ.BasisZ;
                trf.BasisZ = XYZ.BasisX;
                localMin = new XYZ(-sizeY * 0.5 - margin, -sizeZ * 0.5 - margin, -sizeX * 0.5 - margin);
                localMax = new XYZ(sizeY * 0.5 + margin, sizeZ * 0.5 + margin, sizeX * 0.5 + margin);
            }
            else
            {
                trf.BasisX = XYZ.BasisX;
                trf.BasisY = XYZ.BasisZ;
                trf.BasisZ = new XYZ(0.0, -1.0, 0.0);
                localMin = new XYZ(-sizeX * 0.5 - margin, -sizeZ * 0.5 - margin, -sizeY * 0.5 - margin);
                localMax = new XYZ(sizeX * 0.5 + margin, sizeZ * 0.5 + margin, sizeY * 0.5 + margin);
            }

            ViewSection view = null;
            try
            {
                view = ViewSection.CreateSection(
                    doc,
                    sectionType.Id,
                    new BoundingBoxXYZ
                    {
                        Transform = trf,
                        Min = localMin,
                        Max = localMax
                    });
                if (view == null)
                {
                    return null;
                }

                view.Name = MakeUniqueViewName(viewNames, $"MHNK_SEL_{viewKind}_{safeName}");
                ApplySelectedElementViewSettings(doc, view, element, viewScale);
                return view;
            }
            catch
            {
                if (view != null && view.Id != null && view.Id != ElementId.InvalidElementId)
                {
                    try
                    {
                        doc.Delete(view.Id);
                    }
                    catch
                    {
                    }
                }

                return null;
            }
        }

        private static View3D CreateSelectedElement3DView(
            Document doc,
            ViewFamilyType modelViewType,
            HashSet<string> viewNames,
            Element element,
            XYZ min,
            XYZ max,
            string safeName,
