        private static void ApplySelectedElementViewSettings(Document doc, View view, Element element, int viewScale)
        {
            if (doc == null || view == null || element == null)
            {
                return;
            }

            try
            {
                view.Scale = Math.Max(1, viewScale);
            }
            catch
            {
            }

            try
            {
                view.DetailLevel = ViewDetailLevel.Fine;
            }
            catch
            {
            }

            try
            {
                view.DisplayStyle = DisplayStyle.Shading;
            }
            catch
            {
            }

            try
            {
                view.SetElementOverrides(element.Id, BuildSelectedElementDetailOverride(doc));
            }
            catch
            {
            }
        }

        private static OverrideGraphicSettings BuildSelectedElementDetailOverride(Document doc)
        {
            var ogs = new OverrideGraphicSettings();
            Color fillColor = new Color(255, 205, 92);
            Color lineColor = new Color(24, 96, 190);
            ogs.SetProjectionLineColor(lineColor);
            ogs.SetCutLineColor(lineColor);
            ogs.SetSurfaceForegroundPatternColor(fillColor);
            ogs.SetCutForegroundPatternColor(fillColor);

            ElementId solidFillPatternId = GetSolidFillPatternId(doc);
            if (solidFillPatternId != ElementId.InvalidElementId)
            {
                ogs.SetSurfaceForegroundPatternId(solidFillPatternId);
                ogs.SetCutForegroundPatternId(solidFillPatternId);
                ogs.SetSurfaceForegroundPatternVisible(true);
                ogs.SetCutForegroundPatternVisible(true);
            }

            return ogs;
        }

        private static void ApplySelectedElementPlanCrop(ViewPlan view, XYZ min, XYZ max)
        {
            if (view == null)
            {
                return;
            }

            try
            {
                double margin = GetSelectedElementViewMargin(min, max);
                BoundingBoxXYZ crop = view.CropBox ?? new BoundingBoxXYZ();
                crop.Min = new XYZ(min.X - margin, min.Y - margin, min.Z - margin);
                crop.Max = new XYZ(max.X + margin, max.Y + margin, max.Z + margin);
                view.CropBox = crop;
                view.CropBoxActive = true;
                view.CropBoxVisible = true;
            }
            catch
            {
            }
        }

        private static ViewSheet CreateSelectedElementDetailSheetForViews(
            Document doc,
            ElementId titleBlockTypeId,
            HashSet<string> sheetNumbers,
            string sheetPrefix,
            string label,
            ShopDrawingIssueMetadata metadata,
            IList<View> views)
        {
            if (doc == null || views == null || views.Count == 0)
            {
                return null;
            }

            ViewSheet sheet = null;
            try
            {
                sheet = ViewSheet.Create(doc, titleBlockTypeId ?? ElementId.InvalidElementId);
                if (sheet == null)
                {
                    return null;
                }

                string sheetLabel = TruncateShopDrawingCell(DefaultText(label, "ELEMENT"), 30);
                sheet.SheetNumber = MakeUniqueSheetNumber(sheetNumbers, sheetPrefix);
                sheet.Name = TruncateShopDrawingCell($"SELECTED DETAIL - {sheetLabel}", 42);
                ApplyShopDrawingSheetMetadata(doc, sheet, metadata, "SELECTED ELEMENT DETAIL", sheetLabel);

                List<View> viewList = views.Where(v => v != null).Take(5).ToList();
                List<ShopDrawingSheetSlot> slots = BuildShopDrawingSheetSlots(doc, sheet, viewList.Count);

                int index = 0;
                int placedViewports = 0;
                foreach (View view in viewList)
                {
                    if (index >= slots.Count)
                    {
                        break;
                    }

                    Viewport viewport = PlaceShopDrawingViewportFitted(
                        doc,
                        sheet,
                        view,
                        slots[index],
                        preferredScale: view is ViewDrafting ? 1 : Math.Max(1, view.Scale),
                        titleOnSheet: GetSelectedElementViewportTitle(view, index),
                        detailNumber: (index + 1).ToString(CultureInfo.InvariantCulture));
                    if (viewport != null)
                    {
                        placedViewports++;
                    }
                    index++;
                }

                if (placedViewports == 0)
                {
                    doc.Delete(sheet.Id);
                    return null;
                }

                return sheet;
            }
            catch
            {
                if (sheet != null && sheet.Id != null && sheet.Id != ElementId.InvalidElementId)
                {
                    try
                    {
                        doc.Delete(sheet.Id);
                    }
                    catch
                    {
                    }
                }

                return null;
            }
        }

        private static void DrawSelectedElementDimensionView(
            Document doc,
            ViewDrafting view,
            TextNoteType textType,
            Element element,
            XYZ min,
            XYZ max,
            string label,
            ShopDrawingIssueMetadata metadata)
        {
            double sizeX = Math.Max(0.0, max.X - min.X);
            double sizeY = Math.Max(0.0, max.Y - min.Y);
            double sizeZ = Math.Max(0.0, max.Z - min.Z);

            string elementId = element?.Id.Value.ToString(CultureInfo.InvariantCulture) ?? "-";
            List<Element> associatedRebar = CollectAssociatedSelectedElementRebar(doc, element);
            List<Element> associatedFormwork = CollectAssociatedSelectedElementFormwork(doc, element);

            AddShopDrawingText(doc, view, textType, 0.0, 0.66, $"DIMENSIONS - {TruncateShopDrawingCell(label, 26)}");
            AddShopDrawingText(doc, view, textType, 0.0, 0.46, $"Issue: {DefaultText(metadata?.IssueText, "FOR CONSTRUCTION REVIEW")} | Rev: {DefaultText(metadata?.Revision, "R0")} | ID: {elementId}");
            AddShopDrawingText(doc, view, textType, 0.0, 0.28, $"X {FormatShopDrawingLength(sizeX)} | Y {FormatShopDrawingLength(sizeY)} | H {FormatShopDrawingLength(sizeZ)}");
            AddShopDrawingText(doc, view, textType, 0.0, 0.11, $"Bottom {FormatShopDrawingElevation(min.Z)} | Top {FormatShopDrawingElevation(max.Z)}");

            const double planLeft = 0.08;
            const double planTop = -0.14;
            const double planWidth = 0.92;
            const double planHeight = 0.55;
            AddShopDrawingText(doc, view, textType, planLeft, planTop + 0.2, "PLAN EXTENT");
            AddShopDrawingRectangle(doc, view, planLeft, planTop, planLeft + planWidth, planTop - planHeight);
            AddSelectedElementDimensionLine(doc, view, textType, planLeft, planTop - planHeight - 0.25, planLeft + planWidth, planTop - planHeight - 0.25, $"X = {FormatShopDrawingLength(sizeX)}");
            AddSelectedElementDimensionLine(doc, view, textType, planLeft - 0.25, planTop, planLeft - 0.25, planTop - planHeight, $"Y = {FormatShopDrawingLength(sizeY)}");

            const double elevationLeft = 1.38;
            const double elevationTop = -0.14;
            const double elevationWidth = 0.92;
            const double elevationHeight = 0.55;
            AddShopDrawingText(doc, view, textType, elevationLeft, elevationTop + 0.2, "SECTION / ELEV.");
            AddShopDrawingRectangle(doc, view, elevationLeft, elevationTop, elevationLeft + elevationWidth, elevationTop - elevationHeight);
            AddSelectedElementDimensionLine(doc, view, textType, elevationLeft, elevationTop - elevationHeight - 0.25, elevationLeft + elevationWidth, elevationTop - elevationHeight - 0.25, $"X/Y = {FormatShopDrawingLength(Math.Max(sizeX, sizeY))}");
            AddSelectedElementDimensionLine(doc, view, textType, elevationLeft - 0.25, elevationTop, elevationLeft - 0.25, elevationTop - elevationHeight, $"H = {FormatShopDrawingLength(sizeZ)}");

            AddSelectedElementDataPanel(doc, view, textType, element, label, x: 2.62, y: 0.58);
            AddSelectedElementQuantityPanel(doc, view, textType, associatedRebar, associatedFormwork, x: 2.62, y: -0.40);
            AddSelectedElementSiteReadinessPanel(doc, view, textType, element, associatedRebar, associatedFormwork, sizeX, sizeY, sizeZ, x: 0.08, y: -1.18);
        }

        private static void AddSelectedElementDataPanel(
            Document doc,
            View view,
            TextNoteType textType,
            Element element,
            string label,
            double x,
            double y)
        {
            string mark = "";
            try
            {
                mark = element?.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString() ?? "";
            }
            catch
            {
            }

            ElementId hostId = TryGetHostedRebarHostId(element);
            Element host = hostId != null && hostId != ElementId.InvalidElementId ? doc?.GetElement(hostId) : null;
            string hostText = host == null
                ? "-"
                : $"{AbbreviateShopDrawingCategory(host.Category?.Name)} #{host.Id.Value}";
            var rows = new List<string[]>
            {
                new[] { "Label", TruncateShopDrawingCell(label, 24) },
                new[] { "Category", TruncateShopDrawingCell(AbbreviateShopDrawingCategory(element?.Category?.Name), 24) },
                new[] { "Type", TruncateShopDrawingCell(GetShopDrawingElementTypeName(doc, element), 24) },
                new[] { "Level", TruncateShopDrawingCell(DefaultText(GetShopDrawingElementLevelName(doc, element), "-"), 24) },
                new[] { "Mark", TruncateShopDrawingCell(DefaultText(mark, "-"), 24) },
                new[] { "Material", TruncateShopDrawingCell(DefaultText(GetSelectedElementMaterialName(doc, element), "-"), 24) },
                new[] { "Host", TruncateShopDrawingCell(hostText, 24) }
            };

            DrawShopDrawingKeyValuePanel(doc, view, textType, x, y, "ELEMENT DATA", rows, valueWidth: 1.15);
        }

        private static void AddSelectedElementQuantityPanel(
            Document doc,
            View view,
            TextNoteType textType,
            IList<Element> associatedRebar,
            IList<Element> associatedFormwork,
            double x,
            double y)
        {
            double rebarLengthM = (associatedRebar ?? new List<Element>())
                .Where(e => e != null)
                .Sum(GetShopDrawingRebarLengthFt) * 0.3048;
            double rebarWeightKg = (associatedRebar ?? new List<Element>())
                .Where(e => e != null)
                .Sum(e => EstimateShopDrawingRebarWeightKg(doc, e));
            double formworkAreaSqM = (associatedFormwork ?? new List<Element>())
                .Where(e => e != null)
                .Sum(e => GetShopDrawingParameterDouble(e, "CBIM.FWK.FaceArea")) * 0.09290304;

            var rows = new List<string[]>
            {
                new[] { "Rebar sets", $"{associatedRebar?.Count ?? 0}" },
                new[] { "Rebar length", $"{rebarLengthM:0.###} m" },
                new[] { "Rebar weight", $"{rebarWeightKg:0.###} kg" },
                new[] { "FWK shapes", $"{associatedFormwork?.Count ?? 0}" },
                new[] { "FWK area", $"{formworkAreaSqM:0.###} m2" }
            };

            DrawShopDrawingKeyValuePanel(doc, view, textType, x, y, "QTY SUMMARY", rows, valueWidth: 1.15);

            List<string[]> topBars = BuildSelectedElementTopRebarRows(doc, associatedRebar, maxRows: 3);
            if (topBars.Count > 0)
            {
                AddShopDrawingText(doc, view, textType, x, y - 1.36, "TOP REBAR");
                double rowY = y - 1.54;
                foreach (string[] row in topBars)
                {
                    AddShopDrawingText(doc, view, textType, x, rowY, $"{row[0]} | {row[1]} | {row[2]}");
                    rowY -= 0.17;
                }
            }
        }

        private static void AddSelectedElementSiteReadinessPanel(
            Document doc,
            View view,
            TextNoteType textType,
            Element element,
            IList<Element> associatedRebar,
            IList<Element> associatedFormwork,
            double sizeX,
            double sizeY,
            double sizeZ,
            double x,
            double y)
        {
            AddShopDrawingText(doc, view, textType, x, y, "SITE READINESS");
            List<string> rows = BuildSelectedElementSiteReadinessRows(doc, element, associatedRebar, associatedFormwork, sizeX, sizeY, sizeZ)
                .Take(5)
                .ToList();

            double rowY = y - 0.20;
            foreach (string row in rows)
            {
                AddShopDrawingText(doc, view, textType, x, rowY, TruncateShopDrawingCell(row, 58));
                rowY -= 0.18;
            }
        }

        private static void DrawShopDrawingKeyValuePanel(
            Document doc,
            View view,
            TextNoteType textType,
            double x,
            double y,
            string title,
            IList<string[]> rows,
            double valueWidth)
        {
            AddShopDrawingText(doc, view, textType, x, y, title);
            double rowHeight = 0.17;
            double keyWidth = 0.62;
            double tableTop = y - 0.12;
            double tableBottom = tableTop - Math.Max(1, rows?.Count ?? 0) * rowHeight - 0.04;
            double tableRight = x + keyWidth + Math.Max(0.85, valueWidth);
            AddShopDrawingRectangle(doc, view, x - 0.04, tableTop + 0.04, tableRight + 0.04, tableBottom);
            AddShopDrawingLine(doc, view, x + keyWidth, tableTop + 0.04, x + keyWidth, tableBottom);

            double rowY = tableTop - rowHeight + 0.04;
            foreach (string[] row in rows ?? new List<string[]>())
            {
                string key = row.Length > 0 ? row[0] : "";
                string value = row.Length > 1 ? row[1] : "";
                AddShopDrawingText(doc, view, textType, x, rowY, TruncateShopDrawingCell(key, 13));
                AddShopDrawingText(doc, view, textType, x + keyWidth + 0.04, rowY, TruncateShopDrawingCell(value, 26));
                rowY -= rowHeight;
            }
        }

        private static List<Element> CollectAssociatedSelectedElementRebar(Document doc, Element element)
        {
            var result = new List<Element>();
            if (doc == null || element == null)
            {
                return result;
            }

            if (element.Category?.Id?.Value == (long)BuiltInCategory.OST_Rebar)
            {
                result.Add(element);
                return result;
            }

            ElementId hostId = element.Id;
            if (hostId == null || hostId == ElementId.InvalidElementId)
            {
                return result;
            }

            try
            {
                foreach (Element rebar in new FilteredElementCollector(doc)
                    .WhereElementIsNotElementType()
                    .OfCategory(BuiltInCategory.OST_Rebar))
                {
                    ElementId rebarHostId = TryGetHostedRebarHostId(rebar);
                    if (rebarHostId != null &&
                        rebarHostId != ElementId.InvalidElementId &&
                        rebarHostId.Value == hostId.Value)
                    {
                        result.Add(rebar);
                    }
                }
            }
            catch
            {
            }

            return result;
        }

        private static List<Element> CollectAssociatedSelectedElementFormwork(Document doc, Element element)
        {
            var result = new List<Element>();
            if (doc == null || element == null)
            {
                return result;
            }

            ElementId hostId = TryGetHostedRebarHostId(element);
            long hostValue = hostId != null && hostId != ElementId.InvalidElementId
                ? hostId.Value
                : element.Id?.Value ?? -1L;
            if (hostValue <= 0)
            {
                return result;
            }

            try
            {
                foreach (Element shape in new FilteredElementCollector(doc)
                    .WhereElementIsNotElementType()
                    .OfCategory(BuiltInCategory.OST_SpecialityEquipment))
                {
                    if (IsShopDrawingFormworkShape(shape) &&
                        TryGetFormworkHostIdValue(shape) == hostValue)
                    {
                        result.Add(shape);
                    }
                }
            }
            catch
            {
            }

            return result;
        }

        private static List<string[]> BuildSelectedElementTopRebarRows(Document doc, IList<Element> rebarElements, int maxRows)
        {
            return (rebarElements ?? new List<Element>())
                .Where(e => e != null)
                .GroupBy(e => GetShopDrawingElementTypeName(doc, e), StringComparer.OrdinalIgnoreCase)
                .OrderByDescending(g => g.Sum(GetShopDrawingRebarLengthFt))
                .ThenBy(g => g.Key, StringComparer.OrdinalIgnoreCase)
                .Take(Math.Max(1, maxRows))
                .Select(g =>
                {
                    double diameterMm = g.Select(e => GetShopDrawingRebarDiameterMm(doc, e)).FirstOrDefault(v => v > 1e-9);
                    double lengthM = g.Sum(GetShopDrawingRebarLengthFt) * 0.3048;
                    return new[]
                    {
                        TruncateShopDrawingCell(g.Key, 16),
                        diameterMm > 1e-9 ? $"D{diameterMm:0.#}" : "-",
                        $"{g.Count()} set / {lengthM:0.##} m"
                    };
                })
                .ToList();
        }

        private static List<string> BuildSelectedElementSiteReadinessRows(
            Document doc,
            Element element,
            IList<Element> associatedRebar,
            IList<Element> associatedFormwork,
            double sizeX,
            double sizeY,
            double sizeZ)
        {
            var rows = new List<string>();
            string mark = "";
            try
            {
                mark = element?.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString() ?? "";
            }
            catch
            {
            }

            if (string.IsNullOrWhiteSpace(mark))
            {
                rows.Add("Check: element mark is empty.");
            }

            if (string.IsNullOrWhiteSpace(GetSelectedElementMaterialName(doc, element)))
            {
                rows.Add("Check: material parameter not found.");
            }

            if (sizeX <= 1e-9 || sizeY <= 1e-9 || sizeZ <= 1e-9)
            {
                rows.Add("Check: model bounds are incomplete.");
            }

            bool selectedRebar = element?.Category?.Id?.Value == (long)BuiltInCategory.OST_Rebar;
            if (!selectedRebar && (associatedRebar?.Count ?? 0) == 0)
            {
                rows.Add("Check: no hosted rebar found for this element.");
            }

            if ((associatedFormwork?.Count ?? 0) == 0)
            {
                rows.Add("Check: no CBIM formwork shapes found.");
            }

            rows.Add("Verify grids, openings, sleeves, embeds, joints, and cover.");
            rows.Add("Confirm dimensions with approved structural drawings.");
            return rows;
        }

        private static string GetSelectedElementMaterialName(Document doc, Element element)
        {
            string direct = GetSelectedElementMaterialNameFromParameters(doc, element);
            if (!string.IsNullOrWhiteSpace(direct))
            {
                return direct;
            }

            try
            {
                Element type = doc?.GetElement(element?.GetTypeId());
                string typeMaterial = GetSelectedElementMaterialNameFromParameters(doc, type);
                if (!string.IsNullOrWhiteSpace(typeMaterial))
                {
                    return typeMaterial;
                }
            }
            catch
            {
            }

            try
            {
                ElementId materialId = element?.GetMaterialIds(false)?.FirstOrDefault();
                if (materialId != null &&
                    materialId != ElementId.InvalidElementId &&
                    doc?.GetElement(materialId) is Material material &&
                    !string.IsNullOrWhiteSpace(material.Name))
                {
                    return material.Name;
                }
            }
            catch
            {
            }

            return "";
        }

        private static string GetSelectedElementMaterialNameFromParameters(Document doc, Element element)
        {
            string[] names =
            {
                "Structural Material",
                "Material",
                "Concrete Material",
                "Rebar Material"
            };

            foreach (string name in names)
            {
                try
                {
                    Parameter parameter = element?.LookupParameter(name);
                    if (parameter == null)
                    {
                        continue;
                    }

                    if (parameter.StorageType == StorageType.String)
                    {
                        string value = parameter.AsString();
                        if (!string.IsNullOrWhiteSpace(value))
                        {
                            return value.Trim();
                        }
                    }

                    if (parameter.StorageType == StorageType.ElementId)
                    {
                        ElementId id = parameter.AsElementId();
                        if (id != null &&
                            id != ElementId.InvalidElementId &&
                            doc?.GetElement(id) is Element material &&
                            !string.IsNullOrWhiteSpace(material.Name))
                        {
                            return material.Name;
                        }
                    }
                }
                catch
                {
                }
            }

            return "";
        }

        private static void AddSelectedElementDimensionLine(
            Document doc,
            View view,
            TextNoteType textType,
            double x0,
            double y0,
            double x1,
            double y1,
            string label)
        {
            const double tick = 0.08;
            AddShopDrawingLine(doc, view, x0, y0, x1, y1);
            bool horizontal = Math.Abs(x1 - x0) >= Math.Abs(y1 - y0);
            if (horizontal)
            {
                AddShopDrawingLine(doc, view, x0, y0 - tick, x0, y0 + tick);
                AddShopDrawingLine(doc, view, x1, y1 - tick, x1, y1 + tick);
                AddShopDrawingText(doc, view, textType, (x0 + x1) * 0.5 - 0.42, y0 - 0.14, label);
            }
            else
            {
                AddShopDrawingLine(doc, view, x0 - tick, y0, x0 + tick, y0);
                AddShopDrawingLine(doc, view, x1 - tick, y1, x1 + tick, y1);
                AddShopDrawingText(doc, view, textType, x0 - 0.2, (y0 + y1) * 0.5, label);
            }
        }

        private static string BuildSelectedElementShopDrawingLabel(Document doc, Element element)
        {
            string idText = element?.Id.Value.ToString(CultureInfo.InvariantCulture) ?? "";
            string category = AbbreviateShopDrawingCategory(DefaultText(element?.Category?.Name, "Element"));
            string typeName = GetShopDrawingElementTypeName(doc, element);
            string mark = "";
            try
            {
                mark = element?.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString() ?? "";
            }
            catch
            {
            }

            string primary = DefaultText(mark, typeName);
            if (string.IsNullOrWhiteSpace(primary))
            {
                primary = category;
            }

            primary = Regex.Replace(primary, @"\s+", " ").Trim();
            primary = TruncateShopDrawingCell(primary, 20);
            string suffix = string.IsNullOrWhiteSpace(idText) ? "" : $" #{idText}";
            return TruncateShopDrawingCell($"{primary}{suffix}", 30);
        }

        private static string BuildSelectedElementShopDrawingSafeName(Element element)
        {
            string idText = element?.Id.Value.ToString(CultureInfo.InvariantCulture);
            return string.IsNullOrWhiteSpace(idText)
                ? "ELEMENT"
                : SanitizeShopDrawingName(idText);
        }

        private static string AbbreviateShopDrawingCategory(string category)
        {
            string text = DefaultText(category, "Element");
            if (text.Equals("Structural Framing", StringComparison.OrdinalIgnoreCase))
            {
                return "Framing";
            }

            if (text.Equals("Structural Columns", StringComparison.OrdinalIgnoreCase))
            {
                return "Column";
            }

            if (text.Equals("Structural Foundations", StringComparison.OrdinalIgnoreCase))
            {
                return "Foundation";
            }

            if (text.Equals("Floors", StringComparison.OrdinalIgnoreCase))
            {
                return "Slab";
            }

            return text;
        }

        private static string GetSelectedElementViewportTitle(View view, int index)
        {
            string name = view?.Name ?? "";
            if (view is ViewDrafting || name.IndexOf("_DIM_", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "DIMENSIONS";
            }

            if (view is View3D || name.IndexOf("_3D_", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "3D";
            }

            if (name.IndexOf("_ELEVATION_", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "ELEVATION";
            }

            if (name.IndexOf("_SECTION_", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "SECTION";
            }

            if (view is ViewPlan || name.IndexOf("_PLAN_", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "PLAN";
            }

            return $"VIEW {index + 1}";
        }

        private static Level GetSelectedElementLevel(Document doc, Element element, XYZ min, XYZ max)
        {
            if (doc == null || element == null)
            {
                return null;
            }

            try
            {
                if (doc.GetElement(element.LevelId) is Level level)
                {
                    return level;
                }
            }
            catch
            {
            }

            ElementId hostId = TryGetHostedRebarHostId(element);
            if (hostId != null && hostId != ElementId.InvalidElementId && doc.GetElement(hostId) is Element host)
            {
                Level hostLevel = GetSelectedElementLevel(doc, host, min, max);
                if (hostLevel != null)
                {
                    return hostLevel;
                }
            }

            BuiltInParameter[] levelParams =
            {
                BuiltInParameter.LEVEL_PARAM,
                BuiltInParameter.FAMILY_LEVEL_PARAM,
                BuiltInParameter.SCHEDULE_LEVEL_PARAM
            };

            foreach (BuiltInParameter bip in levelParams)
            {
                try
                {
                    Parameter p = element.get_Parameter(bip);
                    if (p?.StorageType != StorageType.ElementId)
                    {
                        continue;
                    }

                    ElementId levelId = p.AsElementId();
                    if (levelId != null && levelId != ElementId.InvalidElementId && doc.GetElement(levelId) is Level level)
                    {
                        return level;
                    }
                }
                catch
                {
                }
            }

            double targetZ = min != null && max != null ? (min.Z + max.Z) * 0.5 : 0.0;
            return new FilteredElementCollector(doc)
                .OfClass(typeof(Level))
                .Cast<Level>()
                .OrderBy(l => Math.Abs(l.Elevation - targetZ))
                .FirstOrDefault();
        }

        private static double GetSelectedElementViewMargin(XYZ min, XYZ max)
        {
            double dx = Math.Abs((max?.X ?? 0.0) - (min?.X ?? 0.0));
            double dy = Math.Abs((max?.Y ?? 0.0) - (min?.Y ?? 0.0));
            double dz = Math.Abs((max?.Z ?? 0.0) - (min?.Z ?? 0.0));
            double maxSize = Math.Max(dx, Math.Max(dy, dz));
            return Math.Max(MmToFeet(300.0), maxSize * 0.15);
        }

        private static string FormatShopDrawingLength(double feet)
        {
            return $"{feet * 0.3048:0.###} m ({feet * 304.8:0.#} mm)";
        }

        private static string FormatShopDrawingElevation(double feet)
        {
            return $"{feet * 0.3048:0.###} m";
        }

        private void CreateShopDrawingViewsForGroups(
            Document doc,
            ViewFamilyType draftingType,
            ViewFamilyType modelViewType,
            TextNoteType textType,
            HashSet<string> viewNames,
            HashSet<string> sheetNumbers,
            ElementId titleBlockTypeId,
            IList<Element> elements,
            string drawingTitle,
            string viewPrefix,
            string sheetPrefix,
            int viewScale,
            int maxMarksPerSheet,
            ShopDrawingGroupMode groupMode,
            string issueText,
            ShopDrawingIssueMetadata metadata,
            bool createSheets,
            bool isFormwork,
            List<View> createdViews,
            List<ViewSheet> createdSheets,
            ref int skippedGroups)
        {
            foreach (ShopDrawingElementGroup group in GroupShopDrawingElements(doc, elements, isFormwork, groupMode))
            {
                List<Element> groupElements = (group.Elements ?? new List<Element>())
                    .Where(x => x != null && x.Id != null && x.Id != ElementId.InvalidElementId)
                    .ToList();
                if (groupElements.Count == 0)
                {
                    skippedGroups++;
                    continue;
                }

                ViewDrafting view = null;
                View3D modelView = null;
                try
                {
                    view = ViewDrafting.Create(doc, draftingType.Id);
                    string safeLevel = string.IsNullOrWhiteSpace(group.SafeName)
                        ? SanitizeShopDrawingName(group.DisplayName)
                        : group.SafeName;
                    view.Name = MakeUniqueViewName(viewNames, $"{viewPrefix}_{safeLevel}");
                    try
                    {
                        view.Scale = 1;
                    }
                    catch
                    {
                    }

                    DrawShopDrawingDraftingView(doc, view, textType, groupElements, drawingTitle, group.DisplayName, viewScale, maxMarksPerSheet, issueText, isFormwork);
                    createdViews.Add(view);

                    if (modelViewType != null)
                    {
                        modelView = CreateShopDrawingModelView(
                            doc,
                            modelViewType,
                            viewNames,
                            groupElements,
                            $"{viewPrefix}_3D_{safeLevel}",
                            viewScale,
                            isFormwork);
                        if (modelView != null)
                        {
                            createdViews.Add(modelView);
                        }
                    }

                    if (createSheets)
                    {
                        ViewSheet sheet = CreateShopDrawingSheetForViews(
                            doc,
                            view,
                            modelView,
                            titleBlockTypeId,
                            sheetNumbers,
                            sheetPrefix,
                            drawingTitle,
                            group.DisplayName,
                            metadata);
                        if (sheet != null)
                        {
                            createdSheets.Add(sheet);
                        }
                    }
                }
                catch
                {
                    if (modelView != null && modelView.Id != null && modelView.Id != ElementId.InvalidElementId)
                    {
                        try
                        {
                            doc.Delete(modelView.Id);
                        }
                        catch
                        {
                        }
                    }

                    if (view != null && view.Id != null && view.Id != ElementId.InvalidElementId)
                    {
                        try
                        {
                            doc.Delete(view.Id);
                        }
                        catch
                        {
                        }
                    }

                    skippedGroups++;
                }
            }
        }

        private sealed class ShopDrawingElementGroup
        {
            public string DisplayName { get; set; } = "";
            public string SafeName { get; set; } = "";
            public List<Element> Elements { get; set; } = new List<Element>();
        }

        private sealed class ShopDrawingIssueMetadata
        {
            public string PackageName { get; set; } = "SHOP DRAWING PACKAGE";
            public string Discipline { get; set; } = "STRUCTURAL";
            public string IssueText { get; set; } = "FOR CONSTRUCTION REVIEW";
            public string Revision { get; set; } = "R0";
            public string PreparedBy { get; set; } = "";
            public string CheckedBy { get; set; } = "";
            public string ApprovedBy { get; set; } = "";
            public string IssueDate { get; set; } = "";
        }

        private sealed class ShopDrawingSheetSlot
        {
            public XYZ Center { get; set; } = XYZ.Zero;
            public double Width { get; set; }
            public double Height { get; set; }
        }

        private static IEnumerable<ShopDrawingElementGroup> GroupShopDrawingElements(
            Document doc,
            IList<Element> elements,
            bool isFormwork,
            ShopDrawingGroupMode groupMode)
        {
            return (elements ?? new List<Element>())
                .Where(x => x != null)
                .GroupBy(
                    x => BuildShopDrawingGroupName(doc, x, isFormwork, groupMode),
                    StringComparer.OrdinalIgnoreCase)
                .OrderBy(g => g.Key, StringComparer.OrdinalIgnoreCase)
                .Select(g => new ShopDrawingElementGroup
                {
                    DisplayName = g.Key,
                    SafeName = SanitizeShopDrawingName(g.Key),
                    Elements = g
                        .OrderBy(e => e.Id?.Value ?? 0)
                        .ToList()
                });
        }

        private static string BuildShopDrawingGroupName(
            Document doc,
            Element element,
            bool isFormwork,
            ShopDrawingGroupMode groupMode)
        {
            string level = DefaultText(GetShopDrawingElementLevelName(doc, element), "NO_LEVEL");
            if (groupMode == ShopDrawingGroupMode.LevelOnly)
            {
                return level;
            }

            string category = GetShopDrawingElementCategoryLabel(doc, element, isFormwork);
            if (groupMode == ShopDrawingGroupMode.LevelAndCategory)
            {
                return $"{level} - {category}";
            }

            string host = GetShopDrawingElementHostGroupLabel(doc, element, isFormwork);
            return $"{level} - {category} - {host}";
        }

        private void DrawShopDrawingDraftingView(
            Document doc,
            ViewDrafting view,
            TextNoteType textType,
            IList<Element> elements,
            string drawingTitle,
            string levelName,
            int viewScale,
            int maxMarksPerSheet,
            string issueText,
            bool isFormwork)
        {
            AddShopDrawingText(doc, view, textType, 0.0, 0.8, $"{drawingTitle} - {levelName}");
            AddShopDrawingText(doc, view, textType, 0.0, 0.45, $"Scale 1:{viewScale} | Issue: {issueText} | Elements: {elements.Count} | Generated by CamboBIM");

            if (TryGetShopDrawingModelBounds(elements, out double minX, out double minY, out double maxX, out double maxY))
            {
                const double drawingWidth = 7.6;
                const double drawingHeight = 5.0;
                const double left = 0.0;
                const double top = -0.15;

                double modelWidth = Math.Max(maxX - minX, 1e-6);
                double modelHeight = Math.Max(maxY - minY, 1e-6);
                double fit = Math.Min(drawingWidth / modelWidth, drawingHeight / modelHeight);
                if (double.IsNaN(fit) || double.IsInfinity(fit) || fit <= 1e-9)
                {
                    fit = 1.0;
                }

                AddShopDrawingRectangle(doc, view, left, top, left + drawingWidth, top - drawingHeight);
                AddShopDrawingLayoutDimensionNotes(
                    doc,
                    view,
                    textType,
                    left,
                    top,
                    drawingWidth,
                    drawingHeight,
                    modelWidth,
                    modelHeight);

                int drawn = 0;
                foreach (Element element in elements.Take(250))
                {
                    BoundingBoxXYZ bb = element.get_BoundingBox(null);
                    if (bb == null)
                    {
                        continue;
                    }

                    double x0 = left + ((bb.Min.X - minX) * fit);
                    double x1 = left + ((bb.Max.X - minX) * fit);
                    double y0 = top - ((bb.Min.Y - minY) * fit);
                    double y1 = top - ((bb.Max.Y - minY) * fit);
                    if (Math.Abs(x1 - x0) < 0.02)
                    {
                        x1 = x0 + 0.02;
                    }
                    if (Math.Abs(y1 - y0) < 0.02)
                    {
                        y1 = y0 - 0.02;
                    }

                    AddShopDrawingRectangle(doc, view, x0, y0, x1, y1);
                    if (drawn < 45)
                    {
                        AddShopDrawingText(doc, view, textType, x0, Math.Max(y0, y1) + 0.03, BuildShopDrawingElementTag(element, drawn + 1, isFormwork));
                    }

                    drawn++;
                }

                if (elements.Count > 250)
                {
                    AddShopDrawingText(doc, view, textType, 0.0, top - drawingHeight - 0.3, $"Layout preview limited to first 250 of {elements.Count} element(s).");
                }
            }
            else
            {
                AddShopDrawingText(doc, view, textType, 0.0, -0.15, "No drawable bounding boxes were available; see element schedule below.");
            }

            DrawShopDrawingScheduleTable(doc, view, textType, elements, isFormwork, maxMarksPerSheet, 8.1, 0.35);
            AddShopDrawingConstructionNotes(doc, view, textType, isFormwork, 8.1, -5.45);
        }

        private static View3D CreateShopDrawingModelView(
            Document doc,
            ViewFamilyType modelViewType,
            HashSet<string> viewNames,
            IList<Element> elements,
            string baseName,
            int viewScale,
            bool isFormwork)
        {
            if (doc == null || modelViewType == null)
            {
                return null;
            }

            if (!TryGetShopDrawingModelBounds3D(elements, out XYZ min, out XYZ max))
            {
                return null;
            }

            View3D view = null;
            try
            {
                view = View3D.CreateIsometric(doc, modelViewType.Id);
                if (view == null)
                {
                    return null;
                }

                view.Name = MakeUniqueViewName(viewNames, baseName);
                view.DetailLevel = ViewDetailLevel.Fine;
                view.DisplayStyle = DisplayStyle.Shading;
                try
                {
                    view.Scale = Math.Max(1, viewScale);
                }
                catch
                {
                }

                double margin = Math.Max(MmToFeet(300.0), Math.Max(Math.Max(max.X - min.X, max.Y - min.Y), max.Z - min.Z) * 0.08);
                BoundingBoxXYZ sectionBox = new BoundingBoxXYZ
                {
                    Transform = Transform.Identity,
                    Min = new XYZ(min.X - margin, min.Y - margin, min.Z - margin),
                    Max = new XYZ(max.X + margin, max.Y + margin, max.Z + margin)
                };

                try
                {
                    view.IsSectionBoxActive = true;
                    view.SetSectionBox(sectionBox);
                }
                catch
                {
                }

                OverrideGraphicSettings targetOverride = BuildShopDrawingTargetOverride(doc, isFormwork);
                foreach (ElementId id in (elements ?? new List<Element>())
                    .Where(e => e?.Id != null && e.Id != ElementId.InvalidElementId)
                    .Select(e => e.Id)
                    .Distinct())
                {
                    try
                    {
                        view.SetElementOverrides(id, targetOverride);
                    }
                    catch
                    {
                    }
                }

                HideOtherShopDrawingTargetElements(doc, view, elements, isFormwork);
            }
            catch
            {
                if (view != null && view.Id != null && view.Id != ElementId.InvalidElementId)
                {
                    try
                    {
                        doc.Delete(view.Id);
                    }
                    catch
                    {
                    }
                }

                return null;
            }

            return view;
        }

        private static OverrideGraphicSettings BuildShopDrawingTargetOverride(Document doc, bool isFormwork)
        {
            Color fillColor = isFormwork
                ? new Color(242, 154, 74)
                : new Color(45, 124, 220);
            Color lineColor = isFormwork
                ? new Color(179, 107, 45)
                : new Color(24, 75, 155);

            var ogs = new OverrideGraphicSettings();
            ogs.SetProjectionLineColor(lineColor);
            ogs.SetCutLineColor(lineColor);
            ogs.SetSurfaceForegroundPatternColor(fillColor);
            ogs.SetCutForegroundPatternColor(fillColor);
            ogs.SetSurfaceTransparency(isFormwork ? 18 : 0);

            ElementId solidFillPatternId = GetSolidFillPatternId(doc);
            if (solidFillPatternId != ElementId.InvalidElementId)
            {
                ogs.SetSurfaceForegroundPatternId(solidFillPatternId);
                ogs.SetCutForegroundPatternId(solidFillPatternId);
                ogs.SetSurfaceForegroundPatternVisible(true);
                ogs.SetCutForegroundPatternVisible(true);
            }

            return ogs;
        }

        private static void HideOtherShopDrawingTargetElements(Document doc, View view, IList<Element> targetElements, bool isFormwork)
        {
            if (doc == null || view == null)
            {
                return;
            }

            var targetIds = new HashSet<long>(
                (targetElements ?? new List<Element>())
                    .Where(e => e?.Id != null && e.Id != ElementId.InvalidElementId)
                    .Select(e => e.Id.Value));

            BuiltInCategory category = isFormwork
                ? BuiltInCategory.OST_SpecialityEquipment
                : BuiltInCategory.OST_Rebar;

            List<ElementId> hideIds;
            try
            {
                hideIds = new FilteredElementCollector(doc)
                    .WhereElementIsNotElementType()
                    .OfCategory(category)
                    .Where(e => e?.Id != null && e.Id != ElementId.InvalidElementId)
                    .Where(e => !targetIds.Contains(e.Id.Value))
                    .Where(e => !isFormwork || IsShopDrawingFormworkShape(e))
                    .Select(e => e.Id)
                    .ToList();
            }
            catch
            {
                return;
            }

            if (hideIds.Count == 0)
            {
                return;
            }

            try
            {
                List<ElementId> visibleHideIds = hideIds
                    .Where(id =>
                    {
                        try
                        {
                            Element element = doc.GetElement(id);
                            return element != null && element.CanBeHidden(view);
                        }
                        catch
                        {
                            return false;
                        }
                    })
                    .ToList();

                if (visibleHideIds.Count > 0)
                {
                    view.HideElements(visibleHideIds);
                }
            }
            catch
            {
            }
        }

        private static ViewSheet CreateShopDrawingSheetForViews(
            Document doc,
            View draftingView,
            View modelView,
            ElementId titleBlockTypeId,
            HashSet<string> sheetNumbers,
            string sheetPrefix,
            string drawingTitle,
            string levelName,
            ShopDrawingIssueMetadata metadata)
        {
            ViewSheet sheet = null;
            try
            {
                sheet = ViewSheet.Create(doc, titleBlockTypeId ?? ElementId.InvalidElementId);
                if (sheet == null)
                {
                    return null;
                }

                string sheetNumber = MakeUniqueSheetNumber(sheetNumbers, sheetPrefix);
                sheet.SheetNumber = sheetNumber;
                sheet.Name = $"{drawingTitle} - {levelName}";
                ApplyShopDrawingSheetMetadata(doc, sheet, metadata, drawingTitle, levelName);

                List<ShopDrawingSheetSlot> slots = BuildShopDrawingSheetSlots(doc, sheet, modelView != null ? 2 : 1);
                int placedViewports = 0;
                Viewport draftingViewport = null;
                if (draftingView != null && slots.Count > 0)
                {
                    draftingViewport = PlaceShopDrawingViewportFitted(
                        doc,
                        sheet,
                        draftingView,
                        slots[0],
                        preferredScale: 1);
                    if (draftingViewport != null)
                    {
                        placedViewports++;
                    }
                }

                if (modelView != null && slots.Count > 1)
                {
                    Viewport modelViewport = PlaceShopDrawingViewportFitted(
                        doc,
                        sheet,
                        modelView,
                        slots[1],
                        preferredScale: Math.Max(1, modelView.Scale));
                    if (modelViewport != null)
                    {
                        placedViewports++;
                    }
                }

                if (placedViewports == 0)
                {
                    doc.Delete(sheet.Id);
                    return null;
                }
            }
            catch
            {
                if (sheet != null && sheet.Id != null && sheet.Id != ElementId.InvalidElementId)
                {
                    try
                    {
                        doc.Delete(sheet.Id);
                    }
                    catch
                    {
                    }
                }

                return null;
            }

            return sheet;
        }

        private static ViewSheet CreateShopDrawingIndexSheet(
            Document doc,
            ViewFamilyType draftingType,
            TextNoteType textType,
            HashSet<string> viewNames,
            HashSet<string> sheetNumbers,
            ElementId titleBlockTypeId,
            IList<ViewSheet> drawingSheets,
            List<View> createdViews,
            IList<Element> formworkElements,
            IList<Element> rebarElements,
            string issueText,
            string indexSheetPrefix,
            ShopDrawingIssueMetadata metadata)
        {
            if (doc == null || draftingType == null || drawingSheets == null || drawingSheets.Count == 0)
            {
                return null;
            }

            ViewDrafting indexView = null;
            try
            {
                indexView = ViewDrafting.Create(doc, draftingType.Id);
                if (indexView == null)
                {
                    return null;
                }

                indexView.Name = MakeUniqueViewName(viewNames, "MHNK_SHOP_DRAWING_INDEX");
                string packageName = DefaultText(metadata?.PackageName, "SHOP DRAWING PACKAGE");
                string revision = DefaultText(metadata?.Revision, "R0");
                string discipline = DefaultText(metadata?.Discipline, "STRUCTURAL");
                string issueDate = DefaultText(metadata?.IssueDate, DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));
                AddShopDrawingText(doc, indexView, textType, 0.0, 0.8, packageName);
                AddShopDrawingText(doc, indexView, textType, 0.0, 0.45, $"SHOP DRAWING INDEX | {discipline} | Rev: {revision}");
                AddShopDrawingText(doc, indexView, textType, 0.0, 0.23, $"Generated sheets: {drawingSheets.Count} | Issue: {issueText} | Date: {issueDate}");

                double formworkAreaSqM = (formworkElements ?? new List<Element>())
                    .Where(e => e != null)
                    .Sum(e => GetShopDrawingParameterDouble(e, "CBIM.FWK.FaceArea")) * 0.09290304;
                double rebarLengthM = (rebarElements ?? new List<Element>())
                    .Where(e => e != null)
                    .Sum(GetShopDrawingRebarLengthFt) * 0.3048;
                double rebarWeightKg = (rebarElements ?? new List<Element>())
                    .Where(e => e != null)
                    .Sum(e => EstimateShopDrawingRebarWeightKg(doc, e));

                AddShopDrawingText(doc, indexView, textType, 0.0, -0.08, "PACKAGE SUMMARY");
                AddShopDrawingText(doc, indexView, textType, 0.0, -0.32, $"Formwork marks: {(formworkElements?.Count ?? 0)} | Total area: {formworkAreaSqM:0.###} m2");
                AddShopDrawingText(doc, indexView, textType, 0.0, -0.54, $"Rebar marks: {(rebarElements?.Count ?? 0)} | Length: {rebarLengthM:0.###} m | Weight: {rebarWeightKg:0.###} kg");
                AddShopDrawingText(doc, indexView, textType, 0.0, -0.76, $"Prepared: {DefaultText(metadata?.PreparedBy, "-")} | Checked: {DefaultText(metadata?.CheckedBy, "-")} | Approved: {DefaultText(metadata?.ApprovedBy, "-")}");

                double tableBottom = DrawShopDrawingIndexTable(
                    doc,
                    indexView,
                    textType,
                    drawingSheets,
                    x: 0.0,
                    y: -1.08);

                double checklistX = 6.15;
                double checklistY = 0.12;
                AddShopDrawingText(doc, indexView, textType, checklistX, checklistY, "DRAFTSMAN / SITE CHECKLIST");
                string[] checklist =
                {
                    "1. Confirm latest architectural and structural background.",
                    "2. Check level, grid, openings, sleeves, embeds, and construction joints.",
                    "3. Review formwork face tags against site pour sequence.",
                    "4. Review rebar bar marks, laps, hooks, cover, and congestion zones.",
                    "5. Issue only after engineer approval and document revision control."
                };
                checklistY -= 0.25;
                foreach (string item in checklist)
                {
                    AddShopDrawingText(doc, indexView, textType, checklistX, checklistY, item);
                    checklistY -= 0.22;
                }

                AddShopDrawingText(doc, indexView, textType, 0.0, tableBottom - 0.35, "Regenerate with Replace Existing to remove old auto-generated shop drawing sheets/views.");

                createdViews?.Add(indexView);

                ViewSheet indexSheet = CreateShopDrawingSheetForViews(
                    doc,
                    indexView,
                    null,
                    titleBlockTypeId,
                    sheetNumbers,
                    indexSheetPrefix,
                    "SHOP DRAWING INDEX",
                    "PACKAGE",
                    metadata);

                if (indexSheet == null)
                {
                    try
                    {
                        doc.Delete(indexView.Id);
                    }
                    catch
                    {
                    }
                }

                return indexSheet;
            }
            catch
            {
                if (indexView != null && indexView.Id != null && indexView.Id != ElementId.InvalidElementId)
                {
                    try
                    {
                        doc.Delete(indexView.Id);
                    }
                    catch
                    {
                    }
                }

                return null;
            }
        }

        private static List<ShopDrawingSheetSlot> BuildShopDrawingSheetSlots(Document doc, ViewSheet sheet, int viewCount)
        {
            var slots = new List<ShopDrawingSheetSlot>();
            if (sheet == null || viewCount <= 0)
            {
                return slots;
            }

            double minX = -1.65;
            double maxX = 1.65;
            double minY = -1.05;
            double maxY = 1.05;

            try
            {
                BoundingBoxXYZ titleBlockBox = new FilteredElementCollector(doc, sheet.Id)
                    .WhereElementIsNotElementType()
                    .OfCategory(BuiltInCategory.OST_TitleBlocks)
                    .Select(tb => tb.get_BoundingBox(sheet))
                    .FirstOrDefault(bb => bb != null);
                if (titleBlockBox != null)
                {
                    minX = titleBlockBox.Min.X;
                    maxX = titleBlockBox.Max.X;
                    minY = titleBlockBox.Min.Y;
                    maxY = titleBlockBox.Max.Y;
                }
            }
            catch
            {
            }

            double sheetWidth = Math.Max(maxX - minX, 1.0);
            double sheetHeight = Math.Max(maxY - minY, 1.0);
            double rightTitlePanelWidth = Math.Min(sheetWidth * 0.18, MmToFeet(165.0));
            double marginX = Math.Max(MmToFeet(18.0), sheetWidth * 0.025);
            double marginY = Math.Max(MmToFeet(18.0), sheetHeight * 0.035);
            double drawMinX = minX + marginX;
            double drawMaxX = maxX - rightTitlePanelWidth - marginX;
            double drawMinY = minY + marginY;
            double drawMaxY = maxY - marginY;
            double drawWidth = Math.Max(drawMaxX - drawMinX, sheetWidth * 0.55);
            double drawHeight = Math.Max(drawMaxY - drawMinY, sheetHeight * 0.75);

            ShopDrawingSheetSlot MakeSlot(double x, double y, double w, double h)
            {
                return new ShopDrawingSheetSlot
                {
                    Center = new XYZ(x + w * 0.5, y + h * 0.5, 0.0),
                    Width = Math.Max(MmToFeet(80.0), w),
                    Height = Math.Max(MmToFeet(60.0), h)
                };
            }

            if (viewCount == 1)
            {
                slots.Add(MakeSlot(drawMinX, drawMinY, drawWidth, drawHeight));
                return slots;
            }

            if (viewCount == 2)
            {
                double gap = Math.Max(MmToFeet(10.0), drawHeight * 0.035);
                double topHeight = drawHeight * 0.64;
                double bottomHeight = Math.Max(MmToFeet(115.0), drawHeight - topHeight - gap);
                slots.Add(MakeSlot(drawMinX, drawMaxY - topHeight, drawWidth, topHeight));
                slots.Add(MakeSlot(drawMinX, drawMinY, drawWidth, bottomHeight));
                return slots;
            }

            if (viewCount == 5)
            {
                double selectedGapX = Math.Max(MmToFeet(8.0), drawWidth * 0.025);
                double selectedGapY = Math.Max(MmToFeet(8.0), drawHeight * 0.025);
                double dimensionHeight = Math.Min(
                    drawHeight * 0.42,
                    Math.Max(MmToFeet(115.0), drawHeight * 0.34));
                double upperHeight = Math.Max(MmToFeet(120.0), drawHeight - dimensionHeight - selectedGapY);
                double cellHeight = Math.Max(MmToFeet(55.0), (upperHeight - selectedGapY) * 0.5);
                double cellWidth = Math.Max(MmToFeet(75.0), (drawWidth - selectedGapX) * 0.5);
                double topY = drawMaxY - cellHeight;
                double middleY = drawMaxY - (cellHeight * 2.0) - selectedGapY;

                slots.Add(MakeSlot(drawMinX, topY, cellWidth, cellHeight));
                slots.Add(MakeSlot(drawMinX + cellWidth + selectedGapX, topY, cellWidth, cellHeight));
                slots.Add(MakeSlot(drawMinX, middleY, cellWidth, cellHeight));
                slots.Add(MakeSlot(drawMinX + cellWidth + selectedGapX, middleY, cellWidth, cellHeight));
                slots.Add(MakeSlot(drawMinX, drawMinY, drawWidth, dimensionHeight));
                return slots;
            }

            int columns = viewCount <= 3 ? 1 : 2;
            int rows = (int)Math.Ceiling(viewCount / (double)columns);
            double gapX = Math.Max(MmToFeet(8.0), drawWidth * 0.025);
            double gapY = Math.Max(MmToFeet(8.0), drawHeight * 0.025);
            double slotWidth = (drawWidth - gapX * (columns - 1)) / columns;
            double slotHeight = (drawHeight - gapY * (rows - 1)) / rows;

            for (int i = 0; i < viewCount; i++)
            {
                int row = i / columns;
                int col = i % columns;
                double x = drawMinX + col * (slotWidth + gapX);
                double y = drawMaxY - (row + 1) * slotHeight - row * gapY;
                slots.Add(MakeSlot(x, y, slotWidth, slotHeight));
            }

            return slots;
        }

        private static double DrawShopDrawingIndexTable(
            Document doc,
            View view,
            TextNoteType textType,
            IList<ViewSheet> drawingSheets,
            double x,
            double y)
        {
            List<ViewSheet> sheets = (drawingSheets ?? new List<ViewSheet>())
                .Where(s => s != null)
                .OrderBy(s => s.SheetNumber, StringComparer.OrdinalIgnoreCase)
                .ToList();
            int visibleRows = Math.Min(34, sheets.Count);
            string[] headers = { "Sheet No.", "Sheet Name", "Rev", "Status" };
            double[] widths = { 1.35, 4.35, 0.65, 1.35 };
            double rowHeight = 0.24;
            double headerY = y;
            double tableWidth = widths.Sum();
            double tableBottom = headerY - ((visibleRows + 1) * rowHeight) - 0.04;

            AddShopDrawingText(doc, view, textType, x, headerY + 0.22, "DRAWING LIST");
            AddShopDrawingRectangle(doc, view, x - 0.05, headerY + 0.12, x + tableWidth + 0.05, tableBottom);

            double colX = x;
            for (int i = 0; i < headers.Length; i++)
            {
                AddShopDrawingText(doc, view, textType, colX, headerY, headers[i]);
                if (i > 0)
                {
                    AddShopDrawingLine(doc, view, colX - 0.05, headerY + 0.12, colX - 0.05, tableBottom);
                }

                colX += widths[i];
            }

            AddShopDrawingLine(doc, view, x - 0.05, headerY - 0.08, x + tableWidth + 0.05, headerY - 0.08);

            double rowY = headerY - rowHeight;
            for (int i = 0; i < visibleRows; i++)
            {
                ViewSheet sheet = sheets[i];
                string revision = GetSheetTextParameter(sheet, "Revision", "Rev", "Current Revision", "Revision Number");
                string status = GetSheetTextParameter(sheet, "Issue", "Issue Status", "Status", "Project Status");
                string[] values =
                {
                    sheet.SheetNumber ?? "",
                    TruncateShopDrawingCell(sheet.Name ?? "", 44),
                    TruncateShopDrawingCell(DefaultText(revision, "-"), 8),
                    TruncateShopDrawingCell(DefaultText(status, "-"), 18)
                };

                colX = x;
                for (int col = 0; col < values.Length; col++)
                {
                    AddShopDrawingText(doc, view, textType, colX, rowY, values[col]);
                    colX += widths[col];
                }

                AddShopDrawingLine(doc, view, x - 0.05, rowY - 0.08, x + tableWidth + 0.05, rowY - 0.08);
                rowY -= rowHeight;
            }

            if (sheets.Count > visibleRows)
            {
                AddShopDrawingText(doc, view, textType, x, tableBottom - 0.22, $"Showing first {visibleRows} of {sheets.Count} sheet(s).");
                return tableBottom - 0.22;
            }

            return tableBottom;
        }

        private static string GetSheetTextParameter(Element element, params string[] parameterNames)
        {
            foreach (string name in parameterNames ?? Array.Empty<string>())
            {
                try
                {
                    Parameter parameter = element?.LookupParameter(name);
                    if (parameter?.StorageType == StorageType.String)
                    {
                        string value = parameter.AsString();
                        if (!string.IsNullOrWhiteSpace(value))
                        {
                            return value.Trim();
                        }
                    }
                }
                catch
                {
                }
            }

            return "";
        }

        private static Viewport PlaceShopDrawingViewportFitted(
            Document doc,
            ViewSheet sheet,
            View view,
            ShopDrawingSheetSlot slot,
            int preferredScale,
            string titleOnSheet = null,
            string detailNumber = null)
        {
            if (doc == null || sheet == null || view == null || slot == null)
            {
                return null;
            }

            try
            {
                if (!Viewport.CanAddViewToSheet(doc, sheet.Id, view.Id))
                {
                    return null;
                }

                ApplyShopDrawingViewTitle(view, titleOnSheet);
                TrySetShopDrawingViewScale(view, preferredScale);
                Viewport viewport = Viewport.Create(doc, sheet.Id, view.Id, slot.Center);
                ApplyShopDrawingViewportLabel(viewport, view, slot, titleOnSheet, detailNumber);
                FitShopDrawingViewportToSlot(doc, view, viewport, slot);
                ApplyShopDrawingViewportLabel(viewport, view, slot, titleOnSheet, detailNumber);
                return viewport;
            }
            catch
            {
                return null;
            }
        }

        private static void FitShopDrawingViewportToSlot(Document doc, View view, Viewport viewport, ShopDrawingSheetSlot slot)
        {
            if (doc == null || view == null || viewport == null || slot == null)
            {
                return;
            }

            double maxWidth = Math.Max(MmToFeet(40.0), slot.Width * 0.95);
            double maxHeight = Math.Max(MmToFeet(35.0), slot.Height * 0.90);

            for (int i = 0; i < 5; i++)
            {
                try
                {
                    doc.Regenerate();
                    viewport.SetBoxCenter(slot.Center);
                    Outline outline = viewport.GetBoxOutline();
                    if (outline == null)
                    {
                        return;
                    }

                    double width = Math.Abs(outline.MaximumPoint.X - outline.MinimumPoint.X);
                    double height = Math.Abs(outline.MaximumPoint.Y - outline.MinimumPoint.Y);
                    if (width <= maxWidth && height <= maxHeight)
                    {
                        return;
                    }

                    double factor = Math.Max(width / maxWidth, height / maxHeight);
                    int currentScale = Math.Max(1, view.Scale);
                    int targetScale = NormalizeShopDrawingViewScale((int)Math.Ceiling(currentScale * factor * 1.12));
                    if (targetScale <= currentScale)
                    {
                        targetScale = currentScale + 1;
                    }

                    if (!TrySetShopDrawingViewScale(view, targetScale))
                    {
                        return;
                    }
                }
                catch
                {
                    return;
                }
            }

            try
            {
                doc.Regenerate();
                viewport.SetBoxCenter(slot.Center);
            }
            catch
            {
            }
        }

        private static void ApplyShopDrawingViewTitle(View view, string titleOnSheet)
        {
            if (view == null || string.IsNullOrWhiteSpace(titleOnSheet))
            {
                return;
            }

            string title = NormalizeShopDrawingViewportText(titleOnSheet, 32);
            TrySetShopDrawingTextParameter(view, title, "Title on Sheet", "View Title", "Drawing Title");
        }

        private static void ApplyShopDrawingViewportLabel(
            Viewport viewport,
            View view,
            ShopDrawingSheetSlot slot,
            string titleOnSheet,
            string detailNumber)
        {
            if (viewport == null)
            {
                return;
            }

            string title = NormalizeShopDrawingViewportText(titleOnSheet, 32);
            string number = NormalizeShopDrawingViewportText(detailNumber, 8);
            if (!string.IsNullOrWhiteSpace(title))
            {
                ApplyShopDrawingViewTitle(view, title);
                TrySetShopDrawingTextParameter(viewport, title, "Title on Sheet", "View Title", "View Name");
            }

            if (!string.IsNullOrWhiteSpace(number))
            {
                TrySetShopDrawingTextParameter(viewport, number, "Detail Number", "Detail No.", "View Number");
            }

            TryTidyShopDrawingViewportLabel(viewport, slot);
        }

        private static string NormalizeShopDrawingViewportText(string value, int maxLength)
        {
            string text = Regex.Replace(value ?? "", @"\s+", " ").Trim();
            return TruncateShopDrawingCell(text, maxLength);
        }

        private static void TryTidyShopDrawingViewportLabel(Viewport viewport, ShopDrawingSheetSlot slot)
        {
            if (viewport == null || slot == null)
            {
                return;
            }

            try
            {
                PropertyInfo lineLengthProperty = viewport.GetType().GetProperty("LabelLineLength");
                if (lineLengthProperty != null && lineLengthProperty.CanWrite)
                {
                    double lineLength = Math.Max(MmToFeet(35.0), Math.Min(MmToFeet(90.0), slot.Width * 0.28));
                    lineLengthProperty.SetValue(viewport, lineLength, null);
                }
            }
            catch
            {
            }
        }

        private static bool TrySetShopDrawingViewScale(View view, int scale)
        {
            if (view == null)
            {
                return false;
            }

            try
            {
                view.Scale = NormalizeShopDrawingViewScale(scale);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static int NormalizeShopDrawingViewScale(int requiredScale)
        {
            int scale = Math.Max(1, Math.Min(5000, requiredScale));
            int[] commonScales =
            {
                1, 2, 5, 10, 20, 25, 50, 75, 100, 150, 200, 250, 500, 750, 1000, 1500, 2000, 2500, 5000
            };

            foreach (int candidate in commonScales)
            {
                if (candidate >= scale)
                {
                    return candidate;
                }
            }

            return scale;
        }

        private ElementId GetShopDrawingTitleBlockTypeId(Document doc)
        {
            if (doc == null)
            {
                return ElementId.InvalidElementId;
            }

            if (Request.ShopDrawingsTitleBlockTypeId != null &&
                Request.ShopDrawingsTitleBlockTypeId != ElementId.InvalidElementId &&
                doc.GetElement(Request.ShopDrawingsTitleBlockTypeId) != null)
            {
                return Request.ShopDrawingsTitleBlockTypeId;
            }

            Element titleBlockType = new FilteredElementCollector(doc)
                .OfCategory(BuiltInCategory.OST_TitleBlocks)
                .WhereElementIsElementType()
                .FirstElement();

            return titleBlockType?.Id ?? ElementId.InvalidElementId;
        }

        private static string NormalizeShopDrawingIssueText(string value)
        {
            string text = DefaultText(value, "FOR CONSTRUCTION REVIEW");
            text = Regex.Replace(text, @"\s+", " ");
            if (text.Length > 64)
            {
                text = text.Substring(0, 64);
            }

            return string.IsNullOrWhiteSpace(text) ? "FOR CONSTRUCTION REVIEW" : text;
        }

        private static ShopDrawingIssueMetadata BuildShopDrawingIssueMetadata(CadToModelRequest request, string issueText)
        {
            return new ShopDrawingIssueMetadata
            {
                PackageName = NormalizeShopDrawingMetadataText(request?.ShopDrawingsPackageName, "SHOP DRAWING PACKAGE", 80),
                Discipline = NormalizeShopDrawingMetadataText(request?.ShopDrawingsDiscipline, "STRUCTURAL", 40),
                IssueText = NormalizeShopDrawingMetadataText(issueText, "FOR CONSTRUCTION REVIEW", 64),
                Revision = NormalizeShopDrawingMetadataText(request?.ShopDrawingsRevision, "R0", 16),
                PreparedBy = NormalizeShopDrawingMetadataText(request?.ShopDrawingsPreparedBy, "", 40),
                CheckedBy = NormalizeShopDrawingMetadataText(request?.ShopDrawingsCheckedBy, "", 40),
                ApprovedBy = NormalizeShopDrawingMetadataText(request?.ShopDrawingsApprovedBy, "", 40),
                IssueDate = DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)
            };
        }

        private static string NormalizeShopDrawingMetadataText(string value, string fallback, int maxLength)
        {
            string text = DefaultText(value, fallback);
            text = Regex.Replace(text, @"\s+", " ").Trim();
            if (maxLength > 0 && text.Length > maxLength)
            {
                text = text.Substring(0, maxLength);
            }

            return string.IsNullOrWhiteSpace(text) ? (fallback ?? "") : text;
        }

        private static void ApplyShopDrawingSheetMetadata(
            Document doc,
            ViewSheet sheet,
            ShopDrawingIssueMetadata metadata,
            string drawingTitle,
            string groupName)
        {
            if (doc == null || sheet == null)
            {
                return;
            }

            ShopDrawingIssueMetadata data = metadata ?? BuildShopDrawingIssueMetadata(null, "FOR CONSTRUCTION REVIEW");
            string sheetTitle = DefaultText(sheet.Name, $"{drawingTitle} - {groupName}");
            ApplyShopDrawingMetadataToElement(sheet, data, sheetTitle);

            try
            {
                foreach (Element titleBlock in new FilteredElementCollector(doc, sheet.Id)
                    .WhereElementIsNotElementType()
                    .OfCategory(BuiltInCategory.OST_TitleBlocks)
                    .ToElements())
                {
                    ApplyShopDrawingMetadataToElement(titleBlock, data, sheetTitle);
                }
            }
            catch
            {
            }
        }

        private static void ApplyShopDrawingMetadataToElement(
            Element element,
            ShopDrawingIssueMetadata metadata,
            string sheetTitle)
        {
            if (element == null || metadata == null)
            {
                return;
            }

            TrySetShopDrawingTextParameter(element, metadata.PackageName, "Package", "Package Name", "Drawing Package", "Shop Drawing Package");
            TrySetShopDrawingTextParameter(element, metadata.Discipline, "Discipline", "Drawing Discipline");
            TrySetShopDrawingTextParameter(element, metadata.IssueText, "Issue", "Issue Status", "Status", "Project Status");
            TrySetShopDrawingTextParameter(element, metadata.Revision, "Revision", "Rev", "Current Revision", "Revision Number");
            TrySetShopDrawingTextParameter(element, metadata.IssueDate, "Date", "Issue Date", "Sheet Issue Date", "Drawn Date");
            TrySetShopDrawingTextParameter(element, metadata.PreparedBy, "Prepared By", "Drawn By", "Designed By", "Created By");
            TrySetShopDrawingTextParameter(element, metadata.CheckedBy, "Checked By", "Check By");
            TrySetShopDrawingTextParameter(element, metadata.ApprovedBy, "Approved By", "Approval By");
            string safeSheetTitle = TruncateShopDrawingCell(
                Regex.Replace(sheetTitle ?? "", @"\s+", " ").Trim(),
                44);
            TrySetShopDrawingTextParameter(element, safeSheetTitle, "Sheet Title", "Drawing Title", "Title");
        }

        private static bool TrySetShopDrawingTextParameter(Element element, string value, params string[] parameterNames)
        {
            string text = value ?? "";
            if (element == null || parameterNames == null || string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            bool changed = false;
            foreach (string name in parameterNames)
            {
                if (string.IsNullOrWhiteSpace(name))
                {
                    continue;
                }

                try
                {
                    Parameter parameter = element.LookupParameter(name);
                    if (parameter == null || parameter.IsReadOnly || parameter.StorageType != StorageType.String)
                    {
                        continue;
                    }

                    string current = parameter.AsString() ?? "";
                    if (!string.Equals(current, text, StringComparison.Ordinal))
                    {
                        parameter.Set(text);
                        changed = true;
                    }
                }
                catch
                {
                }
            }

            return changed;
        }

        private static string NormalizeShopDrawingSheetPrefix(string value, string fallback)
        {
            string text = DefaultText(value, fallback).ToUpperInvariant();
            text = Regex.Replace(text, @"[^A-Z0-9_-]+", "-").Trim('-', '_');
            if (text.Length > 32)
            {
                text = text.Substring(0, 32).Trim('-', '_');
            }

            return string.IsNullOrWhiteSpace(text) ? fallback : text;
        }

        private static string MakeUniqueSheetNumber(HashSet<string> existingNumbers, string sheetPrefix)
        {
            string prefix = string.IsNullOrWhiteSpace(sheetPrefix) ? "MHNK-SD" : sheetPrefix.Trim();
            int index = 1;
            string number;
            do
            {
                number = $"{prefix}-{index:000}";
                index++;
            }
            while (existingNumbers != null && existingNumbers.Contains(number));

            existingNumbers?.Add(number);
            return number;
        }

        private List<Element> CollectShopDrawingFormworkElements(UIDocument uidoc, Document doc, QsScope scope)
        {
            List<Element> candidates = CollectShopDrawingCategoryElements(doc, BuiltInCategory.OST_SpecialityEquipment, scope)
                .Where(IsShopDrawingFormworkShape)
                .ToList();

            return FilterShopDrawingSelectionScope(uidoc, doc, candidates, scope, isFormwork: true);
        }

        private List<Element> CollectShopDrawingRebarElements(UIDocument uidoc, Document doc, QsScope scope)
        {
            List<Element> candidates = CollectShopDrawingCategoryElements(doc, BuiltInCategory.OST_Rebar, scope)
                .ToList();

            return FilterShopDrawingSelectionScope(uidoc, doc, candidates, scope, isFormwork: false);
        }

        private static List<Element> CollectShopDrawingCategoryElements(Document doc, BuiltInCategory category, QsScope scope)
        {
            if (doc == null)
            {
                return new List<Element>();
            }

            try
            {
                if (scope == QsScope.CurrentView &&
                    doc.ActiveView != null &&
                    !doc.ActiveView.IsTemplate &&
                    doc.ActiveView.Id != ElementId.InvalidElementId)
                {
                    return new FilteredElementCollector(doc, doc.ActiveView.Id)
                        .WhereElementIsNotElementType()
                        .OfCategory(category)
                        .ToElements()
                        .ToList();
                }
            }
            catch
            {
            }

            return new FilteredElementCollector(doc)
                .WhereElementIsNotElementType()
                .OfCategory(category)
                .ToElements()
                .ToList();
        }

        private static List<Element> FilterShopDrawingSelectionScope(
            UIDocument uidoc,
            Document doc,
            IList<Element> candidates,
            QsScope scope,
            bool isFormwork)
        {
            if (scope != QsScope.CurrentSelection)
            {
                return (candidates ?? new List<Element>()).Where(x => x != null).ToList();
            }

            var selectedIds = new HashSet<long>();
            try
            {
                foreach (ElementId id in uidoc?.Selection?.GetElementIds() ?? new List<ElementId>())
                {
                    if (id != null && id != ElementId.InvalidElementId)
                    {
                        selectedIds.Add(id.Value);
                    }
                }
            }
            catch
            {
            }

            if (selectedIds.Count == 0)
            {
                return new List<Element>();
            }

            return (candidates ?? new List<Element>())
                .Where(e =>
                {
                    if (e == null || e.Id == null || e.Id == ElementId.InvalidElementId)
                    {
                        return false;
                    }

                    if (selectedIds.Contains(e.Id.Value))
                    {
                        return true;
                    }

                    long hostId = isFormwork
                        ? TryGetFormworkHostIdValue(e)
                        : TryGetHostedRebarHostId(e)?.Value ?? -1L;
                    return selectedIds.Contains(hostId);
                })
                .ToList();
        }

        private static bool IsShopDrawingFormworkShape(Element element)
        {
            if (element == null)
            {
                return false;
            }

            Parameter flag = element.LookupParameter("CBIM.FWK.IsShape");
            if (flag != null)
            {
                try
                {
                    if (flag.StorageType == StorageType.Integer && flag.AsInteger() != 0)
                    {
                        return true;
                    }
                }
                catch
                {
                }
            }

            string marker = GetShopDrawingParameterString(element, "CBIM.FormworkShape");
            if (!string.IsNullOrWhiteSpace(marker))
            {
                return true;
            }

            string name = element.Name ?? "";
            return name.StartsWith("CBIM_FWK_", StringComparison.OrdinalIgnoreCase);
        }

        private static long TryGetFormworkHostIdValue(Element element)
        {
            string text = GetShopDrawingParameterString(element, "CBIM.FWK.ElementId");
            if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out long id))
            {
                return id;
            }

            return -1L;
        }

        private static string GetShopDrawingElementLevelName(Document doc, Element element)
        {
            if (element == null)
            {
                return "";
            }

            string formworkLevel = GetShopDrawingParameterString(element, "CBIM.FWK.Level");
            if (!string.IsNullOrWhiteSpace(formworkLevel))
            {
                return formworkLevel;
            }

            ElementId rebarHostId = TryGetHostedRebarHostId(element);
            if (rebarHostId != null && rebarHostId != ElementId.InvalidElementId && doc?.GetElement(rebarHostId) is Element host)
            {
                string hostLevel = TryGetElementLevelName(doc, host);
                if (!string.IsNullOrWhiteSpace(hostLevel))
                {
                    return hostLevel;
                }
            }

            return TryGetElementLevelName(doc, element);
        }

        private static string GetShopDrawingElementCategoryLabel(Document doc, Element element, bool isFormwork)
        {
            if (isFormwork)
            {
                return DefaultText(
                    GetShopDrawingParameterString(element, "CBIM.FWK.Category"),
                    element?.Category?.Name ?? "Formwork");
            }

            ElementId hostId = TryGetHostedRebarHostId(element);
            Element host = hostId != null && hostId != ElementId.InvalidElementId
                ? doc?.GetElement(hostId)
                : null;
            return DefaultText(host?.Category?.Name, element?.Category?.Name ?? "Rebar");
        }

        private static string GetShopDrawingElementHostGroupLabel(Document doc, Element element, bool isFormwork)
        {
            if (isFormwork)
            {
                long hostIdValue = TryGetFormworkHostIdValue(element);
                if (hostIdValue > 0)
                {
                    Element host = null;
                    try
                    {
                        host = doc?.GetElement(new ElementId(hostIdValue));
                    }
                    catch
                    {
                    }

                    string hostCategory = DefaultText(host?.Category?.Name, "Host");
                    return $"{hostCategory} {hostIdValue}";
                }

                return "No Host";
            }

            ElementId hostId = TryGetHostedRebarHostId(element);
            if (hostId != null && hostId != ElementId.InvalidElementId)
            {
                Element host = doc?.GetElement(hostId);
                string hostCategory = DefaultText(host?.Category?.Name, "Host");
                return $"{hostCategory} {hostId.Value}";
            }

            return "No Host";
        }

        private static bool TryGetShopDrawingModelBounds(
            IList<Element> elements,
            out double minX,
            out double minY,
            out double maxX,
            out double maxY)
        {
            minX = double.MaxValue;
            minY = double.MaxValue;
            maxX = double.MinValue;
            maxY = double.MinValue;
            bool hasBounds = false;

            foreach (Element element in elements ?? new List<Element>())
            {
                BoundingBoxXYZ bb = element?.get_BoundingBox(null);
                if (bb == null)
                {
                    continue;
                }

                minX = Math.Min(minX, bb.Min.X);
                minY = Math.Min(minY, bb.Min.Y);
                maxX = Math.Max(maxX, bb.Max.X);
                maxY = Math.Max(maxY, bb.Max.Y);
                hasBounds = true;
            }

            return hasBounds && maxX > minX - 1e-9 && maxY > minY - 1e-9;
        }

        private static bool TryGetShopDrawingModelBounds3D(IList<Element> elements, out XYZ min, out XYZ max)
        {
            double minX = double.MaxValue;
            double minY = double.MaxValue;
            double minZ = double.MaxValue;
            double maxX = double.MinValue;
            double maxY = double.MinValue;
            double maxZ = double.MinValue;
            bool hasBounds = false;

            foreach (Element element in elements ?? new List<Element>())
            {
                BoundingBoxXYZ bb = element?.get_BoundingBox(null);
                if (bb == null)
                {
                    continue;
                }

                minX = Math.Min(minX, bb.Min.X);
                minY = Math.Min(minY, bb.Min.Y);
                minZ = Math.Min(minZ, bb.Min.Z);
                maxX = Math.Max(maxX, bb.Max.X);
                maxY = Math.Max(maxY, bb.Max.Y);
                maxZ = Math.Max(maxZ, bb.Max.Z);
                hasBounds = true;
            }

            if (!hasBounds)
            {
                min = XYZ.Zero;
                max = XYZ.Zero;
                return false;
            }

            min = new XYZ(minX, minY, minZ);
            max = new XYZ(maxX, maxY, maxZ);
            return maxX > minX - 1e-9 && maxY > minY - 1e-9 && maxZ > minZ - 1e-9;
        }

        private static void AddShopDrawingRectangle(Document doc, View view, double x0, double y0, double x1, double y1)
        {
            double left = Math.Min(x0, x1);
            double right = Math.Max(x0, x1);
            double bottom = Math.Min(y0, y1);
            double top = Math.Max(y0, y1);

            AddShopDrawingLine(doc, view, left, top, right, top);
            AddShopDrawingLine(doc, view, right, top, right, bottom);
            AddShopDrawingLine(doc, view, right, bottom, left, bottom);
            AddShopDrawingLine(doc, view, left, bottom, left, top);
        }

        private static void AddShopDrawingLine(Document doc, View view, double x0, double y0, double x1, double y1)
        {
            if (doc == null || view == null)
            {
                return;
            }

            XYZ p0 = new XYZ(x0, y0, 0.0);
            XYZ p1 = new XYZ(x1, y1, 0.0);
            if (p0.DistanceTo(p1) < 1e-6)
            {
                return;
            }

            try
            {
                doc.Create.NewDetailCurve(view, Line.CreateBound(p0, p1));
            }
            catch
            {
            }
        }

        private static void AddShopDrawingText(Document doc, View view, TextNoteType textType, double x, double y, string text)
        {
            if (doc == null || view == null || textType == null || string.IsNullOrWhiteSpace(text))
            {
                return;
            }

            try
            {
                TextNote.Create(doc, view.Id, new XYZ(x, y, 0.0), text, textType.Id);
            }
            catch
            {
            }
        }

        private static void AddShopDrawingLayoutDimensionNotes(
            Document doc,
            View view,
            TextNoteType textType,
            double left,
            double top,
            double drawingWidth,
            double drawingHeight,
            double modelWidthFt,
            double modelHeightFt)
        {
            double right = left + drawingWidth;
            double bottom = top - drawingHeight;
            double dimOffset = 0.28;
            double tick = 0.08;

            double dimY = bottom - dimOffset;
            AddShopDrawingLine(doc, view, left, dimY, right, dimY);
            AddShopDrawingLine(doc, view, left, dimY - tick, left, dimY + tick);
            AddShopDrawingLine(doc, view, right, dimY - tick, right, dimY + tick);
            AddShopDrawingText(doc, view, textType, (left + right) * 0.5 - 0.45, dimY - 0.12, $"L={modelWidthFt * 0.3048:0.###} m");

            double dimX = left - dimOffset;
            AddShopDrawingLine(doc, view, dimX, top, dimX, bottom);
            AddShopDrawingLine(doc, view, dimX - tick, top, dimX + tick, top);
            AddShopDrawingLine(doc, view, dimX - tick, bottom, dimX + tick, bottom);
            AddShopDrawingText(doc, view, textType, dimX - 0.15, (top + bottom) * 0.5, $"W={modelHeightFt * 0.3048:0.###} m");

            AddShopDrawingLine(doc, view, right - 0.35, top - 0.25, right - 0.35, top - 0.65);
            AddShopDrawingLine(doc, view, right - 0.35, top - 0.25, right - 0.48, top - 0.42);
            AddShopDrawingLine(doc, view, right - 0.35, top - 0.25, right - 0.22, top - 0.42);
            AddShopDrawingText(doc, view, textType, right - 0.43, top - 0.2, "N");
        }

        private static void AddShopDrawingConstructionNotes(
            Document doc,
            View view,
            TextNoteType textType,
            bool isFormwork,
            double x,
            double y)
        {
            string title = isFormwork ? "FORMWORK SITE NOTES" : "REBAR SITE NOTES";
            AddShopDrawingText(doc, view, textType, x, y, title);
            string[] notes = isFormwork
                ? new[]
                {
                    "1. Verify dimensions, openings, and construction joints on site before fabrication.",
                    "2. Coordinate formwork faces with QS CBIM.FWK face types and host element IDs.",
                    "3. Keep edge props, ties, and access platforms clear of embedded items and rebar congestion.",
                    "4. Any mismatch between model and site condition must be returned to the draftsman/engineer."
                }
                : new[]
                {
                    "1. Bar marks are generated from Revit rebar elements; verify against approved structural drawings.",
                    "2. Length and weight are computed from available Revit parameters with fallback from model extents.",
                    "3. Confirm cover, laps, hooks, starter bars, and splice locations before cutting or fixing.",
                    "4. Any site change must be recorded before installation and as-built update."
                };

            double rowY = y - 0.24;
            foreach (string note in notes)
            {
                AddShopDrawingText(doc, view, textType, x, rowY, note);
                rowY -= 0.22;
            }
        }

        private static void DrawShopDrawingScheduleTable(
            Document doc,
            View view,
            TextNoteType textType,
            IList<Element> elements,
            bool isFormwork,
            int maxRows,
            double x,
            double y)
        {
            int rowLimit = Math.Max(1, Math.Min(200, maxRows));
            List<string[]> rows = isFormwork
                ? BuildFormworkShopDrawingRows(elements, rowLimit)
                : BuildRebarShopDrawingRows(doc, elements, rowLimit);
            string[] headers = isFormwork
                ? new[] { "Mark", "Host", "Category", "Face", "Area", "Element" }
                : new[] { "Mark", "Host", "Bar Type", "Dia", "Qty", "Length", "Weight" };
            double[] widths = isFormwork
                ? new[] { 0.65, 0.9, 1.3, 0.9, 0.8, 0.9 }
                : new[] { 0.65, 1.0, 1.55, 0.6, 0.5, 0.8, 0.85 };

            string title = isFormwork ? "FORMWORK MARK SCHEDULE" : "REBAR BAR MARK SCHEDULE";
            AddShopDrawingText(doc, view, textType, x, y, title);

            double headerY = y - 0.28;
            double rowHeight = 0.22;
            double tableWidth = widths.Sum();
            double tableBottom = headerY - ((rows.Count + 1) * rowHeight);
            AddShopDrawingRectangle(doc, view, x - 0.05, headerY + 0.12, x + tableWidth + 0.05, tableBottom - 0.02);

            double colX = x;
            for (int i = 0; i < headers.Length; i++)
            {
                AddShopDrawingText(doc, view, textType, colX, headerY, headers[i]);
                if (i > 0)
                {
                    AddShopDrawingLine(doc, view, colX - 0.05, headerY + 0.12, colX - 0.05, tableBottom - 0.02);
                }
                colX += widths[i];
            }

            AddShopDrawingLine(doc, view, x - 0.05, headerY - 0.08, x + tableWidth + 0.05, headerY - 0.08);

            double rowY = headerY - rowHeight;
            foreach (string[] row in rows)
            {
                colX = x;
                for (int i = 0; i < headers.Length && i < row.Length; i++)
                {
                    AddShopDrawingText(doc, view, textType, colX, rowY, TruncateShopDrawingCell(row[i], i == 2 ? 20 : 14));
                    colX += widths[i];
                }

                rowY -= rowHeight;
            }

            if ((elements?.Count ?? 0) > rows.Count)
            {
                AddShopDrawingText(doc, view, textType, x, tableBottom - 0.25, $"Showing first {rows.Count} of {elements.Count} item(s).");
            }
        }

        private static string BuildShopDrawingElementTag(Element element, int index, bool isFormwork)
        {
            string prefix = isFormwork ? "FW" : "RB";
            if (element?.Id == null || element.Id == ElementId.InvalidElementId)
            {
                return $"{prefix}-{index:000}";
            }

            return $"{prefix}-{index:000}";
        }

        private static List<string[]> BuildFormworkShopDrawingRows(IList<Element> elements, int maxRows)
        {
            return (elements ?? new List<Element>())
                .Where(e => e != null)
                .OrderBy(e => e.Id?.Value ?? 0)
                .Take(Math.Max(1, maxRows))
                .Select((e, i) =>
                {
                    string host = TryGetFormworkHostIdValue(e) > 0
                        ? TryGetFormworkHostIdValue(e).ToString(CultureInfo.InvariantCulture)
                        : "-";
                    string category = DefaultText(GetShopDrawingParameterString(e, "CBIM.FWK.Category"), e.Category?.Name ?? "Formwork");
                    string face = DefaultText(GetShopDrawingParameterString(e, "CBIM.FWK.FaceType"), "-");
                    double areaSqM = GetShopDrawingParameterDouble(e, "CBIM.FWK.FaceArea") * 0.09290304;
                    string elementId = e.Id == null || e.Id == ElementId.InvalidElementId
                        ? "-"
                        : e.Id.Value.ToString(CultureInfo.InvariantCulture);
                    return new[]
                    {
                        $"FW-{i + 1:000}",
                        host,
                        category,
                        face,
                        $"{areaSqM:0.###} m2",
                        elementId
                    };
                })
                .ToList();
        }

        private static List<string[]> BuildRebarShopDrawingRows(Document doc, IList<Element> elements, int maxRows)
        {
            return (elements ?? new List<Element>())
                .Where(e => e != null)
                .OrderBy(e => e.Id?.Value ?? 0)
                .Take(Math.Max(1, maxRows))
                .Select((e, i) =>
                {
                    double diameterMm = GetShopDrawingRebarDiameterMm(doc, e);
                    double qty = GetShopDrawingRebarQuantity(e);
                    double lengthM = GetShopDrawingRebarLengthFt(e) * 0.3048;
                    double weightKg = EstimateShopDrawingRebarWeightKg(doc, e);
                    return new[]
                    {
                        $"RB-{i + 1:000}",
                        TruncateShopDrawingCell(GetShopDrawingRebarHostLabel(doc, e), 14),
                        GetShopDrawingElementTypeName(doc, e),
                        diameterMm > 1e-9 ? $"D{diameterMm:0.#}" : "-",
                        $"{qty:0.##}",
                        $"{lengthM:0.###} m",
                        $"{weightKg:0.###} kg"
                    };
                })
                .ToList();
        }

        private static string TruncateShopDrawingCell(string value, int maxLength)
        {
            string text = value ?? "";
            if (maxLength <= 3 || text.Length <= maxLength)
            {
                return text;
            }

            return text.Substring(0, maxLength - 3) + "...";
        }

        private static string BuildFormworkShopDrawingSummary(IList<Element> elements)
        {
            var rows = (elements ?? new List<Element>())
                .Where(e => e != null)
                .GroupBy(e => new
                {
                    Category = DefaultText(GetShopDrawingParameterString(e, "CBIM.FWK.Category"), e.Category?.Name ?? "Formwork"),
                    Face = DefaultText(GetShopDrawingParameterString(e, "CBIM.FWK.FaceType"), "Face")
                })
                .OrderBy(g => g.Key.Category, StringComparer.OrdinalIgnoreCase)
                .ThenBy(g => g.Key.Face, StringComparer.OrdinalIgnoreCase)
                .Take(24)
                .Select(g =>
                {
                    double areaSqM = g.Sum(e => GetShopDrawingParameterDouble(e, "CBIM.FWK.FaceArea")) * 0.09290304;
                    return $"{g.Key.Category} | {g.Key.Face} | {g.Count()} pc | {areaSqM:0.###} m2";
                })
                .ToList();

            if (rows.Count == 0)
            {
                return "FORMWORK SUMMARY\nNo formwork parameter rows available.";
            }

            return "FORMWORK SUMMARY\nCategory | Face | Count | Area\n" + string.Join("\n", rows);
        }

        private static string BuildRebarShopDrawingSummary(Document doc, IList<Element> elements)
        {
            var rows = (elements ?? new List<Element>())
                .Where(e => e != null)
                .GroupBy(e => new
                {
                    TypeName = GetShopDrawingElementTypeName(doc, e),
                    Host = GetShopDrawingRebarHostLabel(doc, e)
                })
                .OrderBy(g => g.Key.Host, StringComparer.OrdinalIgnoreCase)
                .ThenBy(g => g.Key.TypeName, StringComparer.OrdinalIgnoreCase)
                .Take(24)
                .Select(g =>
                {
                    double totalLengthM = g.Sum(GetShopDrawingRebarLengthFt) * 0.3048;
                    double weightKg = g.Sum(e => EstimateShopDrawingRebarWeightKg(doc, e));
                    return $"{g.Key.Host} | {g.Key.TypeName} | {g.Count()} set | {totalLengthM:0.###} m | {weightKg:0.###} kg";
                })
                .ToList();

            if (rows.Count == 0)
            {
                return "REBAR SUMMARY\nNo rebar parameter rows available.";
            }

            return "REBAR SUMMARY\nHost | Bar Type | Sets | Length | Weight\n" + string.Join("\n", rows);
        }

        private static string GetShopDrawingRebarHostLabel(Document doc, Element rebar)
        {
            ElementId hostId = TryGetHostedRebarHostId(rebar);
            Element host = hostId != null && hostId != ElementId.InvalidElementId ? doc?.GetElement(hostId) : null;
            string category = host?.Category?.Name;
            if (!string.IsNullOrWhiteSpace(category))
            {
                return category;
            }

            return "Host";
        }

        private static string GetShopDrawingElementTypeName(Document doc, Element element)
        {
            if (element == null)
            {
                return "Type";
            }

            try
            {
                Element type = doc?.GetElement(element.GetTypeId());
                if (!string.IsNullOrWhiteSpace(type?.Name))
                {
                    return type.Name;
                }
            }
            catch
            {
            }

            return string.IsNullOrWhiteSpace(element.Name) ? "Type" : element.Name;
        }

        private static double GetShopDrawingRebarLengthFt(Element rebar)
        {
            double total = GetShopDrawingFirstDouble(rebar, "Total Bar Length", "Total Length", "Bar Total Length", "Overall Length");
            if (total > 1e-9)
            {
                return total;
            }

            double single = GetShopDrawingFirstDouble(rebar, "Bar Length", "Length");
            if (single <= 1e-9)
            {
                BoundingBoxXYZ bb = rebar?.get_BoundingBox(null);
                if (bb != null)
                {
                    single = Math.Max(Math.Max(bb.Max.X - bb.Min.X, bb.Max.Y - bb.Min.Y), bb.Max.Z - bb.Min.Z);
                }
            }

            return Math.Max(0.0, single) * Math.Max(1.0, GetShopDrawingRebarQuantity(rebar));
        }

        private static double GetShopDrawingRebarQuantity(Element rebar)
        {
            double quantity = GetShopDrawingFirstDouble(rebar, "Quantity", "Number of Bars", "Bar Quantity", "Bars");
            return quantity > 1e-9 ? quantity : 1.0;
        }

        private static double EstimateShopDrawingRebarWeightKg(Document doc, Element rebar)
        {
            double lengthM = GetShopDrawingRebarLengthFt(rebar) * 0.3048;
            if (lengthM <= 1e-9)
            {
                return 0.0;
            }

            double diameterFt = GetShopDrawingFirstDouble(rebar, "Bar Diameter", "Diameter", "Model Bar Diameter", "Nominal Diameter");
            if (diameterFt <= 1e-9)
            {
                try
                {
                    Element type = doc?.GetElement(rebar.GetTypeId());
                    diameterFt = GetShopDrawingFirstDouble(type, "Bar Diameter", "Diameter", "Model Bar Diameter", "Nominal Diameter");
                }
                catch
                {
                }
            }

            double diameterMm = FeetToMm(diameterFt);
            if (diameterMm <= 1e-9)
            {
                return 0.0;
            }

            return (diameterMm * diameterMm / 162.0) * lengthM;
        }

        private static double GetShopDrawingRebarDiameterMm(Document doc, Element rebar)
        {
            double diameterFt = GetShopDrawingFirstDouble(rebar, "Bar Diameter", "Diameter", "Model Bar Diameter", "Nominal Diameter");
            if (diameterFt <= 1e-9)
            {
                try
                {
                    Element type = doc?.GetElement(rebar.GetTypeId());
                    diameterFt = GetShopDrawingFirstDouble(type, "Bar Diameter", "Diameter", "Model Bar Diameter", "Nominal Diameter");
                }
                catch
                {
                }
            }

            return diameterFt > 1e-9 ? FeetToMm(diameterFt) : 0.0;
        }

        private static double GetShopDrawingFirstDouble(Element element, params string[] names)
        {
            foreach (string name in names ?? new string[0])
            {
                double value = GetShopDrawingParameterDouble(element, name);
                if (Math.Abs(value) > 1e-9)
                {
                    return value;
                }
            }

            return 0.0;
        }

        private static double GetShopDrawingParameterDouble(Element element, string name)
        {
            Parameter parameter = element?.LookupParameter(name);
            if (parameter == null)
            {
                return 0.0;
            }

            try
            {
                if (parameter.StorageType == StorageType.Double)
                {
                    return parameter.AsDouble();
                }

                if (parameter.StorageType == StorageType.Integer)
                {
                    return parameter.AsInteger();
                }

                if (parameter.StorageType == StorageType.String &&
                    double.TryParse(parameter.AsString(), NumberStyles.Float, CultureInfo.InvariantCulture, out double value))
                {
                    return value;
                }
            }
            catch
            {
            }

            return 0.0;
        }

        private static string GetShopDrawingParameterString(Element element, string name)
        {
            Parameter parameter = element?.LookupParameter(name);
            if (parameter == null)
            {
                return "";
            }

            try
            {
                if (parameter.StorageType == StorageType.String)
                {
                    return parameter.AsString() ?? "";
                }

                if (parameter.StorageType == StorageType.Integer)
                {
                    return parameter.AsInteger().ToString(CultureInfo.InvariantCulture);
                }

                if (parameter.StorageType == StorageType.Double)
                {
                    return parameter.AsDouble().ToString("0.###", CultureInfo.InvariantCulture);
                }

                if (parameter.StorageType == StorageType.ElementId)
                {
                    ElementId id = parameter.AsElementId();
                    return id == null || id == ElementId.InvalidElementId
                        ? ""
                        : id.Value.ToString(CultureInfo.InvariantCulture);
                }
            }
            catch
            {
            }

            return "";
        }

        private static string DefaultText(string value, string fallback)
        {
            return string.IsNullOrWhiteSpace(value) ? (fallback ?? "") : value.Trim();
        }

        private static string SanitizeShopDrawingName(string name)
        {
            string text = string.IsNullOrWhiteSpace(name) ? "NO_LEVEL" : name.Trim();
            text = Regex.Replace(text, @"[\\/:*?""<>|]+", "_");
            text = Regex.Replace(text, @"\s+", "_");
            return text.Length > 48 ? text.Substring(0, 48) : text;
        }

        private void ImportAdaptCadDrawing(Document doc)
        {
            string path = Request.AdaptCadSourcePath;
            if (string.IsNullOrWhiteSpace(path) || !System.IO.File.Exists(path))
            {
                _window?.ShowStatus("ADAPT CAD: source DWG/DXF was not found.");
                return;
            }

            string ext = System.IO.Path.GetExtension(path) ?? "";
            if (!string.Equals(ext, ".dwg", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(ext, ".dxf", StringComparison.OrdinalIgnoreCase))
            {
                _window?.ShowStatus("ADAPT CAD: select a DWG or DXF exported from ADAPT-Builder.");
                return;
            }

            View view = doc.ActiveView;
            if (!IsAdaptCadImportView(view))
            {
                _window?.ShowStatus("ADAPT CAD: open a plan, drafting, section, elevation, or 3D view before linking the ADAPT drawing.");
                return;
            }

            ElementId cadId = ElementId.InvalidElementId;
            bool linked = false;
            bool imported = false;
            string linkError = "";

            using (Transaction t = new Transaction(doc, "CamboBIM - Link ADAPT CAD Drawing"))
            {
                t.Start();

                DWGImportOptions options = CreateAdaptCadImportOptions();

                if (!doc.IsFamilyDocument)
                {
                    try
                    {
                        linked = doc.Link(path, options, view, out cadId);
                    }
                    catch (Exception ex)
                    {
                        linkError = ex.Message;
                        cadId = ElementId.InvalidElementId;
                    }
                }

                if (!linked || cadId == ElementId.InvalidElementId)
                {
                    try
                    {
                        imported = doc.Import(path, options, view, out cadId);
                    }
                    catch (Exception ex)
                    {
                        t.RollBack();
                        string detail = string.IsNullOrWhiteSpace(linkError)
                            ? ex.Message
                            : "link failed: " + linkError + "; import failed: " + ex.Message;
                        _window?.ShowStatus("ADAPT CAD import failed: " + detail);
                        return;
                    }
                }

                if (cadId == ElementId.InvalidElementId || (!linked && !imported))
                {
                    t.RollBack();
                    _window?.ShowStatus("ADAPT CAD import failed: Revit did not return a CAD instance.");
                    return;
                }

                t.Commit();
            }

            ImportInstance cad = doc.GetElement(cadId) as ImportInstance;
            if (cad == null)
            {
                _window?.ShowStatus("ADAPT CAD: drawing was added, but the CAD instance could not be selected for CAD2MODEL.");
                return;
            }

            Request.SelectedLinkId = cad.Id;
            List<string> layers = CollectCadLayers(doc, cad);
            _window?.UpdateLink(cad.Name, layers);

            string action = linked ? "linked" : "imported";
            _window?.ShowStatus(
                "ADAPT CAD: " + action + " " + System.IO.Path.GetFileName(path) +
                " at project origin and selected it as the CAD2MODEL source. Layers: " +
                layers.Count.ToString(CultureInfo.InvariantCulture) + ".");
        }

        private static bool IsAdaptCadImportView(View view)
        {
            return view != null &&
                   !view.IsTemplate &&
                   view.ViewType != ViewType.Schedule &&
                   view.ViewType != ViewType.DrawingSheet;
        }

        private static DWGImportOptions CreateAdaptCadImportOptions()
        {
            return new DWGImportOptions
            {
                Placement = ImportPlacement.Origin,
                ColorMode = ImportColorMode.Preserved,
                Unit = ImportUnit.Millimeter,
                ThisViewOnly = false,
                VisibleLayersOnly = false,
                AutoCorrectAlmostVHLines = true
            };
        }

        private void ImportAdaptTendonProfiles(Document doc)
        {
            List<AdaptTendonProfileSegmentPayload> segments = Request.AdaptTendonProfileSegments ?? new List<AdaptTendonProfileSegmentPayload>();
            if (segments.Count == 0)
            {
                _window?.ShowStatus("ADAPT import: no tendon/profile segments to import.");
                return;
            }

            View view = doc.ActiveView;
            if (Request.AdaptTendonImportMode == AdaptTendonImportMode.ProfileDetail)
            {
                if (view == null || view.IsTemplate ||
                    view.ViewType == ViewType.ThreeD ||
                    view.ViewType == ViewType.Schedule ||
                    view.ViewType == ViewType.DrawingSheet)
                {
                    _window?.ShowStatus("ADAPT import: open a plan, section, elevation, or drafting view for Station/Elevation profile lines.");
                    return;
                }
            }

            int created = 0;
            int skipped = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - Import ADAPT Tendon Profiles"))
            {
                t.Start();

                GraphicsStyle lineStyle = EnsureAdaptTendonLineStyle(doc);

                foreach (AdaptTendonProfileSegmentPayload segment in segments)
                {
                    if (segment == null)
                    {
                        skipped++;
                        continue;
                    }

                    try
                    {
                        CurveElement curveElement;
                        if (Request.AdaptTendonImportMode == AdaptTendonImportMode.ProfileDetail)
                        {
                            Line line = CreateAdaptProfileDetailLine(view, segment);
                            if (line == null)
                            {
                                skipped++;
                                continue;
                            }

                            curveElement = doc.Create.NewDetailCurve(view, line);
                        }
                        else
                        {
                            Line line = CreateAdaptModelLine(segment);
                            if (line == null)
                            {
                                skipped++;
                                continue;
                            }

                            SketchPlane sketchPlane = CreateSketchPlaneForAdaptLine(doc, line);
                            curveElement = doc.Create.NewModelCurve(line, sketchPlane);
                        }

                        if (lineStyle != null)
                        {
                            curveElement.LineStyle = lineStyle;
                        }

                        SetAdaptCurveMetadata(curveElement, segment, Request.AdaptTendonSourcePath);
                        created++;
                    }
                    catch
                    {
                        skipped++;
                    }
                }

                t.Commit();
            }

            string source = string.IsNullOrWhiteSpace(Request.AdaptTendonSourcePath)
                ? ""
                : " from " + System.IO.Path.GetFileName(Request.AdaptTendonSourcePath);
            string mode = Request.AdaptTendonImportMode == AdaptTendonImportMode.Model3D
                ? "3D model line"
                : "profile detail line";
            _window?.ShowStatus(
                "ADAPT import: created " +
                created.ToString(CultureInfo.InvariantCulture) +
                " " + mode + "(s)" + source +
                ". Skipped: " + skipped.ToString(CultureInfo.InvariantCulture) + ".");
        }

        private static Line CreateAdaptModelLine(AdaptTendonProfileSegmentPayload segment)
        {
            XYZ p0 = new XYZ(segment.X0Ft, segment.Y0Ft, segment.Z0Ft);
            XYZ p1 = new XYZ(segment.X1Ft, segment.Y1Ft, segment.Z1Ft);
            if (p0.DistanceTo(p1) < 1.0e-6)
            {
                return null;
            }

            return Line.CreateBound(p0, p1);
        }

        private static Line CreateAdaptProfileDetailLine(View view, AdaptTendonProfileSegmentPayload segment)
        {
            if (view == null)
            {
                return null;
            }

            XYZ origin = view.Origin ?? XYZ.Zero;
            XYZ right = view.RightDirection ?? XYZ.BasisX;
            XYZ up = view.UpDirection ?? XYZ.BasisY;

            XYZ p0 = origin
                .Add(right.Multiply(segment.X0Ft))
                .Add(up.Multiply(segment.Z0Ft));
            XYZ p1 = origin
                .Add(right.Multiply(segment.X1Ft))
                .Add(up.Multiply(segment.Z1Ft));

            if (p0.DistanceTo(p1) < 1.0e-6)
            {
                return null;
            }

            return Line.CreateBound(p0, p1);
        }

        private static SketchPlane CreateSketchPlaneForAdaptLine(Document doc, Line line)
        {
            XYZ p0 = line.GetEndPoint(0);
            XYZ p1 = line.GetEndPoint(1);
            XYZ direction = p1.Subtract(p0);
            if (direction.GetLength() < 1.0e-9)
            {
                direction = XYZ.BasisX;
            }
            else
            {
                direction = direction.Normalize();
            }

            XYZ normal;
            if (Math.Abs(p0.Z - p1.Z) < 1.0e-8)
            {
                normal = XYZ.BasisZ;
            }
            else
            {
                normal = direction.CrossProduct(XYZ.BasisZ);
                if (normal.GetLength() < 1.0e-9)
                {
                    normal = direction.CrossProduct(XYZ.BasisX);
                }

                if (normal.GetLength() < 1.0e-9)
                {
                    normal = XYZ.BasisY;
                }
                else
                {
                    normal = normal.Normalize();
                }
            }

            Plane plane = Plane.CreateByNormalAndOrigin(normal, p0);
            return SketchPlane.Create(doc, plane);
        }

        private static GraphicsStyle EnsureAdaptTendonLineStyle(Document doc)
        {
            const string styleName = "MHNK ADAPT Tendon";
            try
            {
                Category lines = doc.Settings.Categories.get_Item(BuiltInCategory.OST_Lines);
                Category subCategory = null;
                foreach (Category candidate in lines.SubCategories)
                {
                    if (string.Equals(candidate?.Name, styleName, StringComparison.OrdinalIgnoreCase))
                    {
                        subCategory = candidate;
                        break;
                    }
                }

                if (subCategory == null)
                {
                    subCategory = doc.Settings.Categories.NewSubcategory(lines, styleName);
                }

                try
                {
                    subCategory.LineColor = new Autodesk.Revit.DB.Color(186, 45, 138);
                    subCategory.SetLineWeight(5, GraphicsStyleType.Projection);
                }
                catch
                {
                }

                return subCategory.GetGraphicsStyle(GraphicsStyleType.Projection);
            }
            catch
            {
                return null;
            }
        }

        private static void SetAdaptCurveMetadata(
            CurveElement curveElement,
            AdaptTendonProfileSegmentPayload segment,
            string sourcePath)
        {
            if (curveElement == null || segment == null)
            {
                return;
            }

            string label = !string.IsNullOrWhiteSpace(segment.SourceLabel)
                ? segment.SourceLabel
                : BuildAdaptMetadataLabel(segment);
            string source = string.IsNullOrWhiteSpace(sourcePath)
                ? ""
                : " | Source=" + System.IO.Path.GetFileName(sourcePath);
            string value = "ADAPT Tendon Profile";
            if (!string.IsNullOrWhiteSpace(label))
            {
                value += " | " + label;
            }

            value += source;

            try
            {
                Parameter comments = curveElement.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
                if (comments == null)
                {
                    comments = curveElement.LookupParameter("Comments");
                }

                if (comments != null && !comments.IsReadOnly)
                {
                    comments.Set(value);
                }
            }
            catch
            {
            }
        }

        private static string BuildAdaptMetadataLabel(AdaptTendonProfileSegmentPayload segment)
        {
            string profile = (segment.ProfileName ?? "").Trim();
            string tendon = (segment.TendonName ?? "").Trim();
            if (!string.IsNullOrWhiteSpace(profile) &&
                !string.IsNullOrWhiteSpace(tendon) &&
                !string.Equals(profile, tendon, StringComparison.OrdinalIgnoreCase))
            {
                return profile + " / " + tendon;
            }

            if (!string.IsNullOrWhiteSpace(tendon)) return tendon;
            if (!string.IsNullOrWhiteSpace(profile)) return profile;
            return "";
        }

        private void GenerateDetailLines(Document doc)
        {
            if (Request.SelectedLinkId == ElementId.InvalidElementId)
            {
                _window?.ShowStatus("Pick a linked DWG first.");
                return;
            }

            if (!(doc.GetElement(Request.SelectedLinkId) is ImportInstance cad))
            {
                _window?.ShowStatus("Selected DWG link is no longer available.");
                return;
            }

            View view = doc.ActiveView;
            if (view == null || view.IsTemplate)
            {
                _window?.ShowStatus("Open a 2D view to place detail lines.");
                return;
            }

            if (view.ViewType == ViewType.ThreeD || view.ViewType == ViewType.Schedule || view.ViewType == ViewType.DrawingSheet)
            {
                _window?.ShowStatus("Detail lines require a plan, section, elevation, or drafting view.");
                return;
            }

            List<Line> lines;
            List<CurveLoop> loops;
            if (Request.UseLayerFilter)
            {
                if (string.IsNullOrWhiteSpace(Request.SelectedLayerName))
                {
                    _window?.ShowStatus("Select line layer.");
                    return;
                }

                lines = ExtractLinesFromLayer(doc, cad, Request.SelectedLayerName);
                loops = ExtractClosedLoopsFromLayer(doc, cad, Request.SelectedLayerName);
            }
            else
            {
                if (Request.SelectedCadReferences == null || Request.SelectedCadReferences.Count == 0)
                {
                    _window?.ShowStatus("Pick CAD objects or choose By Layer.");
                    return;
                }

                lines = ExtractLinesFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
                loops = ExtractClosedLoopsFromSelectedObjects(doc, cad, Request.SelectedCadReferences);
            }

            int loopCurveCount = loops.Sum(l => l.Count());
            int totalCurves = lines.Count + loopCurveCount;
            if (totalCurves == 0)
            {
                _window?.ShowStatus("No valid CAD lines found.");
                return;
            }

            GraphicsStyle lineStyle = doc.GetElement(Request.DrawingLineStyleId) as GraphicsStyle;
            bool flattenToView = IsPlanView(view);

            int created = 0;
            int skipped = 0;

            using (Transaction t = new Transaction(doc, "CamboBIM - CAD to Detail Lines"))
            {
                t.Start();

                foreach (Line line in lines)
                {
                    Line target = flattenToView ? FlattenLineToView(line, view) : line;
                    if (target == null)
                    {
                        skipped++;
                        continue;
                    }

                    try
                    {
                        DetailCurve dc = doc.Create.NewDetailCurve(view, target);
                        if (lineStyle != null) dc.LineStyle = lineStyle;
                        created++;
                    }
                    catch
                    {
                        skipped++;
                    }
                }

                foreach (CurveLoop loop in loops)
                {
                    foreach (Curve c in loop)
                    {
                        Curve target = c;
                        if (flattenToView && c is Line loopLine)
                        {
                            target = FlattenLineToView(loopLine, view);
                        }

                        if (target == null)
                        {
                            skipped++;
                            continue;
                        }

                        try
                        {
                            DetailCurve dc = doc.Create.NewDetailCurve(view, target);
                            if (lineStyle != null) dc.LineStyle = lineStyle;
                            created++;
                        }
                        catch
                        {
                            skipped++;
                        }
                    }
                }

                t.Commit();
            }

            _window?.ShowStatus($"Created detail lines: {created} (from {totalCurves} curves). Skipped: {skipped}.");
        }

        private List<XYZ> ExtractFromSelectedObjects(Document doc, ImportInstance cad, List<Reference> refs)
        {
            var points = new List<XYZ>();
            var lines = new List<Line>();

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (Reference r in refs)
            {
                if (r == null) continue;
                GeometryObject go = cad.GetGeometryObjectFromReference(r);
                if (go == null) continue;

                ExtractFromGeometryObject(doc, go, importTrf, "", points, lines);
            }

            if (Request.UseLineIntersections && lines.Count > 1)
            {
                points.AddRange(FindLineIntersections(lines, GetTasCadLineSearchDistanceFt(0.0), GetTasParallelAngleEpsilonDeg()));
            }

            return points;
        }

        private List<Line> ExtractLinesFromSelectedObjects(Document doc, ImportInstance cad, IList<Reference> refs)
        {
            var hits = ExtractShapesFromSelectedObjects(doc, cad, refs);
            return hits.Lines;
        }

        private List<XYZ> ExtractFromLayer(Document doc, ImportInstance cad, string layerName)
        {
            var points = new List<XYZ>();
            var lines = new List<Line>();

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return points;

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (GeometryObject go in ge)
            {
                ExtractFromGeometryObject(doc, go, importTrf, layerName, points, lines);
            }

            if (Request.UseLineIntersections && lines.Count > 1)
            {
                points.AddRange(FindLineIntersections(lines, GetTasCadLineSearchDistanceFt(0.0), GetTasParallelAngleEpsilonDeg()));
            }

            return points;
        }

        private List<Line> ExtractLinesFromLayer(Document doc, ImportInstance cad, string layerName)
        {
            var hits = ExtractShapesFromLayer(doc, cad, layerName);
            return hits.Lines;
        }

        private void ExtractFromGeometryObject(
            Document doc,
            GeometryObject go,
            Transform trf,
            string layerFilter,
            List<XYZ> points,
            List<Line> lines)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);

                if (Request.UseBlocks)
                {
                    points.Add(instTrf.Origin);
                }

                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        ExtractFromGeometryObject(doc, igo, instTrf, layerFilter, points, lines);
                    }
                }
                return;
            }

            Curve c = go as Curve;
            if (c != null)
            {
                string layer = GetCadLayer(doc, go);
                if (!string.IsNullOrWhiteSpace(layerFilter) &&
                    !string.Equals(layerFilter, layer, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                Arc a = c as Arc;
                if (Request.UseCircles && a != null && a.IsCyclic)
                {
                    points.Add(trf.OfPoint(a.Center));
                    return;
                }

                Line l = c as Line;
                if (l != null)
                {
                    lines.Add(Line.CreateBound(trf.OfPoint(l.GetEndPoint(0)), trf.OfPoint(l.GetEndPoint(1))));
                }
                return;
            }
        }

        private CadShapeHits ExtractShapesFromSelectedObjects(Document doc, ImportInstance cad, IList<Reference> refs)
        {
            var hits = new CadShapeHits();

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (Reference r in refs)
            {
                if (r == null) continue;
                GeometryObject go = cad.GetGeometryObjectFromReference(r);
                if (go == null) continue;

                ExtractShapesFromGeometryObject(doc, go, importTrf, "", hits);
            }

            return hits;
        }

        private CadShapeHits ExtractShapesFromLayer(Document doc, ImportInstance cad, string layerName)
        {
