        private CadShapeHits ExtractShapesFromBox(
            Document doc,
            ImportInstance cad,
            XYZ boxMin,
            XYZ boxMax,
            string layerFilter,
            string colorFilter,
            Dictionary<string, int> layerStats,
            Dictionary<string, int> colorStats)
        {
            var hits = new CadShapeHits();
            if (doc == null || cad == null)
            {
                return hits;
            }

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return hits;

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (GeometryObject go in ge)
            {
                ExtractShapesFromGeometryObjectInBox(
                    doc,
                    go,
                    importTrf,
                    boxMin,
                    boxMax,
                    layerFilter,
                    colorFilter,
                    hits,
                    layerStats,
                    colorStats);
            }

            return hits;
        }

        private void ExtractShapesFromGeometryObjectInBox(
            Document doc,
            GeometryObject go,
            Transform trf,
            XYZ boxMin,
            XYZ boxMax,
            string layerFilter,
            string colorFilter,
            CadShapeHits hits,
            Dictionary<string, int> layerStats,
            Dictionary<string, int> colorStats)
        {
            if (go == null || hits == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                string instanceLayer = GetCadLayer(doc, go);
                string instanceColor = GetCadColorKey(doc, go);
                if (PointInsideBox2D(instTrf.Origin, boxMin, boxMax))
                {
                    IncrementKeyCount(layerStats, instanceLayer);
                    IncrementKeyCount(colorStats, instanceColor);
                    if (MatchesOptionalFilter(instanceLayer, layerFilter) &&
                        MatchesOptionalFilter(instanceColor, colorFilter))
                    {
                        string blockName = GetCadBlockName(doc, gi);
                        hits.Blocks.Add(new CadBlockHit(instTrf.Origin, blockName));
                        hits.BlockPoints.Add(instTrf.Origin);
                    }
                }

                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        ExtractShapesFromGeometryObjectInBox(
                            doc,
                            igo,
                            instTrf,
                            boxMin,
                            boxMax,
                            layerFilter,
                            colorFilter,
                            hits,
                            layerStats,
                            colorStats);
                    }
                }
                return;
            }

            Curve c = go as Curve;
            if (c != null)
            {
                string layer = GetCadLayer(doc, go);
                string color = GetCadColorKey(doc, go);
                Arc a = c as Arc;
                if (a != null && a.IsCyclic)
                {
                    XYZ center = trf.OfPoint(a.Center);
                    if (PointInsideBox2D(center, boxMin, boxMax))
                    {
                        IncrementKeyCount(layerStats, layer);
                        IncrementKeyCount(colorStats, color);
                        if (MatchesOptionalFilter(layer, layerFilter) &&
                            MatchesOptionalFilter(color, colorFilter))
                        {
                            hits.CircleCenters.Add(center);
                        }
                    }
                    return;
                }

                Line l = c as Line;
                if (l != null)
                {
                    Line worldLine = Line.CreateBound(trf.OfPoint(l.GetEndPoint(0)), trf.OfPoint(l.GetEndPoint(1)));
                    if (LineTouchesBox2D(worldLine, boxMin, boxMax))
                    {
                        IncrementKeyCount(layerStats, layer);
                        IncrementKeyCount(colorStats, color);
                        if (MatchesOptionalFilter(layer, layerFilter) &&
                            MatchesOptionalFilter(color, colorFilter))
                        {
                            hits.Lines.Add(worldLine);
                        }
                    }
                    return;
                }
            }

            PolyLine pl = go as PolyLine;
            if (pl != null)
            {
                string layer = GetCadLayer(doc, go);
                string color = GetCadColorKey(doc, go);
                IList<XYZ> pts = pl.GetCoordinates();
                if (pts == null || pts.Count < 2)
                {
                    return;
                }

                var worldPts = pts.Select(p => trf.OfPoint(p)).ToList();
                if (pts.Count >= 4 && IsClosedPolyline(pts))
                {
                    XYZ center = ComputePolylineCentroid(worldPts);
                    if (PointInsideBox2D(center, boxMin, boxMax) || worldPts.Any(p => PointInsideBox2D(p, boxMin, boxMax)))
                    {
                        IncrementKeyCount(layerStats, layer);
                        IncrementKeyCount(colorStats, color);
                        if (MatchesOptionalFilter(layer, layerFilter) &&
                            MatchesOptionalFilter(color, colorFilter))
                        {
                            if (TryGetPolylineSize(worldPts, out double widthFt, out double lengthFt))
                            {
                                hits.Polylines.Add(new CadPolylineHit(center, widthFt * 304.8, lengthFt * 304.8));
                            }
                            else
                            {
                                hits.Polylines.Add(new CadPolylineHit(center, 0, 0));
                            }
                        }
                    }
                    return;
                }

                for (int i = 0; i < worldPts.Count - 1; i++)
                {
                    Line line = Line.CreateBound(worldPts[i], worldPts[i + 1]);
                    if (!LineTouchesBox2D(line, boxMin, boxMax))
                    {
                        continue;
                    }

                    IncrementKeyCount(layerStats, layer);
                    IncrementKeyCount(colorStats, color);
                    if (MatchesOptionalFilter(layer, layerFilter) &&
                        MatchesOptionalFilter(color, colorFilter))
                    {
                        hits.Lines.Add(line);
                    }
                }
            }
        }

        private static bool PointInsideBox2D(XYZ point, XYZ boxMin, XYZ boxMax)
        {
            if (point == null || boxMin == null || boxMax == null)
            {
                return false;
            }

            double minX = Math.Min(boxMin.X, boxMax.X);
            double maxX = Math.Max(boxMin.X, boxMax.X);
            double minY = Math.Min(boxMin.Y, boxMax.Y);
            double maxY = Math.Max(boxMin.Y, boxMax.Y);
            return point.X >= minX && point.X <= maxX && point.Y >= minY && point.Y <= maxY;
        }

        private static bool LineTouchesBox2D(Line line, XYZ boxMin, XYZ boxMax)
        {
            if (line == null) return false;

            XYZ p0 = line.GetEndPoint(0);
            XYZ p1 = line.GetEndPoint(1);
            if (PointInsideBox2D(p0, boxMin, boxMax) || PointInsideBox2D(p1, boxMin, boxMax))
            {
                return true;
            }

            XYZ mid = (p0 + p1) * 0.5;
            if (PointInsideBox2D(mid, boxMin, boxMax))
            {
                return true;
            }

            double minX = Math.Min(boxMin.X, boxMax.X);
            double maxX = Math.Max(boxMin.X, boxMax.X);
            double minY = Math.Min(boxMin.Y, boxMax.Y);
            double maxY = Math.Max(boxMin.Y, boxMax.Y);
            double lineMinX = Math.Min(p0.X, p1.X);
            double lineMaxX = Math.Max(p0.X, p1.X);
            double lineMinY = Math.Min(p0.Y, p1.Y);
            double lineMaxY = Math.Max(p0.Y, p1.Y);

            return lineMaxX >= minX && lineMinX <= maxX && lineMaxY >= minY && lineMinY <= maxY;
        }

        private static void IncrementKeyCount(Dictionary<string, int> stats, string key)
        {
            if (stats == null || string.IsNullOrWhiteSpace(key))
            {
                return;
            }

            stats[key] = stats.TryGetValue(key, out int count) ? count + 1 : 1;
        }

        private static bool MatchesOptionalFilter(string value, string filter)
        {
            return string.IsNullOrWhiteSpace(filter) ||
                   string.Equals(value ?? "", filter, StringComparison.OrdinalIgnoreCase);
        }

        private static string PickDominantKey(Dictionary<string, int> stats, string preferred)
        {
            if (stats == null || stats.Count == 0)
            {
                return "";
            }

            if (!string.IsNullOrWhiteSpace(preferred) && stats.ContainsKey(preferred))
            {
                return preferred;
            }

            return stats
                .Where(kvp => !string.IsNullOrWhiteSpace(kvp.Key))
                .OrderByDescending(kvp => kvp.Value)
                .ThenBy(kvp => kvp.Key)
                .Select(kvp => kvp.Key)
                .FirstOrDefault() ?? "";
        }

        private List<CurveLoop> ExtractClosedLoopsFromSelectedObjects(Document doc, ImportInstance cad, List<Reference> refs)
        {
            var loops = new List<CurveLoop>();

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (Reference r in refs)
            {
                if (r == null) continue;
                GeometryObject go = cad.GetGeometryObjectFromReference(r);
                if (go == null) continue;

                CollectClosedLoopsFromGeom(doc, go, importTrf, "", loops);
            }

            return loops;
        }

        private List<CurveLoop> ExtractClosedLoopsFromLayer(Document doc, ImportInstance cad, string layerName)
        {
            var loops = new List<CurveLoop>();

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return loops;

            Transform importTrf = GetCadGeometryRootTransform(cad);

            foreach (GeometryObject go in ge)
            {
                CollectClosedLoopsFromGeom(doc, go, importTrf, layerName, loops);
            }

            return loops;
        }

        private List<LeanConcreteSourceProfile> BuildLeanConcreteSourceProfiles(Document doc, IList<ElementId> elementIds)
        {
            var profiles = new List<LeanConcreteSourceProfile>();
            if (doc == null || elementIds == null || elementIds.Count == 0)
            {
                return profiles;
            }

            foreach (ElementId id in elementIds)
            {
                if (id == null || id == ElementId.InvalidElementId)
                {
                    continue;
                }

                Element element = doc.GetElement(id);
                if (!IsLeanConcreteSourceElement(element))
                {
                    continue;
                }

                if (!TryExtractLeanConcreteBoundaryFace(element, out PlanarFace sourceFace))
                {
                    continue;
                }

                List<CurveLoop> loops = ExtractBoundaryLoopsFromFace(sourceFace);
                if (loops.Count == 0)
                {
                    continue;
                }

                List<List<CurveLoop>> groups = GroupLoopsWithHoles(loops);
                if (groups.Count == 0)
                {
                    continue;
                }

                profiles.Add(new LeanConcreteSourceProfile
                {
                    BottomElevationFt = sourceFace.Origin.Z,
                    LoopGroups = groups
                });
            }

            return profiles;
        }

        private List<SoilExcavationSourceProfile> BuildSoilExcavationSourceProfiles(Document doc, IList<ElementId> elementIds)
        {
            var profiles = new List<SoilExcavationSourceProfile>();
            if (doc == null || elementIds == null || elementIds.Count == 0)
            {
                return profiles;
            }

            foreach (ElementId id in elementIds)
            {
                if (id == null || id == ElementId.InvalidElementId)
                {
                    continue;
                }

                Element element = doc.GetElement(id);
                if (!IsSoilExcavationSourceElement(element))
                {
                    continue;
                }

                if (!TryExtractSoilExcavationBottomBoundaryFace(element, out PlanarFace bottomFace))
                {
                    continue;
                }

                List<CurveLoop> loops = ExtractBoundaryLoopsFromFace(bottomFace);
                if (loops.Count == 0)
                {
                    continue;
                }

                List<List<CurveLoop>> groups = GroupLoopsWithHoles(loops);
                if (groups.Count == 0)
                {
                    continue;
                }

                profiles.Add(new SoilExcavationSourceProfile
                {
                    BottomElevationFt = bottomFace.Origin.Z,
                    LoopGroups = groups
                });
            }

            return profiles;
        }

        private static bool IsSoilExcavationSourceElement(Element element)
        {
            if (!(element is Floor floor) || floor.Category == null)
            {
                return false;
            }

            long categoryId = floor.Category.Id.Value;
            return categoryId == (long)BuiltInCategory.OST_Floors ||
                   categoryId == (long)BuiltInCategory.OST_StructuralFoundation;
        }

        private List<SoilExcavationFoundationTopCandidate> BuildSoilExcavationFoundationTopCandidates(
            Document doc,
            ISet<ElementId> excludedElementIds)
        {
            var candidates = new List<SoilExcavationFoundationTopCandidate>();
            if (doc == null)
            {
                return candidates;
            }

            var foundationFilter = new LogicalOrFilter(
                new ElementCategoryFilter(BuiltInCategory.OST_StructuralFoundation),
                new ElementClassFilter(typeof(WallFoundation)));

            IEnumerable<Element> foundationElements = new FilteredElementCollector(doc)
                .WhereElementIsNotElementType()
                .WherePasses(foundationFilter)
                .ToElements();

            foreach (Element element in foundationElements)
            {
                if (element == null)
                {
                    continue;
                }

                if (excludedElementIds != null && excludedElementIds.Contains(element.Id))
                {
                    continue;
                }

                if (!IsSoilExcavationFoundationElement(element))
                {
                    continue;
                }

                if (!TryExtractSoilExcavationFoundationTopBoundaryFace(element, out PlanarFace topFace))
                {
                    continue;
                }

                List<CurveLoop> loops = ExtractBoundaryLoopsFromFace(topFace);
                if (loops.Count == 0)
                {
                    continue;
                }

                List<List<CurveLoop>> groups = GroupLoopsWithHoles(loops);
                if (groups.Count == 0)
                {
                    continue;
                }

                foreach (List<CurveLoop> group in groups)
                {
                    CurveLoop outer = SelectOutermostLoop(group) ?? group.FirstOrDefault();
                    LoopInfo outerInfo = LoopInfo.From(outer);
                    if (outerInfo == null)
                    {
                        continue;
                    }

                    candidates.Add(new SoilExcavationFoundationTopCandidate
                    {
                        TopElevationFt = topFace.Origin.Z,
                        OuterLoopInfo = outerInfo,
                        LoopGroup = group
                            .Select((loop, index) => EnsureOrientation(loop, index == 0))
                            .ToList()
                    });
                }
            }

            return candidates;
        }

        private static bool IsSoilExcavationFoundationElement(Element element)
        {
            return IsLeanConcreteFoundationSourceElement(element);
        }

        private static bool TryExtractSoilExcavationBottomBoundaryFace(Element element, out PlanarFace sourceFace)
        {
            sourceFace = null;
            if (element == null)
            {
                return false;
            }

            Options options = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = element.get_Geometry(options);
            if (ge == null)
            {
                return false;
            }

            var horizontalFaces = new List<PlanarFace>();
            CollectHorizontalPlanarFaces(ge, horizontalFaces);
            if (horizontalFaces.Count == 0)
            {
                return false;
            }

            // For Soil Excavation, we must anchor to the true underside of Lean Concrete.
            // Pick the lowest significant horizontal face (not the largest face),
            // because area-first selection can return a higher face for some shapes.
            double maxArea = horizontalFaces.Max(face => Math.Abs(face.Area));
            double minAcceptedArea = maxArea * 0.05;
            IEnumerable<PlanarFace> significantFaces = horizontalFaces
                .Where(face => Math.Abs(face.Area) >= minAcceptedArea);

            sourceFace = significantFaces
                .OrderBy(face => face.Origin.Z)
                .ThenByDescending(face => Math.Abs(face.Area))
                .FirstOrDefault()
                ?? horizontalFaces
                    .OrderBy(face => face.Origin.Z)
                    .ThenByDescending(face => Math.Abs(face.Area))
                    .FirstOrDefault();

            return sourceFace != null;
        }

        private static bool TryExtractSoilExcavationFoundationTopBoundaryFace(Element element, out PlanarFace sourceFace)
        {
            sourceFace = null;
            if (element == null)
            {
                return false;
            }

            Options options = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = element.get_Geometry(options);
            if (ge == null)
            {
                return false;
            }

            var horizontalFaces = new List<PlanarFace>();
            CollectHorizontalPlanarFaces(ge, horizontalFaces);
            if (horizontalFaces.Count == 0)
            {
                return false;
            }

            double maxArea = horizontalFaces.Max(face => Math.Abs(face.Area));
            double minAcceptedArea = maxArea * 0.05;
            IEnumerable<PlanarFace> significantFaces = horizontalFaces
                .Where(face => Math.Abs(face.Area) >= minAcceptedArea);

            sourceFace = significantFaces
                .OrderByDescending(face => face.Origin.Z)
                .ThenByDescending(face => face.Area)
                .FirstOrDefault();

            return sourceFace != null;
        }

        private static SoilExcavationFoundationTopCandidate ResolveSoilExcavationTopCandidate(
            CurveLoop leanOuterLoop,
            double leanBottomElevationFt,
            IList<SoilExcavationFoundationTopCandidate> foundationTopCandidates)
        {
            if (leanOuterLoop == null || foundationTopCandidates == null || foundationTopCandidates.Count == 0)
            {
                return null;
            }

            LoopInfo leanOuterInfo = LoopInfo.From(leanOuterLoop);
            if (leanOuterInfo == null)
            {
                return null;
            }

            XYZ sample = leanOuterInfo.Sample;
            const double tol = 1e-6;
            SoilExcavationFoundationTopCandidate bestCandidate = null;
            double bestDeltaFt = double.PositiveInfinity;

            foreach (SoilExcavationFoundationTopCandidate candidate in foundationTopCandidates)
            {
                if (candidate?.OuterLoopInfo == null)
                {
                    continue;
                }

                double deltaFt = candidate.TopElevationFt - leanBottomElevationFt;
                if (deltaFt <= tol)
                {
                    continue;
                }

                LoopInfo foundationOuterInfo = candidate.OuterLoopInfo;
                if (!foundationOuterInfo.Bounds.Contains(sample))
                {
                    continue;
                }

                if (!PointInPolygon(sample, foundationOuterInfo.Points))
                {
                    continue;
                }

                if (deltaFt < bestDeltaFt)
                {
                    bestDeltaFt = deltaFt;
                    bestCandidate = candidate;
                }
            }

            if (bestCandidate != null)
            {
                return bestCandidate;
            }

            foreach (SoilExcavationFoundationTopCandidate candidate in foundationTopCandidates)
            {
                if (candidate?.OuterLoopInfo == null)
                {
                    continue;
                }

                double deltaFt = candidate.TopElevationFt - leanBottomElevationFt;
                if (deltaFt <= tol)
                {
                    continue;
                }

                XYZ foundationSample = candidate.OuterLoopInfo.Sample;
                if (!leanOuterInfo.Bounds.Contains(foundationSample))
                {
                    continue;
                }

                if (!PointInPolygon(foundationSample, leanOuterInfo.Points))
                {
                    continue;
                }

                if (deltaFt < bestDeltaFt)
                {
                    bestDeltaFt = deltaFt;
                    bestCandidate = candidate;
                }
            }

            return bestCandidate;
        }

        private static List<CurveLoop> TryOffsetLoopGroupForSoilTop(
            List<CurveLoop> group,
            double topOffsetFt,
            out double appliedOffsetFt)
        {
            return TryOffsetLoopGroupForSoilWithFallback(
                group,
                topOffsetFt,
                expandOuter: true,
                out appliedOffsetFt);
        }

        private static List<CurveLoop> TryOffsetLoopGroupForSoilBottom(
            List<CurveLoop> group,
            double bottomInsetFt,
            out double appliedInsetFt)
        {
            return TryOffsetLoopGroupForSoilWithFallback(
                group,
                bottomInsetFt,
                // Bottom profile offset is measured outward from lean shape.
                expandOuter: true,
                out appliedInsetFt);
        }

        private static List<CurveLoop> TryOffsetLoopGroupForSoilWithFallback(
            List<CurveLoop> group,
            double requestedOffsetFt,
            bool expandOuter,
            out double appliedOffsetFt)
        {
            appliedOffsetFt = 0.0;
            if (group == null || group.Count == 0)
            {
                return null;
            }

            double requestedAbsOffsetFt = Math.Abs(requestedOffsetFt);
            List<CurveLoop> exact = TryOffsetLoopGroupForSoil(group, requestedAbsOffsetFt, expandOuter);
            if (exact != null)
            {
                appliedOffsetFt = requestedAbsOffsetFt;
                return exact;
            }

            // If requested offset is too large for the profile, keep reducing it
            // so the tool still generates instead of skipping all geometry.
            List<CurveLoop> best = TryOffsetLoopGroupForSoil(group, 0.0, expandOuter);
            if (best == null)
            {
                return null;
            }

            double low = 0.0;
            double high = requestedAbsOffsetFt;
            for (int i = 0; i < 16; i++)
            {
                double mid = (low + high) * 0.5;
                List<CurveLoop> candidate = TryOffsetLoopGroupForSoil(group, mid, expandOuter);
                if (candidate != null)
                {
                    best = candidate;
                    low = mid;
                }
                else
                {
                    high = mid;
                }
            }

            appliedOffsetFt = low;
            return best;
        }

        private static List<CurveLoop> TryOffsetLoopGroupForSoil(List<CurveLoop> group, double offsetFt, bool expandOuter)
        {
            if (group == null || group.Count == 0)
            {
                return null;
            }

            double absOffsetFt = Math.Abs(offsetFt);
            if (absOffsetFt <= 1e-9)
            {
                var identity = new List<CurveLoop>(group.Count);
                for (int i = 0; i < group.Count; i++)
                {
                    bool isOuter = i == 0;
                    identity.Add(EnsureOrientation(group[i], isOuter));
                }
                return identity;
            }

            var results = new List<CurveLoop>(group.Count);
            for (int i = 0; i < group.Count; i++)
            {
                bool isOuter = i == 0;
                CurveLoop source = EnsureOrientation(group[i], isOuter);
                bool expand = isOuter ? expandOuter : !expandOuter;
                CurveLoop offsetLoop = TryOffsetLoopByArea(source, absOffsetFt, expand, allowOppositeDirection: false);
                if (offsetLoop == null)
                {
                    if (isOuter)
                    {
                        return null;
                    }

                    // Optional holes can collapse under large offsets; keep outer shape.
                    continue;
                }

                results.Add(EnsureOrientation(offsetLoop, isOuter));
            }

            return results;
        }

        private static double ComputeNonOverlappingVolumeFt3(
            IList<Solid> solids,
            out int mergedPairs,
            out int booleanFailures)
        {
            mergedPairs = 0;
            booleanFailures = 0;
            if (solids == null || solids.Count == 0)
            {
                return 0.0;
            }

            const double volTol = 1e-9;
            var work = solids
                .Where(s => s != null && s.Volume > volTol)
                .ToList();
            if (work.Count == 0)
            {
                return 0.0;
            }

            bool changed = true;
            int safety = 0;
            while (changed && safety < 10000)
            {
                changed = false;
                safety++;

                for (int i = 0; i < work.Count; i++)
                {
                    Solid a = work[i];
                    if (a == null || a.Volume <= volTol)
                    {
                        continue;
                    }

                    for (int j = i + 1; j < work.Count; j++)
                    {
                        Solid b = work[j];
                        if (b == null || b.Volume <= volTol)
                        {
                            continue;
                        }

                        Solid inter = null;
                        try
                        {
                            inter = BooleanOperationsUtils.ExecuteBooleanOperation(
                                a,
                                b,
                                BooleanOperationsType.Intersect);
                        }
                        catch
                        {
                            booleanFailures++;
                            continue;
                        }

                        if (inter == null || inter.Volume <= volTol)
                        {
                            continue;
                        }

                        try
                        {
                            Solid union = BooleanOperationsUtils.ExecuteBooleanOperation(
                                a,
                                b,
                                BooleanOperationsType.Union);
                            if (union != null && union.Volume > volTol)
                            {
                                work[i] = union;
                                work.RemoveAt(j);
                                mergedPairs++;
                                changed = true;
                                break;
                            }
                        }
                        catch
                        {
                            booleanFailures++;
                        }

                        try
                        {
                            Solid bMinusA = BooleanOperationsUtils.ExecuteBooleanOperation(
                                b,
                                a,
                                BooleanOperationsType.Difference);
                            if (bMinusA == null || bMinusA.Volume <= volTol)
                            {
                                work.RemoveAt(j);
                                mergedPairs++;
                                changed = true;
                                break;
                            }

                            double reduced = b.Volume - bMinusA.Volume;
                            if (reduced > volTol)
                            {
                                work[j] = bMinusA;
                                mergedPairs++;
                                changed = true;
                                break;
                            }
                        }
                        catch
                        {
                            booleanFailures++;
                        }
                    }

                    if (changed)
                    {
                        break;
                    }
                }
            }

            double total = 0.0;
            foreach (Solid s in work)
            {
                if (s != null && s.Volume > volTol)
                {
                    total += s.Volume;
                }
            }

            return total;
        }

        private static Solid CreateSoilExcavationSolidFromGroups(
            List<CurveLoop> topGroup,
            List<CurveLoop> bottomGroup,
            double topElevationFt,
            double bottomElevationFt)
        {
            if (topGroup == null || bottomGroup == null || topGroup.Count == 0 || bottomGroup.Count == 0)
            {
                return null;
            }

            CurveLoop topOuter = EnsureOrientation(topGroup[0], true);
            CurveLoop bottomOuter = EnsureOrientation(bottomGroup[0], true);

            Solid solid = CreateLoftBetweenLoops(topOuter, bottomOuter, topElevationFt, bottomElevationFt);
            if (solid == null)
            {
                return null;
            }

            int holeCount = Math.Min(topGroup.Count, bottomGroup.Count);
            for (int i = 1; i < holeCount; i++)
            {
                CurveLoop topHole = EnsureOrientation(topGroup[i], false);
                CurveLoop bottomHole = EnsureOrientation(bottomGroup[i], false);
                Solid holeSolid = CreateLoftBetweenLoops(topHole, bottomHole, topElevationFt, bottomElevationFt);
                if (holeSolid == null || holeSolid.Volume <= 1e-9)
                {
                    continue;
                }

                try
                {
                    solid = BooleanOperationsUtils.ExecuteBooleanOperation(
                        solid,
                        holeSolid,
                        BooleanOperationsType.Difference);
                }
                catch
                {
                }
            }

            return solid;
        }

        private static Solid CreateLoftBetweenLoops(
            CurveLoop topLoop,
            CurveLoop bottomLoop,
            double topElevationFt,
            double bottomElevationFt)
        {
            if (topLoop == null || bottomLoop == null)
            {
                return null;
            }

            CurveLoop topAtZ = MoveCurveLoopToElevation(topLoop, topElevationFt);
            CurveLoop bottomAtZ = MoveCurveLoopToElevation(bottomLoop, bottomElevationFt);
            if (topAtZ == null || bottomAtZ == null)
            {
                return null;
            }

            var profiles = new List<CurveLoop> { topAtZ, bottomAtZ };
            try
            {
                return GeometryCreationUtilities.CreateLoftGeometry(
                    profiles,
                    new SolidOptions(ElementId.InvalidElementId, ElementId.InvalidElementId));
            }
            catch
            {
                return null;
            }
        }

        private static CurveLoop MoveCurveLoopToElevation(CurveLoop sourceLoop, double elevationFt)
        {
            if (sourceLoop == null)
            {
                return null;
            }

            Curve first = sourceLoop.FirstOrDefault();
            if (first == null)
            {
                return null;
            }

            double sourceElevationFt = first.GetEndPoint(0).Z;
            double dz = elevationFt - sourceElevationFt;
            Transform shift = Transform.CreateTranslation(new XYZ(0, 0, dz));
            var curves = new List<Curve>();
            foreach (Curve c in sourceLoop)
            {
                if (c == null)
                {
                    continue;
                }

                curves.Add(c.CreateTransformed(shift));
            }

            if (curves.Count < 3)
            {
                return null;
            }

            try
            {
                return CurveLoop.Create(curves);
            }
            catch
            {
                return null;
            }
        }

        private List<CurveLoop> ExtractTopBoundaryLoopsFromElements(Document doc, IList<ElementId> elementIds)
        {
            var loops = new List<CurveLoop>();
            if (doc == null || elementIds == null || elementIds.Count == 0)
            {
                return loops;
            }

            foreach (ElementId id in elementIds)
            {
                if (id == null || id == ElementId.InvalidElementId)
                {
                    continue;
                }

                Element element = doc.GetElement(id);
                if (!IsLeanConcreteSourceElement(element))
                {
                    continue;
                }

                loops.AddRange(ExtractTopBoundaryLoopsFromElement(element));
            }

            return loops;
        }

        private static bool IsLeanConcreteSourceElement(Element element)
        {
            if (IsLeanConcreteFoundationSourceElement(element))
            {
                return true;
            }

            if (element?.Category == null)
            {
                return false;
            }

            long categoryId = element.Category.Id.Value;
            return categoryId == (long)BuiltInCategory.OST_StructuralColumns ||
                   categoryId == (long)BuiltInCategory.OST_Walls ||
                   categoryId == (long)BuiltInCategory.OST_StructuralFraming ||
                   categoryId == (long)BuiltInCategory.OST_Floors ||
                   categoryId == (long)BuiltInCategory.OST_Stairs;
        }

        private static bool IsColumnRebarHostElement(Element element)
        {
            if (!(element is FamilyInstance))
            {
                return false;
            }

            if (element?.Category == null)
            {
                return false;
            }

            return element.Category.Id.Value == (long)BuiltInCategory.OST_StructuralColumns;
        }

        private static bool IsFoundationRebarHostElement(Element element)
        {
            if (element == null || element.Category == null)
            {
                return false;
            }

            long categoryId = element.Category.Id.Value;
            bool categoryOk = categoryId == (long)BuiltInCategory.OST_StructuralFoundation ||
                              categoryId == (long)BuiltInCategory.OST_Floors;
            if (!categoryOk)
            {
                return false;
            }

            if (element is FamilyInstance fi && IsBoredPileFoundationInstance(fi))
            {
                return false;
            }

            try
            {
                return RebarHostData.IsValidHost(element);
            }
            catch
            {
                return false;
            }
        }

        private static bool IsWallRebarHostElement(Element element)
        {
            if (element == null || element.Category == null)
            {
                return false;
            }

            long categoryId = element.Category.Id.Value;
            bool categoryOk = categoryId == (long)BuiltInCategory.OST_Walls ||
                              categoryId == (long)BuiltInCategory.OST_Floors ||
                              categoryId == (long)BuiltInCategory.OST_StructuralFoundation;
            if (!categoryOk)
            {
                return false;
            }

            try
            {
                return RebarHostData.IsValidHost(element);
            }
            catch
            {
                return false;
            }
        }

        private static bool IsBeamRebarHostElement(Element element)
        {
            if (!(element is FamilyInstance fi))
            {
                return false;
            }

            if (fi.Category == null ||
                fi.Category.Id.Value != (long)BuiltInCategory.OST_StructuralFraming)
            {
                return false;
            }

            try
            {
                StructuralType st = fi.StructuralType;
                if (st != StructuralType.Beam &&
                    st != StructuralType.Brace &&
                    st != StructuralType.UnknownFraming)
                {
                    return false;
                }
            }
            catch
            {
            }

            try
            {
                return RebarHostData.IsValidHost(fi);
            }
            catch
            {
                return false;
            }
        }

        private static bool IsBeamSupportReferenceElement(Element element)
        {
            if (element?.Category == null)
            {
                return false;
            }

            long categoryId = element.Category.Id.Value;
            return categoryId == (long)BuiltInCategory.OST_StructuralColumns ||
                   categoryId == (long)BuiltInCategory.OST_Walls ||
                   categoryId == (long)BuiltInCategory.OST_StructuralFoundation ||
                   categoryId == (long)BuiltInCategory.OST_StructuralFraming;
        }

        private static bool IsLeanConcreteFoundationSourceElement(Element element)
        {
            if (element == null)
            {
                return false;
            }

            if (element is WallFoundation)
            {
                return true;
            }

            if (element.Category == null)
            {
                return false;
            }

            if (element is FamilyInstance fi && IsBoredPileFoundationInstance(fi))
            {
                return false;
            }

            long categoryId = element.Category.Id.Value;
            return categoryId == (long)BuiltInCategory.OST_StructuralFoundation;
        }

        private List<CurveLoop> CollectBoredPileCutLoops(Document doc, ISet<ElementId> excludedIds)
        {
            var cutLoops = new List<CurveLoop>();
            if (doc == null)
            {
                return cutLoops;
            }

            List<FamilyInstance> pileInstances = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilyInstance))
                .OfCategory(BuiltInCategory.OST_StructuralFoundation)
                .Cast<FamilyInstance>()
                .Where(fi => fi != null && IsBoredPileFoundationInstance(fi))
                .ToList();

            foreach (FamilyInstance pile in pileInstances)
            {
                if (excludedIds != null && excludedIds.Contains(pile.Id))
                {
                    continue;
                }

                List<CurveLoop> pileLoops = ExtractTopBoundaryLoopsFromElement(pile);
                if (pileLoops.Count == 0)
                {
                    continue;
                }

                List<List<CurveLoop>> pileGroups = GroupLoopsWithHoles(pileLoops);
                foreach (List<CurveLoop> group in pileGroups)
                {
                    CurveLoop outer = SelectOutermostLoop(group) ?? group.FirstOrDefault();
                    if (outer != null)
                    {
                        cutLoops.Add(EnsureOrientation(outer, false));
                    }
                }
            }

            return cutLoops;
        }

        private static bool IsBoredPileFoundationInstance(FamilyInstance fi)
        {
            if (fi == null || fi.Category == null)
            {
                return false;
            }

            if (fi.Category.Id.Value != (long)BuiltInCategory.OST_StructuralFoundation)
            {
                return false;
            }

            string instanceName = fi.Name ?? "";
            string symbolName = fi.Symbol?.Name ?? "";
            string familyName = fi.Symbol?.Family?.Name ?? "";
            string key = (instanceName + " " + symbolName + " " + familyName).ToUpperInvariant();

            bool hasPileKeyword = key.Contains("PILE") || key.Contains("BORED");
            bool hasCapKeyword = key.Contains("CAP");
            return hasPileKeyword && !hasCapKeyword;
        }

        private static List<CurveLoop> ApplyInnerCutLoops(List<CurveLoop> sourceGroup, IList<CurveLoop> candidateCutLoops)
        {
            if (sourceGroup == null || sourceGroup.Count == 0)
            {
                return sourceGroup;
            }

            var result = new List<CurveLoop>();
            CurveLoop outer = EnsureOrientation(sourceGroup[0], true);
            result.Add(outer);

            for (int i = 1; i < sourceGroup.Count; i++)
            {
                result.Add(EnsureOrientation(sourceGroup[i], false));
            }

            if (candidateCutLoops == null || candidateCutLoops.Count == 0)
            {
                return result;
            }

            LoopInfo outerInfo = LoopInfo.From(outer);
            if (outerInfo == null)
            {
                return result;
            }

            var existingHoles = result
                .Skip(1)
                .Select(LoopInfo.From)
                .Where(info => info != null)
                .ToList();

            foreach (CurveLoop cutLoop in candidateCutLoops)
            {
                if (cutLoop == null)
                {
                    continue;
                }

                LoopInfo cutInfo = LoopInfo.From(cutLoop);
                if (cutInfo == null)
                {
                    continue;
                }

                if (!outerInfo.Contains(cutInfo))
                {
                    continue;
                }

                bool duplicatesHole = existingHoles.Any(existing =>
                    existing.Contains(cutInfo) || cutInfo.Contains(existing));
                if (duplicatesHole)
                {
                    continue;
                }

                CurveLoop normalizedHole = EnsureOrientation(cutLoop, false);
                result.Add(normalizedHole);
                LoopInfo normalizedInfo = LoopInfo.From(normalizedHole);
                if (normalizedInfo != null)
                {
                    existingHoles.Add(normalizedInfo);
                }
            }

            return result;
        }

        private static List<CurveLoop> ExtractTopBoundaryLoopsFromElement(Element element)
        {
            if (!TryExtractLeanConcreteBoundaryFace(element, out PlanarFace sourceFace))
            {
                return new List<CurveLoop>();
            }

            return ExtractBoundaryLoopsFromFace(sourceFace);
        }

        private static bool TryExtractLeanConcreteBoundaryFace(Element element, out PlanarFace sourceFace)
        {
            sourceFace = null;
            if (element == null)
            {
                return false;
            }

            Options options = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = element.get_Geometry(options);
            if (ge == null)
            {
                return false;
            }

            var horizontalFaces = new List<PlanarFace>();
            CollectHorizontalPlanarFaces(ge, horizontalFaces);
            if (horizontalFaces.Count == 0)
            {
                return false;
            }

            // Lean concrete should follow the underside footprint of the selected source element.
            // Use the lowest significant horizontal face to avoid picking tiny low faces while
            // still supporting columns/walls/beams/floors that have equal top/bottom areas.
            double maxArea = horizontalFaces.Max(face => Math.Abs(face.Area));
            double minAcceptedArea = maxArea * 0.05;
            IEnumerable<PlanarFace> significantFaces = horizontalFaces
                .Where(face => Math.Abs(face.Area) >= minAcceptedArea);

            sourceFace = significantFaces
                .OrderBy(face => face.Origin.Z)
                .ThenByDescending(face => Math.Abs(face.Area))
                .FirstOrDefault()
                ?? horizontalFaces
                    .OrderBy(face => face.Origin.Z)
                    .ThenByDescending(face => Math.Abs(face.Area))
                    .FirstOrDefault();

            return sourceFace != null;
        }

        private static List<CurveLoop> ExtractBoundaryLoopsFromFace(PlanarFace sourceFace)
        {
            var loops = new List<CurveLoop>();
            if (sourceFace == null)
            {
                return loops;
            }

            IList<CurveLoop> sourceLoops;
            try
            {
                sourceLoops = sourceFace.GetEdgesAsCurveLoops();
            }
            catch
            {
                return loops;
            }

            if (sourceLoops == null)
            {
                return loops;
            }

            foreach (CurveLoop faceLoop in sourceLoops)
            {
                CurveLoop flatLoop = FlattenCurveLoopToXY(faceLoop);
                if (flatLoop != null)
                {
                    loops.Add(flatLoop);
                }
            }

            return loops;
        }

        private static void CollectHorizontalPlanarFaces(GeometryElement ge, List<PlanarFace> faces)
        {
            if (ge == null || faces == null)
            {
                return;
            }

            foreach (GeometryObject go in ge)
            {
                if (go is GeometryInstance gi)
                {
                    GeometryElement instGeom = gi.GetInstanceGeometry();
                    if (instGeom != null)
                    {
                        CollectHorizontalPlanarFaces(instGeom, faces);
                    }

                    continue;
                }

                if (!(go is Solid solid) || solid.Faces == null || solid.Faces.Size == 0)
                {
                    continue;
                }

                foreach (Face face in solid.Faces)
                {
                    if (!(face is PlanarFace planarFace))
                    {
                        continue;
                    }

                    XYZ normal = planarFace.FaceNormal;
                    double length = normal.GetLength();
                    if (length < 1e-9)
                    {
                        continue;
                    }

                    normal = normal.Divide(length);
                    double absDot = Math.Abs(normal.DotProduct(XYZ.BasisZ));
                    if (absDot >= 0.999)
                    {
                        faces.Add(planarFace);
                    }
                }
            }
        }

        private static CurveLoop FlattenCurveLoopToXY(CurveLoop sourceLoop)
        {
            if (sourceLoop == null)
            {
                return null;
            }

            var flatCurves = new List<Curve>();
            foreach (Curve curve in sourceLoop)
            {
                AppendFlattenedCurveSegments(flatCurves, curve);
            }

            if (flatCurves.Count < 3)
            {
                return null;
            }

            try
            {
                return CurveLoop.Create(flatCurves);
            }
            catch
            {
                return null;
            }
        }

        private static void AppendFlattenedCurveSegments(List<Curve> target, Curve source)
        {
            if (target == null || source == null)
            {
                return;
            }

            if (source is Line line)
            {
                XYZ p0 = FlattenPointToXY(line.GetEndPoint(0));
                XYZ p1 = FlattenPointToXY(line.GetEndPoint(1));
                if (p0.DistanceTo(p1) > 1e-6)
                {
                    target.Add(Line.CreateBound(p0, p1));
                }

                return;
            }

            if (source is Arc arc)
            {
                XYZ p0 = FlattenPointToXY(arc.GetEndPoint(0));
                XYZ p1 = FlattenPointToXY(arc.GetEndPoint(1));
                XYZ pm = FlattenPointToXY(arc.Evaluate(0.5, true));

                if (p0.DistanceTo(p1) > 1e-6 &&
                    p0.DistanceTo(pm) > 1e-6 &&
                    p1.DistanceTo(pm) > 1e-6)
                {
                    try
                    {
                        target.Add(Arc.Create(p0, p1, pm));
                        return;
                    }
                    catch
                    {
                    }
                }

                if (p0.DistanceTo(p1) > 1e-6)
                {
                    target.Add(Line.CreateBound(p0, p1));
                }

                return;
            }

            IList<XYZ> points = source.Tessellate();
            if (points == null || points.Count < 2)
            {
                return;
            }

            for (int i = 0; i < points.Count - 1; i++)
            {
                XYZ p0 = FlattenPointToXY(points[i]);
                XYZ p1 = FlattenPointToXY(points[i + 1]);
                if (p0.DistanceTo(p1) <= 1e-6)
                {
                    continue;
                }

                target.Add(Line.CreateBound(p0, p1));
            }
        }

        private static XYZ FlattenPointToXY(XYZ point)
        {
            return point == null ? XYZ.Zero : new XYZ(point.X, point.Y, 0.0);
        }

        private void CollectClosedLoopsFromGeom(
            Document doc,
            GeometryObject go,
            Transform trf,
            string layerFilter,
            List<CurveLoop> loops)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        CollectClosedLoopsFromGeom(doc, igo, instTrf, layerFilter, loops);
                    }
                }
                return;
            }

            PolyLine pl = go as PolyLine;
            if (pl == null) return;

            string layer = GetCadLayer(doc, go);
            if (!string.IsNullOrWhiteSpace(layerFilter) &&
                !string.Equals(layerFilter, layer, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            IList<XYZ> pts = pl.GetCoordinates();
            if (pts == null || pts.Count < 3) return;

            double tolFt = MmToFeet(2.0);
            XYZ first = trf.OfPoint(pts[0]);
            XYZ last = trf.OfPoint(pts[pts.Count - 1]);
            bool closed = first.DistanceTo(last) <= tolFt;
            if (!closed) return;

            var curves = new List<Curve>();
            for (int i = 0; i < pts.Count - 1; i++)
            {
                XYZ p0 = trf.OfPoint(pts[i]);
                XYZ p1 = trf.OfPoint(pts[i + 1]);
                p0 = new XYZ(p0.X, p0.Y, 0);
                p1 = new XYZ(p1.X, p1.Y, 0);

                if (p0.DistanceTo(p1) < 1e-6) continue;
                curves.Add(Line.CreateBound(p0, p1));
            }

            if (curves.Count < 3) return;

            try
            {
                CurveLoop loop = CurveLoop.Create(curves);
                loops.Add(loop);
            }
            catch
            {
                // ignore invalid loops
            }
        }

        private static List<CurveLoop> TryOffsetLoopGroup(List<CurveLoop> group, double sideOffsetFt)
        {
            if (group == null || group.Count == 0)
            {
                return null;
            }

            double offsetFt = Math.Abs(sideOffsetFt);
            if (offsetFt <= 1e-9)
            {
                var identity = new List<CurveLoop>(group.Count);
                for (int i = 0; i < group.Count; i++)
                {
                    bool isOuter = i == 0;
                    identity.Add(EnsureOrientation(group[i], isOuter));
                }
                return identity;
            }

            var results = new List<CurveLoop>(group.Count);
            for (int i = 0; i < group.Count; i++)
            {
                bool isOuter = i == 0;
                CurveLoop source = EnsureOrientation(group[i], isOuter);
                CurveLoop offsetLoop = TryOffsetLoopByArea(source, offsetFt, expand: isOuter);
                if (offsetLoop == null)
                {
                    return null;
                }

                results.Add(EnsureOrientation(offsetLoop, isOuter));
            }

            return results;
        }

        private static CurveLoop TryOffsetLoopByArea(
            CurveLoop loop,
            double offsetFt,
            bool expand,
            bool allowOppositeDirection = true)
        {
            if (loop == null)
            {
                return null;
            }

            double baseArea = GetLoopAbsoluteArea(loop);
            if (baseArea <= 1e-9)
            {
                return null;
            }

            CurveLoop plus = TryCreateOffsetLoop(loop, offsetFt);
            CurveLoop minus = TryCreateOffsetLoop(loop, -offsetFt);

            if (plus == null && minus == null)
            {
                return null;
            }

            double plusArea = plus != null ? GetLoopAbsoluteArea(plus) : 0.0;
            double minusArea = minus != null ? GetLoopAbsoluteArea(minus) : 0.0;
            double tol = Math.Max(baseArea * 1e-6, 1e-9);

            bool plusExpands = plus != null && plusArea > baseArea + tol;
            bool minusExpands = minus != null && minusArea > baseArea + tol;
            bool plusShrinks = plus != null && plusArea < baseArea - tol;
            bool minusShrinks = minus != null && minusArea < baseArea - tol;

            if (expand)
            {
                if (plusExpands && minusExpands)
                {
                    return plusArea >= minusArea ? plus : minus;
                }

                if (plusExpands)
                {
                    return plus;
                }

                if (minusExpands)
                {
                    return minus;
                }

                if (!allowOppositeDirection)
                {
                    return null;
                }

                if (plus == null) return minus;
                if (minus == null) return plus;
                return plusArea >= minusArea ? plus : minus;
            }

            if (plusShrinks && minusShrinks)
            {
                return plusArea <= minusArea ? plus : minus;
            }

            if (plusShrinks)
            {
                return plus;
            }

            if (minusShrinks)
            {
                return minus;
            }

            if (!allowOppositeDirection)
            {
                return null;
            }

            if (plus == null) return minus;
            if (minus == null) return plus;
            return plusArea <= minusArea ? plus : minus;
        }

        private static CurveLoop TryCreateOffsetLoop(CurveLoop loop, double signedOffsetFt)
        {
            try
            {
                return CurveLoop.CreateViaOffset(loop, signedOffsetFt, XYZ.BasisZ);
            }
            catch
            {
                return null;
            }
        }

        private static double GetLoopAbsoluteArea(CurveLoop loop)
        {
            LoopInfo info = LoopInfo.From(loop);
            if (info == null || info.Points == null || info.Points.Count < 3)
            {
                return 0.0;
            }

            return Math.Abs(ComputePolygonArea(info.Points));
        }

        private static List<List<CurveLoop>> GroupLoopsWithHoles(List<CurveLoop> loops)
        {
            var infos = loops
                .Select(l => LoopInfo.From(l))
                .Where(i => i != null)
                .ToList();

            for (int i = 0; i < infos.Count; i++)
            {
                int depth = 0;
                for (int j = 0; j < infos.Count; j++)
                {
                    if (i == j) continue;
                    if (infos[j].Contains(infos[i]))
                    {
                        depth++;
                    }
                }
                infos[i].Depth = depth;
            }

            var outers = infos.Where(i => i.Depth % 2 == 0).ToList();
            var holes = infos.Where(i => i.Depth % 2 == 1).ToList();

            var groups = new List<List<CurveLoop>>();
            foreach (var outer in outers)
            {
                var group = new List<CurveLoop>
                {
                    EnsureOrientation(outer.Loop, true)
                };

                var childHoles = holes
                    .Where(h => outer.Contains(h))
                    .Where(h => IsImmediateHole(outer, h, outers))
                    .ToList();

                foreach (var hole in childHoles)
                {
                    group.Add(EnsureOrientation(hole.Loop, false));
                }

                groups.Add(group);
            }

            return groups;
        }

        private static bool IsImmediateHole(LoopInfo outer, LoopInfo hole, List<LoopInfo> outers)
        {
            foreach (var candidate in outers)
            {
                if (candidate == outer) continue;
                if (candidate.Contains(hole) && outer.Contains(candidate))
                {
                    return false;
                }
            }
            return true;
        }

        private static CurveLoop EnsureOrientation(CurveLoop loop, bool wantCcw)
        {
            bool isCcw = loop.IsCounterclockwise(XYZ.BasisZ);
            if (isCcw == wantCcw) return loop;

            var curves = new List<Curve>();
            foreach (Curve c in loop)
            {
                curves.Add(c.CreateReversed());
            }
            curves.Reverse();
            return CurveLoop.Create(curves);
        }

        private static CurveLoop SelectOutermostLoop(List<CurveLoop> loops)
        {
            if (loops == null || loops.Count == 0) return null;

            CurveLoop best = null;
            double bestArea = 0.0;

            foreach (CurveLoop loop in loops)
            {
                if (loop == null) continue;
                LoopInfo info = LoopInfo.From(loop);
                if (info == null || info.Points == null || info.Points.Count < 3) continue;

                double area = Math.Abs(ComputePolygonArea(info.Points));
                if (area > bestArea)
                {
                    bestArea = area;
                    best = loop;
                }
            }

            return best;
        }

        private static double ComputePolygonArea(List<XYZ> pts)
        {
            if (pts == null || pts.Count < 3) return 0.0;

            double area = 0.0;
            int count = pts.Count;
            for (int i = 0, j = count - 1; i < count; j = i++)
            {
                area += (pts[j].X * pts[i].Y) - (pts[i].X * pts[j].Y);
            }

            return area * 0.5;
        }

        private class LoopInfo
        {
            public CurveLoop Loop { get; private set; }
            public List<XYZ> Points { get; private set; }
            public BoundingBox2D Bounds { get; private set; }
            public XYZ Sample { get; private set; }
            public int Depth { get; set; }

            public static LoopInfo From(CurveLoop loop)
            {
                if (loop == null) return null;

                var pts = new List<XYZ>();
                foreach (Curve c in loop)
                {
                    XYZ p = c.GetEndPoint(0);
                    pts.Add(new XYZ(p.X, p.Y, 0));
                }

                if (pts.Count < 3) return null;

                var bounds = BoundingBox2D.From(pts);
                XYZ sample = GetCentroid(pts);

                return new LoopInfo
                {
                    Loop = loop,
                    Points = pts,
                    Bounds = bounds,
                    Sample = sample
                };
            }

            public bool Contains(LoopInfo other)
            {
                if (other == null) return false;
                if (!Bounds.Contains(other.Sample)) return false;
                return PointInPolygon(other.Sample, Points);
            }
        }

        private class BoundingBox2D
        {
            public double MinX { get; private set; }
            public double MinY { get; private set; }
            public double MaxX { get; private set; }
            public double MaxY { get; private set; }

            public static BoundingBox2D From(List<XYZ> pts)
            {
                double minX = double.PositiveInfinity;
                double minY = double.PositiveInfinity;
                double maxX = double.NegativeInfinity;
                double maxY = double.NegativeInfinity;

                foreach (var p in pts)
                {
                    if (p.X < minX) minX = p.X;
                    if (p.Y < minY) minY = p.Y;
                    if (p.X > maxX) maxX = p.X;
                    if (p.Y > maxY) maxY = p.Y;
                }

                return new BoundingBox2D
                {
                    MinX = minX,
                    MinY = minY,
                    MaxX = maxX,
                    MaxY = maxY
                };
            }

            public bool Contains(XYZ p)
            {
                return p.X >= MinX && p.X <= MaxX && p.Y >= MinY && p.Y <= MaxY;
            }
        }

        private static XYZ GetCentroid(List<XYZ> pts)
        {
            double sumX = 0;
            double sumY = 0;
            foreach (var p in pts)
            {
                sumX += p.X;
                sumY += p.Y;
            }

            double inv = 1.0 / pts.Count;
            return new XYZ(sumX * inv, sumY * inv, 0);
        }

        private static XYZ GetLoopSamplePoint(CurveLoop loop)
        {
            if (loop == null) return XYZ.Zero;

            var pts = new List<XYZ>();
            foreach (Curve c in loop)
            {
                XYZ p = c.GetEndPoint(0);
                pts.Add(new XYZ(p.X, p.Y, 0));
            }

            if (pts.Count == 0) return XYZ.Zero;

            return GetCentroid(pts);
        }

        private static bool PointInPolygon(XYZ p, List<XYZ> polygon)
        {
            bool inside = false;
            int n = polygon.Count;
            for (int i = 0, j = n - 1; i < n; j = i++)
            {
                double xi = polygon[i].X, yi = polygon[i].Y;
                double xj = polygon[j].X, yj = polygon[j].Y;

                bool intersect = ((yi > p.Y) != (yj > p.Y)) &&
                                 (p.X < (xj - xi) * (p.Y - yi) / (yj - yi + 1e-12) + xi);
                if (intersect) inside = !inside;
            }
            return inside;
        }

        private void ExtractShapesFromGeometryObject(
            Document doc,
            GeometryObject go,
            Transform trf,
            string layerFilter,
            CadShapeHits hits)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                bool includeBlockInsertion = true;
                if (!string.IsNullOrWhiteSpace(layerFilter))
                {
                    string instanceLayer = GetCadLayer(doc, go);
                    includeBlockInsertion = string.Equals(layerFilter, instanceLayer, StringComparison.OrdinalIgnoreCase);
                }

                if (includeBlockInsertion)
                {
                    string blockName = GetCadBlockName(doc, gi);
                    hits.Blocks.Add(new CadBlockHit(instTrf.Origin, blockName));
                    hits.BlockPoints.Add(instTrf.Origin);
                }

                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        ExtractShapesFromGeometryObject(doc, igo, instTrf, layerFilter, hits);
                    }
                }
                return;
            }

            Curve c = go as Curve;
            if (c != null)
            {
                string layer = GetCadLayer(doc, go);
                if (!string.IsNullOrWhiteSpace(layerFilter) &&
                    !string.Equals(layerFilter, layer, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                Arc a = c as Arc;
                if (a != null && a.IsCyclic)
                {
                    hits.CircleCenters.Add(trf.OfPoint(a.Center));
                    return;
                }

                Line l = c as Line;
                if (l != null)
                {
                    hits.Lines.Add(Line.CreateBound(trf.OfPoint(l.GetEndPoint(0)), trf.OfPoint(l.GetEndPoint(1))));
                    return;
                }
            }

            PolyLine pl = go as PolyLine;
            if (pl != null)
            {
                string layer = GetCadLayer(doc, go);
                if (!string.IsNullOrWhiteSpace(layerFilter) &&
                    !string.Equals(layerFilter, layer, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                IList<XYZ> pts = pl.GetCoordinates();
                if (pts.Count >= 4 && IsClosedPolyline(pts))
                {
                    var worldPts = pts.Select(p => trf.OfPoint(p)).ToList();
                    XYZ center = ComputePolylineCentroid(worldPts);
                    if (TryGetPolylineSize(worldPts, out double widthFt, out double lengthFt))
                    {
                        double widthMm = widthFt * 304.8;
                        double lengthMm = lengthFt * 304.8;
                        hits.Polylines.Add(new CadPolylineHit(center, widthMm, lengthMm));
                    }
                    else
                    {
                        hits.Polylines.Add(new CadPolylineHit(center, 0, 0));
                    }
                    return;
                }

                for (int i = 0; i < pts.Count - 1; i++)
                {
                    XYZ p0 = trf.OfPoint(pts[i]);
                    XYZ p1 = trf.OfPoint(pts[i + 1]);
                    hits.Lines.Add(Line.CreateBound(p0, p1));
                }
            }
        }

        private void ExtractShapesFromGeometryObjectByColor(
            Document doc,
            GeometryObject go,
            Transform trf,
            string colorKey,
            CadShapeHits hits)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                string instanceColor = GetCadColorKey(doc, go);
                if (string.Equals(colorKey, instanceColor, StringComparison.OrdinalIgnoreCase))
                {
                    string blockName = GetCadBlockName(doc, gi);
                    hits.Blocks.Add(new CadBlockHit(instTrf.Origin, blockName));
                    hits.BlockPoints.Add(instTrf.Origin);
                }

                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        ExtractShapesFromGeometryObjectByColor(doc, igo, instTrf, colorKey, hits);
                    }
                }
                return;
            }

            Curve c = go as Curve;
            if (c != null)
            {
                if (!string.Equals(colorKey, GetCadColorKey(doc, go), StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                Arc a = c as Arc;
                if (a != null && a.IsCyclic)
                {
                    hits.CircleCenters.Add(trf.OfPoint(a.Center));
                    return;
                }

                Line l = c as Line;
                if (l != null)
                {
                    hits.Lines.Add(Line.CreateBound(trf.OfPoint(l.GetEndPoint(0)), trf.OfPoint(l.GetEndPoint(1))));
                    return;
                }
            }

            PolyLine pl = go as PolyLine;
            if (pl != null)
            {
                if (!string.Equals(colorKey, GetCadColorKey(doc, go), StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                IList<XYZ> pts = pl.GetCoordinates();
                if (pts.Count >= 4 && IsClosedPolyline(pts))
                {
                    var worldPts = pts.Select(p => trf.OfPoint(p)).ToList();
                    XYZ center = ComputePolylineCentroid(worldPts);
                    if (TryGetPolylineSize(worldPts, out double widthFt, out double lengthFt))
                    {
                        hits.Polylines.Add(new CadPolylineHit(center, widthFt * 304.8, lengthFt * 304.8));
                    }
                    else
                    {
                        hits.Polylines.Add(new CadPolylineHit(center, 0, 0));
                    }
                    return;
                }

                for (int i = 0; i < pts.Count - 1; i++)
                {
                    XYZ p0 = trf.OfPoint(pts[i]);
                    XYZ p1 = trf.OfPoint(pts[i + 1]);
                    hits.Lines.Add(Line.CreateBound(p0, p1));
                }
            }
        }

        private int PlacePointBasedFoundations(Document doc, FamilySymbol symbol, Level baseLevel, Level topLevel, List<XYZ> points, double topOffsetFt)
        {
            int created = 0;
            foreach (XYZ p in points)
            {
                FamilyInstance fi = doc.Create.NewFamilyInstance(p, symbol, baseLevel, StructuralType.Footing);
                SetBaseAndTop(fi, baseLevel, topLevel, topOffsetFt);
                ApplyTasAttributesToElement(fi);
                created++;
            }
            return created;
        }

        private int PlaceSheetPiles(Document doc, FamilySymbol symbol, Level baseLevel, Level topLevel, List<Line> lines, double topOffsetFt)
        {
            int created = 0;

            FamilyPlacementType placementType = symbol.Family.FamilyPlacementType;
            bool isCurveBased = placementType == FamilyPlacementType.CurveBased ||
                                placementType == FamilyPlacementType.CurveDrivenStructural;

            foreach (Line line in lines)
            {
                FamilyInstance fi;
                if (isCurveBased)
                {
                    fi = doc.Create.NewFamilyInstance(line, symbol, baseLevel, StructuralType.Footing);
                }
                else
                {
                    XYZ mid = (line.GetEndPoint(0) + line.GetEndPoint(1)) * 0.5;
                    fi = doc.Create.NewFamilyInstance(mid, symbol, baseLevel, StructuralType.Footing);
                }

                SetBaseAndTop(fi, baseLevel, topLevel, topOffsetFt);
                ApplyTasAttributesToElement(fi);
                created++;
            }

            return created;
        }

        private static void SetBaseAndTop(FamilyInstance fi, Level baseLevel, Level topLevel, double topOffsetFt)
        {
            Parameter pBase = fi.get_Parameter(BuiltInParameter.FAMILY_LEVEL_PARAM);
            if (pBase != null && !pBase.IsReadOnly)
                pBase.Set(baseLevel.Id);

            Parameter pTop = fi.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_PARAM);
            if (pTop != null && !pTop.IsReadOnly)
                pTop.Set(topLevel.Id);

            Parameter pTopOffset = fi.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_OFFSET_PARAM);
            if (pTopOffset != null && !pTopOffset.IsReadOnly)
                pTopOffset.Set(topOffsetFt);
        }

