        private static List<XYZ> FindLineIntersections(List<Line> lines)
        {
            return FindLineIntersections(lines, 0.0, 5.0);
        }

        private static List<XYZ> FindLineIntersections(
            List<Line> lines,
            double snapToleranceFt,
            double parallelAngleEpsilonDeg)
        {
            var points = new List<XYZ>();
            if (lines == null || lines.Count < 2)
            {
                return points;
            }

            double safeSnapToleranceFt = Math.Max(0.0, snapToleranceFt);
            double safeParallelAngleEpsilonDeg = Math.Max(0.0, Math.Min(45.0, parallelAngleEpsilonDeg));

            for (int i = 0; i < lines.Count; i++)
            {
                Line a = lines[i];
                if (a == null) continue;

                for (int j = i + 1; j < lines.Count; j++)
                {
                    Line b = lines[j];
                    if (b == null) continue;

                    bool exactIntersectionFound = false;
                    SetComparisonResult res = a.Intersect(b, out IntersectionResultArray ira);
                    if (res == SetComparisonResult.Overlap && ira != null)
                    {
                        foreach (IntersectionResult ir in ira)
                        {
                            if (ir?.XYZPoint != null)
                            {
                                points.Add(ir.XYZPoint);
                                exactIntersectionFound = true;
                            }
                        }
                    }

                    if (exactIntersectionFound ||
                        safeSnapToleranceFt <= 1e-9 ||
                        ArePlanDirectionsParallel(a, b, safeParallelAngleEpsilonDeg))
                    {
                        continue;
                    }

                    AddNearEndpointIntersections(a, b, safeSnapToleranceFt, points);
                    AddNearEndpointIntersections(b, a, safeSnapToleranceFt, points);
                }
            }

            return points;
        }

        private static void AddNearEndpointIntersections(Line endpointSource, Line target, double toleranceFt, List<XYZ> points)
        {
            if (endpointSource == null || target == null || points == null)
            {
                return;
            }

            TryAddNearEndpointIntersection(endpointSource.GetEndPoint(0), target, toleranceFt, points);
            TryAddNearEndpointIntersection(endpointSource.GetEndPoint(1), target, toleranceFt, points);
        }

        private static void TryAddNearEndpointIntersection(XYZ endpoint, Line target, double toleranceFt, List<XYZ> points)
        {
            if (endpoint == null || target == null || points == null)
            {
                return;
            }

            if (!TryProjectPointToSegment2D(endpoint, target, out XYZ projected, out double distanceFt))
            {
                return;
            }

            if (distanceFt > toleranceFt)
            {
                return;
            }

            XYZ snapped = new XYZ(
                (endpoint.X + projected.X) * 0.5,
                (endpoint.Y + projected.Y) * 0.5,
                (endpoint.Z + projected.Z) * 0.5);
            points.Add(snapped);
        }

        private static bool TryProjectPointToSegment2D(XYZ point, Line target, out XYZ projected, out double distanceFt)
        {
            projected = null;
            distanceFt = double.MaxValue;

            if (point == null || target == null)
            {
                return false;
            }

            XYZ a = target.GetEndPoint(0);
            XYZ b = target.GetEndPoint(1);
            double dx = b.X - a.X;
            double dy = b.Y - a.Y;
            double lenSq = (dx * dx) + (dy * dy);
            if (lenSq <= 1e-18)
            {
                return false;
            }

            double t = (((point.X - a.X) * dx) + ((point.Y - a.Y) * dy)) / lenSq;
            t = Math.Max(0.0, Math.Min(1.0, t));

            projected = new XYZ(
                a.X + (dx * t),
                a.Y + (dy * t),
                a.Z + ((b.Z - a.Z) * t));

            double px = point.X - projected.X;
            double py = point.Y - projected.Y;
            distanceFt = Math.Sqrt((px * px) + (py * py));
            return !double.IsNaN(distanceFt) && !double.IsInfinity(distanceFt);
        }

        private static bool ArePlanDirectionsParallel(Line a, Line b, double angleEpsilonDeg)
        {
            if (a == null || b == null)
            {
                return false;
            }

            XYZ a0 = a.GetEndPoint(0);
            XYZ a1 = a.GetEndPoint(1);
            XYZ b0 = b.GetEndPoint(0);
            XYZ b1 = b.GetEndPoint(1);
            double ax = a1.X - a0.X;
            double ay = a1.Y - a0.Y;
            double bx = b1.X - b0.X;
            double by = b1.Y - b0.Y;
            double alen = Math.Sqrt((ax * ax) + (ay * ay));
            double blen = Math.Sqrt((bx * bx) + (by * by));
            if (alen <= 1e-12 || blen <= 1e-12)
            {
                return false;
            }

            double dot = Math.Abs(((ax / alen) * (bx / blen)) + ((ay / alen) * (by / blen)));
            dot = Math.Max(-1.0, Math.Min(1.0, dot));
            double angleDeg = Math.Acos(dot) * 180.0 / Math.PI;
            return angleDeg <= angleEpsilonDeg;
        }

        private static void SetTopLevel(FamilyInstance fi, Level topLevel)
        {
            Parameter pTop = fi.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_PARAM);
            if (pTop != null && !pTop.IsReadOnly)
                pTop.Set(topLevel.Id);

            Parameter pTopOffset = fi.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_OFFSET_PARAM);
            if (pTopOffset != null && !pTopOffset.IsReadOnly)
                pTopOffset.Set(0.0);
        }

        private static string GetCadLayer(Document doc, GeometryObject go)
        {
            try
            {
                if (go.GraphicsStyleId == ElementId.InvalidElementId) return "";
                if (!(doc.GetElement(go.GraphicsStyleId) is GraphicsStyle gs)) return "";
                return (gs.GraphicsStyleCategory != null) ? gs.GraphicsStyleCategory.Name : gs.Name;
            }
            catch
            {
                return "";
            }
        }

        private static string GetCadColorKey(Document doc, GeometryObject go)
        {
            try
            {
                if (go == null || go.GraphicsStyleId == ElementId.InvalidElementId) return "";
                if (!(doc.GetElement(go.GraphicsStyleId) is GraphicsStyle gs)) return "";

                Autodesk.Revit.DB.Color color = gs.GraphicsStyleCategory?.LineColor;
                if (color == null || !color.IsValid) return "";

                return color.Red.ToString(CultureInfo.InvariantCulture) + "," +
                       color.Green.ToString(CultureInfo.InvariantCulture) + "," +
                       color.Blue.ToString(CultureInfo.InvariantCulture);
            }
            catch
            {
                return "";
            }
        }

        private static List<string> CollectCadLayers(Document doc, ImportInstance cad)
        {
            var layers = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return layers.OrderBy(l => l).ToList();

            foreach (GeometryObject go in ge)
            {
                CollectLayersFromGeom(doc, go, layers);
            }

            return layers.OrderBy(l => l).ToList();
        }

        private List<XYZ> BuildPointsFromHits(CadShapeHits hits)
        {
            var points = new List<XYZ>();
            if (hits == null) return points;

            if (Request.UseCircles)
            {
                points.AddRange(hits.CircleCenters);
            }

            if (Request.UseBlocks)
            {
                points.AddRange(hits.BlockPoints);
            }

            if (Request.UseLineIntersections)
            {
                if (hits.Lines.Count > 1)
                {
                    points.AddRange(FindLineIntersections(hits.Lines, GetTasCadLineSearchDistanceFt(0.0), GetTasParallelAngleEpsilonDeg()));
                }

                if (hits.Polylines.Count > 0)
                {
                    points.AddRange(hits.Polylines.Select(p => p.Center));
                }
            }

            return points;
        }

        private static Dictionary<string, ColumnSectionSpec> BuildSpecNameMap(List<ColumnSectionSpec> specs)
        {
            var map = new Dictionary<string, ColumnSectionSpec>(StringComparer.OrdinalIgnoreCase);
            if (specs == null) return map;

            foreach (ColumnSectionSpec spec in specs)
            {
                if (spec == null || string.IsNullOrWhiteSpace(spec.Name)) continue;
                string key = NormalizeSectionKey(spec.Name);
                if (string.IsNullOrWhiteSpace(key)) continue;
                map[key] = spec;
            }

            return map;
        }

        private static Dictionary<string, ColumnSectionSpec> BuildSpecSizeMap(List<ColumnSectionSpec> specs)
        {
            var map = new Dictionary<string, ColumnSectionSpec>(StringComparer.OrdinalIgnoreCase);
            if (specs == null) return map;

            foreach (ColumnSectionSpec spec in specs)
            {
                if (spec == null) continue;
                if (spec.WidthMm <= 0 || spec.LengthMm <= 0) continue;
                string key = NormalizeSizeKey(spec.WidthMm, spec.LengthMm);
                if (string.IsNullOrWhiteSpace(key)) continue;
                if (!map.ContainsKey(key))
                {
                    map[key] = spec;
                }
            }

            return map;
        }

