        private void EnsureColumnTypesFromExcel(
            Document doc,
            FamilySymbol baseType,
            List<ColumnSectionSpec> specs,
            Dictionary<ColumnSectionSpec, FamilySymbol> typeBySpec,
            Dictionary<string, FamilySymbol> typeByName,
            out int created,
            out int skipped)
        {
            created = 0;
            skipped = 0;

            if (doc == null || baseType == null || specs == null || specs.Count == 0) return;

            List<FamilySymbol> familyTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Family != null && fs.Family.Id == baseType.Family.Id)
                .ToList();

            foreach (ColumnSectionSpec spec in specs)
            {
                if (spec == null || string.IsNullOrWhiteSpace(spec.Name))
                {
                    skipped++;
                    continue;
                }

                string normalizedName = NormalizeSectionKey(spec.Name);
                if (string.IsNullOrWhiteSpace(normalizedName))
                {
                    skipped++;
                    continue;
                }

                FamilySymbol type = familyTypes
                    .FirstOrDefault(fs => string.Equals(fs.Name, spec.Name, StringComparison.OrdinalIgnoreCase));

                bool createdType = false;
                if (type == null)
                {
                    ElementType newType = baseType.Duplicate(spec.Name);
                    type = newType as FamilySymbol;
                    if (type != null)
                    {
                        familyTypes.Add(type);
                        created++;
                        createdType = true;
                    }
                }

                if (type == null)
                {
                    skipped++;
                    continue;
                }

                if (!TrySetColumnTypeDimensions(type, spec.WidthMm, spec.LengthMm))
                {
                    if (createdType)
                    {
                        skipped++;
                        continue;
                    }
                }

                typeBySpec[spec] = type;
                typeByName[normalizedName] = type;
            }
        }

        private void EnsureWallTypesFromExcel(
            Document doc,
            WallType baseType,
            List<WallSectionSpec> specs,
            Dictionary<WallSectionSpec, WallType> typeBySpec,
            Dictionary<string, WallType> typeByName,
            out int created,
            out int skipped)
        {
            created = 0;
            skipped = 0;

            if (doc == null || baseType == null || specs == null || specs.Count == 0) return;

            List<WallType> wallTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(WallType))
                .Cast<WallType>()
                .Where(wt => wt.FamilyName == baseType.FamilyName)
                .ToList();

            foreach (WallSectionSpec spec in specs)
            {
                if (spec == null || string.IsNullOrWhiteSpace(spec.Name))
                {
                    skipped++;
                    continue;
                }

                string normalizedName = NormalizeSectionKey(spec.Name);
                if (string.IsNullOrWhiteSpace(normalizedName))
                {
                    skipped++;
                    continue;
                }

                WallType type = wallTypes
                    .FirstOrDefault(wt => string.Equals(wt.Name, spec.Name, StringComparison.OrdinalIgnoreCase));

                bool createdType = false;
                if (type == null)
                {
                    ElementType newType = baseType.Duplicate(spec.Name);
                    type = newType as WallType;
                    if (type != null)
                    {
                        wallTypes.Add(type);
                        created++;
                        createdType = true;
                    }
                }

                if (type == null)
                {
                    skipped++;
                    continue;
                }

                if (!TrySetWallTypeWidth(type, spec.WidthMm))
                {
                    if (createdType)
                    {
                        skipped++;
                        continue;
                    }
                }

                typeBySpec[spec] = type;
                typeByName[normalizedName] = type;
            }
        }

        private bool TrySetWallTypeWidth(WallType type, double widthMm)
        {
            if (type == null || widthMm <= 0) return false;

            Parameter widthParam = type.get_Parameter(BuiltInParameter.WALL_ATTR_WIDTH_PARAM) ?? type.Parameters
                    .Cast<Parameter>()
                    .FirstOrDefault(p => p != null && p.Definition != null &&
                                         p.Definition.Name.Equals("Width", StringComparison.OrdinalIgnoreCase));
            if (widthParam == null || widthParam.IsReadOnly || widthParam.StorageType != StorageType.Double)
            {
                return false;
            }

            widthParam.Set(MmToFeet(widthMm));
            return true;
        }

        private static Dictionary<string, FloorType> BuildFloorTypeNameMap(List<FloorType> types)
        {
            var map = new Dictionary<string, FloorType>(StringComparer.OrdinalIgnoreCase);
            if (types == null) return map;

            foreach (FloorType type in types)
            {
                if (type == null) continue;

                AddFloorTypeNameKey(map, type.Name, type);
                if (!string.IsNullOrWhiteSpace(type.FamilyName))
                {
                    AddFloorTypeNameKey(map, $"{type.FamilyName}:{type.Name}", type);
                    AddFloorTypeNameKey(map, $"{type.FamilyName} {type.Name}", type);
                }
            }

            return map;
        }

        private static void AddFloorTypeNameKey(Dictionary<string, FloorType> map, string name, FloorType type)
        {
            if (map == null || type == null || string.IsNullOrWhiteSpace(name)) return;
            string key = NormalizeSectionKey(name);
            if (string.IsNullOrWhiteSpace(key)) return;
            map[key] = type;
        }

        private static Dictionary<string, List<FloorType>> BuildFloorTypeThicknessMap(List<FloorType> types)
        {
            var map = new Dictionary<string, List<FloorType>>(StringComparer.OrdinalIgnoreCase);
            if (types == null) return map;

            foreach (FloorType type in types)
            {
                if (type == null) continue;
                double thicknessMm = GetFloorTypeThicknessMm(type);
                if (thicknessMm <= 0) continue;

                string key = NormalizeSlabThicknessKey(thicknessMm);
                if (string.IsNullOrWhiteSpace(key)) continue;

                if (!map.TryGetValue(key, out List<FloorType> list))
                {
                    list = new List<FloorType>();
                    map[key] = list;
                }

                list.Add(type);
            }

            return map;
        }

        private static FloorType ResolveSlabTypeForSpec(
            SlabSectionSpec spec,
            FloorType defaultType,
            Dictionary<string, FloorType> typeByName,
            Dictionary<string, List<FloorType>> typeByThickness)
        {
            if (spec == null) return defaultType;

            if (typeByName != null && !string.IsNullOrWhiteSpace(spec.Name))
            {
                string nameKey = NormalizeSectionKey(spec.Name);
                if (!string.IsNullOrWhiteSpace(nameKey) && typeByName.TryGetValue(nameKey, out FloorType typeByNm))
                {
                    return typeByNm ?? defaultType;
                }
            }

            if (spec.ThicknessMm > 0 && typeByThickness != null)
            {
                string key = NormalizeSlabThicknessKey(spec.ThicknessMm);
                return ResolveSlabTypeForThicknessKey(key, defaultType, typeByThickness);
            }

            return defaultType;
        }

        private static FloorType ResolveSlabTypeForThicknessKey(
            string key,
            FloorType defaultType,
            Dictionary<string, List<FloorType>> typeByThickness)
        {
            if (string.IsNullOrWhiteSpace(key) || typeByThickness == null) return defaultType;

            if (!typeByThickness.TryGetValue(key, out List<FloorType> list) || list.Count == 0)
            {
                return defaultType;
            }

            if (defaultType != null)
            {
                FloorType match = list.FirstOrDefault(t => t != null &&
                                                           !string.IsNullOrWhiteSpace(t.FamilyName) &&
                                                           string.Equals(t.FamilyName, defaultType.FamilyName, StringComparison.OrdinalIgnoreCase));
                if (match != null) return match;
            }

            return list[0] ?? defaultType;
        }

        private static double GetFloorTypeThicknessMm(FloorType type)
        {
            if (type == null) return 0;

            CompoundStructure structure = type.GetCompoundStructure();
            if (structure != null)
            {
                IList<CompoundStructureLayer> layers = structure.GetLayers();
                if (layers != null && layers.Count > 0)
                {
                    double totalFt = 0.0;
                    foreach (CompoundStructureLayer layer in layers)
                    {
                        totalFt += layer.Width;
                    }

                    if (totalFt > 0)
                    {
                        return FeetToMm(totalFt);
                    }
                }
            }

            Parameter thicknessParam = type.get_Parameter(BuiltInParameter.FLOOR_ATTR_THICKNESS_PARAM);
            if (thicknessParam != null && thicknessParam.StorageType == StorageType.Double)
            {
                double val = thicknessParam.AsDouble();
                if (val > 0)
                {
                    return FeetToMm(val);
                }
            }

            return 0;
        }

        private bool TrySetColumnTypeDimensions(FamilySymbol type, double widthMm, double lengthMm)
        {
            if (type == null || widthMm <= 0 || lengthMm <= 0) return false;

            Parameter widthParam = FindColumnDimensionParameter(type, new[]
            {
                "b", "width", "w", "dim b", "dim_b", "b1"
            });
            Parameter lengthParam = FindColumnDimensionParameter(type, new[]
            {
                "h", "depth", "height", "d", "dim h", "dim_h", "h1"
            });

            if (widthParam == null || lengthParam == null)
            {
                return false;
            }

            double widthFt = MmToFeet(widthMm);
            double lengthFt = MmToFeet(lengthMm);

            if (!widthParam.IsReadOnly && widthParam.StorageType == StorageType.Double)
            {
                widthParam.Set(widthFt);
            }
            else
            {
                return false;
            }

            if (!lengthParam.IsReadOnly && lengthParam.StorageType == StorageType.Double)
            {
                lengthParam.Set(lengthFt);
            }
            else
            {
                return false;
            }

            return true;
        }

        private static Parameter FindColumnDimensionParameter(FamilySymbol type, IEnumerable<string> tokens)
        {
            if (type == null) return null;

            IList<Parameter> parameters = type.Parameters.Cast<Parameter>().ToList();
            foreach (string token in tokens)
            {
                Parameter param = parameters.FirstOrDefault(p =>
                    p != null &&
                    p.Definition != null &&
                    string.Equals(p.Definition.Name, token, StringComparison.OrdinalIgnoreCase));
                if (param != null) return param;
            }

            foreach (string token in tokens)
            {
                Parameter param = parameters.FirstOrDefault(p =>
                    p != null &&
                    p.Definition != null &&
                    p.Definition.Name.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0);
                if (param != null) return param;
            }

            return null;
        }

        private ColumnSectionSpec ResolveColumnSpecForPoint(
            XYZ point,
            CadShapeHits hits,
            List<CadTextLabel> labels,
            Dictionary<string, ColumnSectionSpec> specByName,
            Dictionary<string, ColumnSectionSpec> specBySize,
            ColumnSectionSpec layerSpec,
            double labelSearchMaxDistFt)
        {
            if (point == null) return null;

            if (labels != null && labels.Count > 0)
            {
                ColumnSectionSpec spec = FindNearestSpecFromLabels(point, labels, specByName, specBySize, labelSearchMaxDistFt);
                if (spec != null) return spec;
            }

            if (Request.UseBlocks && hits?.Blocks != null && hits.Blocks.Count > 0)
            {
                string blockName = FindBlockNameForPoint(point, hits.Blocks, MmToFeet(5.0));
                ColumnSectionSpec spec = MatchSpecFromLabel(blockName, specByName, specBySize, false);
                if (spec != null) return spec;
            }

            if (hits?.Polylines != null && hits.Polylines.Count > 0)
            {
                CadPolylineHit poly = FindPolylineHitForPoint(point, hits.Polylines, MmToFeet(50.0));
                if (poly != null && poly.WidthMm > 0 && poly.LengthMm > 0)
                {
                    string sizeKey = NormalizeSizeKey(poly.WidthMm, poly.LengthMm);
                    if (!string.IsNullOrWhiteSpace(sizeKey) && specBySize.TryGetValue(sizeKey, out ColumnSectionSpec specBySz))
                    {
                        return specBySz;
                    }
                }
            }

            if (labels != null && labels.Count > 0)
            {
                if (TryGetNearestSizeFromTwoLabels(point, labels, MmToFeet(1200.0), out double wMm, out double lMm))
                {
                    string sizeKey = NormalizeSizeKey(wMm, lMm);
                    if (!string.IsNullOrWhiteSpace(sizeKey) && specBySize.TryGetValue(sizeKey, out ColumnSectionSpec specBySz))
                    {
                        return specBySz;
                    }
                }
            }

            return layerSpec;
        }

        private static ColumnSectionSpec FindNearestSpecFromLabels(
            XYZ point,
            List<CadTextLabel> labels,
            Dictionary<string, ColumnSectionSpec> specByName,
            Dictionary<string, ColumnSectionSpec> specBySize,
            double maxDistFt)
        {
            ColumnSectionSpec bestByExactName = null;
            double bestByExactNameDist = double.MaxValue;
            ColumnSectionSpec bestByName = null;
            double bestByNameDist = double.MaxValue;
            ColumnSectionSpec bestBySize = null;
            double bestBySizeDist = double.MaxValue;

            foreach (CadTextLabel label in labels)
            {
                if (label == null) continue;
                double dist = label.Position.DistanceTo(point);
                if (dist > maxDistFt) continue;

                if (TryMatchColumnSpecByExactName(label.Text, specByName, out ColumnSectionSpec specByExactName))
                {
                    if (dist < bestByExactNameDist)
                    {
                        bestByExactNameDist = dist;
                        bestByExactName = specByExactName;
                    }
                    continue;
                }

                if (TryMatchColumnSpecByName(label.Text, specByName, out ColumnSectionSpec specByLooseName))
                {
                    if (dist < bestByNameDist)
                    {
                        bestByNameDist = dist;
                        bestByName = specByLooseName;
                    }
                    continue;
                }

                if (specBySize == null) continue;
                if (!TryParseSizeLabel(label.Text, out double w, out double l)) continue;

                string sizeKey = NormalizeSizeKey(w, l);
                if (string.IsNullOrWhiteSpace(sizeKey)) continue;
                if (!specBySize.TryGetValue(sizeKey, out ColumnSectionSpec specBySizeLabel)) continue;

                if (dist < bestBySizeDist)
                {
                    bestBySizeDist = dist;
                    bestBySize = specBySizeLabel;
                }
            }

            return bestByExactName ?? bestByName ?? bestBySize;
        }

        private static ColumnSectionSpec MatchSpecFromLabel(
            string text,
            Dictionary<string, ColumnSectionSpec> specByName,
            Dictionary<string, ColumnSectionSpec> specBySize,
            bool allowLooseNameMatch = true)
        {
            if (string.IsNullOrWhiteSpace(text)) return null;

            bool hasNameMatch = allowLooseNameMatch
                ? TryMatchColumnSpecByName(text, specByName, out ColumnSectionSpec specByKey)
                : TryMatchColumnSpecByExactName(text, specByName, out specByKey);
            if (hasNameMatch)
            {
                return specByKey;
            }

            if (TryParseSizeLabel(text, out double w, out double l))
            {
                string sizeKey = NormalizeSizeKey(w, l);
                if (!string.IsNullOrWhiteSpace(sizeKey) && specBySize.TryGetValue(sizeKey, out ColumnSectionSpec specBySz))
                {
                    return specBySz;
                }
            }

            return null;
        }

        private static bool TryMatchColumnSpecByExactName(
            string text,
            Dictionary<string, ColumnSectionSpec> specByName,
            out ColumnSectionSpec spec)
        {
            spec = null;
            if (string.IsNullOrWhiteSpace(text) || specByName == null || specByName.Count == 0)
            {
                return false;
            }

            string key = NormalizeSectionKey(text);
            if (string.IsNullOrWhiteSpace(key))
            {
                return false;
            }

            if (specByName.TryGetValue(key, out ColumnSectionSpec exact))
            {
                spec = exact;
                return true;
            }

            return false;
        }

        private static bool TryMatchColumnSpecByName(
            string text,
            Dictionary<string, ColumnSectionSpec> specByName,
            out ColumnSectionSpec spec)
        {
            spec = null;
            if (string.IsNullOrWhiteSpace(text) || specByName == null || specByName.Count == 0)
            {
                return false;
            }

            string key = NormalizeSectionKey(text);
            if (!string.IsNullOrWhiteSpace(key) && specByName.TryGetValue(key, out ColumnSectionSpec exact))
            {
                spec = exact;
                return true;
            }

            string[] tokens = text.Split(new[]
            {
                ' ', '\t', '\r', '\n', ',', ';', ':', '|',
                '{', '}', '[', ']', '(', ')', '<', '>', '/', '\\', '"'
            }, StringSplitOptions.RemoveEmptyEntries);

            foreach (string rawToken in tokens)
            {
                string token = NormalizeSectionKey(rawToken);
                if (string.IsNullOrWhiteSpace(token))
                {
                    continue;
                }

                if (specByName.TryGetValue(token, out ColumnSectionSpec tokenExact))
                {
                    spec = tokenExact;
                    return true;
                }

                if (TryMatchColumnSpecBySuffix(token, specByName, out ColumnSectionSpec tokenSuffix))
                {
                    spec = tokenSuffix;
                    return true;
                }
            }

            if (TryMatchColumnSpecBySuffix(key, specByName, out ColumnSectionSpec fullSuffix))
            {
                spec = fullSuffix;
                return true;
            }

            return false;
        }

        private static bool TryMatchColumnSpecBySuffix(
            string key,
            Dictionary<string, ColumnSectionSpec> specByName,
            out ColumnSectionSpec spec)
        {
            spec = null;
            if (string.IsNullOrWhiteSpace(key) || specByName == null || specByName.Count == 0)
            {
                return false;
            }

            int bestLen = 0;
            foreach (KeyValuePair<string, ColumnSectionSpec> pair in specByName)
            {
                string specKey = pair.Key;
                if (string.IsNullOrWhiteSpace(specKey)) continue;
                if (specKey.Length <= bestLen) continue;
                if (key.Length <= specKey.Length) continue;
                if (!key.EndsWith(specKey, StringComparison.OrdinalIgnoreCase)) continue;

                bestLen = specKey.Length;
                spec = pair.Value;
            }

            return spec != null;
        }

        private static WallSectionSpec MatchWallSpecFromLabel(
            string text,
            Dictionary<string, WallSectionSpec> specByName,
            Dictionary<string, WallSectionSpec> specBySize)
        {
            if (string.IsNullOrWhiteSpace(text)) return null;

            string key = NormalizeSectionKey(text);
            if (!string.IsNullOrWhiteSpace(key) && specByName.TryGetValue(key, out WallSectionSpec specByKey))
            {
                return specByKey;
            }

            if (TryParseWallWidthLabel(text, out double widthMm))
            {
                string sizeKey = NormalizeWallSizeKey(widthMm);
                if (!string.IsNullOrWhiteSpace(sizeKey) && specBySize.TryGetValue(sizeKey, out WallSectionSpec specBySz))
                {
                    return specBySz;
                }
            }

            return null;
        }

        private static SlabSectionSpec MatchSlabSpecFromLabel(
            string text,
            Dictionary<string, SlabSectionSpec> specByName,
            Dictionary<string, SlabSectionSpec> specByThickness)
        {
            if (string.IsNullOrWhiteSpace(text)) return null;

            string key = NormalizeSectionKey(text);
            if (!string.IsNullOrWhiteSpace(key) && specByName.TryGetValue(key, out SlabSectionSpec specByKey))
            {
                return specByKey;
            }

            if (TryParseSlabThicknessLabel(text, out double thicknessMm))
            {
                string sizeKey = NormalizeSlabThicknessKey(thicknessMm);
                if (!string.IsNullOrWhiteSpace(sizeKey) && specByThickness.TryGetValue(sizeKey, out SlabSectionSpec specBySz))
                {
                    return specBySz;
                }
            }

            return null;
        }

        private SlabSectionSpec ResolveSlabSpecForLoop(
            CurveLoop loop,
            List<CadTextLabel> labels,
            Dictionary<string, SlabSectionSpec> specByName,
            Dictionary<string, SlabSectionSpec> specByThickness,
            SlabSectionSpec layerSpec)
        {
            if (loop == null) return layerSpec;

            XYZ sample = GetLoopSamplePoint(loop);
            if (labels != null && labels.Count > 0)
            {
                SlabSectionSpec spec = FindNearestSlabSpecFromLabels(sample, labels, specByName, specByThickness, MmToFeet(1200.0));
                if (spec != null) return spec;
            }

            return layerSpec;
        }

        private WallSectionSpec ResolveWallSpecForLine(
            Line line,
            List<CadTextLabel> labels,
            Dictionary<string, WallSectionSpec> specByName,
            Dictionary<string, WallSectionSpec> specBySize,
            WallSectionSpec layerSpec)
        {
            if (line == null) return layerSpec;

            XYZ mid = (line.GetEndPoint(0) + line.GetEndPoint(1)) * 0.5;

            if (labels != null && labels.Count > 0)
            {
                WallSectionSpec spec = FindNearestWallSpecFromLabels(mid, labels, specByName, specBySize, MmToFeet(1200.0));
                if (spec != null) return spec;
            }

            return layerSpec;
        }

        private static SlabSectionSpec FindNearestSlabSpecFromLabels(
            XYZ point,
            List<CadTextLabel> labels,
            Dictionary<string, SlabSectionSpec> specByName,
            Dictionary<string, SlabSectionSpec> specByThickness,
            double maxDistFt)
        {
            SlabSectionSpec best = null;
            double bestDist = double.MaxValue;

            foreach (CadTextLabel label in labels)
            {
                if (label == null) continue;
                double dist = label.Position.DistanceTo(point);
                if (dist > maxDistFt) continue;

                SlabSectionSpec spec = MatchSlabSpecFromLabel(label.Text, specByName, specByThickness);
                if (spec == null) continue;

                if (dist < bestDist)
                {
                    bestDist = dist;
                    best = spec;
                }
            }

            return best;
        }

        private static WallSectionSpec FindNearestWallSpecFromLabels(
            XYZ point,
            List<CadTextLabel> labels,
            Dictionary<string, WallSectionSpec> specByName,
            Dictionary<string, WallSectionSpec> specBySize,
            double maxDistFt)
        {
            WallSectionSpec best = null;
            double bestDist = double.MaxValue;

            foreach (CadTextLabel label in labels)
            {
                if (label == null) continue;
                double dist = label.Position.DistanceTo(point);
                if (dist > maxDistFt) continue;

                WallSectionSpec spec = MatchWallSpecFromLabel(label.Text, specByName, specBySize);
                if (spec == null) continue;

                if (dist < bestDist)
                {
                    bestDist = dist;
                    best = spec;
                }
            }

            return best;
        }

        private static bool TryGetNearestSizeFromTwoLabels(
            XYZ point,
            List<CadTextLabel> labels,
            double maxDistFt,
            out double widthMm,
            out double lengthMm)
        {
            widthMm = 0;
            lengthMm = 0;

            if (labels == null || labels.Count == 0) return false;

            var candidates = new List<(double Dist, double ValueMm)>();
            foreach (CadTextLabel label in labels)
            {
                if (label == null) continue;
                if (!TryParseSingleNumberLabel(label.Text, out double valMm)) continue;

                double dist = label.Position.DistanceTo(point);
                if (dist <= maxDistFt)
                {
                    candidates.Add((dist, valMm));
                }
            }

            if (candidates.Count < 2) return false;

            candidates.Sort((a, b) => a.Dist.CompareTo(b.Dist));
            widthMm = candidates[0].ValueMm;
            lengthMm = candidates[1].ValueMm;
            return widthMm > 0 && lengthMm > 0;
        }

        private static bool TryParseSingleNumberLabel(string text, out double valueMm)
        {
            valueMm = 0;
            if (string.IsNullOrWhiteSpace(text)) return false;

            if (!TryParseNumber(text, out double value))
            {
                return false;
            }

            valueMm = NormalizeLengthToMm(value, text);
            return valueMm > 0;
        }

        private static string FindBlockNameForPoint(XYZ point, List<CadBlockHit> blocks, double tolFt)
        {
            if (blocks == null || blocks.Count == 0) return "";

            foreach (CadBlockHit hit in blocks)
            {
                if (hit == null) continue;
                if (hit.Point.DistanceTo(point) <= tolFt)
                {
                    return hit.Name ?? "";
                }
            }

            return "";
        }

        private static string NormalizeSectionKey(string text)
        {
            if (string.IsNullOrWhiteSpace(text)) return "";

            var chars = new List<char>(text.Length);
            foreach (char c in text)
            {
                if (char.IsLetterOrDigit(c) || c == '\'' || c == '-')
                {
                    chars.Add(char.ToUpperInvariant(c));
                }
            }

            return new string(chars.ToArray());
        }

        private static List<ColumnSectionSpec> ParseColumnScheduleFromLabels(List<CadTextLabel> labels)
        {
            var specs = new List<ColumnSectionSpec>();
            if (labels == null || labels.Count == 0) return specs;

            CadTextLabel headerMark = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "MARK"));
            CadTextLabel headerType = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "TYPE"));

            if (headerMark == null || headerType == null)
            {
                return ParseColumnScheduleRowsByMarkAndSize(labels);
            }

            double minY = labels.Min(l => l.Position.Y);
            double maxY = labels.Max(l => l.Position.Y);
            double rowTol = Math.Max((maxY - minY) * 0.03, MmToFeet(50.0));

            var content = labels
                .Where(l => l != headerMark && l != headerType)
                .OrderByDescending(l => l.Position.Y)
                .ToList();

            var rows = new List<RowBucket>();
            foreach (CadTextLabel label in content)
            {
                if (IsHeaderLabel(label.Text, "SCHEDULE")) continue;

                RowBucket bucket = rows.FirstOrDefault(r => Math.Abs(r.CenterY - label.Position.Y) <= rowTol);
                if (bucket == null)
                {
                    bucket = new RowBucket(label.Position.Y);
                    rows.Add(bucket);
                }

                bucket.Add(label);
            }

            foreach (RowBucket row in rows)
            {
                CadTextLabel markLabel = row.FindClosestToX(headerMark.Position.X);
                CadTextLabel typeLabel = row.FindClosestToX(headerType.Position.X);

                if (markLabel == null || typeLabel == null) continue;

                string name = CleanScheduleName(markLabel.Text);
                if (string.IsNullOrWhiteSpace(name)) continue;

                if (!TryParseSizeLabel(typeLabel.Text, out double wMm, out double lMm))
                {
                    continue;
                }

                specs.Add(new ColumnSectionSpec
                {
                    Name = name,
                    WidthMm = wMm,
                    LengthMm = lMm
                });
            }

            return specs;
        }

        private static List<ColumnSectionSpec> ParseColumnScheduleRowsByMarkAndSize(List<CadTextLabel> labels)
        {
            var specs = new List<ColumnSectionSpec>();
            if (labels == null || labels.Count == 0)
            {
                return specs;
            }

            double minY = labels.Min(l => l.Position.Y);
            double maxY = labels.Max(l => l.Position.Y);
            double rowTol = Math.Max((maxY - minY) * 0.05, MmToFeet(50.0));

            var rows = new List<List<CadTextLabel>>();
            foreach (CadTextLabel label in labels
                         .Where(l => l != null && !string.IsNullOrWhiteSpace(l.Text))
                         .OrderByDescending(l => l.Position.Y))
            {
                if (IsHeaderLabel(label.Text, "SCHEDULE") ||
                    IsHeaderLabel(label.Text, "MARK") ||
                    IsHeaderLabel(label.Text, "TYPE"))
                {
                    continue;
                }

                List<CadTextLabel> row = rows.FirstOrDefault(r =>
                    r.Count > 0 && Math.Abs(r.Average(l => l.Position.Y) - label.Position.Y) <= rowTol);
                if (row == null)
                {
                    row = new List<CadTextLabel>();
                    rows.Add(row);
                }

                row.Add(label);
            }

            var byName = new Dictionary<string, ColumnSectionSpec>(StringComparer.OrdinalIgnoreCase);
            foreach (List<CadTextLabel> row in rows)
            {
                CadTextLabel sizeLabel = row
                    .Where(l => TryParseSizeLabel(l.Text, out _, out _))
                    .OrderBy(l => l.Position.X)
                    .LastOrDefault();
                if (sizeLabel == null ||
                    !TryParseSizeLabel(sizeLabel.Text, out double widthMm, out double lengthMm))
                {
                    continue;
                }

                CadTextLabel markLabel = row
                    .Where(l => !ReferenceEquals(l, sizeLabel) && IsLikelyScheduleMark(l.Text))
                    .OrderBy(l => l.Position.X)
                    .FirstOrDefault();
                if (markLabel == null)
                {
                    markLabel = row
                        .Where(l => !ReferenceEquals(l, sizeLabel) && !TryParseSizeLabel(l.Text, out _, out _))
                        .OrderBy(l => l.Position.X)
                        .FirstOrDefault();
                }

                if (markLabel == null)
                {
                    continue;
                }

                string name = CleanScheduleName(markLabel.Text);
                if (string.IsNullOrWhiteSpace(name))
                {
                    continue;
                }

                byName[name] = new ColumnSectionSpec
                {
                    Name = name,
                    WidthMm = widthMm,
                    LengthMm = lengthMm
                };
            }

            specs.AddRange(byName.Values);
            return specs;
        }

        private static List<List<string>> BuildColumnScheduleTableRowsFromLabels(List<CadTextLabel> labels)
        {
            var rows = new List<List<string>>();
            if (labels == null || labels.Count == 0)
            {
                return rows;
            }

            CadTextLabel headerMark = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "MARK"));
            CadTextLabel headerType = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "TYPE"));

            rows.Add(new List<string> { "MARK", "TYPE", "Corresponding Floor" });

            double minY = labels.Min(l => l.Position.Y);
            double maxY = labels.Max(l => l.Position.Y);
            double rowTol = Math.Max((maxY - minY) * 0.05, MmToFeet(50.0));

            List<List<CadTextLabel>> buckets = BuildCadTextRows(labels, rowTol);

            var byName = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            foreach (List<CadTextLabel> row in buckets)
            {
                if (row == null || row.Count == 0)
                {
                    continue;
                }

                if (row.Any(l => IsHeaderLabel(l.Text, "SCHEDULE")))
                {
                    continue;
                }

                CadTextLabel markLabel = null;
                CadTextLabel typeLabel = null;

                if (headerMark != null && headerType != null)
                {
                    markLabel = row
                        .Where(l => !ReferenceEquals(l, headerMark) && !ReferenceEquals(l, headerType))
                        .OrderBy(l => Math.Abs(l.Position.X - headerMark.Position.X))
                        .FirstOrDefault();
                    typeLabel = row
                        .Where(l => !ReferenceEquals(l, headerMark) && !ReferenceEquals(l, headerType) && !ReferenceEquals(l, markLabel))
                        .OrderBy(l => Math.Abs(l.Position.X - headerType.Position.X))
                        .FirstOrDefault();
                }

                if (markLabel == null || typeLabel == null || !TryParseSizeLabel(typeLabel.Text, out _, out _))
                {
                    typeLabel = row
                        .Where(l => TryParseSizeLabel(l.Text, out _, out _))
                        .OrderBy(l => l.Position.X)
                        .LastOrDefault();
                    markLabel = row
                        .Where(l => !ReferenceEquals(l, typeLabel) && IsLikelyScheduleMark(l.Text))
                        .OrderBy(l => l.Position.X)
                        .FirstOrDefault();
                }

                if (markLabel == null || typeLabel == null)
                {
                    continue;
                }

                string name = CleanScheduleName(markLabel.Text);
                if (string.IsNullOrWhiteSpace(name) || IsHeaderLabel(name, "MARK"))
                {
                    continue;
                }

                string sizeText = NormalizeColumnScheduleSizeText(typeLabel.Text);
                if (string.IsNullOrWhiteSpace(sizeText) || IsHeaderLabel(sizeText, "TYPE"))
                {
                    continue;
                }

                byName[name] = new List<string>
                {
                    name,
                    sizeText,
                    "Zone-1[0]"
                };
            }

            foreach (List<string> row in byName.Values.OrderBy(r => NaturalScheduleSortKey(r[0])))
            {
                rows.Add(row);
            }

            if (rows.Count <= 1)
            {
                rows.Clear();
            }

            return rows;
        }

        private static List<List<CadTextLabel>> BuildCadTextRows(List<CadTextLabel> labels, double rowTol)
        {
            var rows = new List<List<CadTextLabel>>();
            if (labels == null)
            {
                return rows;
            }

            foreach (CadTextLabel label in labels
                         .Where(l => l != null && !string.IsNullOrWhiteSpace(l.Text))
                         .OrderByDescending(l => l.Position.Y)
                         .ThenBy(l => l.Position.X))
            {
                List<CadTextLabel> row = rows.FirstOrDefault(r =>
                    r.Count > 0 && Math.Abs(r.Average(l => l.Position.Y) - label.Position.Y) <= rowTol);
                if (row == null)
                {
                    row = new List<CadTextLabel>();
                    rows.Add(row);
                }

                row.Add(label);
            }

            foreach (List<CadTextLabel> row in rows)
            {
                row.Sort((a, b) => a.Position.X.CompareTo(b.Position.X));
            }

            return rows;
        }

        private static List<List<string>> BuildColumnScheduleRowsFromSpecs(List<ColumnSectionSpec> specs)
        {
            var rows = new List<List<string>>
            {
                new List<string> { "MARK", "TYPE", "Corresponding Floor" }
            };

            if (specs != null)
            {
                foreach (ColumnSectionSpec spec in specs
                             .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                             .OrderBy(s => NaturalScheduleSortKey(s.Name)))
                {
                    rows.Add(new List<string>
                    {
                        spec.Name.Trim(),
                        $"({spec.WidthMm:0.###}x{spec.LengthMm:0.###})mm",
                        "Zone-1[0]"
                    });
                }
            }

            if (rows.Count <= 1)
            {
                rows.Clear();
            }

            return rows;
        }

        private static List<List<string>> BuildWallScheduleRowsFromSpecs(List<WallSectionSpec> specs)
        {
            var rows = new List<List<string>>
            {
                new List<string> { "MARK", "Thickness", "Corresponding Floor" }
            };

            if (specs != null)
            {
                foreach (WallSectionSpec spec in specs
                             .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                             .OrderBy(s => NaturalScheduleSortKey(s.Name)))
                {
                    rows.Add(new List<string>
                    {
                        spec.Name.Trim(),
                        spec.WidthMm.ToString("0.###", CultureInfo.InvariantCulture),
                        "Zone-1[0]"
                    });
                }
            }

            if (rows.Count <= 1)
            {
                rows.Clear();
            }

            return rows;
        }

        private static List<List<string>> BuildBeamScheduleRowsFromSpecs(List<BeamSectionSpec> specs)
        {
            var rows = new List<List<string>>
            {
                new List<string> { "MARK", "TYPE", "Corresponding Floor" }
            };

            if (specs != null)
            {
                foreach (BeamSectionSpec spec in specs
                             .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                             .OrderBy(s => NaturalScheduleSortKey(s.Name)))
                {
                    rows.Add(new List<string>
                    {
                        spec.Name.Trim(),
                        $"({spec.WidthMm:0.###}x{spec.DepthMm:0.###})mm",
                        "Zone-1[0]"
                    });
                }
            }

            if (rows.Count <= 1)
            {
                rows.Clear();
            }

            return rows;
        }

        private static string NormalizeColumnScheduleSizeText(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            string cleaned = text.Trim()
                .Replace(" X ", "x")
                .Replace(" x ", "x")
                .Replace(" * ", "x")
                .Replace("*", "x");

            if (!Regex.IsMatch(cleaned, @"mm|cm|m", RegexOptions.IgnoreCase) &&
                Regex.IsMatch(cleaned, @"\d+\s*x\s*\d+", RegexOptions.IgnoreCase))
            {
                cleaned += "mm";
            }

            return cleaned;
        }

        private static string NaturalScheduleSortKey(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            return Regex.Replace(text, @"\d+", m => m.Value.PadLeft(10, '0')).ToUpperInvariant();
        }

        private bool TryStartColumnScheduleScreenOcr(
            UIDocument uidoc,
            PickedBox box,
            out string status)
        {
#if REVIT2025
            status = "";
            CamboBIMWindow window = _window;
            if (window == null)
            {
                status = "Screen OCR could not start because the CamboBIM window is not ready.";
                return false;
            }

            try
            {
                if (!TryGetPickedBoxScreenRectangle(uidoc, box, out DrawingRectangle screenRect, out string rectStatus))
                {
                    status = rectStatus;
                    return false;
                }

                const int maxScreenOcrPixels = 1600000;
                if ((long)screenRect.Width * screenRect.Height > maxScreenOcrPixels)
                {
                    status = "Screen OCR selected area is too large. Zoom closer to the table and drag only the schedule cells.";
                    return false;
                }

                DrawingBitmap capture = CaptureScreenRectangle(screenRect);
                string debugFolder = CreateColumnScheduleOcrDebugFolder();
                _ = Task.Run(async () =>
                {
                    try
                    {
                        using (capture)
                        {
                            TrySaveOcrDebugBitmap(capture, debugFolder, "01-selected-screen.png");

                            List<string> originalLines = await RecognizeOcrLinesAsync(capture).ConfigureAwait(false);
                            List<string> lines = originalLines.ToList();
                            List<List<string>> rows = BuildColumnScheduleRowsFromOcrLines(lines);
                            List<string> preparedLines = new List<string>();
                            if (rows.Count <= 1)
                            {
                                using (DrawingBitmap prepared = PrepareScheduleImageForOcr(capture))
                                {
                                    TrySaveOcrDebugBitmap(prepared, debugFolder, "02-prepared-for-ocr.png");
                                    preparedLines = await RecognizeOcrLinesAsync(prepared).ConfigureAwait(false);
                                    lines = originalLines
                                        .Concat(preparedLines)
                                        .Where(line => !string.IsNullOrWhiteSpace(line))
                                        .Distinct(StringComparer.OrdinalIgnoreCase)
                                        .ToList();
                                    rows = BuildColumnScheduleRowsFromOcrLines(lines);
                                }
                            }

                            TrySaveOcrDebugText(debugFolder, screenRect, originalLines, preparedLines, rows);
                            string doneStatus = rows.Count > 1
                                ? "Screen OCR read " + (rows.Count - 1).ToString(CultureInfo.InvariantCulture) + " schedule row(s)."
                                : "Screen OCR did not find rows like C1 and (250x450)mm. Debug files: " + debugFolder;

                            if (window.Dispatcher == null || window.Dispatcher.HasShutdownStarted)
                            {
                                return;
                            }

                            _ = window.Dispatcher.BeginInvoke(new Action(() =>
                            {
                                if (rows.Count > 1)
                                {
                                    window.OpenColumnScheduleRowsInElementSchedule(rows, "screen OCR schedule");
                                }
                                else
                                {
                                    window.ShowStatus(doneStatus);
                                }
                            }));
                        }
                    }
                    catch (Exception ex)
                    {
                        if (window.Dispatcher == null || window.Dispatcher.HasShutdownStarted)
                        {
                            return;
                        }

                        _ = window.Dispatcher.BeginInvoke(new Action(() =>
                        {
                            window.ShowStatus("Screen OCR failed: " + ex.Message);
                        }));
                    }
                });

                status = "Screen OCR started.";
                return true;
            }
            catch (Exception ex)
            {
                status = "Screen OCR could not start: " + ex.Message;
                return false;
            }
#else
            status = "Screen OCR is available in the Revit 2025 build only.";
            return false;
#endif
        }

        private static List<List<string>> TryReadColumnScheduleRowsFromScreen(
            UIDocument uidoc,
            PickedBox box,
            out string status)
        {
#if REVIT2025
            status = "";
            var empty = new List<List<string>>();
            try
            {
                if (!TryGetPickedBoxScreenRectangle(uidoc, box, out DrawingRectangle screenRect, out string rectStatus))
                {
                    status = rectStatus;
                    return empty;
                }

                using (DrawingBitmap capture = CaptureScreenRectangle(screenRect))
                using (DrawingBitmap prepared = PrepareScheduleImageForOcr(capture))
                {
                    List<string> lines = RecognizeOcrLinesAsync(prepared).GetAwaiter().GetResult();
                    List<List<string>> rows = BuildColumnScheduleRowsFromOcrLines(lines);
                    status = rows.Count > 1
                        ? "OCR read " + (rows.Count - 1).ToString(CultureInfo.InvariantCulture) + " schedule row(s)."
                        : "Screen OCR did not find rows like C1 and (250x450)mm.";
                    return rows;
                }
            }
            catch (Exception ex)
            {
                status = "Screen OCR failed: " + ex.Message;
                return empty;
            }
#else
            status = "Screen OCR is available in the Revit 2025 build only.";
            return new List<List<string>>();
#endif
        }

#if REVIT2025
        private static bool TryGetPickedBoxScreenRectangle(
            UIDocument uidoc,
            PickedBox box,
            out DrawingRectangle screenRect,
            out string status)
        {
            screenRect = DrawingRectangle.Empty;
            status = "";

            if (uidoc == null || uidoc.Document == null || box == null)
            {
                status = "Screen OCR could not read the selected area.";
                return false;
            }

            UIView uiView = uidoc.GetOpenUIViews()
                .FirstOrDefault(v => v != null && v.ViewId == uidoc.Document.ActiveView.Id);
            if (uiView == null)
            {
                status = "Screen OCR could not find the active Revit view.";
                return false;
            }

            IList<XYZ> zoomCorners = uiView.GetZoomCorners();
            if (zoomCorners == null || zoomCorners.Count < 2)
            {
                status = "Screen OCR could not read the active view zoom area.";
                return false;
            }

            var viewRect = uiView.GetWindowRectangle();
            int viewWidth = Math.Abs(viewRect.Right - viewRect.Left);
            int viewHeight = Math.Abs(viewRect.Bottom - viewRect.Top);
            if (viewWidth <= 10 || viewHeight <= 10)
            {
                status = "Screen OCR could not read the active view window.";
                return false;
            }

            double viewMinX = Math.Min(zoomCorners[0].X, zoomCorners[1].X);
            double viewMaxX = Math.Max(zoomCorners[0].X, zoomCorners[1].X);
            double viewMinY = Math.Min(zoomCorners[0].Y, zoomCorners[1].Y);
            double viewMaxY = Math.Max(zoomCorners[0].Y, zoomCorners[1].Y);
            if (viewMaxX <= viewMinX || viewMaxY <= viewMinY)
            {
                status = "Screen OCR could not map model coordinates to screen coordinates.";
                return false;
            }

            double pickMinX = Math.Min(box.Min.X, box.Max.X);
            double pickMaxX = Math.Max(box.Min.X, box.Max.X);
            double pickMinY = Math.Min(box.Min.Y, box.Max.Y);
            double pickMaxY = Math.Max(box.Min.Y, box.Max.Y);

            int x0 = viewRect.Left + (int)Math.Round((pickMinX - viewMinX) / (viewMaxX - viewMinX) * viewWidth);
            int x1 = viewRect.Left + (int)Math.Round((pickMaxX - viewMinX) / (viewMaxX - viewMinX) * viewWidth);
            int y0 = viewRect.Top + (int)Math.Round((viewMaxY - pickMaxY) / (viewMaxY - viewMinY) * viewHeight);
            int y1 = viewRect.Top + (int)Math.Round((viewMaxY - pickMinY) / (viewMaxY - viewMinY) * viewHeight);

            int left = Math.Min(x0, x1);
            int top = Math.Min(y0, y1);
            int right = Math.Max(x0, x1);
            int bottom = Math.Max(y0, y1);

            int padX = Math.Max(18, (right - left) / 12);
            int padY = Math.Max(14, (bottom - top) / 8);
            left -= padX;
            right += padX;
            top -= padY;
            bottom += padY;

            DrawingRectangle virtualScreen = System.Windows.Forms.SystemInformation.VirtualScreen;
            left = Math.Max(virtualScreen.Left, left);
            top = Math.Max(virtualScreen.Top, top);
            right = Math.Min(virtualScreen.Right, right);
            bottom = Math.Min(virtualScreen.Bottom, bottom);

            if (right - left < 24 || bottom - top < 24)
            {
                status = "Screen OCR selected area is too small.";
                return false;
            }

            screenRect = new DrawingRectangle(left, top, right - left, bottom - top);
            return true;
        }

        private static DrawingBitmap CaptureScreenRectangle(DrawingRectangle rect)
        {
            var bitmap = new DrawingBitmap(rect.Width, rect.Height, DrawingPixelFormat.Format24bppRgb);
            using (DrawingGraphics graphics = DrawingGraphics.FromImage(bitmap))
            {
                graphics.CopyFromScreen(rect.Left, rect.Top, 0, 0, rect.Size);
            }

            return bitmap;
        }

        private static string CreateColumnScheduleOcrDebugFolder()
        {
            string root = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "CamboBIM",
                "CadScheduleOcr");
            string folder = Path.Combine(root, DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture));
            Directory.CreateDirectory(folder);
            return folder;
