                if (bitmap == null || string.IsNullOrWhiteSpace(folder) || string.IsNullOrWhiteSpace(fileName))
                {
                    return;
                }

                Directory.CreateDirectory(folder);
                bitmap.Save(Path.Combine(folder, fileName), DrawingImageFormat.Png);
            }
            catch
