        }

        private static void TrySaveOcrDebugText(
            string folder,
            DrawingRectangle screenRect,
            IEnumerable<string> originalLines,
            IEnumerable<string> preparedLines,
            List<List<string>> rows)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(folder))
                {
                    return;
                }

                Directory.CreateDirectory(folder);
                var text = new List<string>
                {
                    "CamboBIM Column Schedule OCR Debug",
                    "ScreenRect: " + screenRect.Left.ToString(CultureInfo.InvariantCulture) + "," +
                    screenRect.Top.ToString(CultureInfo.InvariantCulture) + "," +
                    screenRect.Width.ToString(CultureInfo.InvariantCulture) + "x" +
                    screenRect.Height.ToString(CultureInfo.InvariantCulture),
                    "",
                    "Original OCR Lines:"
                };

                text.AddRange((originalLines ?? Enumerable.Empty<string>()).Select(line => "  " + line));
                text.Add("");
                text.Add("Prepared OCR Lines:");
                text.AddRange((preparedLines ?? Enumerable.Empty<string>()).Select(line => "  " + line));
                text.Add("");
                text.Add("Parsed Rows:");
                if (rows != null)
                {
                    text.AddRange(rows.Select(row => "  " + string.Join(" | ", row ?? new List<string>())));
                }

                File.WriteAllLines(Path.Combine(folder, "ocr-lines.txt"), text);
            }
            catch
            {
            }
        }

        private static DrawingBitmap PrepareScheduleImageForOcr(DrawingBitmap source)
        {
            int scale = 3;
            int maxDimension = Math.Max(source.Width, source.Height) * scale;
            if (maxDimension > 2600)
            {
                scale = Math.Max(1, 2600 / Math.Max(source.Width, source.Height));
            }

            var scaled = new DrawingBitmap(source.Width * scale, source.Height * scale, DrawingPixelFormat.Format24bppRgb);
            using (DrawingGraphics graphics = DrawingGraphics.FromImage(scaled))
            {
                graphics.InterpolationMode = DrawingInterpolationMode.HighQualityBicubic;
                graphics.DrawImage(source, 0, 0, scaled.Width, scaled.Height);
            }

            var prepared = new DrawingBitmap(scaled.Width, scaled.Height, DrawingPixelFormat.Format24bppRgb);
            for (int y = 0; y < scaled.Height; y++)
            {
                for (int x = 0; x < scaled.Width; x++)
                {
                    DrawingColor p = scaled.GetPixel(x, y);
                    int max = Math.Max(p.R, Math.Max(p.G, p.B));
                    int min = Math.Min(p.R, Math.Min(p.G, p.B));
                    bool isBrightDrawing = max > 72 && (max - min > 20 || max > 145);
                    prepared.SetPixel(x, y, isBrightDrawing ? DrawingColor.Black : DrawingColor.White);
                }
            }

            scaled.Dispose();
            return prepared;
        }

        private static async Task<List<string>> RecognizeOcrLinesAsync(DrawingBitmap bitmap)
        {
#pragma warning disable CA1416
            string tempFile = Path.Combine(
                Path.GetTempPath(),
                "CamboBIM_ElementSchedule_OCR_" + Guid.NewGuid().ToString("N") + ".png");

            try
            {
                bitmap.Save(tempFile, DrawingImageFormat.Png);
                StorageFile file = await StorageFile.GetFileFromPathAsync(tempFile);
                using (Windows.Storage.Streams.IRandomAccessStream stream = await file.OpenAsync(FileAccessMode.Read))
                {
                    BitmapDecoder decoder = await BitmapDecoder.CreateAsync(stream);
                    using (SoftwareBitmap softwareBitmap = await decoder.GetSoftwareBitmapAsync(
                               BitmapPixelFormat.Bgra8,
                               BitmapAlphaMode.Premultiplied))
                    {
                        OcrEngine engine = OcrEngine.TryCreateFromUserProfileLanguages();
                        if (engine == null)
                        {
                            try
                            {
                                engine = OcrEngine.TryCreateFromLanguage(new Language("en-US"));
                            }
                            catch
                            {
                            }
                        }

                        if (engine == null)
                        {
                            return new List<string>();
                        }

                        OcrResult result = await engine.RecognizeAsync(softwareBitmap);
                        return result.Lines
                            .Select(line => string.Join(" ", line.Words.Select(word => word.Text)))
                            .Where(line => !string.IsNullOrWhiteSpace(line))
                            .ToList();
                    }
                }
            }
            finally
            {
                try
                {
                    if (File.Exists(tempFile))
                    {
                        File.Delete(tempFile);
                    }
                }
                catch
                {
                }
            }
        }

        private static List<List<string>> BuildColumnScheduleRowsFromOcrLines(IEnumerable<string> lines)
        {
            var rows = new List<List<string>>
            {
                new List<string> { "MARK", "TYPE", "Corresponding Floor" }
            };
            var byName = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            var pendingMarks = new List<string>();
            var pendingSizes = new List<string>();
            const string sizePattern = @"\(?\s*\d+(?:[.,]\d+)?\s*(?:x|X|\*)\s*\d+(?:[.,]\d+)?(?:\s*(?:x|X|\*)\s*\d+(?:[.,]\d+)?)?\s*\)?\s*(?:mm|cm|m)?";
            const string markPattern = @"\b[A-Z]{1,4}\s*[-']?\s*\d+[A-Z0-9']*\b";

            void addRow(string rawName, string rawSize)
            {
                string name = CleanScheduleName(rawName);
                string size = NormalizeColumnScheduleSizeText(rawSize);
                if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(size))
                {
                    return;
                }

                byName[name] = new List<string> { name, size, "Zone-1[0]" };
            }

            if (lines != null)
            {
                foreach (string rawLine in lines)
                {
                    string line = NormalizeOcrText(rawLine);
                    if (string.IsNullOrWhiteSpace(line) ||
                        IsHeaderLabel(line, "SCHEDULE") ||
                        IsHeaderLabel(line, "SAFETY") ||
                        IsHeaderLabel(line, "PILE CAP") ||
                        IsHeaderLabel(line, "ALLOWABLE"))
                    {
                        continue;
                    }

                    List<string> sizeTokens = Regex.Matches(line, sizePattern, RegexOptions.IgnoreCase)
                        .Cast<Match>()
                        .Select(m => m.Value)
                        .Where(v => !string.IsNullOrWhiteSpace(v))
                        .ToList();
                    List<string> markTokens = Regex.Matches(line, markPattern, RegexOptions.IgnoreCase)
                        .Cast<Match>()
                        .Select(m => m.Value)
                        .Where(v => !string.IsNullOrWhiteSpace(v))
                        .ToList();

                    if (sizeTokens.Count == 0 && markTokens.Count == 0)
                    {
                        continue;
                    }

                    int paired = Math.Min(markTokens.Count, sizeTokens.Count);
                    for (int i = 0; i < paired; i++)
                    {
                        addRow(markTokens[i], sizeTokens[i]);
                    }

                    if (markTokens.Count > paired)
                    {
                        pendingMarks.AddRange(markTokens.Skip(paired));
                    }

                    if (sizeTokens.Count > paired)
                    {
                        pendingSizes.AddRange(sizeTokens.Skip(paired));
                    }
                }
            }

            pendingMarks = CollapseRepeatedOcrTokens(pendingMarks);
            pendingSizes = CollapseRepeatedOcrTokens(pendingSizes);

            int pendingPairCount = Math.Min(pendingMarks.Count, pendingSizes.Count);
            for (int i = 0; i < pendingPairCount; i++)
            {
                addRow(pendingMarks[i], pendingSizes[i]);
            }

            if (byName.Count == 0 && pendingSizes.Count > 0)
            {
                string prefix = InferScheduleMarkPrefix(pendingMarks, "C");
                int startNumber = InferScheduleStartNumber(pendingMarks, 1);
                for (int i = 0; i < pendingSizes.Count; i++)
                {
                    addRow(prefix + (startNumber + i).ToString(CultureInfo.InvariantCulture), pendingSizes[i]);
                }
            }
            else if (pendingMarks.Count > 0 && pendingSizes.Count > byName.Count)
            {
                List<string> existingNames = byName.Keys.OrderBy(NaturalScheduleSortKey).ToList();
                string prefix = InferScheduleMarkPrefix(existingNames.Concat(pendingMarks), "C");
                int nextNumber = InferNextScheduleNumber(existingNames.Concat(pendingMarks), 1);
                int missingCount = pendingSizes.Count - byName.Count;
                int sizeIndex = byName.Count;
                for (int i = 0; i < missingCount && sizeIndex < pendingSizes.Count; i++, sizeIndex++)
                {
                    addRow(prefix + (nextNumber + i).ToString(CultureInfo.InvariantCulture), pendingSizes[sizeIndex]);
                }
            }

            foreach (List<string> row in byName.Values.OrderBy(r => NaturalScheduleSortKey(r[0])))
            {
                rows.Add(row);
            }

            if (rows.Count <= 1)
            {
                rows.Clear();
            }

            return rows;
        }

        private static List<string> CollapseRepeatedOcrTokens(List<string> tokens)
        {
            if (tokens == null || tokens.Count < 2 || tokens.Count % 2 != 0)
            {
                return tokens ?? new List<string>();
            }

            int half = tokens.Count / 2;
            for (int i = 0; i < half; i++)
            {
                if (!string.Equals(
                        NormalizeOcrText(tokens[i]),
                        NormalizeOcrText(tokens[i + half]),
                        StringComparison.OrdinalIgnoreCase))
                {
                    return tokens;
                }
            }

            return tokens.Take(half).ToList();
        }

        private static string InferScheduleMarkPrefix(IEnumerable<string> marks, string fallback)
        {
            if (marks != null)
            {
                foreach (string mark in marks)
                {
                    string cleaned = CleanScheduleName(mark);
                    Match match = Regex.Match(cleaned, @"^(?<prefix>[A-Z]+)", RegexOptions.IgnoreCase);
                    if (match.Success)
                    {
                        return match.Groups["prefix"].Value.ToUpperInvariant();
                    }
                }
            }

            return string.IsNullOrWhiteSpace(fallback) ? "C" : fallback.ToUpperInvariant();
        }

        private static int InferScheduleStartNumber(IEnumerable<string> marks, int fallback)
        {
            if (marks != null)
            {
                foreach (string mark in marks)
                {
                    Match match = Regex.Match(CleanScheduleName(mark), @"\d+");
                    if (match.Success && int.TryParse(match.Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value))
                    {
                        return Math.Max(1, value);
                    }
                }
            }

            return Math.Max(1, fallback);
        }

        private static int InferNextScheduleNumber(IEnumerable<string> marks, int fallback)
        {
            int max = 0;
            if (marks != null)
            {
                foreach (string mark in marks)
                {
                    Match match = Regex.Match(CleanScheduleName(mark), @"\d+");
                    if (match.Success && int.TryParse(match.Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value))
                    {
                        max = Math.Max(max, value);
                    }
                }
            }

            return max > 0 ? max + 1 : Math.Max(1, fallback);
        }

        private static string NormalizeOcrText(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            string normalized = text
                .Trim()
                .Replace("（", "(")
                .Replace("）", ")")
                .Replace("×", "x")
                .Replace("X", "x")
                .Replace("*", "x");

            normalized = Regex.Replace(normalized, @"(?<=\d)[Oo](?=\d)", "0");
            normalized = Regex.Replace(normalized, @"(?<=\d)[Oo](?=\s*(?:x|\)|m|$))", "0");
            normalized = Regex.Replace(normalized, @"(?<=(?:x|\())\s*[Oo](?=\d)", "0");
            normalized = Regex.Replace(normalized, @"(?<=\d)[Cc](?=\d|x|\)|m|$)", "0");
            normalized = Regex.Replace(normalized, @"(?<=(?:x|\())\s*[Cc](?=\d)", "0");
            normalized = Regex.Replace(normalized, @"(?<=[A-Za-z])(?:[Il\|])(?=\b)", "1");
            return normalized;
        }
#endif

        private static bool IsLikelyScheduleMark(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string cleaned = CleanScheduleName(text);
            if (cleaned.Length == 0 || cleaned.Length > 16)
            {
                return false;
            }

            bool hasLetter = cleaned.Any(char.IsLetter);
            bool hasDigit = cleaned.Any(char.IsDigit);
            return hasLetter && hasDigit && cleaned.All(c => char.IsLetterOrDigit(c) || c == '-' || c == '\'');
        }

        private static List<WallSectionSpec> ParseWallScheduleFromLabels(List<CadTextLabel> labels)
        {
            var specs = new List<WallSectionSpec>();
            if (labels == null || labels.Count == 0) return specs;

            CadTextLabel headerMark = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "MARK"));
            CadTextLabel headerType = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "TYPE"));

            if (headerMark == null || headerType == null)
            {
                return specs;
            }

            double minY = labels.Min(l => l.Position.Y);
            double maxY = labels.Max(l => l.Position.Y);
            double rowTol = Math.Max((maxY - minY) * 0.03, MmToFeet(50.0));

            var content = labels
                .Where(l => l != headerMark && l != headerType)
                .OrderByDescending(l => l.Position.Y)
                .ToList();

            var rows = new List<RowBucket>();
            foreach (CadTextLabel label in content)
            {
                if (IsHeaderLabel(label.Text, "SCHEDULE")) continue;

                RowBucket bucket = rows.FirstOrDefault(r => Math.Abs(r.CenterY - label.Position.Y) <= rowTol);
                if (bucket == null)
                {
                    bucket = new RowBucket(label.Position.Y);
                    rows.Add(bucket);
                }

                bucket.Add(label);
            }

            foreach (RowBucket row in rows)
            {
                CadTextLabel markLabel = row.FindClosestToX(headerMark.Position.X);
                CadTextLabel typeLabel = row.FindClosestToX(headerType.Position.X);

                if (markLabel == null || typeLabel == null) continue;

                string name = CleanScheduleName(markLabel.Text);
                if (string.IsNullOrWhiteSpace(name)) continue;

                if (!TryParseWallWidthLabel(typeLabel.Text, out double widthMm))
                {
                    continue;
                }

                specs.Add(new WallSectionSpec
                {
                    Name = name,
                    WidthMm = widthMm
                });
            }

            return specs;
        }

        private static List<BeamSectionSpec> ParseBeamScheduleFromLabels(List<CadTextLabel> labels)
        {
            var specs = new List<BeamSectionSpec>();
            if (labels == null || labels.Count == 0) return specs;

            CadTextLabel headerMark = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "MARK"));
            CadTextLabel headerType = labels.FirstOrDefault(l => IsHeaderLabel(l.Text, "TYPE"));

            if (headerMark == null || headerType == null)
            {
                return specs;
            }

            double minY = labels.Min(l => l.Position.Y);
            double maxY = labels.Max(l => l.Position.Y);
            double rowTol = Math.Max((maxY - minY) * 0.03, MmToFeet(50.0));

            var content = labels
                .Where(l => l != headerMark && l != headerType)
                .OrderByDescending(l => l.Position.Y)
                .ToList();

            var rows = new List<RowBucket>();
            foreach (CadTextLabel label in content)
            {
                if (IsHeaderLabel(label.Text, "SCHEDULE")) continue;

                RowBucket bucket = rows.FirstOrDefault(r => Math.Abs(r.CenterY - label.Position.Y) <= rowTol);
                if (bucket == null)
                {
                    bucket = new RowBucket(label.Position.Y);
                    rows.Add(bucket);
                }

                bucket.Add(label);
            }

            foreach (RowBucket row in rows)
            {
                CadTextLabel markLabel = row.FindClosestToX(headerMark.Position.X);
                CadTextLabel typeLabel = row.FindClosestToX(headerType.Position.X);

                if (markLabel == null || typeLabel == null) continue;

                string name = CleanScheduleName(markLabel.Text);
                if (string.IsNullOrWhiteSpace(name)) continue;

                if (!TryParseSizeLabel(typeLabel.Text, out double wMm, out double dMm))
                {
                    continue;
                }

                specs.Add(new BeamSectionSpec
                {
                    Name = name,
                    WidthMm = wMm,
                    DepthMm = dMm
                });
            }

            return specs;
        }

        private static string CleanScheduleName(string text)
        {
            if (string.IsNullOrWhiteSpace(text)) return "";
            string cleaned = text.Trim();

            int paren = cleaned.IndexOf('(');
            if (paren > 0)
            {
                cleaned = cleaned.Substring(0, paren);
            }

            cleaned = cleaned.Replace(" ", "");
            return cleaned;
        }

        private static bool IsHeaderLabel(string text, string keyword)
        {
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(keyword)) return false;
            return text.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private class RowBucket
        {
            private readonly List<CadTextLabel> _labels = new List<CadTextLabel>();

            public double CenterY { get; private set; }

            public RowBucket(double y)
            {
                CenterY = y;
            }

            public void Add(CadTextLabel label)
            {
                _labels.Add(label);
                CenterY = _labels.Average(l => l.Position.Y);
            }

            public CadTextLabel FindClosestToX(double x)
            {
                CadTextLabel best = null;
                double bestDist = double.MaxValue;
                foreach (CadTextLabel label in _labels)
                {
                    double dist = Math.Abs(label.Position.X - x);
                    if (dist < bestDist)
                    {
                        bestDist = dist;
                        best = label;
                    }
                }

                return best;
            }
        }

        private static bool TryParseSizeLabel(string text, out double widthMm, out double lengthMm)
        {
            widthMm = 0;
            lengthMm = 0;
            if (string.IsNullOrWhiteSpace(text)) return false;

            var numbers = new List<double>();
            string current = "";
            foreach (char c in text)
            {
                if (char.IsDigit(c) || c == '.' || c == ',')
                {
                    current += c;
                }
                else
                {
                    if (current.Length > 0 && TryParseNumber(current, out double val))
                    {
                        numbers.Add(val);
                    }
                    current = "";
                }
            }

            if (current.Length > 0 && TryParseNumber(current, out double lastVal))
            {
                numbers.Add(lastVal);
            }

            if (numbers.Count < 2) return false;

            widthMm = NormalizeLengthToMm(numbers[0], text);
            lengthMm = NormalizeLengthToMm(numbers[1], text);
            return widthMm > 0 && lengthMm > 0;
        }

        private static bool TryParseNumber(string raw, out double value)
        {
            if (double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value))
            {
                return true;
            }

            return double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out value);
        }

        private static List<double> ExtractNumbers(string text)
        {
            var numbers = new List<double>();
            if (string.IsNullOrWhiteSpace(text)) return numbers;

            string current = "";
            foreach (char c in text)
            {
                if (char.IsDigit(c) || c == '.' || c == ',')
                {
                    current += c;
                }
                else
                {
                    if (current.Length > 0 && TryParseNumber(current, out double val))
                    {
                        numbers.Add(val);
                    }
                    current = "";
                }
            }

            if (current.Length > 0 && TryParseNumber(current, out double lastVal))
            {
                numbers.Add(lastVal);
            }

            return numbers;
        }

        private static string NormalizeSizeKey(double widthMm, double lengthMm)
        {
            if (widthMm <= 0 || lengthMm <= 0) return "";
            double a = Math.Min(widthMm, lengthMm);
            double b = Math.Max(widthMm, lengthMm);
            return $"{Math.Round(a)}x{Math.Round(b)}";
        }

        private static string NormalizeWallSizeKey(double widthMm)
        {
            if (widthMm <= 0) return "";
            return $"{Math.Round(widthMm)}";
        }

        private static string NormalizeSlabThicknessKey(double thicknessMm)
        {
            if (thicknessMm <= 0) return "";
            return $"{Math.Round(thicknessMm)}";
        }

        private static bool TryParseWallWidthLabel(string text, out double widthMm)
        {
            widthMm = 0;
            if (string.IsNullOrWhiteSpace(text)) return false;

            List<double> numbers = ExtractNumbers(text);
            if (numbers.Count == 0) return false;

            widthMm = NormalizeLengthToMm(numbers[0], text);
            return widthMm > 0;
        }

        private static bool TryParseSlabThicknessLabel(string text, out double thicknessMm)
        {
            return TryParseWallWidthLabel(text, out thicknessMm);
        }

        private static string NormalizeBeamSizeKey(double widthMm, double depthMm)
        {
            if (widthMm <= 0 || depthMm <= 0) return "";
            double a = Math.Min(widthMm, depthMm);
            double b = Math.Max(widthMm, depthMm);
            return $"{Math.Round(a)}x{Math.Round(b)}";
        }

        private static Dictionary<string, BeamSectionSpec> BuildBeamSpecNameMap(List<BeamSectionSpec> specs)
        {
            var map = new Dictionary<string, BeamSectionSpec>(StringComparer.OrdinalIgnoreCase);
            if (specs == null) return map;

            foreach (BeamSectionSpec spec in specs)
            {
                if (spec == null || string.IsNullOrWhiteSpace(spec.Name)) continue;
                string key = NormalizeSectionKey(spec.Name);
                if (string.IsNullOrWhiteSpace(key)) continue;
                map[key] = spec;
            }

            return map;
        }

        private static Dictionary<string, BeamSectionSpec> BuildBeamSpecSizeMap(List<BeamSectionSpec> specs)
        {
            var map = new Dictionary<string, BeamSectionSpec>(StringComparer.OrdinalIgnoreCase);
            if (specs == null) return map;

            foreach (BeamSectionSpec spec in specs)
            {
                if (spec == null) continue;
                if (spec.WidthMm <= 0 || spec.DepthMm <= 0) continue;
                string key = NormalizeBeamSizeKey(spec.WidthMm, spec.DepthMm);
                if (string.IsNullOrWhiteSpace(key)) continue;
                map[key] = spec;
            }

            return map;
        }

        private static BeamSectionSpec MatchBeamSpecFromLabel(
            string text,
            Dictionary<string, BeamSectionSpec> specByName,
            Dictionary<string, BeamSectionSpec> specBySize)
        {
            if (string.IsNullOrWhiteSpace(text)) return null;

            string key = NormalizeSectionKey(text);
            if (!string.IsNullOrWhiteSpace(key) && specByName.TryGetValue(key, out BeamSectionSpec specByKey))
            {
                return specByKey;
            }

            if (TryParseSizeLabel(text, out double w, out double d))
            {
                string sizeKey = NormalizeBeamSizeKey(w, d);
                if (!string.IsNullOrWhiteSpace(sizeKey) && specBySize.TryGetValue(sizeKey, out BeamSectionSpec specBySz))
                {
                    return specBySz;
                }
            }

            return null;
        }

        private BeamSectionSpec ResolveBeamSpecForLine(
            Line line,
            List<CadTextLabel> labels,
            Dictionary<string, BeamSectionSpec> specByName,
            Dictionary<string, BeamSectionSpec> specBySize,
            BeamSectionSpec layerSpec)
        {
            if (line == null) return layerSpec;

            XYZ mid = (line.GetEndPoint(0) + line.GetEndPoint(1)) * 0.5;

            if (labels != null && labels.Count > 0)
            {
                BeamSectionSpec spec = FindNearestBeamSpecFromLabels(mid, labels, specByName, specBySize, MmToFeet(1200.0));
                if (spec != null) return spec;
            }

            return layerSpec;
        }

        private static BeamSectionSpec FindNearestBeamSpecFromLabels(
            XYZ point,
            List<CadTextLabel> labels,
            Dictionary<string, BeamSectionSpec> specByName,
            Dictionary<string, BeamSectionSpec> specBySize,
            double maxDistFt)
        {
            BeamSectionSpec best = null;
            double bestDist = double.MaxValue;

            foreach (CadTextLabel label in labels)
            {
                if (label == null) continue;
                double dist = label.Position.DistanceTo(point);
                if (dist > maxDistFt) continue;

                BeamSectionSpec spec = MatchBeamSpecFromLabel(label.Text, specByName, specBySize);
                if (spec == null) continue;

                if (dist < bestDist)
                {
                    bestDist = dist;
                    best = spec;
                }
            }

            return best;
        }

        private void EnsureBeamTypesFromExcel(
            Document doc,
            FamilySymbol baseType,
            List<BeamSectionSpec> specs,
            Dictionary<BeamSectionSpec, FamilySymbol> typeBySpec,
            Dictionary<string, FamilySymbol> typeByName,
            out int created,
            out int skipped)
        {
            created = 0;
            skipped = 0;

            if (doc == null || baseType == null || specs == null || specs.Count == 0) return;

            List<FamilySymbol> familyTypes = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Family != null && fs.Family.Id == baseType.Family.Id)
                .ToList();

            foreach (BeamSectionSpec spec in specs)
            {
                if (spec == null || string.IsNullOrWhiteSpace(spec.Name))
                {
                    skipped++;
                    continue;
                }

                string normalizedName = NormalizeSectionKey(spec.Name);
                if (string.IsNullOrWhiteSpace(normalizedName))
                {
                    skipped++;
                    continue;
                }

                FamilySymbol type = familyTypes
                    .FirstOrDefault(fs => string.Equals(fs.Name, spec.Name, StringComparison.OrdinalIgnoreCase));

                bool createdType = false;
                if (type == null)
                {
                    ElementType newType = baseType.Duplicate(spec.Name);
                    type = newType as FamilySymbol;
                    if (type != null)
                    {
                        familyTypes.Add(type);
                        created++;
                        createdType = true;
                    }
                }

                if (type == null)
                {
                    skipped++;
                    continue;
                }

                if (!TrySetBeamTypeDimensions(type, spec.WidthMm, spec.DepthMm))
                {
                    if (createdType)
                    {
                        skipped++;
                        continue;
                    }
                }

                typeBySpec[spec] = type;
                typeByName[normalizedName] = type;
            }
        }

        private bool TrySetBeamTypeDimensions(FamilySymbol type, double widthMm, double depthMm)
        {
            if (type == null || widthMm <= 0 || depthMm <= 0) return false;

            Parameter widthParam = FindColumnDimensionParameter(type, new[]
            {
                "b", "width", "w", "bw", "dim b", "dim_b"
            });
            Parameter depthParam = FindColumnDimensionParameter(type, new[]
            {
                "h", "depth", "height", "d", "dim h", "dim_h"
            });

            if (widthParam == null || depthParam == null)
            {
                return false;
            }

            double widthFt = MmToFeet(widthMm);
            double depthFt = MmToFeet(depthMm);

            if (!widthParam.IsReadOnly && widthParam.StorageType == StorageType.Double)
            {
                widthParam.Set(widthFt);
            }
            else
            {
                return false;
            }

            if (!depthParam.IsReadOnly && depthParam.StorageType == StorageType.Double)
            {
                depthParam.Set(depthFt);
            }
            else
            {
                return false;
            }

            return true;
        }

        private static void SetBeamEndOffsets(FamilyInstance beam, Level baseLevel, Level topLevel)
        {
            if (beam == null || baseLevel == null || topLevel == null) return;

            double offset = topLevel.Elevation - baseLevel.Elevation;

            Parameter end0 = beam.get_Parameter(BuiltInParameter.STRUCTURAL_BEAM_END0_ELEVATION);
            Parameter end1 = beam.get_Parameter(BuiltInParameter.STRUCTURAL_BEAM_END1_ELEVATION);

            if (end0 != null && !end0.IsReadOnly)
            {
                end0.Set(offset);
            }
            if (end1 != null && !end1.IsReadOnly)
            {
                end1.Set(offset);
            }
        }

        private static Dictionary<string, FamilySymbol> BuildBeamTypeNameMap(Document doc, FamilySymbol baseType)
        {
            var map = new Dictionary<string, FamilySymbol>(StringComparer.OrdinalIgnoreCase);
            if (doc == null) return map;

            IEnumerable<FamilySymbol> types = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Category != null &&
                             fs.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFraming);

            if (baseType != null && baseType.Family != null)
            {
                types = types.Where(fs => fs.Family != null && fs.Family.Id == baseType.Family.Id);
            }

            foreach (FamilySymbol fs in types)
            {
                if (fs == null) continue;
                string key = NormalizeSectionKey(fs.Name);
                if (string.IsNullOrWhiteSpace(key)) continue;
                if (!map.ContainsKey(key))
                {
                    map[key] = fs;
                }
            }

            return map;
        }

        private static Dictionary<string, FamilySymbol> BuildBeamTypeSizeMap(Document doc, FamilySymbol baseType)
        {
            var map = new Dictionary<string, FamilySymbol>(StringComparer.OrdinalIgnoreCase);
            if (doc == null) return map;

            IEnumerable<FamilySymbol> types = new FilteredElementCollector(doc)
                .OfClass(typeof(FamilySymbol))
                .Cast<FamilySymbol>()
                .Where(fs => fs.Category != null &&
                             fs.Category.Id.Value == (int)BuiltInCategory.OST_StructuralFraming);

            if (baseType != null && baseType.Family != null)
            {
                types = types.Where(fs => fs.Family != null && fs.Family.Id == baseType.Family.Id);
            }

            foreach (FamilySymbol fs in types)
            {
                if (fs == null) continue;

                if (!TryGetBeamTypeSize(fs, out double widthMm, out double depthMm)) continue;
                string key = NormalizeBeamSizeKey(widthMm, depthMm);
                if (string.IsNullOrWhiteSpace(key)) continue;

                if (!map.ContainsKey(key))
                {
                    map[key] = fs;
                }
            }

            return map;
        }

        private static bool TryGetBeamTypeSize(FamilySymbol type, out double widthMm, out double depthMm)
        {
            widthMm = 0;
            depthMm = 0;
            if (type == null) return false;

            Parameter widthParam = FindColumnDimensionParameter(type, new[]
            {
                "b", "width", "w", "bw", "dim b", "dim_b"
            });
            Parameter depthParam = FindColumnDimensionParameter(type, new[]
            {
                "h", "depth", "height", "d", "dim h", "dim_h"
            });

            if (widthParam == null || depthParam == null) return false;
            if (widthParam.StorageType != StorageType.Double || depthParam.StorageType != StorageType.Double) return false;

            widthMm = widthParam.AsDouble() * 304.8;
            depthMm = depthParam.AsDouble() * 304.8;
            return widthMm > 0 && depthMm > 0;
        }

        private static FamilySymbol FindNearestBeamTypeFromLabels(
            XYZ point,
            List<CadTextLabel> labels,
            Dictionary<string, FamilySymbol> typeByName,
            Dictionary<string, FamilySymbol> typeBySize,
            double maxDistFt)
        {
            if (labels == null) return null;
            bool hasNames = typeByName != null && typeByName.Count > 0;
            bool hasSizes = typeBySize != null && typeBySize.Count > 0;
            if (!hasNames && !hasSizes) return null;

            FamilySymbol best = null;
            double bestDist = double.MaxValue;

            foreach (CadTextLabel label in labels)
            {
                if (label == null) continue;
                double dist = label.Position.DistanceTo(point);
                if (dist > maxDistFt) continue;

                if (hasNames)
                {
                    string key = NormalizeSectionKey(label.Text);
                    if (!string.IsNullOrWhiteSpace(key) && typeByName.TryGetValue(key, out FamilySymbol type))
                    {
                        if (dist < bestDist)
                        {
                            bestDist = dist;
                            best = type;
                        }
                    }
                }

                if (hasSizes && TryParseSizeLabel(label.Text, out double w, out double d))
                {
                    string sizeKey = NormalizeBeamSizeKey(w, d);
                    if (!string.IsNullOrWhiteSpace(sizeKey) && typeBySize.TryGetValue(sizeKey, out FamilySymbol sizeType))
                    {
                        if (dist < bestDist)
                        {
                            bestDist = dist;
                            best = sizeType;
                    }
                }
            }
#pragma warning restore CA1416
        }

            return best;
        }

        private static CadPolylineHit FindPolylineHitForPoint(XYZ point, List<CadPolylineHit> polylines, double tolFt)
        {
            if (polylines == null || polylines.Count == 0) return null;

            CadPolylineHit best = null;
            double bestDist = double.MaxValue;
            foreach (CadPolylineHit hit in polylines)
            {
                if (hit == null) continue;
                double dist = hit.Center.DistanceTo(point);
                if (dist <= tolFt && dist < bestDist)
                {
                    best = hit;
                    bestDist = dist;
                }
            }

            return best;
        }

        private static bool TryGetPolylineSize(IList<XYZ> pts, out double widthFt, out double lengthFt)
        {
            widthFt = 0;
            lengthFt = 0;

            if (pts == null || pts.Count < 4) return false;

            int count = pts.Count;
            if (pts[0].DistanceTo(pts[count - 1]) <= 1e-3)
            {
                count -= 1;
            }

            if (count < 3) return false;

            var lengths = new List<double>();
            for (int i = 0; i < count; i++)
            {
                XYZ p0 = pts[i];
                XYZ p1 = pts[(i + 1) % count];
                double len = p0.DistanceTo(p1);
                if (len > 1e-4)
                {
                    lengths.Add(len);
                }
            }

            if (lengths.Count >= 2)
            {
                double maxLen = lengths.Max();
                List<double> filtered = lengths.Where(l => l >= maxLen * 0.2).ToList();
                if (filtered.Count >= 2)
                {
                    widthFt = filtered.Min();
                    lengthFt = filtered.Max();
                }
                else
                {
                    widthFt = lengths.Min();
                    lengthFt = lengths.Max();
                }
                if (widthFt > 0 && lengthFt > 0) return true;
            }

            double minX = pts[0].X, maxX = pts[0].X;
            double minY = pts[0].Y, maxY = pts[0].Y;
            for (int i = 1; i < count; i++)
            {
                XYZ p = pts[i];
                if (p.X < minX) minX = p.X;
                if (p.X > maxX) maxX = p.X;
                if (p.Y < minY) minY = p.Y;
                if (p.Y > maxY) maxY = p.Y;
            }

            widthFt = Math.Abs(maxX - minX);
            lengthFt = Math.Abs(maxY - minY);
            return widthFt > 0 && lengthFt > 0;
        }

        private static bool IsClosedPolyline(IList<XYZ> pts)
        {
            if (pts == null || pts.Count < 3) return false;
            XYZ first = pts[0];
            XYZ last = pts[pts.Count - 1];
            return first.DistanceTo(last) <= 1e-3;
        }

        private static XYZ ComputePolylineCentroid(IList<XYZ> pts)
        {
            if (pts == null || pts.Count < 3) return XYZ.Zero;

            int count = pts.Count;
            if (pts[0].DistanceTo(pts[count - 1]) <= 1e-3)
            {
                count -= 1;
            }

            double area = 0.0;
            double cx = 0.0;
            double cy = 0.0;
            double z = 0.0;

            for (int i = 0; i < count; i++)
            {
                XYZ p0 = pts[i];
                XYZ p1 = pts[(i + 1) % count];
                double cross = p0.X * p1.Y - p1.X * p0.Y;
                area += cross;
                cx += (p0.X + p1.X) * cross;
                cy += (p0.Y + p1.Y) * cross;
                z += p0.Z;
            }

            if (Math.Abs(area) < 1e-9)
            {
                double avgX = 0.0;
                double avgY = 0.0;
                for (int i = 0; i < count; i++)
                {
                    avgX += pts[i].X;
                    avgY += pts[i].Y;
                    z += pts[i].Z;
                }

                avgX /= count;
                avgY /= count;
                z /= count;
                return new XYZ(avgX, avgY, z);
            }

            area *= 0.5;
            cx /= (6.0 * area);
            cy /= (6.0 * area);
            z /= count;
            return new XYZ(cx, cy, z);
        }

        private static double NormalizeLengthToMm(double value, string text)
        {
            if (value <= 0) return value;

            string lower = text?.ToLowerInvariant() ?? "";
            if (lower.Contains("mm")) return value;
            if (lower.Contains("cm")) return value * 10.0;
            if (lower.Contains("m")) return value * 1000.0;

            if (value < 10.0)
            {
                return value * 1000.0;
            }

            return value;
        }

        private static string GetCadBlockName(Document doc, GeometryInstance gi)
        {
            if (gi == null) return "";

            try
            {
                PropertyInfo symbolIdProp = gi.GetType().GetProperty("SymbolId");
                if (symbolIdProp != null)
                {
                    object idObj = symbolIdProp.GetValue(gi, null);
                    if (idObj is ElementId id && id != ElementId.InvalidElementId)
                    {
                        Element sym = doc.GetElement(id);
                        if (sym != null) return sym.Name ?? "";
                    }
                }

                PropertyInfo symbolProp = gi.GetType().GetProperty("Symbol");
                if (symbolProp != null)
                {
                    object symObj = symbolProp.GetValue(gi, null);
                    if (symObj is Element symElem)
                    {
                        return symElem.Name ?? "";
                    }

                    PropertyInfo nameProp = symObj?.GetType().GetProperty("Name");
                    if (nameProp != null)
                    {
                        return nameProp.GetValue(symObj, null)?.ToString() ?? "";
                    }
                }
            }
            catch
            {
                return "";
            }

            return "";
        }

        private static bool LayerExists(List<string> layers, string name)
        {
            if (layers == null || string.IsNullOrWhiteSpace(name)) return false;
            return layers.Any(l => string.Equals(l, name, StringComparison.OrdinalIgnoreCase));
        }

        private static string FindBestColumnLayerByName(List<string> layers)
        {
            if (layers == null || layers.Count == 0) return "";

            string best = "";
            int bestScore = 0;

            foreach (string layer in layers)
            {
                int score = ScoreColumnLayerName(layer);
                if (score > bestScore)
                {
                    bestScore = score;
                    best = layer;
                }
            }

            return bestScore > 0 ? best : "";
        }

