        private static int ScoreColumnLayerName(string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName)) return 0;

            string name = layerName.ToUpperInvariant();
            int score = 0;

            if (name.Contains("COLUMN")) score += 10;
            if (ContainsToken(name, "COL")) score += 6;
            if (name.Contains("CENTER") || name.Contains("CENTRE") || name.Contains("CTR") || name.Contains("CTRE")) score += 4;
            if (name.Contains("POINT") || ContainsToken(name, "PT")) score += 2;

            if (name.Contains("GRID")) score -= 2;
            if (name.Contains("PILE") || name.Contains("SLAB") || name.Contains("BEAM") || name.Contains("WALL")) score -= 4;

            return score;
        }

        private static int ScoreWallLayerName(string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName)) return 0;

            string name = layerName.ToUpperInvariant();
            int score = 0;

            if (name.Contains("WALL")) score += 10;
            if (ContainsToken(name, "WL")) score += 4;
            if (name.Contains("CENTER") || name.Contains("CENTRE") || name.Contains("CTR") || name.Contains("CTRE")) score += 2;
            if (name.Contains("LINE") || name.Contains("CL")) score += 1;

            if (name.Contains("GRID")) score -= 2;
            if (name.Contains("COLUMN") || name.Contains("PILE") || name.Contains("SLAB") || name.Contains("BEAM")) score -= 4;

            return score;
        }

