        }

        private static int ScoreBeamLayerName(string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName)) return 0;

            string name = layerName.ToUpperInvariant();
            int score = 0;

            if (name.Contains("BEAM")) score += 10;
            if (ContainsToken(name, "BM")) score += 5;
            if (name.Contains("GIRDER")) score += 4;
            if (name.Contains("FRAMING")) score += 2;

            if (name.Contains("GRID")) score -= 2;
            if (name.Contains("COLUMN") || name.Contains("PILE") || name.Contains("SLAB") || name.Contains("WALL")) score -= 4;

            return score;
        }

        private static bool ContainsToken(string name, string token)
        {
            if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(token)) return false;

            int idx = name.IndexOf(token, StringComparison.OrdinalIgnoreCase);
            if (idx < 0) return false;

            bool leftOk = idx == 0 || !char.IsLetter(name[idx - 1]);
            int rightIndex = idx + token.Length;
            bool rightOk = rightIndex >= name.Length || !char.IsLetter(name[rightIndex]);
            return leftOk && rightOk;
        }

        private int EstimateColumnCount(CadShapeHits hits, bool useCircles, bool useBlocks, bool useLines)
        {
            if (hits == null) return 0;

            var points = new List<XYZ>();
            if (useCircles) points.AddRange(hits.CircleCenters);
            if (useBlocks) points.AddRange(hits.BlockPoints);
            if (useLines)
            {
                if (hits.Lines.Count > 1)
                {
                    points.AddRange(FindLineIntersections(hits.Lines, GetTasCadLineSearchDistanceFt(0.0), GetTasParallelAngleEpsilonDeg()));
                }

                if (hits.Polylines.Count > 0)
                {
                    points.AddRange(hits.Polylines.Select(p => p.Center));
                }
            }

            if (points.Count == 0) return 0;

            double tolFt = GetTasRdpToleranceFt(1.0);
            points = DeduplicatePoints(points, tolFt);
            return points.Count;
        }

        private static void CollectLayersFromGeom(Document doc, GeometryObject go, HashSet<string> layers)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        CollectLayersFromGeom(doc, igo, layers);
                    }
                }
                return;
            }

            string layer = GetCadLayer(doc, go);
            if (!string.IsNullOrWhiteSpace(layer))
            {
                layers.Add(layer);
            }
        }

        private static List<XYZ> DeduplicatePoints(List<XYZ> points, double tolFt)
        {
            var result = new List<XYZ>();
            foreach (XYZ p in points)
            {
                bool exists = false;
                foreach (XYZ q in result)
                {
                    if (p.DistanceTo(q) <= tolFt)
                    {
                        exists = true;
                        break;
                    }
                }
                if (!exists) result.Add(p);
            }
            return result;
        }

        private static List<Line> DeduplicateLines(List<Line> lines, double tolFt)
        {
            var result = new List<Line>();
            foreach (Line line in lines)
            {
                if (line == null) continue;

                bool exists = false;
                foreach (Line existing in result)
                {
                    if (LinesMatch(line, existing, tolFt))
                    {
                        exists = true;
                        break;
                    }
                }

                if (!exists)
                {
                    result.Add(line);
                }
            }

            return result;
        }

        private static bool LinesMatch(Line a, Line b, double tolFt)
        {
            XYZ a0 = a.GetEndPoint(0);
            XYZ a1 = a.GetEndPoint(1);
            XYZ b0 = b.GetEndPoint(0);
            XYZ b1 = b.GetEndPoint(1);

            bool direct = a0.DistanceTo(b0) <= tolFt && a1.DistanceTo(b1) <= tolFt;
            if (direct) return true;

            bool reverse = a0.DistanceTo(b1) <= tolFt && a1.DistanceTo(b0) <= tolFt;
            return reverse;
        }

        private static Line FlattenLine(Line line)
        {
            if (line == null) return null;

            XYZ p0 = line.GetEndPoint(0);
            XYZ p1 = line.GetEndPoint(1);

            double z = (p0.Z + p1.Z) * 0.5;
            XYZ f0 = new XYZ(p0.X, p0.Y, z);
            XYZ f1 = new XYZ(p1.X, p1.Y, z);

            if (f0.DistanceTo(f1) < 1e-6) return null;

            return Line.CreateBound(f0, f1);
        }

        private static Line ProjectLineToZ(Line line, double z)
        {
            if (line == null) return null;

            XYZ p0 = line.GetEndPoint(0);
            XYZ p1 = line.GetEndPoint(1);

            XYZ f0 = new XYZ(p0.X, p0.Y, z);
            XYZ f1 = new XYZ(p1.X, p1.Y, z);

            if (f0.DistanceTo(f1) < 1e-6) return null;

            return Line.CreateBound(f0, f1);
        }

        private static bool IsPlanView(View view)
        {
            if (view == null) return false;
            XYZ dir = view.ViewDirection;
            return dir != null && (dir.IsAlmostEqualTo(XYZ.BasisZ) || dir.IsAlmostEqualTo(-XYZ.BasisZ));
        }

        private static Line FlattenLineToView(Line line, View view)
        {
            if (line == null || view == null) return null;

            double z = view.Origin.Z;
            XYZ p0 = line.GetEndPoint(0);
            XYZ p1 = line.GetEndPoint(1);

            XYZ f0 = new XYZ(p0.X, p0.Y, z);
            XYZ f1 = new XYZ(p1.X, p1.Y, z);

            if (f0.DistanceTo(f1) < 1e-6) return null;

            return Line.CreateBound(f0, f1);
        }

        private void CreateColumnSections(
            Document doc,
            List<FamilyInstance> columns,
            List<ColumnSectionSpec> specs,
            out int created,
            out int skipped)
        {
            created = 0;
            skipped = 0;

            if (columns == null || columns.Count == 0 || specs == null || specs.Count == 0)
            {
                return;
            }

            ViewFamilyType sectionType = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewFamilyType))
                .Cast<ViewFamilyType>()
                .FirstOrDefault(vft => vft.ViewFamily == ViewFamily.Section);

            if (sectionType == null)
            {
                _window?.ShowStatus("Section view type not found.");
                return;
            }

            ColumnSectionSpec defaultSpec = specs.Count == 1 ? specs[0] : null;
            var viewNames = new HashSet<string>(
                new FilteredElementCollector(doc)
                    .OfClass(typeof(View))
                    .Cast<View>()
                    .Select(v => v.Name),
                StringComparer.OrdinalIgnoreCase);

            foreach (FamilyInstance column in columns)
            {
                if (column == null)
                {
                    skipped++;
                    continue;
                }

                ColumnSectionSpec spec = MatchColumnSectionSpec(column, specs) ?? defaultSpec;
                if (spec == null || spec.WidthMm <= 0 || spec.LengthMm <= 0)
                {
                    skipped++;
                    continue;
                }

                if (!(column.Location is LocationPoint lp))
                {
                    skipped++;
                    continue;
                }

                BoundingBoxXYZ bb = column.get_BoundingBox(null);
                double heightFt = bb != null ? (bb.Max.Z - bb.Min.Z) : 0.0;
                if (heightFt <= 1e-6)
                {
                    heightFt = MmToFeet(3000.0);
                }

                double halfHeight = heightFt * 0.5;
                double widthFt = MmToFeet(spec.WidthMm);
                double lengthFt = MmToFeet(spec.LengthMm);
                double halfWidth = widthFt * 0.5;
                double halfLength = lengthFt * 0.5;

                XYZ origin = lp.Point;
                if (bb != null)
                {
                    origin = new XYZ(lp.Point.X, lp.Point.Y, (bb.Min.Z + bb.Max.Z) * 0.5);
                }

                double rotation = lp.Rotation;
                XYZ basisX = new XYZ(Math.Cos(rotation), Math.Sin(rotation), 0);
                XYZ basisY = XYZ.BasisZ;
                XYZ basisZ = new XYZ(-Math.Sin(rotation), Math.Cos(rotation), 0);

                Transform trf = Transform.Identity;
                trf.Origin = origin;
                trf.BasisX = basisX;
                trf.BasisY = basisY;
                trf.BasisZ = basisZ;

                BoundingBoxXYZ sectionBox = new BoundingBoxXYZ
                {
                    Transform = trf,
                    Min = new XYZ(-halfWidth, -halfHeight, -halfLength),
                    Max = new XYZ(halfWidth, halfHeight, halfLength)
                };

                try
                {
                    ViewSection section = ViewSection.CreateSection(doc, sectionType.Id, sectionBox);
                    if (section != null)
                    {
                        string baseName = $"C-SEC-{spec.Name}";
                        section.Name = MakeUniqueViewName(viewNames, baseName);
                        created++;
                    }
                    else
                    {
                        skipped++;
                    }
                }
                catch
                {
                    skipped++;
                }
            }
        }

        private static ColumnSectionSpec MatchColumnSectionSpec(FamilyInstance column, List<ColumnSectionSpec> specs)
        {
            if (column == null || specs == null || specs.Count == 0) return null;

            string mark = column.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString() ?? "";
            string typeName = column.Symbol?.Name ?? "";
            string familyName = column.Symbol?.FamilyName ?? "";

            foreach (ColumnSectionSpec spec in specs)
            {
                if (spec == null) continue;
                if (string.IsNullOrWhiteSpace(spec.Name)) continue;

                if (string.Equals(spec.Name, mark, StringComparison.OrdinalIgnoreCase)) return spec;
                if (string.Equals(spec.Name, typeName, StringComparison.OrdinalIgnoreCase)) return spec;
                if (string.Equals(spec.Name, familyName, StringComparison.OrdinalIgnoreCase)) return spec;
            }

            return null;
        }

        private static string MakeUniqueViewName(HashSet<string> existingNames, string baseName)
        {
            if (existingNames == null) return baseName;

            string name = baseName;
            int index = 1;
            while (existingNames.Contains(name))
            {
                name = $"{baseName}-{index:00}";
                index++;
            }

            existingNames.Add(name);
            return name;
        }

        private static List<CadTextLabel> CollectCadTextLabels(Document doc, ImportInstance cad, string layerFilter)
        {
            return CollectCadTextLabelsWithBaseTransform(
                doc,
                cad,
                layerFilter,
                GetCadGeometryRootTransform(cad));
        }

        private static List<CadTextLabel> CollectCadTextLabelsRaw(Document doc, ImportInstance cad, string layerFilter)
        {
            return CollectCadTextLabelsWithBaseTransform(doc, cad, layerFilter, Transform.Identity);
        }

        private static List<CadTextLabel> CollectCadTextLabelsWithBaseTransform(
            Document doc,
            ImportInstance cad,
            string layerFilter,
            Transform baseTransform)
        {
            var labels = new List<CadTextLabel>();
            if (cad == null)
            {
                return labels;
            }

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return labels;

            Transform importTrf = baseTransform ?? Transform.Identity;
            foreach (GeometryObject go in ge)
            {
                CollectCadTextFromGeom(doc, go, importTrf, layerFilter, labels);
            }

            return labels;
        }

        private static List<CadTextLabel> CollectCadTextLabelsFromSelectedObjects(
            Document doc,
            ImportInstance cad,
            IList<Reference> refs,
            string layerFilter)
        {
            var labels = new List<CadTextLabel>();
            if (doc == null || cad == null || refs == null || refs.Count == 0) return labels;

            Transform importTrf = GetCadGeometryRootTransform(cad);
            foreach (Reference r in refs)
            {
                if (r == null || r.ElementId != cad.Id) continue;
                GeometryObject go = cad.GetGeometryObjectFromReference(r);
                if (go == null) continue;
                CollectCadTextFromGeom(doc, go, importTrf, layerFilter, labels);
            }

            return labels;
        }

        private static List<CadTextLabel> CollectCadTextLabelsByColor(
            Document doc,
            ImportInstance cad,
            string colorKey)
        {
            var labels = new List<CadTextLabel>();
            if (doc == null || cad == null || string.IsNullOrWhiteSpace(colorKey)) return labels;

            Options opt = new Options
            {
                ComputeReferences = false,
                DetailLevel = ViewDetailLevel.Fine,
                IncludeNonVisibleObjects = true
            };

            GeometryElement ge = cad.get_Geometry(opt);
            if (ge == null) return labels;

            Transform importTrf = GetCadGeometryRootTransform(cad);
            foreach (GeometryObject go in ge)
            {
                CollectCadTextFromGeomByColor(doc, go, importTrf, colorKey, labels);
            }

            return labels;
        }

        private static void CollectCadTextFromGeom(
            Document doc,
            GeometryObject go,
            Transform trf,
            string layerFilter,
            List<CadTextLabel> labels)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        CollectCadTextFromGeom(doc, igo, instTrf, layerFilter, labels);
                    }
                }
                return;
            }

            if (TryGetCadText(go, out string text, out XYZ pos))
            {
                if (!string.IsNullOrWhiteSpace(layerFilter))
                {
                    string layer = GetCadLayer(doc, go);
                    if (!string.Equals(layerFilter, layer, StringComparison.OrdinalIgnoreCase))
                    {
                        return;
                    }
                }

                XYZ world = trf.OfPoint(pos);
                labels.Add(new CadTextLabel(text.Trim(), world));
            }
        }

        private static void CollectCadTextFromGeomByColor(
            Document doc,
            GeometryObject go,
            Transform trf,
            string colorKey,
            List<CadTextLabel> labels)
        {
            if (go == null) return;

            GeometryInstance gi = go as GeometryInstance;
            if (gi != null)
            {
                Transform instTrf = trf.Multiply(gi.Transform);
                GeometryElement instGeom = GetCadSymbolGeometry(gi);
                if (instGeom != null)
                {
                    foreach (GeometryObject igo in instGeom)
                    {
                        CollectCadTextFromGeomByColor(doc, igo, instTrf, colorKey, labels);
                    }
                }
                return;
            }

            if (TryGetCadText(go, out string text, out XYZ pos))
            {
                if (!string.Equals(colorKey, GetCadColorKey(doc, go), StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                XYZ world = trf.OfPoint(pos);
                labels.Add(new CadTextLabel(text.Trim(), world));
            }
        }

        private static bool TryGetCadText(GeometryObject go, out string text, out XYZ position)
        {
            text = null;
            position = XYZ.Zero;

            if (go == null) return false;

            Type type = go.GetType();
            string typeName = type.Name;
            if (!string.Equals(typeName, "Text", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(typeName, "TextElement", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(typeName, "TextNote", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            PropertyInfo textProp = type.GetProperty("Text") ??
                                    type.GetProperty("Value") ??
                                    type.GetProperty("TextString");
            if (textProp != null)
            {
                text = textProp.GetValue(go, null) as string;
            }

            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            PropertyInfo posProp = type.GetProperty("Position") ??
                                   type.GetProperty("Coord") ??
                                   type.GetProperty("Origin");
            object posVal = posProp?.GetValue(go, null);
            if (posVal is XYZ xyz)
            {
                position = xyz;
                return true;
            }

            PropertyInfo bbProp = type.GetProperty("BoundingBox");
            object bbVal = bbProp?.GetValue(go, null);
            if (bbVal is BoundingBoxXYZ bb)
            {
                position = (bb.Min + bb.Max) * 0.5;
                return true;
            }

            return false;
        }

        private static bool IsLikelyGridLabel(string text)
        {
            if (string.IsNullOrWhiteSpace(text)) return false;

            string trimmed = text.Trim();
            if (trimmed.Length > 8) return false;

            foreach (char c in trimmed)
            {
                if (!char.IsLetterOrDigit(c) && c != '-')
                {
                    return false;
                }
            }

            return true;
        }

        private static string TryMatchLabel(Line line, List<CadTextLabel> labels, double maxDistFt, HashSet<string> usedNames)
        {
            if (labels == null || labels.Count == 0) return null;

            int bestIndex = -1;
            double bestDist = double.MaxValue;

            for (int i = 0; i < labels.Count; i++)
            {
                CadTextLabel label = labels[i];
                if (label == null || string.IsNullOrWhiteSpace(label.Text)) continue;

                double dist = DistancePointToLine2D(label.Position, line);
                if (dist <= maxDistFt && dist < bestDist)
                {
                    string name = label.Text.Trim();
                    if (!usedNames.Contains(name))
                    {
                        bestDist = dist;
                        bestIndex = i;
                    }
                }
            }

            if (bestIndex >= 0)
            {
                string result = labels[bestIndex].Text.Trim();
                labels.RemoveAt(bestIndex);
                return result;
            }

            return null;
        }

        private static double DistancePointToLine2D(XYZ point, Line line)
        {
            XYZ a = line.GetEndPoint(0);
            XYZ b = line.GetEndPoint(1);

            double ax = a.X;
            double ay = a.Y;
            double bx = b.X;
            double by = b.Y;
            double px = point.X;
            double py = point.Y;

            double dx = bx - ax;
            double dy = by - ay;
            double len2 = dx * dx + dy * dy;
            if (len2 < 1e-9) return double.MaxValue;

            double t = ((px - ax) * dx + (py - ay) * dy) / len2;
            t = Math.Max(0.0, Math.Min(1.0, t));

            double cx = ax + t * dx;
            double cy = ay + t * dy;
            double ddx = px - cx;
            double ddy = py - cy;

            return Math.Sqrt(ddx * ddx + ddy * ddy);
        }

        private static List<Line> MergeColinearLines(List<Line> lines, double tolFt)
        {
            const double angleTolRad = 1.0 * Math.PI / 180.0;
            var groups = new Dictionary<Tuple<int, long>, LineMergeBucket>();

            foreach (Line line in lines)
            {
                if (line == null) continue;

                if (!TryGetDirection2D(line, out XYZ dir))
                {
                    continue;
                }

                dir = Canonicalize(dir);
                XYZ perp = new XYZ(-dir.Y, dir.X, 0);
                XYZ p0 = line.GetEndPoint(0);
                XYZ p1 = line.GetEndPoint(1);

                double dist = perp.DotProduct(p0);
                double angle = Math.Atan2(dir.Y, dir.X);
                int angleKey = (int)Math.Round(angle / angleTolRad);
                long distKey = (long)Math.Round(dist / tolFt);

                var key = Tuple.Create(angleKey, distKey);
                if (!groups.TryGetValue(key, out LineMergeBucket bucket))
                {
                    bucket = new LineMergeBucket(dir, perp);
                    groups.Add(key, bucket);
                }

                double t0 = dir.DotProduct(p0);
                double t1 = dir.DotProduct(p1);
                bucket.Add(dist, t0, t1);
            }

            var merged = new List<Line>();
            foreach (LineMergeBucket bucket in groups.Values)
            {
                Line line = bucket.ToLine();
                if (line != null)
                {
                    merged.Add(line);
                }
            }

            return merged;
        }

        private static bool TryGetDirection2D(Line line, out XYZ dir)
        {
            XYZ v = line.Direction;
            v = new XYZ(v.X, v.Y, 0);
            double len = v.GetLength();
            if (len < 1e-9)
            {
                dir = XYZ.BasisX;
                return false;
            }

            dir = v.Normalize();
            return true;
        }

        private static XYZ Canonicalize(XYZ dir)
        {
            if (dir.X < 0 || (Math.Abs(dir.X) < 1e-9 && dir.Y < 0))
            {
                return new XYZ(-dir.X, -dir.Y, 0);
            }

            return dir;
        }

        private class LineMergeBucket
        {
            private readonly XYZ _dir;
            private readonly XYZ _perp;
            private double _minT = double.PositiveInfinity;
            private double _maxT = double.NegativeInfinity;
            private double _distSum;
            private int _count;

            public LineMergeBucket(XYZ dir, XYZ perp)
            {
                _dir = dir;
                _perp = perp;
            }

            public void Add(double dist, double t0, double t1)
            {
                double min = Math.Min(t0, t1);
                double max = Math.Max(t0, t1);

                if (min < _minT) _minT = min;
                if (max > _maxT) _maxT = max;

                _distSum += dist;
                _count++;
            }

            public Line ToLine()
            {
                if (_count == 0 || _maxT <= _minT)
                {
                    return null;
                }

                double dist = _distSum / _count;
                XYZ p0 = _dir.Multiply(_minT).Add(_perp.Multiply(dist));
                XYZ p1 = _dir.Multiply(_maxT).Add(_perp.Multiply(dist));

                if (p0.DistanceTo(p1) < 1e-6)
                {
                    return null;
                }

                return Line.CreateBound(p0, p1);
            }
        }

        private class CadTextLabel
        {
            public string Text { get; }
            public XYZ Position { get; }

            public CadTextLabel(string text, XYZ position)
            {
                Text = text;
                Position = position;
            }
        }

        private static double MmToFeet(double mm)
        {
            return mm / 304.8;
        }

        private static double FeetToMm(double feet)
        {
            return feet * 304.8;
        }

        private double GetTasRdpToleranceFt(double fallbackMm)
        {
            return MmToFeet(GetPositiveTasMm(Request?.TasRdpEpsilonMm ?? 0.0, fallbackMm, 0.1, 100.0));
        }

        private double GetTasCadLineSearchDistanceFt(double fallbackMm)
        {
            return MmToFeet(GetPositiveTasMm(Request?.TasCadLineSearchMaxDistanceMm ?? 0.0, fallbackMm, 0.0, 5000.0));
        }

        private double GetTasShortLineMinLengthFt(double fallbackMm)
        {
            return MmToFeet(GetPositiveTasMm(Request?.TasShortLineMinLengthMm ?? 0.0, fallbackMm, 0.0, 5000.0));
        }

        private double GetTasParallelAngleEpsilonDeg()
        {
            double value = Request?.TasCadLineParallelAngleEpsilonDeg ?? 5.0;
            if (double.IsNaN(value) || double.IsInfinity(value) || value <= 0)
            {
                return 5.0;
            }

            return Math.Max(0.1, Math.Min(45.0, value));
        }

        private static double GetPositiveTasMm(double valueMm, double fallbackMm, double minMm, double maxMm)
        {
            double safeFallback = double.IsNaN(fallbackMm) || double.IsInfinity(fallbackMm)
                ? 0.0
                : fallbackMm;

            double value = double.IsNaN(valueMm) || double.IsInfinity(valueMm) || valueMm < minMm
                ? safeFallback
                : valueMm;

            return Math.Max(minMm, Math.Min(maxMm, value));
        }

        private void RunAutoJoin(Document doc, AutoJoinAction action)
        {
            if (Request.AutoJoinCategories == null || Request.AutoJoinCategories.Count == 0)
            {
                _window?.ShowStatus("Select at least one category for AutoJoin.");
                return;
            }

            IList<Element> elements = CollectElements(doc, Request.AutoJoinCategories, Request.AutoJoinUseActiveView);
            if (elements.Count == 0)
            {
                _window?.ShowStatus("No elements found for AutoJoin.");
                return;
            }

            int processed = 0;
            int changed = 0;
            Dictionary<BuiltInCategory, int> priorityByCategory = new Dictionary<BuiltInCategory, int>();
            for (int i = 0; i < Request.AutoJoinCategories.Count; i++)
            {
                BuiltInCategory bic = Request.AutoJoinCategories[i];
                if (!priorityByCategory.ContainsKey(bic))
                {
                    priorityByCategory[bic] = i;
                }
            }

            using (Transaction t = new Transaction(doc, $"CamboBIM - AutoJoin ({action})"))
            {
                t.Start();

                Dictionary<ElementId, Element> elementMap = elements.ToDictionary(e => e.Id, e => e);

                foreach (Element e in elements)
                {
                    BoundingBoxXYZ bbox = e.get_BoundingBox(null);
                    if (bbox == null) continue;

                    Outline outline = new Outline(bbox.Min, bbox.Max);
                    BoundingBoxIntersectsFilter bbFilter = new BoundingBoxIntersectsFilter(outline);

                    ElementMulticategoryFilter catFilter = new ElementMulticategoryFilter(Request.AutoJoinCategories);
                    FilteredElementCollector collector = CreateScopedElementCollector(doc, Request.AutoJoinUseActiveView)
                        .WherePasses(catFilter)
                        .WherePasses(bbFilter)
                        .WhereElementIsNotElementType();

                    foreach (Element other in collector)
                    {
                        if (other == null || other.Id == e.Id) continue;
                        if (other.Id.Value <= e.Id.Value) continue;

                        processed++;
                        bool joined = JoinGeometryUtils.AreElementsJoined(doc, e, other);

                        try
                        {
                            if (action == AutoJoinAction.Join)
                            {
                                if (!joined)
                                {
                                    JoinGeometryUtils.JoinGeometry(doc, e, other);
                                    joined = true;
                                    changed++;
                                }

                                if (joined &&
                                    TryGetPreferredAutoJoinCuttingElement(doc, e, other, priorityByCategory, out bool firstElementShouldCut))
                                {
                                    bool firstCutsNow = JoinGeometryUtils.IsCuttingElementInJoin(doc, e, other);
                                    if (firstCutsNow != firstElementShouldCut)
                                    {
                                        JoinGeometryUtils.SwitchJoinOrder(doc, e, other);
                                        changed++;
                                    }
                                }
                            }
                            else if (action == AutoJoinAction.Switch)
                            {
                                if (joined)
                                {
                                    JoinGeometryUtils.SwitchJoinOrder(doc, e, other);
                                    changed++;
                                }
                            }
                            else if (action == AutoJoinAction.Unjoin)
                            {
                                if (joined)
                                {
                                    JoinGeometryUtils.UnjoinGeometry(doc, e, other);
                                    changed++;
                                }
                            }
                        }
                        catch
                        {
                            // Ignore invalid joins
                        }
                    }
                }

                t.Commit();
            }

            _window?.ShowStatus($"AutoJoin {action}: processed {processed} pairs, changed {changed}.");
        }

        private static bool TryGetPreferredAutoJoinCuttingElement(
            Document doc,
            Element first,
            Element second,
            IDictionary<BuiltInCategory, int> priorityByCategory,
            out bool firstElementShouldCut)
        {
            firstElementShouldCut = false;
            if (first == null || second == null || priorityByCategory == null || priorityByCategory.Count == 0)
            {
                return false;
            }

            if (!TryGetAutoJoinBuiltInCategory(first, out BuiltInCategory firstCategory) ||
                !TryGetAutoJoinBuiltInCategory(second, out BuiltInCategory secondCategory))
            {
                return false;
            }

            if (!priorityByCategory.TryGetValue(firstCategory, out int firstPriority) ||
                !priorityByCategory.TryGetValue(secondCategory, out int secondPriority))
            {
                return false;
            }

            if (firstPriority == secondPriority)
            {
                return false;
            }

            // Earlier categories in the UI list have higher join priority.
            firstElementShouldCut = firstPriority < secondPriority;
            return true;
        }

        private static bool TryGetAutoJoinBuiltInCategory(Element element, out BuiltInCategory category)
        {
            category = default(BuiltInCategory);
            if (element?.Category?.Id == null)
            {
                return false;
            }

            ElementId categoryId = element.Category.Id;
            if (categoryId == ElementId.InvalidElementId)
            {
                return false;
            }

            int rawValue = unchecked((int)categoryId.Value);
            category = (BuiltInCategory)rawValue;
            return true;
        }

        private static IList<Element> CollectElements(Document doc, IList<BuiltInCategory> categories, bool activeView)
        {
            ElementMulticategoryFilter catFilter = new ElementMulticategoryFilter(categories);

            FilteredElementCollector collector = CreateScopedElementCollector(doc, activeView);

            return collector
                .WherePasses(catFilter)
                .WhereElementIsNotElementType()
                .ToElements();
        }

        private static FilteredElementCollector CreateScopedElementCollector(Document doc, bool activeView)
        {
            return activeView && doc.ActiveView != null
                ? new FilteredElementCollector(doc, doc.ActiveView.Id)
                : new FilteredElementCollector(doc);
        }

