        private class CadShapeHits
        {
            public List<XYZ> CircleCenters { get; } = new List<XYZ>();
            public List<CadBlockHit> Blocks { get; } = new List<CadBlockHit>();
            public List<XYZ> BlockPoints { get; } = new List<XYZ>();
            public List<Line> Lines { get; } = new List<Line>();
            public List<CadPolylineHit> Polylines { get; } = new List<CadPolylineHit>();

            public bool IsEmpty => CircleCenters.Count == 0 &&
                                   BlockPoints.Count == 0 &&
                                   Lines.Count == 0 &&
                                   Polylines.Count == 0;
        }

        private class CadBlockHit
        {
            public XYZ Point { get; }
            public string Name { get; }

            public CadBlockHit(XYZ point, string name)
            {
                Point = point;
                Name = name ?? "";
            }
        }

        private class CadPolylineHit
        {
            public XYZ Center { get; }
            public double WidthMm { get; }
            public double LengthMm { get; }

            public CadPolylineHit(XYZ center, double widthMm, double lengthMm)
            {
                Center = center;
                WidthMm = widthMm;
                LengthMm = lengthMm;
            }
        }

        private enum AutoJoinAction
        {
            Join,
            Switch,
            Unjoin
        }
